# opensourcefpa-engine/app.R — Statements, variance, scenarios, drivers.
# Launch: Rscript app.R "C:/path/fpa-config.json"
# Or, once the engine is loaded: fpa_app("C:/path/fpa-config.json")
# Actuals are read from work/. A scenario is computed in the session.

app_root <- local({
  args <- commandArgs(trailingOnly = FALSE)
  hit <- grep("^--file=", args, value = TRUE)
  if (length(hit)) {
    return(normalizePath(dirname(sub("^--file=", "", hit[[1]])), winslash = "/"))
  }
  normalizePath(getwd(), winslash = "/")
})
if (dir.exists(file.path(app_root, "R"))) {
  source(file.path(app_root, "R", "fpa-paths.R"), encoding = "UTF-8")
  source(file.path(app_root, "R", "fpa-config.R"), encoding = "UTF-8")
  fpa_source_all(app_root)
} else {
  moteur <- file.path(app_root, "fpa-engine.R")
  if (!file.exists(moteur)) moteur <- file.path(app_root, "fpa-moteur.R")
  if (!file.exists(moteur)) {
    stop(
      "Placez fpa-engine.R dans le meme dossier que app.R, a cote de fpa-config.json.",
      call. = FALSE
    )
  }
  options(fpa.skip_main = TRUE)
  sys.source(moteur, envir = .GlobalEnv)
}

if (!requireNamespace("shiny", quietly = TRUE) || !requireNamespace("bslib", quietly = TRUE)) {
  stop(
    fpa_screen("loc_pkg_drivers"),
    fpa_screen("loc_pkg_install"),
    call. = FALSE
  )
}
library(shiny)
library(bslib)
FPA_HAS_PLOTLY <- requireNamespace("plotly", quietly = TRUE)
if (FPA_HAS_PLOTLY) {
  # Soft: base plots remain if plotly is absent.
  # Do not rely on %>% inside renderPlotly (search path is masked).
}

fpa_shiny_script_pick <- function(home, names) {
  for (nm in names) {
    path <- file.path(home, nm)
    if (!file.exists(path)) next
    line <- tryCatch(readLines(path, n = 1L, warn = FALSE, encoding = "UTF-8"), error = function(e) "")
    hit <- regmatches(line, regexec("v[0-9]+\\.[0-9]+\\.[0-9]+", line))[[1]]
    return(list(file = nm, ver = if (length(hit)) hit[[1]] else ""))
  }
  list(file = names[[1]], ver = "")
}

fpa_shiny_ver_newer <- function(server, local) {
  s <- sub("^v", "", as.character(server %||% ""))
  l <- sub("^v", "", as.character(local %||% ""))
  if (!nzchar(s)) return(FALSE)
  if (!nzchar(l)) return(TRUE)
  out <- tryCatch(numeric_version(s) > numeric_version(l), error = function(e) FALSE)
  isTRUE(out)
}

#' One line per script, local against server. `stale` names the files to replace.
fpa_shiny_script_rows <- function(home, server) {
  rows <- list(
    list(pick = fpa_shiny_script_pick(home, c("fpa-engine.R", "fpa-moteur.R")),
         want = if (is.null(server)) "" else server$engine,
         file = if (is.null(server)) "fpa-engine.R" else server$engine_file),
    list(pick = fpa_shiny_script_pick(home, "app.R"),
         want = if (is.null(server)) "" else server$screen,
         file = if (is.null(server)) "app.R" else server$screen_file)
  )
  lines <- list()
  stale <- character(0)
  add <- function(r, state, gap, text) {
    lines[[length(lines) + 1L]] <<- list(
      state = state, gap = gap, text = text,
      file = r$file, local_file = r$pick$file, have = r$pick$ver, want = r$want
    )
  }
  for (r in rows) {
    have <- r$pick$ver
    if (is.null(server) || !nzchar(r$want)) {
      add(r, "unchecked", FALSE, if (nzchar(have)) {
        if (is.null(server)) fpa_screen("params_script_unchecked", r$pick$file, have) else paste(r$pick$file, have)
      } else "")
      next
    }
    if (!nzchar(have)) {
      add(r, "missing", TRUE, fpa_screen("params_script_missing", r$file, r$want))
      stale <- c(stale, r$file)
    } else if (identical(sub("^v", "", have), sub("^v", "", r$want)) && identical(r$pick$file, r$file)) {
      add(r, "ok", FALSE, fpa_screen("params_script_same", r$file, have))
    } else {
      behind <- fpa_shiny_ver_newer(r$want, have) || !identical(r$pick$file, r$file)
      add(r, if (behind) "old" else "ahead", TRUE, fpa_screen("params_script_gap", r$pick$file, have, r$want))
      if (behind) stale <- c(stale, r$file)
    }
  }
  list(rows = lines, lines = Filter(function(x) nzchar(x$text), lines), stale = stale)
}

