fpa_shiny_delta_body <- function(rec) {
  if (is.null(rec)) return("")
  part <- function(key, items) {
    items <- as.character(unlist(items %||% character(0)))
    if (!length(items)) return("")
    fpa_screen(key, length(items), paste(items, collapse = ", "))
  }
  bits <- c(
    part("params_delta_files_add", rec$files_added),
    part("params_delta_files_drop", rec$files_removed),
    part("params_delta_drv_add", rec$drivers_added),
    part("params_delta_drv_drop", rec$drivers_removed)
  )
  bits <- bits[nzchar(bits)]
  if (length(bits)) paste(bits, collapse = " \u00b7 ") else fpa_screen("params_delta_other")
}

fpa_shiny_delta_line <- function(rec) {
  if (is.null(rec) || is.null(rec$revision)) return("")
  fpa_screen("params_delta_head", rec$revision, as.character(rec$at %||% ""), fpa_shiny_delta_body(rec))
}

fpa_shiny_stamp <- function(raw) {
  raw <- as.character(raw %||% "")
  if (!nzchar(raw)) return("")
  parsed <- suppressWarnings(as.POSIXct(raw, format = "%Y-%m-%dT%H:%M:%OS", tz = "UTC"))
  if (is.na(parsed)) return(raw)
  format(parsed, "%Y-%m-%d %H:%M", tz = Sys.timezone())
}

#' "aujourd'hui à 15:02", "hier à 09:10", "il y a 4 jours (2026-09-25)". Empty when never.
fpa_shiny_ago <- function(at, now = Sys.time()) {
  at <- as.character(at %||% "")
  if (!nzchar(at)) return("")
  t <- suppressWarnings(as.POSIXct(at, format = "%Y-%m-%d %H:%M", tz = Sys.timezone()))
  if (is.na(t)) return(at)
  days <- as.integer(as.Date(format(now, "%Y-%m-%d")) - as.Date(format(t, "%Y-%m-%d")))
  hm <- format(t, "%H:%M")
  if (days <= 0L) return(fpa_screen("pm_ago_today", hm))
  if (days == 1L) return(fpa_screen("pm_ago_yesterday", hm))
  fpa_screen("pm_ago_days", days, format(t, "%Y-%m-%d"))
}

fpa_shiny_project_link <- function(config) {
  p <- config$project
  if (is.null(p) || !is.list(p)) return("")
  id <- as.character(p$id %||% "")
  key <- as.character(p$key %||% "")
  site <- sub("/+$", "", as.character(p$site %||% ""))
  if (!nzchar(id) || !nzchar(key) || !grepl("^https?://", site)) return("")
  paste0(
    site, "/open?project=", utils::URLencode(id, reserved = TRUE),
    "&key=", utils::URLencode(key, reserved = TRUE)
  )
}

fpa_shiny_find_config <- function() {
  cli <- commandArgs(trailingOnly = TRUE)
  cli <- cli[nzchar(cli)]
  script_dir <- ""
  file_arg <- grep("^--file=", commandArgs(trailingOnly = FALSE), value = TRUE)
  if (length(file_arg)) {
    script_dir <- dirname(sub("^--file=", "", file_arg[[1]]))
  }
  candidates <- c(
    if (length(cli)) cli[[1]] else "",
    Sys.getenv("FPA_CONFIG", unset = ""),
    if (nzchar(script_dir)) file.path(script_dir, "fpa-config.json") else "",
    file.path(getwd(), "fpa-config.json"),
    file.path(getwd(), "..", "fpa-config.json"),
    file.path(getwd(), "config", "fpa-config.json")
  )
  candidates <- candidates[nzchar(candidates) & file.exists(candidates)]
  if (!length(candidates)) return("")
  normalizePath(candidates[[1]], winslash = "/", mustWork = FALSE)
}

#' Working folder shown in the banner (hint, else folder of the JSON).
fpa_shiny_work_root <- function(pack) {
  if (is.null(pack) || !isTRUE(pack$ok)) return("")
  hint <- as.character((pack$config$paths %||% list())$working_root_hint %||% "")
  if (nzchar(hint)) {
    return(normalizePath(hint, winslash = "/", mustWork = FALSE))
  }
  cfg <- as.character(pack$config_path %||% "")
  if (!nzchar(cfg)) return("")
  normalizePath(dirname(cfg), winslash = "/", mustWork = FALSE)
}

#' Source file basenames newer than the last written monthly P&L.
fpa_shiny_newer_sources <- function(config, paths) {
  if (is.null(config) || is.null(paths)) return(character(0))
  work_pnl <- file.path(paths$work, "pnl-monthly.csv")
  if (!nzchar(work_pnl) || !file.exists(work_pnl)) return(character(0))
  stamp <- file.info(work_pnl)$mtime
  if (is.na(stamp)) return(character(0))
  newer <- character(0)
  seen <- character(0)
  consider <- function(fp) {
    fp <- as.character(fp %||% "")
    if (length(fp) != 1L || !nzchar(fp) || fp %in% seen || !file.exists(fp)) return(invisible(NULL))
    seen <<- c(seen, fp)
    mt <- file.info(fp)$mtime
    if (!is.na(mt) && mt > stamp + 1) newer <<- c(newer, basename(fp))
  }
  for (fp in fpa_config_source_paths(config)) consider(fp)
  for (s in config$sources %||% list()) {
    consider(tryCatch(fpa_chain_source_path(config, s), error = function(e) ""))
  }
  grades_path <- file.path(paths$work, "drivers", "driver-grades.csv")
  if (file.exists(grades_path)) {
    head_cols <- tryCatch(names(utils::read.csv(grades_path, nrows = 1L)), error = function(e) character(0))
    if (length(head_cols) && !"line_n" %in% head_cols) newer <- c(newer, basename(grades_path))
  }
  unique(newer)
}

fpa_shiny_fr_stamp <- function(t) {
  t <- suppressWarnings(as.POSIXct(t))
  if (length(t) != 1L || is.na(t)) return("")
  paste(fpa_header_fr_date(as.Date(t)), format(t, "%H:%M"))
}

fpa_shiny_sync_stamp_path <- function(paths) {
  work <- as.character(paths$work %||% "")
  if (!nzchar(work)) return("")
  file.path(work, "sync-local.json")
}

fpa_shiny_sync_stamp_write <- function(paths) {
  dest <- fpa_shiny_sync_stamp_path(paths)
  if (!nzchar(dest)) return(invisible(NULL))
  dir.create(dirname(dest), showWarnings = FALSE, recursive = TRUE)
  jsonlite::write_json(
    list(synced_at = format(Sys.time(), "%Y-%m-%dT%H:%M:%S")),
    dest, auto_unbox = TRUE
  )
}

fpa_shiny_sync_stamp_read <- function(paths) {
  dest <- fpa_shiny_sync_stamp_path(paths)
  if (!nzchar(dest) || !file.exists(dest)) return(as.POSIXct(NA))
  got <- tryCatch(jsonlite::fromJSON(dest), error = function(e) NULL)
  if (is.null(got)) return(as.POSIXct(NA))
  suppressWarnings(as.POSIXct(as.character(got$synced_at %||% ""), format = "%Y-%m-%dT%H:%M:%S"))
}

#' Reload work outputs. Pull published settings first, then re-run if needed.
#' `force` rereads the source files even when none is newer than the last calculation.
fpa_shiny_sync <- function(config_path, pull = NULL, force = FALSE) {
  if (exists("fpa_assumptions_reconcile_path", mode = "function")) {
    tryCatch(fpa_assumptions_reconcile_path(config_path), error = function(e) NULL)
  }
  pulled <- pull
  if (is.null(pulled) && exists("fpa_sync_pull", mode = "function")) {
    pulled <- tryCatch(
      fpa_sync_pull(home = dirname(config_path), config_path = config_path),
      error = function(e) list(status = "offline", changed = FALSE, message = fpa_screen("sync_pull_offline"), revision = 0L)
    )
  }
  loaded <- fpa_shiny_load(config_path)
  if (!isTRUE(loaded$ok)) {
    return(list(pack = loaded, status = "bad", newer = character(0), changed = list(), pull = pulled))
  }
  snapshot <- function(x, stale = character()) {
    fin <- x$finance
    status <- fin$period_status
    focus <- fpa_anomaly_focus_periods(status)
    scan <- tryCatch({
      hist <- fpa_line_history(x$config, x$paths)
      vol <- fpa_shiny_volumes(x$config, x$paths)
      map <- fpa_line_map(x$config, "pnl")
      fpa_anomaly_scan(fin$bs, fin$pnl, fin$cash, vol, hist, map, focus)
    }, error = function(e) NULL)
    fpa_snapshot_build(
      fin$pnl, fin$cash, status, fpa_anomaly_counts(scan), stale,
      cash_floor = fpa_cash_floor_read(x$config), config = x$config
    )
  }
  disk_before <- fpa_snapshot_read(loaded$paths)
  before <- if (!is.null(disk_before)) disk_before else snapshot(loaded)
  newer <- fpa_shiny_newer_sources(loaded$config, loaded$paths)
  if (isTRUE(pulled$changed)) newer <- unique(c(newer, "fpa-config.json"))
  if (!length(newer) && !isTRUE(force)) {
    after <- snapshot(loaded)
    changed <- if (is.null(disk_before)) list() else fpa_snapshot_diff(before, after)
    fpa_snapshot_write(loaded$paths, after)
    return(list(pack = loaded, status = "fresh", newer = character(0), changed = changed, first = is.null(disk_before), pull = pulled))
  }
  run_err <- NULL
  res <- tryCatch(
    fpa_run(config_path, write = TRUE, stop_on_error = FALSE),
    error = function(e) {
      run_err <<- conditionMessage(e)
      NULL
    }
  )
  if (!is.null(run_err)) {
    return(list(pack = fpa_shiny_load(config_path), status = "run_fail", newer = newer, detail = run_err, changed = list(), pull = pulled))
  }
  if (exists("fpa_sync_report_run", mode = "function")) {
    tryCatch(fpa_sync_report_run(dirname(config_path), config_path, res), error = function(e) NULL)
  }
  drv_err <- NULL
  tryCatch(
    fpa_driver_pass(config_path, res = res, write = TRUE),
    error = function(e) {
      drv_err <<- conditionMessage(e)
      NULL
    }
  )
  out <- fpa_shiny_load(config_path)
  if (!is.null(drv_err)) {
    return(list(pack = out, status = "drv_fail", newer = newer, detail = drv_err, changed = list(), pull = pulled))
  }
  after <- snapshot(out, fpa_shiny_newer_sources(out$config, out$paths))
  changed <- if (is.null(disk_before)) list() else fpa_snapshot_diff(before, after)
  fpa_snapshot_write(out$paths, after)
  list(pack = out, status = "rebuilt", newer = newer, changed = changed, first = is.null(disk_before), pull = pulled)
}

fpa_shiny_csv <- function(path) {
  if (!nzchar(path) || !file.exists(path)) return(data.frame())
  utils::read.csv(path, stringsAsFactors = FALSE, fileEncoding = "UTF-8")
}

fpa_shiny_finance <- function(paths) {
  list(
    pnl = fpa_shiny_csv(file.path(paths$work, "pnl-monthly.csv")),
    pnl_long = fpa_shiny_csv(file.path(paths$work, "pnl-monthly-long.csv")),
    cash = fpa_shiny_csv(file.path(paths$work, "cash-bridge-monthly.csv")),
    bs = fpa_shiny_csv(file.path(paths$work, "bs-monthly.csv")),
    budget = fpa_shiny_csv(file.path(paths$work, "budget-monthly.csv")),
    variance = fpa_shiny_csv(file.path(paths$work, "variance-monthly.csv")),
    scenarios = fpa_shiny_csv(file.path(paths$work, "scenarios-monthly.csv")),
    scenario_ranks = fpa_shiny_csv(file.path(paths$work, "scenario-ranks.csv")),
    line_drivers = fpa_shiny_csv(file.path(paths$work, "line-drivers.csv")),
    sensitivity = fpa_shiny_csv(file.path(paths$work, "sensitivity.csv")),
    driver_impact = fpa_shiny_csv(file.path(paths$work, "driver-impact.csv")),
    period_status = fpa_shiny_csv(file.path(paths$work, "period-status.csv"))
  )
}

#' Finance tables from an engine result already in memory. Sensitivity stays from the loaded book.
fpa_shiny_finance_from_run <- function(result, prev = list()) {
  take <- function(obj, fallback) {
    if (is.data.frame(obj) && nrow(obj)) return(obj)
    if (is.data.frame(fallback)) return(fallback)
    data.frame()
  }
  list(
    pnl = take(result$pnl, prev$pnl),
    pnl_long = take(result$pnl_long, prev$pnl_long),
    cash = take(result$cash, prev$cash),
    bs = take(result$bs, prev$bs),
    budget = take(result$budget_monthly, prev$budget),
    variance = take(result$variance, prev$variance),
    scenarios = take(result$scenarios, prev$scenarios),
    scenario_ranks = take(result$scenario_ranks, prev$scenario_ranks),
    line_drivers = take(result$line_drivers, prev$line_drivers),
    sensitivity = if (is.data.frame(prev$sensitivity)) prev$sensitivity else data.frame(),
    driver_impact = if (is.data.frame(prev$driver_impact)) prev$driver_impact else data.frame(),
    period_status = take(result$period_status, prev$period_status)
  )
}

fpa_shiny_vintages <- function(paths) {
  root <- file.path(paths$work, "vintages")
  if (!dir.exists(root)) return(data.frame())
  rows <- list()
  for (id in list.dirs(root, full.names = FALSE, recursive = FALSE)) {
    man <- file.path(root, id, "manifest.json")
    if (!file.exists(man)) next
    m <- tryCatch(jsonlite::read_json(man), error = function(e) NULL)
    if (is.null(m)) next
    rows[[length(rows) + 1L]] <- data.frame(
      id = id,
      label = as.character(m$label %||% ""),
      saved_at = as.character(m$saved_at %||% ""),
      stringsAsFactors = FALSE
    )
  }
  if (!length(rows)) return(data.frame())
  do.call(rbind, rows)
}

fpa_shiny_write_lock <- function(paths) {
  status <- fpa_shiny_csv(file.path(paths$work, "period-status.csv"))
  pnl <- fpa_shiny_csv(file.path(paths$work, "pnl-monthly.csv"))
  if (!nrow(status) || !nrow(pnl) || !("status" %in% names(status))) {
    stop("Pas de statut de periode. Lancez le moteur d'abord.", call. = FALSE)
  }
  closed <- as.character(status$periode[status$status == "actual"])
  if (!length(closed)) stop(fpa_screen("loc_no_close_lock"), call. = FALSE)
  lines <- intersect(fpa_pnl_input_ids(), names(pnl))
  rows <- list()
  for (line in lines) {
    sl <- pnl[pnl$periode %in% closed, c("periode", line), drop = FALSE]
    if (!nrow(sl)) next
    rows[[length(rows) + 1L]] <- data.frame(
      periode = sl$periode, line_id = line, montant = as.numeric(sl[[line]]),
      stringsAsFactors = FALSE
    )
  }
  if (!length(rows)) stop("Rien a verrouiller.", call. = FALSE)
  fresh <- do.call(rbind, rows)
  old <- fpa_shiny_csv(file.path(paths$work, "standing-lock.csv"))
  out <- fpa_close_lock_merge(old, fresh)
  utils::write.csv(out, file.path(paths$work, "standing-lock.csv"), row.names = FALSE)
  had <- if (nrow(old)) unique(as.character(old$periode)) else character(0)
  list(lock = out, added = setdiff(unique(as.character(fresh$periode)), had))
}

#' The name on Paramètres is project.name, the same string as the Nom column on the site.
#' The company stays on its own line.
fpa_shiny_project_title <- function(cfg) {
  proj <- if (is.null(cfg)) list() else cfg$project %||% list()
  company <- if (is.null(cfg)) list() else cfg$company %||% list()
  name <- as.character(proj$name %||% "")
  company_name <- as.character(company$name %||% "")
  if (!nzchar(name)) name <- company_name
  if (!nzchar(name)) name <- "Projet"
  list(name = name, company = company_name)
}

fpa_shiny_eur <- function(x) {
  x <- suppressWarnings(as.numeric(x))
  if (!length(x) || !is.finite(x[[1]])) return("n/a")
  format(round(x[[1]]), big.mark = " ", scientific = FALSE, trim = TRUE)
}

#' Smallest amount worth a manual line. See fpa_manual_floor.
fpa_shiny_manual_floor <- function(cash) fpa_manual_floor(cash)

fpa_shiny_bridge_frame <- function(row) {
  pieces <- c(
    "Résultat net" = as.numeric(row$NI),
    "Dotations" = as.numeric(row$D_A),
    "BFR" = as.numeric(row$wc_impact),
    "Dénouement du BFR d'ouverture" = if ("wc_opening_release" %in% names(row)) as.numeric(row$wc_opening_release) else 0,
    "Investissement" = -as.numeric(row$capex),
    "Dette" = as.numeric(row$debt_net)
  )
  pieces <- pieces[is.finite(pieces) & abs(pieces) >= 0.5]
  if (!length(pieces)) return(NULL)
  end <- cumsum(as.numeric(pieces))
  data.frame(
    label = names(pieces),
    value = as.numeric(pieces),
    base = c(0, end[-length(end)]),
    end = end,
    stringsAsFactors = FALSE
  )
}

fpa_shiny_bridge_row <- function(cash, period) {
  if (is.null(cash) || !nrow(cash)) return(NULL)
  per <- as.character(period %||% "")
  if (!nzchar(per) || !per %in% cash$periode) per <- as.character(cash$periode[nrow(cash)])
  cash[as.character(cash$periode) == per, , drop = FALSE][1, , drop = FALSE]
}

fpa_shiny_bridge_periods <- function(cash, view, period, span, start) {
  pers <- as.character(cash$periode)
  if (!length(pers)) return(character())
  key <- as.character(view %||% "6")
  if (!nzchar(key)) key <- "6"
  if (identical(key, "one")) {
    per <- as.character(period %||% "")
    if (!nzchar(per)) per <- as.character(start %||% "")
    if (!nzchar(per) || !per %in% pers) per <- pers[[length(pers)]]
    return(per)
  }
  if (identical(key, "series")) key <- as.character(span %||% "6")
  if (identical(key, "all")) {
    i0 <- match(as.character(start %||% ""), pers)
    if (is.na(i0)) i0 <- 1L
    return(pers[seq.int(i0, length(pers))])
  }
  n <- suppressWarnings(as.integer(key))
  if (!is.finite(n) || n < 1L) n <- 6L
  n <- min(as.integer(n), length(pers))
  if (n >= length(pers)) return(pers)
  i0 <- match(as.character(start %||% ""), pers)
  if (is.na(i0)) i0 <- max(1L, length(pers) - n + 1L)
  end <- min(length(pers), i0 + n - 1L)
  pers[seq.int(i0, end)]
}

#' X of the dotted line where the bridge leaves the closed months.
#' NA when the window is entirely closed.
fpa_shiny_bridge_future_x <- function(built, forecast) {
  months <- built$months
  if (is.null(months) || !nrow(months) || !length(forecast)) return(NA_real_)
  fc <- months$month %in% as.character(forecast)
  if (!any(fc)) return(NA_real_)
  first <- which(fc)[[1]]
  if (first <= 1L) return(min(built$bars$x) - 0.42)
  (months$x1[[first - 1L]] + months$x0[[first]]) / 2
}

fpa_shiny_bridge_rows <- function(cash, periods) {
  rows <- list()
  for (p in periods) {
    r <- cash[as.character(cash$periode) == p, , drop = FALSE]
    if (nrow(r)) rows[[length(rows) + 1L]] <- r[1, , drop = FALSE]
  }
  rows
}

#' One cascade, three shapes: one month, months side by side, or one bar per month.
#' Chained mode opens on real cash so the last bar equals the closing balance.
fpa_shiny_bridge_build <- function(cash, view, period, span, start, link = "reset", grain = "poste") {
  if (is.null(cash) || !nrow(cash)) return(NULL)
  rows <- fpa_shiny_bridge_rows(cash, fpa_shiny_bridge_periods(cash, view, period, span, start))
  if (!length(rows)) return(NULL)
  pers <- vapply(rows, function(r) as.character(r$periode), character(1))
  multi <- length(pers) > 1L
  monthly <- multi && identical(as.character(grain), "mois")
  chain <- multi && identical(as.character(link), "chain")
  width <- 0.86

  frames <- list()
  for (r in rows) {
    if (monthly) {
      v <- suppressWarnings(as.numeric(r$delta_cash))
      if (!is.finite(v)) v <- 0
      fr <- data.frame(label = as.character(r$periode), value = v, stringsAsFactors = FALSE)
    } else {
      fr <- fpa_shiny_bridge_frame(r)
      if (is.null(fr)) next
      fr <- fr[, c("label", "value"), drop = FALSE]
    }
    fr$month <- as.character(r$periode)
    frames[[length(frames) + 1L]] <- fr
  }
  if (!length(frames)) return(NULL)

  gap <- if (monthly) 0.08 else 0.18
  cursor <- 1
  for (i in seq_along(frames)) {
    n <- nrow(frames[[i]])
    frames[[i]]$x <- cursor + seq_len(n) - 1
    cursor <- cursor + n + gap
  }
  bars <- do.call(rbind, frames)
  bars$kind <- "step"

  opening <- suppressWarnings(as.numeric(rows[[1]]$cash_open))
  closing <- suppressWarnings(as.numeric(rows[[length(rows)]]$cash_close))
  if (!is.finite(opening)) opening <- 0

  carry <- if (chain) opening else 0
  prev_month <- bars$month[[1]]
  base <- numeric(nrow(bars))
  for (i in seq_len(nrow(bars))) {
    if (!chain && !identical(bars$month[[i]], prev_month)) carry <- 0
    prev_month <- bars$month[[i]]
    base[[i]] <- carry
    carry <- carry + bars$value[[i]]
  }
  bars$base <- base
  bars$end <- base + bars$value

  keep <- c("label", "value", "month", "x", "kind", "base", "end")
  bars <- bars[, keep, drop = FALSE]
  if (chain) {
    if (!is.finite(closing)) closing <- bars$end[[nrow(bars)]]
    caps <- data.frame(
      label = c("Ouverture", fpa_screen("loc_closing")),
      value = c(opening, closing),
      month = c(pers[[1]], pers[[length(pers)]]),
      x = c(min(bars$x) - 1.3, max(bars$x) + 1.3),
      kind = c("total", "total"),
      base = c(0, 0),
      end = c(opening, closing),
      stringsAsFactors = FALSE
    )
    bars <- rbind(caps[1, , drop = FALSE], bars, caps[2, , drop = FALSE])
  }
  bars <- bars[order(bars$x), , drop = FALSE]
  rownames(bars) <- NULL

  connectors <- list()
  if (nrow(bars) > 1) {
    for (i in seq_len(nrow(bars) - 1L)) {
      linked <- chain || identical(bars$month[[i]], bars$month[[i + 1L]])
      if (!linked) next
      connectors[[length(connectors) + 1L]] <- data.frame(
        x0 = bars$x[[i]] + width / 2,
        x1 = bars$x[[i + 1L]] - width / 2,
        y = bars$end[[i]],
        stringsAsFactors = FALSE
      )
    }
  }

  steps <- bars[bars$kind == "step", , drop = FALSE]
  month_labs <- do.call(rbind, lapply(pers, function(p) {
    xs <- steps$x[steps$month == p]
    if (!length(xs)) return(NULL)
    data.frame(month = p, x = mean(xs), x0 = min(xs), x1 = max(xs), stringsAsFactors = FALSE)
  }))

  list(
    bars = bars,
    connectors = if (length(connectors)) do.call(rbind, connectors) else NULL,
    months = month_labs,
    periods = pers,
    width = width,
    chain = chain,
    monthly = monthly,
    opening = opening,
    closing = closing
  )
}

#' Label tiers: the chart always fills the panel. Labels thin out; zoom recovers the detail.
fpa_shiny_bridge_tiers <- function(built) {
  n <- nrow(built$bars)
  m <- length(built$periods)
  one <- m <= 1L
  monthly <- isTRUE(built$monthly)
  list(
    one = one,
    bars = n,
    values = one || n <= 22L,
    upright = one || n <= 7L,
    steps_on_axis = one || monthly || m <= 3L,
    month_every = max(1L, as.integer(ceiling(m / if (monthly) 16 else 12))),
    bands = !one && !monthly,
    zoom = n > 22L
  )
}

