)

fpa_shiny_cash_cell <- function(v, strong = FALSE) {
  txt <- fpa_shiny_eur(v)
  num <- suppressWarnings(as.numeric(v))
  col <- if (is.finite(num) && num < 0) "#8c3a3a" else "#1a2b32"
  shiny::tags$td(
    style = paste0(
      "text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap;",
