  )
}

#' The same months as the chart, named in French, with empty columns dropped.
fpa_shiny_cash_table_ui <- function(cash, periods, focus = NULL, mode = "abs",
                                    nature = character(0), show_op_fin = FALSE, scope = "all",
                                    status = NULL) {
  if (is.null(cash) || !nrow(cash)) return(shiny::tags$p(fpa_screen("loc_no_cash")))
  mode <- as.character(mode %||% "abs")
  if (!mode %in% c("abs", "pct", "pop")) mode <- "abs"
  pers <- as.character(cash$periode)
  wanted <- as.character(periods %||% character(0))
  wanted <- wanted[wanted %in% pers]
  if (!length(wanted)) wanted <- utils::tail(pers, 12)
  if (length(wanted) == 1L) {
    i <- match(wanted, pers)
    wanted <- pers[seq.int(max(1L, i - 11L), i)]
  }
  df <- cash[match(wanted, pers), , drop = FALSE]
  cols <- Filter(function(c) {
    if (!c$key %in% names(df)) return(FALSE)
    v <- suppressWarnings(as.numeric(df[[c$key]]))
    any(is.finite(v) & abs(v) >= 0.5)
  }, fpa_shiny_cash_cols)
  cols <- Filter(function(c) fpa_nature_keep(c$key, nature, scope), cols)
  if (!length(cols)) return(shiny::tags$p(fpa_screen("loc_no_cash")))
  dropped <- setdiff(
    vapply(fpa_shiny_cash_cols, function(c) c$label, character(1)),
    vapply(cols, function(c) c$label, character(1))
  )
  close_v <- if ("cash_close" %in% names(df)) suppressWarnings(as.numeric(df$cash_close)) else rep(NA_real_, nrow(df))
  series <- lapply(cols, function(c) {
    vals <- suppressWarnings(as.numeric(df[[c$key]]))
    if (identical(mode, "pct")) return(vapply(seq_along(vals), function(j) fpa_stmt_ratio(vals[[j]], close_v[[j]]), numeric(1)))
    if (identical(mode, "pop")) {
      out <- rep(NA_real_, length(vals))
      if (length(vals) > 1L) out[-1L] <- vapply(seq.int(2L, length(vals)), function(j) fpa_stmt_delta(vals[[j]], vals[[j - 1L]]), numeric(1))
      return(out)
    }
    vals
  })
  pool <- unlist(series, use.names = FALSE)
  pool <- pool[is.finite(pool)]
  cap <- if (length(pool)) max(abs(pool)) else 1
  note <- if (identical(mode, "pct")) fpa_screen("stmt_pct_cash") else if (identical(mode, "pop")) fpa_screen("stmt_pop_note") else fpa_screen("stmt_heat_note")
  forecast <- character()
  if (!is.null(status) && nrow(status) && all(c("periode", "status") %in% names(status))) {
    forecast <- as.character(status$periode)[as.character(status$status) == "forecast"]
  }
  shiny::tagList(
    shiny::tags$div(
      class = "fpa-pnl",
      shiny::tags$table(
        shiny::tags$thead(shiny::tags$tr(
          shiny::tags$th("Ligne"),
          lapply(seq_len(nrow(df)), function(j) {
            per <- as.character(df$periode[[j]])
            on <- !is.null(focus) && identical(per, as.character(focus))
            shiny::tags$th(style = if (on) "background:#8a5a00;" else NULL, per)
          })
        )),
        shiny::tags$tbody(lapply(seq_along(cols), function(i) {
          c <- cols[[i]]
          raw <- suppressWarnings(as.numeric(df[[c$key]]))
          disp <- series[[i]]
          shiny::tags$tr(
            class = if (c$kind == "balance") "fpa-pnl-total" else NULL,
            fpa_shiny_nature_th(c$label, fpa_line_nature_of(nature, c$key), show_op_fin),
            lapply(seq_along(raw), function(j) {
              text <- if (identical(mode, "pct")) {
                fpa_shiny_pct_label(disp[[j]])
              } else if (identical(mode, "pop")) {
                fpa_shiny_signed_eur(disp[[j]])
              } else if (is.finite(raw[[j]]) && abs(raw[[j]]) >= 0.5) {
                fpa_shiny_eur(raw[[j]])
              } else {
                "–"
              }
              per <- as.character(df$periode[[j]])
              tip <- paste0(c$label, " · ", per, if (is.finite(raw[[j]])) paste0(" · ", fpa_shiny_eur(raw[[j]]), " EUR") else "")
              chip <- fpa_shiny_chip(text, fpa_shiny_chip_score(disp[[j]], cap))
              clickable <- per %in% forecast
              shiny::tags$td(
                title = if (clickable) paste0(tip, " · ", fpa_screen("oi_read_open")) else tip,
                if (clickable) fpa_shiny_cell_button(chip, "cash", per, c$key) else chip
              )
            })
          )
        }))
      )
    ),
    shiny::tags$p(
      style = "color:#5c6b73;font-size:12.5px;margin:0 0 1rem;",
      note, fpa_screen("loc_bridge_same_months"),
      if (any(as.character(df$periode) %in% forecast)) shiny::tagList(
        shiny::tags$span(
          class = "fpa-oi-mark",
          shiny::tags$span(class = "fpa-oi-swatch", `aria-hidden` = "true"),
          fpa_screen("oi_read_hint")
        ),
        " "
      ) else NULL,
      if (isTRUE(show_op_fin)) paste0(" ", fpa_screen("stmt_opfin_note")) else "",
      if (length(dropped)) paste0(fpa_screen("loc_empty_rows_hidden"), paste(dropped, collapse = ", "), ".") else ""
    )
  )
}

fpa_shiny_load <- function(config_path) {
  empty <- list(
    ok = FALSE, drivers_ok = FALSE, finance_ok = FALSE,
    message = "Indiquez le chemin de fpa-config.json.",
    finance = list()
  )
  if (!nzchar(config_path) || !file.exists(config_path)) return(empty)
  config <- tryCatch(fpa_load_config(config_path), error = function(e) NULL)
  if (is.null(config)) {
    return(list(ok = FALSE, drivers_ok = FALSE, finance_ok = FALSE,
                 message = "JSON illisible.", finance = list()))
  }
  paths <- fpa_paths(config)
  fpa_shiny_set_series_meta(config)
  finance <- fpa_shiny_finance(paths)
  finance_ok <- nrow(finance$pnl) > 0
  root <- file.path(paths$work, "drivers")
  grades_path <- file.path(root, "driver-grades.csv")
  base <- list(
    ok = TRUE,
    finance_ok = finance_ok,
    config_path = config_path,
    config = config,
    paths = paths,
    finance = finance,
    message = ""
  )
  if (!file.exists(grades_path)) {
    base$drivers_ok <- FALSE
    base$message <- paste0(
      fpa_screen("loc_no_driver_result"), root,
      fpa_screen("loc_run_engine_first")
    )
    base$grades <- data.frame()
    base$profiles <- list()
    return(base)
  }
  read_csv <- function(name) {
    p <- file.path(root, name)
    if (!file.exists(p)) return(data.frame())
    utils::read.csv(p, stringsAsFactors = FALSE, fileEncoding = "UTF-8")
  }
  grades <- read_csv("driver-grades.csv")
  if (!fpa_driver_bottom_done(grades)) {
    filled <- tryCatch(fpa_driver_apply_bottom(grades, config), error = function(e) NULL)
    if (!is.null(filled) && fpa_driver_bottom_done(filled)) {
      grades <- filled
      fpa_driver_write_csv(grades, grades_path)
    }
  }
  profiles <- list()
  prof_dir <- file.path(root, "lag-profiles")
  if (dir.exists(prof_dir)) {
    for (f in list.files(prof_dir, pattern = "\\.csv$", full.names = TRUE)) {
      key <- sub("\\.csv$", "", basename(f))
      profiles[[key]] <- utils::read.csv(f, stringsAsFactors = FALSE)
    }
  }
  formulas <- read_csv("formula-checks.csv")
  grades <- tryCatch(fpa_driver_state(grades, formulas, config), error = function(e) grades)
  c(base, list(
    drivers_ok = TRUE,
    grades = grades,
    formulas = formulas,
    candidates = read_csv("driver-candidates.csv"),
    aligned = read_csv("aligned-series.csv"),
    oos = read_csv("oos-backtests.csv"),
    profiles = profiles,
    budget = if (nrow(grades)) {
      fpa_driver_data_budget(max(grades$n, na.rm = TRUE))
    } else {
      ""
    }
  ))
}

fpa_shiny_profile <- function(pack, series_id) {
  if (!length(pack$profiles)) return(NULL)
  safe <- gsub("[^A-Za-z0-9_-]", "_", series_id)
  hit <- pack$profiles[[safe]]
  if (!is.null(hit)) return(hit)
  pack$profiles[[series_id]]
}

fpa_shiny_slice <- function(df, series_id) {
  if (is.null(df) || !nrow(df) || !"series_id" %in% names(df)) return(df)
  df[df$series_id == series_id, , drop = FALSE]
}

fpa_shiny_lead <- function(...) {
  shiny::tags$div(
    style = "margin:0 0 0.75rem;line-height:1.45;color:#1a2b32;",
    lapply(list(...), function(txt) shiny::tags$p(style = "margin:0 0 0.35rem;", txt))
  )
}

fpa_shiny_use_badge <- function(g) {
  tier <- as.character(g$tier %||% "")
  forecast <- identical(as.character(g$driver_class), "forecasting")
  if (fpa_shiny_state_flag(g, "state_failed")) {
    return(list(label = fpa_screen("drv_badge_failed"), bg = "#f6f1e8", fg = "#8a5a00", mark = "pause"))
  }
  if (fpa_shiny_state_flag(g, "state_proved")) {
    return(list(label = fpa_screen("loc_use"), bg = "#1f4e5f", fg = "#fff", mark = "check"))
  }
  if (identical(tier, "confirmed") && forecast) {
    return(list(label = fpa_screen("loc_to_forecast"), bg = "#1f4e5f", fg = "#fff", mark = "check"))
  }
  if (identical(tier, "confirmed")) {
    return(list(label = fpa_screen("loc_to_explain"), bg = "#c47b2b", fg = "#fff", mark = "check"))
  }
  if (identical(tier, "mechanism")) {
    return(list(label = fpa_screen("loc_use"), bg = "#1f4e5f", fg = "#fff", mark = "check"))
  }
  list(label = "Pas encore", bg = "#f6f1e8", fg = "#8a5a00", mark = "pause")
}

fpa_shiny_use_cell <- function(g) {
  b <- fpa_shiny_use_badge(g)
  icon <- if (identical(b$mark, "check")) {
    '<svg viewBox="0 0 16 16" width="14" height="14" aria-hidden="true"><path d="M3.2 8.2 6.4 11.4 12.8 4.6" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>'
  } else {
    '<svg viewBox="0 0 16 16" width="14" height="14" aria-hidden="true"><path d="M5 4.5v7M11 4.5v7" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>'
  }
  shiny::tags$td(
    style = "padding:7px 10px;white-space:nowrap;",
    shiny::tags$span(
      style = paste0(
        "display:inline-flex;align-items:center;gap:6px;height:26px;padding:0 8px;border-radius:8px;",
        "font-size:12.5px;font-weight:700;background:", b$bg, ";color:", b$fg, ";"
      ),
      shiny::HTML(icon),
      b$label
    )
  )
}

#' Sensitivity rows in business words, sorted by the euro span.
fpa_shiny_sens_table <- function(s, keys = NULL) {
  if (is.null(s) || !nrow(s)) return(NULL)
  s <- s[order(-abs(suppressWarnings(as.numeric(s$oi_span)))), , drop = FALSE]
  fam <- c(finance = "Finance", costs = fpa_screen("loc_costs"), operations = fpa_screen("loc_operations"), commercial = "Commercial")
  head_style <- paste0(
    "position:sticky;top:0;background:#1f4e5f;color:#fff;font-weight:600;",
    "font-size:12.5px;padding:8px 10px;text-align:right;white-space:nowrap;"
  )
  num <- function(v, strong = FALSE) {
    x <- suppressWarnings(as.numeric(v))
    shiny::tags$td(
      style = paste0(
        "text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap;padding:6px 10px;",
        if (is.finite(x) && x < 0) "color:#8c3a3a;" else "color:#1a2b32;",
        if (strong) "font-weight:600;" else ""
      ),
      fpa_shiny_eur(x)
    )
  }
  rows <- lapply(seq_len(nrow(s)), function(i) {
    g <- s[i, , drop = FALSE]
    shiny::tags$tr(
      style = if (i %% 2 == 0) "background:#f6f9fa;" else "",
      shiny::tags$td(style = "padding:6px 10px;font-weight:600;white-space:nowrap;", fpa_scenario_label(g$assumption_id, fpa_scenario_find(keys, g$assumption_id))),
      shiny::tags$td(style = "padding:6px 10px;color:#5c6b73;", fam[[as.character(g$family)]] %||% as.character(g$family)),
      num(g$low), num(g$high), num(g$oi_low), num(g$oi_high), num(g$oi_span, strong = TRUE)
    )
  })
  shiny::tags$div(
    style = "border:1px solid #d6e1e5;border-radius:8px;overflow:hidden;margin:0.2rem 0 0.6rem;",
    shiny::tags$table(
      style = "width:100%;border-collapse:collapse;font-size:13px;",
      shiny::tags$thead(shiny::tags$tr(
        shiny::tags$th(style = paste0(head_style, "text-align:left;"), fpa_screen("loc_hypothesis")),
        shiny::tags$th(style = paste0(head_style, "text-align:left;"), "Famille"),
        shiny::tags$th(style = head_style, "Valeur basse"),
        shiny::tags$th(style = head_style, "Valeur haute"),
        shiny::tags$th(style = head_style, "RE au bas"),
        shiny::tags$th(style = head_style, "RE au haut"),
        shiny::tags$th(style = head_style, "Écart de RE")
      )),
      shiny::tags$tbody(rows)
    )
  )
}

#' What the sliders say right now, without running the engine.
fpa_shiny_scn_read <- function(lv, input) {
  assum <- lapply(lv$ids, function(id) {
    v <- suppressWarnings(as.numeric(input[[paste0("lev_", id)]] %||% 0))
    if (!is.finite(v)) 0 else v
  })
  names(assum) <- lv$ids
  lines <- lapply(lv$lines, function(nm) {
    v <- suppressWarnings(as.numeric(input[[paste0("line_", nm)]] %||% 0))
    if (!is.finite(v)) 0 else v
  })
  names(lines) <- lv$lines
  list(assum = assum, lines = lines)
}

fpa_shiny_scn_same <- function(a, b) {
  if (is.null(a) || is.null(b)) return(FALSE)
  same_num <- function(x, y) {
    nx <- names(x)
    ny <- names(y)
    if (!identical(sort(nx), sort(ny))) return(FALSE)
    for (nm in nx) {
      if (!isTRUE(all.equal(as.numeric(x[[nm]]), as.numeric(y[[nm]])))) return(FALSE)
    }
    TRUE
  }
  same_num(a$assum, b$assum) && same_num(a$lines, b$lines)
}

#' French label for a solved lever bundle: "Chiffre d'affaires +10 % · DSO -5 jours".
fpa_shiny_obj_move_lab <- function(deltas, keys) {
  bits <- fpa_shiny_scn_moves(deltas$assum %||% list(), deltas$lines %||% list(), keys)
  if (!length(bits)) "—" else paste(bits, collapse = " · ")
}

fpa_shiny_scn_moves <- function(assum, lines, keys) {
  bits <- fpa_scenario_moves(list(), assum, list(), keys)
  for (nm in names(lines)) {
    d <- suppressWarnings(as.numeric(lines[[nm]]))
    if (!is.finite(d) || d == 0) next
    bits <- c(bits, paste0(fpa_shiny_line_name(nm), " ", if (d > 0) "+" else "", d, " %"))
  }
  bits
}

#' One row per moved dial: absolute before/after, plus EUR gap for P&L lines.
fpa_shiny_scn_dial_rows <- function(lv, deltas, base_pnl = NULL, scen_pnl = NULL) {
  if (is.null(deltas)) return(list())
  rows <- list()
  assum <- deltas$assum %||% list()
  lines <- deltas$lines %||% list()
  for (id in names(assum)) {
    d <- suppressWarnings(as.numeric(assum[[id]]))
    if (!is.finite(d) || abs(d) < 1e-9) next
    key <- fpa_scenario_find(lv$keys %||% list(), id)
    spec <- fpa_scenario_lever_spec(id, key)
    base <- suppressWarnings(as.numeric(lv$base[[id]] %||% NA_real_))
    after <- if (is.finite(base)) fpa_scenario_value(spec, base, d) else NA_real_
    unit <- if (identical(spec$kind, "days")) "j" else if (identical(spec$kind, "points")) "pts" else "%"
    rows[[length(rows) + 1L]] <- list(
      type = "assum",
      label = fpa_scenario_label(id, key),
      delta = d,
      unit = unit,
      base = base,
      after = after
    )
  }
  for (nm in names(lines)) {
    d <- suppressWarnings(as.numeric(lines[[nm]]))
    if (!is.finite(d) || abs(d) < 1e-9) next
    sum_col <- function(pnl, col) {
      if (is.null(pnl) || !col %in% names(pnl)) return(NA_real_)
      v <- suppressWarnings(as.numeric(pnl[[col]]))
      if (!any(is.finite(v))) return(NA_real_)
      round(sum(v, na.rm = TRUE))
    }
    base_eur <- sum_col(base_pnl, nm)
    after_eur <- sum_col(scen_pnl, nm)
    rows[[length(rows) + 1L]] <- list(
      type = "line",
      label = fpa_shiny_line_name(nm),
      delta = d,
      unit = "%",
      base = base_eur,
      after = after_eur,
      gap = if (is.finite(base_eur) && is.finite(after_eur)) after_eur - base_eur else NA_real_
    )
  }
  rows
}

fpa_shiny_scn_unit_txt <- function(x, unit) {
  x <- suppressWarnings(as.numeric(x))
  if (!length(x) || !is.finite(x[[1]])) return("n/a")
  if (identical(unit, "%") || identical(unit, "pts")) {
    paste0(format(round(x[[1]], 2), trim = TRUE, decimal.mark = ","), " ", unit)
  } else {
    paste0(fpa_shiny_eur(x[[1]]), " ", unit)
  }
}

fpa_shiny_scn_dial_trace_ui <- function(rows) {
  if (!length(rows)) return(NULL)
  blocks <- lapply(rows, function(r) {
    move <- paste0(if (is.finite(r$delta) && r$delta > 0) "+" else "", r$delta, " ", r$unit)
    if (identical(r$type, "line")) {
      bits <- list(fpa_shiny_scn_pair(move, r$label))
      if (is.finite(r$gap %||% NA_real_)) {
        bits <- c(bits, list(
          fpa_shiny_scn_pair(paste(fpa_shiny_eur_signed(r$gap), "EUR"), fpa_screen("scn_lab_dial_gap")),
          "=",
          fpa_shiny_scn_pair(paste(fpa_shiny_eur(r$after), "EUR"), fpa_screen("scn_lab_dial_after")),
          "−",
          fpa_shiny_scn_pair(paste(fpa_shiny_eur(r$base), "EUR"), fpa_screen("scn_lab_dial_before"))
        ))
      }
      return(fpa_shiny_scn_align_ui(bits))
    }
    if (is.finite(r$after %||% NA_real_) && is.finite(r$base %||% NA_real_)) {
      fpa_shiny_scn_align_ui(list(
        fpa_shiny_scn_pair(fpa_shiny_scn_unit_txt(r$after, r$unit), fpa_screen("scn_lab_dial_after")),
        "=",
        fpa_shiny_scn_pair(fpa_shiny_scn_unit_txt(r$base, r$unit), fpa_screen("scn_lab_dial_before")),
        "+",
        fpa_shiny_scn_pair(move, r$label)
      ))
    } else {
      fpa_shiny_scn_align_ui(list(fpa_shiny_scn_pair(move, r$label)))
    }
  })
  shiny::tagList(
    shiny::tags$h4(style = "margin:0 0 8px;font-size:14px;color:#1f4e5f;", fpa_screen("scn_trace_dials")),
    blocks
  )
}

fpa_shiny_eur_signed <- function(x) {
  x <- suppressWarnings(as.numeric(x))
  if (!length(x) || !is.finite(x[[1]])) return("n/a")
  paste0(if (x[[1]] >= -0.5) "+" else "", fpa_shiny_eur(x[[1]]))
}

fpa_shiny_scn_axis_short <- function(id) {
  switch(
    as.character(id),
    dso = "Clients",
    dpo = "Fourn.",
    dio = "Stocks",
    "taux.impot" = fpa_screen("loc_tax"),
    "cout.variable.pct" = fpa_screen("loc_cost"),
    REV = "CA",
    COGS = "Achats",
    PAYROLL = "Salaires",
    OPEX_OTHER = "Autres",
    {
      lab <- fpa_shiny_line_name(id)
      if (!nzchar(lab) || nchar(lab) > 10) as.character(id) else lab
    }
  )
}

#' +1 when a higher slider helps cash. -1 when it hurts, so the spoke is drawn the other way.
#' Receivables and stock tie cash up. Payables release it. Revenue helps. Cost and tax hurt.
#' Lowercase first. The class is a-z, so stripping before tolower deletes REV and every
#' other uppercase id, and those spokes all fall through to "hurts".
fpa_shiny_scn_impact_sign <- function(id) {
  key <- gsub("[^a-z0-9]", "", tolower(as.character(id)))
  if (key %in% c("dpo", "rev", "otheropinc")) return(1)
  if (key %in% c(
    "dso", "dio", "cogs", "payroll", "opexother", "tax", "da", "fin", "excep",
    "tauximpot", "coutvariablepct"
  )) return(-1)
  if (grepl("dpo", key)) return(1)
  if (grepl("dso|dio", key)) return(-1)
  if (grepl("impot|taxe|cout|cost|charge|cogs|payroll|opex", key)) return(-1)
  if (grepl("^rev|vente|tarif", key)) return(1)
  -1
}

#' One spoke per slider. The middle ring is no effect on cash.
#' Beyond it, the move helps. Inside it, the move hurts.
#' That ring is a faint gold line on a pale yellow disk, so a dial left at zero stays visible.
fpa_shiny_scn_axes <- function(entry, lv) {
  if (is.null(lv) || is.null(entry$deltas)) return(list())
  axes <- list()
  for (id in lv$ids) {
    spec <- fpa_scenario_lever_spec(id, fpa_scenario_find(lv$keys, id))
    half <- max(abs(spec$min), abs(spec$max), 1)
    v <- suppressWarnings(as.numeric(entry$deltas$assum[[id]] %||% 0))
    if (!is.finite(v)) v <- 0
    axes[[length(axes) + 1L]] <- list(
      short = fpa_shiny_scn_axis_short(id),
      t = fpa_shiny_scn_impact_sign(id) * v / half
    )
  }
  for (nm in lv$lines) {
    range <- lv$line_spec[[nm]] %||% list(min = -20, max = 20)
    half <- max(abs(range$min %||% 20), abs(range$max %||% 20), 1)
    v <- suppressWarnings(as.numeric(entry$deltas$lines[[nm]] %||% 0))
    if (!is.finite(v)) v <- 0
    axes[[length(axes) + 1L]] <- list(
      short = fpa_shiny_scn_axis_short(nm),
      t = fpa_shiny_scn_impact_sign(nm) * v / half
    )
  }
  axes
}

fpa_shiny_scn_web <- function(entry, axes, open_ix = NULL) {
  n <- length(axes)
  if (!n) return(NULL)
  cx <- 120
  cy <- 118
  rad <- 62
  ang <- -pi / 2 + (seq_len(n) - 1L) * 2 * pi / n
  xy <- function(a, r) c(cx + r * cos(a), cy + r * sin(a))
  ring_pts <- function(t) {
    rr <- rad * (t + 1) / 2
    paste(vapply(ang, function(a) {
      p <- xy(a, rr)
      paste(round(p[[1]], 1), round(p[[2]], 1), sep = ",")
    }, character(1)), collapse = " ")
  }
  pts <- lapply(seq_len(n), function(i) {
    t <- axes[[i]]$t
    if (!is.finite(t)) t <- 0
    t <- max(-1, min(1, t))
    p <- xy(ang[[i]], rad * (t + 1) / 2)
    list(x = round(p[[1]], 1), y = round(p[[2]], 1), t = t)
  })
  poly <- paste(vapply(pts, function(p) paste(p$x, p$y, sep = ","), character(1)), collapse = " ")
  gap <- suppressWarnings(as.numeric(entry$cash_delta))
  click <- if (!is.null(open_ix) && is.finite(open_ix)) {
    sprintf("Shiny.setInputValue('scn_open', %d, {priority:'event'})", as.integer(open_ix))
  } else {
    NULL
  }
  shiny::tags$div(
    class = paste("fpa-scn-web", if (!is.null(click)) "is-click" else ""),
    role = if (!is.null(click)) "button" else NULL,
    tabindex = if (!is.null(click)) "0" else NULL,
    onclick = click,
    title = if (!is.null(click)) fpa_screen("scn_trace_hint") else NULL,
    shiny::tags$div(class = "fpa-scn-web-time", substr(as.character(entry$at %||% ""), 12, 19)),
    shiny::tags$svg(
      viewBox = "-16 -10 272 256",
      class = "fpa-scn-web-svg",
      role = "img",
      lapply(ang, function(a) {
        p <- xy(a, rad)
        shiny::tags$line(
          x1 = cx, y1 = cy, x2 = round(p[[1]], 1), y2 = round(p[[2]], 1),
          stroke = "#e6edef", `stroke-width` = "1"
        )
      }),
      shiny::tags$polygon(points = ring_pts(1), fill = "none", stroke = "#e6edef", `stroke-width` = "1"),
      shiny::tags$polygon(
        points = ring_pts(0),
        fill = "#f6e7a4", `fill-opacity` = "0.55",
        stroke = "none"
      ),
      shiny::tags$polygon(
        points = poly, fill = "#1f4e5f", `fill-opacity` = "0.35",
        stroke = "#1f4e5f", `stroke-width` = "1.8", `stroke-linejoin` = "round"
      ),
      shiny::tags$polygon(
        points = ring_pts(0),
        fill = "none",
        stroke = "#c9a227", `stroke-opacity` = "0.8", `stroke-width` = "2.2"
      ),
      lapply(seq_len(n), function(i) {
        p <- xy(ang[[i]], 86)
        anchor <- if (p[[1]] < cx - 10) "end" else if (p[[1]] > cx + 10) "start" else "middle"
        shiny::tags$text(
          x = round(p[[1]], 1), y = round(p[[2]], 1),
          `text-anchor` = anchor, `dominant-baseline` = "middle",
          fill = "#3d4c54", style = "font-size:11px;",
          axes[[i]]$short
        )
      })
    ),
    shiny::tags$div(
      class = paste("fpa-scn-web-gap", if (is.finite(gap) && gap < -0.5) "neg" else ""),
      fpa_shiny_eur_signed(gap)
    )
  )
}

fpa_shiny_rel_path <- function(path, root) {
  path <- gsub("\\\\", "/", as.character(path %||% ""))
  if (!nzchar(path) || identical(path, "NA")) return("")
  root_n <- sub("/+$", "", gsub("\\\\", "/", as.character(root %||% "")))
  prefix <- paste0(root_n, "/")
  if (nzchar(root_n) && startsWith(tolower(path), tolower(prefix))) {
    return(substring(path, nchar(prefix) + 1L))
  }
  hit <- regexpr("fpa-local-test/", path, ignore.case = TRUE)
  if (hit[[1]] > 0L) return(substring(path, hit[[1]] + nchar("fpa-local-test/")))
  basename(path)
}

fpa_shiny_scn_files <- function(config) {
  fpa_shiny_scn_files_for(config, c(
    "pnl_monthly", "pnl_actuals", "opening_bs", "budget",
    "assumptions", "decisions", "ops_other"
  ))
}

#' Only the paths that feed the figure on screen. keys are config path names or work_*.
fpa_shiny_scn_files_for <- function(config, keys) {
  root <- config$paths$working_root_hint %||% ""
  roles <- c(
    pnl_monthly = fpa_screen("loc_pnl_monthly"),
    pnl_actuals = "Compte de résultat",
    opening_bs = "Bilan d'ouverture",
    budget = "Budget",
    assumptions = "Paramètres",
    decisions = "Calendrier investissement et dette",
    ops_other = "Volumes",
    manual = "Saisies manuelles",
    work_cash = fpa_screen("loc_cash_monthly"),
    work_pnl = fpa_screen("loc_pnl_monthly")
  )
  out <- list()
  seen <- character()
  for (nm in keys) {
    abs_path <- if (identical(nm, "work_cash")) {
      file.path(root, "work", "cash-bridge-monthly.csv")
    } else if (identical(nm, "work_pnl")) {
      file.path(root, "work", "pnl-monthly.csv")
    } else if (identical(nm, "manual")) {
      fpa_manual_path(config)
    } else {
      config$paths[[nm]] %||% ""
    }
    relp <- fpa_shiny_rel_path(abs_path, root)
    if (!nzchar(relp) || relp %in% seen) next
    seen <- c(seen, relp)
    out[[length(out) + 1L]] <- list(path = relp, role = unname(roles[[nm]] %||% nm))
  }
  out
}

fpa_shiny_scn_bridge <- function(cash) {
  if (is.null(cash) || !nrow(cash)) return(NULL)
  need <- c("cash_open", "cash_close", "NI", "D_A", "wc_impact")
  if (!all(need %in% names(cash))) return(NULL)
  last <- cash[nrow(cash), , drop = FALSE]
  num <- function(col) {
    if (!col %in% names(last)) return(0)
    v <- suppressWarnings(as.numeric(last[[col]][[1]]))
    if (!is.finite(v)) 0 else round(v)
  }
  list(
    periode = as.character(last$periode[[1]] %||% ""),
    close = num("cash_close"),
    open = num("cash_open"),
    ni = num("NI"),
    da = num("D_A"),
    wc = num("wc_impact"),
    capex = num("capex"),
    debt = num("debt_net")
  )
}

fpa_shiny_scn_pair <- function(num, lab) list(num = num, lab = lab)

fpa_shiny_scn_align_ui <- function(bits) {
