  shiny::tags$div(
    class = "fpa-kpi-align",
    lapply(bits, function(bit) {
      if (is.character(bit)) return(shiny::tags$span(class = "op", bit))
      shiny::tags$span(
        class = "pair",
        shiny::tags$span(class = "num", bit$num),
        shiny::tags$span(class = "lab", bit$lab)
      )
    })
  )
}

fpa_shiny_scn_bridge_bits <- function(b, close_lab) {
