#' French month and year for one YYYY-MM. A run of open months becomes one span.
fpa_shiny_scn_month_lab <- function(periode) {
  periode <- as.character(periode %||% "")
  if (!grepl("^[0-9]{4}-[0-9]{2}$", periode)) return("")
  paste(fpa_chain_month_fr(as.integer(substr(periode, 6, 7))), substr(periode, 1, 4))
}

fpa_shiny_scn_span <- function(periods) {
  periods <- sort(unique(as.character(periods %||% character(0))))
  periods <- periods[grepl("^[0-9]{4}-[0-9]{2}$", periods)]
  labs <- vapply(periods, fpa_shiny_scn_month_lab, character(1))
  labs <- labs[nzchar(labs)]
  if (!length(labs)) return("")
  if (length(labs) == 1L) return(labs[[1]])
  ym <- as.integer(substr(periods, 1, 4)) * 12L + as.integer(substr(periods, 6, 7))
  if (length(ym) == length(labs) && all(diff(ym) == 1L)) {
    return(fpa_screen("scn_trace_span", labs[[1]], labs[[length(labs)]]))
  }
  paste(labs, collapse = ", ")
}

fpa_shiny_scn_has_line_move <- function(deltas) {
  v <- suppressWarnings(as.numeric(unlist(deltas$lines %||% list())))
  any(is.finite(v) & abs(v) > 1e-9)
}

fpa_shiny_obj_info <- function(p) {
  if (!isTRUE(p$ok)) return(fpa_year_end_info(list(), NULL, character(0)))
  pers <- as.character((p$finance$pnl %||% p$finance$cash %||% list())$periode %||% character(0))
  fpa_year_end_info(p$config, p$finance$period_status, pers)
}

#' Label of a year-end metric. The close-month income names its month.
fpa_shiny_obj_metric_lab <- function(metric, info = NULL) {
  month <- as.character(info$measured %||% "")
  switch(
    metric,
    oi_fy = fpa_screen("obj_metric_oi_fy"),
    oi_ye = if (nzchar(month)) fpa_screen("obj_metric_oi_month", fpa_ym_fr(month)) else fpa_screen("obj_metric_oi"),
    fpa_screen("obj_metric_cash")
  )
}

fpa_shiny_obj_fy_note <- function(info) {
  months <- info$months %||% character(0)
  span <- if (length(months)) fpa_shiny_scn_span(months) else ""
  if (isTRUE(info$beyond)) {
    return(fpa_screen("obj_fy_beyond", fpa_ym_fr(info$close), fpa_ym_fr(info$measured), span))
  }
  fpa_screen("obj_fy_note", span, fpa_ym_fr(info$close))
}

#' Frozen figures of one scenario pass. Both income meanings travel together.
fpa_shiny_scn_kpi_fields <- function(scen_kpi, base_kpi, info) {
  r <- function(x) if (is.finite(x %||% NA_real_)) round(x) else NA_real_
  cash_close <- r(scen_kpi$close)
  oi_fy <- r(scen_kpi$oi_fy)
  oi_last <- r(scen_kpi$oi_last)
  list(
    cash_close = cash_close,
    cash_delta = cash_close - r(base_kpi$close),
    oi = oi_fy,
    oi_delta = oi_fy - r(base_kpi$oi_fy),
    oi_fy = oi_fy,
    oi_fy_delta = oi_fy - r(base_kpi$oi_fy),
    oi_last = oi_last,
    oi_last_delta = oi_last - r(base_kpi$oi_last),
    base_cash = r(base_kpi$close),
    base_oi = r(base_kpi$oi_fy),
    base_oi_fy = r(base_kpi$oi_fy),
    base_oi_last = r(base_kpi$oi_last),
    ye_month = as.character(info$measured %||% ""),
    fy_close = as.character(info$close %||% ""),
    fy_months = as.character(info$months %||% character(0))
  )
}

#' Gap = scenario − reference, once for the fiscal year and once for the close month.
fpa_shiny_scn_oi_identities <- function(e, base_oi = NULL, info = NULL) {
  month <- as.character(e$ye_month %||% info$measured %||% "")
  inf <- list(measured = month)
  fy_v <- e$oi_fy %||% e$oi
  fy_b <- e$base_oi_fy %||% base_oi %||% e$base_oi
  fy_d <- e$oi_fy_delta %||% e$oi_delta
  span <- fpa_shiny_scn_span(e$fy_months %||% info$months %||% character(0))
  one <- function(lab, d, v, b) {
    shiny::tagList(
      shiny::tags$p(style = "margin:0 0 4px;font-size:12.5px;font-weight:600;color:#1f4e5f;", lab),
      fpa_shiny_scn_align_ui(list(
        fpa_shiny_scn_pair(fpa_shiny_eur_signed(d), fpa_screen("scn_lab_oi_gap")),
        "=",
        fpa_shiny_scn_pair(paste(fpa_shiny_eur(v), "EUR"), fpa_screen("scn_lab_pass_oi")),
        "−",
        fpa_shiny_scn_pair(paste(fpa_shiny_eur(b), "EUR"), fpa_screen("scn_lab_ref_oi"))
      ))
    )
  }
  shiny::tagList(
    one(
      if (nzchar(span)) paste0(fpa_shiny_obj_metric_lab("oi_fy", inf), " · ", span) else fpa_shiny_obj_metric_lab("oi_fy", inf),
      fy_d, fy_v, fy_b
    ),
    if (!is.null(e$oi_last)) one(
      fpa_shiny_obj_metric_lab("oi_ye", inf),
      e$oi_last_delta, e$oi_last, e$base_oi_last
    )
  )
}

fpa_shiny_scn_files_table <- function(files) {
  if (!length(files)) return(NULL)
  shiny::tagList(
    shiny::tags$h4(style = "margin:4px 0 8px;font-size:14px;color:#1f4e5f;", fpa_screen("scn_trace_files")),
    shiny::tags$table(
      shiny::tags$thead(shiny::tags$tr(
        shiny::tags$th(fpa_screen("scn_th_file")),
        shiny::tags$th(fpa_screen("scn_th_role"))
      )),
      shiny::tags$tbody(lapply(files, function(f) {
        shiny::tags$tr(
          shiny::tags$td(f$path),
          shiny::tags$td(f$role)
        )
      }))
    )
  )
}

fpa_shiny_scn_trace_style <- function() {
  shiny::tags$style(HTML("
    .modal-dialog:has(.fpa-scn-trace) { max-width:980px; width:94vw; }
    .fpa-scn-trace .fpa-kpi-align { display:flex; flex-wrap:wrap; align-items:flex-start; gap:2px 8px; margin:0 0 16px; }
    .fpa-scn-trace .pair { display:flex; flex-direction:column; align-items:center; text-align:center; max-width:11em; }
    .fpa-scn-trace .num { font-family:Consolas,'Courier New',monospace; font-weight:700; font-size:14px; color:#0f2f3a; white-space:nowrap; }
    .fpa-scn-trace .lab { font-size:12px; color:#3d4c54; line-height:1.25; margin-top:3px; }
    .fpa-scn-trace .op { font-weight:700; font-size:14px; color:#0f2f3a; line-height:1.3; padding-top:0; }
