#' Up to ten applied passes. Newest first. The green dot is the passage on the dials.
fpa_shiny_scn_log_ui <- function(entries, lv = NULL, now = NULL) {
  n <- length(entries)
  head_style <- paste0(
    "position:sticky;top:0;background:#1f4e5f;color:#fff;font-weight:600;",
    "font-size:12.5px;padding:8px 10px;text-align:right;white-space:nowrap;"
  )
  num_cell <- function(x, signed = FALSE) {
    v <- suppressWarnings(as.numeric(x))
    shiny::tags$td(
      style = paste0(
        "text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap;padding:6px 10px;",
        if (is.finite(v) && v < -0.5) "color:#8c3a3a;" else "color:#1a2b32;"
      ),
      if (signed) fpa_shiny_eur_signed(v) else fpa_shiny_eur(v)
    )
  }
  current_ix <- if (n) n else 0L
  if (n && !is.null(now)) {
    for (i in rev(seq_len(n))) {
      if (fpa_shiny_scn_same(now, entries[[i]]$deltas)) {
        current_ix <- i
        break
      }
    }
  }
  ord <- if (n) rev(seq_len(n)) else integer()
  chrono <- if (n) seq_len(n) else integer()
  rows <- lapply(ord, function(i) {
    e <- entries[[i]]
    on <- identical(i, current_ix)
    none <- identical(as.character(e$moves %||% ""), fpa_screen("scn_none_moved"))
    bg <- if (none) {
      "background:#e8f2ee;box-shadow:inset 3px 0 0 #2e7d4f;"
    } else if (on) {
      "background:#e7eef0;"
    } else if ((n - i + 1L) %% 2L == 0L) {
      "background:#f6f9fa;"
    } else {
      ""
    }
    shiny::tags$tr(
      class = if (none) "fpa-scn-row-ref" else NULL,
      style = paste0(bg, "cursor:pointer;"),
      onclick = sprintf("Shiny.setInputValue('scn_open', %d, {priority:'event'})", i),
      shiny::tags$td(
        class = "fpa-scn-time",
        style = "padding:6px 10px;white-space:nowrap;font-variant-numeric:tabular-nums;",
        shiny::tags$span(
          class = "fpa-scn-mark",
          if (on) shiny::tags$span(class = "fpa-scn-now", title = fpa_screen("scn_now"), `aria-label` = fpa_screen("scn_now"))
        ),
        shiny::tags$span(class = "fpa-scn-at", e$at)
      ),
      shiny::tags$td(
        style = paste0(
          "padding:6px 10px;",
          if (none) "color:#3d5c52;font-style:italic;" else ""
        ),
        e$moves,
        shiny::tags$button(
          type = "button", class = "fpa-go-btn",
          style = "margin-left:8px;font-size:11px;padding:2px 8px;",
          onclick = sprintf(
            "event.stopPropagation(); Shiny.setInputValue('journal_capture',{kind:'scenario',ix:%d},{priority:'event'})",
            i
          ),
          fpa_screen("journal_to_journal")
        )
      ),
      num_cell(e$cash_close),
      num_cell(e$cash_delta, signed = TRUE),
      num_cell(e$oi_fy %||% e$oi),
      num_cell(e$oi_fy_delta %||% e$oi_delta, signed = TRUE),
      num_cell(e$oi_last %||% NA_real_),
      num_cell(e$oi_last_delta %||% NA_real_, signed = TRUE)
    )
  })
  last_month <- ""
  for (e in entries) if (nzchar(as.character(e$ye_month %||% ""))) last_month <- as.character(e$ye_month)
  oi_last_head <- if (grepl("^[0-9]{4}-[0-9]{2}$", last_month)) {
    fpa_screen("scn_h_oi_last", fpa_chain_month_fr(substr(last_month, 6L, 7L)))
  } else {
    fpa_screen("scn_h_oi")
  }
  gaps <- if (n) vapply(entries, function(e) suppressWarnings(as.numeric(e$cash_delta)), numeric(1)) else numeric(0)
  lim <- if (length(gaps) && any(is.finite(gaps))) max(abs(gaps[is.finite(gaps)]), 1) else 1
  bars <- lapply(chrono, function(i) {
    g <- gaps[[i]]
    if (!is.finite(g)) g <- 0
    pct <- 50 * abs(g) / lim
    if (abs(g) >= 0.5 && pct < 4) pct <- 4
    dir <- if (g < -0.5) "down" else "up"
    shiny::tags$div(
      class = "fpa-scn-col is-click",
      role = "button",
      tabindex = "0",
      onclick = sprintf("Shiny.setInputValue('scn_open', %d, {priority:'event'})", i),
      title = fpa_screen("scn_trace_hint"),
      shiny::tags$div(
        class = paste("fpa-scn-val", if (g < -0.5) "neg" else ""),
        fpa_shiny_eur_signed(g)
      ),
      shiny::tags$div(
        class = "fpa-scn-track",
        shiny::tags$div(class = "fpa-scn-zero"),
        shiny::tags$div(class = paste("fpa-scn-fill", dir), style = sprintf("height:%.1f%%;", pct))
      ),
      shiny::tags$div(class = "fpa-scn-tm", substr(entries[[i]]$at, 12, 19))
    )
  })
  shiny::tagList(
    shiny::tags$div(
      style = "display:flex;align-items:baseline;gap:10px;margin:0.8rem 0 0.3rem;",
      shiny::tags$h3(style = "margin:0;font-size:16px;color:#1f4e5f;", fpa_screen("scn_log_title")),
      shiny::tags$span(style = "color:#5c6b73;font-size:13px;", fpa_screen("scn_log_count", n))
    ),
    if (!n) shiny::tags$p(style = "color:#5c6b73;margin:0 0 0.4rem;", fpa_screen("scn_log_empty")),
    if (n) shiny::tagList(
      shiny::tags$div(class = "fpa-scn-chart", bars),
      shiny::tags$p(style = "color:#3d4c54;font-size:0.9rem;line-height:1.4;margin:0.35rem 0 0.5rem;", fpa_screen("scn_chart")),
      shiny::tags$div(
        style = "border:1px solid #d6e1e5;border-radius:8px;overflow-x:auto;margin:0 0 0.4rem;",
        shiny::tags$table(
          style = "width:max-content;min-width:100%;border-collapse:collapse;font-size:13px;",
          shiny::tags$thead(shiny::tags$tr(
            shiny::tags$th(style = paste0(head_style, "text-align:left;"), fpa_screen("scn_h_time")),
            shiny::tags$th(style = paste0(head_style, "text-align:left;"), fpa_screen("scn_h_moves")),
            shiny::tags$th(style = head_style, fpa_screen("scn_h_cash")),
            shiny::tags$th(style = head_style, fpa_screen("scn_h_gap")),
            shiny::tags$th(style = head_style, fpa_screen("scn_h_oi_fy")),
            shiny::tags$th(style = head_style, fpa_screen("scn_h_gap")),
            shiny::tags$th(style = head_style, oi_last_head),
            shiny::tags$th(style = head_style, fpa_screen("scn_h_gap"))
          )),
          shiny::tags$tbody(rows)
        )
      )
    ),
    shiny::tags$p(style = "color:#5c6b73;font-size:12.5px;margin:0;", fpa_screen("scn_log_cap")),
    if (n) shiny::tags$p(style = "color:#1f4e5f;font-size:13px;margin:0.2rem 0 0;", fpa_screen("scn_trace_hint")),
    if (n) shiny::tagList(
      shiny::tags$h3(style = "margin:1.1rem 0 0.2rem;font-size:16px;color:#1f4e5f;", fpa_screen("scn_web_title")),
      shiny::tags$p(style = "color:#3d4c54;font-size:0.9rem;line-height:1.4;margin:0 0 0.5rem;", fpa_screen("scn_web_note")),
      shiny::tags$div(
        class = "fpa-scn-webs-wrap",
        shiny::tags$div(
          class = "fpa-scn-webs",
          lapply(chrono, function(i) {
            fpa_shiny_scn_web(entries[[i]], fpa_shiny_scn_axes(entries[[i]], lv), open_ix = i)
          })
        )
      )
    )
  )
}

fpa_shiny_pair_r <- function(x, y) {
  ok <- is.finite(x) & is.finite(y)
  if (sum(ok) < 3L) return(NA_real_)
  stats::cor(x[ok], y[ok])
}

fpa_shiny_r_txt <- function(r) {
  if (!is.finite(r)) return("n/a")
  format(round(r, 2), nsmall = 2)
}

fpa_shiny_scatter_panel <- function(x, y, col, xlab, ylab, main) {
  ok <- is.finite(x) & is.finite(y)
  plot(x, y, pch = 16, col = col, xlab = xlab, ylab = ylab, main = main)
  if (sum(ok) >= 3L && stats::sd(x[ok]) > 1e-12) {
    fit <- stats::lm(y[ok] ~ x[ok])
    abline(fit, col = "#0f2f3a", lwd = 1.4)
  }
}

#' Two sentences: what the two clouds are, and what decision they support.
fpa_shiny_scatter_note <- function(g, al) {
  line <- fpa_shiny_line_name(g$target_line)
  r_res <- fpa_shiny_pair_r(al$driver_resid, al$target_resid)
  r_txt <- fpa_shiny_r_txt(r_res)
  identity <- identical(as.character(g$relation %||% ""), "part_whole") ||
    identical(as.character(g$tier %||% ""), "mechanism") ||
    identical(as.character(g$flag %||% ""), "identite")
  if (identity) {
    return(paste0(
      fpa_screen("loc_scatter_full"),
      g$series_name, " et ", line, fpa_screen("loc_scatter_compose"),
      fpa_screen("loc_scatter_resid"), r_txt, "). ",
      fpa_screen("loc_not_discovered")
    ))
  }
  holds <- is.finite(r_res) && abs(r_res) >= 0.30
  paste0(
    fpa_screen("loc_scatter_resid_long"),
    r_txt, "). ",
    "Conclusion : ",
    if (holds) {
      fpa_screen("loc_link_survives")
    } else {
      fpa_screen("loc_link_calendar")
    }
  )
}

#' Unit-free residual. Correlation does not depend on euros versus degrees.
fpa_shiny_z <- function(x) {
  x <- suppressWarnings(as.numeric(x))
  ok <- is.finite(x)
  if (sum(ok) < 2L) return(x)
  s <- stats::sd(x[ok])
  if (!is.finite(s) || s < 1e-12) return(x * 0)
  (x - mean(x[ok])) / s
}

#' Plot range over the finite values only. NULL when a chart would have no scale.
fpa_shiny_span <- function(...) {
  vals <- unlist(list(...), use.names = FALSE)
  vals <- suppressWarnings(as.numeric(vals))
  vals <- vals[is.finite(vals)]
  if (!length(vals)) return(NULL)
  rng <- range(vals)
  if (rng[[1]] == rng[[2]]) rng <- rng + c(-0.5, 0.5)
  rng
}

fpa_shiny_flag <- function(x) {
  if (is.logical(x)) return(isTRUE(x))
  tolower(as.character(x)) %in% c("true", "t", "1")
}

fpa_shiny_num <- function(x) {
  if (is.null(x) || !length(x)) return(NA_real_)
  out <- suppressWarnings(as.numeric(x[[1]]))
  if (!length(out) || is.na(out)) NA_real_ else out
}

#' Lags worth a click: the engine peak, same-month, and any other shift that clears the bar.
fpa_shiny_shift_offers <- function(g, prof) {
  peak <- fpa_shiny_num(g$causal_lag)
  avail <- fpa_shiny_num(g$availability_lag_days)
  empty_lab <- paste0(fpa_screen("drv_lag_none"), " · ", fpa_screen("drv_engine_pick"))
  if (!is.finite(peak)) {
    return(list(choices = stats::setNames("none", empty_lab), selected = "none"))
  }
  if (is.null(prof) || !nrow(prof) || !"lag" %in% names(prof)) {
    return(list(
      choices = stats::setNames(
        as.character(as.integer(peak)),
        fpa_shiny_lag_label(peak, NA, peak, avail, TRUE, FALSE)
      ),
      selected = as.character(as.integer(peak))
    ))
  }
  prof$lag <- as.integer(prof$lag)
  prof$r <- as.numeric(prof$r)
  sig <- if ("significant" %in% names(prof)) vapply(prof$significant, fpa_shiny_flag, logical(1)) else rep(FALSE, nrow(prof))
  keep <- rep(FALSE, nrow(prof))
  if (is.finite(peak)) keep <- keep | prof$lag == as.integer(peak)
  keep <- keep | prof$lag == 0L | sig
  if (!any(keep)) keep <- prof$lag == 0L
  rows <- prof[keep, , drop = FALSE]
  rows <- rows[order(rows$lag), , drop = FALSE]
  labels <- vapply(seq_len(nrow(rows)), function(i) {
    h <- rows$lag[[i]]
    fpa_shiny_lag_label(
      h, rows$r[[i]], peak, avail,
      is.finite(peak) && h == as.integer(peak),
      is.finite(peak) && h == as.integer(peak) && identical(as.character(g$lag_status), "refused_reverse_causality")
    )
  }, character(1))
  values <- as.character(rows$lag)
  selected <- if (is.finite(peak) && as.character(as.integer(peak)) %in% values) {
    as.character(as.integer(peak))
  } else {
    values[[1]]
  }
  list(choices = stats::setNames(values, labels), selected = selected, rows = rows)
}

fpa_shiny_lag_label <- function(lag, r, peak, avail, recommended, refused) {
  lag <- as.integer(lag)
  lag_txt <- if (lag == 0L) fpa_screen("drv_lag_same") else if (lag > 0L) paste0("+", lag, " mois") else paste0(lag, " mois")
  bits <- lag_txt
  if (is.finite(r)) bits <- paste0(bits, fpa_screen("loc_correlation"), fpa_shiny_fr_num(r, 2))
  if (is.finite(avail)) {
    horizon <- as.numeric(lag) * 30 - avail
    bits <- paste0(
      bits, ", ",
      if (horizon > 0) fpa_screen("drv_lag_horizon", round(horizon)) else fpa_screen("drv_lag_explain")
    )
  }
  if (refused) bits <- paste0(bits, " · ", fpa_screen("drv_lag_refused"))
  if (recommended) bits <- paste0(bits, " · ", fpa_screen("drv_engine_pick"))
  bits
}

#' Critical |r| at the partial-correlation degrees of freedom (n - 3).
fpa_shiny_r_crit <- function(df) {
  df <- as.integer(df)
  if (!is.finite(df) || df < 1L) return(NA_real_)
  tc <- stats::qt(0.975, df)
  sqrt(tc^2 / (tc^2 + df))
}

.fpa_series_meta <- new.env(parent = emptyenv())

#' Names, kinds and formulas the wizard declared (config driver_bindings).
#' Without that block every lookup below falls back to the column name.
fpa_shiny_set_series_meta <- function(config) {
  meta <- tryCatch(fpa_driver_bound_meta(config), error = function(e) NULL)
  assign("labels", if (is.null(meta)) character() else meta$labels, envir = .fpa_series_meta)
  assign("formula", if (is.null(meta)) character() else meta$formula, envir = .fpa_series_meta)
  assign("kind", if (is.null(meta)) character() else meta$kind, envir = .fpa_series_meta)
  invisible(meta)
}

fpa_shiny_series_meta <- function(field, name) {
  vals <- get0(field, envir = .fpa_series_meta, inherits = FALSE, ifnotfound = character())
  name <- as.character(name)
  if (!length(vals) || !name %in% names(vals)) return(NA_character_)
  unname(vals[[name]])
}

fpa_shiny_is_volume <- function(name) {
  kind <- fpa_shiny_series_meta("kind", name)
  if (!is.na(kind)) return(identical(kind, "volume"))
  grepl("nuitee|volume|couvert|booking|reservation|quantite", fpa_fold_label(name))
}

#' TRUE when the series belongs to a formula of the forecast.
fpa_shiny_in_formula <- function(g) {
  if ("state_configured" %in% names(g)) return(isTRUE(as.logical(g$state_configured[[1]])))
  if (as.character(g$relation %||% "") %in% c("part_whole", "derived") ||
      identical(as.character(g$tier), "mechanism")) {
    return(TRUE)
  }
  declared <- fpa_shiny_series_meta("formula", g$series_name)
  !is.na(declared) && nzchar(declared)
}

fpa_shiny_state_flag <- function(g, col) {
  col %in% names(g) && isTRUE(as.logical(g[[col]][[1]]))
}

fpa_shiny_state_label <- function(g) {
  if (!"state_label" %in% names(g)) return("")
  x <- as.character(g$state_label[[1]] %||% "")
  if (is.na(x)) "" else x
}

fpa_shiny_bottom_label <- function(name) {
  declared <- fpa_shiny_series_meta("labels", name)
  if (!is.na(declared) && nzchar(declared)) return(declared)
  labels <- c(
    capacite = fpa_screen("loc_capacity"),
    taux_utilisation = "taux d'utilisation",
    tarif = "tarif",
    nuitees_vendues = fpa_screen("loc_nights_sold"),
    effectif = "effectif",
    cout_moyen = "coût moyen",
    temperature_c = fpa_screen("loc_temperature"),
    precipitations_mm = fpa_screen("loc_precip")
  )
  hit <- unname(labels[as.character(name)])
  if (!length(hit) || is.na(hit) || !nzchar(hit)) as.character(name) else hit
}

fpa_shiny_bottom_control_phrase <- function(name) {
  phrases <- c(
    nuitees_vendues = fpa_screen("loc_the_nights"),
    tarif = "le tarif"
  )
  hit <- unname(phrases[as.character(name)])
  if (!length(hit) || is.na(hit) || !nzchar(hit)) fpa_shiny_bottom_label(name) else hit
}

#' fpa_screen("loc_of_nights"), "du tarif": the control as it reads after "l'effet".
fpa_shiny_control_de <- function(name) {
  hit <- unname(c(nuitees_vendues = fpa_screen("loc_of_nights"), tarif = "du tarif")[as.character(name)])
  if (length(hit) && !is.na(hit)) return(hit)
  paste("de", fpa_shiny_bottom_label(name))
}

fpa_shiny_when <- function(x) {
  x <- as.character(x %||% "")
  if (!nzchar(x)) return("")
  sub("T", " ", substr(x, 1L, 16L), fixed = TRUE)
}

fpa_shiny_fr_num <- function(x, digits) {
  x <- fpa_shiny_num(x)
  if (!is.finite(x)) return("—")
  formatC(x, format = "f", digits = digits, decimal.mark = ",")
}

fpa_shiny_bottom_sentence <- function(g) {
  if (is.null(g) || !nrow(g)) return("")
  name <- fpa_shiny_bottom_label(g$series_name[[1]])
  if (!"bottom_line" %in% names(g)) return(fpa_screen("drv_bottom_missing", name))
  line <- as.character(g$bottom_line[[1]] %||% "")
  if (!identical(line, "OI")) return(fpa_screen("drv_bottom_missing", name))
  n <- suppressWarnings(as.integer(fpa_shiny_num(g$bottom_n)))
  if (!is.finite(fpa_shiny_num(g$bottom_r))) {
    return(fpa_screen("drv_bottom_flat_full", name, n, g$bottom_from[[1]], g$bottom_to[[1]]))
  }
  lag <- fpa_shiny_num(g$bottom_lag)
  lag_txt <- if (!is.finite(lag) || lag == 0) {
    fpa_screen("drv_bottom_same")
  } else if (lag < 0) {
    fpa_screen("drv_bottom_follow", abs(as.integer(lag)))
  } else {
    fpa_screen("drv_bottom_lead", as.integer(lag))
  }
  r_kind <- fpa_driver_map_edge_kind(g$bottom_r, g$bottom_n, NA_real_, if ("bottom_sig" %in% names(g)) g$bottom_sig else NA, "")
  if (identical(r_kind$kind, "noise")) {
    return(paste(
      fpa_screen("drv_bottom_head", name, n, g$bottom_from[[1]], g$bottom_to[[1]]),
      fpa_screen("drv_map_noise_full", fpa_shiny_fr_num(g$bottom_r, 2), as.integer(n))
    ))
  }
  r_txt <- fpa_shiny_fr_num(g$bottom_r, 2)
  partial <- if ("bottom_partial" %in% names(g)) fpa_shiny_num(g$bottom_partial) else NA_real_
  ctl <- if ("bottom_control" %in% names(g)) as.character(g$bottom_control[[1]] %||% "") else ""
  partial_txt <- if (is.finite(partial) && nzchar(ctl)) {
    fpa_screen("drv_bottom_partial", fpa_shiny_control_de(ctl), fpa_shiny_fr_num(partial, 2))
  } else {
    fpa_screen("drv_bottom_nopartial")
  }
  rank <- fpa_shiny_num(g$bottom_rank)
  rank_txt <- fpa_shiny_fr_num(rank * 100, 1)
  rank_sentence <- if (is.finite(rank) && rank <= 0.05) {
    fpa_screen("drv_bottom_rank_in", rank_txt)
  } else {
    fpa_screen("drv_bottom_rank_out", rank_txt)
  }
  bits <- c(
    fpa_screen("drv_bottom_head", name, n, g$bottom_from[[1]], g$bottom_to[[1]]),
    fpa_screen("drv_bottom_r", r_txt),
    lag_txt,
    partial_txt,
    rank_sentence
  )
  eur <- fpa_shiny_num(g$bottom_eur10)
  if (is.finite(eur)) {
    bits <- c(bits, fpa_screen(
      "drv_bottom_eur",
      format(round(eur), big.mark = " ", scientific = FALSE, trim = TRUE)
    ))
  }
  paste(c(bits, fpa_screen("drv_bottom_not_rule")), collapse = " ")
}

fpa_shiny_line_sentence <- function(g) {
  if (is.null(g) || !nrow(g) || !"line_n" %in% names(g)) return(fpa_screen("drv_line_missing"))
  n <- fpa_shiny_num(g$line_n)
  if (!is.finite(n)) return(fpa_screen("drv_line_missing"))
  name <- fpa_shiny_bottom_label(g$series_name[[1]])
  line <- tolower(fpa_shiny_line_name(g$target_line))
  head <- fpa_screen("drv_line_head", name, line, as.integer(n), g$line_from[[1]], g$line_to[[1]])
  r <- fpa_shiny_num(g$evidence_r)
  if (!is.finite(r)) return(paste(head, fpa_screen("drv_line_flat")))
  kind <- fpa_driver_map_edge_kind(
    r, g$n, if ("evidence_r_crit" %in% names(g)) g$evidence_r_crit else NA, if ("evidence_sig" %in% names(g)) g$evidence_sig else NA,
    g$target_line, if ("series_name" %in% names(g)) g$series_name else ""
  )
  if (identical(kind$kind, "noise")) {
    return(paste(head, fpa_screen("drv_map_noise_full", fpa_shiny_fr_num(r, 2), as.integer(fpa_shiny_num(g$n)))))
  }
  if ("relation" %in% names(g) && as.character(g$relation[[1]]) %in% c("part_whole", "derived")) {
    return(paste(head, fpa_screen("drv_line_mech_card", fpa_shiny_fr_num(r, 2))))
  }
  pay_key <- if (identical(kind$kind, "pay_factor")) {
    "drv_map_pay_factor_full"
  } else if (kind$kind %in% c("pay_down", "pay_up")) {
    paste0("drv_map_", kind$kind, "_full")
  } else {
    ""
  }
  pay_bit <- if (nzchar(pay_key)) fpa_screen(pay_key) else ""
  lag <- fpa_shiny_num(g$causal_lag)
  lag_txt <- if (!is.finite(lag) || lag == 0) {
    fpa_screen("drv_bottom_same")
  } else if (lag < 0) {
    fpa_screen("drv_line_follow", abs(as.integer(lag)))
  } else {
    fpa_screen("drv_line_lead", as.integer(lag))
  }
  rank <- fpa_shiny_num(g$permutation_rank)
  rank_txt <- fpa_shiny_fr_num(rank * 100, 1)
  bits <- c(
    head,
    if (nzchar(pay_bit)) pay_bit else fpa_screen("drv_bottom_r", fpa_shiny_fr_num(r, 2)),
    lag_txt,
    if (is.finite(rank) && rank <= 0.05) fpa_screen("drv_bottom_rank_in", rank_txt) else fpa_screen("drv_bottom_rank_out", rank_txt)
  )
  paste(bits, collapse = " ")
}

fpa_shiny_nights_sentence <- function(grades) {
  if (is.null(grades) || !nrow(grades) || !"bottom_r" %in% names(grades)) return(fpa_screen("drv_nights"))
  hit <- which(vapply(grades$series_name, fpa_shiny_is_volume, logical(1)))
  if (!length(hit)) return(fpa_screen("drv_nights"))
  fpa_shiny_bottom_sentence(grades[hit[[1]], , drop = FALSE])
}

fpa_shiny_bottom_table <- function(grades, selected_id = "") {
  fpa_shiny_goal_table(grades, selected_id, "oi")
}

#' One table per goal, same columns. "line" reads the test against the line the
#' series feeds (chiffre d'affaires, masse salariale); "oi" reads the test
#' against operating income.
fpa_shiny_goal_fields <- function(goal) {
  if (identical(goal, "line")) {
    return(list(
      n = "line_n", lag = "causal_lag", r = "evidence_r", partial = "independence_r",
      rank = "permutation_rank", from = "line_from", to = "line_to",
      title = "drv_line_title", method = "drv_line_method"
    ))
  }
  list(
    n = "bottom_n", lag = "bottom_lag", r = "bottom_r", partial = "bottom_partial",
    rank = "bottom_rank", from = "bottom_from", to = "bottom_to",
    title = "drv_bottom_title", method = "drv_bottom_method"
  )
}

fpa_shiny_goal_table <- function(grades, selected_id = "", goal = c("oi", "line")) {
  goal <- match.arg(goal)
  f <- fpa_shiny_goal_fields(goal)
  is_line <- identical(goal, "line")
  title <- shiny::tags$h3(
    style = "margin:1.1rem 0 0.35rem;font-size:1.05rem;color:#0f2f3a;",
    fpa_screen(f$title)
  )
  method <- shiny::tags$details(
    class = "fpa-drv-fold-lite",
    shiny::tags$summary(fpa_screen("drv_method_fold")),
    shiny::tags$p(
      style = "color:#3d4c54;font-size:0.9rem;line-height:1.45;margin:0.3rem 0 0.4rem;",
      fpa_screen(f$method)
    ),
    shiny::tags$p(
      style = "color:#3d4c54;font-size:0.9rem;line-height:1.45;margin:0 0 0.4rem;",
      fpa_screen("drv_goal_no_euro")
    )
  )
  if (is.null(grades) || !nrow(grades) || !f$n %in% names(grades)) {
    return(shiny::tagList(title, method))
  }
  rows <- if (is_line) {
    grades[is.finite(suppressWarnings(as.numeric(grades[[f$n]]))), , drop = FALSE]
  } else {
    grades[as.character(grades$bottom_line) == "OI", , drop = FALSE]
  }
  if (!nrow(rows)) return(shiny::tagList(title, method))
  val <- function(g, key) fpa_shiny_num(g[[f[[key]]]])
  mech <- if ("relation" %in% names(rows)) as.character(rows$relation) %in% c("part_whole", "derived") else rep(FALSE, nrow(rows))
  cell_pad <- "padding:0.45rem 0.7rem;border-bottom:1px solid #d5dde0;font-variant-numeric:tabular-nums;white-space:nowrap;"
  head_base <- "padding:0.45rem 0.7rem;font-weight:600;white-space:nowrap;font-variant-numeric:tabular-nums;"
  headers <- list(
    list(lab = fpa_drv_term("serie", "Série"), align = "left", width = "22%"),
    list(lab = fpa_screen("drv_h_against"), align = "left", width = "20%"),
    list(lab = fpa_drv_term("mois", "Mois"), align = "right", width = "9%"),
    list(lab = fpa_drv_term("lag", "Décalage"), align = "right", width = "12%"),
    list(lab = fpa_drv_term("r", "r"), align = "right", width = "13%"),
    list(lab = fpa_drv_term("partial", "r partiel"), align = "right", width = "12%"),
    list(lab = fpa_drv_term("rank", "Rang"), align = "right", width = "12%")
  )
  header <- shiny::tags$tr(lapply(headers, function(h) {
    shiny::tags$th(style = paste0(head_base, "text-align:", h$align, ";"), h$lab)
  }))
  cols <- shiny::tags$colgroup(lapply(headers, function(h) shiny::tags$col(style = paste0("width:", h$width, ";"))))
  num_style <- paste0(cell_pad, "text-align:right;")
  name_style <- paste0(cell_pad, "text-align:left;font-variant-numeric:normal;white-space:normal;")
  body <- lapply(seq_len(nrow(rows)), function(i) {
    g <- rows[i, , drop = FALSE]
    on <- identical(as.character(g$series_id), as.character(selected_id))
    r <- val(g, "r")
    lag <- val(g, "lag")
    lag_txt <- if (!is.finite(lag)) "—" else if (lag > 0) paste0("+", as.integer(lag)) else as.character(as.integer(lag))
    rank <- val(g, "rank")
    rank_col <- if (is.finite(rank) && rank <= 0.05) "#1f4e5f" else "#5c6b73"
    r_col <- if (is.finite(r) && r < 0) "#8c3a3a" else "#1a2b32"
    n_g <- val(g, "n")
    shiny::tags$tr(
      style = if (on) "background:#e7eef0;" else NULL,
      shiny::tags$td(
        style = name_style,
        fpa_shiny_bottom_label(g$series_name),
        if (is_line && mech[[i]]) shiny::tags$span(
          style = "display:block;font-size:11px;color:#5c6b73;",
          fpa_screen("drv_mech_tag")
        )
      ),
      shiny::tags$td(style = name_style, fpa_shiny_line_name(if (is_line) g$target_line else "OI")),
      shiny::tags$td(style = num_style, if (is.finite(n_g)) as.integer(n_g) else "—"),
      shiny::tags$td(style = num_style, if (is.finite(r)) lag_txt else "—"),
      shiny::tags$td(
        style = paste0(num_style, "color:", r_col, ";", if (!is.finite(r)) "white-space:normal;" else ""),
        if (is.finite(r)) fpa_shiny_fr_num(r, 2) else fpa_screen("drv_bottom_flat_cell")
      ),
      shiny::tags$td(style = num_style, if (is.finite(r)) fpa_shiny_fr_num(val(g, "partial"), 2) else "—"),
      shiny::tags$td(
        style = paste0(num_style, "font-weight:700;color:", rank_col, ";"),
        if (is.finite(rank)) paste0(fpa_shiny_fr_num(rank * 100, 1), " %") else "—"
      )
    )
  })
  n <- nrow(rows)
  bar <- fpa_shiny_fr_num(0.05 / n * 100, 1)
  ranks <- suppressWarnings(as.numeric(rows[[f$rank]]))
  if (is_line) {
    ranks[mech] <- NA_real_
    if ("lag_status" %in% names(rows)) ranks[as.character(rows$lag_status) == "refused_reverse_causality"] <- NA_real_
  }
  clear <- which(is.finite(ranks) & ranks <= 0.05)
  pass_txt <- if (!length(clear)) {
    fpa_screen("drv_bottom_none_pass")
  } else {
    fpa_screen("drv_bottom_pass_list", paste(vapply(clear, function(i) {
      fpa_screen(
        "drv_bottom_one_pass",
        fpa_shiny_bottom_label(rows$series_name[[i]]),
        fpa_shiny_fr_num(ranks[[i]] * 100, 1)
      )
    }, character(1)), collapse = ", "))
  }
  family <- which(is.finite(ranks) & ranks <= 0.05 / n)
  family_txt <- if (!length(family)) {
    fpa_screen("drv_bottom_family_none")
  } else {
    who <- paste(vapply(family, function(i) fpa_shiny_bottom_label(rows$series_name[[i]]), character(1)), collapse = ", ")
    fpa_screen(
      if (length(family) > 1L) "drv_bottom_family_pass_n" else "drv_bottom_family_pass",
      paste0(toupper(substr(who, 1, 1)), substr(who, 2, nchar(who)))
    )
  }
  if (is_line && "lag_status" %in% names(rows)) {
    back <- which(as.character(rows$lag_status) == "refused_reverse_causality" & !mech)
    if (length(back)) {
      family_txt <- paste(family_txt, fpa_screen(
        "drv_line_reverse",
        paste(vapply(back, function(i) fpa_shiny_bottom_label(rows$series_name[[i]]), character(1)), collapse = ", ")
      ))
    }
  }
  capped <- fpa_shiny_cap_rows(body, 8L)
  shiny::tagList(
    title,
    method,
    shiny::tags$div(
      class = "fpa-cap",
      shiny::tags$table(
        style = "width:100%;border-collapse:collapse;table-layout:fixed;margin-bottom:0.45rem;font-size:13px;",
        cols,
        shiny::tags$thead(style = "background:#1f4e5f;color:#fff;", header),
        shiny::tags$tbody(capped$rows)
      ),
      capped$toggle
    ),
    shiny::tags$p(
      style = "color:#1a2b32;font-size:0.92rem;line-height:1.45;margin:0 0 0.3rem;",
      pass_txt, " ", family_txt
    ),
    shiny::tags$p(
      style = "color:#3d4c54;font-size:0.9rem;line-height:1.4;margin:0;",
      fpa_screen("drv_bottom_bar", n, bar),
      if (is_line && any(mech)) paste0(" ", fpa_screen("drv_line_mech"))
    )
  )
}

fpa_shiny_confirm_read <- function(config_path) {
  dest <- file.path(dirname(as.character(config_path %||% "")), "config", "driver-confirmations.json")
  if (!nzchar(config_path %||% "") || !file.exists(dest)) return(list())
  existing <- tryCatch(jsonlite::fromJSON(dest, simplifyVector = FALSE), error = function(e) list())
  if (!is.list(existing)) return(list())
  if (!is.null(existing$series_id)) existing <- list(existing)
  existing
}

fpa_shiny_saved_ids <- function(saved) {
  if (!length(saved)) return(character())
  vapply(saved, function(item) as.character(item$series_id %||% ""), character(1))
}

#' A saved Keep promotes a watched series to confirmed. A saved Reject parks it.
#' A mechanism stays a mechanism. The engine file is not rewritten.
fpa_shiny_apply_confirmations <- function(grades, saved) {
  if (is.null(grades) || !nrow(grades)) return(grades)
  grades$saved_verdict <- ""
  if (!length(saved)) return(grades)
  for (item in saved) {
    sid <- as.character(item$series_id %||% "")
    hit <- which(as.character(grades$series_id) == sid)
    if (!length(hit)) next
    v <- as.character(item$verdict %||% "")
    grades$saved_verdict[hit[[1]]] <- v
    tier <- as.character(grades$tier[hit[[1]]] %||% "")
    if (identical(tier, "mechanism")) next
    if (identical(v, "Keep")) grades$tier[hit[[1]]] <- "confirmed"
    if (identical(v, "Reject")) grades$tier[hit[[1]]] <- "watch"
  }
  grades
}

fpa_shiny_progress_path <- function(config_path) {
  file.path(dirname(as.character(config_path %||% "")), "config", "structure-progress.json")
}

fpa_shiny_progress_read <- function(config_path) {
  empty <- list(map_read = FALSE, map_read_at = "")
  if (!nzchar(config_path %||% "") || !file.exists(fpa_shiny_progress_path(config_path))) return(empty)
  got <- tryCatch(jsonlite::fromJSON(fpa_shiny_progress_path(config_path), simplifyVector = FALSE), error = function(e) list())
  if (!is.list(got)) return(empty)
  list(map_read = isTRUE(got$map_read), map_read_at = as.character(got$map_read_at %||% ""))
}

fpa_shiny_check_svg <- function(size = 16) {
  shiny::HTML(sprintf(
    '<svg viewBox="0 0 16 16" width="%s" height="%s" aria-hidden="true"><path d="M3.2 8.2 6.4 11.4 12.8 4.6" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>',
    as.integer(size), as.integer(size)
  ))
}

#' A word with a dotted underline; the shared tooltip script reads data-tip.
fpa_drv_term <- function(key, label = NULL) {
  tip <- fpa_screen(paste0("drv_tip_", key))
  lab <- if (is.null(label)) fpa_screen(paste0("drv_term_", key)) else label
  if (!nzchar(tip)) return(lab)
  shiny::tags$span(class = "fpa-term", tabindex = "0", `data-tip` = tip, lab)
}

fpa_drv_tier_tip <- function(tier) {
  key <- unname(c(mechanism = "mecanisme", confirmed = "confirme", watch = "veille")[as.character(tier)])
  if (!length(key) || is.na(key)) return(NULL)
  fpa_screen(paste0("drv_tip_", key))
}

fpa_drv_glossary <- function(open = FALSE) {
  items <- lapply(fpa_drv_glossary_keys, function(k) {
    shiny::tagList(
      shiny::tags$dt(fpa_screen(paste0("drv_term_", k))),
      shiny::tags$dd(fpa_screen(paste0("drv_tip_", k)))
    )
  })
  shiny::tags$details(
    id = "drv-gloss", class = "fpa-drv-gloss",
    open = if (isTRUE(open)) "open" else NULL,
    shiny::tags$summary(fpa_screen("drv_gloss_btn")),
    shiny::tags$p(fpa_screen("drv_gloss_lead")),
    shiny::tags$dl(items)
  )
}

#' Rows past `cap` stay in the DOM but hidden; one button shows or hides them.
#' The wrapper must carry class fpa-cap for the CSS to apply.
fpa_shiny_cap_rows <- function(rows, cap = 8L) {
  n <- length(rows)
  if (n <= cap) return(list(rows = rows, toggle = NULL, n_hidden = 0L))
  rows <- lapply(seq_len(n), function(i) {
    if (i <= cap) return(rows[[i]])
    shiny::tagAppendAttributes(rows[[i]], class = "fpa-cap-hidden")
  })
  toggle <- shiny::tags$button(
    type = "button", class = "fpa-cap-btn",
    onclick = "var w=this.closest('.fpa-cap'); if(w) w.classList.toggle('is-all');",
    shiny::tags$span(class = "fpa-cap-more", fpa_screen("drv_cap_more", n - cap)),
    shiny::tags$span(class = "fpa-cap-less", fpa_screen("drv_cap_less"))
  )
  list(rows = rows, toggle = toggle, n_hidden = n - cap)
}

#' Top of Drivers: what a driver is, the three families as tiles, and the progress.
fpa_shiny_driver_hero <- function(grades, formulas, n_saved, n_all) {
  tiles <- NULL
  if (!is.null(grades) && nrow(grades) && "tier" %in% names(grades)) {
    tile <- function(tier, title_key, sub_key, term_key) {
      sub <- grades[as.character(grades$tier) == tier, , drop = FALSE]
      chips <- if (nrow(sub)) {
        lapply(seq_len(nrow(sub)), function(i) {
          safe <- gsub("[^A-Za-z0-9_-]", "", as.character(sub$series_id[[i]]))
          shiny::tags$button(
            type = "button", class = "fpa-hero-chip",
            onclick = sprintf(
              "var d=document.getElementById('drv-more'); if(d) d.open=true; Shiny.setInputValue('drv_pick', '%s', {priority:'event'});",
              safe
            ),
            fpa_shiny_bottom_label(sub$series_name[[i]])
          )
        })
      } else {
        shiny::tags$span(class = "fpa-hero-none", fpa_screen("drv_tile_none"))
      }
      shiny::tags$div(
        class = paste("fpa-hero-tile", paste0("is-", tier)),
        shiny::tags$div(
          class = "fpa-hero-tile-head",
          shiny::tags$span(class = "fpa-hero-n", as.character(nrow(sub))),
          shiny::tags$span(class = "fpa-hero-t", fpa_screen(title_key)),
          shiny::tags$span(class = "fpa-hero-tag", fpa_drv_term(term_key))
        ),
        shiny::tags$p(fpa_screen(sub_key)),
        shiny::tags$div(class = "fpa-hero-chips", chips)
      )
    }
    tiles <- shiny::tags$div(
      class = "fpa-hero-tiles",
      tile("mechanism", "drv_tile_mech", "drv_tile_mech_sub", "mecanisme"),
      tile("confirmed", "drv_tile_conf", "drv_tile_conf_sub", "confirme"),
      tile("watch", "drv_tile_watch", "drv_tile_watch_sub", "veille")
    )
  }
  lead <- fpa_shiny_driver_lead(grades, formulas)
  progress <- if (n_all > 0L && n_saved >= n_all) {
    fpa_screen("path_drv_all")
  } else if (n_all > 0L && identical(as.integer(n_saved), 1L)) {
    fpa_screen("path_drv_progress_one", n_saved, n_all)
  } else if (n_all > 0L) {
    fpa_screen("path_drv_progress", n_saved, n_all)
  } else {
    ""
  }
  shiny::tags$section(
    class = "fpa-path fpa-drv-hero",
    shiny::tags$p(class = "fpa-path-kicker", fpa_screen("path_drv_kicker")),
    shiny::tags$h2(fpa_screen("drv_hero_title")),
    shiny::tags$p(fpa_screen("drv_hero_intro")),
    tiles,
    lead,
    if (nzchar(progress)) shiny::tags$div(
      class = "fpa-hero-progress",
      shiny::tags$span(class = "fpa-hero-progress-txt", progress),
      if (n_all > 0L && n_saved < n_all) shiny::tags$div(
        class = "fpa-path-bar",
        shiny::tags$span(style = sprintf("width:%.1f%%;", 100 * n_saved / n_all))
      )
    ),
    shiny::tags$div(
      class = "fpa-path-actions",
      shiny::tags$button(
        type = "button", class = "fpa-path-btn",
        onclick = paste0(
          "var d=document.getElementById('drv-more'); if(d){ d.open=true; d.scrollIntoView({block:'start',behavior:'smooth'}); }",
          " Shiny.setInputValue('drv_open_map', Date.now(), {priority:'event'});"
        ),
        fpa_screen("drv_open_map")
      ),
      shiny::tags$button(
        type = "button", class = "fpa-path-btn is-quiet",
        onclick = "var g=document.getElementById('drv-gloss'); if(g){ g.open=!g.open; if(g.open) g.scrollIntoView({block:'nearest',behavior:'smooth'}); }",
        fpa_screen("drv_gloss_btn")
      ),
      shiny::tags$button(
        type = "button", class = "fpa-path-btn is-quiet",
        onclick = "var a=document.querySelector('#main_nav a.nav-link[data-value=Cartographie]'); if(a) a.click();",
        fpa_screen("path_goto_map")
      )
    ),
    fpa_drv_glossary()
  )
}

fpa_shiny_verdict_fr <- function(verdict) {
  key <- switch(
    as.character(verdict),
    Keep = "drv_v_keep",
    Optional = "drv_v_optional",
    Reject = "drv_v_reject",
    "Needs more history" = "drv_v_short",
    NULL
  )
  if (is.null(key)) as.character(verdict) else fpa_screen(key)
}

fpa_shiny_bottom_chip <- function(g) {
  r <- fpa_shiny_num(g$bottom_r)
  if (!is.finite(r)) return(fpa_screen("drv_bottom_flat_cell"))
  paste0(
    "r ", fpa_shiny_fr_num(r, 2),
    " · rang ", fpa_shiny_fr_num(fpa_shiny_num(g$bottom_rank) * 100, 1), " %"
  )
}

fpa_shiny_line_chip <- function(g) {
  line <- shiny::tags$div(style = "color:#5c6b73;font-size:12px;", fpa_shiny_line_name(g$target_line))
  r <- fpa_shiny_num(g$evidence_r)
  mech <- "relation" %in% names(g) && as.character(g$relation[[1]]) %in% c("part_whole", "derived")
  body <- if (!is.finite(r)) {
    fpa_screen("drv_bottom_flat_cell")
  } else if (mech) {
    paste0("r ", fpa_shiny_fr_num(r, 2), " · ", fpa_screen("drv_mech_expected"))
  } else if (identical(as.character(g$lag_status[[1]] %||% ""), "refused_reverse_causality")) {
    paste0("r ", fpa_shiny_fr_num(r, 2), " · ", fpa_screen("drv_chip_reverse"))
  } else {
    paste0("r ", fpa_shiny_fr_num(r, 2), " · rang ", fpa_shiny_fr_num(fpa_shiny_num(g$permutation_rank) * 100, 1), " %")
  }
  shiny::tagList(line, shiny::tags$div(body))
}

fpa_shiny_map_gap <- function(absent) {
  if (is.null(absent) || !nrow(absent)) return("")
  if (nrow(absent) == 1L) return(fpa_screen("path_map_gap", as.character(absent$title[[1]])))
  fpa_screen("path_map_gaps", as.integer(nrow(absent)))
}

fpa_shiny_structure_guide <- function(where, map_done, map_at, n_saved, n_all, map_gap = "") {
  drv_done <- n_all > 0L && n_saved >= n_all
  blocked <- nzchar(as.character(map_gap %||% ""))
  map_clear <- isTRUE(map_done) && !blocked
  step <- function(n, label, detail, state) {
    shiny::tags$li(
      class = paste("fpa-path-step", paste0("is-", state)),
      shiny::tags$span(
        class = "fpa-path-num",
        if (identical(state, "done")) fpa_shiny_check_svg(14) else as.character(n)
      ),
      shiny::tags$span(
        class = "fpa-path-step-body",
        shiny::tags$span(class = "fpa-path-step-label", label),
        shiny::tags$span(class = "fpa-path-step-detail", detail)
      )
    )
  }
  map_state <- if (map_clear) "done" else if (identical(where, "map") || blocked) "now" else "later"
  drv_state <- if (drv_done) "done" else if (identical(where, "drivers")) "now" else "later"
  map_detail <- if (blocked) {
    as.character(map_gap)
  } else if (isTRUE(map_done) && nzchar(map_at)) {
    fpa_screen("path_map_done", map_at)
  } else {
    fpa_screen("path_map_title")
  }
  drv_detail <- if (drv_done) {
    fpa_screen("path_drv_all")
  } else if (n_all > 0L && identical(as.integer(n_saved), 1L)) {
    fpa_screen("path_drv_progress_one", n_saved, n_all)
  } else if (n_all > 0L) {
    fpa_screen("path_drv_progress", n_saved, n_all)
  } else {
    fpa_screen("path_drv_title")
  }
  on_map <- identical(where, "map")
  if (on_map && map_clear) {
    return(shiny::tags$section(
      class = "fpa-path",
      shiny::tags$p(class = "fpa-path-kicker", fpa_screen("path_map_kicker")),
      shiny::tags$div(
        class = "fpa-path-actions",
        shiny::tags$span(fpa_screen("path_map_done_short", map_at)),
        shiny::tags$button(
          type = "button", class = "fpa-path-btn",
          onclick = "var a=document.querySelector('#main_nav a.nav-link[data-value=Drivers]'); if(a) a.click();",
          fpa_screen("path_goto_drv")
        )
      )
    ))
  }
  if (!on_map) {
    return(shiny::tags$section(
      class = "fpa-path",
      shiny::tags$p(class = "fpa-path-kicker", fpa_screen("path_drv_kicker")),
      shiny::tags$h2(fpa_screen("path_drv_title")),
      shiny::tags$p(fpa_screen("drv_keep_lead")),
      shiny::tags$p(style = "font-weight:700;color:#1f4e5f;", drv_detail),
      if (!drv_done && n_all > 0L) shiny::tags$div(
        class = "fpa-path-bar",
        shiny::tags$span(style = sprintf("width:%.1f%%;", 100 * n_saved / n_all))
      )
    ))
  }
  shiny::tags$section(
    class = "fpa-path",
    shiny::tags$p(class = "fpa-path-kicker", if (on_map) fpa_screen("path_map_kicker") else fpa_screen("path_drv_kicker")),
    shiny::tags$h2(if (on_map) fpa_screen("path_map_title") else fpa_screen("path_drv_title")),
    shiny::tags$p(shiny::tags$strong(fpa_screen("loc_page_shows")), if (on_map) fpa_screen("path_map_shows") else fpa_screen("path_drv_shows")),
    shiny::tags$p(shiny::tags$strong("Objectif. "), if (on_map) fpa_screen("path_map_obj") else fpa_screen("path_drv_obj")),
    shiny::tags$p(shiny::tags$strong(fpa_screen("loc_to_do")), if (on_map && blocked) as.character(map_gap) else if (on_map) fpa_screen("path_map_do") else fpa_screen("path_drv_do")),
    shiny::tags$p(class = "fpa-path-final", fpa_screen("path_final")),
    shiny::tags$ol(
      class = "fpa-path-steps",
      step(1L, "Cartographie", map_detail, map_state),
      step(2L, "Drivers", drv_detail, drv_state)
    ),
    if (!drv_done && n_all > 0L) shiny::tags$div(
      class = "fpa-path-bar",
      shiny::tags$span(style = sprintf("width:%.1f%%;", 100 * n_saved / n_all))
    ),
    shiny::tags$div(
      class = "fpa-path-actions",
      if (on_map && !map_clear && !blocked) shiny::actionButton(
        "map_read", fpa_screen("path_map_btn"),
        style = "background:#1f4e5f;color:#fff;border:1px solid #1f4e5f;border-radius:8px;font-weight:600;"
      ),
      if (on_map && map_clear) shiny::tags$p(
        class = "fpa-path-checkline",
        fpa_shiny_check_svg(16),
        fpa_screen("path_map_done", map_at)
      ),
      shiny::tags$button(
        type = "button",
        class = if (on_map) "fpa-path-btn" else "fpa-path-btn is-quiet",
        onclick = if (on_map) {
          "var a=document.querySelector('#main_nav a.nav-link[data-value=Drivers]'); if(a) a.click();"
        } else {
          "var a=document.querySelector('#main_nav a.nav-link[data-value=Cartographie]'); if(a) a.click();"
        },
        if (on_map) fpa_screen("path_goto_drv") else fpa_screen("path_goto_map")
      )
    )
  )
}

#' Four shapes, not four colours: filled tick, ringed cross, double bar, dashed dash.
fpa_drv_pil_icon <- function(state, size = 22L) {
  inner <- switch(
    as.character(state),
    pass = '<circle cx="11" cy="11" r="10" fill="#1f4e5f"/><path d="M6.6 11.3 9.6 14.2 15.4 8" fill="none" stroke="#fff" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"/>',
    fail = '<circle cx="11" cy="11" r="9.2" fill="#fff" stroke="#8c3a3a" stroke-width="1.6"/><path d="M7.9 7.9 14.1 14.1 M14.1 7.9 7.9 14.1" stroke="#8c3a3a" stroke-width="1.9" stroke-linecap="round"/>',
    expected = '<circle cx="11" cy="11" r="9.2" fill="#e6edef" stroke="#1f4e5f" stroke-width="1.4"/><path d="M7.3 9.4h7.4 M7.3 12.6h7.4" stroke="#1f4e5f" stroke-width="1.7" stroke-linecap="round"/>',
    '<circle cx="11" cy="11" r="9.2" fill="#fff" stroke="#b9c6cb" stroke-width="1.4" stroke-dasharray="2.6 2.2"/><path d="M7.6 11h6.8" stroke="#8a989e" stroke-width="1.7" stroke-linecap="round"/>'
  )
  shiny::HTML(sprintf('<svg class="fpa-pil-ico" viewBox="0 0 22 22" width="%d" height="%d" aria-hidden="true">%s</svg>', as.integer(size), as.integer(size), inner))
}

#' The accounting proof and the three history tests of one series, each as
#' state (pass, fail, expected, na), a short figure, and a sentence for the tooltip.
fpa_drv_pillars <- function(g, formulas = NULL) {
  pct <- function(x) fpa_shiny_fr_num(fpa_shiny_num(x) * 100, 1)
  rr <- function(x) fpa_shiny_fr_num(x, 2)
  words <- c(pass = fpa_screen("drv_leg_pass"), fail = fpa_screen("drv_leg_fail"),
             expected = fpa_screen("drv_leg_expected"), na = fpa_screen("drv_leg_na"))
  out <- function(state, num, tip) list(state = state, num = num, tip = tip, word = unname(words[[state]]))
  line_of <- fpa_screen("drv_pil_line_of", tolower(fpa_shiny_line_name(g$target_line)))
  oi_of <- fpa_screen("drv_pil_oi")
  pass_txt <- fpa_screen("drv_pass")
  fail_txt <- fpa_screen("drv_fail")

  nm <- as.character(g$series_name)
  hit <- if (is.null(formulas) || !nrow(formulas)) NULL else {
    has <- vapply(seq_len(nrow(formulas)), function(k) {
      nm %in% c(strsplit(as.character(formulas$factors[[k]]), " x ", fixed = TRUE)[[1]], as.character(formulas$target[[k]]))
    }, logical(1))
    formulas[has, , drop = FALSE]
  }
  eq_of <- function(f) paste(vapply(seq_len(nrow(f)), function(k) fpa_shiny_formula_eq(f[k, , drop = FALSE], cap = FALSE), ""), collapse = " ; ")
  form <- if (fpa_shiny_state_flag(g, "state_proved")) {
    ok <- if (is.null(hit)) NULL else hit[as.logical(hit$verified) %in% TRUE, , drop = FALSE]
    if (is.null(ok) || !nrow(ok)) {
      out("pass", "", fpa_screen("drv_bil_proved_tip"))
    } else {
      gap <- max(suppressWarnings(as.numeric(ok$median_gap)), na.rm = TRUE)
      n_mo <- as.integer(min(suppressWarnings(as.numeric(ok$n)), na.rm = TRUE))
      tip <- if (is.finite(gap) && gap * 100 < 0.05) {
        fpa_screen("drv_pil_form_exact", eq_of(ok), n_mo)
      } else {
        fpa_screen("drv_pil_form_ok", eq_of(ok), n_mo, pct(gap))
      }
      out("pass", fpa_screen("drv_pil_gap", pct(gap)), tip)
    }
  } else if (fpa_shiny_state_flag(g, "state_failed")) {
    bad <- if (is.null(hit)) NULL else hit[!(as.logical(hit$verified) %in% TRUE), , drop = FALSE]
    if (is.null(bad) || !nrow(bad)) {
      out("fail", "", fpa_screen("drv_bil_decide_tip"))
    } else {
      gap <- min(suppressWarnings(as.numeric(bad$median_gap)), na.rm = TRUE)
      out("fail", fpa_screen("drv_pil_gap", pct(gap)), fpa_screen("drv_pil_form_no", eq_of(bad), pct(gap)))
    }
  } else {
    out("na", "\u2014", fpa_screen("drv_pil_form_none"))
  }

  ev_mark <- fpa_shiny_axis_mark(g, "evidence")
  ev_r <- fpa_shiny_num(g$evidence_r)
  ev_rank <- fpa_shiny_num(g$permutation_rank)
  line <- if (!is.finite(ev_r)) {
    out("na", "\u2014", fpa_screen("drv_pil_flat"))
  } else if (identical(ev_mark, fpa_screen("drv_mark_expected"))) {
    out("expected", paste("r", rr(ev_r)), fpa_screen("drv_pil_expected", line_of, rr(ev_r)))
  } else if (identical(ev_mark, pass_txt)) {
    out("pass", paste("r", rr(ev_r)), fpa_screen("drv_pil_pass", rr(ev_r), line_of, pct(ev_rank)))
  } else if (identical(as.character(g$lag_status[[1]] %||% ""), "refused_reverse_causality")) {
    out("fail", paste("r", rr(ev_r)), fpa_screen("drv_pil_reverse", rr(ev_r), line_of))
  } else {
    key <- if (is.finite(ev_rank) && ev_rank > 0.05) "drv_pil_fail_chance" else "drv_pil_fail_bar"
    out("fail", paste("r", rr(ev_r)), fpa_screen(key, rr(ev_r), line_of, pct(ev_rank)))
  }

  ind_mark <- fpa_shiny_axis_mark(g, "independence")
  ind_r <- fpa_shiny_num(g$independence_r)
  indep <- if (identical(ind_mark, pass_txt)) {
    out("pass", paste("r", rr(ind_r)), fpa_screen("drv_pil_indep_pass", rr(ind_r), line_of))
  } else if (identical(ind_mark, fail_txt)) {
    out("fail", paste("r", rr(ind_r)), fpa_screen("drv_pil_indep_fail", rr(ind_r), line_of))
  } else {
    out("na", "\u2014", fpa_screen("drv_pil_na"))
  }

  res_mark <- fpa_shiny_axis_mark(g, "result")
  b_r <- fpa_shiny_num(g$bottom_r)
  b_rank <- fpa_shiny_num(g$bottom_rank)
  result <- if (!is.finite(b_r)) {
    out("na", "\u2014", if ("bottom_r" %in% names(g)) fpa_screen("drv_pil_flat") else fpa_screen("drv_pil_na"))
  } else if (identical(res_mark, pass_txt)) {
    out("pass", paste("r", rr(b_r)), fpa_screen("drv_pil_pass", rr(b_r), oi_of, pct(b_rank)))
  } else {
    key <- if (is.finite(b_rank) && b_rank > 0.05) "drv_pil_fail_chance" else "drv_pil_fail_bar"
    out("fail", paste("r", rr(b_r)), fpa_screen(key, rr(b_r), oi_of, pct(b_rank)))
  }
  list(formula = form, line = line, indep = indep, result = result)
}

#' One overall reading per series. The formula outranks the tests; the tests
#' count only when they could be measured.
fpa_drv_bilan <- function(g, pil) {
  states <- c(pil$line$state, pil$indep$state, pil$result$state)
  run <- sum(states %in% c("pass", "fail"))
  np <- sum(states == "pass")
  score <- if (run == 0L) {
    fpa_screen("drv_bil_score_none")
  } else if (np == 0L) {
    fpa_screen("drv_bil_score_zero", run)
  } else if (np == 1L) {
    fpa_screen("drv_bil_score_one", run)
  } else {
    fpa_screen("drv_bil_score", np, run)
  }
  kind <- if (identical(pil$formula$state, "pass")) {
    "proved"
  } else if (identical(pil$formula$state, "fail")) {
    "decide"
  } else if (run > 0L && np == run) {
    "solid"
  } else if (np > 0L) {
    "weak"
  } else {
    "none"
  }
  tip <- switch(
    kind,
    proved = fpa_screen("drv_bil_proved_tip"),
    decide = if (fpa_shiny_state_flag(g, "state_used")) fpa_screen("drv_bil_decide_tip_used") else fpa_screen("drv_bil_decide_tip"),
    solid = fpa_screen("drv_bil_solid_tip"),
    weak = fpa_screen("drv_bil_weak_tip"),
    fpa_screen("drv_bil_none_tip")
  )
  label <- fpa_screen(paste0("drv_bil_", kind))
  list(kind = kind, label = label, tip = tip, score = score, np = np, run = run)
}

fpa_shiny_driver_work <- function(grades, saved, selected_id, formulas = NULL) {
  if (is.null(grades) || !nrow(grades)) {
    return(shiny::tags$p(fpa_screen("loc_no_series_run")))
  }
  saved_ids <- fpa_shiny_saved_ids(saved)
  header <- shiny::tagList(
    shiny::tags$tr(
      class = "fpa-work-band",
      shiny::tags$th(rowspan = "2", class = "fpa-w-check"),
      shiny::tags$th(rowspan = "2", class = "fpa-w-name", fpa_drv_term("serie", "Série")),
      shiny::tags$th(class = "fpa-band", fpa_screen("drv_band_proof")),
      shiny::tags$th(colspan = "3", class = "fpa-band fpa-w-first", fpa_screen("drv_band_tests")),
      shiny::tags$th(rowspan = "2", class = "fpa-w-bil fpa-w-first", fpa_drv_term("bilan", fpa_screen("drv_col_bilan"))),
      shiny::tags$th(rowspan = "2", class = "fpa-w-act")
    ),
    shiny::tags$tr(
      shiny::tags$th(class = "fpa-w-pil", fpa_drv_term("formule", fpa_screen("drv_col_formula"))),
      shiny::tags$th(class = "fpa-w-pil fpa-w-first", fpa_drv_term("soutien", fpa_screen("drv_col_line"))),
      shiny::tags$th(class = "fpa-w-pil", fpa_drv_term("indep", fpa_screen("drv_col_indep"))),
      shiny::tags$th(class = "fpa-w-pil", fpa_drv_term("resultat", fpa_screen("drv_col_result")))
    )
  )
  tier_key <- c(mechanism = "mecanisme", confirmed = "confirme", watch = "veille")
  body <- lapply(seq_len(nrow(grades)), function(i) {
    g <- grades[i, , drop = FALSE]
    sid <- as.character(g$series_id)
    done <- sid %in% saved_ids
    on <- identical(sid, as.character(selected_id))
    safe <- gsub("[^A-Za-z0-9_-]", "", sid)
    in_formula <- fpa_shiny_in_formula(g)
    open_test <- fpa_shiny_state_flag(g, "state_proved") && !fpa_shiny_state_flag(g, "state_stat")
    saved_v <- if ("saved_verdict" %in% names(g)) as.character(g$saved_verdict[[1]] %||% "") else ""
    pil <- fpa_drv_pillars(g, formulas)
    bil <- fpa_drv_bilan(g, pil)
    bil_kind <- bil$kind
    bil_label <- bil$label
    bil_tip <- bil$tip
    if (identical(bil$kind, "decide") && nzchar(saved_v)) {
      bil_label <- fpa_shiny_verdict_fr(saved_v)
      bil_kind <- switch(
        saved_v,
        Keep = "called",
        Reject = "parked",
        "held"
      )
      bil_tip <- fpa_screen("drv_bil_called_tip", bil_label)
    }
    proposal <- as.character(g$verdict)
    if (fpa_shiny_state_flag(g, "state_proved") && identical(proposal, "Reject")) proposal <- "Optional"
    avis <- if (nzchar(saved_v)) {
      fpa_screen("drv_bil_avis", fpa_shiny_verdict_fr(saved_v))
    } else {
      fpa_screen("drv_bil_engine", fpa_shiny_verdict_fr(proposal))
    }
    formula_note <- if (identical(saved_v, "Reject")) {
      if (isTRUE(in_formula)) fpa_screen("drv_reject_still_formula") else fpa_screen("drv_reject_not_formula")
    } else {
      ""
    }
    tk <- unname(tier_key[as.character(g$tier %||% "")])
    tier_tag <- if (length(tk) && !is.na(tk)) {
      shiny::tags$span(class = paste0("fpa-w-tier is-", as.character(g$tier)), fpa_drv_term(tk))
    }
    pil_cell <- function(p, first = FALSE) {
      shiny::tags$td(
        class = paste("fpa-w-pil", if (first) "fpa-w-first"),
        shiny::tags$span(
          class = paste0("fpa-pil is-", p$state), tabindex = "0",
          `data-tip` = p$tip, `aria-label` = p$word,
          fpa_drv_pil_icon(p$state),
          shiny::tags$span(class = "fpa-pil-num", p$num)
        )
      )
    }
    shiny::tags$tr(
      class = if (on) "is-on" else NULL,
      shiny::tags$td(
        class = "fpa-w-check",
        if (done) fpa_shiny_check_svg(16) else shiny::tags$span(class = "fpa-path-empty", " ")
      ),
      shiny::tags$td(
        class = "fpa-w-name",
        shiny::tags$div(class = "fpa-w-series", paste0(i, ". ", fpa_shiny_bottom_label(g$series_name))),
        shiny::tags$div(class = "fpa-w-sub", tier_tag, shiny::tags$span(fpa_shiny_line_name(g$target_line)))
      ),
      pil_cell(pil$formula),
      pil_cell(pil$line, first = TRUE),
      pil_cell(pil$indep),
      pil_cell(pil$result),
      shiny::tags$td(
        class = "fpa-w-bil fpa-w-first",
        shiny::tags$span(class = paste0("fpa-bil is-", bil_kind), tabindex = "0", `data-tip` = bil_tip, bil_label),
        shiny::tags$div(class = "fpa-w-sub", bil$score),
        shiny::tags$div(class = "fpa-w-sub", avis),
        if (nzchar(formula_note)) shiny::tags$div(class = "fpa-w-sub", formula_note)
      ),
      shiny::tags$td(
        class = "fpa-w-act",
        shiny::tags$button(
          type = "button",
          class = "fpa-path-btn",
          onclick = sprintf(
            "var d=document.getElementById('drv-more'); if(d) d.open=true; Shiny.setInputValue('drv_pick', '%s', {priority:'event'});",
            safe
          ),
          fpa_screen("drv_change")
        ),
        if (!done) shiny::tags$button(
          type = "button",
          class = "fpa-path-btn is-quiet",
          style = "margin-left:6px;",
          onclick = sprintf("Shiny.setInputValue('drv_keep', '%s', {priority:'event'})", safe),
          if (open_test || (in_formula && !is.finite(fpa_shiny_num(g$bottom_r)))) fpa_screen("drv_read") else fpa_screen("drv_keep")
        )
      )
    )
  })
  capped <- fpa_shiny_cap_rows(body, 8L)
  n_ok <- if (is.null(formulas) || !nrow(formulas)) 0L else sum(as.logical(formulas$verified) %in% TRUE)
  shiny::tags$section(
    class = "fpa-drv-work",
    shiny::tags$h3(fpa_screen("drv_work_title")),
    shiny::tags$p(class = "fpa-drv-work-lead", fpa_screen("drv_keep_lead")),
    shiny::tags$div(
      class = "fpa-cap",
      shiny::tags$table(
        class = "fpa-work",
        shiny::tags$thead(header),
        shiny::tags$tbody(capped$rows)
      ),
      capped$toggle
    ),
    shiny::tags$div(
      class = "fpa-w-legend",
      lapply(c("pass", "fail", "expected", "na"), function(s) {
        shiny::tags$span(class = "fpa-w-leg", fpa_drv_pil_icon(s, 15L), fpa_screen(paste0("drv_leg_", s)))
      }),
      shiny::tags$span(class = "fpa-w-leg-hover", fpa_screen("drv_leg_hover"))
    ),
    shiny::tags$p(style = "color:#3d4c54;font-size:0.9rem;line-height:1.4;margin:0 0 0.6rem;", fpa_screen("drv_formula_note")),
    if (!is.null(formulas) && nrow(formulas)) shiny::tags$details(
      class = "fpa-drv-fold-lite",
      shiny::tags$summary(fpa_screen("drv_formula_fold", n_ok, nrow(formulas))),
      fpa_shiny_formula_block(formulas)
    ),
    fpa_shiny_segment_block(grades)
  )
}

#' Declared formulas and what the engine found on the closed months.
fpa_shiny_formula_eq <- function(f, cap = TRUE) {
  side <- function(x) {
    x <- as.character(x)
    if (startsWith(x, "LINE:")) return(fpa_shiny_line_name(sub("^LINE:", "", x)))
    fpa_shiny_bottom_label(x)
  }
  factors <- strsplit(as.character(f$factors[[1]]), " x ", fixed = TRUE)[[1]]
  lhs <- side(f$target[[1]])
  lhs <- if (cap) paste0(toupper(substr(lhs, 1, 1)), substr(lhs, 2, nchar(lhs))) else tolower(lhs)
  paste0(lhs, " = ", paste(vapply(factors, side, character(1)), collapse = " \u00d7 "))
}

#' Three sentences at the top of Drivers: what the forecast reads, what proves it,
#' what still needs a choice. Built from fpa_driver_state columns.
fpa_shiny_driver_lead <- function(grades, formulas) {
  if (is.null(grades) || !nrow(grades) || !"state_used" %in% names(grades)) return(NULL)
  flag <- function(col) as.logical(grades[[col]]) %in% TRUE
  used <- grades[flag("state_used"), , drop = FALSE]
  s1 <- if (nrow(used)) {
    fpa_screen("drv_lead_uses", paste(vapply(as.character(used$series_name), fpa_shiny_bottom_label, ""), collapse = ", "))
  } else {
    fpa_screen("drv_lead_uses_none")
  }
  ok <- if (is.null(formulas) || !nrow(formulas)) formulas else formulas[as.logical(formulas$verified) %in% TRUE, , drop = FALSE]
  s2 <- if (is.null(ok) || !nrow(ok)) {
    fpa_screen("drv_lead_proves_none")
  } else {
    eqs <- vapply(seq_len(nrow(ok)), function(i) fpa_shiny_formula_eq(ok[i, , drop = FALSE], cap = FALSE), "")
    gap_pct <- max(fpa_shiny_num(ok$median_gap), na.rm = TRUE) * 100
    n_mo <- as.integer(min(fpa_shiny_num(ok$n), na.rm = TRUE))
    if (is.finite(gap_pct) && gap_pct < 0.05) {
      fpa_screen("drv_lead_proves_exact", paste(eqs, collapse = " ; "), n_mo)
    } else {
      fpa_screen("drv_lead_proves", paste(eqs, collapse = " ; "), n_mo, fpa_shiny_fr_num(gap_pct, 1))
    }
  }
  bad <- if (is.null(formulas) || !nrow(formulas)) formulas else formulas[!(as.logical(formulas$verified) %in% TRUE), , drop = FALSE]
  has_call <- function(series_name) {
    if (!nzchar(series_name) || !"saved_verdict" %in% names(grades)) return(FALSE)
    hit <- which(as.character(grades$series_name) == series_name)
    length(hit) > 0L && nzchar(as.character(grades$saved_verdict[[hit[[1]]]] %||% ""))
  }
  formula_series <- function(f) {
    factors <- strsplit(as.character(f$factors[[1]]), " x ", fixed = TRUE)[[1]]
    tgt <- as.character(f$target[[1]])
    raw <- c(factors, if (!startsWith(tgt, "LINE:")) tgt else character())
    raw[!startsWith(raw, "LINE:") & nzchar(raw)]
  }
  bits <- character()
  if (!is.null(bad) && nrow(bad)) {
    for (i in seq_len(nrow(bad))) {
      named <- formula_series(bad[i, , drop = FALSE])
      if (length(named) && all(vapply(named, has_call, logical(1)))) next
      gap <- fpa_shiny_num(bad$median_gap[[i]])
      if (!is.finite(gap)) next
      bits <- c(bits, fpa_screen("drv_lead_choice_failed", fpa_shiny_formula_eq(bad[i, , drop = FALSE], cap = FALSE), fpa_shiny_fr_num(gap * 100, 1)))
    }
  }
  called <- if ("saved_verdict" %in% names(grades)) {
    nzchar(as.character(grades$saved_verdict))
  } else {
    rep(FALSE, nrow(grades))
  }
  n_open <- sum(!flag("state_proved") & !flag("state_failed") & !flag("state_stat") & !called)
  if (n_open == 1L) bits <- c(bits, fpa_screen("drv_lead_choice_open_one"))
  if (n_open > 1L) bits <- c(bits, fpa_screen("drv_lead_choice_open", n_open))
  s3 <- if (length(bits)) fpa_screen("drv_lead_choice", paste(bits, collapse = " ; ")) else fpa_screen("drv_lead_choice_none")
  shiny::tags$div(
    class = "fpa-drv-lead",
    shiny::tags$p(s1),
    shiny::tags$p(s2),
    shiny::tags$p(s3)
  )
}

fpa_shiny_formula_block <- function(formulas) {
  if (is.null(formulas) || !nrow(formulas)) return(NULL)
  rows <- lapply(seq_len(nrow(formulas)), function(i) {
    f <- formulas[i, , drop = FALSE]
    eq <- fpa_shiny_formula_eq(f)
    good <- fpa_shiny_flag(f$verified)
    gap <- fpa_shiny_num(f$median_gap)
    verdict <- if (good) {
      fpa_screen("drv_formula_ok", fpa_shiny_fr_num(gap * 100, 1), as.integer(fpa_shiny_num(f$n)))
    } else if (is.finite(gap)) {
      fpa_screen("drv_formula_no", fpa_shiny_fr_num(gap * 100, 1))
    } else {
      as.character(f$note)
    }
    shiny::tags$tr(
      shiny::tags$td(style = "padding:0.4rem 0.7rem;border-bottom:1px solid #d5dde0;", eq),
      shiny::tags$td(
        style = paste0("padding:0.4rem 0.7rem;border-bottom:1px solid #d5dde0;font-weight:600;color:",
                       if (good) "#1f4e5f" else "#8c3a3a", ";"),
        verdict
      )
    )
  })
  shiny::tagList(
    shiny::tags$p(style = "color:#3d4c54;font-size:0.9rem;line-height:1.4;margin:0.4rem 0 0.4rem;", fpa_screen("drv_formula_lead")),
    shiny::tags$table(
      style = "width:100%;border-collapse:collapse;margin:0 0 1rem;font-size:13px;",
      shiny::tags$thead(
        style = "background:#1f4e5f;color:#fff;text-align:left;",
        shiny::tags$tr(
          shiny::tags$th(style = "padding:0.4rem 0.7rem;", fpa_screen("drv_formula_h_eq")),
          shiny::tags$th(style = "padding:0.4rem 0.7rem;", fpa_screen("drv_formula_h_check"))
        )
      ),
      shiny::tags$tbody(rows)
    )
  )
}

#' One sentence per file whose rows were collapsed (one row per site per month).
fpa_shiny_segment_block <- function(grades) {
  if (is.null(grades) || !nrow(grades) || !"segment_note" %in% names(grades)) return(NULL)
  notes <- unique(as.character(grades$segment_note))
  notes <- notes[!is.na(notes) & nzchar(notes)]
  if (!length(notes)) return(NULL)
  shiny::tags$div(
    style = "border:1px solid #e0cba8;background:#fdf6ea;border-radius:8px;padding:10px 14px;margin:0 0 1rem;",
    lapply(notes, function(n) shiny::tags$p(style = "margin:0;", n))
  )
}

#' Pass, Fail, or a short French mark. Non disponible meant the test was not run.
fpa_shiny_axis_mark <- function(g, axis) {
  if (identical(axis, "impact")) {
    eur <- fpa_shiny_num(g$impact_eur)
    if (identical(as.character(g$impact_status), "engine") && is.finite(eur)) return(fpa_screen("drv_pass"))
    return(fpa_screen("drv_impact_na"))
  }
  if (identical(axis, "evidence")) {
    r <- fpa_shiny_num(g$evidence_r)
    if (!is.finite(r)) return("Non disponible")
    if ("relation" %in% names(g) && as.character(g$relation[[1]]) %in% c("part_whole", "derived")) {
      return(fpa_screen("drv_mark_expected"))
    }
    if (identical(as.character(g$lag_status[[1]] %||% ""), "refused_reverse_causality")) return(fpa_screen("drv_fail"))
    rank <- fpa_shiny_num(g$permutation_rank)
    if (fpa_shiny_flag(g$evidence_sig) && is.finite(rank) && rank <= 0.05) return(fpa_screen("drv_pass"))
    return(fpa_screen("drv_fail"))
  }
  if (identical(axis, "result")) {
    if (!"bottom_r" %in% names(g)) return("Non disponible")
    r <- fpa_shiny_num(g$bottom_r)
    if (!is.finite(r)) return("Non disponible")
    rank <- fpa_shiny_num(g$bottom_rank)
    if (fpa_shiny_flag(g$bottom_sig) && is.finite(rank) && rank <= 0.05) return(fpa_screen("drv_pass"))
    return(fpa_screen("drv_fail"))
  }
  if (!identical(as.character(g$independence_status), "measured")) return(fpa_screen("drv_indep_na"))
  r <- fpa_shiny_num(g$independence_r)
  n <- if ("line_n" %in% names(g) && is.finite(fpa_shiny_num(g$line_n))) fpa_shiny_num(g$line_n) else fpa_shiny_num(g$n)
  lag <- fpa_shiny_num(g$causal_lag)
  if (!is.finite(r) || !is.finite(n)) return(fpa_screen("drv_indep_na"))
  n_obs <- as.integer(n)
  if (is.finite(lag)) n_obs <- n_obs - abs(as.integer(lag))
  bar <- fpa_shiny_r_crit(n_obs - 3L)
  if (!is.finite(bar)) return(fpa_screen("drv_indep_na"))
  if (abs(r) >= bar) fpa_screen("drv_pass") else fpa_screen("drv_fail")
}

fpa_shiny_axis_cell <- function(mark) {
  col <- if (identical(as.character(mark), fpa_screen("drv_pass"))) {
    "#1f4e5f"
  } else if (identical(as.character(mark), fpa_screen("drv_fail"))) {
    "#8c3a3a"
  } else {
    "#5c6b73"
  }
  if (startsWith(as.character(mark), "r =")) col <- "#8a5a00"
  shiny::tags$td(
    style = paste0("padding:0.35rem 0.6rem;border-bottom:1px solid #d5dde0;font-weight:600;color:", col, ";"),
    mark
  )
}

fpa_shiny_tests_table <- function(grades, selected_id = "", saved = list()) {
  if (is.null(grades) || !nrow(grades)) return(NULL)
  saved_ids <- vapply(saved, function(item) as.character(item$series_id %||% ""), character(1))
  header <- shiny::tags$tr(
    lapply(list(
      fpa_drv_term("serie", "Série"),
      fpa_drv_term("ligne", fpa_screen("drv_h_line")),
      fpa_drv_term("soutien", fpa_screen("drv_col_line")),
      fpa_drv_term("indep", fpa_screen("drv_col_indep")),
      fpa_drv_term("resultat", fpa_screen("drv_col_result")),
      fpa_screen("drv_h_saved")
    ), function(lab) {
      shiny::tags$th(style = "padding:0.4rem 0.6rem;", lab)
    })
  )
  check <- '<svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true"><path d="M3.2 8.2 6.4 11.4 12.8 4.6" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>'
  body <- lapply(seq_len(nrow(grades)), function(i) {
    g <- grades[i, , drop = FALSE]
    on <- identical(as.character(g$series_id), as.character(selected_id))
    done <- as.character(g$series_id) %in% saved_ids
    shiny::tags$tr(
      style = if (on) "background:#e7eef0;" else NULL,
      shiny::tags$td(style = "padding:0.35rem 0.6rem;border-bottom:1px solid #d5dde0;", fpa_shiny_bottom_label(g$series_name)),
      shiny::tags$td(style = "padding:0.35rem 0.6rem;border-bottom:1px solid #d5dde0;color:#3d4c54;", fpa_shiny_line_name(g$target_line)),
      fpa_shiny_axis_cell(fpa_shiny_axis_mark(g, "evidence")),
      fpa_shiny_axis_cell(fpa_shiny_axis_mark(g, "independence")),
      fpa_shiny_axis_cell(fpa_shiny_axis_mark(g, "result")),
      shiny::tags$td(
        style = "padding:0.35rem 0.6rem;border-bottom:1px solid #d5dde0;color:#1f4e5f;font-weight:700;",
        if (done) shiny::HTML(check) else ""
      )
    )
  })
  capped <- fpa_shiny_cap_rows(body, 8L)
  shiny::tags$div(
    shiny::tags$p(style = "color:#1a2b32;font-size:0.92rem;line-height:1.45;margin:0.2rem 0 0.5rem;", fpa_screen("drv_tests_lead")),
    shiny::tags$div(
      class = "fpa-cap",
      shiny::tags$table(
        style = "width:100%;border-collapse:collapse;margin-bottom:0.6rem;",
        shiny::tags$thead(
          style = "background:#1f4e5f;color:#fff;text-align:left;",
          header
        ),
        shiny::tags$tbody(capped$rows)
      ),
      capped$toggle
    ),
    shiny::tags$details(
      class = "fpa-drv-fold-lite",
      shiny::tags$summary(fpa_screen("drv_method_fold")),
      shiny::tags$p(style = "color:#3d4c54;font-size:0.9rem;line-height:1.4;margin:0.3rem 0 0;", fpa_screen("drv_tests_foot"))
    ),
    fpa_shiny_goal_table(grades, selected_id, "line"),
    fpa_shiny_bottom_table(grades, selected_id)
  )
}

fpa_shiny_recommend_sentence <- function(g, prof, offers) {
  peak <- fpa_shiny_num(g$causal_lag)
  tested <- paste0(fpa_screen("drv_rec_noprof"), " ")
  r_peak <- NA_real_
  r0 <- NA_real_
  if (!is.null(prof) && nrow(prof) && "lag" %in% names(prof)) {
    lags <- as.integer(prof$lag)
    tested <- paste0(fpa_screen("drv_rec_tested", min(lags), max(lags)), " ")
    rr <- as.numeric(prof$r)
    if (is.finite(peak)) {
      hit <- rr[lags == as.integer(peak)]
      if (length(hit)) r_peak <- hit[[1]]
    }
    z <- rr[lags == 0L]
    if (length(z)) r0 <- z[[1]]
  }
  signed <- function(h) if (h > 0) paste0("+", as.integer(h)) else as.character(as.integer(h))
  if (!is.finite(peak)) {
    pick <- paste0(fpa_screen("drv_rec_none"), " ")
  } else if (is.finite(r0) && as.integer(peak) != 0L && is.finite(r_peak)) {
    pick <- paste0(fpa_screen("drv_rec_better", signed(peak), fpa_shiny_fr_num(r_peak, 2), fpa_shiny_fr_num(r0, 2)), " ")
  } else if (is.finite(r_peak)) {
    pick <- paste0(fpa_screen("drv_rec_same", signed(peak), fpa_shiny_fr_num(r_peak, 2)), " ")
  } else {
    pick <- paste0(fpa_screen("drv_rec_plain", signed(peak)), " ")
  }
  verd <- if (nzchar(fpa_shiny_state_label(g))) {
    paste0(fpa_shiny_state_label(g), ". ")
  } else {
    paste0(fpa_screen("drv_rec_verdict", fpa_shiny_verdict_fr(g$verdict)), " ")
  }
  alt <- ""
  avail <- fpa_shiny_num(g$availability_lag_days)
  if (!is.null(prof) && nrow(prof) && is.finite(peak) && is.finite(avail)) {
    horizon_peak <- as.numeric(peak) * 30 - avail
    if (horizon_peak <= 0 && "significant" %in% names(prof)) {
      sig <- vapply(prof$significant, fpa_shiny_flag, logical(1))
      later <- which(as.integer(prof$lag) > as.integer(peak) & sig & is.finite(as.numeric(prof$r)))
      if (length(later)) {
        horizons <- as.integer(prof$lag[later]) * 30 - avail
        use <- later[horizons > 0]
        if (length(use)) {
          ord <- use[order(as.integer(prof$lag[use]))][[1]]
          hzn <- as.integer(prof$lag[[ord]]) * 30 - avail
          alt <- paste0(fpa_screen(
            "drv_rec_late",
            as.integer(prof$lag[[ord]]),
            fpa_shiny_fr_num(as.numeric(prof$r[[ord]]), 2),
            round(hzn)
          ), " ")
        }
      }
    }
  }
  paste0(tested, pick, verd, alt)
}

fpa_shiny_line_name <- function(id) {
  id <- as.character(id %||% "")
  switch(
    id,
    REV = "Chiffre d'affaires",
    OTHER_OP_INC = "Autres produits",
    COGS = "Achats",
    GP = "Marge brute",
    PAYROLL = "Masse salariale",
    OPEX_OTHER = "Autres charges",
    EBITDA = "EBE",
    D_A = "Dotations",
    OI = "Résultat d'exploitation",
    FIN = fpa_screen("loc_fin_result"),
    EXCEP = "Exceptionnel",
    TAX = fpa_screen("loc_tax"),
    NI = "Résultat net",
    if (nzchar(id)) id else "aucune"
  )
}

fpa_shiny_arrival <- function(p, mode = c("full", "slim")) {
  mode <- match.arg(mode)
  cfg <- p$config
  if (is.null(cfg)) return(NULL)
  company <- as.character((cfg$company %||% list())$name %||% "")
  status <- p$finance$period_status
  closed <- ""
  if (!is.null(status) && nrow(status) && all(c("periode", "status") %in% names(status))) {
    act <- status[as.character(status$status) == "actual", , drop = FALSE]
    if (nrow(act)) closed <- as.character(act$periode[[nrow(act)]])
  }
  work <- if (!is.null(p$paths) && !is.null(p$paths$work)) p$paths$work else ""
  pnl_file <- if (nzchar(work)) file.path(work, "pnl-monthly.csv") else ""
  when <- if (nzchar(pnl_file) && file.exists(pnl_file)) {
    format(file.info(pnl_file)$mtime, "%Y-%m-%d %H:%M")
  } else {
    ""
  }
  newer <- if (nzchar(when)) fpa_shiny_newer_sources(cfg, p$paths) else character()
  focus <- tryCatch(fpa_anomaly_focus_periods(status), error = function(e) closed)
  n_fix <- 0L
  counts <- list(act = 0L, watch = 0L)
  scan <- tryCatch({
    hist <- fpa_line_history(cfg, p$paths)
    vol <- fpa_shiny_volumes(cfg, p$paths)
    map <- fpa_line_map(cfg, "pnl")
    fpa_anomaly_scan(p$finance$bs, p$finance$pnl, p$finance$cash, vol, hist, map, focus)
  }, error = function(e) NULL)
  if (!is.null(scan) && nrow(scan)) counts <- fpa_anomaly_counts(scan)
  n_fix <- as.integer(counts$act %||% 0L) + as.integer(counts$watch %||% 0L)
  saved <- length(fpa_shiny_saved_ids(fpa_shiny_confirm_read(p$config_path %||% "")))
  n_series <- if (!is.null(p$grades)) nrow(p$grades) else 0L
  drivers_open <- n_series > 0L && saved < n_series
  books_line <- if (is.null(scan) || !"family" %in% names(scan)) {
    fpa_screen("home_books_wait")
  } else if (!any(scan$family == "books" & scan$level != "clear")) {
    fpa_screen("home_books_ok")
  } else {
    fpa_screen("home_books_bad")
  }
  file_names <- character()
  for (nm in names(cfg$paths %||% list())) {
    if (identical(nm, "working_root_hint")) next
    fp <- as.character(cfg$paths[[nm]] %||% "")
    if (nzchar(fp) && file.exists(fp)) file_names <- c(file_names, basename(fp))
  }
  file_names <- unique(file_names)
  if (length(file_names) > 6L) file_names <- file_names[seq_len(6L)]
  next_txt <- if (drivers_open) {
    fpa_screen("home_next_drv", n_series - saved)
  } else if (n_fix > 0L) {
    fpa_screen("home_form", counts$act, counts$watch)
  } else {
    fpa_screen("home_next_month")
  }
  next_nav <- if (drivers_open) "Drivers" else if (n_fix > 0L) "Anomalies" else ""
  status_line <- shiny::tags$p(
    class = "fpa-home-status",
    shiny::tags$strong(if (nzchar(company)) company else fpa_screen("loc_company")),
    if (nzchar(closed)) paste0(fpa_screen("loc_chip_closed"), closed) else "",
    if (nzchar(when)) paste0(" · ", fpa_screen("home_when", when)) else "",
    " · ",
    if (length(newer)) fpa_screen("home_stale", paste(unique(newer), collapse = ", ")) else fpa_screen("home_fresh")
  )
  if (identical(mode, "slim")) return(status_line)
  steps_done <- !drivers_open && !length(newer)
  shiny::tags$section(
    class = "fpa-home",
    shiny::tags$details(
      class = "fpa-fold",
      shiny::tags$summary(fpa_screen("home_detail")),
      shiny::tags$p(if (length(file_names)) fpa_screen("home_files", paste(file_names, collapse = ", ")) else fpa_screen("home_when_none")),
      shiny::tags$p(books_line),
      shiny::tags$p(if (n_fix > 0L) fpa_screen("home_form", counts$act, counts$watch) else fpa_screen("home_clear")),
      if (steps_done) shiny::tags$p(fpa_screen("home_steps_done")) else shiny::tags$ol(
        class = "fpa-path-steps",
        shiny::tags$li(class = paste("fpa-path-step", if (drivers_open) "is-now" else "is-done"),
          shiny::tags$span(class = "fpa-path-num", if (drivers_open) "1" else fpa_shiny_check_svg(14)),
          shiny::tags$span(class = "fpa-path-step-body", shiny::tags$span(class = "fpa-path-step-label", "Drivers"), shiny::tags$span(class = "fpa-path-step-detail", if (drivers_open) fpa_screen("home_next_drv", n_series - saved) else fpa_screen("path_drv_all")))),
        shiny::tags$li(class = paste("fpa-path-step", if (!drivers_open && length(newer)) "is-now" else if (drivers_open) "is-later" else "is-done"),
          shiny::tags$span(class = "fpa-path-num", "2"),
          shiny::tags$span(class = "fpa-path-step-body", shiny::tags$span(class = "fpa-path-step-label", fpa_screen("loc_file_of_month")), shiny::tags$span(class = "fpa-path-step-detail", if (length(newer)) fpa_screen("home_stale", paste(unique(newer), collapse = ", ")) else fpa_screen("home_fresh")))),
        shiny::tags$li(class = paste("fpa-path-step", if (drivers_open) "is-later" else "is-now"),
          shiny::tags$span(class = "fpa-path-num", "3"),
          shiny::tags$span(class = "fpa-path-step-body", shiny::tags$span(class = "fpa-path-step-label", "Rapport"), shiny::tags$span(class = "fpa-path-step-detail", fpa_screen("home_month"))))
      )
    ),
    shiny::tags$p(next_txt),
    shiny::tags$div(
      class = "fpa-home-actions",
      shiny::downloadButton("mgmt_report", fpa_screen("home_report"), class = "fpa-path-btn"),
      if (nzchar(next_nav)) shiny::tags$button(
        type = "button",
        class = "fpa-path-btn",
        onclick = sprintf(
          "var a=document.querySelector('#main_nav a.nav-link[data-value=%s]'); if(a) a.click();",
          next_nav
        ),
        if (identical(next_nav, "Drivers")) fpa_screen("home_go_drv") else fpa_screen("home_go_anom")
      )
    )
  )
}

fpa_shiny_binding_for <- function(config, series_id) {
  binds <- config$driver_bindings %||% list()
  for (b in binds) {
    if (identical(as.character(b$series_id %||% ""), as.character(series_id))) return(b)
  }
  NULL
}

#' One screen for the verdict rule. The grade file is the source, not a spreadsheet.
fpa_shiny_driver_review <- function(grades, config, selected_id = "") {
  if (is.null(grades) || !nrow(grades)) {
    return(shiny::tags$p(fpa_screen("loc_no_drivers_engine")))
  }
  binds <- config$driver_bindings %||% list()
  notes <- lapply(binds, function(b) {
    sid <- as.character(b$series_id %||% "")
    hit <- grades[as.character(grades$series_id) == sid, , drop = FALSE]
    if (!nrow(hit)) return(NULL)
    g <- hit[1, , drop = FALSE]
    r <- fpa_shiny_num(g$evidence_r)
    lag <- fpa_shiny_num(g$causal_lag)
    partial <- fpa_shiny_num(g$independence_r)
    skill <- fpa_shiny_num(g$oos_skill)
    horizon <- fpa_shiny_num(g$usable_horizon_days)
    indep <- fpa_shiny_axis_mark(g, "independence")
    tested <- fpa_shiny_line_name(g$target_line)
    bound <- fpa_shiny_line_name(b$target_line)
    same <- identical(as.character(g$target_line), as.character(b$target_line %||% ""))
    usage <- if (identical(as.character(g$driver_class), "forecasting")) "prévoir" else "expliquer"
    tier_name <- c(mechanism = "Mécanisme", confirmed = "Confirmé", watch = "Veille")
    listed <- tier_name[[as.character(g$tier %||% "")]] %||% as.character(g$tier %||% g$verdict)
    body <- paste0(
      g$series_name, " est en ", listed,
      if (is.finite(fpa_shiny_num(g$score))) paste0(", score ", format(round(fpa_shiny_num(g$score), 2), nsmall = 2)) else "",
      fpa_screen("loc_calc_aims"), tested, ".",
      if (!same) paste0(fpa_screen("loc_config_said"), bound, ".") else "",
      fpa_screen("loc_resid_r"), if (is.finite(r)) format(round(r, 2), nsmall = 2) else "n/a",
      if (is.finite(lag)) paste0(fpa_screen("loc_to_glue"), ifelse(lag > 0, "+", ""), as.integer(lag), " mois") else "",
      ", usage ", usage, ".",
      if (identical(as.character(g$impact_status), "engine")) {
        paste0(fpa_screen("loc_oi_band_09"), fpa_shiny_eur(abs(fpa_shiny_num(g$impact_eur))), " EUR.")
      } else {
        ""
      },
      fpa_screen("loc_lag_suggestion")
    )
    shiny::tags$p(style = "margin:0 0 0.7rem;line-height:1.45;", body)
  })
  notes <- Filter(Negate(is.null), notes)
  head_style <- paste0(
    "position:sticky;top:0;background:#1f4e5f;color:#fff;font-weight:600;",
    "font-size:12.5px;padding:8px 10px;text-align:left;white-space:nowrap;"
  )
  if (!"tier" %in% names(grades)) grades$tier <- grades$verdict
  if (!"score" %in% names(grades)) grades$score <- NA_real_
  if (!"flag" %in% names(grades)) grades$flag <- ""
  tier_order <- c(mechanism = 1L, confirmed = 2L, watch = 3L)
  ord <- order(tier_order[as.character(grades$tier)], -suppressWarnings(as.numeric(grades$score)), na.last = TRUE)
  grades <- grades[ord, , drop = FALSE]
  tier_fr <- c(mechanism = "Mécanisme", confirmed = "Confirmé", watch = "Veille")
  rows <- lapply(seq_len(nrow(grades)), function(i) {
    g <- grades[i, , drop = FALSE]
    sid <- as.character(g$series_id)
    b <- fpa_shiny_binding_for(config, sid)
    on <- identical(sid, as.character(selected_id))
    mismatch <- !is.null(b) && !identical(as.character(g$target_line), as.character(b$target_line %||% ""))
    r <- fpa_shiny_num(g$evidence_r)
    lag <- fpa_shiny_num(g$causal_lag)
    proof <- if (!is.finite(r)) {
      fpa_screen("loc_not_calculated")
    } else {
      paste0(format(round(r, 2), nsmall = 2), if (is.finite(lag)) paste0(fpa_screen("loc_to_glue"), ifelse(lag > 0, "+", ""), as.integer(lag), " mois") else "")
    }
    indep <- fpa_shiny_axis_mark(g, "independence")
    indep_txt <- if (indep %in% c("Non disponible", fpa_screen("drv_indep_na"))) "Non faite" else if (identical(indep, fpa_screen("drv_pass"))) "Passe" else "Sous le seuil"
    impact <- if (identical(as.character(g$impact_status), "engine") && is.finite(fpa_shiny_num(g$impact_eur))) {
      paste0(fpa_shiny_eur(abs(fpa_shiny_num(g$impact_eur))), " EUR")
    } else {
      "Pas chiffré"
    }
    tier_col <- switch(
      as.character(g$tier),
      mechanism = "#1f4e5f",
      confirmed = "#1f4e5f",
      watch = "#8a5a00",
      "#3d4c54"
    )
    score_txt <- if (is.finite(fpa_shiny_num(g$score))) format(round(fpa_shiny_num(g$score), 2), nsmall = 2) else ""
    shiny::tags$tr(
      style = paste0(if (i %% 2 == 0) "background:#f6f9fa;" else "", if (on) "box-shadow:inset 3px 0 0 #c47b2b;" else ""),
      shiny::tags$td(style = "padding:7px 10px;font-weight:600;white-space:nowrap;", g$series_name),
      fpa_shiny_use_cell(g),
      shiny::tags$td(style = paste0("padding:7px 10px;font-weight:700;color:", tier_col, ";white-space:nowrap;"), tier_fr[[as.character(g$tier)]] %||% g$tier),
      shiny::tags$td(style = "padding:7px 10px;font-variant-numeric:tabular-nums;", score_txt),
      shiny::tags$td(style = "padding:7px 10px;white-space:nowrap;", if (identical(as.character(g$driver_class), "forecasting")) "Prévoir" else "Expliquer"),
      shiny::tags$td(style = "padding:7px 10px;", fpa_shiny_line_name(g$target_line)),
      shiny::tags$td(
        style = paste0("padding:7px 10px;", if (mismatch) "color:#8a5a00;font-weight:700;" else ""),
        if (is.null(b)) "Aucun" else fpa_shiny_line_name(b$target_line)
      ),
      shiny::tags$td(style = "padding:7px 10px;font-variant-numeric:tabular-nums;white-space:nowrap;", proof),
      shiny::tags$td(style = paste0("padding:7px 10px;color:", if (identical(indep, fpa_screen("drv_fail"))) "#8c3a3a" else "#1a2b32", ";"), indep_txt),
      shiny::tags$td(style = "padding:7px 10px;white-space:nowrap;", impact),
      shiny::tags$td(style = "padding:7px 10px;white-space:nowrap;", g$flag)
    )
  })
  shiny::tagList(
    shiny::tags$p(
      style = "margin:0.2rem 0 0.8rem;color:#3d4c54;line-height:1.45;",
      fpa_screen("drv_review_lead")
    ),
    if (length(notes)) shiny::tags$details(
      class = "fpa-drv-fold-lite",
      shiny::tags$summary(fpa_screen("drv_review_notes", length(notes))),
      shiny::tags$div(
        style = "border:1px solid #e0cba8;background:#fdf6ea;border-radius:8px;padding:12px 14px;margin:0.4rem 0 0.9rem;",
        notes
      )
    ) else shiny::tags$p(fpa_screen("loc_no_mechanism_cfg")),
    shiny::tags$div(
      style = "border:1px solid #d6e1e5;border-radius:8px;overflow:auto;",
      shiny::tags$table(
        style = "width:100%;border-collapse:collapse;font-size:13px;",
        shiny::tags$thead(
          shiny::tags$tr(
            lapply(
              c("Série", "Décision", "Liste", "Score", "Usage", fpa_screen("loc_line_tested"), "Mécanisme", "Preuve", fpa_screen("loc_independence"), "Impact", "Signal"),
              function(lab) shiny::tags$th(style = head_style, lab)
            )
          )
        ),
        shiny::tags$tbody(rows)
      )
    )
  )
}

#' The driver map. Every number comes from the grade file. A gap stays a gap.
fpa_shiny_graph_box <- function(grades) {
  if (is.null(grades) || !nrow(grades)) return(NULL)
  fr_r <- function(x) {
    x <- fpa_shiny_num(x)
    if (!is.finite(x)) return("\u2014")
    paste0(if (x > 0) "+" else "", fpa_shiny_fr_num(x, 2))
  }
  fact <- function(lab, val, key) {
    shiny::tags$span(
      class = "fpa-g-fact fpa-term-box", tabindex = "0",
      `data-tip` = fpa_screen(paste0("drv_tip_", key)),
      shiny::tags$em(lab), val
    )
  }
  tier_fr <- c(mechanism = "M\u00e9canisme", confirmed = "Confirm\u00e9", watch = "Veille")
  cards <- lapply(seq_len(nrow(grades)), function(i) {
    g <- grades[i, , drop = FALSE]
    sid <- gsub("[^A-Za-z0-9_-]", "", as.character(g$series_id))
    tier <- as.character(g$tier[[1]] %||% "")
    tier_lab <- unname(tier_fr[[tier]])
    if (is.null(tier_lab) || is.na(tier_lab)) tier_lab <- ""
    saved_v <- if ("saved_verdict" %in% names(g)) as.character(g$saved_verdict[[1]] %||% "") else ""
    mech <- "relation" %in% names(g) && as.character(g$relation[[1]]) %in% c("part_whole", "derived")
    facts_of <- function(goal) {
      f <- fpa_shiny_goal_fields(goal)
      v <- function(key) if (f[[key]] %in% names(g)) fpa_shiny_num(g[[f[[key]]]]) else NA_real_
      n <- v("n")
      r <- v("r")
      lag <- v("lag")
      rank <- v("rank")
      lag_txt <- if (!is.finite(r) || !is.finite(lag)) "\u2014" else if (lag > 0) paste0("+", as.integer(lag)) else as.character(as.integer(lag))
      shiny::tags$div(
        class = "fpa-g-box-facts",
        fact("Mois", if (is.finite(n)) as.character(as.integer(n)) else "\u2014", "mois"),
        fact("D\u00e9calage", lag_txt, "lag"),
        fact("r", fr_r(r), "r"),
        fact("r partiel", fr_r(v("partial")), "partial"),
        fact("Rang", if (is.finite(rank)) paste0(fpa_shiny_fr_num(rank * 100, 1), " %") else "\u2014", "rank")
      )
    }
    shiny::tags$div(
      class = "fpa-g-box-card",
      `data-id` = sid,
      shiny::tags$div(
        class = "fpa-g-box-head",
        shiny::tags$strong(fpa_shiny_bottom_label(g$series_name)),
        shiny::tags$span(
          class = paste("fpa-g-box-tier", paste0("is-", tier)),
          `data-tip` = fpa_drv_tier_tip(tier),
          tier_lab
        )
      ),
      shiny::tags$p(
        class = "fpa-g-box-goal",
        fpa_screen("drv_box_against", fpa_shiny_line_name(g$target_line)),
        if (mech) shiny::tags$span(class = "fpa-g-box-note", fpa_screen("drv_box_mech"))
      ),
      facts_of("line"),
      shiny::tags$p(class = "fpa-g-box-goal", fpa_screen("drv_bottom_title")),
      facts_of("oi"),
      shiny::tags$p(
        class = "fpa-g-box-line",
        fpa_drv_term("soutien"), " : ", tolower(fpa_shiny_axis_mark(g, "evidence")),
        " \u00b7 ", fpa_drv_term("indep"), " : ", tolower(fpa_shiny_axis_mark(g, "independence")),
        " \u00b7 ", fpa_drv_term("resultat"), " : ", tolower(fpa_shiny_axis_mark(g, "result"))
      ),
      if (nzchar(saved_v)) shiny::tags$p(
        class = "fpa-g-box-yours",
        fpa_screen("drv_box_yours", fpa_shiny_verdict_fr(saved_v))
      )
    )
  })
  shiny::div(id = "fpaGraphBox", class = "fpa-g-box", cards)
}

fpa_shiny_driver_map <- function(grades, candidates, shares = NULL) {
  if (is.null(grades) || !nrow(grades)) {
    return(shiny::tags$p(fpa_screen("loc_no_drivers_engine")))
  }
  if (!"tier" %in% names(grades)) grades$tier <- ""
  if (!"flag" %in% names(grades)) grades$flag <- ""
  vol <- fpa_driver_map_volume(candidates, grades)
  heat_score <- fpa_driver_map_heat(grades, "score")
  heat_partial <- fpa_driver_map_heat(grades, "partial")
  heat_euro <- fpa_driver_map_heat(grades, "euro")
  flags <- fpa_driver_map_flags(grades)
  links <- fpa_driver_map_layout(fpa_driver_map_links(grades))
  bottom_r_of <- if ("bottom_r" %in% names(grades)) {
    stats::setNames(suppressWarnings(as.numeric(grades$bottom_r)), as.character(grades$series_id))
  } else {
    numeric()
  }
  bottom_sig_of <- if ("bottom_sig" %in% names(grades)) {
    stats::setNames(fpa_driver_map_as_flag(grades$bottom_sig), as.character(grades$series_id))
  } else {
    logical()
  }
  bottom_n_of <- if ("bottom_n" %in% names(grades)) {
    stats::setNames(suppressWarnings(as.integer(grades$bottom_n)), as.character(grades$series_id))
  } else {
    integer()
  }
  edge_of <- function(g) {
    fpa_driver_map_edge_kind(g$r, g$n, g$r_crit, g$sig, g$target_line, g$series_name)
  }
  edge_words <- function(kind) {
    switch(kind$kind,
      constant = fpa_screen("drv_map_constant"),
      noise = fpa_screen("drv_map_noise", kind$n),
      pay_down = fpa_screen("drv_map_pay_down"),
      pay_up = fpa_screen("drv_map_pay_up"),
      pay_factor = fpa_screen("drv_map_pay_factor"),
      ""
    )
  }
  result_words <- function(sid) {
    b_r <- unname(bottom_r_of[sid])
    b_sig <- unname(bottom_sig_of[sid])
    b_n <- unname(bottom_n_of[sid])
    kind <- fpa_driver_map_edge_kind(b_r, b_n, NA_real_, b_sig, "")
    if (identical(kind$kind, "noise")) return(fpa_screen("drv_map_noise", kind$n))
    if (length(b_r) == 1L && is.finite(b_r)) {
      return(paste0(if (b_r > 0) "+" else "", fpa_shiny_fr_num(b_r, 2)))
    }
    ""
  }

  jump <- function(id, tab) {
    safe <- gsub("[^A-Za-z0-9_-]", "", as.character(id))
    sprintf(
      "Shiny.setInputValue('map_jump', {id:'%s', tab:'%s'}, {priority:'event'})",
      safe, tab
    )
  }
  fmt_score <- function(v) format(round(v, 2), nsmall = 2)
  fmt_r <- function(v) {
    v <- suppressWarnings(as.numeric(v))
    if (length(v) != 1L || !is.finite(v)) return("\u2014")
    paste0(if (v > 0) "+" else "", fpa_shiny_fr_num(v, 2))
  }
  tier_fr <- c(mechanism = "Mécanisme", confirmed = "Confirmé", watch = "Veille")
  read_cell <- function(row, kind) {
    sid <- as.character(row$series_id)
    name <- as.character(row$series_name)
    missing <- !identical(as.character(row$state), "value")
    v <- suppressWarnings(as.numeric(row$value))
    label <- fpa_driver_map_cell_label(kind, row$state, v)
    note <- if (identical(kind, "score")) fpa_driver_map_score_note(row$score_kind) else ""
    if (missing) {
      ink <- NULL
    } else if (identical(kind, "score")) {
      ink <- fpa_driver_map_score_ink(v)
    } else if (identical(kind, "partial")) {
      cap <- max(abs(heat_partial$value), na.rm = TRUE)
      ink <- fpa_driver_map_signed_ink(v, cap)
    } else {
      cap <- max(abs(heat_euro$value), na.rm = TRUE)
      ink <- fpa_driver_map_signed_ink(v, cap)
    }
    shiny::tags$button(
      type = "button",
      class = if (missing) "fpa-read-cell is-gap" else "fpa-read-cell",
      style = if (is.null(ink)) NULL else paste0("background:", ink$bg, ";color:", ink$fg, ";"),
      onclick = jump(sid, "Fiche"),
      title = paste(fpa_screen("loc_open_card_of"), name),
      shiny::tags$span(class = "fpa-read-val", label),
      if (nzchar(note)) shiny::tags$span(class = "fpa-read-note", note)
    )
  }
  count_fixed <- function(labels, order) {
    labels <- as.character(labels)
    bits <- character(0)
    for (lab in order) {
      n <- sum(labels == lab, na.rm = TRUE)
      if (n > 0L) bits <- c(bits, paste(n, lab))
    }
    paste(bits, collapse = " · ")
  }
  score_labs <- ifelse(
    heat_score$score_kind == "prior", "prior",
    ifelse(
      heat_score$score_kind == "mix", "mesuré",
      ifelse(heat_score$score_kind == "held", "sans mesure",
        ifelse(heat_score$score_kind == "missing", "sans score", ""))
    )
  )
  partial_labs <- ifelse(heat_partial$state == "value", "mesuré", "non mesuré")
  euro_labs <- ifelse(heat_euro$state == "value", "chiffré", "pas chiffré")
  engine_euro <- "impact_status" %in% names(grades) &&
    any(as.character(grades$impact_status) == "engine" & is.finite(suppressWarnings(as.numeric(grades$impact_eur))))
  euro_sub <- if (engine_euro) fpa_screen("readings_euro") else fpa_screen("readings_euro_hist")
  vol_sub <- if (nzchar(vol$name)) fpa_screen("readings_partial", vol$name) else fpa_screen("readings_partial_none")
  head_col <- function(n, title, question, sub, count) {
    shiny::tags$div(
      class = "fpa-read-head",
      shiny::tags$div(
        class = "fpa-read-title",
        shiny::tags$span(class = "fpa-read-n", as.character(n)),
        title
      ),
      shiny::tags$div(class = "fpa-read-q", question),
      shiny::tags$div(class = "fpa-read-sub", sub),
      shiny::tags$div(class = "fpa-read-count", count)
    )
  }
  ids <- as.character(heat_score$series_id)
  part_rows <- heat_partial[match(ids, as.character(heat_partial$series_id)), , drop = FALSE]
  euro_rows <- heat_euro[match(ids, as.character(heat_euro$series_id)), , drop = FALSE]
  row_tags <- lapply(seq_len(nrow(heat_score)), function(i) {
    g <- heat_score[i, , drop = FALSE]
    tier_lab <- unname(tier_fr[as.character(g$tier)])
    if (length(tier_lab) != 1L || is.na(tier_lab)) tier_lab <- ""
    list(
      shiny::tags$button(
        type = "button",
        class = "fpa-read-series",
        onclick = jump(g$series_id, "Fiche"),
        title = paste(fpa_screen("loc_open_card_of"), g$series_name),
        shiny::tags$span(class = "fpa-read-series-name", fpa_shiny_bottom_label(g$series_name)),
        if (nzchar(tier_lab)) shiny::tags$span(class = "fpa-read-series-tier", tier_lab)
      ),
      read_cell(g, "score"),
      read_cell(part_rows[i, , drop = FALSE], "partial"),
      read_cell(euro_rows[i, , drop = FALSE], "euro")
    )
  })
  lead_bits <- strsplit(fpa_screen("readings_lead"), "\n", fixed = TRUE)[[1]]
  readings <- shiny::tags$div(
    class = "fpa-read-wrap",
    shiny::tags$div(
      class = "fpa-read-lead",
      lapply(lead_bits, function(bit) shiny::tags$p(bit))
    ),
    shiny::tags$div(
      class = "fpa-read",
      shiny::tags$div(
        class = "fpa-read-head fpa-read-head-name",
        shiny::tags$div(class = "fpa-read-title", fpa_drv_term("serie", "Série")),
        shiny::tags$div(class = "fpa-read-sub", fpa_screen("drv_read_series_sub"))
      ),
      head_col(
        "1", fpa_drv_term("score", "Soutien"),
        fpa_screen("loc_data_support"),
        fpa_screen("readings_score"),
        count_fixed(score_labs, c("prior", "mesuré", "sans mesure", "sans score"))
      ),
      head_col(
        "2", fpa_drv_term("partial", "Hors volume"),
        fpa_screen("loc_link_volume"),
        vol_sub,
        count_fixed(partial_labs, c("mesuré", "non mesuré"))
      ),
      head_col(
        "3", "Euros",
        fpa_screen("loc_how_far_series"),
        euro_sub,
        count_fixed(euro_labs, c("chiffré", "pas chiffré"))
      ),
      row_tags
    )
  )
  chip <- function(g) {
    sc <- suppressWarnings(as.numeric(g$score))
    shiny::tags$button(
      type = "button",
      class = "fpa-drv-chip",
      onclick = jump(g$series_id, "Fiche"),
      shiny::tags$span(class = "fpa-drv-chip-name", fpa_shiny_bottom_label(g$series_name)),
      shiny::tags$span(class = "fpa-drv-chip-score", if (is.finite(sc)) fmt_score(sc) else "")
    )
  }
  tier_block <- function(id, title, blurb) {
    sub <- grades[as.character(grades$tier) == id, , drop = FALSE]
    if (nrow(sub)) {
      sub <- sub[order(-suppressWarnings(as.numeric(sub$score)), sub$series_name), , drop = FALSE]
    }
    shiny::tags$div(
      class = "fpa-drv-col",
      shiny::tags$h4(shiny::tags$span(class = "fpa-term", tabindex = "0", `data-tip` = fpa_drv_tier_tip(id), title), paste0(" · ", nrow(sub))),
      shiny::tags$p(blurb),
      if (nrow(sub)) shiny::tags$div(lapply(seq_len(nrow(sub)), function(i) chip(sub[i, , drop = FALSE]))) else shiny::tags$p(class = "fpa-drv-empty", fpa_screen("drv_tier_empty"))
    )
  }
  flag_title <- c(
    identite = fpa_screen("drv_flag_identite_t"),
    "arrive tard" = fpa_screen("drv_flag_late_t"),
    doublon = fpa_screen("drv_flag_double_t"),
    "sens inverse" = fpa_screen("drv_flag_reverse_t")
  )
  flag_body <- c(
    identite = fpa_screen("drv_flag_identite"),
    "arrive tard" = fpa_screen("drv_flag_late"),
    doublon = fpa_screen("drv_flag_double"),
    "sens inverse" = fpa_screen("drv_flag_reverse")
  )
  head_style <- paste0(
    "position:sticky;top:0;background:#1f4e5f;color:#fff;font-weight:600;",
    "font-size:12.5px;padding:8px 10px;text-align:left;white-space:nowrap;"
  )
  num_style <- "padding:6px 10px;text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap;"
  show_euro_col <- any(links$euro_state == "value")
  link_rows <- lapply(seq_len(nrow(links)), function(i) {
    g <- links[i, , drop = FALSE]
    lag <- suppressWarnings(as.numeric(g$lag))
    lag_status <- as.character(g$lag_status)
    lag_txt <- if (!is.finite(lag) || identical(lag_status, "not_distinguishable")) {
      fpa_screen("loc_not_separated")
    } else if (identical(lag_status, "suggested")) {
      paste0(if (lag > 0) "+" else "", as.integer(lag), fpa_screen("loc_months_suggested"))
    } else if (identical(lag_status, "refused_reverse_causality")) {
      paste0(if (lag > 0) "+" else "", as.integer(lag), fpa_screen("loc_months_refused"))
    } else {
      paste0(if (lag > 0) "+" else "", as.integer(lag), " mois")
    }
    euro_cell <- if (!show_euro_col) {
      NULL
    } else if (identical(as.character(g$euro_state), "value")) {
      shiny::tags$td(
        style = paste0(num_style, if (g$euro < 0) "color:#8c3a3a;" else "color:#1a2b32;", "font-weight:600;"),
        paste0(fpa_shiny_eur(g$euro), " EUR")
      )
    } else {
      shiny::tags$td(style = paste0(num_style, "color:#5c6b73;"), "Pas chiffré")
    }
    bg <- if (i %% 2 == 0) "background:#f6f9fa;" else ""
    shiny::tags$tr(
      style = bg,
      shiny::tags$td(
        style = "padding:6px 10px;font-weight:600;white-space:nowrap;",
        shiny::tags$button(type = "button", class = "fpa-drv-link", onclick = jump(g$series_id, "Fiche"), fpa_shiny_bottom_label(g$series_name))
      ),
      shiny::tags$td(style = "padding:6px 10px;", fpa_shiny_line_name(g$target_line)),
      shiny::tags$td(style = num_style, lag_txt),
      shiny::tags$td(style = num_style, {
        kind <- edge_of(g)
        words <- edge_words(kind)
        if (nzchar(words)) words else fmt_r(g$r)
      }),
      shiny::tags$td(style = num_style, {
        words <- result_words(as.character(g$series_id))
        if (nzchar(words)) words else "\u2014"
      }),
      euro_cell
    )
  })
  link_capped <- fpa_shiny_cap_rows(link_rows, 8L)
  card_h <- 52
  card_w <- 196
  left_x <- 12
  line_x <- 380
  line_w <- 170
  gate_w <- 128
  mb_x <- 620
  ebe_x <- 820
  oi_x <- 1020
  oi_w <- 150
  plot_w <- 1180
  tier_of <- if (nrow(grades)) {
    stats::setNames(as.character(grades$tier), as.character(grades$series_id))
  } else {
    character()
  }
  tier_fr <- c(mechanism = "Mécanisme", confirmed = "Confirmé", watch = "Veille")
  sid_tier <- function(sid) {
    t <- unname(tier_of[[as.character(sid)]])
    if (length(t) != 1L || is.na(t)) "" else as.character(t)
  }
  kept_n <- if (nrow(links)) {
    sum(vapply(as.character(links$series_id), function(sid) sid_tier(sid) %in% c("mechanism", "confirmed"), logical(1)))
  } else {
    0L
  }
  watch_n <- if (nrow(links)) {
    sum(vapply(as.character(links$series_id), function(sid) identical(sid_tier(sid), "watch"), logical(1)))
  } else {
    0L
  }
  pal_of <- function(tier) {
    if (identical(tier, "mechanism")) {
      return(list(fill = "#e6f1f4", stroke = "#1f4e5f", fg = "#0f2f3a", sub = "#1f4e5f"))
    }
    if (identical(tier, "confirmed")) {
      return(list(fill = "#1f4e5f", stroke = "#163844", fg = "#ffffff", sub = "#d6e7ec"))
    }
    if (identical(tier, "watch")) {
      return(list(fill = "#fdf6ea", stroke = "#c47b2b", fg = "#5a4420", sub = "#8a5a00"))
    }
    list(fill = "#f4f7f8", stroke = "#d6e1e5", fg = "#1a2b32", sub = "#5c6b73")
  }
  bez <- function(x0, y0, x1, y1) {
    c1 <- x0 + (x1 - x0) * 0.45
    c2 <- x0 + (x1 - x0) * 0.55
    sprintf(
      "M %.1f %.1f C %.1f %.1f, %.1f %.1f, %.1f %.1f",
      x0, y0, c1, y0, c2, y1, x1, y1
    )
  }
  bez_at <- function(x0, y0, x1, y1, t = 0.42) {
    c1 <- x0 + (x1 - x0) * 0.45
    c2 <- x0 + (x1 - x0) * 0.55
    u <- 1 - t
    list(
      x = u^3 * x0 + 3 * u^2 * t * c1 + 3 * u * t^2 * c2 + t^3 * x1,
      y = u^3 * y0 + 3 * u^2 * t * y0 + 3 * u * t^2 * y1 + t^3 * y1
    )
  }
  pill <- function(x, y, lab, bg, fg, class, sid = NULL, line = NULL, tip = NULL, tier = NULL) {
    w <- nchar(lab) * 6.4 + 16
    shiny::tags$g(
      class = class,
      `data-id` = sid,
      `data-line` = line,
      `data-tier` = if (!is.null(tier) && nzchar(tier)) tier else NULL,
      `data-tip` = if (!is.null(tip) && nzchar(tip)) tip else NULL,
      shiny::tags$rect(
        x = x - w / 2, y = y - 11, width = w, height = 20, rx = 6,
        fill = bg, stroke = bg
      ),
      shiny::tags$text(
        x = x, y = y + 4, `text-anchor` = "middle",
        fill = fg, `font-size` = "11", `font-weight` = "700",
        lab
      )
    )
  }
  line_euro <- fpa_driver_map_line_euro(links)
  y_oi <- if (nrow(links)) mean(unique(links$y_right)) else 80
  gate_of <- function(ln) {
    ln <- as.character(ln)
    if (ln %in% c("REV", "OTHER_OP_INC", "COGS")) return("GP")
    if (ln %in% c("PAYROLL", "OPEX_OTHER")) return("EBITDA")
    "OI"
  }
  all_lines <- unique(as.character(links$target_line))
  sh_ok <- !is.null(shares) && isTRUE(shares$ok)
  node_ok <- function(node) {
    sh_ok && is.finite(shares$nodes[[node]]$gap %||% NA_real_) && shares$nodes[[node]]$gap < 2
  }
  share_in <- function(node, part) {
    if (!node_ok(node)) return(NA_real_)
    v <- shares$nodes[[node]]$pct[part]
    if (length(v) != 1L || is.na(v)) NA_real_ else unname(v) / 100
  }
  is_fixed <- function(id) sh_ok && id %in% shares$fixed
  share_ink <- function(v, id) {
    if (is_fixed(id) || !is.finite(v) || abs(v) < 0.005) return(list(bg = "#e6edef", fg = "#3d4c54"))
    if (v < 0) list(bg = "#8c3a3a", fg = "#ffffff") else list(bg = "#1f4e5f", fg = "#ffffff")
  }
  oi_sub <- function(id) {
    v <- if (sh_ok) unname(shares$to_oi_pct[id]) / 100 else NA_real_
    txt <- fpa_driver_map_share_txt(if (is_fixed(id)) 0 else v)
    bits <- c(if (is_fixed(id)) fpa_screen("drv_map_fixed"), if (nzchar(txt)) fpa_screen("drv_map_oi_share", txt))
    paste(bits, collapse = " \u00b7 ")
  }
  absorb_col <- c(OTHER_OP_INC = "line", COGS = "line", PAYROLL = "mb", OPEX_OTHER = "mb", D_A = "ebe")
  absorb_ids <- if (sh_ok) setdiff(names(absorb_col), c(all_lines, shares$zero)) else character(0)
  absorb_y <- stats::setNames(numeric(length(absorb_ids)), absorb_ids)
  next_line_y <- if (nrow(links)) max(links$y_right) + 76 else 70
  for (id in absorb_ids[absorb_col[absorb_ids] == "line"]) {
    absorb_y[[id]] <- next_line_y
    next_line_y <- next_line_y + 76
  }
  gp_lines <- all_lines[vapply(all_lines, gate_of, character(1)) == "GP"]
  ebe_lines <- all_lines[vapply(all_lines, gate_of, character(1)) == "EBITDA"]
  gp_absorb <- absorb_ids[vapply(absorb_ids, gate_of, character(1)) == "GP"]
  ebe_absorb <- absorb_ids[vapply(absorb_ids, gate_of, character(1)) == "EBITDA"]
  gp_all <- c(gp_lines, gp_absorb)
  ebe_all <- c(ebe_lines, ebe_absorb)
  gp_ys <- c(links$y_right[links$target_line %in% gp_lines], absorb_y[gp_absorb])
  gp_y <- if (length(gp_ys)) mean(gp_ys) else y_oi
  gate_y <- c(GP = gp_y, EBITDA = y_oi, OI = y_oi)
  k <- 0
  for (id in absorb_ids[absorb_col[absorb_ids] == "mb"]) {
    k <- k + 1
    absorb_y[[id]] <- gp_y + 84 * k
  }
  for (id in absorb_ids[absorb_col[absorb_ids] == "ebe"]) absorb_y[[id]] <- y_oi + 84
  absorb_x <- c(line = line_x, mb = mb_x, ebe = ebe_x)
  absorb_w <- c(line = line_w, mb = gate_w, ebe = gate_w)
  svg_h <- if (nrow(links)) max(links$y_left) + card_h else 80
  if (length(absorb_y)) svg_h <- max(svg_h, max(absorb_y) + 40)
  svg_edges <- lapply(seq_len(nrow(links)), function(i) {
    g <- links[i, , drop = FALSE]
    sid <- as.character(g$series_id)
    has_euro <- identical(as.character(g$euro_state), "value")
    shiny::tags$path(
      class = "fpa-g-edge",
      d = bez(left_x + card_w, g$y_left, line_x, g$y_right),
      fill = "none",
      stroke = if (has_euro && is.finite(g$euro) && g$euro < 0) "#8c3a3a" else "#1f4e5f",
      `stroke-width` = if (has_euro) "2.4" else "1.5",
      `data-id` = sid,
      `data-line` = as.character(g$target_line),
      `data-tier` = sid_tier(sid)
    )
  })
  svg_euros <- lapply(seq_len(nrow(links)), function(i) {
    g <- links[i, , drop = FALSE]
    kind <- edge_of(g)
    words <- edge_words(kind)
    lab <- if (nzchar(words)) {
      if (identical(as.character(g$euro_state), "value") && is.finite(g$euro)) {
        paste0(words, " · ", format(round(g$euro), big.mark = " ", scientific = FALSE, trim = TRUE), " EUR")
      } else words
    } else {
      fpa_driver_map_edge_tag(g$r, g$euro, g$euro_state)
    }
    if (!nzchar(lab)) return(NULL)
    is_mech <- identical(kind$kind, "r") && identical(unname(tier_of[as.character(g$series_id)]), "mechanism")
    if (is_mech) lab <- paste0(lab, " · attendu")
    same <- which(links$target_line == g$target_line)
    t <- if (length(same) <= 1L) 0.42 else 0.33
    at <- bez_at(left_x + card_w, g$y_left, line_x, g$y_right, t)
    half <- (nchar(lab) * 6.4 + 16) / 2
    at$x <- min(max(at$x, left_x + card_w + 6 + half), line_x - 6 - half)
    r_val <- suppressWarnings(as.numeric(g$r))
    if (kind$kind %in% c("noise", "constant")) {
      ink <- list(bg = "#e6edef", fg = "#3d4c54")
    } else if (is_mech) {
      ink <- list(bg = "#e6edef", fg = "#3d4c54")
    } else if (is.finite(r_val)) {
      ink <- fpa_driver_map_r_ink(r_val)
    } else if (identical(as.character(g$euro_state), "value") && is.finite(g$euro) && g$euro < 0) {
      ink <- list(bg = "#8c3a3a", fg = "#ffffff")
    } else {
      ink <- list(bg = "#1f4e5f", fg = "#ffffff")
    }
    tip_key <- switch(kind$kind,
      constant = "constante", noise = "bruit", pay_factor = "plus_cout",
      pay_down = "residu", pay_up = "residu",
      if (is_mech) "attendu" else "r"
    )
    pill(at$x, at$y, lab, ink$bg, ink$fg, "fpa-g-edge", as.character(g$series_id), as.character(g$target_line),
         tip = fpa_screen(paste0("drv_tip_", tip_key)), tier = sid_tier(g$series_id))
  })
  left_nodes <- lapply(seq_len(nrow(links)), function(i) {
    g <- links[i, , drop = FALSE]
    sid <- as.character(g$series_id)
    tier <- unname(tier_of[[sid]])
    if (is.null(tier) || is.na(tier)) tier <- ""
    pal <- pal_of(tier)
    lab <- unname(tier_fr[[tier]])
    if (is.null(lab)) lab <- ""
    rw <- result_words(sid)
    if (!nzchar(rw) && identical(edge_of(g)$kind, "constant")) rw <- fpa_screen("drv_map_constant")
    if (nzchar(rw)) {
      prefix <- if (grepl("^bruit", rw)) fpa_screen("loc_result_colon") else fpa_screen("loc_result_r")
      if (identical(rw, fpa_screen("drv_map_constant"))) prefix <- ""
      lab <- paste0(lab, if (nzchar(lab) && nzchar(prefix)) " · " else if (nzchar(lab) && !nzchar(prefix)) " · " else "", prefix, rw)
    }
    shiny::tags$g(
      class = "fpa-g-card",
      `data-id` = sid,
      `data-line` = as.character(g$target_line),
      `data-tier` = tier,
      onclick = sprintf("fpaGraphFocus('%s','%s')", gsub("[^A-Za-z0-9_-]", "", sid), gsub("[^A-Z0-9_]", "", as.character(g$target_line))),
      shiny::tags$rect(
        x = left_x, y = g$y_left - card_h / 2, width = card_w, height = card_h, rx = 8,
        fill = pal$fill, stroke = pal$stroke, `stroke-width` = "1.4"
      ),
      shiny::tags$text(
        x = left_x + 12, y = g$y_left - 4,
        fill = pal$fg, `font-size` = "13.5", `font-weight` = "700",
        fpa_shiny_bottom_label(g$series_name)
      ),
      shiny::tags$text(
        x = left_x + 12, y = g$y_left + 14,
        fill = pal$sub, `font-size` = "11",
        lab
      )
    )
  })
  right_lines <- unique(links$target_line)
  right_nodes <- lapply(right_lines, function(ln) {
    y <- links$y_right[match(ln, links$target_line)]
    shiny::tags$g(
      class = "fpa-g-out",
      `data-line` = as.character(ln),
      onclick = sprintf("fpaGraphFocusLine('%s')", gsub("[^A-Z0-9_]", "", as.character(ln))),
      shiny::tags$rect(
        x = line_x, y = y - 28, width = line_w, height = 56, rx = 8,
        fill = "#0f2f3a", stroke = "#0f2f3a"
      ),
      shiny::tags$text(
        x = line_x + 12, y = y - 2,
        fill = "#ffffff", `font-size` = "13", `font-weight` = "700",
        fpa_shiny_line_name(ln)
      ),
      shiny::tags$text(
        x = line_x + 12, y = y + 16,
        fill = "#b7cdd4", `font-size` = "11",
        {
          verb <- if (identical(gate_of(ln), "GP") && !identical(as.character(ln), "COGS")) "s'ajoute" else "se déduit"
          tail <- if (sh_ok) oi_sub(as.character(ln)) else ""
          if (nzchar(tail)) paste0(verb, " \u00b7 ", tail) else paste0(fpa_screen("loc_line_aimed_dot"), verb)
        }
      )
    )
  })
  gate_x <- c(GP = mb_x, EBITDA = ebe_x, OI = oi_x)
  final_edges <- lapply(right_lines, function(ln) {
    y0 <- links$y_right[match(ln, links$target_line)]
    gate <- gate_of(ln)
    shiny::tags$path(
      class = "fpa-g-final",
      d = bez(line_x + line_w, y0, gate_x[[gate]], gate_y[[gate]]),
      fill = "none",
      stroke = "#0f2f3a",
      `stroke-width` = "1.8",
      `data-line` = as.character(ln)
    )
  })
  chain_edge <- function(x0, y0, x1, y1, lines_on) {
    shiny::tags$path(
      class = "fpa-g-final",
      d = bez(x0, y0, x1, y1),
      fill = "none",
      stroke = "#0f2f3a",
      `stroke-width` = "2.2",
      `data-line` = paste(lines_on, collapse = " ")
    )
  }
  chain_edges <- list(
    if (length(gp_all)) chain_edge(mb_x + gate_w, gate_y[["GP"]], ebe_x, gate_y[["EBITDA"]], gp_all),
    if (length(c(gp_all, ebe_all))) chain_edge(ebe_x + gate_w, gate_y[["EBITDA"]], oi_x, y_oi, c(gp_all, ebe_all))
  )
  chain_pill <- function(x0, y0, x1, y1, node, part, lines_on) {
    v <- share_in(node, part)
    lab <- fpa_driver_map_share_txt(v)
    if (!nzchar(lab)) return(NULL)
    at <- bez_at(x0, y0, x1, y1, 0.5)
    ink <- share_ink(v, part)
    pill(at$x, at$y, lab, ink$bg, ink$fg, "fpa-g-final", line = paste(lines_on, collapse = " "), tip = fpa_screen("drv_tip_part"))
  }
  chain_tags <- if (sh_ok) list(
    if (length(gp_all)) chain_pill(mb_x + gate_w, gate_y[["GP"]], ebe_x, gate_y[["EBITDA"]], "EBITDA", "GP", gp_all),
    if (length(c(gp_all, ebe_all))) chain_pill(ebe_x + gate_w, gate_y[["EBITDA"]], oi_x, y_oi, "OI", "EBITDA", c(gp_all, ebe_all))
  )
  absorb_nodes <- lapply(absorb_ids, function(id) {
    col <- absorb_col[[id]]
    x <- absorb_x[[col]]
    w <- absorb_w[[col]]
    y <- absorb_y[[id]]
    gate <- gate_of(id)
    x1 <- gate_x[[gate]]
    y1 <- if (identical(gate, "OI")) y_oi else gate_y[[gate]]
    v <- share_in(gate, id)
    lab <- fpa_driver_map_share_txt(if (is_fixed(id)) 0 else v)
    at <- bez_at(x + w, y, x1, y1, 0.5)
    ink <- share_ink(v, id)
    shiny::tags$g(
      shiny::tags$path(
        class = "fpa-g-final", d = bez(x + w, y, x1, y1), fill = "none",
        stroke = "#5c6b73", `stroke-width` = "1.6", `stroke-dasharray` = "5 4", `data-line` = id
      ),
      shiny::tags$g(
        class = "fpa-g-out",
        `data-line` = id,
        onclick = sprintf("fpaGraphFocusLine('%s')", id),
        shiny::tags$rect(
          x = x, y = y - 28, width = w, height = 56, rx = 8,
          fill = "#f4f7f8", stroke = "#5c6b73", `stroke-width` = "1.3", `stroke-dasharray` = "5 4"
        ),
        shiny::tags$text(x = x + 12, y = y - 2, fill = "#0f2f3a", `font-size` = "13", `font-weight` = "700", fpa_shiny_line_name(id)),
        shiny::tags$text(x = x + 12, y = y + 16, fill = "#5c6b73", `font-size` = "11", oi_sub(id))
      ),
      if (nzchar(lab)) pill(at$x, at$y, lab, ink$bg, ink$fg, "fpa-g-final", line = id, tip = fpa_screen("drv_tip_part"))
    )
  })
  gate_node <- function(x, y, title, sub, lines_on) {
    shiny::tags$g(
      class = "fpa-g-gate",
      `data-line` = paste(lines_on, collapse = " "),
      onclick = "fpaGraphFocusSink()",
      shiny::tags$rect(
        x = x, y = y - 28, width = gate_w, height = 56, rx = 8,
        fill = "#ffffff", stroke = "#0f2f3a", `stroke-width` = "1.4"
      ),
      shiny::tags$text(x = x + 12, y = y - 2, fill = "#0f2f3a", `font-size` = "13", `font-weight` = "700", title),
      shiny::tags$text(x = x + 12, y = y + 16, fill = "#5c6b73", `font-size` = "11", sub)
    )
  }
  gate_nodes <- list(
    if (length(gp_all)) gate_node(mb_x, gate_y[["GP"]], "Marge brute", "CA \u2212 achats", gp_all),
    if (length(c(gp_all, ebe_all))) gate_node(ebe_x, gate_y[["EBITDA"]], "EBE", "marge \u2212 salaires", c(gp_all, ebe_all))
  )
  final_tags <- lapply(right_lines, function(ln) {
    ln <- as.character(ln)
    y0 <- links$y_right[match(ln, links$target_line)]
    gate <- gate_of(ln)
    at <- bez_at(line_x + line_w, y0, gate_x[[gate]], gate_y[[gate]], 0.5)
    sv <- share_in(gate, ln)
    s_lab <- fpa_driver_map_share_txt(if (is_fixed(ln)) 0 else sv)
    v <- suppressWarnings(as.numeric(line_euro[[ln]]))
    e_lab <- if (length(v) == 1L && is.finite(v)) paste0(format(round(v), big.mark = " ", scientific = FALSE, trim = TRUE), " EUR") else ""
    ink <- share_ink(sv, ln)
    shiny::tagList(
      if (nzchar(s_lab)) pill(at$x, at$y, s_lab, ink$bg, ink$fg, "fpa-g-final", line = ln, tip = fpa_screen("drv_tip_part")),
      if (nzchar(e_lab)) {
        stroke <- if (v < 0) "#8c3a3a" else "#0f2f3a"
        pill(at$x, at$y + if (nzchar(s_lab)) 24 else 0, e_lab, stroke, "#ffffff", "fpa-g-final", line = ln)
      }
    )
  })
  shares_note <- if (is.null(shares)) {
    NULL
  } else if (!isTRUE(shares$ok)) {
    shiny::tags$p(fpa_screen("drv_map_shares_short"))
  } else {
    broken <- names(shares$nodes)[!vapply(names(shares$nodes), node_ok, logical(1))]
    shiny::tags$p(
      fpa_screen("drv_map_shares", shares$n),
      paste0(" ", fpa_screen("drv_map_shares_caveat")),
      if (length(shares$zero)) paste0(" ", fpa_screen("drv_map_shares_hidden", paste(vapply(shares$zero, fpa_shiny_line_name, ""), collapse = ", "))),
      lapply(broken, function(node) {
        gap <- format(round(shares$nodes[[node]]$gap), big.mark = " ", scientific = FALSE, trim = TRUE)
        shiny::tags$strong(style = "color:#8c3a3a;", paste0(" ", fpa_screen("drv_map_shares_tie", fpa_shiny_line_name(node), gap)))
      })
    )
  }
  oi_node <- shiny::tags$g(
    class = "fpa-g-sink",
    onclick = "fpaGraphFocusSink()",
    shiny::tags$rect(
      x = oi_x, y = y_oi - 28, width = oi_w, height = 56, rx = 8,
      fill = "#1f4e5f", stroke = "#163844", `stroke-width` = "1.6"
    ),
    shiny::tags$text(
      x = oi_x + 12, y = y_oi - 4,
      fill = "#ffffff", `font-size` = "13", `font-weight` = "700",
      "Résultat"
    ),
