fpa_shiny_kpi <- function(title, value, subtitle = "") {
  bslib::value_box(
    title = title,
    value = value,
    shiny::p(subtitle),
    theme = "primary"
  )
}

fpa_shiny_pnl_window <- function(months, span, start) {
  months <- as.character(months)
  if (!length(months)) return(months)
  span <- as.character(span)
  if (!length(span) || !nzchar(span[[1]]) || is.na(span[[1]])) span <- "12"
  if (identical(span[[1]], "all")) return(months)
  n <- suppressWarnings(as.integer(span[[1]]))
  if (length(n) != 1L || !is.finite(n) || n < 1L) n <- 12L
  start <- as.character(start)
  if (!length(start) || is.na(start[[1]])) start <- ""
  i0 <- match(start[[1]], months)
  if (length(i0) != 1L || is.na(i0)) i0 <- max(1L, length(months) - n + 1L)
  i1 <- min(length(months), i0 + n - 1L)
  months[i0:i1]
}

fpa_shiny_heat <- function(value, max_abs) {
  v <- suppressWarnings(as.numeric(value))
  if (!is.finite(v) || abs(v) < 0.5) return(list(bg = "#f7fafa", fg = "#9aa7ad", label = "–"))
  cap <- suppressWarnings(as.numeric(max_abs))
  if (!is.finite(cap) || cap < 0.5) cap <- abs(v)
  t <- min(1, abs(v) / cap)
  if (v < 0) {
    bg <- fpa_driver_map_mix(t, c(0xfd, 0xf6, 0xf6), c(0xf0, 0xc8, 0xc8))
    fg <- "#8c3a3a"
  } else {
    bg <- fpa_driver_map_mix(t, c(0xf4, 0xf8, 0xf9), c(0x1f, 0x4e, 0x5f))
    fg <- if (t >= 0.55) "#ffffff" else "#1a2b32"
  }
  list(bg = bg, fg = fg, label = fpa_shiny_eur(v))
}

#' One tint scale for the whole table. The chip carries the colour, not the cell.
fpa_shiny_chip <- function(text, score) {
  t <- suppressWarnings(as.numeric(score))
  if (!is.finite(t)) t <- 0
  t <- max(0, min(1, t))
  empty <- !nzchar(text) || identical(text, "–")
  if (empty) {
    bg <- "#f4f7f8"
    fg <- "#9aa7ad"
    text <- "–"
  } else {
    bg <- fpa_driver_map_mix(t, c(0xe8, 0xf1, 0xf6), c(0x1f, 0x4e, 0x5f))
    fg <- if (t >= 0.55) "#ffffff" else "#1a2b32"
  }
  shiny::tags$span(class = "fpa-chip", style = paste0("background:", bg, ";color:", fg, ";"), text)
}

fpa_shiny_chip_score <- function(v, cap) {
  if (!is.finite(v)) return(0)
  cap <- suppressWarnings(as.numeric(cap))
  if (!is.finite(cap) || cap < 1e-9) return(if (abs(v) < 0.5) 0 else 1)
  if (abs(v) < 0.5 && abs(v) < 0.05 * cap) return(0)
  min(1, abs(v) / cap)
}

fpa_shiny_nature_badge <- function(cat) {
  cat <- fpa_nature_norm(cat)
  if (is.na(cat)) return(NULL)
  if (identical(cat, "op")) {
    return(shiny::tags$span(class = "fpa-opfin is-op", title = "Exploitation", "Op"))
  }
  if (identical(cat, "fin")) {
    return(shiny::tags$span(class = "fpa-opfin is-fin", title = "Financement", "Fin"))
  }
  shiny::tags$span(class = "fpa-opfin is-other", title = "Ni Op ni Fin", "\u2014")
}

fpa_shiny_nature_th <- function(label, cat = NA_character_, show = FALSE) {
  if (!isTRUE(show) || is.na(fpa_nature_norm(cat))) {
    return(shiny::tags$th(label))
  }
  shiny::tags$th(
    class = "fpa-opfin-lab",
    fpa_shiny_nature_badge(cat),
    shiny::tags$span(class = "fpa-opfin-name", label)
  )
}

#' Op/Fin controls. Built only when line_nature is present (caller checks).
fpa_shiny_opfin_controls <- function(prefix) {
  show_id <- paste0(prefix, "_show_op_fin")
  scope_id <- paste0(prefix, "_op_fin_scope")
  shiny::div(
    class = "fpa-stmt-modes fpa-opfin-modes",
    shiny::checkboxInput(show_id, fpa_screen("stmt_opfin_show"), TRUE),
    shiny::conditionalPanel(
      paste0("input.", show_id, " == true"),
      shiny::radioButtons(
        scope_id, NULL,
        choices = stats::setNames(
          c("all", "op_fin"),
          c(fpa_screen("stmt_opfin_all"), fpa_screen("stmt_opfin_only"))
        ),
        selected = "all", inline = TRUE
      )
    )
  )
}

fpa_shiny_pct_label <- function(v) {
  if (!is.finite(v)) return("–")
  paste0(formatC(v, format = "f", digits = 1, decimal.mark = ",", big.mark = " "), " %")
}

fpa_shiny_signed_eur <- function(v) {
  if (!is.finite(v)) return("–")
  paste0(if (v > 0.5) "+" else "", fpa_shiny_eur(v))
}

fpa_shiny_case_choices <- function() {
  stats::setNames(
    c("low", "base", "high"),
    c(fpa_screen("scen_bas"), fpa_screen("scen_central"), fpa_screen("scen_haut"))
  )
}

fpa_shiny_case_input <- function(input_id, label = NULL, selected = "base") {
  if (!selected %in% c("low", "base", "high")) selected <- "base"
  shiny::div(
    class = "fpa-case",
    shiny::radioButtons(
      input_id, label %||% fpa_screen("scen_case_label"),
      choices = fpa_shiny_case_choices(),
      selected = selected, inline = TRUE
    )
  )
}

fpa_shiny_scn_score <- function(case_id) {
  switch(as.character(case_id %||% "base"), low = -1, high = 1, 0)
}

fpa_shiny_scn_picks <- function(scope, current) {
  specs <- list(
    list(id = "low", lab = "scen_bas"),
    list(id = "base", lab = "scen_central"),
    list(id = "high", lab = "scen_haut")
  )
  shiny::tags$div(
    class = "fpa-scn-picks", role = "group",
    lapply(specs, function(sp) {
      on <- identical(current, sp$id)
      shiny::tags$button(
        type = "button",
        class = paste(c("fpa-scn-pick", if (on) "is-on"), collapse = " "),
        `data-scope` = scope,
        `data-case` = sp$id,
        `aria-pressed` = if (on) "true" else "false",
        fpa_screen(sp$lab)
      )
    })
  )
}

#' Round control on the variance chart. Colour is the sign of the open-month average.
fpa_shiny_scn_dock <- function(open, cases, dock_id = "gap", extra = NULL) {
  if (!length(open)) return(NULL)
  ids <- vapply(open, function(per) {
    if (!is.null(cases[[per]])) as.character(cases[[per]]) else "base"
  }, character(1))
  avg <- mean(vapply(ids, fpa_shiny_scn_score, numeric(1)))
  tone <- if (avg > 0) "is-hi" else if (avg < 0) "is-lo" else "is-base"
  # Triangle up, two bars, triangle down. The shape carries the sign, not only the colour.
  glyph <- if (avg > 0) {
    '<svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true"><path d="M8 2.5 L14 13 H2 Z" fill="currentColor"/></svg>'
  } else if (avg < 0) {
    '<svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true"><path d="M8 13.5 L2 3 H14 Z" fill="currentColor"/></svg>'
  } else {
    '<svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true"><rect x="2" y="4" width="12" height="2.4" rx="0.4" fill="currentColor"/><rect x="2" y="9.6" width="12" height="2.4" rx="0.4" fill="currentColor"/></svg>'
  }
  tip <- if (avg > 0) "var_scn_tip_hi" else if (avg < 0) "var_scn_tip_lo" else "var_scn_tip_base"
  shared <- if (length(unique(ids)) == 1L) ids[[1]] else ""
  rows <- c(
    list(shiny::tags$div(
      class = "fpa-scn-row is-all",
      shiny::tags$span(class = "fpa-scn-lab", fpa_screen("var_scn_all")),
      fpa_shiny_scn_picks("all", shared)
    )),
    lapply(seq_along(open), function(i) {
      shiny::tags$div(
        class = "fpa-scn-row",
        shiny::tags$span(class = "fpa-scn-lab", fpa_shiny_month_short(open[[i]])),
        fpa_shiny_scn_picks(open[[i]], ids[[i]])
      )
    })
  )
  shiny::tags$div(
    class = "fpa-scn-dock",
    `data-dock` = dock_id,
    shiny::tags$button(
      type = "button",
      class = paste("fpa-scn-btn", tone),
      title = fpa_screen(tip),
      `aria-label` = fpa_screen(tip),
      `aria-expanded` = "false",
      shiny::HTML(glyph),
      shiny::tags$span(class = "fpa-scn-name", fpa_screen("var_scn_btn"))
    ),
    shiny::tags$div(
      class = "fpa-scn-pop",
      hidden = "hidden",
      shiny::tags$button(
        type = "button",
        class = "fpa-scn-gear",
        title = fpa_screen("var_scn_pct_tip"),
        `aria-label` = fpa_screen("var_scn_pct_tip"),
        shiny::HTML('<svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="2.1" fill="none" stroke="currentColor" stroke-width="1.4"/><path d="M8 1.4v2.1M8 12.5v2.1M1.4 8h2.1M12.5 8h2.1M3.1 3.1l1.5 1.5M11.4 11.4l1.5 1.5M3.1 12.9l1.5-1.5M11.4 4.6l1.5-1.5" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/></svg>')
      ),
      shiny::tags$p(class = "fpa-scn-head", fpa_screen("var_scn_btn")),
      if (is.character(extra) && length(extra) == 1L && nzchar(extra)) shiny::tags$p(class = "fpa-scn-flat", extra) else extra,
      shiny::tags$div(class = "fpa-scn-scroll", rows),
      shiny::tags$button(
        type = "button", class = "fpa-scn-more",
        onclick = "if (window.fpaScnGo) window.fpaScnGo('pnl-fold-case');",
        fpa_screen("scnp_dock_more"),
        shiny::HTML('<svg width="12" height="12" viewBox="0 0 16 16" aria-hidden="true"><path d="M5 3 L11 8 L5 13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>')
      )
    ),
    shiny::tags$script(HTML(sprintf("
      (function () {
        if (window.fpaScnDockOpen !== '%s') return;
        var root = document.querySelector('.fpa-scn-dock[data-dock=\"%s\"]');
        if (!root) return;
        var pop = root.querySelector('.fpa-scn-pop');
        var btn = root.querySelector('.fpa-scn-btn');
        if (pop) pop.removeAttribute('hidden');
        if (btn) btn.setAttribute('aria-expanded', 'true');
      })();
    ", dock_id, dock_id)))
  )
}

#' Chart: the button sits on the plot, unless `dock_out` parks it under the chart, on the right.
#' Table or cards: the button sits above, on the right.
fpa_scn_host <- function(id, ..., plot = FALSE, dock_out = FALSE, dock_above = FALSE) {
  dock <- shiny::uiOutput(paste0("scn_dock_", id))
  if (isTRUE(plot)) {
    cls <- "fpa-scn-plot"
    if (isTRUE(dock_out)) cls <- paste(cls, "fpa-scn-dock-out")
    if (isTRUE(dock_above)) cls <- paste(cls, "fpa-scn-dock-above")
    if (isTRUE(dock_above)) shiny::div(class = cls, dock, ...) else shiny::div(class = cls, ..., dock)
  } else {
    shiny::div(class = "fpa-scn-bar", dock, ...)
  }
}

fpa_shiny_month_name <- function(periode) {
  names <- c(
    fpa_screen("month_1"), fpa_screen("month_2"), fpa_screen("month_3"), fpa_screen("month_4"), fpa_screen("month_5"), fpa_screen("month_6"),
    fpa_screen("month_7"), fpa_screen("month_8"), fpa_screen("month_9"), fpa_screen("month_10"), fpa_screen("month_11"), fpa_screen("month_12")
  )
  m <- as.integer(substr(periode, 6, 7))
  if (is.na(m) || m < 1L || m > 12L) return(as.character(periode))
  names[[m]]
}

fpa_shiny_close_when <- function(periode) {
  periode <- as.character(periode %||% "")
  month <- fpa_shiny_month_name(periode)
  year <- substr(periode, 1, 4)
  if (!nzchar(month) || identical(month, periode) || !nzchar(year)) return(periode)
  paste(month, year)
}

fpa_shiny_and <- function() if (identical(fpa_lang_current(), "en")) "and" else "et"

fpa_shiny_join_months <- function(pers) {
  labs <- vapply(pers, fpa_shiny_month_name, character(1))
  n <- length(labs)
  if (!n) return("")
  if (n == 1L) return(labs[[1]])
  conj <- fpa_shiny_and()
  if (n == 2L) return(paste(labs[[1]], conj, labs[[2]]))
  paste0(paste(labs[-n], collapse = ", "), " ", conj, " ", labs[[n]])
}

fpa_shiny_case_word <- function(case_id, plural = FALSE) {
  key <- switch(
    as.character(case_id %||% "base"),
    low = "scen_bas",
    high = "scen_haut",
    "scen_central"
  )
  word <- tolower(fpa_screen(key))
  if (isTRUE(plural) && word %in% c("prudent", "attendu")) word <- paste0(word, "s")
  word
}

#' Open months, then the scenario they share, or each month with its own.
fpa_shiny_case_phrase <- function(open, cases) {
  if (!length(open)) return("")
  ids <- vapply(open, function(per) {
    if (!is.null(cases[[per]])) as.character(cases[[per]]) else "base"
  }, character(1))
  if (length(unique(ids)) == 1L) {
    word <- fpa_shiny_case_word(ids[[1]], plural = length(open) > 1L && length(open) <= 4L)
    if (length(open) > 4L) return(fpa_screen("pnl_partner_many", length(open), word))
    return(paste(fpa_shiny_join_months(open), word))
  }
  if (length(open) > 4L) return(fpa_screen("pnl_partner_many_mixed", length(open)))
  bits <- vapply(seq_along(open), function(i) {
    paste(fpa_shiny_month_name(open[[i]]), fpa_shiny_case_word(ids[[i]]))
  }, character(1))
  n <- length(bits)
  if (n == 1L) return(bits[[1]])
  conj <- fpa_shiny_and()
  if (n == 2L) return(paste(bits[[1]], conj, bits[[2]]))
  paste0(paste(bits[-n], collapse = ", "), " ", conj, " ", bits[[n]])
}

#' The radio is the source of truth. Before it exists, the month stays central.
fpa_shiny_month_case <- function(per, input) {
  val <- input[[paste0("case_", gsub("-", "_", per))]]
  if (is.null(val) || !val %in% c("low", "base", "high")) return("base")
  as.character(val)
}

fpa_shiny_ranges <- function(config) {
  empty <- data.frame(
    id = character(), label = character(), low_pct = numeric(), high_pct = numeric(),
    stringsAsFactors = FALSE
  )
  inp <- config$scenario_ranges$inputs
  if (is.null(inp) || !length(inp)) return(empty)
  if (is.data.frame(inp)) {
    if (!nrow(inp) || !("id" %in% names(inp))) return(empty)
    labs <- if ("label" %in% names(inp)) as.character(inp$label) else as.character(inp$id)
    return(data.frame(
      id = as.character(inp$id), label = labs,
      low_pct = suppressWarnings(as.numeric(inp$low_pct)),
      high_pct = suppressWarnings(as.numeric(inp$high_pct)),
      stringsAsFactors = FALSE
    ))
  }
  rows <- lapply(inp, function(x) {
    data.frame(
      id = as.character(x$id %||% ""),
      label = as.character(x$label %||% x$id %||% ""),
      low_pct = suppressWarnings(as.numeric(x$low_pct %||% NA)),
      high_pct = suppressWarnings(as.numeric(x$high_pct %||% NA)),
      stringsAsFactors = FALSE
    )
  })
  out <- do.call(rbind, rows)
  out <- out[nzchar(out$id), , drop = FALSE]
  book <- list()
  if (is.list(inp) && !is.data.frame(inp)) {
    for (x in inp) {
      id <- as.character(x$id %||% "")
      if (nzchar(id) && !is.null(x$months) && length(x$months)) book[[id]] <- x$months
    }
  }
  attr(out, "months") <- book
  out
}

#' Month cell in the config, otherwise the driver's own percent.
fpa_shiny_cell_pct <- function(ranges, i, per, side) {
  key <- if (identical(side, "low")) "low_pct" else "high_pct"
  base <- suppressWarnings(as.numeric(ranges[[key]][[i]]))
  book <- attr(ranges, "months")
  if (is.null(book) || !length(book)) return(base)
  cell <- book[[as.character(ranges$id[[i]])]][[as.character(per)]]
  if (is.null(cell)) return(base)
  val <- suppressWarnings(as.numeric(cell[[key]]))
  if (length(val) != 1L || !is.finite(val)) return(base)
  val
}

fpa_shiny_shock_number <- function(value, id, ranges, case_id) {
  value <- suppressWarnings(as.numeric(value))
  if (!is.finite(value)) return(value)
  if (!case_id %in% c("low", "high") || is.null(ranges) || !nrow(ranges)) return(value)
  hit <- which(ranges$id == id)
  if (!length(hit)) return(value)
  pct <- if (identical(case_id, "low")) ranges$low_pct[[hit[[1]]]] else ranges$high_pct[[hit[[1]]]]
  value * fpa_scenario_input_factor(id, pct, case_id)
}

#' A month starts locked when it is already closed. The checkbox then decides.
fpa_shiny_month_is_locked <- function(per, open, input) {
  key <- paste0("rng_lock_", gsub("-", "_", per))
  val <- input[[key]]
  if (is.null(val)) return(!(per %in% open))
  isTRUE(val)
}

fpa_shiny_range_id <- function(id) gsub("[^A-Za-z0-9]", "_", id)

#' Config percents, overwritten by the cells the user has typed for that month.
fpa_shiny_widths_for <- function(ranges, per, input) {
  if (is.null(ranges) || !nrow(ranges)) return(ranges)
  out <- ranges
  stem <- gsub("-", "_", per)
  for (i in seq_len(nrow(out))) {
    base <- paste0("rng_", fpa_shiny_range_id(out$id[[i]]), "_", stem)
    lo <- input[[paste0(base, "_low")]]
    hi <- input[[paste0(base, "_high")]]
    out$low_pct[[i]] <- if (is.null(lo)) fpa_shiny_cell_pct(ranges, i, per, "low") else suppressWarnings(as.numeric(lo))
    out$high_pct[[i]] <- if (is.null(hi)) fpa_shiny_cell_pct(ranges, i, per, "high") else suppressWarnings(as.numeric(hi))
  }
  out
}

#' Scale one closed month that the user has unlocked. No driver boxes exist for it.
fpa_shiny_scale_month <- function(out, base, i, ranges, case_id) {
  if (!case_id %in% c("low", "high") || is.null(ranges) || !nrow(ranges)) return(out)
  rev_f <- 1
  cogs_f <- 1
  pay_f <- 1
  opex_f <- 1
  for (k in seq_len(nrow(ranges))) {
    pct <- if (identical(case_id, "low")) ranges$low_pct[[k]] else ranges$high_pct[[k]]
    f <- fpa_scenario_input_factor(ranges$id[[k]], pct, case_id)
    line <- fpa_scenario_line_of(ranges$id[[k]])
    if (identical(line, "REV")) rev_f <- rev_f * f
    if (identical(line, "COGS")) cogs_f <- cogs_f * f
    if (identical(line, "PAYROLL")) pay_f <- pay_f * f
    if (identical(line, "OPEX_OTHER")) opex_f <- opex_f * f
  }
  if ("REV" %in% names(out)) out$REV[[i]] <- suppressWarnings(as.numeric(base$REV[[i]])) * rev_f
  if ("COGS" %in% names(out)) out$COGS[[i]] <- suppressWarnings(as.numeric(base$COGS[[i]])) * rev_f * cogs_f
  if ("PAYROLL" %in% names(out)) out$PAYROLL[[i]] <- suppressWarnings(as.numeric(base$PAYROLL[[i]])) * pay_f
  if ("OPEX_OTHER" %in% names(out)) out$OPEX_OTHER[[i]] <- suppressWarnings(as.numeric(base$OPEX_OTHER[[i]])) * opex_f
  out
}

fpa_shiny_forecast_periods <- function(status) {
  if (is.null(status) || !nrow(status) || !all(c("periode", "status") %in% names(status))) {
    return(character())
  }
  as.character(status$periode[as.character(status$status) == "forecast"])
}

#' Forecast months take the chosen case. Closed months stay the realised statement.
fpa_shiny_open_months <- function(pnl, status) {
  fc <- fpa_shiny_forecast_periods(status)
  if (length(fc)) return(fc)
  if (is.null(pnl) || !nrow(pnl) || !("REV" %in% names(pnl))) return(character())
  rev <- suppressWarnings(as.numeric(pnl$REV))
  alive <- which(is.finite(rev) & abs(rev) >= 1)
  if (!length(alive) || max(alive) >= length(rev)) return(character())
  as.character(pnl$periode[(max(alive) + 1L):length(rev)])
}

fpa_shiny_date_fr <- function(d) {
  d <- as.Date(d)
  if (is.na(d)) return("")
  paste(as.integer(format(d, "%d")), fpa_chain_month_fr(as.integer(format(d, "%m"))), format(d, "%Y"))
}

#' Last calendar day of each YYYY-MM, so a mid-month mark can sit on the cash chart.
fpa_shiny_month_end <- function(ym) {
  ym <- substr(as.character(ym), 1, 7)
  vapply(ym, function(one) {
    if (!grepl("^[0-9]{4}-[0-9]{2}$", one)) return(one)
    start <- as.Date(paste0(one, "-01"))
    format(seq(start, by = "month", length.out = 2L)[[2]] - 1L, "%Y-%m-%d")
  }, character(1), USE.NAMES = FALSE)
}

#' Monthly revenue by calendar year from the long history file, one total per month.
fpa_shiny_hist_rev <- function(config, paths) {
  hist <- tryCatch(fpa_line_history(config, paths), error = function(e) NULL)
  map <- tryCatch(fpa_line_map(config, "pnl"), error = function(e) NULL)
  bucket <- fpa_anomaly_bucket_month(hist, map, "REV")
  if (is.null(bucket) || !nrow(bucket)) return(list())
  years <- sort(unique(substr(bucket$periode, 1, 4)))
  out <- list()
  for (y in years) {
    sl <- bucket[startsWith(bucket$periode, y), , drop = FALSE]
    out[[y]] <- setNames(sl$montant, sl$periode)
  }
  out
}

fpa_shiny_year_on <- function(year, current, input) {
  val <- input[[paste0("pnl_year_", year)]]
  if (is.null(val)) return(identical(as.character(year), as.character(current)))
  isTRUE(val)
}

#' Question and menu under the budget bar when that file does not cover the open exercise.
fpa_shiny_budget_year_ask <- function(need, source_id) {
  if (is.null(need)) return(NULL)
  safe <- gsub("[^A-Za-z0-9_:.-]", "", as.character(source_id %||% ""))
  if (!nzchar(safe)) return(NULL)
  shiny::tags$div(
    class = "fpa-budget-year",
    onclick = "event.stopPropagation()",
    shiny::tags$p(fpa_screen("budget_year_read", need$declared, need$open)),
    shiny::tags$label(
      `for` = paste0("fpa-budget-year-", safe),
      fpa_screen("budget_year_ask")
    ),
    shiny::tags$select(
      id = paste0("fpa-budget-year-", safe),
      onchange = sprintf(
        "Shiny.setInputValue('budget_year','%s\\t'+this.value,{priority:'event'})",
        safe
      ),
      lapply(need$choices, function(y) {
        lab <- if (identical(as.integer(y), as.integer(need$open))) {
          fpa_screen("budget_year_open", y)
        } else {
          as.character(y)
        }
        shiny::tags$option(
          value = as.character(y),
          selected = if (identical(as.integer(y), as.integer(need$declared))) NA else NULL,
          lab
        )
      })
    ),
    shiny::tags$p(class = "hint", fpa_screen("budget_year_hint"))
  )
}

#' Does the voted budget contain any month of `year`? `last` is the latest YYYY-MM it holds.
fpa_shiny_budget_gap <- function(budget, year) {
  out <- list(covers = FALSE, last = NA_character_, has_rows = FALSE)
  if (is.null(budget) || !is.data.frame(budget) || !nrow(budget) || !("periode" %in% names(budget))) return(out)
  per <- as.character(budget$periode)
  per <- per[grepl("^[0-9]{4}-[0-9]{2}", per)]
  if (!length(per)) return(out)
  out$has_rows <- TRUE
  out$last <- max(per)
  out$covers <- any(startsWith(per, as.character(year)))
  out
}

fpa_shiny_role_source <- function(config, role) {
  for (s in config$sources %||% list()) {
    if (identical(as.character(s$file_role %||% ""), role)) return(s)
  }
  NULL
}

#' Source files behind a chart. Each entry opens the existing raw-file popup.
fpa_chart_source_refs <- function(config, which) {
  if (is.null(config)) return(list())
  which <- as.character(which %||% "be")
  roles <- if (identical(which, "terrain")) {
    "pnl_monthly"
  } else if (which %in% c("be", "cloud")) {
    c("pnl_monthly", "opening_bs", "volumes")
  } else {
    c("pnl_monthly", "opening_bs")
  }
  if (identical(which, "be")) roles <- c("pnl_monthly", "volumes")
  sources <- config$sources %||% list()
  is_vol <- function(s) {
    keys <- c(names(s$column_map), as.character(unlist(s$column_map, use.names = FALSE)))
    any(keys %in% c(
      "nuitees_vendues", "tarif", "quantite", "prix",
      "nb_clients", "depense_moyenne", "capacite", "taux_utilisation"
    ))
  }
  rows <- list()
  seen <- character()
  add <- function(s) {
    id <- as.character(s$source_id %||% "")
    if (!nzchar(id) || id %in% seen) return()
    seen <<- c(seen, id)
    name <- as.character(s$source_name %||% "")
    if (!nzchar(name)) name <- id
    rows[[length(rows) + 1L]] <<- list(id = id, name = name)
  }
  for (role in roles) {
    hit <- FALSE
    if (identical(role, "volumes")) {
      for (s in sources) if (isTRUE(is_vol(s))) add(s)
      next
    }
    for (s in sources) {
      if (identical(as.character(s$file_role %||% ""), role)) {
        add(s)
        hit <- TRUE
      }
    }
    if (!hit && identical(role, "pnl_monthly")) {
      for (s in sources) if (identical(as.character(s$file_role %||% ""), "pnl_actuals")) add(s)
    }
  }
  rows
}

# Prior-year lines stay clear of teal (2026 central), near-black (réalisé) and orange (budget).
fpa_shiny_year_color <- function(year) {
  known <- c(
    "2021" = "#6D4C41",
    "2022" = "#00838F",
    "2023" = "#7A1FA2",
    "2024" = "#C62828",
    "2025" = "#1565C0",
    "2027" = "#AD1457"
  )
  hit <- unname(known[as.character(year)])
  if (length(hit) == 1L && !is.na(hit)) return(hit)
  pool <- unname(known)
  pool[[(abs(sum(utf8ToInt(as.character(year)))) %% length(pool)) + 1L]]
}

fpa_shiny_month_short <- function(periode) {
  names <- c(fpa_screen("month_s_1"), fpa_screen("month_s_2"), fpa_screen("month_s_3"), fpa_screen("month_s_4"), fpa_screen("month_s_5"), fpa_screen("month_s_6"), fpa_screen("month_s_7"), fpa_screen("month_s_8"), fpa_screen("month_s_9"), fpa_screen("month_s_10"), fpa_screen("month_s_11"), fpa_screen("month_s_12"))
  m <- as.integer(substr(periode, 6, 7))
  if (is.na(m) || m < 1L || m > 12L) return(as.character(periode))
  names[[m]]
}

fpa_shiny_volumes <- function(config, paths) {
  got <- tryCatch(fpa_read_volumes(config, paths), error = function(e) NULL)
  if (is.null(got) || !isTRUE(got$ok) || is.null(got$data) || !nrow(got$data)) return(NULL)
  got$data
}

#' Driven lines from work/line-drivers.csv: the ones measured on the history.
fpa_shiny_driven_lines <- function(fit) {
  if (is.null(fit) || !nrow(fit) || !all(c("method", "functional_label", "per_volume", "pct_rev", "fixed") %in% names(fit))) {
    return(NULL)
  }
  fit <- fit[as.character(fit$method) != "seasonal", , drop = FALSE]
  if (!nrow(fit)) return(NULL)
  for (col in c("fixed", "per_volume", "pct_rev", "r2")) {
    if (col %in% names(fit)) fit[[col]] <- suppressWarnings(as.numeric(fit[[col]]))
  }
  fit
}

fpa_shiny_month_nights <- function(row, occ = NA_real_) {
  if (is.null(row)) return(NA_real_)
  rooms <- if ("capacite" %in% names(row)) suppressWarnings(as.numeric(row$capacite[[1]])) else NA_real_
  if (is.finite(occ) && is.finite(rooms)) return(rooms * occ / 100)
  if (is.finite(rooms) && "taux_utilisation" %in% names(row)) {
    return(rooms * suppressWarnings(as.numeric(row$taux_utilisation[[1]])))
  }
  if ("nuitees_vendues" %in% names(row)) return(suppressWarnings(as.numeric(row$nuitees_vendues[[1]])))
  NA_real_
}

#' Part of a bucket that moves with volume or revenue, for one month.
fpa_shiny_driven_part <- function(lines, bucket, nights, revenue, factor = 1) {
  if (is.null(lines)) return(0)
  sl <- lines[as.character(lines$functional_label) == bucket, , drop = FALSE]
  if (!nrow(sl)) return(0)
  n <- if (is.finite(nights)) nights else 0
  r <- if (is.finite(revenue)) revenue else 0
  factor * sum(sl$per_volume * n + sl$pct_rev * r, na.rm = TRUE)
}

fpa_shiny_eur2 <- function(x) {
  formatC(x, format = "f", digits = 2, big.mark = " ", decimal.mark = ",")
}

#' What each measured line follows, one sentence per line, under the driver boxes.
fpa_shiny_driven_list <- function(lines) {
  if (is.null(lines) || !nrow(lines)) return(NULL)
  sentence <- function(r) {
    n <- as.integer(r$n %||% 0L)
    d <- as.character(r$driver)
    if (d == "mixed" && identical(as.character(r$method), "fit_ols")) {
      fpa_screen("pnl_line_mixed", fpa_synthese_eur(r$fixed), fpa_shiny_eur2(r$per_volume), n,
              formatC(r$r2, format = "f", digits = 2, decimal.mark = ","))
    } else if (d %in% c("volume", "mixed") && r$per_volume > 0) {
      fpa_screen("pnl_line_volume", fpa_shiny_eur2(r$per_volume), n)
    } else if (d == "revenue_pct") {
      fpa_screen("pnl_line_pct", formatC(100 * r$pct_rev, format = "f", digits = 1, decimal.mark = ","), n)
    } else {
      fpa_screen("pnl_line_contract", fpa_synthese_eur(r$fixed))
    }
  }
  shiny::tags$div(
    class = "fpa-drv-lines",
    shiny::tags$p(class = "fpa-drv-lead", fpa_screen("pnl_lines_head")),
    shiny::tags$ul(lapply(seq_len(nrow(lines)), function(k) {
      r <- lines[k, , drop = FALSE]
      shiny::tags$li(shiny::tags$strong(as.character(r$user_label)), " : ", sentence(r))
    }))
  )
}

fpa_shiny_apply_driver_edits <- function(pnl, volumes, open, edits, var_pct, lines = NULL, var_factor = 1) {
  if (is.null(pnl) || !nrow(pnl) || !length(open) || !length(edits)) return(pnl)
  out <- pnl
  touched <- FALSE
  for (p in open) {
    i <- match(p, out$periode)
    e <- edits[[p]]
    if (is.na(i) || is.null(e)) next
    row <- NULL
    if (!is.null(volumes) && nrow(volumes)) {
      hit <- which(as.character(volumes$periode) == p)
      if (length(hit)) row <- volumes[hit[[1]], , drop = FALSE]
    }
    rooms <- if (!is.null(row) && "capacite" %in% names(row)) suppressWarnings(as.numeric(row$capacite[[1]])) else NA_real_
    if (is.finite(e$occ) && is.finite(e$rate) && is.finite(rooms)) {
      out$REV[[i]] <- rooms * (e$occ / 100) * e$rate
      touched <- TRUE
    }
    if (is.finite(e$head) && is.finite(e$cost)) {
      out$PAYROLL[[i]] <- e$head * e$cost
      touched <- TRUE
    }
    if (!is.null(lines)) {
      n_base <- fpa_shiny_month_nights(row)
      n_new <- fpa_shiny_month_nights(row, e$occ)
      for (bucket in intersect(unique(as.character(lines$functional_label)), names(out))) {
        before <- fpa_shiny_driven_part(lines, bucket, n_base, pnl$REV[[i]])
        after <- fpa_shiny_driven_part(lines, bucket, n_new, out$REV[[i]], var_factor)
        out[[bucket]][[i]] <- out[[bucket]][[i]] + after - before
      }
      touched <- TRUE
    } else if (length(var_pct) == 1L && is.finite(var_pct) && is.finite(out$REV[[i]])) {
      out$COGS[[i]] <- out$REV[[i]] * var_pct / 100
      touched <- TRUE
    }
  }
  if (!touched) return(pnl)
  fpa_pnl_derive(out)
}

#' A driver rewrite owns the lines it moved off the plan. Every other line still takes the percent.
fpa_shiny_scale_untouched <- function(out, base, i, ranges, case_id) {
  if (!case_id %in% c("low", "high") || is.null(ranges) || !nrow(ranges)) return(out)
  if (is.na(i)) return(out)
  scaled <- fpa_shiny_scale_month(out, base, i, ranges, case_id)
  for (col in c("REV", "COGS", "PAYROLL", "OPEX_OTHER")) {
    if (!col %in% names(out) || !col %in% names(base)) next
    a <- suppressWarnings(as.numeric(out[[col]][[i]]))
    b <- suppressWarnings(as.numeric(base[[col]][[i]]))
    if (is.finite(a) && is.finite(b) && abs(a - b) < 0.5) out[[col]][[i]] <- scaled[[col]][[i]]
  }
  out
}

#' Central boxes, then the live percents, on the months whose lock is off.
fpa_shiny_case_pnl <- function(pnl, volumes, open, edits, var_pct, ranges, case_id, lines = NULL, active = open, widths = NULL) {
  rg <- function(per) {
    if (!is.null(widths) && !is.null(widths[[per]])) widths[[per]] else ranges
  }
  shocked <- edits
  drive <- intersect(names(edits), active)
  for (per in drive) {
    if (is.null(shocked[[per]])) next
    r <- rg(per)
    shocked[[per]]$occ <- fpa_shiny_shock_number(edits[[per]]$occ, "taux_utilisation", r, case_id)
    shocked[[per]]$rate <- fpa_shiny_shock_number(edits[[per]]$rate, "tarif", r, case_id)
    shocked[[per]]$head <- fpa_shiny_shock_number(edits[[per]]$head, "effectif", r, case_id)
    shocked[[per]]$cost <- fpa_shiny_shock_number(edits[[per]]$cost, "cout_moyen", r, case_id)
  }
  out <- fpa_shiny_apply_driver_edits(pnl, volumes, drive, shocked, NA, lines, 1)
  if (is.null(out)) out <- pnl
  for (per in drive) {
    i <- match(per, out$periode)
    if (is.na(i)) next
    r <- rg(per)
    var_factor <- fpa_shiny_shock_number(1, "cout.variable.pct", r, case_id)
    if (!is.finite(var_factor)) var_factor <- 1
    if (!is.null(lines) && abs(var_factor - 1) > 1e-8) {
      row <- NULL
      if (!is.null(volumes) && nrow(volumes)) {
        hit <- which(as.character(volumes$periode) == per)
        if (length(hit)) row <- volumes[hit[[1]], , drop = FALSE]
      }
      occ <- shocked[[per]]$occ %||% NA_real_
      for (bucket in intersect(unique(as.character(lines$functional_label)), names(out))) {
        before <- fpa_shiny_driven_part(lines, bucket, fpa_shiny_month_nights(row, occ), out$REV[[i]], 1)
        after <- fpa_shiny_driven_part(lines, bucket, fpa_shiny_month_nights(row, occ), out$REV[[i]], var_factor)
        out[[bucket]][[i]] <- out[[bucket]][[i]] + after - before
      }
    }
    factor <- fpa_shiny_shock_number(1, "charges.fixes", r, case_id)
    if (is.finite(factor) && abs(factor - 1) > 1e-8 && "OPEX_OTHER" %in% names(out) && is.finite(out$OPEX_OTHER[[i]])) {
      row <- NULL
      if (!is.null(volumes) && nrow(volumes)) {
        hit <- which(as.character(volumes$periode) == per)
        if (length(hit)) row <- volumes[hit[[1]], , drop = FALSE]
      }
      occ <- shocked[[per]]$occ %||% NA_real_
      moving <- fpa_shiny_driven_part(lines, "OPEX_OTHER", fpa_shiny_month_nights(row, occ), out$REV[[i]], var_factor)
      out$OPEX_OTHER[[i]] <- (out$OPEX_OTHER[[i]] - moving) * factor + moving
    }
    out <- fpa_shiny_scale_untouched(out, pnl, i, r, case_id)
  }
  for (per in setdiff(active, drive)) {
    i <- match(per, out$periode)
    if (is.na(i)) next
    out <- fpa_shiny_scale_month(out, pnl, i, rg(per), case_id)
  }
  if (all(c("REV", "OTHER_OP_INC", "COGS", "PAYROLL", "OPEX_OTHER", "D_A", "FIN", "EXCEP", "TAX") %in% names(out))) {
    out <- fpa_pnl_derive(out)
  }
  out
}

#' One case per month. Central stays the plan. Bas and haut replace that month only.
fpa_shiny_stitch_pnl <- function(central, low, high, cases) {
  out <- central
  if (!length(cases)) return(out)
  cols <- intersect(
    c("REV", "OTHER_OP_INC", "COGS", "PAYROLL", "OPEX_OTHER", "D_A", "FIN", "EXCEP", "TAX"),
    names(out)
  )
  for (per in names(cases)) {
    src <- if (identical(cases[[per]], "low")) low else if (identical(cases[[per]], "high")) high else NULL
    if (is.null(src)) next
    i <- match(per, as.character(out$periode))
    j <- match(per, as.character(src$periode))
    if (is.na(i) || is.na(j)) next
    for (col in cols) out[[col]][[i]] <- src[[col]][[j]]
  }
  if (all(c("REV", "OTHER_OP_INC", "COGS", "PAYROLL", "OPEX_OTHER", "D_A", "FIN", "EXCEP", "TAX") %in% names(out))) {
    out <- fpa_pnl_derive(out)
  }
  out
}

#' Cash follows the named months. The extra profit lands in the net result, then in the balance.
fpa_shiny_cash_path <- function(cash, pnl_central, pnl_path) {
  if (is.null(cash) || !nrow(cash) || is.null(pnl_central) || is.null(pnl_path)) return(cash)
  if (!"NI" %in% names(pnl_path) || !"NI" %in% names(pnl_central)) return(cash)
  out <- cash
  dni <- rep(0, nrow(out))
  for (i in seq_len(nrow(out))) {
    p <- as.character(out$periode[[i]])
    ic <- match(p, as.character(pnl_central$periode))
    ip <- match(p, as.character(pnl_path$periode))
    if (is.na(ic) || is.na(ip)) next
    d <- suppressWarnings(as.numeric(pnl_path$NI[[ip]]) - as.numeric(pnl_central$NI[[ic]]))
    if (is.finite(d)) dni[[i]] <- d
  }
  if ("NI" %in% names(out)) out$NI <- suppressWarnings(as.numeric(out$NI)) + dni
  if ("delta_cash" %in% names(out)) out$delta_cash <- suppressWarnings(as.numeric(out$delta_cash)) + dni
  if ("CFO" %in% names(out)) out$CFO <- suppressWarnings(as.numeric(out$CFO)) + dni
  out$cash_close <- suppressWarnings(as.numeric(out$cash_close)) + cumsum(dni)
  if ("cash_open" %in% names(out) && length(dni)) {
    prior <- c(0, cumsum(dni)[-length(dni)])
    out$cash_open <- suppressWarnings(as.numeric(out$cash_open)) + prior
  }
  out
}

#' The extra cash is retained earnings, so the balance sheet still balances.
fpa_shiny_bs_path <- function(bs, cash_base, cash_path) {
  if (is.null(bs) || !nrow(bs) || is.null(cash_base) || is.null(cash_path)) return(bs)
  out <- bs
  for (i in seq_len(nrow(out))) {
    p <- as.character(out$periode[[i]])
    ib <- match(p, as.character(cash_base$periode))
    ip <- match(p, as.character(cash_path$periode))
    if (is.na(ib) || is.na(ip)) next
    d <- suppressWarnings(as.numeric(cash_path$cash_close[[ip]]) - as.numeric(cash_base$cash_close[[ib]]))
    if (!is.finite(d) || abs(d) < 0.5) next
    if ("CASH" %in% names(out)) out$CASH[[i]] <- suppressWarnings(as.numeric(out$CASH[[i]])) + d
    if ("EQUITY" %in% names(out)) out$EQUITY[[i]] <- suppressWarnings(as.numeric(out$EQUITY[[i]])) + d
  }
  out
}

#' Forecast months compare the named case with the voted budget. Closed months stay the file.
fpa_shiny_variance_path <- function(var_df, pnl_path, open) {
  if (is.null(var_df) || !nrow(var_df) || is.null(pnl_path) || !nrow(pnl_path) || !length(open)) return(var_df)
  out <- var_df
  for (i in seq_len(nrow(out))) {
    p <- as.character(out$periode[[i]])
    if (!p %in% open) next
    line <- as.character(out$line_id[[i]])
    if (!line %in% names(pnl_path)) next
    j <- match(p, as.character(pnl_path$periode))
    if (is.na(j)) next
    new_act <- suppressWarnings(as.numeric(pnl_path[[line]][[j]]))
    old_act <- suppressWarnings(as.numeric(out$actual[[i]]))
    bud <- suppressWarnings(as.numeric(out$budget[[i]]))
    if (!is.finite(new_act) || !is.finite(old_act)) next
    delta <- new_act - old_act
    if (abs(delta) < 0.5) next
    out$actual[[i]] <- new_act
    if (is.finite(bud)) {
      out$variance[[i]] <- new_act - bud
      out$variance_pct[[i]] <- if (abs(bud) > 1e-9) (new_act - bud) / bud else NA_real_
    }
    if ("unexplained" %in% names(out)) {
      u <- suppressWarnings(as.numeric(out$unexplained[[i]]))
      if (!is.finite(u)) u <- 0
      out$unexplained[[i]] <- u + delta
    }
  }
  out
}

fpa_var_oi_lines <- c("REV", "OTHER_OP_INC", "COGS", "PAYROLL", "OPEX_OTHER", "D_A")
fpa_var_line_order <- c(fpa_var_oi_lines, "FIN", "EXCEP", "TAX")

fpa_var_num <- function(x) suppressWarnings(as.numeric(x))

fpa_var_sg <- function(line, x) {
  s <- fpa_pnl_ni_sign(line)
  if (!is.finite(s) || s == 0) s <- 1
  fpa_var_num(x) * s
}

fpa_var_eur <- function(x) {
  x <- fpa_var_num(x)
  vapply(x, function(v) {
    if (!is.finite(v)) return("\u2013")
    s <- format(round(abs(v)), big.mark = " ", scientific = FALSE, trim = TRUE)
    if (round(v) < 0) paste0("\u2212", s) else s
  }, character(1))
}

fpa_var_eur_s <- function(x) {
  x <- fpa_var_num(x)
  vapply(x, function(v) {
    if (!is.finite(v)) return("\u2013")
    r <- round(v)
    if (r == 0) return("0")
    paste0(if (r > 0) "+" else "\u2212", format(abs(r), big.mark = " ", scientific = FALSE, trim = TRUE))
  }, character(1))
}

fpa_var_k <- function(x) {
  x <- fpa_var_num(x)
  vapply(x, function(v) {
    if (!is.finite(v)) return("")
    if (abs(v) < 50) return("0")
    paste0(if (v > 0) "+" else "\u2212", formatC(abs(v) / 1000, format = "f", digits = 1, decimal.mark = ","), "\u00a0k")
  }, character(1))
}

fpa_var_pct_s <- function(x) {
  x <- fpa_var_num(x)
  vapply(x, function(v) {
    if (!is.finite(v)) return("\u2013")
    r <- round(100 * v, 1)
    if (r == 0) return("0,0\u00a0%")
    paste0(if (r > 0) "+" else "\u2212", formatC(abs(r), format = "f", digits = 1, decimal.mark = ","), "\u00a0%")
  }, character(1))
}

fpa_var_month_abbr <- function(periode, with_year = FALSE) {
  p <- as.character(periode)
  m <- suppressWarnings(as.integer(substr(p, 6, 7)))
  ab <- c(fpa_screen("month_s_1"), fpa_screen("month_s_2"), fpa_screen("month_s_3"), fpa_screen("month_s_4"), fpa_screen("month_s_5"), fpa_screen("month_s_6"), fpa_screen("month_s_7"), fpa_screen("month_s_8"), fpa_screen("month_s_9"), fpa_screen("month_s_10"), fpa_screen("month_s_11"), fpa_screen("month_s_12"))
  out <- p
  ok <- is.finite(m) & m >= 1L & m <= 12L
  out[ok] <- ab[m[ok]]
  if (isTRUE(with_year)) out[ok] <- paste(out[ok], substr(p[ok], 3, 4))
  out
}

fpa_var_span <- function(periods) {
  p <- sort(unique(as.character(periods)))
  if (!length(p)) return("")
  if (length(p) == 1L) return(fpa_shiny_scn_month_lab(p[[1]]))
  y1 <- substr(p[[1]], 1, 4)
  y2 <- substr(p[[length(p)]], 1, 4)
  a <- fpa_var_month_abbr(p[[1]])
  b <- fpa_var_month_abbr(p[[length(p)]])
  if (identical(y1, y2)) paste(fpa_screen("var_span", a, b), y2) else fpa_screen("var_span", paste(a, y1), paste(b, y2))
}

fpa_var_join <- function(x) {
  x <- as.character(x)
  if (length(x) <= 1L) return(paste(x, collapse = ""))
  paste0(paste(x[-length(x)], collapse = ", "), fpa_screen("var_and"), x[[length(x)]])
}

fpa_var_is_fc <- function(sl) {
  if ("status" %in% names(sl)) as.character(sl$status) == "forecast" else rep(FALSE, nrow(sl))
}

#' Revenue only: the rest splits into budget phasing (q0 x p0 minus the P&L budget) and the part
#' of the P&L not found in actual quantity x rate. Both add back to `unexplained` row by row.
fpa_var_split <- function(sl, vol) {
  sl$phase <- NA_real_
  sl$unlinked <- NA_real_
  if (is.null(sl) || !nrow(sl) || !identical(as.character(sl$line_id[[1]]), "REV")) return(sl)
  if (is.null(vol) || !nrow(vol) || !all(c("periode", "nuitees_budget", "tarif_budget") %in% names(vol))) return(sl)
  if (!"unexplained" %in% names(sl)) return(sl)
  vp <- as.character(vol$periode)
  sl$q0 <- sl$p0 <- sl$q1 <- sl$p1 <- NA_real_
  has_real <- all(c("nuitees_vendues", "tarif") %in% names(vol))
  for (i in seq_len(nrow(sl))) {
    j <- match(as.character(sl$periode[[i]]), vp)
    if (is.na(j)) next
    q0 <- fpa_var_num(vol$nuitees_budget[[j]])
    p0 <- fpa_var_num(vol$tarif_budget[[j]])
    sl$q0[[i]] <- q0
    sl$p0[[i]] <- p0
    if (has_real) {
      sl$q1[[i]] <- fpa_var_num(vol$nuitees_vendues[[j]])
      sl$p1[[i]] <- fpa_var_num(vol$tarif[[j]])
    }
    b <- fpa_var_num(sl$budget[[i]])
    u <- fpa_var_num(sl$unexplained[[i]])
    if (!all(is.finite(c(q0, p0, b, u)))) next
    sl$phase[[i]] <- q0 * p0 - b
    sl$unlinked[[i]] <- u - sl$phase[[i]]
  }
  if (!any(is.finite(sl$phase))) return(sl)
  miss <- !is.finite(sl$phase)
  sl$phase[miss] <- 0
  u_all <- fpa_var_num(sl$unexplained)
  u_all[!is.finite(u_all)] <- 0
  sl$unlinked[miss] <- u_all[miss]
  sl
}

fpa_var_has_split <- function(sl) "phase" %in% names(sl) && any(is.finite(fpa_var_num(sl$phase)))

fpa_var_fmt_num <- function(x, digits, signed = FALSE, fixed = FALSE) {
  x <- fpa_var_num(x)[1]
  if (!is.finite(x)) return("\u2013")
  d <- if (!isTRUE(fixed) && abs(x - round(x)) < 0.5 * 10^(-digits)) 0L else as.integer(digits)
  r <- round(x, d)
  body <- formatC(abs(r), format = "f", digits = d, big.mark = " ", decimal.mark = ",")
  if (r < 0) return(paste0("\u2212", body))
  if (isTRUE(signed) && r > 0) return(paste0("+", body))
  body
}

fpa_var_qty_s <- function(x, signed = FALSE) fpa_var_fmt_num(x, 1, signed)
fpa_var_rate_s <- function(x, signed = FALSE, fixed = FALSE) fpa_var_fmt_num(x, 2, signed, fixed)

#' Months whose price and volume split comes from nights and rate, read off the volumes file.
fpa_var_pv_frame <- function(sl) {
  if (is.null(sl) || !nrow(sl) || !all(c("q0", "p0", "q1", "p1", "price", "volume") %in% names(sl))) return(NULL)
  line <- as.character(sl$line_id[[1]])
  fc <- fpa_var_is_fc(sl)
  q0 <- fpa_var_num(sl$q0); p0 <- fpa_var_num(sl$p0)
  q1 <- fpa_var_num(sl$q1); p1 <- fpa_var_num(sl$p1)
  pr <- fpa_var_sg(line, sl$price)
  vo <- fpa_var_sg(line, sl$volume)
  mx <- if ("mix" %in% names(sl)) fpa_var_sg(line, sl$mix) else rep(0, nrow(sl))
  mx[!is.finite(mx)] <- 0
  ok <- is.finite(q0) & is.finite(p0) & is.finite(q1) & is.finite(p1) & is.finite(pr) & is.finite(vo)
  moved <- ok & (abs(pr) + abs(vo) + abs(mx) > 0.5)
  keep <- ok & (!fc | moved)
  if (!any(keep)) return(NULL)
  out <- data.frame(
    periode = as.character(sl$periode), fc = fc,
    q0 = q0, p0 = p0, q1 = q1, p1 = p1,
    price = pr, volume = vo, mix = mx,
    stringsAsFactors = FALSE
  )
  list(rows = out[keep, , drop = FALSE], idle = as.character(sl$periode[ok & fc & !moved]))
}

fpa_var_pv_formula <- function(kind, q0, p0, q1, p1) {
  dq <- q1 - q0
  dp <- p1 - p0
  switch(kind,
    volume = paste(fpa_var_rate_s(p0), "\u00d7", fpa_var_qty_s(dq, signed = TRUE)),
    price = paste(fpa_var_qty_s(q0), "\u00d7", fpa_var_rate_s(dp, signed = TRUE)),
    mix = paste(fpa_var_qty_s(dq, signed = TRUE), "\u00d7", fpa_var_rate_s(dp, signed = TRUE)),
    ""
  )
}

fpa_var_pv_dir <- function(now, base, tol) {
  if (!is.finite(now) || !is.finite(base)) return("eq")
  if (now > base + tol) "up" else if (now < base - tol) "down" else "eq"
}

fpa_var_pv_glyph <- function(dir) {
  shiny::tags$span(
    class = paste0("fpa-pv-g is-", dir),
    title = fpa_screen(paste0("var_pv_", dir)),
    `aria-label` = fpa_screen(paste0("var_pv_", dir)),
    switch(dir, up = "\u25B2", down = "\u25BC", "=")
  )
}

fpa_var_pv_ui <- function(sl, sel_month = "") {
  f <- fpa_var_pv_frame(sl)
  if (is.null(f)) return(NULL)
  r <- f$rows
  line <- as.character(sl$line_id[[1]])
  esc <- function(x) gsub("[^A-Za-z0-9_-]", "", x)
  cl <- r[!r$fc, , drop = FALSE]
  tot_p <- sum(r$price); tot_v <- sum(r$volume); tot_m <- sum(r$mix)
  months_of <- function(mask) {
    p <- cl$periode[mask]
    if (!length(p)) fpa_screen("var_pv_none") else paste(vapply(p, fpa_shiny_month_name, character(1)), collapse = ", ")
  }
  sentences <- character(0)
  if (nrow(cl)) {
    cp <- sum(cl$price); cv <- sum(cl$volume); cm <- sum(cl$mix)
    sentences <- c(sentences, fpa_screen("var_pv_year", fpa_var_span(cl$periode), fpa_var_eur_s(cp), fpa_var_eur_s(cv), fpa_var_eur_s(cm), fpa_var_eur_s(cp + cv + cm)))
    if (max(abs(cp), abs(cv)) >= 0.5) sentences <- c(sentences, fpa_screen(if (abs(cp) >= abs(cv)) "var_pv_top_price" else "var_pv_top_volume"))
    rd <- vapply(seq_len(nrow(cl)), function(i) fpa_var_pv_dir(cl$p1[[i]], cl$p0[[i]], 0.005), character(1))
    qd <- vapply(seq_len(nrow(cl)), function(i) fpa_var_pv_dir(cl$q1[[i]], cl$q0[[i]], 0.05), character(1))
    sentences <- c(sentences,
      fpa_screen("var_pv_rate_line", months_of(rd == "down"), months_of(rd == "up")),
      fpa_screen("var_pv_qty_line", months_of(qd == "down"), months_of(qd == "up"))
    )
  }
  eff_td <- function(v, sub) shiny::tags$td(
    class = paste(c("is-eff", if (round(v) < 0) "neg"), collapse = " "),
    shiny::tags$span(class = "v", fpa_var_eur_s(v)),
    if (nzchar(sub) && abs(v) >= 0.5) shiny::tags$span(class = "f", sub)
  )
  rows <- lapply(seq_len(nrow(r)), function(i) {
    x <- r[i, ]
    qd <- fpa_var_pv_dir(x$q1, x$q0, 0.05)
    rd <- fpa_var_pv_dir(x$p1, x$p0, 0.005)
    s <- x$price + x$volume + x$mix
    shiny::tags$tr(
      class = paste(c(if (x$fc) "is-fc", if (identical(x$periode, sel_month)) "is-sel"), collapse = " "),
      onclick = sprintf("Shiny.setInputValue('var_pick',{line:'%s',month:'%s',n:Date.now()},{priority:'event'})", esc(line), esc(x$periode)),
      shiny::tags$td(class = "is-month", fpa_shiny_scn_month_lab(x$periode),
                     if (x$fc) shiny::tags$span(class = "fpa-var-chip", fpa_screen("var_chip_fc"))),
      shiny::tags$td(paste(fpa_var_qty_s(x$q0), "\u2192", fpa_var_qty_s(x$q1)), " ", fpa_var_pv_glyph(qd)),
      shiny::tags$td(paste(fpa_var_rate_s(x$p0, fixed = TRUE), "\u2192", fpa_var_rate_s(x$p1, fixed = TRUE)), " ", fpa_var_pv_glyph(rd)),
      eff_td(x$volume, fpa_var_pv_formula("volume", x$q0, x$p0, x$q1, x$p1)),
      eff_td(x$price, fpa_var_pv_formula("price", x$q0, x$p0, x$q1, x$p1)),
      eff_td(x$mix, fpa_var_pv_formula("mix", x$q0, x$p0, x$q1, x$p1)),
      shiny::tags$td(class = paste(c("is-sum", if (round(s) < 0) "neg"), collapse = " "), fpa_var_eur_s(s))
    )
  })
  sq0 <- sum(r$q0); sq1 <- sum(r$q1)
  avg0 <- if (sq0 > 0) sum(r$q0 * r$p0) / sq0 else NA_real_
  avg1 <- if (sq1 > 0) sum(r$q1 * r$p1) / sq1 else NA_real_
  ts <- tot_p + tot_v + tot_m
  total <- shiny::tags$tr(
    class = "is-total",
    shiny::tags$td(class = "is-month", fpa_screen("var_tbl_total")),
    shiny::tags$td(paste(fpa_var_qty_s(sq0), "\u2192", fpa_var_qty_s(sq1))),
    shiny::tags$td(paste(fpa_var_rate_s(avg0, fixed = TRUE), "\u2192", fpa_var_rate_s(avg1, fixed = TRUE))),
    shiny::tags$td(class = paste(c("is-eff", if (round(tot_v) < 0) "neg"), collapse = " "), fpa_var_eur_s(tot_v)),
    shiny::tags$td(class = paste(c("is-eff", if (round(tot_p) < 0) "neg"), collapse = " "), fpa_var_eur_s(tot_p)),
    shiny::tags$td(class = paste(c("is-eff", if (round(tot_m) < 0) "neg"), collapse = " "), fpa_var_eur_s(tot_m)),
    shiny::tags$td(class = paste(c("is-sum", if (round(ts) < 0) "neg"), collapse = " "), fpa_var_eur_s(ts))
  )
  shiny::tags$section(
    class = "fpa-pv",
    shiny::tags$p(class = "fpa-var-lead", fpa_screen("var_pv_lead")),
    shiny::tags$p(
      class = "fpa-pv-src",
      shiny::tags$button(
        type = "button",
        class = "fpa-file-link",
        onclick = "Shiny.setInputValue('var_pv_src', Date.now(), {priority:'event'})",
        fpa_screen("var_pv_src")
      )
    ),
    if (length(sentences)) shiny::tags$div(class = "fpa-drv-lead", lapply(sentences, function(s) shiny::tags$p(s))),
    shiny::tags$div(
      class = "fpa-var-table fpa-pv-table",
      shiny::tags$table(
        shiny::tags$thead(shiny::tags$tr(
          shiny::tags$th(fpa_screen("var_pv_col_month")),
          shiny::tags$th(fpa_screen("var_pv_col_qty")),
          shiny::tags$th(fpa_screen("var_pv_col_rate")),
          shiny::tags$th(fpa_screen("var_pv_col_vol")),
          shiny::tags$th(fpa_screen("var_pv_col_price")),
          shiny::tags$th(fpa_screen("var_pv_col_mix")),
          shiny::tags$th(fpa_screen("var_pv_col_sum"))
        )),
        shiny::tags$tbody(rows, total)
      )
    ),
    shiny::tags$p(class = "fpa-var-note", fpa_screen("var_pv_rest")),
    if (length(f$idle)) shiny::tags$p(class = "fpa-var-note", fpa_screen("var_pv_fc", fpa_var_span(f$idle)))
  )
}

#' Two ranges that share the same fraction of the plot below zero.
fpa_var_pv_axis_pair <- function(bars, cum, pad = 0.12) {
  span <- function(x) {
    x <- x[is.finite(x)]
    if (!length(x)) return(c(0, 1))
    c(min(0, min(x)), max(0, max(x)))
  }
  ends <- list(span(bars), span(cum))
  neg <- vapply(ends, function(z) abs(z[[1]]), numeric(1))
  pos <- vapply(ends, function(z) z[[2]], numeric(1))
  share <- max(neg / pmax(neg + pos, 1e-9))
  expand <- function(z) {
    n <- abs(z[[1]])
    p <- z[[2]]
    if (share <= 1e-9) return(c(0, max(p, 1) * (1 + pad)))
    if (share >= 1 - 1e-9) return(c(-max(n, 1) * (1 + pad), 0))
    total <- max(n / share, p / (1 - share), 1) * (1 + pad)
    c(-share * total, (1 - share) * total)
  }
  list(bars = expand(ends[[1]]), cum = expand(ends[[2]]))
}

#' Grouped bars for the price card, plus one running total per effect on the right axis.
#' Sign is the side of zero. Both axes cross zero at the same height.
fpa_var_pv_fig <- function(sl, sel = "") {
  f <- fpa_var_pv_frame(sl)
  if (is.null(f) || !nrow(f$rows)) return(NULL)
  r <- f$rows
  n <- nrow(r)
  per <- as.character(r$periode)
  xl <- fpa_var_month_abbr(per, with_year = length(unique(substr(per, 1, 4))) > 1L)
  hov <- vapply(per, fpa_shiny_scn_month_lab, character(1), USE.NAMES = FALSE)
  fc <- r$fc
  op <- ifelse(fc, 0.45, 1)
  line <- gsub("[^A-Za-z0-9_]", "", as.character(sl$line_id[[1]]))
  shapes <- list()
  annos <- list()
  if (nzchar(sel) && sel %in% per) {
    j <- match(sel, per) - 1L
    shapes[[length(shapes) + 1L]] <- list(
      type = "rect", xref = "x", yref = "paper", x0 = j - 0.5, x1 = j + 0.5, y0 = 0, y1 = 1,
      fillcolor = "rgba(196,123,43,0.14)", line = list(width = 0), layer = "below"
    )
  }
  if (any(fc) && any(!fc)) {
    k <- min(which(fc)) - 1L
    shapes[[length(shapes) + 1L]] <- list(
      type = "line", xref = "x", yref = "paper", x0 = k - 0.5, x1 = k - 0.5, y0 = 0, y1 = 1,
      line = list(color = "#5c6b73", width = 1, dash = "dot")
    )
    annos[[length(annos) + 1L]] <- list(
      x = k - 0.5, y = 1, xref = "x", yref = "paper", xanchor = "left", yanchor = "bottom",
      text = paste0("\u00a0", fpa_screen("var_plot_fc"), " \u2192"), showarrow = FALSE,
      font = list(size = 11, color = "#5c6b73")
    )
  }
  series <- list(
    list(id = "volume", y = r$volume, name = fpa_screen("var_col_volume"), col = "#1f4e5f"),
    list(id = "price", y = r$price, name = fpa_screen("var_col_price"), col = "#c47b2b"),
    list(id = "mix", y = r$mix, name = fpa_screen("var_col_mix"), col = "#3b6fb6")
  )
  label <- n <= 6L
  p <- plotly::plot_ly()
  for (s in series) {
    p <- plotly::add_trace(
      p, x = xl, y = s$y, type = "bar", name = s$name,
      marker = list(color = s$col, opacity = op, line = list(width = 0)),
      text = if (label) fpa_var_k(s$y) else NULL,
      textposition = if (label) "outside" else "none",
      textfont = list(size = 11, color = "#0f2f3a"),
      cliponaxis = FALSE,
      hoverinfo = "none"
    )
  }
  month_sum <- r$volume + r$price + r$mix
  cums <- list(
    list(y = cumsum(r$volume), name = fpa_screen("var_pv_cum_volume"), col = "#1f4e5f"),
    list(y = cumsum(r$price), name = fpa_screen("var_pv_cum_price"), col = "#c47b2b"),
    list(y = cumsum(r$mix), name = fpa_screen("var_pv_cum_mix"), col = "#3b6fb6")
  )
  for (s in cums) {
    p <- plotly::add_trace(
      p, x = xl, y = s$y, type = "scatter", mode = "lines+markers",
      name = s$name, yaxis = "y2",
      line = list(color = s$col, width = 2.2),
      marker = list(
        color = "#ffffff", size = 11, symbol = "circle",
        line = list(color = s$col, width = 2.5)
      ),
      hoverinfo = "none"
    )
  }
  axes <- fpa_var_pv_axis_pair(
    unlist(lapply(series, function(s) s$y)),
    unlist(lapply(cums, function(s) s$y))
  )
  tip <- vapply(seq_len(n), function(i) {
    one <- function(id, lab, val) {
      row <- fpa_var_tip_row(lab, paste(fpa_var_eur_s(val), "EUR"))
      if (is.finite(val) && abs(val) >= 0.5) {
        row <- paste0(row, fpa_var_tip_sub(fpa_var_pv_formula(id, r$q0[[i]], r$p0[[i]], r$q1[[i]], r$p1[[i]])))
      }
      row
    }
    rows <- c(
      one("volume", fpa_screen("var_col_volume"), r$volume[[i]]),
      one("price", fpa_screen("var_col_price"), r$price[[i]]),
      one("mix", fpa_screen("var_col_mix"), r$mix[[i]]),
      fpa_var_tip_row(
        fpa_screen("var_pv_col_sum"),
        paste(fpa_var_eur_s(month_sum[[i]]), "EUR"),
        rule = TRUE
      ),
      vapply(seq_along(cums), function(k) {
        fpa_var_tip_row(cums[[k]]$name, paste(fpa_var_eur_s(cums[[k]]$y[[i]]), "EUR"), rule = k == 1L)
      }, character(1))
    )
    fpa_var_tip_html(fpa_var_tip_title(hov[[i]], fc[[i]]), rows)
  }, character(1))
  fig <- plotly::layout(
    p,
    barmode = "group",
    bargap = if (n > 24L) 0.08 else 0.22,
    margin = list(l = 64, r = 68, t = 28, b = 72),
    xaxis = list(
      title = "", type = "category", categoryorder = "array", categoryarray = xl,
      tickfont = fpa_var_axis_font, tickangle = if (n > 18L) -45 else 0, fixedrange = FALSE,
      dtick = if (n > 24L) ceiling(n / 18) else 1,
      showspikes = TRUE, spikemode = "across", spikesnap = "data",
      spikecolor = "#5c6b73", spikethickness = 1, spikedash = "dot"
    ),
    yaxis = list(
      title = "EUR", tickfont = fpa_var_axis_font, gridcolor = "#e6edef",
      zeroline = TRUE, zerolinecolor = "#5c6b73", zerolinewidth = 1,
      separatethousands = TRUE, tickformat = ",.0f",
      range = axes$bars, autorange = FALSE
    ),
    yaxis2 = list(
      title = fpa_screen("var_pv_axis_cum"), overlaying = "y", side = "right",
      tickfont = fpa_var_axis_font, showgrid = FALSE, zeroline = FALSE,
      separatethousands = TRUE, tickformat = ",.0f",
      range = axes$cum, autorange = FALSE
    ),
    separators = ", ",
    legend = list(orientation = "h", x = 0, y = -0.18, font = list(size = 12, color = "#0f2f3a")),
    shapes = shapes, annotations = annos,
    hovermode = "closest", hoverdistance = 36,
    plot_bgcolor = "#ffffff", paper_bgcolor = "#ffffff"
  )
  fpa_var_tip_bind(
    fig, tip, tip_id = "fpa-pv-tip",
    pick = list(line = line, months = I(per))
  )
}

#' Popup body: the volumes file that feeds the price and volume card.
fpa_var_pv_src_body <- function(files) {
  rows <- lapply(files, function(f) {
    name <- basename(f$path)
    safe <- gsub("[^A-Za-z0-9._-]", "", name)
    shiny::tags$tr(
      shiny::tags$td(
        shiny::tags$button(
          type = "button",
          class = "fpa-file-link",
          onclick = sprintf(
            "Shiny.setInputValue('oi_file',{periode:'',file:'%s',kind:'pnl',line:'REV'},{priority:'event'})",
            safe
          ),
          name
        )
      ),
      shiny::tags$td(f$role)
    )
  })
  shiny::div(
    class = "fpa-scn-trace",
    shiny::tags$p(class = "fpa-file-lead", fpa_screen("var_pv_src_lead")),
    shiny::tags$p(class = "fpa-var-note", fpa_screen("var_pv_src_cols")),
    if (length(rows)) {
      shiny::tags$table(
        shiny::tags$thead(shiny::tags$tr(
          shiny::tags$th(fpa_screen("scn_th_file")),
          shiny::tags$th(fpa_screen("scn_th_role"))
        )),
        shiny::tags$tbody(rows)
      )
    } else {
      shiny::tags$p(class = "fpa-var-note", fpa_screen("var_pv_src_none"))
    }
  )
}

#' Causes of one line's variance. `v` is signed (favourable > 0), `raw` keeps the P&L direction.
fpa_var_parts <- function(sl) {
  if (is.null(sl) || !nrow(sl)) return(list())
  line <- as.character(sl$line_id[[1]])
  tot <- function(col, signed = TRUE) {
    if (!col %in% names(sl)) return(0)
    x <- if (signed) fpa_var_sg(line, sl[[col]]) else fpa_var_num(sl[[col]])
    sum(x, na.rm = TRUE)
  }
  defs <- list(
    list(id = "price", col = "price", lab = "var_col_price", tip = "var_pt_price", modal = "price"),
    list(id = "volume", col = "volume", lab = "var_col_volume", tip = "var_pt_volume", modal = "volume"),
    list(id = "mix", col = "mix", lab = "var_col_mix", tip = "var_pt_mix", modal = "mix"),
    list(id = "rate", col = "rate", lab = "var_col_rate", tip = "var_pt_rate", modal = "rate"),
    list(id = "head", col = "headcount", lab = "var_col_head", tip = "var_pt_head", modal = "head")
  )
  rest <- if (fpa_var_has_split(sl)) {
    list(
      list(id = "phase", col = "phase", lab = "var_part_phase", tip = "var_pt_phase", modal = "unexp"),
      list(id = "unlinked", col = "unlinked", lab = "var_part_unlinked", tip = "var_pt_unlinked", modal = "unexp")
    )
  } else {
    list(list(id = "unexp", col = "unexplained", lab = "var_col_unexplained", tip = "var_pt_unexp", modal = "unexp"))
  }
  out <- lapply(c(defs, rest), function(d) {
    d$v <- tot(d$col)
    d$raw <- tot(d$col, signed = FALSE)
    d$named <- d$id %in% c("price", "volume", "mix", "rate", "head")
    d
  })
  Filter(function(d) is.finite(d$v) && abs(d$v) > 0.5, out)
}

fpa_var_line_sum <- function(sl) {
  line <- as.character(sl$line_id[[1]])
  fc <- fpa_var_is_fc(sl)
  s <- fpa_var_sg(line, sl$variance)
  s[!is.finite(s)] <- 0
  list(
    closed = sum(s[!fc]), rest = sum(s[fc]), year = sum(s),
    p_closed = as.character(sl$periode[!fc]), p_fc = as.character(sl$periode[fc]),
    actual = sum(fpa_var_num(sl$actual), na.rm = TRUE),
    budget = sum(fpa_var_num(sl$budget), na.rm = TRUE),
    raw = sum(fpa_var_num(sl$variance), na.rm = TRUE)
  )
}

fpa_var_flat <- function(sl) {
  b <- fpa_var_num(sl$budget)
  a <- fpa_var_num(sl$actual)
  b <- b[is.finite(b)]
  a <- a[is.finite(a)]
  if (length(b) < 6L || length(a) < 6L) return(NULL)
  mb <- mean(abs(b))
  if (!is.finite(mb) || mb < 1) return(NULL)
  if ((max(b) - min(b)) > 0.02 * mb) return(NULL)
  if ((max(a) - min(a)) < 0.25 * mb) return(NULL)
  list(budget = mean(b), lo = min(a), hi = max(a))
}

#' Sentences for the open line. Every number comes from `sl`, nothing is rounded before the sum.
fpa_var_story <- function(sl, vol = NULL) {
  if (is.null(sl) || !nrow(sl)) return(character(0))
  s <- fpa_var_line_sum(sl)
  out <- character(0)
  out <- c(out, if (length(s$p_fc)) {
    fpa_screen("var_s_year", fpa_var_span(s$p_closed), fpa_var_eur_s(s$closed), fpa_var_span(s$p_fc), fpa_var_eur_s(s$rest), fpa_var_eur_s(s$year))
  } else {
    fpa_screen("var_s_year_closed", fpa_var_span(s$p_closed), fpa_var_eur_s(s$closed))
  })
  fl <- fpa_var_flat(sl)
  if (!is.null(fl)) out <- c(out, fpa_screen("var_s_flat", fpa_var_eur(fl$budget), fpa_var_eur(fl$lo), fpa_var_eur(fl$hi)))
  parts <- fpa_var_parts(sl)
  named <- Filter(function(p) isTRUE(p$named), parts)
  if (length(named)) {
    labs <- vapply(named, function(p) fpa_screen(p$lab), character(1))
    labs <- c(labs[[1]], tolower(labs[-1]))
    val <- fpa_var_eur_s(sum(vapply(named, function(p) p$v, numeric(1))))
    out <- c(out, if (length(named) > 1L) fpa_screen("var_s_parts", fpa_var_join(labs), val) else fpa_screen("var_s_part_one", labs, val))
  }
  if (fpa_var_has_split(sl)) {
    line <- as.character(sl$line_id[[1]])
    ph <- sum(fpa_var_sg(line, sl$phase), na.rm = TRUE)
    ph_raw <- sum(fpa_var_num(sl$phase), na.rm = TRUE)
    if (abs(ph) > 0.5) out <- c(out, fpa_screen("var_s_phase", fpa_var_eur_s(ph), fpa_var_eur(s$budget), fpa_var_eur(s$budget + ph_raw)))
    un <- fpa_var_sg(line, sl$unlinked)
    un[!is.finite(un)] <- 0
    tu <- sum(un)
    if (abs(tu) > 0.5) {
      k <- which.max(abs(un))
      big <- un[[k]]
      act <- fpa_var_num(sl$actual[[k]])
      qp <- act - fpa_var_num(sl$unlinked[[k]])
      out <- c(out, if (abs(big) >= 0.5 * abs(tu) && abs(big) >= 500 && is.finite(qp)) {
        fpa_screen("var_s_unlinked", fpa_var_eur_s(tu), fpa_var_eur_s(big), fpa_shiny_scn_month_lab(sl$periode[[k]]), fpa_var_eur(act), fpa_var_eur(qp))
      } else {
        fpa_screen("var_s_unlinked_small", fpa_var_eur_s(tu))
      })
    }
  } else {
    un <- Filter(function(p) identical(p$id, "unexp"), parts)
    if (length(un)) {
      out <- c(out, if (length(named)) fpa_screen("var_s_unexp_rest", fpa_var_eur_s(un[[1]]$v)) else fpa_screen("var_s_unexp_only", fpa_var_eur_s(un[[1]]$v)))
    }
  }
  out
}

#' One sentence per Écarts card, shown while the card is folded.
fpa_var_card_facts <- function(v, sl = NULL) {
  blank <- ""
  hero <- if (is.null(v) || !nrow(v)) {
    fpa_screen("var_empty")
  } else {
    m <- fpa_var_hero_math(v)
    if (isTRUE(m$has_rest)) {
      fpa_screen("var_hero_oi", fpa_var_eur_s(m$year), fpa_var_eur_s(m$closed), fpa_var_eur_s(m$rest))
    } else {
      fpa_screen("var_hero_oi_closed", fpa_var_eur_s(m$closed))
    }
  }
  oi_year <- if (is.null(v) || !nrow(v)) NA_real_ else fpa_var_hero_math(v)$year
  has_line <- !is.null(sl) && nrow(sl) > 0
  line_name <- if (has_line) fpa_shiny_line_name(as.character(sl$line_id[[1]])) else ""
  s <- if (has_line) fpa_var_line_sum(sl) else NULL
  heat <- if (is.null(v) || !nrow(v)) {
    fpa_screen("var_empty")
  } else if (is.null(s)) {
    fpa_screen("var_heat_fact_oi", fpa_var_eur_s(oi_year))
  } else {
    fpa_screen("var_heat_fact", fpa_var_eur_s(oi_year), line_name, fpa_var_eur_s(s$year))
  }
  if (is.null(s)) {
    return(list(hero = hero, heat = heat, line = blank, pv = blank, bridge = blank, parts = blank, months = blank))
  }
  story <- fpa_var_story(sl)
  line <- if (length(story)) fpa_screen("var_line_fact", line_name, story[[1]]) else line_name
  pv_f <- fpa_var_pv_frame(sl)
  pv <- if (is.null(pv_f)) {
    fpa_screen("var_pv_none_line")
  } else {
    cl <- pv_f$rows[!pv_f$rows$fc, , drop = FALSE]
    if (!nrow(cl)) {
      fpa_screen("var_pv_none_line")
    } else {
      fpa_screen(
        "var_pv_year", fpa_var_span(cl$periode),
        fpa_var_eur_s(sum(cl$price)), fpa_var_eur_s(sum(cl$volume)), fpa_var_eur_s(sum(cl$mix)),
        fpa_var_eur_s(sum(cl$price) + sum(cl$volume) + sum(cl$mix))
      )
    }
  }
  parts <- fpa_var_parts(sl)
  parts_fact <- if (!length(parts)) {
    fpa_screen("var_parts_fact_none")
  } else {
    top <- parts[[order(-vapply(parts, function(p) abs(p$v), numeric(1)))[[1]]]]
    denom <- sum(vapply(parts, function(p) abs(p$v), numeric(1)))
    share <- if (denom > 0) round(100 * abs(top$v) / denom) else 0
    fpa_screen("var_parts_fact", fpa_screen(top$lab), fpa_var_eur_s(top$v), formatC(share, format = "f", digits = 0))
  }
  list(
    hero = hero, heat = heat, line = line, pv = pv,
    bridge = fpa_screen("var_bridge_fact", fpa_var_eur(s$budget), fpa_var_eur(s$actual), fpa_var_eur_s(s$year)),
    parts = parts_fact,
    months = fpa_screen("var_tbl_fact", fpa_var_eur(s$actual), fpa_var_eur(s$budget), fpa_var_eur_s(s$year))
  )
}

#' Foldable Écarts card. `open` stays on this tag, so a redraw of the body does not collapse it.
fpa_var_fold <- function(id, kicker, fact, ..., open = FALSE) {
  shiny::tags$details(
    class = paste("fpa-fold fpa-var-fold", paste0("fpa-var-fold-", id)),
    id = paste0("fpa-var-fold-", id),
    open = if (isTRUE(open)) NA else NULL,
    shiny::tags$summary(
      shiny::tags$span(class = "fpa-fold-k", kicker),
      shiny::tags$span(class = "fpa-fold-fact", fact)
    ),
    shiny::tags$div(class = "fpa-fold-body", ...)
  )
}

#' Budget, causes, landing. Raw P&L direction so the chain ends on the landed amount.
fpa_var_bridge_frame <- function(sl) {
  if (is.null(sl) || !nrow(sl)) return(NULL)
  line <- as.character(sl$line_id[[1]])
  s <- fpa_var_line_sum(sl)
  parts <- fpa_var_parts(sl)
  if (!any(vapply(parts, function(p) isTRUE(p$named) || p$id %in% c("phase", "unlinked"), logical(1)))) {
    fc <- fpa_var_is_fc(sl)
    raw <- fpa_var_num(sl$variance)
    raw[!is.finite(raw)] <- 0
    steps <- list(
      list(label = fpa_screen("var_bridge_closed"), raw = sum(raw[!fc]), tip = fpa_screen("var_pt_closed")),
      list(label = fpa_screen("var_bridge_fc"), raw = sum(raw[fc]), tip = fpa_screen("var_pt_fc"))
    )
    steps <- Filter(function(x) abs(x$raw) > 0.5, steps)
  } else {
    steps <- lapply(parts, function(p) list(label = fpa_screen(p$lab), raw = p$raw, tip = fpa_screen(p$tip)))
  }
  sign <- fpa_pnl_ni_sign(line)
  if (!is.finite(sign) || sign == 0) sign <- 1
  lab <- c(fpa_screen("var_bridge_budget"), vapply(steps, function(x) x$label, character(1)), fpa_screen("var_bridge_landing"))
  tip <- c("", vapply(steps, function(x) x$tip, character(1)), "")
  raw <- c(s$budget, vapply(steps, function(x) x$raw, numeric(1)), s$budget + sum(vapply(steps, function(x) x$raw, numeric(1))))
  kind <- c("total", rep("step", length(steps)), "total")
  start <- numeric(length(raw))
  end <- numeric(length(raw))
  run <- s$budget
  for (i in seq_along(raw)) {
    if (kind[[i]] == "total") {
      start[[i]] <- 0
      end[[i]] <- raw[[i]]
    } else {
      start[[i]] <- run
      end[[i]] <- run + raw[[i]]
      run <- end[[i]]
    }
  }
  data.frame(
    label = lab, kind = kind, raw = raw, signed = raw * sign, start = start, end = end, tip = tip,
    stringsAsFactors = FALSE
  )
}

#' Integers that sum to the rounded total. Each stays within 1 EUR of its own value.
fpa_var_round_tie <- function(parts, total) {
  parts <- fpa_var_num(parts)
  parts <- parts[is.finite(parts)]
  target <- round(total)
  if (!length(parts)) return(list(parts = target, total = target))
  fl <- floor(parts)
  gap <- as.integer(target - sum(fl))
  if (gap != 0 && length(fl)) {
    rem <- parts - fl
    ord <- order(rem, decreasing = gap > 0)
    step <- if (gap > 0) 1L else -1L
    idx <- ord[((seq_len(abs(gap)) - 1L) %% length(ord)) + 1L]
    for (i in idx) fl[[i]] <- fl[[i]] + step
  }
  list(parts = fl, total = target)
}

fpa_var_calc_tip <- function(parts, total) {
  tied <- fpa_var_round_tie(parts, total)
  paste(c(vapply(tied$parts, fpa_var_eur_s, character(1)), paste0("= ", fpa_var_eur_s(tied$total))), collapse = "|")
}

fpa_var_sum_tip <- function(parts, total) {
  parts <- fpa_var_num(parts)
  parts <- parts[is.finite(parts)]
  kept <- parts[abs(parts) >= 0.5]
  if (length(kept) && abs(sum(kept) - total) < 0.51) parts <- kept
  if (!length(parts)) return(fpa_var_eur_s(total))
  fpa_var_calc_tip(parts, total)
}

#' Two signed amounts, no words. sign * actual and -sign * budget add to the cell.
fpa_var_pair_tip <- function(actual, budget, sign, cell) {
  if (!is.finite(sign) || sign == 0) sign <- 1
  a <- fpa_var_num(actual)
  b <- fpa_var_num(budget)
  if (!is.finite(a)) a <- 0
  if (!is.finite(b)) b <- 0
  fpa_var_calc_tip(c(sign * a, -sign * b), cell)
}

#' Same rows as the level chart: actual, budget, and budgeted quantity x rate when it exists.
fpa_var_level_tip <- function(title, actual, budget, ecart, qp = NULL) {
  rows <- c(
    fpa_var_tip_row(fpa_screen("var_plot_actual"), paste(fpa_var_eur(actual), "EUR")),
    fpa_var_tip_row(fpa_screen("var_plot_budget"), paste(fpa_var_eur(budget), "EUR"), rule = TRUE)
  )
  q <- fpa_var_num(qp)[1]
  if (is.finite(q)) rows <- c(rows, fpa_var_tip_row(fpa_screen("var_plot_vol_budget"), paste(fpa_var_eur(q), "EUR")))
  rows <- c(rows, fpa_var_tip_row(fpa_screen("var_col_variance"), paste(fpa_var_eur_s(ecart), "EUR"), rule = TRUE))
  fpa_var_tip_html(title, rows)
}

fpa_var_cell_bg <- function(v, vmax) {
  if (!is.finite(v) || abs(v) < 0.5 || !is.finite(vmax) || vmax <= 0) return(list(bg = "#ffffff", dark = FALSE))
  a <- 0.08 + 0.82 * sqrt(min(1, abs(v) / vmax))
  rgb <- if (v > 0) "31,78,95" else "140,58,58"
  list(bg = sprintf("rgba(%s,%.2f)", rgb, a), dark = a >= 0.5)
}

fpa_var_heat_ui <- function(v, sel_line = NULL, sel_month = "", vol = NULL) {
  if (is.null(v) || !nrow(v)) return(NULL)
  periods <- sort(unique(as.character(v$periode)))
  fc_p <- unique(as.character(v$periode[fpa_var_is_fc(v)]))
  is_fc <- periods %in% fc_p
  multi_year <- length(unique(substr(periods, 1, 4))) > 1L
  present <- unique(as.character(v$line_id))
  lines <- c(intersect(fpa_var_line_order, present), setdiff(present, fpa_var_line_order))
  mat <- matrix(0, nrow = length(lines), ncol = length(periods), dimnames = list(lines, periods))
  act <- bud <- matrix(NA_real_, nrow = length(lines), ncol = length(periods), dimnames = list(lines, periods))
  for (i in seq_len(nrow(v))) {
    ln <- as.character(v$line_id[[i]])
    p <- as.character(v$periode[[i]])
    x <- fpa_var_sg(ln, v$variance[[i]])
    mat[ln, p] <- if (is.finite(x)) x else 0
    act[ln, p] <- fpa_var_num(v$actual[[i]])
    bud[ln, p] <- fpa_var_num(v$budget[[i]])
  }
  zero <- apply(abs(mat) < 0.5, 1, all)
  hidden <- lines[zero]
  lines <- lines[!zero]
  oi_in <- intersect(fpa_var_oi_lines, lines)
  oi <- if (length(oi_in)) colSums(mat[oi_in, , drop = FALSE]) else NULL
  qp <- matrix(NA_real_, nrow = length(lines), ncol = length(periods), dimnames = list(lines, periods))
  if (!is.null(vol) && "REV" %in% lines && all(c("periode", "nuitees_budget", "tarif_budget") %in% names(vol))) {
    vp <- as.character(vol$periode)
    for (j in seq_along(periods)) {
      hit <- match(periods[[j]], vp)
      if (is.na(hit)) next
      q0 <- fpa_var_num(vol$nuitees_budget[[hit]])
      p0 <- fpa_var_num(vol$tarif_budget[[hit]])
      if (is.finite(q0) && is.finite(p0)) qp["REV", periods[[j]]] <- q0 * p0
    }
  }
  sum_win <- function(row, mask) {
    z <- row[mask]
    z <- z[is.finite(z)]
    if (!length(z)) NA_real_ else sum(z)
  }
  vmax <- max(c(abs(mat[lines, , drop = FALSE]), abs(oi), 0), na.rm = TRUE)
  tot_of <- function(x) c(closed = sum(x[!is_fc]), rest = sum(x[is_fc]), year = sum(x))
  tmax <- max(c(0, unlist(lapply(lines, function(l) abs(tot_of(mat[l, ])))), if (!is.null(oi)) abs(tot_of(oi))), na.rm = TRUE)
  dense <- length(periods) > 14L
  esc <- function(x) gsub("[^A-Za-z0-9_-]", "", x)
  pick_js <- function(line, month) sprintf(
    "Shiny.setInputValue('var_pick',{line:'%s',month:'%s',n:Date.now()},{priority:'event'})",
    esc(line), esc(month)
  )
  cell <- function(val, tip, cls = NULL, onclick = NULL, scale = vmax, text = fpa_var_k(val), html = FALSE) {
    st <- fpa_var_cell_bg(val, scale)
    shiny::tags$td(
      class = paste(c("fpa-vh-c", cls, if (st$dark) "is-dark", if (is.finite(val) && abs(val) >= 1000) "is-big",
                      if (!is.finite(val) || abs(val) < 50) "is-zero"), collapse = " "),
      style = sprintf("background:%s;", st$bg),
      `data-tip` = tip,
      `data-tip-html` = if (isTRUE(html)) "1" else NULL,
      onclick = onclick,
      if (dense) NULL else if (identical(text, "0")) "\u00b7" else text
    )
  }
  row_ui <- function(ln) {
    x <- mat[ln, ]
    nm <- fpa_shiny_line_name(ln)
    tt <- tot_of(x)
    has_q <- any(is.finite(qp[ln, ]))
    level <- function(mask, ecart, title) {
      q <- if (has_q) sum_win(qp[ln, ], mask) else NULL
      fpa_var_level_tip(title, sum_win(act[ln, ], mask), sum_win(bud[ln, ], mask), ecart, q)
    }
    shiny::tags$tr(
      class = paste(c("fpa-vh-row", if (identical(ln, sel_line)) "is-on"), collapse = " "),
      shiny::tags$th(
        scope = "row", class = "fpa-vh-name", onclick = pick_js(ln, ""),
        shiny::tags$span(class = "fpa-vh-dot", if (identical(ln, sel_line)) "\u25B6" else ""),
        nm
      ),
      lapply(seq_along(periods), function(j) {
        p <- periods[[j]]
        q <- if (has_q && is.finite(qp[ln, p])) qp[ln, p] else NULL
        cell(
          x[[j]],
          fpa_var_level_tip(fpa_var_tip_title(fpa_shiny_scn_month_lab(p), is_fc[[j]]), act[ln, p], bud[ln, p], x[[j]], q),
          cls = c(if (is_fc[[j]]) "is-fc", if (identical(ln, sel_line) && identical(p, sel_month)) "is-sel"),
          onclick = pick_js(ln, p),
          html = TRUE
        )
      }),
      cell(tt[["closed"]], level(!is_fc, tt[["closed"]], fpa_screen("var_heat_col_closed")), cls = "is-tot is-first", scale = tmax, text = fpa_var_eur_s(tt[["closed"]]), onclick = pick_js(ln, ""), html = TRUE),
      cell(tt[["rest"]], if (any(is_fc)) level(is_fc, tt[["rest"]], fpa_screen("var_heat_col_rest")) else fpa_var_eur_s(0), cls = "is-tot", scale = tmax, text = if (any(is_fc)) fpa_var_eur_s(tt[["rest"]]) else "\u2013", onclick = pick_js(ln, ""), html = any(is_fc)),
      cell(tt[["year"]], level(rep(TRUE, length(periods)), tt[["year"]], fpa_screen("var_heat_col_year")), cls = "is-tot is-year", scale = tmax, text = fpa_var_eur_s(tt[["year"]]), onclick = pick_js(ln, ""), html = TRUE)
    )
  }
  oi_row <- if (!is.null(oi)) {
    tt <- tot_of(oi)
    shiny::tags$tr(
      class = "fpa-vh-row is-oi",
      shiny::tags$th(scope = "row", class = "fpa-vh-name", `data-tip` = fpa_screen("var_heat_oi_tip"), fpa_shiny_line_name("OI")),
      lapply(seq_along(periods), function(j) cell(
        oi[[j]], fpa_var_sum_tip(mat[oi_in, periods[[j]]], oi[[j]]),
        cls = if (is_fc[[j]]) "is-fc" else NULL
      )),
      cell(tt[["closed"]], fpa_var_sum_tip(oi[!is_fc], tt[["closed"]]), cls = "is-tot is-first", scale = tmax, text = fpa_var_eur_s(tt[["closed"]])),
      cell(tt[["rest"]], if (any(is_fc)) fpa_var_sum_tip(oi[is_fc], tt[["rest"]]) else fpa_var_eur_s(0), cls = "is-tot", scale = tmax, text = if (any(is_fc)) fpa_var_eur_s(tt[["rest"]]) else "\u2013"),
      cell(tt[["year"]], fpa_var_calc_tip(c(tt[["closed"]], tt[["rest"]]), tt[["year"]]), cls = "is-tot is-year", scale = tmax, text = fpa_var_eur_s(tt[["year"]]))
    )
  }
  body <- list()
  for (ln in lines) {
    body[[length(body) + 1L]] <- row_ui(ln)
    if (!is.null(oi_row) && identical(ln, oi_in[[length(oi_in)]])) body[[length(body) + 1L]] <- oi_row
  }
  n_act <- sum(!is_fc)
  n_fc <- sum(is_fc)
  mlab <- fpa_var_month_abbr(periods, with_year = multi_year)
  shiny::tags$section(
    class = "fpa-vh",
    shiny::tags$p(class = "fpa-var-lead", fpa_screen("var_heat_lead")),
    shiny::tags$div(
      class = paste(c("fpa-vh-wrap", if (dense) "is-dense"), collapse = " "),
      shiny::tags$table(
        class = "fpa-vh-table",
        shiny::tags$thead(
          shiny::tags$tr(
            class = "fpa-vh-band",
            shiny::tags$th(""),
            if (n_act) shiny::tags$th(colspan = n_act, class = "is-act", fpa_screen("var_heat_band_actual")),
            if (n_fc) shiny::tags$th(colspan = n_fc, class = "is-fc", fpa_screen("var_heat_band_fc")),
            shiny::tags$th(colspan = 3, class = "is-tot", fpa_screen("var_heat_band_tot"))
          ),
          shiny::tags$tr(
            shiny::tags$th(class = "fpa-vh-name", fpa_screen("var_heat_col_line")),
            lapply(seq_along(periods), function(j) shiny::tags$th(
              class = paste(c(if (is_fc[[j]]) "is-fc", if (identical(periods[[j]], sel_month)) "is-sel"), collapse = " "),
              title = fpa_shiny_scn_month_lab(periods[[j]]),
              mlab[[j]]
            )),
            shiny::tags$th(class = "is-tot is-first", fpa_screen("var_heat_col_closed")),
            shiny::tags$th(class = "is-tot", fpa_screen("var_heat_col_rest")),
            shiny::tags$th(class = "is-tot is-year", fpa_screen("var_heat_col_year"))
          )
        ),
        shiny::tags$tbody(body)
      )
    ),
    if (dense) shiny::tags$p(class = "fpa-var-note", fpa_screen("var_heat_dense")),
    if (length(hidden)) shiny::tags$p(class = "fpa-var-note", fpa_screen("var_heat_hidden", paste(vapply(hidden, fpa_shiny_line_name, character(1)), collapse = ", ")))
  )
}

#' Integers for one card. Small parts drop when the rest still equals the total.
fpa_var_math_tie <- function(labels, vals, total, drop_small = TRUE) {
  labels <- as.character(labels)
  vals <- fpa_var_num(vals)
  vals[!is.finite(vals)] <- 0
  total <- fpa_var_num(total)[1]
  if (!is.finite(total)) total <- 0
  if (!length(vals)) return(list(labels = character(), shown = numeric(), total = round(total), hidden = character()))
  keep <- if (isTRUE(drop_small)) abs(vals) >= 0.5 else rep(TRUE, length(vals))
  if (any(keep) && abs(sum(vals[keep]) - total) >= 0.51) keep[] <- TRUE
  if (!any(keep) && abs(total) >= 0.51) keep[] <- TRUE
  hidden <- labels[!keep]
  labels <- labels[keep]
  vals <- vals[keep]
  if (!length(vals)) return(list(labels = character(), shown = numeric(), total = round(total), hidden = hidden))
  tied <- fpa_var_round_tie(vals, total)
  list(labels = labels, shown = as.numeric(tied$parts), total = tied$total, hidden = hidden)
}

fpa_var_math_table <- function(labels, shown, total) {
  body <- lapply(seq_along(labels), function(i) {
    shiny::tags$tr(
      class = if (is.finite(shown[[i]]) && shown[[i]] < 0) "is-neg",
      shiny::tags$td(labels[[i]]),
      shiny::tags$td(class = "n", fpa_var_eur_s(shown[[i]]))
    )
  })
  shiny::tags$table(
    shiny::tags$tbody(
      body,
      shiny::tags$tr(
        class = "is-sum",
        shiny::tags$td(fpa_screen("var_math_total")),
        shiny::tags$td(class = "n", fpa_var_eur_s(total))
      )
    )
  )
}

fpa_var_math_col <- function(title, tied, hidden_key) {
  shiny::tags$div(
    class = "fpa-var-math-col",
    shiny::tags$h4(title),
    fpa_var_math_table(tied$labels, tied$shown, tied$total),
    if (length(tied$hidden)) shiny::tags$p(class = "fpa-var-note", fpa_screen(hidden_key, paste(tied$hidden, collapse = ", ")))
  )
}

#' Signed operating-income parts behind the three cards.
fpa_var_hero_math <- function(v) {
  fc <- fpa_var_is_fc(v)
  sg <- vapply(seq_len(nrow(v)), function(i) fpa_var_sg(as.character(v$line_id[[i]]), v$variance[[i]]), numeric(1))
  sg[!is.finite(sg)] <- 0
  in_oi <- as.character(v$line_id) %in% fpa_var_oi_lines
  closed <- sum(sg[in_oi & !fc])
  rest <- sum(sg[in_oi & fc])
  year <- closed + rest
  ids <- intersect(fpa_var_oi_lines, unique(as.character(v$line_id)))
  line_vals <- function(mask) {
    vapply(ids, function(id) sum(sg[as.character(v$line_id) == id & mask]), numeric(1))
  }
  month_of <- function(mask) {
    p <- sort(unique(as.character(v$periode[mask])))
    if (!length(p)) return(list(labels = character(), vals = numeric()))
    multi <- length(unique(substr(as.character(v$periode), 1, 4))) > 1L
    list(
      labels = fpa_var_month_abbr(p, with_year = multi),
      vals = vapply(p, function(one) sum(sg[in_oi & as.character(v$periode) == one]), numeric(1))
    )
  }
  names <- vapply(ids, fpa_shiny_line_name, character(1))
  c_lines <- line_vals(!fc)
  r_lines <- line_vals(fc)
  y_lines <- line_vals(rep(TRUE, nrow(v)))
  c_months <- month_of(!fc)
  r_months <- month_of(fc)
  list(
    closed = closed, rest = rest, year = year,
    has_rest = any(fc),
    closed_lines = fpa_var_math_tie(names, c_lines, closed),
    rest_lines = fpa_var_math_tie(names, r_lines, rest),
    year_lines = fpa_var_math_tie(names, y_lines, year),
    closed_months = fpa_var_math_tie(c_months$labels, c_months$vals, closed),
    rest_months = fpa_var_math_tie(r_months$labels, r_months$vals, rest),
    year_periods = fpa_var_math_tie(
      c(fpa_screen("var_tile_closed"), fpa_screen("var_tile_rest")),
      c(closed, rest),
      year,
      drop_small = FALSE
    )
  )
}

fpa_var_hero_ui <- function(v) {
  if (is.null(v) || !nrow(v)) {
    return(shiny::tags$section(
      class = "fpa-path fpa-var-hero",
      shiny::tags$p(class = "fpa-path-kicker", fpa_screen("var_kicker")),
      shiny::tags$h2(fpa_screen("var_title")),
      shiny::tags$p(fpa_screen("var_empty"))
    ))
  }
  fc <- fpa_var_is_fc(v)
  m <- fpa_var_hero_math(v)
  closed <- m$closed
  rest <- m$rest
  year <- m$year
  p_closed <- unique(as.character(v$periode[!fc]))
  p_fc <- unique(as.character(v$periode[fc]))
  sg <- vapply(seq_len(nrow(v)), function(i) fpa_var_sg(as.character(v$line_id[[i]]), v$variance[[i]]), numeric(1))
  sg[!is.finite(sg)] <- 0
  by_line <- tapply(sg, as.character(v$line_id), sum)
  by_line <- by_line[is.finite(by_line) & abs(by_line) > 0.5]
  top <- if (length(by_line)) names(by_line)[which.max(abs(by_line))] else NULL
  chev <- shiny::HTML('<svg class="chev" width="12" height="12" viewBox="0 0 16 16" aria-hidden="true"><path d="M3 6 L8 11 L13 6" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>')
  tile <- function(id, lab, val, sub, cls = NULL) {
    shiny::tags$button(
      type = "button",
      class = paste(c("fpa-var-tile", cls, if (is.finite(val) && val < -0.5) "is-neg" else if (is.finite(val) && val > 0.5) "is-pos"), collapse = " "),
      `aria-expanded` = "false",
      `aria-controls` = paste0("fpa-var-math-", id),
      title = fpa_screen("var_tile_calc"),
      onclick = "if (window.fpaVarTile) window.fpaVarTile(this);",
      shiny::tags$span(class = "k", lab, chev),
      shiny::tags$span(class = "v", fpa_var_eur_s(val), shiny::tags$small(" EUR")),
      shiny::tags$span(class = "s", sub)
    )
  }
  panel <- function(id, ...) {
    shiny::tags$div(id = paste0("fpa-var-math-", id), class = "fpa-var-math", hidden = "hidden", ...)
  }
  verdict <- if (length(p_fc)) {
    fpa_screen("var_hero_oi", fpa_var_eur_s(year), fpa_var_eur_s(closed), fpa_var_eur_s(rest))
  } else {
    fpa_screen("var_hero_oi_closed", fpa_var_eur_s(closed))
  }
  join <- function(word) {
    shiny::tags$div(
      class = "fpa-var-join",
      role = "img",
      `aria-label` = word,
      shiny::tags$span(class = "w", word),
      shiny::HTML(paste0(
        '<svg class="fpa-var-arrow" viewBox="0 0 36 14" width="36" height="14" focusable="false" aria-hidden="true">',
        '<path d="M1 7h26" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>',
        '<path d="M22 2.2 33 7 22 11.8" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>',
        "</svg>"
      ))
    )
  }
  shiny::tags$section(
    class = "fpa-path fpa-var-hero",
    shiny::tags$p(class = "fpa-path-kicker", fpa_screen("var_kicker")),
    shiny::tags$h2(fpa_screen("var_title")),
    shiny::tags$p(fpa_screen("var_intro")),
    shiny::tags$div(class = "fpa-var-tiles-head", fpa_screen("var_tile_head")),
    shiny::tags$div(
      class = "fpa-var-tiles",
      tile("closed", fpa_screen("var_tile_closed"), closed, fpa_screen("var_tile_closed_sub", fpa_var_span(p_closed))),
      join(fpa_screen("var_join_then")),
      tile("rest", fpa_screen("var_tile_rest"), if (length(p_fc)) rest else NA_real_,
           if (length(p_fc)) fpa_screen("var_tile_rest_sub", fpa_var_span(p_fc)) else fpa_screen("var_tile_none_sub")),
      join(fpa_screen("var_join_eq")),
      tile("year", fpa_screen("var_tile_year"), year, fpa_screen("var_tile_year_sub"), cls = "is-year")
    ),
    panel(
      "closed",
      shiny::tags$div(
        class = "fpa-var-math-grid",
        fpa_var_math_col(fpa_screen("var_math_lines"), m$closed_lines, "var_math_hidden"),
        fpa_var_math_col(fpa_screen("var_math_months"), m$closed_months, "var_math_months_hidden")
      )
    ),
    panel(
      "rest",
      if (length(p_fc)) {
        shiny::tags$div(
          class = "fpa-var-math-grid",
          fpa_var_math_col(fpa_screen("var_math_lines"), m$rest_lines, "var_math_hidden"),
          fpa_var_math_col(fpa_screen("var_math_months"), m$rest_months, "var_math_months_hidden")
        )
      } else {
        shiny::tags$p(class = "fpa-var-note", fpa_screen("var_tile_none_sub"))
      }
    ),
    panel(
      "year",
      shiny::tags$div(
        class = "fpa-var-math-grid",
        if (length(p_fc)) fpa_var_math_col(fpa_screen("var_math_periods"), m$year_periods, "var_math_hidden"),
        fpa_var_math_col(fpa_screen("var_math_lines"), m$year_lines, "var_math_hidden")
      )
    ),
    shiny::tags$div(
      class = "fpa-drv-lead",
      shiny::tags$p(shiny::tags$strong(verdict)),
      if (!is.null(top)) shiny::tags$p(fpa_screen("var_hero_top", fpa_shiny_line_name(top), fpa_var_eur_s(by_line[[top]])))
    )
  )
}

fpa_var_parts_ui <- function(sl) {
  parts <- fpa_var_parts(sl)
  head <- shiny::tags$p(class = "fpa-var-lead", fpa_screen("var_parts_lead"))
  named <- Filter(function(p) isTRUE(p$named) || p$id %in% c("phase", "unlinked"), parts)
  if (!length(parts)) return(shiny::tagList(head, shiny::tags$p(class = "fpa-var-note", fpa_screen("var_parts_none"))))
  ord <- order(-vapply(parts, function(p) abs(p$v), numeric(1)))
  parts <- parts[ord]
  denom <- sum(vapply(parts, function(p) abs(p$v), numeric(1)))
  rows <- lapply(parts, function(p) {
    share <- if (denom > 0) abs(p$v) / denom else 0
    shiny::tags$button(
      type = "button",
      class = paste("fpa-var-part", if (p$v < 0) "is-neg" else "is-pos"),
      onclick = sprintf("Shiny.setInputValue('var_card','%s',{priority:'event'})", p$modal),
      shiny::tags$span(class = "fpa-var-part-top",
        shiny::tags$span(class = "fpa-var-part-sign", if (p$v < 0) "\u2212" else "+"),
        shiny::tags$span(class = "fpa-var-part-lab", fpa_screen(p$lab)),
        shiny::tags$span(class = "fpa-var-part-v", fpa_var_eur_s(p$v), " EUR")
      ),
      shiny::tags$span(class = "fpa-var-part-bar", shiny::tags$span(style = sprintf("width:%.1f%%;", 100 * share))),
      shiny::tags$span(class = "fpa-var-part-txt",
        fpa_screen(p$tip), " ",
        shiny::tags$em(fpa_screen("var_part_share", formatC(100 * share, format = "f", digits = 0)))
      )
    )
  })
  shiny::tagList(
    head,
    shiny::tags$div(class = "fpa-var-parts", rows),
    if (!length(named)) shiny::tags$p(class = "fpa-var-note", fpa_screen("var_parts_none"))
  )
}

fpa_var_table_ui <- function(sl, sel_month = "") {
  if (is.null(sl) || !nrow(sl)) return(NULL)
  line <- as.character(sl$line_id[[1]])
  fc <- fpa_var_is_fc(sl)
  split <- fpa_var_has_split(sl)
  qp_at <- function(i) {
    b <- fpa_var_num(sl$budget[[i]])
    ph <- fpa_var_num(sl$phase[[i]])
    if (is.finite(b) && is.finite(ph)) b + ph else NA_real_
  }
  comp <- c(price = "var_col_price", volume = "var_col_volume", mix = "var_col_mix", rate = "var_col_rate", headcount = "var_col_head")
  if (split) comp <- c(comp, phase = "var_col_phase", unlinked = "var_col_unlinked") else comp <- c(comp, unexplained = "var_col_unexplained")
  comp <- comp[names(comp) %in% names(sl)]
  empty <- vapply(names(comp), function(nm) {
    x <- fpa_var_num(sl[[nm]])
    !length(x) || all(!is.finite(x) | abs(x) < 0.5)
  }, logical(1))
  hidden <- unname(vapply(comp[empty], fpa_txt, character(1)))
  comp <- comp[!empty]
  sv <- fpa_var_sg(line, sl$variance)
  sv0 <- sv
  sv0[!is.finite(sv0)] <- 0
  cum <- cumsum(sv0)
  num_td <- function(x, txt = fpa_var_eur_s(x), cls = NULL) shiny::tags$td(
    class = paste(c(cls, if (is.finite(x) && round(x) < 0) "neg"), collapse = " "),
    txt
  )
  esc <- function(x) gsub("[^A-Za-z0-9_-]", "", x)
  rows <- lapply(seq_len(nrow(sl)), function(i) {
    p <- as.character(sl$periode[[i]])
    b <- fpa_var_num(sl$budget[[i]])
    pct <- if (is.finite(b) && abs(b) > 1e-9) sv[[i]] / abs(b) else NA_real_
    shiny::tags$tr(
      class = paste(c(if (fc[[i]]) "is-fc", if (identical(p, sel_month)) "is-sel"), collapse = " "),
      onclick = sprintf("Shiny.setInputValue('var_pick',{line:'%s',month:'%s',n:Date.now()},{priority:'event'})", esc(line), esc(p)),
      shiny::tags$td(
        class = "is-month",
        fpa_shiny_scn_month_lab(p),
        if (fc[[i]]) shiny::tags$span(class = "fpa-var-chip", fpa_screen("var_chip_fc"))
      ),
      num_td(fpa_var_num(sl$actual[[i]]), fpa_var_eur(sl$actual[[i]])),
      num_td(b, fpa_var_eur(b)),
      if (split) num_td(qp_at(i), fpa_var_eur(qp_at(i))),
      num_td(sv[[i]], cls = "is-gap"),
      num_td(pct, fpa_var_pct_s(pct)),
      lapply(names(comp), function(nm) num_td(fpa_var_sg(line, sl[[nm]][[i]]), cls = "is-comp")),
      num_td(cum[[i]], cls = "is-cum")
    )
  })
  ta <- sum(fpa_var_num(sl$actual), na.rm = TRUE)
  tb <- sum(fpa_var_num(sl$budget), na.rm = TRUE)
  tq <- if (split) sum(vapply(seq_len(nrow(sl)), qp_at, numeric(1)), na.rm = TRUE) else NA_real_
  tv <- sum(sv0)
  total <- shiny::tags$tr(
    class = "is-total",
    shiny::tags$td(class = "is-month", fpa_screen("var_tbl_total")),
    num_td(ta, fpa_var_eur(ta)),
    num_td(tb, fpa_var_eur(tb)),
    if (split) num_td(tq, fpa_var_eur(tq)),
    num_td(tv, cls = "is-gap"),
    num_td(if (abs(tb) > 1e-9) tv / abs(tb) else NA_real_, fpa_var_pct_s(if (abs(tb) > 1e-9) tv / abs(tb) else NA_real_)),
    lapply(names(comp), function(nm) num_td(sum(fpa_var_sg(line, sl[[nm]]), na.rm = TRUE), cls = "is-comp")),
    num_td(tv, cls = "is-cum")
  )
  shiny::tags$section(
    class = "fpa-var-tbl-sec",
    shiny::tags$p(class = "fpa-var-lead", fpa_screen("var_tbl_lead")),
    shiny::tags$div(
      class = "fpa-var-table",
      shiny::tags$table(
        shiny::tags$thead(shiny::tags$tr(
          shiny::tags$th(fpa_screen("var_col_periode")),
          shiny::tags$th(if (any(fc)) fpa_screen("var_col_actual_fc") else fpa_screen("var_col_actual")),
          shiny::tags$th(fpa_screen("var_col_budget")),
          if (split) shiny::tags$th(class = "is-qp", fpa_screen("var_plot_vol_budget")),
          shiny::tags$th(fpa_screen("var_col_variance")),
          shiny::tags$th(fpa_screen("var_col_pct")),
          lapply(unname(comp), function(k) shiny::tags$th(class = "is-comp", fpa_screen(k))),
          shiny::tags$th(fpa_screen("var_col_cum"))
        )),
        shiny::tags$tbody(rows, total)
      )
    ),
    if (any(fc)) shiny::tags$p(class = "fpa-var-note", fpa_screen("var_fc_note", fpa_shiny_scn_span(sl$periode[fc]))),
    if (length(hidden)) shiny::tags$p(class = "fpa-var-note", fpa_screen("var_hidden_cols", paste(hidden, collapse = ", ")))
  )
}

fpa_var_part_colour <- c(
  price = "#1f4e5f", volume = "#6fa3b3", mix = "#c47b2b", rate = "#1f4e5f", head = "#6fa3b3",
  phase = "#b9c6cb", unlinked = "#3d4c54"
)

fpa_var_axis_font <- list(size = 11, color = "#3d4c54")

fpa_var_tip_row <- function(label, value, rule = FALSE) {
  neg <- grepl("^\u2212", value)
  col <- if (neg) "#f0c2c2" else "#ffffff"
  edge <- if (isTRUE(rule)) "margin-top:6px;padding-top:6px;border-top:1px solid rgba(255,255,255,0.28);" else ""
  sprintf(
    "<div style='display:flex;justify-content:space-between;gap:18px;align-items:baseline;%s'><span>%s</span><span style='font-variant-numeric:tabular-nums;font-weight:650;color:%s;padding-left:12px'>%s</span></div>",
    edge, label, col, value
  )
}

fpa_var_tip_sub <- function(text) {
  sprintf("<div style='text-align:right;font-size:11px;color:#b9cbd1;font-variant-numeric:tabular-nums;margin:-1px 0 3px'>%s</div>", text)
}

fpa_var_tip_html <- function(title, rows) {
  paste0("<div style='font-weight:650;margin:0 0 6px'>", title, "</div>", paste(rows, collapse = ""))
}

fpa_var_tip_title <- function(lab, forecast = FALSE) {
  if (isTRUE(forecast)) paste(lab, fpa_screen("var_chip_fc"), sep = " \u00b7 ") else lab
}

fpa_var_tip_bind <- function(fig, rows, tip_id = "fpa-var-tip", pick = NULL) {
  payload <- list(rows = I(as.character(rows)), id = tip_id)
  if (!is.null(pick)) payload$pick <- pick
  htmlwidgets::onRender(fig, "
    function(el, x, data) {
      var id = (data && data.id) ? data.id : 'fpa-var-tip';
      var prev = document.getElementById(id);
      if (prev) prev.remove();
      var tip = document.createElement('div');
      tip.id = id;
      tip.style.cssText = 'position:fixed;z-index:10000;display:none;pointer-events:none;background:#0f2f3a;color:#ffffff;padding:8px 10px;border-radius:8px;font:12px/1.4 Segoe UI,sans-serif;min-width:190px;box-shadow:0 8px 20px rgba(15,47,58,0.18)';
      document.body.appendChild(tip);
      function hide() { tip.style.display = 'none'; }
      function place(ev) {
        if (!ev || !ev.points || !ev.points.length || !data || !data.rows) return;
        var pt = ev.points[0];
        var i = pt.pointNumber;
        if (i == null || i < 0 || i >= data.rows.length) return;
        var html = data.rows[i];
        if (!html) return;
        tip.innerHTML = html;
        tip.style.display = 'block';
        var e = ev.event || {};
        var cx = e.clientX, cy = e.clientY;
        if (cx == null || cy == null) return;
        var isLine = !(pt.data && pt.data.type === 'bar');
        var w = tip.offsetWidth, h = tip.offsetHeight, gap = 16;
        var left = cx - w / 2;
        if (left < 8) left = 8;
        var maxL = window.innerWidth - w - 8;
        if (left > maxL) left = Math.max(8, maxL);
        var top = isLine ? cy - h - gap : cy + gap;
        if (top < 8) top = 8;
        var maxT = window.innerHeight - h - 8;
        if (top > maxT) top = Math.max(8, maxT);
        tip.style.left = left + 'px';
        tip.style.top = top + 'px';
      }
      el.on('plotly_hover', place);
      el.on('plotly_unhover', hide);
      el.addEventListener('mouseleave', hide);
      if (data && data.pick && data.pick.months && window.Shiny) {
        el.on('plotly_click', function(ev) {
          if (!ev || !ev.points || !ev.points.length) return;
          var i = ev.points[0].pointNumber;
          var month = data.pick.months[i];
          if (!month) return;
          Shiny.setInputValue('var_pick', {line: data.pick.line, month: month, n: Date.now()}, {priority: 'event'});
        });
      }
    }
  ", data = payload)
}

fpa_var_main_fig <- function(sl, mode = "gap", sel = "") {
  line <- as.character(sl$line_id[[1]])
  fc <- fpa_var_is_fc(sl)
  per <- as.character(sl$periode)
  xl <- fpa_var_month_abbr(per, with_year = length(unique(substr(per, 1, 4))) > 1L)
  n <- length(per)
  hov <- vapply(per, fpa_shiny_scn_month_lab, character(1), USE.NAMES = FALSE)
  shapes <- list()
  annos <- list()
  if (nzchar(sel) && sel %in% per) {
    j <- match(sel, per) - 1L
    shapes[[length(shapes) + 1L]] <- list(
      type = "rect", xref = "x", yref = "paper", x0 = j - 0.5, x1 = j + 0.5, y0 = 0, y1 = 1,
      fillcolor = "rgba(196,123,43,0.14)", line = list(width = 0), layer = "below"
    )
  }
  if (any(fc) && any(!fc)) {
    k <- min(which(fc)) - 1L
    shapes[[length(shapes) + 1L]] <- list(
      type = "line", xref = "x", yref = "paper", x0 = k - 0.5, x1 = k - 0.5, y0 = 0, y1 = 1,
      line = list(color = "#5c6b73", width = 1, dash = "dot")
    )
    annos[[length(annos) + 1L]] <- list(
      x = k - 0.5, y = 1, xref = "x", yref = "paper", xanchor = "left", yanchor = "bottom",
      text = paste0("\u00a0", fpa_screen("var_plot_fc"), " \u2192"), showarrow = FALSE,
      font = list(size = 11, color = "#5c6b73")
    )
  }
  op <- ifelse(fc, 0.45, 1)
  tip <- rep("", n)
  if (identical(mode, "level")) {
    act <- fpa_var_num(sl$actual)
    bud <- fpa_var_num(sl$budget)
    has_split <- fpa_var_has_split(sl)
    qp <- if (has_split) bud + fpa_var_num(sl$phase) else NULL
    p <- plotly::plot_ly()
    p <- plotly::add_trace(
      p, x = xl, y = act, type = "bar", name = fpa_screen("var_plot_actual"),
      marker = list(color = ifelse(fc, "#9fb9c2", "#1f4e5f")),
      hoverinfo = "none"
    )
    p <- plotly::add_trace(
      p, x = xl, y = bud, type = "scatter", mode = "lines+markers", name = fpa_screen("var_plot_budget"),
      line = list(color = "#c47b2b", width = 2.5), marker = list(color = "#c47b2b", size = 6, symbol = "diamond"),
      hoverinfo = "none"
    )
    if (has_split) {
      p <- plotly::add_trace(
        p, x = xl, y = qp, type = "scatter", mode = "lines+markers", name = fpa_screen("var_plot_vol_budget"),
        line = list(color = "#0f2f3a", width = 1.5, dash = "dash"), marker = list(color = "#0f2f3a", size = 5, symbol = "circle-open"),
        hoverinfo = "none"
      )
    }
    tip <- vapply(seq_len(n), function(i) {
      rows <- c(
        fpa_var_tip_row(fpa_screen("var_plot_actual"), paste(fpa_var_eur(act[[i]]), "EUR")),
        fpa_var_tip_row(fpa_screen("var_plot_budget"), paste(fpa_var_eur(bud[[i]]), "EUR"), rule = TRUE)
      )
      if (has_split) rows <- c(rows, fpa_var_tip_row(fpa_screen("var_plot_vol_budget"), paste(fpa_var_eur(qp[[i]]), "EUR")))
      fpa_var_tip_html(fpa_var_tip_title(hov[[i]], fc[[i]]), rows)
    }, character(1))
    ytitle <- "EUR"
  } else {
    parts <- fpa_var_parts(sl)
    named <- any(vapply(parts, function(x) isTRUE(x$named) || x$id %in% c("phase", "unlinked"), logical(1)))
    p <- plotly::plot_ly()
    tot <- fpa_var_sg(line, sl$variance)
    tot[!is.finite(tot)] <- 0
    if (!named) {
      p <- plotly::add_trace(
        p, x = xl, y = tot, type = "bar", name = fpa_screen("var_col_variance"),
        marker = list(color = ifelse(tot >= 0, "#1f4e5f", "#8c3a3a"), opacity = op),
        hoverinfo = "none"
      )
    } else {
      for (pt in parts) {
        y <- fpa_var_sg(line, sl[[pt$col]])
        y[!is.finite(y)] <- 0
        col <- if (pt$id %in% names(fpa_var_part_colour)) fpa_var_part_colour[[pt$id]] else "#9fb3ba"
        p <- plotly::add_trace(
          p, x = xl, y = y, type = "bar", name = fpa_screen(pt$lab),
          marker = list(color = col, opacity = op, line = list(color = "#ffffff", width = 0.6)),
          hoverinfo = "none"
        )
      }
    }
    if (n <= 18L) {
      pos <- vapply(seq_len(n), function(i) {
        ys <- vapply(if (named) parts else list(list(col = "variance")), function(pt) {
          v <- fpa_var_sg(line, sl[[pt$col]][[i]])
          if (is.finite(v)) v else 0
        }, numeric(1))
        if (tot[[i]] >= 0) sum(ys[ys > 0]) else sum(ys[ys < 0])
      }, numeric(1))
      p <- plotly::add_trace(
        p, x = xl, y = pos, type = "scatter", mode = "text", text = fpa_var_k(tot),
        textposition = ifelse(tot >= 0, "top center", "bottom center"),
        textfont = list(size = 11, color = ifelse(tot >= 0, "#0f2f3a", "#8c3a3a")),
        hoverinfo = "skip", showlegend = FALSE
      )
    }
    cum <- cumsum(tot)
    p <- plotly::add_trace(
      p, x = xl, y = cum, type = "scatter", mode = "lines+markers", name = fpa_screen("var_plot_cum"),
      line = list(color = "#0f2f3a", width = 2), marker = list(color = "#0f2f3a", size = 6, symbol = "circle"),
      hoverinfo = "none"
    )
    tip <- vapply(seq_len(n), function(i) {
      if (named) {
        rows <- c(
          fpa_var_tip_row(fpa_screen("var_col_variance"), paste(fpa_var_eur_s(tot[[i]]), "EUR")),
          vapply(parts, function(pt) {
            y <- fpa_var_sg(line, sl[[pt$col]][[i]])
            row <- fpa_var_tip_row(fpa_screen(pt$lab), paste(fpa_var_eur_s(y), "EUR"))
            if (pt$id %in% c("price", "volume", "mix") && all(c("q0", "p0", "q1", "p1") %in% names(sl)) && is.finite(y) && abs(y) >= 0.5) {
              qp <- fpa_var_num(c(sl$q0[[i]], sl$p0[[i]], sl$q1[[i]], sl$p1[[i]]))
              if (all(is.finite(qp))) row <- paste0(row, fpa_var_tip_sub(fpa_var_pv_formula(pt$id, qp[[1]], qp[[2]], qp[[3]], qp[[4]])))
            }
            row
          }, character(1))
        )
      } else {
        rows <- fpa_var_tip_row(fpa_screen("var_col_variance"), paste(fpa_var_eur_s(tot[[i]]), "EUR"))
      }
      rows <- c(rows, fpa_var_tip_row(fpa_screen("var_plot_cum"), paste(fpa_var_eur_s(cum[[i]]), "EUR"), rule = TRUE))
      fpa_var_tip_html(fpa_var_tip_title(hov[[i]], fc[[i]]), rows)
    }, character(1))
    ytitle <- "EUR"
  }
  fig <- plotly::layout(
    p,
    barmode = if (identical(mode, "level")) "group" else "relative",
    bargap = if (n > 24L) 0.08 else 0.28,
    margin = list(l = 64, r = 16, t = 28, b = 46),
    xaxis = list(
      title = "", type = "category", categoryorder = "array", categoryarray = xl,
      tickfont = fpa_var_axis_font, tickangle = if (n > 18L) -45 else 0, fixedrange = FALSE,
      dtick = if (n > 24L) ceiling(n / 18) else 1,
      showspikes = TRUE, spikemode = "across", spikesnap = "data",
      spikecolor = "#5c6b73", spikethickness = 1, spikedash = "dot"
    ),
    yaxis = list(title = ytitle, tickfont = fpa_var_axis_font, gridcolor = "#e6edef", zerolinecolor = "#5c6b73", separatethousands = TRUE, tickformat = ",.0f"),
    separators = ", ",
    legend = list(orientation = "h", x = 0, y = -0.16, font = list(size = 11)),
    shapes = shapes, annotations = annos,
    hovermode = "closest", hoverdistance = 36,
    plot_bgcolor = "#ffffff", paper_bgcolor = "#ffffff"
  )
  fpa_var_tip_bind(fig, tip)
}

fpa_var_bridge_fig <- function(bf) {
  if (is.null(bf) || !nrow(bf)) return(plotly::plotly_empty())
  n <- nrow(bf)
  base <- pmin(bf$start, bf$end)
  h <- abs(bf$end - bf$start)
  col <- ifelse(bf$kind == "total", "#0f2f3a", ifelse(bf$signed >= 0, "#1f4e5f", "#8c3a3a"))
  txt <- ifelse(bf$kind == "total", fpa_var_eur(bf$raw), fpa_var_eur_s(bf$signed))
  hover <- paste0(bf$label, " : ", txt, " EUR", ifelse(nzchar(bf$tip), paste0("<br>", bf$tip), ""))
  shapes <- lapply(seq_len(n - 1L), function(i) list(
    type = "line", xref = "x", yref = "y",
    x0 = i - 1 + 0.36, x1 = i - 0.36, y0 = bf$end[[i]], y1 = bf$end[[i]],
    line = list(color = "#5c6b73", width = 1)
  ))
  p <- plotly::plot_ly(
    x = bf$label, y = h, base = base, type = "bar",
    marker = list(color = col), text = txt, textposition = "outside", cliponaxis = FALSE,
    textfont = list(size = 11, color = ifelse(bf$kind == "step" & bf$signed < 0, "#8c3a3a", "#0f2f3a")),
    hovertext = hover, hoverinfo = "text", showlegend = FALSE
  )
  rng <- range(c(0, bf$start, bf$end), na.rm = TRUE)
  pad <- 0.12 * max(diff(rng), 1)
  yr <- c(if (rng[[1]] < 0) rng[[1]] - pad else 0, if (rng[[2]] > 0) rng[[2]] + pad else 0)
  plotly::layout(
    p,
    bargap = 0.28,
    margin = list(l = 64, r = 16, t = 20, b = 70),
    xaxis = list(title = "", type = "category", categoryorder = "array", categoryarray = bf$label, tickfont = fpa_var_axis_font, tickangle = if (n > 5L) -25 else 0),
    yaxis = list(title = "EUR", tickfont = fpa_var_axis_font, gridcolor = "#e6edef", zerolinecolor = "#5c6b73", tickformat = ",.0f", range = yr),
    separators = ", ",
    shapes = shapes,
    hoverlabel = list(bgcolor = "#0f2f3a", font = list(color = "#ffffff")),
    plot_bgcolor = "#ffffff", paper_bgcolor = "#ffffff"
  )
}

#' Monthly operating-income band. The chart axis is EUR per month, so the band is not a running total.
fpa_shiny_oi_ribbon <- function(low, high, monthly) {
  if (is.null(low) || is.null(high) || is.null(monthly) || !nrow(monthly) || !"etat" %in% names(monthly)) return(NULL)
  pers <- as.character(monthly$periode)
  act <- monthly$etat != "prévision"
  base <- suppressWarnings(as.numeric(monthly$OI))
  pull <- function(df) {
    v <- suppressWarnings(as.numeric(df$OI[match(pers, as.character(df$periode))]))
    v[!is.finite(v)] <- 0
    v[act] <- base[act]
    v
  }
  lo <- pull(low)
  hi <- pull(high)
  fc <- !act
  if (!any(fc)) return(NULL)
  idx <- which(fc)
  if (idx[[1]] > 1L) idx <- c(idx[[1]] - 1L, idx)
  data.frame(
    periode = pers[idx],
    ymin = pmin(lo[idx], hi[idx], na.rm = TRUE),
    ymax = pmax(lo[idx], hi[idx], na.rm = TRUE),
    stringsAsFactors = FALSE
  )
}

#' Empty when prudent and ambitieux both move revenue and operating income.
fpa_shiny_flat_note <- function(v) {
  if (is.null(v) || !length(v$open) || is.null(v$low) || is.null(v$high)) return("")
  if (!nrow(v$low) || !nrow(v$high)) return("")
  if (!all(c("REV", "OI") %in% names(v$low)) || !all(c("REV", "OI") %in% names(v$high))) return("")
  grab <- function(df, line) {
    sum(suppressWarnings(as.numeric(df[[line]][as.character(df$periode) %in% v$open])), na.rm = TRUE)
  }
  same <- function(a, b) is.finite(a) && is.finite(b) && abs(round(a) - round(b)) < 0.5
  lo_oi <- grab(v$low, "OI")
  hi_oi <- grab(v$high, "OI")
  lo_rev <- grab(v$low, "REV")
  hi_rev <- grab(v$high, "REV")
  oi_flat <- same(lo_oi, hi_oi)
  rev_flat <- same(lo_rev, hi_rev)
  eur <- function(x) format(round(x), big.mark = " ", scientific = FALSE, trim = TRUE)
  if (oi_flat && rev_flat) return(fpa_screen("scn_flat_both"))
  if (oi_flat) return(fpa_screen("scn_flat_result"))
  if (rev_flat) return(fpa_screen("scn_flat_revenue", eur(lo_oi), eur(hi_oi)))
  ""
}

fpa_shiny_setup_href <- function(config) {
  site <- ""
  id <- ""
  if (!is.null(config) && !is.null(config$project)) {
    site <- as.character(config$project$site %||% "")
    id <- as.character(config$project$id %||% "")
  }
  site <- sub("/+$", "", site)
  if (!nzchar(site) || !grepl("^https?://", site)) return("")
  q <- "step=1&file=1&anchor=chain-extra-export"
  if (grepl("^[0-9a-fA-F-]{16,}$", id)) q <- paste0("project=", id, "&", q)
  paste0(site, "/setup?", q)
}

fpa_shiny_flat_ui <- function(v, config = NULL, place = "scn") {
  note <- fpa_shiny_flat_note(v)
  if (!nzchar(note)) return(NULL)
  href <- fpa_shiny_setup_href(config)
  on_map <- identical(place, "map")
  shiny::tags$div(
    class = "fpa-scn-flat",
    shiny::tags$p(note),
    shiny::tags$p(style = "font-weight:500;", fpa_screen("scn_flat_invite")),
    shiny::tags$div(
      class = "fpa-scn-flat-actions",
      if (!on_map) shiny::tags$button(
        type = "button",
        class = "fpa-scn-flat-go",
        onclick = "if (window.Shiny) Shiny.setInputValue('scn_flat_map', Date.now(), {priority:'event'});",
        fpa_screen("scn_flat_map")
      ),
      if (nzchar(href)) shiny::tags$a(
        class = if (on_map) "fpa-scn-flat-go" else "fpa-scn-flat-go is-quiet",
        href = href,
        target = "_blank",
        rel = "noopener",
        fpa_screen("scn_flat_setup")
      )
    )
  )
}

#' Floor and ceiling on 100, 1 000, 10 000, and so on.
#' The floor is 0, or the highest round step at or under the series. Never one step below that.
fpa_shiny_round_axis <- function(vals, mode = c("fit", "zero")) {
  mode <- match.arg(mode)
  vals <- suppressWarnings(as.numeric(vals))
  vals <- vals[is.finite(vals)]
  if (!length(vals)) return(c(0, 1))
  lo <- min(vals)
  hi <- max(vals)
  if (identical(mode, "zero")) {
    lo <- min(0, lo)
    hi <- max(0, hi)
  }
  scale <- max(abs(lo), abs(hi), 1)
  step <- 10^floor(log10(scale))
  if (!is.finite(step) || step <= 0) step <- 1
  ymin <- floor(lo / step) * step
  ymax <- ceiling(hi / step) * step
  if (identical(mode, "zero") && lo >= 0 && ymin < 0) ymin <- 0
  if (identical(mode, "zero") && ymin > 0) ymin <- 0
  if (identical(mode, "zero") && ymax < 0) ymax <- 0
  if (abs(ymax - hi) < 1e-6) ymax <- ymax + step
  if (ymax <= ymin) ymax <- ymin + step
  c(ymin, ymax)
}

fpa_shiny_path_sentence <- function(v) {
  if (is.null(v) || !isTRUE(v$ready) || !length(v$open)) return("")
  eur <- function(x) format(round(x), big.mark = " ", scientific = FALSE, trim = TRUE)
  open <- as.character(v$open)
  oi <- sum(suppressWarnings(as.numeric(v$pnl$OI[v$pnl$periode %in% open])), na.rm = TRUE)
  bud <- fpa_scenario_budget_oi(v$budget)
  bud_vals <- if (!is.null(bud)) {
    suppressWarnings(as.numeric(bud$OI[match(open, as.character(bud$periode))]))
  } else {
    rep(NA_real_, length(open))
  }
  n_missing <- sum(!is.finite(bud_vals))
  bud_oi <- if (!n_missing && length(bud_vals)) sum(bud_vals) else NA_real_
  gap <- if (is.finite(bud_oi)) oi - bud_oi else NA_real_
  year <- substr(open[[1]], 1, 4)
  dec_cash <- NA_real_
  if (!is.null(v$cash) && nrow(v$cash)) {
    hit <- match(paste0(year, "-12"), as.character(v$cash$periode))
    if (!is.na(hit)) dec_cash <- suppressWarnings(as.numeric(v$cash$cash_close[[hit]]))
  }
  if (!is.finite(oi)) return("")
  phrase <- fpa_shiny_case_phrase(open, v$cases)
  cash_txt <- if (is.finite(dec_cash)) eur(dec_cash) else "–"
  if (is.finite(gap)) {
    return(fpa_screen("pnl_partner_path", phrase, eur(oi), cash_txt, eur(gap)))
  }
  if (n_missing > 0L) {
    return(fpa_screen(
      "pnl_partner_path_partial", phrase, eur(oi), cash_txt,
      n_missing, length(open)
    ))
  }
  fpa_screen("pnl_partner_path_nobudget", phrase, eur(oi), cash_txt)
}

fpa_shiny_apply_pnl_case <- function(pnl, scenarios, case_id, status) {
  if (is.null(pnl) || !nrow(pnl)) return(pnl)
  if (is.null(scenarios) || !nrow(scenarios) || !("case" %in% names(scenarios))) return(pnl)
  case_id <- as.character(case_id %||% "base")
  if (!case_id %in% c("low", "high")) return(pnl)
  sl <- scenarios[as.character(scenarios$case) == case_id, , drop = FALSE]
  if (!nrow(sl)) return(pnl)
  open <- fpa_shiny_forecast_periods(status)
  if (!length(open)) return(pnl)
  out <- pnl
  cols <- intersect(c("REV", "COGS", "PAYROLL", "OPEX_OTHER"), names(out))
  cols <- cols[cols %in% names(sl)]
  for (i in which(as.character(out$periode) %in% open)) {
    hit <- match(as.character(out$periode[[i]]), as.character(sl$periode))
    if (is.na(hit)) next
    for (col in cols) out[[col]][[i]] <- suppressWarnings(as.numeric(sl[[col]][[hit]]))
  }
  if (all(c("REV", "OTHER_OP_INC", "COGS", "PAYROLL", "OPEX_OTHER", "D_A", "FIN", "EXCEP", "TAX") %in% names(out))) {
    out <- fpa_pnl_derive(out)
  }
  out
}

fpa_shiny_apply_cash_case <- function(cash, scenarios, case_id, status) {
  if (is.null(cash) || !nrow(cash) || !("cash_close" %in% names(cash))) return(cash)
  if (is.null(scenarios) || !nrow(scenarios) || !("cash_close" %in% names(scenarios))) return(cash)
  case_id <- as.character(case_id %||% "base")
  if (!case_id %in% c("low", "high")) return(cash)
  sl <- scenarios[as.character(scenarios$case) == case_id, , drop = FALSE]
  open <- fpa_shiny_forecast_periods(status)
  if (!nrow(sl) || !length(open)) return(cash)
  out <- cash
  for (i in which(as.character(out$periode) %in% open)) {
    hit <- match(as.character(out$periode[[i]]), as.character(sl$periode))
    if (is.na(hit)) next
    out$cash_close[[i]] <- suppressWarnings(as.numeric(sl$cash_close[[hit]]))
  }
  out
}

#' Band from the last closed month through the open months. Ends meet on the closed month.
fpa_shiny_cum_year <- function(periode, value) {
  value <- suppressWarnings(as.numeric(value))
  value[!is.finite(value)] <- 0
  year <- substr(as.character(periode), 1, 4)
  as.numeric(ave(value, year, FUN = cumsum))
}

fpa_shiny_cum_ribbon <- function(scenarios, frame, value_col) {
  if (is.null(scenarios) || !nrow(scenarios) || !value_col %in% names(scenarios)) return(NULL)
  if (is.null(frame) || !nrow(frame) || !value_col %in% names(frame)) return(NULL)
  pers <- as.character(frame$periode)
  act <- frame$etat != "prévision"
  base <- suppressWarnings(as.numeric(frame[[value_col]]))
  pull <- function(case_id) {
    sl <- scenarios[as.character(scenarios$case) == case_id, , drop = FALSE]
    v <- suppressWarnings(as.numeric(sl[[value_col]][match(pers, as.character(sl$periode))]))
    v[act] <- base[act]
    fpa_shiny_cum_year(pers, v)
  }
  lo <- pull("low")
  hi <- pull("high")
  fc <- !act
  if (!any(fc)) return(NULL)
  idx <- which(fc)
  if (idx[[1]] > 1L) idx <- c(idx[[1]] - 1L, idx)
  data.frame(
    periode = pers[idx],
    ymin = pmin(lo[idx], hi[idx]),
    ymax = pmax(lo[idx], hi[idx]),
    stringsAsFactors = FALSE
  )
}

fpa_shiny_case_ribbon <- function(scenarios, status, value_col) {
  if (is.null(scenarios) || !nrow(scenarios) || !value_col %in% names(scenarios)) return(NULL)
  low <- scenarios[as.character(scenarios$case) == "low", , drop = FALSE]
  high <- scenarios[as.character(scenarios$case) == "high", , drop = FALSE]
  if (!nrow(low) || !nrow(high)) return(NULL)
  open <- fpa_shiny_forecast_periods(status)
  allp <- as.character(low$periode)
  pers <- if (length(open)) allp[allp %in% open] else allp
  if (!length(pers)) return(NULL)
  first <- match(pers[[1]], allp)
  if (!is.na(first) && first > 1L) pers <- c(allp[[first - 1L]], pers)
  ymin <- suppressWarnings(as.numeric(low[[value_col]][match(pers, allp)]))
  ymax <- suppressWarnings(as.numeric(high[[value_col]][match(pers, as.character(high$periode))]))
  data.frame(
    periode = pers,
    ymin = pmin(ymin, ymax),
    ymax = pmax(ymin, ymax),
    stringsAsFactors = FALSE
  )
}

fpa_shiny_rank_table <- function(ranks) {
  if (is.null(ranks) || !nrow(ranks)) return(NULL)
  head_style <- paste0(
    "position:sticky;top:0;background:#1f4e5f;color:#fff;font-weight:600;",
    "font-size:12.5px;padding:8px 12px;text-align:right;white-space:nowrap;"
  )
  cell <- function(x, strong = FALSE) {
    v <- suppressWarnings(as.numeric(x))
    col <- if (is.finite(v) && v < 0) "#8c3a3a" else "#1a2b32"
    shiny::tags$td(
      style = paste0(
        "padding:6px 12px;text-align:right;font-variant-numeric:tabular-nums;color:", col, ";",
        if (strong) "font-weight:700;" else ""
      ),
      if (is.finite(v)) fpa_shiny_eur(v) else ""
    )
  }
  shiny::tags$div(
    style = "margin:0.4rem 0 0.8rem;",
    shiny::tags$p(
      style = "margin:0 0 0.35rem;font-weight:600;color:#1f4e5f;",
      fpa_screen("scen_rank_title")
    ),
    shiny::tags$p(style = "margin:0 0 0.45rem;line-height:1.4;color:#3d4c54;", fpa_screen("scen_rank_lead")),
    shiny::tags$div(
      style = "border:1px solid #d6e1e5;border-radius:8px;overflow:auto;background:#fff;",
      shiny::tags$table(
        style = "width:100%;border-collapse:collapse;font-size:13px;",
        shiny::tags$thead(
          shiny::tags$tr(
            shiny::tags$th(style = paste0(head_style, "text-align:left;"), fpa_screen("scen_rank_input")),
            shiny::tags$th(style = head_style, fpa_screen("scen_bas")),
            shiny::tags$th(style = head_style, fpa_screen("scen_central")),
            shiny::tags$th(style = head_style, fpa_screen("scen_haut")),
            shiny::tags$th(style = head_style, fpa_screen("scen_rank_span"))
          )
        ),
        shiny::tags$tbody(lapply(seq_len(nrow(ranks)), function(i) {
          lab <- as.character(ranks$label[[i]])
          if (!nzchar(lab)) lab <- as.character(ranks$id[[i]])
          shiny::tags$tr(
            style = if (i %% 2 == 0) "background:#f6f9fa;" else "",
            shiny::tags$td(style = "padding:6px 12px;text-align:left;white-space:nowrap;", lab),
            cell(ranks$oi_low[[i]]),
            cell(ranks$oi_base[[i]]),
            cell(ranks$oi_high[[i]]),
            cell(ranks$oi_span[[i]], strong = TRUE)
          )
        }))
      )
    )
  )
}

fpa_shiny_factors <- function(parts) {
  if (!length(parts)) return(NULL)
  kids <- list()
  for (p in parts) {
    op <- as.character(p$op %||% "")
    if (nzchar(op)) kids[[length(kids) + 1L]] <- shiny::tags$span(class = "fpa-op", op)
    kids[[length(kids) + 1L]] <- shiny::tags$span(
      class = "fpa-fac",
      shiny::tags$span(class = "fpa-fac-num", p$value),
      shiny::tags$span(class = "fpa-fac-lab", p$label)
    )
  }
  shiny::tagList(kids)
}

fpa_shiny_linkify <- function(text, periode, files, kind = "pnl", line = "") {
  text <- as.character(text %||% "")
  files <- unique(as.character(files))
  files <- files[nzchar(files)]
  kind <- if (as.character(kind %||% "") %in% c("pnl", "cash", "bs")) as.character(kind) else "pnl"
  line <- gsub("[^A-Za-z0-9_]", "", as.character(line %||% ""))
  if (!nzchar(text) || !length(files)) return(text)
  files <- files[order(nchar(files), decreasing = TRUE)]
  pos <- nchar(text) + 1L
  hit <- ""
  for (f in files) {
    i <- regexpr(f, text, fixed = TRUE)[[1]]
    if (i > 0L && i < pos) {
      pos <- i
      hit <- f
    }
  }
  if (!nzchar(hit)) return(text)
  before <- substr(text, 1L, pos - 1L)
  after <- substr(text, pos + nchar(hit), nchar(text))
  safe <- gsub("[^A-Za-z0-9._-]", "", hit)
  per <- ifelse(grepl("^[0-9]{4}-[0-9]{2}$", periode), periode, "")
  shiny::tagList(
    before,
    shiny::tags$button(
      type = "button",
      class = "fpa-file-link",
      onclick = sprintf(
        "Shiny.setInputValue('oi_file',{periode:'%s',file:'%s',kind:'%s',line:'%s'},{priority:'event'})",
        per, safe, kind, line
      ),
      hit
    ),
    fpa_shiny_linkify(after, periode, files, kind, line)
  )
}

fpa_shiny_oi_row <- function(label, equation, amount, role = "term", id = "", focus = "") {
  neg <- is.finite(amount) && amount < -0.005
  cls <- paste0("is-", role)
  if (nzchar(id) && identical(id, as.character(focus %||% ""))) cls <- paste(cls, "is-focus")
  shiny::tags$tr(
    class = cls,
    shiny::tags$td(class = "lab", label),
    shiny::tags$td(class = "eq", equation %||% ""),
    shiny::tags$td(class = paste("amt", if (neg) "is-neg" else ""), fpa_cell_amt(amount))
  )
}

fpa_shiny_oi_note <- function(text, periode = "", files = character(), kind = "pnl", line = "") {
  if (!nzchar(text %||% "")) return(NULL)
  shiny::tags$tr(
    class = "is-note",
    shiny::tags$td(""),
    shiny::tags$td(class = "eq", colspan = "2", fpa_shiny_linkify(text, periode, files, kind, line))
  )
}

fpa_shiny_pnl_focus_amt <- function(read, focus) {
  switch(as.character(focus %||% ""),
    REV = read$rev, OTHER_OP_INC = read$other, COGS = read$cogs, GP = read$gp,
    PAYROLL = read$pay, OPEX_OTHER = read$opex, EBITDA = read$ebitda, D_A = read$da,
    OI = read$oi, FIN = read$fin, EXCEP = read$excep, TAX = read$tax, NI = read$ni,
    read$oi
  )
}

fpa_shiny_pnl_frame_lines <- function() {
  c("REV", "OTHER_OP_INC", "COGS", "GP", "PAYROLL", "OPEX_OTHER", "EBITDA", "D_A", "OI", "FIN", "EXCEP", "TAX", "NI")
}

fpa_shiny_cell_button <- function(chip, stmt, periode, line) {
  stmt <- if (as.character(stmt %||% "") %in% c("pnl", "cash", "bs")) as.character(stmt) else "pnl"
  line <- gsub("[^A-Za-z0-9_]", "", as.character(line %||% ""))
  periode <- as.character(periode %||% "")
  shiny::tags$button(
    type = "button",
    class = "fpa-oi-hit",
    `aria-label` = paste(fpa_screen("oi_read_open"), periode),
    onclick = sprintf(
      "Shiny.setInputValue('stmt_read',{stmt:'%s',periode:'%s',line:'%s'},{priority:'event'})",
      stmt, periode, line
    ),
    chip
  )
}

fpa_shiny_oi_modal <- function(read, focus = "OI") {
  files <- c(read$vol_file %||% "", read$hist_file %||% "")
  focus <- as.character(focus %||% "OI")
  if (!focus %in% fpa_shiny_pnl_frame_lines()) focus <- "OI"
  amt <- suppressWarnings(as.numeric(fpa_shiny_pnl_focus_amt(read, focus)))
  if (!is.finite(amt)) {
    focus <- "OI"
    amt <- read$oi
  }
  if (identical(focus, "OI")) {
    title <- fpa_screen("oi_read_title", read$periode)
    lead <- fpa_screen("oi_read_lead", read$periode, read$screen, read$precise)
  } else {
    title <- fpa_screen("cell_read_title", fpa_shiny_line_name(focus), read$periode)
    lead <- fpa_screen(
      "cell_read_lead", fpa_shiny_line_name(focus), read$periode,
      fpa_cell_screen(amt), fpa_cell_amt(amt, digits = 2)
    )
  }
  note <- function(text) fpa_shiny_oi_note(text, read$periode, files, "pnl", focus)
  line_row <- function(label, equation, amount, role = "term", id = "") {
    fpa_shiny_oi_row(label, equation, amount, role, id, focus)
  }
  eq_of <- function(parts, fallback = "") {
    if (length(parts)) shiny::tags$span(class = "fpa-facs", fpa_shiny_factors(parts)) else fallback
  }
  opex_rows <- list()
  if (!is.null(read$opex_driven)) {
    d <- read$opex_driven
    opex_rows <- list(
      line_row(d$label, eq_of(d$factors, d$equation), d$amount, id = "OPEX_OTHER"),
      note(d$note)
    )
    if (is.finite(read$opex_rest) && abs(read$opex_rest) >= 0.5) {
      opex_rows <- c(opex_rows, list(
        line_row(fpa_screen("loc_other_charges_rest"), "", read$opex_rest, id = "OPEX_REST"),
        note(read$opex_rest_note)
      ))
    }
  } else {
    opex_rows <- list(line_row("Autres charges", "", read$opex, id = "OPEX_OTHER"))
  }
  below <- list(
    shiny::tags$p(class = "fpa-read-below", fpa_screen("oi_read_below")),
    shiny::tags$table(
      class = "fpa-read",
      line_row(fpa_screen("loc_fin_result"), fpa_screen("oi_read_seasonal"), read$fin, id = "FIN"),
      if (is.finite(read$excep) && abs(read$excep) >= 0.5) {
        line_row("Exceptionnel", "", read$excep, id = "EXCEP")
      },
      line_row(fpa_screen("loc_tax"), "", read$tax, id = "TAX"),
      note(read$tax_note),
      line_row(
        "Résultat net",
        fpa_screen("oi_read_ni"),
        read$ni,
        role = "sum",
        id = "NI"
      )
    )
  )
  shiny::modalDialog(
    title = title,
    easyClose = TRUE,
    size = "l",
    footer = shiny::tags$button(
      type = "button",
      style = "background:#1f4e5f;color:#fff;border:1px solid #1f4e5f;border-radius:8px;font-weight:600;padding:6px 14px;",
      `data-dismiss` = "modal",
      `data-bs-dismiss` = "modal",
      fpa_screen("kpi_close")
    ),
    shiny::tags$p(
      class = "fpa-read-lead",
      lead
    ),
    local({
      rows <- list()
      push <- function(item) {
        if (is.null(item)) return()
        rows[[length(rows) + 1L]] <<- item
      }
      push(line_row("Chiffre d'affaires", eq_of(read$rev_factors, read$rev_eq), read$rev, id = "REV"))
      push(note(read$rev_note))
      push(line_row("Autres produits", "", read$other, id = "OTHER_OP_INC"))
      push(note(read$other_note))
      push(line_row("Achats", eq_of(read$cogs_factors, read$cogs_eq), read$cogs, id = "COGS"))
      push(note(read$cogs_note))
      push(line_row(
        "Marge brute",
        eq_of(list(
          list(op = "", label = "Chiffre d'affaires", value = fpa_cell_amt(read$rev)),
          list(op = "+", label = "Autres produits", value = fpa_cell_amt(read$other)),
          list(op = "\u2212", label = "Achats", value = fpa_cell_amt(read$cogs))
        )),
        read$gp,
        role = "sum",
        id = "GP"
      ))
      push(line_row("Masse salariale", eq_of(read$pay_factors, read$pay_eq), read$pay, id = "PAYROLL"))
      push(note(read$pay_note))
      for (item in opex_rows) push(item)
      push(line_row(
        "EBE",
        eq_of(list(
          list(op = "", label = "Marge brute", value = fpa_cell_amt(read$gp)),
          list(op = "\u2212", label = "Masse salariale", value = fpa_cell_amt(read$pay)),
          list(op = "\u2212", label = "Autres charges", value = fpa_cell_amt(read$opex))
        )),
        read$ebitda,
        role = "sum",
        id = "EBITDA"
      ))
      push(line_row("Dotations", "", read$da, id = "D_A"))
      push(note(read$da_note))
      push(line_row(
        "Résultat d'exploitation",
        eq_of(list(
          list(op = "", label = "EBE", value = fpa_cell_amt(read$ebitda)),
          list(op = "\u2212", label = "Dotations", value = fpa_cell_amt(read$da))
        )),
        read$oi,
        role = "oi",
        id = "OI"
      ))
      tbl <- shiny::tags$table(class = "fpa-read")
      for (row in rows) tbl <- htmltools::tagAppendChild(tbl, row)
      tbl
    }),
    below[[1]],
    below[[2]]
  )
}

fpa_shiny_health_modal <- function(id, row, periode, bs_file, pnl_file, result_text, fy_month = fpa_screen("month_1")) {
  spec <- fpa_health_explain(id)
  keys <- fpa_health_copy_keys(id)
  if (is.null(spec) || length(keys) < 2L) return(NULL)
  days <- fpa_health_days(periode)
  val_of <- function(field) {
    if (identical(field, "days")) return(days)
    if (identical(field, "a")) return(row$a)
    if (identical(field, "b")) return(row$b)
    if (identical(field, "c")) return(row$c)
    NA_real_
  }
  parts <- lapply(spec$parts, function(p) {
    x <- val_of(p$field)
    shown <- if (identical(p$field, "days")) {
      if (!is.finite(x)) "\u2013" else paste0(as.integer(round(x)), " j")
    } else {
      fpa_cell_amt(x)
    }
    lab <- fpa_screen(p$key)
    if (grepl("%s", lab, fixed = TRUE)) lab <- fpa_screen(p$key, fy_month)
    list(op = p$op, label = lab, value = shown)
  })
  files <- if (identical(spec$files, "pnl")) {
    list(pnl_file)
  } else if (identical(spec$files, "both")) {
    list(bs_file, pnl_file)
  } else {
    list(bs_file)
  }
  files <- Filter(function(f) nzchar(f$name %||% "") && nzchar(f$id %||% ""), files)
  file_btn <- function(f) {
    safe <- gsub("[^A-Za-z0-9_-]", "", f$id)
    shiny::tags$button(
      type = "button",
      class = "fpa-file-link",
      onclick = sprintf("Shiny.setInputValue('raw_file','src:%s',{priority:'event'})", safe),
      f$name
    )
  }
  shiny::modalDialog(
    title = fpa_screen(switch(
      id,
      current_ratio = "health_current", quick_ratio = "health_quick", cash_ratio = "health_cash",
      debt_to_equity = "health_de", debt_to_assets = "health_da", interest_coverage = "health_cover",
      dso_days = "health_dso", dio_days = "health_dio", asset_turnover = "health_turn",
      gross_margin = "health_gm", ebitda_margin = "health_ebitda", oi_margin = "health_om",
      roa = "health_roa", book_ev = "health_ev", roce = "health_roce", "health_na"
    )),
    easyClose = TRUE,
    size = "l",
    footer = shiny::tags$button(
      type = "button",
      style = "background:#1f4e5f;color:#fff;border:1px solid #1f4e5f;border-radius:8px;font-weight:600;padding:6px 14px;",
      `data-dismiss` = "modal",
      `data-bs-dismiss` = "modal",
      fpa_screen("kpi_close")
    ),
    shiny::tags$p(class = "fpa-read-lead", {
      lead <- fpa_screen(keys[[1]])
      if (grepl("%s", lead, fixed = TRUE)) fpa_screen(keys[[1]], fy_month) else lead
    }),
    shiny::tags$p(class = "fpa-read-lead", style = "font-weight:600;color:#1f4e5f;", {
      why <- fpa_screen(keys[[2]])
      if (grepl("%s", why, fixed = TRUE)) fpa_screen(keys[[2]], fy_month) else why
    }),
    shiny::tags$table(
      class = "fpa-read",
      shiny::tags$tr(
        shiny::tags$td(class = "lab", fpa_screen(switch(
          id,
          current_ratio = "health_current", quick_ratio = "health_quick", cash_ratio = "health_cash",
          debt_to_equity = "health_de", debt_to_assets = "health_da", interest_coverage = "health_cover",
          dso_days = "health_dso", dio_days = "health_dio", asset_turnover = "health_turn",
          gross_margin = "health_gm", ebitda_margin = "health_ebitda", oi_margin = "health_om",
          roa = "health_roa", book_ev = "health_ev", roce = "health_roce", "health_na"
        ))),
        shiny::tags$td(class = "eq", shiny::tags$span(class = "fpa-facs", fpa_shiny_factors(parts))),
        shiny::tags$td(class = "amt", result_text)
      )
    ),
    if (length(files)) shiny::tags$p(
      class = "fpa-read-lead",
      fpa_screen(if (identical(spec$files, "pnl")) "health_src_pnl" else if (identical(spec$files, "both")) "health_src_both" else "health_src_bs"),
      " ",
      file_btn(files[[1]]),
      if (length(files) > 1L) shiny::tagList(" · ", file_btn(files[[2]]))
    )
  )
}

fpa_shiny_flow_modal <- function(read) {
  files <- read$files %||% character()
  kind <- if (as.character(read$kind %||% "") %in% c("cash", "bs")) as.character(read$kind) else "cash"
  focus <- as.character(read$focus %||% "")
  title <- if (identical(kind, "bs")) {
    fpa_screen("bs_read_title", read$periode)
  } else {
    fpa_screen("cash_read_title", read$periode)
  }
  lead <- fpa_screen(
    "cell_read_lead", read$focus_label, read$periode, read$screen, read$precise
  )
  shiny::modalDialog(
    title = title,
    easyClose = TRUE,
    size = "l",
    footer = shiny::tags$button(
      type = "button",
      style = "background:#1f4e5f;color:#fff;border:1px solid #1f4e5f;border-radius:8px;font-weight:600;padding:6px 14px;",
      `data-dismiss` = "modal",
      `data-bs-dismiss` = "modal",
      fpa_screen("kpi_close")
    ),
    shiny::tags$p(class = "fpa-read-lead", lead),
    local({
      tbl <- shiny::tags$table(class = "fpa-read")
      for (r in read$rows) {
        if (identical(r$role, "head")) {
          tbl <- htmltools::tagAppendChild(tbl, shiny::tags$tr(
            class = "is-head",
            shiny::tags$td(colspan = "3", r$label)
          ))
          next
        }
        eq <- if (length(r$factors)) {
          shiny::tags$span(class = "fpa-facs", fpa_shiny_factors(r$factors))
        } else {
          r$equation %||% ""
        }
        tbl <- htmltools::tagAppendChild(
          tbl, fpa_shiny_oi_row(r$label, eq, r$amount, r$role %||% "term", r$id, focus)
        )
        note <- fpa_shiny_oi_note(r$note, read$periode, files, kind, focus)
        if (!is.null(note)) tbl <- htmltools::tagAppendChild(tbl, note)
      }
      tbl
    })
  )
}

fpa_shiny_pnl_grid <- function(pnl, long, status = NULL, span = "12", start = NULL, mode = "abs",
                               nature = character(0), show_op_fin = FALSE, scope = "all") {
  if (is.null(pnl) || !nrow(pnl)) return(shiny::tags$p(fpa_screen("loc_no_pnl_engine")))
  lines <- c("REV", "OTHER_OP_INC", "COGS", "GP", "PAYROLL", "OPEX_OTHER", "EBITDA", "D_A", "OI", "FIN", "EXCEP", "TAX", "NI")
  lines <- intersect(lines, names(pnl))
  keep <- vapply(lines, function(line) {
    v <- suppressWarnings(as.numeric(pnl[[line]]))
    any(is.finite(v) & abs(v) >= 0.5)
  }, logical(1))
  hidden <- lines[!keep]
  lines <- lines[keep]
  lines <- lines[vapply(lines, function(line) fpa_nature_keep(line, nature, scope), logical(1))]
  if (!length(lines)) return(shiny::tags$p(fpa_screen("loc_no_opfin_window")))
  months <- fpa_shiny_pnl_window(pnl$periode, span, start)
  forecast <- character()
  if (!is.null(status) && nrow(status) && all(c("periode", "status") %in% names(status))) {
    forecast <- as.character(status$periode)[as.character(status$status) == "forecast"]
  }
  lab_of <- function(line, periode) {
    if (is.null(long) || !nrow(long)) return("")
    hit <- long$evidence_label[long$line_id == line & long$periode == periode]
    if (!length(hit)) return("")
    switch(as.character(hit[[1]]),
      imported_actual = fpa_screen("loc_imported"),
      mechanical_rule = fpa_screen("loc_rule"),
      management_assumption = fpa_screen("loc_hypothesis"),
      as.character(hit[[1]])
    )
  }
  totals <- c("GP", "EBITDA", "OI", "NI")
  mode <- as.character(mode %||% "abs")
  if (!mode %in% c("abs", "pct", "pop")) mode <- "abs"
  rev <- suppressWarnings(as.numeric(pnl$REV[match(months, pnl$periode)]))
  raw <- lapply(lines, function(line) {
    suppressWarnings(as.numeric(pnl[[line]][match(months, pnl$periode)]))
  })
  names(raw) <- lines
  shown <- lapply(lines, function(line) {
    vals <- raw[[line]]
    if (identical(mode, "pct")) return(vapply(seq_along(vals), function(j) fpa_stmt_ratio(vals[[j]], rev[[j]]), numeric(1)))
    if (identical(mode, "pop")) {
      out <- rep(NA_real_, length(vals))
      if (length(vals) > 1L) out[-1L] <- vapply(seq.int(2L, length(vals)), function(j) fpa_stmt_delta(vals[[j]], vals[[j - 1L]]), numeric(1))
      return(out)
    }
    vals
  })
  names(shown) <- lines
  pool <- unlist(shown, use.names = FALSE)
  pool <- pool[is.finite(pool)]
  cap <- if (length(pool)) max(abs(pool)) else 1
  header <- shiny::tags$tr(
    shiny::tags$th("Ligne"),
    lapply(months, function(m) {
      fc <- m %in% forecast
      shiny::tags$th(
        style = paste0("background:", if (fc) "#8a5a00" else "#1f4e5f", ";"),
        m
      )
    })
  )
  body <- lapply(lines, function(line) {
    vals <- raw[[line]]
    disp <- shown[[line]]
    shiny::tags$tr(
      class = if (line %in% totals) "fpa-pnl-total" else NULL,
      fpa_shiny_nature_th(
        shiny::tags$button(
          type = "button",
          class = "fpa-line-go",
          title = fpa_screen("home_test_impact"),
          `aria-label` = paste(fpa_screen("home_test_impact"), fpa_shiny_line_name(line)),
          onclick = sprintf(
            "Shiny.setInputValue('fpa_go',{tab:'Impact',line:'%s'},{priority:'event'})",
            line
          ),
          fpa_shiny_line_name(line)
        ),
        fpa_line_nature_of(nature, line), show_op_fin
      ),
      lapply(seq_along(months), function(j) {
        ev <- lab_of(line, months[[j]])
        label <- if (identical(mode, "pct")) {
          fpa_shiny_pct_label(disp[[j]])
        } else if (identical(mode, "pop")) {
          fpa_shiny_signed_eur(disp[[j]])
        } else {
          if (is.finite(vals[[j]]) && abs(vals[[j]]) >= 0.5) fpa_shiny_eur(vals[[j]]) else "–"
        }
        tip <- paste0(
          fpa_shiny_line_name(line), " · ", months[[j]],
          if (months[[j]] %in% forecast) " · prévision" else " · réalisé",
          " · ", if (is.finite(vals[[j]])) paste0(fpa_shiny_eur(vals[[j]]), " EUR") else "–",
          if (nzchar(ev)) paste0(" · ", ev) else ""
        )
        chip <- fpa_shiny_chip(label, fpa_shiny_chip_score(disp[[j]], cap))
        clickable <- line %in% fpa_shiny_pnl_frame_lines() && months[[j]] %in% forecast
        shiny::tags$td(
          title = if (clickable) paste0(tip, " · ", fpa_screen("oi_read_open")) else tip,
          if (clickable) fpa_shiny_cell_button(chip, "pnl", months[[j]], line) else chip
        )
      })
    )
  })
  note <- if (identical(mode, "pct")) {
    fpa_screen("stmt_pct_pnl")
  } else if (identical(mode, "pop")) {
    fpa_screen("stmt_pop_note")
  } else {
    fpa_screen("stmt_heat_note")
  }
  shiny::tags$div(
    class = "fpa-pnl",
    shiny::tags$table(
      shiny::tags$thead(header),
      shiny::tags$tbody(body)
    ),
    shiny::tags$p(
      note, " ",
      fpa_screen("loc_hover_cell"),
      if (any(lines %in% fpa_shiny_pnl_frame_lines()) && any(months %in% forecast)) shiny::tagList(
        shiny::tags$span(
          class = "fpa-oi-mark",
          shiny::tags$span(class = "fpa-oi-swatch", `aria-hidden` = "true"),
          fpa_screen("oi_read_hint")
        ),
        " "
      ) else NULL,
      if (isTRUE(show_op_fin)) paste0(fpa_screen("stmt_opfin_note"), " ") else "",
      if (length(hidden)) paste0(fpa_screen("loc_row_hidden_zero"), paste(vapply(hidden, fpa_shiny_line_name, character(1)), collapse = ", "), ".") else ""
    )
  )
}

fpa_shiny_bs_name <- function(id) {
  switch(as.character(id),
    CASH = "Trésorerie",
    AR = "Clients",
    INV = "Stocks",
    PPE = "Immobilisations",
    OTHER_CA = "Autres actifs",
    AP = "Fournisseurs",
    ST_DEBT = "Dette court terme",
    LT_DEBT = "Dette long terme",
    OTHER_CL = "Autres dettes",
    EQUITY = "Capitaux propres",
    as.character(id)
  )
}

fpa_shiny_bs_headline <- function(bs) {
  if (is.null(bs) || !nrow(bs)) return("")
  if (nrow(bs) < 2L) return(fpa_screen("bs_headline_one"))
  last <- bs[nrow(bs), , drop = FALSE]
  prev <- bs[nrow(bs) - 1L, , drop = FALSE]
  cash_d <- suppressWarnings(as.numeric(last$CASH) - as.numeric(prev$CASH))
  bfr <- function(row) {
    ar <- if ("AR" %in% names(row)) suppressWarnings(as.numeric(row$AR[[1]])) else 0
    inv <- if ("INV" %in% names(row)) suppressWarnings(as.numeric(row$INV[[1]])) else 0
    ap <- if ("AP" %in% names(row)) suppressWarnings(as.numeric(row$AP[[1]])) else 0
    (if (is.finite(ar)) ar else 0) + (if (is.finite(inv)) inv else 0) - (if (is.finite(ap)) ap else 0)
  }
  bfr_d <- bfr(last) - bfr(prev)
  if (!is.finite(cash_d)) return("")
  sign_txt <- function(x) if (is.finite(x) && x > 0) "+" else ""
  if (!is.finite(bfr_d) || abs(bfr_d) < 0.5) {
    return(fpa_screen("bs_headline_cash_only", sign_txt(cash_d), fpa_synthese_eur(cash_d)))
  }
  # WC drop frees cash; WC rise ties cash up. Only claim that path when signs agree.
  explains <- (cash_d > 0 && bfr_d < 0) || (cash_d < 0 && bfr_d > 0)
  if (explains && abs(bfr_d) >= 0.2 * abs(cash_d)) {
    fpa_screen(
      "bs_headline",
      sign_txt(cash_d), fpa_synthese_eur(cash_d),
      sign_txt(bfr_d), fpa_synthese_eur(bfr_d)
    )
  } else {
    fpa_screen(
      "bs_headline_parallel",
      sign_txt(cash_d), fpa_synthese_eur(cash_d),
      sign_txt(bfr_d), fpa_synthese_eur(bfr_d)
    )
  }
}

fpa_shiny_bs_grid <- function(bs, status = NULL, mode = "abs",
                              nature = character(0), show_op_fin = FALSE, scope = "all") {
  if (is.null(bs) || !nrow(bs)) return(shiny::tags$p("Pas de bilan."))
  mode <- as.character(mode %||% "abs")
  if (!mode %in% c("abs", "pct", "pop")) mode <- "abs"
  assets <- c("CASH", "AR", "INV", "PPE", "OTHER_CA")
  claims <- c("AP", "ST_DEBT", "LT_DEBT", "OTHER_CL", "EQUITY")
  assets <- intersect(assets, names(bs))
  claims <- intersect(claims, names(bs))
  months <- as.character(bs$periode)
  shown <- if (length(months) > 12L) tail(months, 12) else months
  forecast <- character()
  if (!is.null(status) && nrow(status) && all(c("periode", "status") %in% names(status))) {
    forecast <- as.character(status$periode)[as.character(status$status) == "forecast"]
  }
  alive <- function(cols) {
    keep <- vapply(cols, function(col) {
      v <- suppressWarnings(as.numeric(bs[[col]][match(shown, bs$periode)]))
      any(is.finite(v) & abs(v) >= 0.5)
    }, logical(1))
    list(show = cols[keep], hide = cols[!keep])
  }
  asset_use <- alive(assets)
  claim_use <- alive(claims)
  asset_use$show <- asset_use$show[vapply(asset_use$show, function(col) fpa_nature_keep(col, nature, scope), logical(1))]
  claim_use$show <- claim_use$show[vapply(claim_use$show, function(col) fpa_nature_keep(col, nature, scope), logical(1))]
  at <- function(col, month) {
    i <- match(month, as.character(bs$periode))
    if (is.na(i)) return(NA_real_)
    suppressWarnings(as.numeric(bs[[col]][[i]]))
  }
  total_of <- function(cols) {
    vapply(shown, function(m) {
      sum(vapply(cols, function(col) {
        x <- at(col, m)
        if (!is.finite(x)) 0 else x
      }, numeric(1)))
    }, numeric(1))
  }
  assets_tot <- total_of(assets)
  present <- function(vals) {
    if (identical(mode, "pct")) return(vapply(seq_along(vals), function(j) fpa_stmt_ratio(vals[[j]], assets_tot[[j]]), numeric(1)))
    if (identical(mode, "pop")) {
      out <- rep(NA_real_, length(vals))
      if (length(vals) > 1L) out[-1L] <- vapply(seq.int(2L, length(vals)), function(j) fpa_stmt_delta(vals[[j]], vals[[j - 1L]]), numeric(1))
      return(out)
    }
    vals
  }
  series <- list()
  for (col in c(asset_use$show, claim_use$show)) series[[col]] <- present(vapply(shown, function(m) at(col, m), numeric(1)))
  series[["__assets"]] <- present(assets_tot)
  series[["__claims"]] <- present(total_of(claims))
  pool <- unlist(series, use.names = FALSE)
  pool <- pool[is.finite(pool)]
  cap <- if (length(pool)) max(abs(pool)) else 1
  chip_row <- function(label, raw_vals, disp, total = FALSE, line_id = NULL, click_id = NULL) {
    shiny::tags$tr(
      class = if (total) "fpa-pnl-total" else NULL,
      if (total || is.null(line_id)) {
        shiny::tags$th(label)
      } else {
        fpa_shiny_nature_th(label, fpa_line_nature_of(nature, line_id), show_op_fin)
      },
      lapply(seq_along(shown), function(j) {
        text <- if (identical(mode, "pct")) {
          fpa_shiny_pct_label(disp[[j]])
        } else if (identical(mode, "pop")) {
          fpa_shiny_signed_eur(disp[[j]])
        } else if (is.finite(raw_vals[[j]]) && abs(raw_vals[[j]]) >= 0.5) {
          fpa_shiny_eur(raw_vals[[j]])
        } else {
          "–"
        }
        tip <- paste0(label, " · ", shown[[j]], if (is.finite(raw_vals[[j]])) paste0(" · ", fpa_shiny_eur(raw_vals[[j]]), " EUR") else "")
        chip <- fpa_shiny_chip(text, fpa_shiny_chip_score(disp[[j]], cap))
        clickable <- nzchar(as.character(click_id %||% "")) && shown[[j]] %in% forecast
        shiny::tags$td(
          title = if (clickable) paste0(tip, " · ", fpa_screen("oi_read_open")) else tip,
          if (clickable) fpa_shiny_cell_button(chip, "bs", shown[[j]], click_id) else chip
        )
      })
    )
  }
  line_row <- function(col) {
    raw_vals <- vapply(shown, function(m) at(col, m), numeric(1))
    chip_row(fpa_shiny_bs_name(col), raw_vals, series[[col]], line_id = col, click_id = col)
  }
  total_row <- function(label, key, raw_vals) {
    click <- if (identical(key, "__assets")) "assets" else if (identical(key, "__claims")) "claims" else ""
    chip_row(label, raw_vals, series[[key]], total = TRUE, click_id = click)
  }
  section <- function(label) {
    shiny::tags$tr(
      class = "fpa-bs-section",
      shiny::tags$th(colspan = length(shown) + 1L, label)
    )
  }
  header <- shiny::tags$tr(
    shiny::tags$th("Poste"),
    lapply(shown, function(m) {
      shiny::tags$th(style = paste0("background:", if (m %in% forecast) "#8a5a00" else "#1f4e5f", ";"), m)
    })
  )
  hidden <- c(asset_use$hide, claim_use$hide)
  shiny::tags$div(
    class = "fpa-pnl fpa-bs",
    shiny::tags$table(
      shiny::tags$thead(header),
      shiny::tags$tbody(
        section("Actif"),
        lapply(asset_use$show, line_row),
        if (!identical(scope, "op_fin")) total_row("Total actif", "__assets", assets_tot) else NULL,
        section("Passif et capitaux"),
        lapply(claim_use$show, line_row),
        if (!identical(scope, "op_fin")) total_row("Total passif et capitaux", "__claims", total_of(claims)) else NULL
      )
    ),
    shiny::tags$p(
      if (identical(mode, "pct")) fpa_screen("stmt_pct_bs") else if (identical(mode, "pop")) fpa_screen("stmt_pop_note") else fpa_screen("stmt_heat_note"),
      " ",
      if (any(shown %in% forecast)) shiny::tagList(
        shiny::tags$span(
          class = "fpa-oi-mark",
          shiny::tags$span(class = "fpa-oi-swatch", `aria-hidden` = "true"),
          fpa_screen("oi_read_hint")
        ),
        " "
      ) else NULL,
      if (isTRUE(show_op_fin)) paste0(" ", fpa_screen("stmt_opfin_note")) else "",
      if (length(months) > length(shown)) paste0(" ", fpa_screen("bs_window")) else "",
      if (length(hidden)) paste0(" ", fpa_screen("bs_hidden", paste(vapply(hidden, fpa_shiny_bs_name, character(1)), collapse = ", "))) else ""
    )
  )
}

fpa_shiny_pnl_waterfall_plot <- function(row, compact = FALSE) {
  built <- fpa_pnl_waterfall_build(row)
  if (is.null(built) || !FPA_HAS_PLOTLY) return(NULL)
  br <- built$bars
  br$label <- vapply(br$id, fpa_shiny_line_name, character(1))
  # FSI palette: navy totals, red costs, green gains
  cols <- ifelse(
    br$kind == "total", "#1B3A5C",
    ifelse(br$value >= 0, "#27AE60", "#E74C3C")
  )
  links <- if (!is.null(built$connectors)) {
    lapply(seq_len(nrow(built$connectors)), function(i) {
      list(
        type = "line", xref = "x", yref = "y",
        x0 = built$connectors$x0[[i]], x1 = built$connectors$x1[[i]],
        y0 = built$connectors$y[[i]], y1 = built$connectors$y[[i]],
        line = list(color = "#5c6b73", width = 1.2, dash = "dot")
      )
    })
  } else {
    list()
  }
  amounts <- vapply(br$value, fpa_shiny_eur, character(1))
  signs <- ifelse(br$value >= 0, "+", "")
  labels <- paste0(signs, amounts)
  extras <- if ("hover_extra" %in% names(br)) as.character(br$hover_extra) else rep("", nrow(br))
  extras[is.na(extras)] <- ""
  hover <- paste0(
    "<b>", br$label, "</b><br>",
    ifelse(br$kind == "total", "Solde ", ""), labels, " EUR",
    ifelse(nzchar(extras), paste0("<br>", extras), "")
  )
  span <- range(c(0, br$base, br$end), na.rm = TRUE)
  # Room above/below for value labels (outside the bar).
  pad <- max(diff(span) * if (isTRUE(compact)) 0.16 else 0.18, 1)
  # Positive amounts sit above the bar, negatives below.
  text_pos <- ifelse(br$value >= 0, "outside", "outside")
  p <- plotly::plot_ly(
    type = "bar",
    x = br$x, y = br$value, base = br$base,
    marker = list(color = cols, line = list(width = 0)),
    text = labels,
    textposition = text_pos,
    cliponaxis = FALSE,
    textfont = list(size = if (isTRUE(compact)) 9 else 11, color = "#1a2b32"),
    hovertext = hover,
    hoverinfo = "text",
    showlegend = FALSE
  )
  # plot_ly() treats top-level `width` as figure size; keep bar width on attrs.
  if (length(p$x$attrs) >= 1L) p$x$attrs[[1]]$width <- built$width
  # Invisible markers at each bar mid-height so thin steps stay hoverable.
  mid_y <- br$base + br$value / 2
  p <- plotly::add_trace(
    p,
    inherit = FALSE,
    type = "scatter",
    mode = "markers",
    x = br$x,
    y = mid_y,
    marker = list(size = if (isTRUE(compact)) 22 else 28, opacity = 0, color = "#000000"),
    hovertext = hover,
    hoverinfo = "text",
    showlegend = FALSE,
    cliponaxis = FALSE
  )
  p <- plotly::layout(
    p,
    autosize = TRUE,
    separators = ",\u202f",
    bargap = 0.15,
    hovermode = "closest",
    hoverdistance = 64,
    spikedistance = -1,
    shapes = links,
    plot_bgcolor = "#ffffff",
    paper_bgcolor = "#ffffff",
    margin = if (isTRUE(compact)) {
      list(t = 18, b = 52, l = 36, r = 4)
    } else {
      list(t = 28, b = 90, l = 56, r = 12)
    },
    yaxis = list(
      title = if (isTRUE(compact)) "" else "EUR",
      tickformat = ",d",
      gridcolor = "#e6edef",
      zeroline = TRUE,
      zerolinecolor = "#1f4e5f",
      zerolinewidth = if (isTRUE(compact)) 1.2 else 2,
      tickfont = list(size = if (isTRUE(compact)) 9 else 12),
      range = c(span[[1]] - pad, span[[2]] + pad)
    ),
    xaxis = list(
      title = "",
      tickmode = "array",
      tickvals = br$x,
      ticktext = br$label,
      tickangle = if (isTRUE(compact)) -40 else -35,
      tickfont = list(size = if (isTRUE(compact)) 9 else 12)
    )
  )
  p <- plotly::config(
    p,
    displaylogo = FALSE,
    displayModeBar = !isTRUE(compact),
    responsive = TRUE
  )
  p
}

fpa_shiny_bs_treemap <- function(bs, period) {
  if (is.null(bs) || !nrow(bs) || !FPA_HAS_PLOTLY) return(NULL)
  per <- as.character(period %||% "")
  pers <- as.character(bs$periode)
  if (!nzchar(per) || !per %in% pers) per <- pers[[length(pers)]]
  row <- bs[pers == per, , drop = FALSE][1, , drop = FALSE]
  assets <- c("CASH", "AR", "INV", "PPE", "OTHER_CA")
  claims <- c("AP", "ST_DEBT", "LT_DEBT", "OTHER_CL", "EQUITY")
  asset_col <- c(CASH = "#1f4e5f", AR = "#2f6d82", INV = "#4d8ea0", PPE = "#163844", OTHER_CA = "#7aabba")
  claim_col <- c(AP = "#8c3a3a", ST_DEBT = "#a85a4a", LT_DEBT = "#6e2c2c", OTHER_CL = "#c4897a", EQUITY = "#3d5c66")
  take <- function(ids, parent, cols) {
    out <- list()
    for (id in intersect(ids, names(row))) {
      v <- suppressWarnings(as.numeric(row[[id]][[1]]))
      if (!is.finite(v) || abs(v) < 0.5) next
      out[[length(out) + 1L]] <- data.frame(
        label = fpa_shiny_bs_name(id), parent = parent,
        value = abs(v), raw = v, color = unname(cols[[id]] %||% "#5c6b73"),
        stringsAsFactors = FALSE
      )
    }
    out
  }
  leaves <- c(take(assets, "Actif", asset_col), take(claims, "Passif et capitaux", claim_col))
  if (!length(leaves)) return(plotly::plotly_empty())
  leaf <- do.call(rbind, leaves)
  parents <- unique(leaf$parent)
  parent_rows <- data.frame(
    label = parents,
    parent = "",
    value = vapply(parents, function(p) sum(leaf$value[leaf$parent == p]), numeric(1)),
    raw = vapply(parents, function(p) sum(leaf$raw[leaf$parent == p]), numeric(1)),
    color = ifelse(parents == "Actif", "#1f4e5f", "#8c3a3a"),
    stringsAsFactors = FALSE
  )
  all_rows <- rbind(parent_rows, leaf)
  hover <- paste0(all_rows$label, "<br>", vapply(all_rows$raw, function(v) paste0(fpa_shiny_eur(v), " EUR"), character(1)))
  p <- plotly::plot_ly(
    type = "treemap",
    labels = all_rows$label,
    parents = all_rows$parent,
    values = all_rows$value,
    branchvalues = "total",
    marker = list(colors = all_rows$color, line = list(width = 1, color = "#ffffff")),
    text = hover,
    hoverinfo = "text",
    textinfo = "label+percent parent",
    textfont = list(size = 13, color = "#ffffff")
  )
  p <- plotly::layout(
    p,
    margin = list(t = 28, l = 8, r = 8, b = 8),
    paper_bgcolor = "#ffffff"
  )
  plotly::config(p, displaylogo = FALSE, displayModeBar = FALSE)
}

fpa_shiny_bs_color <- function(id) {
  cols <- c(
    CASH = "#1f4e5f", AR = "#2f6d82", INV = "#4d8ea0", PPE = "#163844", OTHER_CA = "#7aabba",
    AP = "#8c3a3a", ST_DEBT = "#a85a4a", LT_DEBT = "#6e2c2c", OTHER_CL = "#c4897a", EQUITY = "#3d5c66"
  )
  hit <- unname(cols[as.character(id)])
  if (length(hit) == 1L && !is.na(hit)) hit else "#5c6b73"
}

fpa_shiny_bs_pts <- function(v) {
  if (!is.finite(v)) return("–")
  paste0(if (v > 0.05) "+" else "", formatC(v, format = "f", digits = 1, decimal.mark = ",", big.mark = " "), " pts")
}

fpa_shiny_bs_move <- function(move) {
  key <- switch(as.character(move),
    up = "bs_cmp_up", down = "bs_cmp_down", new = "bs_cmp_new",
    gone = "bs_cmp_gone", "bs_cmp_flat"
  )
  fpa_screen(key)
}

#' Assets on the left, liabilities and equity on the right.
#' Block height is the line's share of its side. A slice too thin for a label keeps the label beside it.
fpa_shiny_bs_map_column <- function(bs, period, ids, side_class, title, kicker = NULL) {
  stack_px <- 360
  label_px <- 34
  tags_left <- identical(side_class, "is-asset")
  vals <- vapply(ids, function(id) {
    v <- fpa_bs_amount_at(bs, period, id)
    if (!is.finite(v)) 0 else v
  }, numeric(1))
  keep <- abs(vals) >= 0.5
  ids <- ids[keep]
  vals <- vals[keep]
  if (!length(ids)) {
    return(shiny::tags$div(
      class = paste("fpa-bs-col", side_class),
      if (!is.null(kicker)) shiny::tags$h3(kicker),
      shiny::tags$h4(title)
    ))
  }
  tot <- sum(abs(vals))
  heights <- if (tot < 0.5) rep(0, length(vals)) else abs(vals) / tot * stack_px
  tops <- c(0, cumsum(heights))[seq_along(heights)]
  inside <- heights >= label_px
  tag_top <- tops
  if (any(!inside)) {
    idx <- which(!inside)
    prev <- -label_px
    for (j in idx) {
      if (tag_top[[j]] < prev) tag_top[[j]] <- prev
      prev <- tag_top[[j]] + label_px
    }
    overflow <- prev - stack_px
    if (overflow > 0) tag_top[idx] <- pmax(0, tag_top[idx] - overflow)
  }
  blocks <- lapply(seq_along(ids), function(i) {
    lab <- fpa_shiny_bs_name(ids[[i]])
    share <- if (tot < 0.5) NA_real_ else 100 * abs(vals[[i]]) / tot
    pct <- if (is.finite(share)) fpa_shiny_pct_label(share) else ""
    shiny::tags$div(
      class = "fpa-bs-block",
      style = sprintf(
        "top:%.2fpx;height:%.2fpx;background:%s;%s",
        tops[[i]], max(heights[[i]], 0), fpa_shiny_bs_color(ids[[i]]),
        if (isTRUE(inside[[i]])) "padding:4px 8px;" else "padding:0;"
      ),
      title = paste0(lab, " · ", fpa_shiny_eur(vals[[i]]), " EUR", if (nzchar(pct)) paste0(" · ", pct) else ""),
      if (isTRUE(inside[[i]])) shiny::tagList(
        shiny::tags$b(lab),
        shiny::tags$span(paste0(fpa_shiny_eur(vals[[i]]), " €\u2003", pct))
      ) else NULL
    )
  })
  tags <- lapply(which(!inside), function(i) {
    lab <- fpa_shiny_bs_name(ids[[i]])
    share <- if (tot < 0.5) NA_real_ else 100 * abs(vals[[i]]) / tot
    pct <- if (is.finite(share)) fpa_shiny_pct_label(share) else ""
    shiny::tags$div(
      class = "fpa-bs-tag",
      style = sprintf("top:%.0fpx;", tag_top[[i]]),
      shiny::tags$span(class = "fpa-bs-tag-name", shiny::tags$i(style = paste0("background:", fpa_shiny_bs_color(ids[[i]]), ";")), lab),
      shiny::tags$span(class = "fpa-bs-tag-num", paste0(fpa_shiny_eur(vals[[i]]), " €  ", pct))
    )
  })
  tag_box <- if (length(tags)) shiny::tags$div(class = "fpa-bs-tags", tags) else NULL
  shiny::tags$div(
    class = paste("fpa-bs-col", side_class),
    if (!is.null(kicker)) shiny::tags$h3(kicker),
    shiny::tags$h4(title),
    shiny::tags$div(
      class = paste("fpa-bs-plot", if (length(tags)) if (tags_left) "has-tags tags-left" else "has-tags tags-right"),
      shiny::tags$div(class = "fpa-bs-stack", blocks),
      tag_box
    )
  )
}

fpa_shiny_bs_map_card <- function(bs, period, kicker) {
  sides <- fpa_bs_side_ids()
  shiny::tags$section(
    class = "fpa-bs-map-card",
    shiny::tags$h3(paste0(kicker, " · ", fpa_ym_fr(period))),
    shiny::tags$div(
      class = "fpa-bs-split",
      fpa_shiny_bs_map_column(bs, period, sides$asset, "is-asset", fpa_screen("bs_cmp_asset")),
      fpa_shiny_bs_map_column(bs, period, sides$claim, "is-claim", fpa_screen("bs_cmp_claim"))
    )
  )
}

fpa_shiny_bs_top <- function(cmp) {
  cmp <- fpa_shiny_bs_cmp_euros(cmp)
  lines <- cmp$lines
  if (is.null(lines) || !nrow(lines)) return(NULL)
  lines <- lines[order(-abs(lines$show_d)), , drop = FALSE]
  lines <- head(lines, 3L)
  shiny::tags$details(
    class = "fpa-bs-top",
    open = NA,
    shiny::tags$summary(fpa_screen("bs_cmp_top")),
    shiny::tags$ol(
      lapply(seq_len(nrow(lines)), function(i) {
        row <- lines[i, , drop = FALSE]
        side <- if (identical(row$side, "asset")) fpa_screen("bs_cmp_asset") else fpa_screen("bs_cmp_claim")
        pct <- if (is.finite(row$pct)) fpa_shiny_pct_label(row$pct) else fpa_shiny_bs_move(row$move)
        level <- fpa_shiny_bs_strength(row$pct, row$move)
        shiny::tags$li(
          shiny::tags$i(class = "fpa-bs-swatch", style = paste0("background:", fpa_shiny_bs_color(row$id), ";")),
          shiny::tags$b(fpa_shiny_bs_name(row$id)),
          shiny::tags$span(class = "fpa-bs-top-side", side),
          shiny::tags$span(
            class = paste("fpa-bs-top-move", paste0("is-", level)),
            paste(fpa_shiny_bs_arrow(row$move), fpa_shiny_signed_eur(row$show_d), "·", pct)
          )
        )
      })
    )
  )
}

fpa_shiny_bs_cmp_euros <- function(cmp) {
  if (is.null(cmp) || !nrow(cmp$lines)) return(cmp)
  lines <- cmp$lines
  lines$show_a <- round(lines$amount_a)
  lines$show_b <- round(lines$amount_b)
  lines$show_d <- lines$show_b - lines$show_a
  sides <- cmp$sides
  sides$show_a <- round(sides$total_a)
  sides$show_b <- round(sides$total_b)
  sides$show_d <- sides$show_b - sides$show_a
  cmp$lines <- lines
  cmp$sides <- sides
  cmp
}

fpa_shiny_bs_cmp_lead <- function(cmp) {
  cmp <- fpa_shiny_bs_cmp_euros(cmp)
  side <- function(name) cmp$sides[cmp$sides$side == name, , drop = FALSE]
  asset <- side("asset")
  claim <- side("claim")
  if (!nrow(asset) || !nrow(claim)) return("")
  fpa_screen(
    "bs_cmp_lead",
    fpa_ym_fr(cmp$period_a), fpa_ym_fr(cmp$period_b),
    fpa_shiny_eur(asset$show_a), fpa_shiny_eur(asset$show_b), fpa_shiny_signed_eur(asset$show_d),
    fpa_shiny_eur(claim$show_a), fpa_shiny_eur(claim$show_b), fpa_shiny_signed_eur(claim$show_d)
  )
}

fpa_shiny_bs_arrow <- function(move) {
  switch(as.character(move),
    up = "\u2191",
    down = "\u2193",
    new = "\u2191",
    gone = "\u2193",
    "\u2192"
  )
}

#' 1 is a small move, 4 is a large one. The scale is size, not a judgement.
fpa_shiny_bs_strength <- function(pct, move) {
  if (identical(as.character(move), "flat")) return(1L)
  if (as.character(move) %in% c("new", "gone")) return(4L)
  if (!is.finite(pct)) return(2L)
  a <- abs(pct)
  if (a < 5) 1L else if (a < 15) 2L else if (a < 30) 3L else 4L
}

fpa_shiny_bs_cmp_table <- function(cmp) {
  cmp <- fpa_shiny_bs_cmp_euros(cmp)
  if (is.null(cmp) || !nrow(cmp$lines)) return(shiny::tags$p(fpa_screen("loc_no_lines_compare")))
  abs_td <- function(v) shiny::tags$td(class = "is-abs", fpa_shiny_eur(v))
  move_td <- function(pct, move, text) {
    level <- fpa_shiny_bs_strength(pct, move)
    width <- if (is.finite(pct)) min(100, abs(pct)) else if (as.character(move) %in% c("new", "gone")) 100 else 0
    shiny::tags$td(
      class = paste("fpa-bs-var", paste0("is-", level)),
      shiny::tags$span(class = "fpa-bs-var-txt", paste(fpa_shiny_bs_arrow(move), text)),
      shiny::tags$span(
        class = "fpa-bs-var-track",
        shiny::tags$span(class = "fpa-bs-var-bar", style = sprintf("width:%.1f%%;", width))
      )
    )
  }
  line_tr <- function(row) {
    sens <- fpa_shiny_bs_move(row$move)
    pct_txt <- if (is.finite(row$pct)) fpa_shiny_pct_label(row$pct) else sens
    shiny::tags$tr(
      shiny::tags$td(fpa_shiny_bs_name(row$id)),
      shiny::tags$td(if (identical(row$side, "asset")) fpa_screen("bs_cmp_asset") else fpa_screen("bs_cmp_claim")),
      abs_td(row$show_a),
      abs_td(row$show_b),
      move_td(row$pct, row$move, fpa_shiny_signed_eur(row$show_d)),
      move_td(row$pct, row$move, pct_txt),
      move_td(row$pct, row$move, sens),
      shiny::tags$td(class = "is-abs", if (is.finite(row$share_a)) fpa_shiny_pct_label(100 * row$share_a) else "–"),
      shiny::tags$td(class = "is-abs", if (is.finite(row$share_b)) fpa_shiny_pct_label(100 * row$share_b) else "–"),
      move_td(row$share_pts, if (is.finite(row$share_pts) && row$share_pts > 0.05) "up" else if (is.finite(row$share_pts) && row$share_pts < -0.05) "down" else "flat", fpa_shiny_bs_pts(row$share_pts))
    )
  }
  total_tr <- function(side_name, label) {
    row <- cmp$sides[cmp$sides$side == side_name, , drop = FALSE]
    if (!nrow(row)) return(NULL)
    shiny::tags$tr(
      class = "is-total",
      shiny::tags$td(label),
      shiny::tags$td(if (identical(side_name, "asset")) fpa_screen("bs_cmp_asset") else fpa_screen("bs_cmp_claim")),
      abs_td(row$show_a),
      abs_td(row$show_b),
      shiny::tags$td(class = "is-abs", fpa_shiny_signed_eur(row$show_d)),
      shiny::tags$td(class = "is-abs", if (is.finite(row$pct)) fpa_shiny_pct_label(row$pct) else "–"),
      shiny::tags$td(""),
      shiny::tags$td("100 %"),
      shiny::tags$td("100 %"),
      shiny::tags$td("–")
    )
  }
  plug_tr <- function(side_name) {
    part <- cmp$lines[cmp$lines$side == side_name, , drop = FALSE]
    side <- cmp$sides[cmp$sides$side == side_name, , drop = FALSE]
    if (!nrow(side)) return(NULL)
    ga <- side$show_a[[1]] - sum(part$show_a)
    gb <- side$show_b[[1]] - sum(part$show_b)
    gd <- side$show_d[[1]] - sum(part$show_d)
    if (abs(ga) < 0.5 && abs(gb) < 0.5 && abs(gd) < 0.5) return(NULL)
    shiny::tags$tr(
      shiny::tags$td(fpa_screen("bs_cmp_round")),
      shiny::tags$td(if (identical(side_name, "asset")) fpa_screen("bs_cmp_asset") else fpa_screen("bs_cmp_claim")),
      shiny::tags$td(class = "is-abs", fpa_shiny_eur(ga)),
      shiny::tags$td(class = "is-abs", fpa_shiny_eur(gb)),
      shiny::tags$td(class = "is-abs", fpa_shiny_signed_eur(gd)),
      shiny::tags$td("–"), shiny::tags$td(""),
      shiny::tags$td("–"), shiny::tags$td("–"), shiny::tags$td("–")
    )
  }
  body <- list()
  for (side_name in c("asset", "claim")) {
    part <- cmp$lines[cmp$lines$side == side_name, , drop = FALSE]
    if (nrow(part)) {
      for (i in seq_len(nrow(part))) body[[length(body) + 1L]] <- line_tr(part[i, , drop = FALSE])
    }
    body[[length(body) + 1L]] <- plug_tr(side_name)
    body[[length(body) + 1L]] <- total_tr(
      side_name,
      if (identical(side_name, "asset")) fpa_screen("bs_cmp_total_asset") else fpa_screen("bs_cmp_total_claim")
    )
  }
  known <- unlist(fpa_bs_side_ids(), use.names = FALSE)
  hidden <- setdiff(known, cmp$lines$id)
  shiny::tags$div(
    class = "fpa-bs-diff",
    shiny::tags$table(
      shiny::tags$thead(shiny::tags$tr(
        shiny::tags$th(fpa_screen("bs_cmp_th_item")),
        shiny::tags$th(fpa_screen("bs_cmp_th_side")),
        shiny::tags$th(fpa_ym_fr(cmp$period_a)),
        shiny::tags$th(fpa_ym_fr(cmp$period_b)),
        shiny::tags$th(fpa_screen("bs_cmp_th_delta")),
        shiny::tags$th(fpa_screen("bs_cmp_th_pct")),
        shiny::tags$th(fpa_screen("bs_cmp_th_move")),
        shiny::tags$th(paste(fpa_screen("bs_cmp_th_share"), fpa_ym_fr(cmp$period_a))),
        shiny::tags$th(paste(fpa_screen("bs_cmp_th_share"), fpa_ym_fr(cmp$period_b))),
        shiny::tags$th(fpa_screen("bs_cmp_th_pts"))
      )),
      shiny::tags$tbody(body)
    ),
    if (length(hidden)) shiny::tags$p(fpa_screen("bs_cmp_hidden", paste(vapply(hidden, fpa_shiny_bs_name, character(1)), collapse = ", "))) else NULL
  )
}

fpa_shiny_when <- function(x) {
  raw <- as.character(x)
  raw[is.na(raw)] <- ""
  vapply(raw, function(one) {
    one <- sub("\\..*$", "", sub("T", " ", one, fixed = TRUE))
    if (!nzchar(one) || nchar(one) < 16L) return(one)
    paste0(substr(one, 9L, 10L), "/", substr(one, 6L, 7L), "/", substr(one, 1L, 4L), fpa_screen("loc_to_glue"), substr(one, 12L, 16L))
  }, character(1), USE.NAMES = FALSE)
}

fpa_shiny_lock_grid <- function(lock, nature = character(0), show_op_fin = FALSE) {
  if (is.null(lock) || !nrow(lock)) return(shiny::tags$p(fpa_screen("loc_no_month_locked")))
  order_ids <- intersect(fpa_pnl_input_ids(), unique(as.character(lock$line_id)))
  extra <- setdiff(unique(as.character(lock$line_id)), order_ids)
  lines <- c(order_ids, extra)
  months <- sort(unique(as.character(lock$periode)))
  shown <- if (length(months) > 12L) utils::tail(months, 12) else months
  keep <- vapply(lines, function(line) {
    v <- lock$montant[lock$line_id == line & lock$periode %in% shown]
    any(is.finite(v) & abs(v) >= 0.5)
  }, logical(1))
  hidden <- lines[!keep]
  lines <- lines[keep]
  raw <- lapply(lines, function(line) {
    vapply(shown, function(m) {
      hit <- lock$montant[lock$line_id == line & lock$periode == m]
      if (!length(hit)) return(NA_real_)
      suppressWarnings(as.numeric(hit[[1]]))
    }, numeric(1))
  })
  names(raw) <- lines
  pool <- unlist(raw, use.names = FALSE)
  pool <- pool[is.finite(pool)]
  cap <- if (length(pool)) max(abs(pool)) else 1
  totals <- intersect(c("GP", "EBITDA", "OI", "NI"), lines)
  shiny::tags$div(
    class = "fpa-pnl",
    shiny::tags$table(
      shiny::tags$thead(shiny::tags$tr(
        shiny::tags$th("Ligne"),
        lapply(shown, function(m) shiny::tags$th(style = "background:#1f4e5f;", fpa_var_month_abbr(m, with_year = TRUE)))
      )),
      shiny::tags$tbody(lapply(lines, function(line) {
        vals <- raw[[line]]
        shiny::tags$tr(
          class = if (line %in% totals) "fpa-pnl-total" else NULL,
          fpa_shiny_nature_th(
            fpa_shiny_line_name(line),
            fpa_line_nature_of(nature, line),
            show_op_fin
          ),
          lapply(seq_along(shown), function(j) {
            label <- if (is.finite(vals[[j]]) && abs(vals[[j]]) >= 0.5) fpa_shiny_eur(vals[[j]]) else "–"
            shiny::tags$td(
              title = paste0(
                fpa_shiny_line_name(line), " · ", fpa_close_mlong(shown[[j]]), " · ",
                if (is.finite(vals[[j]])) paste0(fpa_shiny_eur(vals[[j]]), " EUR") else "–"
              ),
              fpa_shiny_chip(label, fpa_shiny_chip_score(vals[[j]], cap))
            )
          })
        )
      }))
    ),
    shiny::tags$p(
      fpa_screen("stmt_heat_note"),
      if (length(months) > length(shown)) paste0(" ", fpa_screen("bs_window")) else "",
      if (isTRUE(show_op_fin)) paste0(" ", fpa_screen("stmt_opfin_note")) else "",
      if (length(hidden)) paste0(
        fpa_screen("loc_row_hidden_zero_sp"),
        paste(vapply(hidden, fpa_shiny_line_name, character(1)), collapse = ", "), "."
      ) else ""
    )
  )
}

fpa_close_mlong <- function(p) {
  p <- as.character(p %||% "")
  if (!length(p) || !nzchar(p[[1]])) return("")
  paste(fpa_shiny_month_name(p[[1]]), substr(p[[1]], 1L, 4L))
}

fpa_close_between <- function(pers) {
  pers <- sort(unique(as.character(pers)))
  if (!length(pers)) return("")
  if (length(pers) == 1L) return(fpa_close_mlong(pers))
  fpa_screen("close_between", fpa_close_mlong(pers[[1]]), fpa_close_mlong(pers[[length(pers)]]))
}

fpa_close_lc <- function(x) paste0(tolower(substr(x, 1L, 1L)), substr(x, 2L, nchar(x)))
fpa_close_uc <- function(x) paste0(toupper(substr(x, 1L, 1L)), substr(x, 2L, nchar(x)))

fpa_close_year <- function(months) {
  y <- unique(substr(as.character(months), 1L, 4L))
  if (length(y) == 1L) y else fpa_screen("close_year_span")
}

fpa_close_month_oi <- function(pnl, variance, m) {
  if (!nzchar(m %||% "") || is.null(pnl) || !nrow(pnl)) return(NULL)
  act <- fpa_close_sum(pnl, "OI", m)
  bud <- NA_real_
  if (!is.null(variance) && nrow(variance) && all(c("periode", "line_id", "budget") %in% names(variance))) {
    sl <- variance[as.character(variance$periode) == m & as.character(variance$line_id) %in% fpa_close_op_lines(), , drop = FALSE]
    if (nrow(sl)) {
      bud <- sum(vapply(seq_len(nrow(sl)), function(i) {
        fpa_pnl_ni_sign(as.character(sl$line_id[[i]])) * suppressWarnings(as.numeric(sl$budget[[i]]))
      }, numeric(1)), na.rm = TRUE)
    }
  }
  list(actual = act, budget = bud, gap = act - bud)
}

#' Everything the Clôture page reads, from the work folder of the loaded calculation.
fpa_close_state <- function(p) {
  if (!isTRUE(p$ok) || is.null(p$paths)) return(NULL)
  paths <- p$paths
  fin <- p$finance %||% list()
  pnl <- fin$pnl
  status <- fin$period_status
  act <- character(0)
  if (!is.null(status) && nrow(status) && all(c("periode", "status") %in% names(status))) {
    act <- sort(as.character(status$periode[as.character(status$status) == "actual"]))
  }
  months <- if (!is.null(pnl) && nrow(pnl)) as.character(pnl$periode) else character(0)
  lock <- fpa_shiny_csv(file.path(paths$work, "standing-lock.csv"))
  lock_months <- if (nrow(lock)) sort(unique(as.character(lock$periode))) else character(0)
  pnl_path <- file.path(paths$work, "pnl-monthly.csv")
  cur_md5 <- fpa_md5_file(pnl_path)
  versions <- fpa_close_versions(paths, months)
  saved <- NULL
  if (nrow(versions) && !is.na(cur_md5) && cur_md5 %in% versions$md5) {
    saved <- versions[max(which(versions$md5 == cur_md5)), , drop = FALSE]
  }
  snap <- fpa_snapshot_read(paths)
  newer <- tryCatch(fpa_shiny_newer_sources(p$config, paths), error = function(e) character(0))
  closed <- if (length(act)) act[[length(act)]] else ""
  list(
    months = months, act = act, closed = closed, year = fpa_close_year(months),
    lock = lock, lock_months = lock_months, unlocked = setdiff(act, lock_months),
    versions = versions, cur_md5 = cur_md5, saved = saved,
    current = list(
      rev = fpa_close_sum(pnl, "REV", months), oi = fpa_close_sum(pnl, "OI", months),
      ni = fpa_close_sum(pnl, "NI", months), cash_end = fpa_close_cash_end(fin$cash, months)
    ),
    budget = fpa_close_budget_check(paths),
    anom = if (is.null(snap)) NULL else list(act = as.integer(snap$anom_act %||% 0L), watch = as.integer(snap$anom_watch %||% 0L)),
    newer = unique(as.character(newer)),
    run_at = if (file.exists(pnl_path)) format(file.info(pnl_path)$mtime, "%Y-%m-%dT%H:%M") else "",
    month_oi = fpa_close_month_oi(pnl, fin$variance, closed),
    pnl = pnl
  )
}

#' Drift rows that touch the current calculation. Older locked months have no effect.
fpa_close_drift_in <- function(st, drift) {
  if (is.null(st) || is.null(drift) || !nrow(drift)) return(drift)
  drift[as.character(drift$periode) %in% st$months, , drop = FALSE]
}

#' One line per drifted month: locked revenue and operating income against the file.
fpa_close_drift_months <- function(st, drift) {
  d <- fpa_close_drift_in(st, drift)
  if (is.null(d) || !nrow(d)) return(data.frame())
  ms <- sort(unique(as.character(d$periode)))
  rows <- lapply(ms, function(m) {
    sl <- d[d$periode == m, , drop = FALSE]
    rev_lock <- fpa_close_sum(st$pnl, "REV", m)
    oi_lock <- fpa_close_sum(st$pnl, "OI", m)
    op <- sl[sl$line_id %in% fpa_close_op_lines(), , drop = FALSE]
    oi_eff <- if (nrow(op)) sum(vapply(seq_len(nrow(op)), function(i) fpa_pnl_ni_sign(op$line_id[[i]]) * op$delta[[i]], numeric(1))) else 0
    rev_d <- sum(sl$delta[sl$line_id == "REV"])
    data.frame(
      periode = m, n_lines = nrow(sl),
      rev_lock = rev_lock, rev_file = rev_lock + rev_d,
      oi_lock = oi_lock, oi_file = oi_lock + oi_eff, oi_gap = oi_eff,
      stringsAsFactors = FALSE
    )
  })
  do.call(rbind, rows)
}

#' The six close steps. `state` is done, now, or info; info never counts as left to do.
fpa_close_steps <- function(st, drift = NULL) {
  if (is.null(st)) return(list())
  m <- st$closed
  ml <- fpa_close_mlong(m)
  go <- function(tab, periode = "") sprintf("Shiny.setInputValue('fpa_go',{tab:'%s',periode:'%s'},{priority:'event'})", tab, periode)
  open_fold <- function(id) sprintf("if (window.fpaCloseOpen) window.fpaCloseOpen('%s')", id)
  btn <- function(label, onclick) shiny::tags$button(type = "button", class = "fpa-path-btn is-quiet", onclick = onclick, label)
  steps <- list()
  if (!length(st$act)) {
    steps$data <- list(state = "now", label = fpa_screen("close_s_data_none_lab"), detail = fpa_screen("close_s_data_none"))
  } else if (length(st$newer)) {
    steps$data <- list(
      state = "now", label = fpa_screen("close_s_data_lab", ml),
      detail = fpa_screen("close_s_data_stale", paste(st$newer, collapse = ", ")),
      action = btn(fpa_screen("close_btn_sync"), "var b=document.getElementById('sync'); if (b) b.click();")
    )
  } else {
    steps$data <- list(
      state = "done", label = fpa_screen("close_s_data_lab", ml),
      detail = fpa_screen("close_s_data_ok", length(st$act), fpa_close_between(st$act), fpa_shiny_when(st$run_at))
    )
  }
  a <- st$anom
  steps$checks <- if (is.null(a)) {
    list(state = "info", label = fpa_screen("close_s_chk_lab"), detail = fpa_screen("close_s_chk_wait"))
  } else if (a$act > 0L) {
    list(state = "now", label = fpa_screen("close_s_chk_lab"), detail = fpa_screen("close_s_chk_open", a$act, a$watch),
         action = btn(fpa_screen("close_btn_anom"), go("Anomalies")))
  } else {
    list(state = "done", label = fpa_screen("close_s_chk_lab"),
         detail = if (a$watch > 0L) fpa_screen("close_s_chk_watch", a$watch) else fpa_screen("close_s_chk_clear"))
  }
  mo <- st$month_oi
  if (!is.null(mo) && is.finite(mo$actual)) {
    steps$result <- list(
      state = "info", label = fpa_screen("close_s_res_lab", ml),
      detail = if (is.finite(mo$budget)) {
        fpa_screen("close_s_res", fpa_var_eur(mo$actual), fpa_var_eur(mo$budget), fpa_var_eur_s(mo$gap))
      } else {
        fpa_screen("close_s_res_nobud", fpa_var_eur(mo$actual))
      },
      action = btn(fpa_screen("close_btn_var"), go(fpa_screen("loc_variances"), m))
    )
  }
  d_months <- fpa_close_drift_months(st, drift)
  steps$lock <- if (nrow(d_months)) {
    list(state = "now", label = fpa_screen("close_s_lock_drift_lab"),
         detail = fpa_screen("close_s_lock_drift", nrow(d_months), fpa_close_between(d_months$periode)),
         action = btn(fpa_screen("close_btn_see"), open_fold("close-lock")))
  } else if (length(st$unlocked)) {
    list(
      state = "now",
      label = if (length(st$unlocked) == 1L) fpa_screen("close_s_lock_one", ml) else fpa_screen("close_s_lock_n", length(st$unlocked)),
      detail = if (length(st$unlocked) == 1L) fpa_screen("close_s_lock_open1") else fpa_screen("close_s_lock_openn", fpa_close_between(st$unlocked)),
      action = shiny::actionButton("close_lock_btn", fpa_screen("close_btn_lock"), class = "fpa-path-btn")
    )
  } else if (length(st$act)) {
    list(state = "done", label = fpa_screen("close_s_lock_done_lab"), detail = fpa_screen("close_s_lock_done", length(st$act)))
  } else {
    NULL
  }
  steps$save <- if (!is.null(st$saved)) {
    lab <- as.character(st$saved$label[[1]])
    list(state = "done", label = fpa_screen("close_s_save_done_lab"),
         detail = fpa_screen("close_s_save_done", fpa_shiny_when(st$saved$saved_at[[1]]), if (nzchar(lab)) lab else "–"))
  } else {
    last <- if (nrow(st$versions)) fpa_shiny_when(utils::tail(st$versions$saved_at, 1)) else ""
    list(
      state = "now", label = fpa_screen("close_s_save_lab"),
      detail = if (nzchar(last)) fpa_screen("close_s_save_since", last) else fpa_screen("close_s_save_none"),
      action = shiny::tags$div(
        class = "fpa-close-save",
        shiny::textInput("close_label", NULL, value = fpa_screen("close_label_def", ml), width = "220px"),
        shiny::actionButton("close_save_btn", fpa_screen("close_btn_save"), class = "fpa-path-btn")
      )
    )
  }
  b <- st$budget
  steps$budget <- if (!isTRUE(b$frozen)) {
    list(state = "now", label = fpa_screen("close_s_bud_lab"), detail = fpa_screen("close_s_bud_none"),
         action = shiny::actionButton("close_freeze_btn", fpa_screen("close_btn_freeze"), class = "fpa-path-btn"))
  } else if (isTRUE(b$intact)) {
    list(state = "done", label = fpa_screen("close_s_bud_ok_lab"), detail = fpa_screen("close_s_bud_ok", fpa_shiny_when(b$frozen_at)))
  } else {
    rev_c <- b$table$current[b$table$line_id == "REV"]
    rev_f <- b$table$frozen[b$table$line_id == "REV"]
    rev_d <- b$table$delta[b$table$line_id == "REV"]
    one <- function(x) if (length(x)) x[[1]] else NA_real_
    list(state = "now", label = fpa_screen("close_s_bud_moved_lab"),
         detail = fpa_screen(
           "close_s_bud_moved", fpa_shiny_when(b$frozen_at),
           fpa_var_eur(one(rev_c)), fpa_var_eur(one(rev_f)), fpa_var_eur_s(one(rev_d))
         ),
         action = shiny::tags$div(
           class = "fpa-close-step-act",
           shiny::actionButton("close_freeze_btn", fpa_screen("close_btn_refreeze"), class = "fpa-path-btn"),
           btn(fpa_screen("close_btn_see"), open_fold("close-budget"))
         ))
  }
  Filter(Negate(is.null), steps)
}

fpa_close_steps_fact <- function(st, steps) {
  if (is.null(st) || !length(steps)) return(fpa_screen("close_fact_wait"))
  gate <- Filter(function(s) !identical(s$state, "info"), steps)
  done <- sum(vapply(gate, function(s) identical(s$state, "done"), logical(1)))
  left <- Filter(function(s) identical(s$state, "now"), gate)
  ml <- fpa_close_mlong(st$closed)
  if (!length(left)) return(fpa_screen("close_fact_ready", ml, length(gate)))
  fpa_screen("close_fact_left", ml, done, length(gate),
          paste(vapply(left, function(s) fpa_close_lc(s$label), character(1)), collapse = ", "))
}

fpa_close_steps_ui <- function(st, steps) {
  if (is.null(st)) return(shiny::tags$p(class = "fpa-var-note", fpa_screen("close_fact_wait")))
  gate <- Filter(function(s) !identical(s$state, "info"), steps)
  done <- sum(vapply(gate, function(s) identical(s$state, "done"), logical(1)))
  pct <- if (length(gate)) round(100 * done / length(gate)) else 0
  shiny::tagList(
    shiny::tags$div(
      class = "fpa-close-prog",
      shiny::tags$div(class = "fpa-path-bar", shiny::tags$span(style = sprintf("width:%d%%;", as.integer(pct)))),
      shiny::tags$span(fpa_screen("close_prog", done, length(gate)))
    ),
    shiny::tags$ol(
      class = "fpa-close-steps",
      lapply(steps, function(s) {
        mark <- switch(s$state, done = fpa_shiny_check_svg(14), now = "!", "i")
        word <- switch(s$state, done = fpa_screen("close_state_done"), now = fpa_screen("close_state_now"), fpa_screen("close_state_info"))
        shiny::tags$li(
          class = paste("fpa-close-step", paste0("is-", s$state)),
          shiny::tags$span(class = "fpa-close-mark", title = word, `aria-label` = word, mark),
          shiny::tags$div(
            class = "fpa-close-step-body",
            shiny::tags$span(class = "fpa-close-step-label", s$label),
            shiny::tags$span(class = "fpa-close-step-detail", s$detail)
          ),
          if (!is.null(s$action)) shiny::tags$div(class = "fpa-close-step-act", s$action)
        )
      })
    )
  )
}

#' Versions grouped by runs of identical files, newest first.
fpa_close_groups <- function(versions) {
  if (is.null(versions) || !nrow(versions)) return(list())
  run <- cumsum(!versions$same_as_prev)
  out <- lapply(unique(run), function(r) {
    idx <- which(run == r)
    last <- idx[[length(idx)]]
    list(
      id = versions$id[[last]], idx = last, n = length(idx),
      first_at = versions$saved_at[[idx[[1]]]], row = versions[last, , drop = FALSE]
    )
  })
  rev(out)
}

fpa_close_ver_label <- function(versions, id) {
  if (identical(id, "current")) return(fpa_screen("close_cur"))
  i <- match(id, versions$id)
  if (is.na(i)) return(id)
  lab <- as.character(versions$label[[i]])
  w <- fpa_shiny_when(versions$saved_at[[i]])
  if (nzchar(lab)) paste0(w, " · ", lab) else w
}

fpa_close_ver_ref <- function(versions, id) {
  if (identical(id, "current")) return(fpa_screen("close_ref_cur"))
  i <- match(id, versions$id)
  if (is.na(i)) return(id)
  fpa_screen("close_ref_ver", fpa_shiny_when(versions$saved_at[[i]]))
}

fpa_close_pick_choices <- function(st) {
  g <- fpa_close_groups(st$versions)
  labs <- vapply(g, function(x) {
    base <- fpa_close_ver_label(st$versions, x$id)
    if (x$n == 2L) paste0(base, " ", fpa_screen("close_copy_short")) else if (x$n > 2L) paste0(base, " ", fpa_screen("close_copies_short", x$n - 1L)) else base
  }, character(1))
  ids <- vapply(g, function(x) x$id, character(1))
  if (is.null(st$saved)) {
    ids <- c("current", ids)
    labs <- c(fpa_screen("close_cur_unsaved"), labs)
  }
  stats::setNames(ids, labs)
}

fpa_close_picks_ui <- function(st, a, b) {
  ch <- fpa_close_pick_choices(st)
  if (length(ch) < 2L) return(shiny::tags$p(class = "fpa-var-note", fpa_screen("close_cmp_need2")))
  if (!a %in% ch) a <- ch[[min(2L, length(ch))]]
  if (!b %in% ch) b <- ch[[1]]
  shiny::tags$div(
    class = "fpa-close-picks",
    shiny::selectInput("close_a", fpa_screen("close_vintage_from"), choices = ch, selected = a, width = "480px", selectize = FALSE),
    shiny::tags$span(class = "fpa-close-arrow", `aria-hidden` = "true", shiny::HTML("&rarr;")),
    shiny::selectInput("close_b", fpa_screen("close_vintage_to"), choices = ch, selected = b, width = "480px", selectize = FALSE)
  )
}

#' Period words for a comparison: the plan year, or the months both versions share.
fpa_close_cmp_span <- function(cmp, year, n_all = NULL) {
  if (!is.null(cmp) && !is.null(n_all) && length(cmp$months) < n_all) {
    btw <- fpa_close_between(cmp$months)
    return(list(of = fpa_screen("close_span_of", length(cmp$months), btw), on = fpa_screen("close_span_on", length(cmp$months), btw), total = fpa_screen("close_total"), partial = TRUE))
  }
  list(of = year, on = year, total = fpa_screen("close_col_total", year), partial = FALSE)
}

fpa_close_cmp_fact <- function(cmp, ref_a, ref_b, year, n_all = NULL) {
  if (is.null(cmp)) return(fpa_screen("close_cmp_none"))
  sp <- fpa_close_cmp_span(cmp, year, n_all)
  if (!length(cmp$moved)) return(fpa_screen("close_cmp_same", ref_a, ref_b, sp$on))
  tot <- rowSums(cmp$impact)
  op <- tot[names(tot) %in% fpa_close_op_lines()]
  top <- if (length(op) && any(abs(op) >= 0.5)) names(op)[[which.max(abs(op))]] else ""
  base <- fpa_screen("close_cmp_fact", ref_a, ref_b, sp$of, fpa_var_eur(cmp$oi_a), fpa_var_eur(cmp$oi_b), fpa_var_eur_s(cmp$oi_b - cmp$oi_a))
  if (nzchar(top)) paste(base, fpa_screen("close_cmp_top", fpa_shiny_line_name(top), fpa_var_eur_s(op[[top]]))) else base
}

#' Departure OI, one step per operating line, arrival OI. Totals start at zero.
fpa_close_bridge_frame <- function(cmp, lab_a = "", lab_b = "") {
  if (is.null(cmp)) return(NULL)
  tot <- rowSums(cmp$impact)
  op <- tot[names(tot) %in% fpa_close_op_lines()]
  op <- op[abs(op) >= 0.5]
  lab <- c(fpa_screen("close_br_from"), vapply(names(op), fpa_shiny_line_name, character(1)), fpa_screen("close_br_to"))
  raw <- c(cmp$oi_a, unname(op), cmp$oi_b)
  kind <- c("total", rep("step", length(op)), "total")
  start <- numeric(length(raw))
  end <- numeric(length(raw))
  run <- cmp$oi_a
  for (i in seq_along(raw)) {
    if (kind[[i]] == "total") {
      end[[i]] <- raw[[i]]
    } else {
      start[[i]] <- run
      end[[i]] <- run + raw[[i]]
      run <- end[[i]]
    }
  }
  data.frame(
    label = lab, kind = kind, raw = raw, signed = raw, start = start, end = end,
    tip = c(lab_a, rep("", length(op)), lab_b), stringsAsFactors = FALSE
  )
}

fpa_close_num_td <- function(v, total = FALSE) {
  cls <- c(if (is.finite(v) && round(v) < 0) "is-neg", if (!is.finite(v) || abs(v) < 0.5) "is-zero")
  shiny::tags$td(class = paste(cls, collapse = " "), if (!is.finite(v) || abs(v) < 0.5) "\u2013" else if (total) fpa_var_eur(v) else fpa_var_eur_s(v))
}

fpa_close_cmp_table <- function(cmp, act = character(0), year = "", n_all = NULL) {
  if (is.null(cmp) || !length(cmp$moved)) return(NULL)
  sp <- fpa_close_cmp_span(cmp, year, n_all)
  shown <- cmp$moved
  hidden_m <- setdiff(cmp$months, shown)
  tot <- rowSums(cmp$impact)
  live <- names(tot)[rowSums(abs(cmp$impact) >= 0.5) > 0]
  op <- intersect(fpa_close_op_lines(), live)
  below <- intersect(fpa_close_below_lines(), live)
  hidden_l <- setdiff(cmp$lines, live)
  row <- function(name, vals, total, cls = NULL) {
    shiny::tags$tr(
      class = cls,
      shiny::tags$th(scope = "row", name),
      lapply(vals, fpa_close_num_td),
      fpa_close_num_td(total)
    )
  }
  oi_m <- stats::setNames(cmp$oi, cmp$months)
  ni_m <- stats::setNames(cmp$ni, cmp$months)
  shiny::tags$div(
    class = "fpa-close-tbl-wrap",
    shiny::tags$table(
      class = "fpa-close-tbl",
      shiny::tags$thead(shiny::tags$tr(
        shiny::tags$th(fpa_screen("close_col_line")),
        lapply(shown, function(m) shiny::tags$th(
          class = if (m %in% act) "is-act" else "is-fc",
          fpa_var_month_abbr(m, with_year = TRUE),
          shiny::tags$small(if (m %in% act) fpa_screen("close_col_act") else fpa_screen("close_col_fc"))
        )),
        shiny::tags$th(sp$total)
      )),
      shiny::tags$tbody(
        lapply(op, function(l) row(fpa_shiny_line_name(l), cmp$impact[l, shown], tot[[l]])),
        row(fpa_shiny_line_name("OI"), oi_m[shown], sum(cmp$oi), "is-total"),
        lapply(below, function(l) row(fpa_shiny_line_name(l), cmp$impact[l, shown], tot[[l]])),
        if (length(below)) row(fpa_shiny_line_name("NI"), ni_m[shown], sum(cmp$ni), "is-total") else NULL
      )
    ),
    shiny::tags$p(
      class = "fpa-var-note",
      fpa_screen("close_cmp_cap"),
      if (sp$partial) paste0(" ", fpa_screen("close_cmp_partial", sp$on)) else "",
      if (length(hidden_m)) paste0(" ", fpa_screen("close_hidden_m", fpa_close_between(hidden_m))) else "",
      if (length(hidden_l)) paste0(" ", fpa_screen("close_hidden_l", paste(vapply(hidden_l, fpa_shiny_line_name, character(1)), collapse = ", "))) else ""
    )
  )
}

fpa_close_cmp_csv <- function(cmp) {
  if (is.null(cmp)) return(data.frame())
  lines <- c(fpa_close_op_lines(), "OI", fpa_close_below_lines(), "NI")
  rows <- lapply(lines, function(l) {
    v <- if (l == "OI") cmp$oi else if (l == "NI") cmp$ni else if (l %in% rownames(cmp$impact)) cmp$impact[l, ] else NULL
    if (is.null(v)) return(NULL)
    out <- as.list(round(v, 2))
    names(out) <- cmp$months
    data.frame(Ligne = fpa_shiny_line_name(l), out, Total = round(sum(v), 2), check.names = FALSE, stringsAsFactors = FALSE)
  })
  do.call(rbind, Filter(Negate(is.null), rows))
}

fpa_close_reg_fact <- function(st) {
  v <- st$versions
  if (is.null(v) || !nrow(v)) return(fpa_screen("close_reg_none"))
  g <- fpa_close_groups(v)
  base <- fpa_screen("close_reg_fact", nrow(v), length(g), fpa_shiny_when(utils::tail(v$saved_at, 1)))
  if (is.null(st$saved)) paste(base, fpa_screen("close_reg_unsaved")) else base
}

fpa_close_register_ui <- function(st) {
  v <- st$versions
  if (is.null(v) || !nrow(v)) return(shiny::tags$p(class = "fpa-var-note", fpa_screen("close_reg_none")))
  g <- fpa_close_groups(v)
  n_all <- length(st$months)
  pick <- function(id) sprintf("Shiny.setInputValue('close_pick',{a:'%s',n:Date.now()},{priority:'event'})", id)
  prev_oi <- function(k) if (k < length(g)) g[[k + 1L]]$row$oi[[1]] else NA_real_
  cells <- function(r, gap) shiny::tagList(
    fpa_close_num_td(r$rev, TRUE), fpa_close_num_td(r$oi, TRUE), fpa_close_num_td(r$ni, TRUE),
    fpa_close_num_td(r$cash_end, TRUE), fpa_close_num_td(gap)
  )
  cur_row <- if (is.null(st$saved)) {
    r <- st$current
    gap <- if (length(g)) r$oi - g[[1]]$row$oi[[1]] else NA_real_
    shiny::tags$tr(
      class = "is-cur",
      shiny::tags$th(scope = "row", fpa_screen("close_cur")),
      shiny::tags$td(class = "is-txt", fpa_screen("close_cur_note")),
      cells(r, gap),
      shiny::tags$td(class = "is-txt", "")
    )
  } else NULL
  shiny::tags$div(
    class = "fpa-close-tbl-wrap",
    shiny::tags$table(
      class = "fpa-close-tbl fpa-close-reg",
      shiny::tags$thead(shiny::tags$tr(
        shiny::tags$th(fpa_screen("close_reg_when")),
        shiny::tags$th(class = "is-txt", fpa_screen("close_reg_label")),
        shiny::tags$th(fpa_screen("close_reg_rev", st$year)),
        shiny::tags$th(fpa_screen("close_reg_oi")),
        shiny::tags$th(fpa_screen("close_reg_ni")),
        shiny::tags$th(fpa_screen("close_reg_cash")),
        shiny::tags$th(fpa_screen("close_reg_gap")),
        shiny::tags$th(class = "is-txt", "")
      )),
      shiny::tags$tbody(
        cur_row,
        lapply(seq_along(g), function(k) {
          x <- g[[k]]
          r <- x$row
          is_cur <- !is.null(st$saved) && identical(r$md5[[1]], st$cur_md5)
          notes <- c(
            if (x$n == 2L) fpa_screen("close_copy", fpa_shiny_when(x$first_at)),
            if (x$n > 2L) fpa_screen("close_copies", x$n - 1L, fpa_shiny_when(x$first_at)),
            if (r$n_months[[1]] < n_all) fpa_screen("close_reg_part", r$n_months[[1]], n_all),
            if (is_cur) fpa_screen("close_reg_is_cur")
          )
          shiny::tags$tr(
            class = if (is_cur) "is-cur" else NULL,
            shiny::tags$th(scope = "row", fpa_shiny_when(r$saved_at[[1]]),
              if (length(notes)) shiny::tags$small(paste(notes, collapse = " · ")) else NULL),
            shiny::tags$td(class = "is-txt", if (nzchar(r$label[[1]])) r$label[[1]] else "\u2013"),
            cells(list(rev = r$rev[[1]], oi = r$oi[[1]], ni = r$ni[[1]], cash_end = r$cash_end[[1]]), r$oi[[1]] - prev_oi(k)),
            shiny::tags$td(class = "is-txt", if (!is_cur) shiny::tags$button(
              type = "button", class = "fpa-path-btn is-quiet fpa-close-mini", onclick = pick(x$id), fpa_screen("close_btn_cmp")
            ) else NULL)
          )
        })
      )
    ),
    shiny::tags$p(class = "fpa-var-note", fpa_screen("close_reg_cap", st$year))
  )
}

fpa_close_lock_fact <- function(st, drift) {
  if (is.null(st)) return(fpa_screen("close_fact_wait"))
  lm <- st$lock_months
  base <- if (!length(lm)) fpa_screen("close_lock_none") else fpa_screen("close_lock_fact", length(lm), fpa_close_between(lm))
  d <- fpa_close_drift_months(st, drift)
  extra <- c(
    if (length(st$unlocked) == 1L) fpa_screen("close_lock_open", fpa_close_uc(fpa_close_mlong(st$unlocked))),
    if (length(st$unlocked) > 1L) fpa_screen("close_lock_open_n", length(st$unlocked), fpa_close_between(st$unlocked)),
    if (nrow(d)) fpa_screen("close_lock_drift_fact", nrow(d))
  )
  paste(c(base, extra), collapse = " ")
}

fpa_close_lock_ui <- function(st, drift, nature = character(0), show_op_fin = FALSE) {
  if (is.null(st)) return(NULL)
  d <- fpa_close_drift_months(st, drift)
  outside <- setdiff(st$lock_months, st$months)
  drift_block <- if (is.null(drift)) {
    shiny::tags$p(class = "fpa-var-note", fpa_screen("close_drift_wait"))
  } else if (nrow(d)) {
    shiny::tags$div(
      class = "fpa-close-alert",
      shiny::tags$p(shiny::tags$strong(fpa_screen("close_drift_head", nrow(d))), " ", fpa_screen("close_drift_lead")),
      shiny::tags$div(
        class = "fpa-close-tbl-wrap",
        shiny::tags$table(
          class = "fpa-close-tbl",
          shiny::tags$thead(shiny::tags$tr(
            shiny::tags$th(fpa_screen("close_col_month")),
            shiny::tags$th(fpa_screen("close_drift_lines")),
            shiny::tags$th(fpa_screen("close_drift_rev_lock")),
            shiny::tags$th(fpa_screen("close_drift_rev_file")),
            shiny::tags$th(fpa_screen("close_drift_oi_lock")),
            shiny::tags$th(fpa_screen("close_drift_oi_file")),
            shiny::tags$th(fpa_screen("close_drift_oi_gap"))
          )),
          shiny::tags$tbody(
            lapply(seq_len(nrow(d)), function(i) shiny::tags$tr(
              shiny::tags$th(scope = "row", fpa_close_mlong(d$periode[[i]])),
              shiny::tags$td(d$n_lines[[i]]),
              fpa_close_num_td(d$rev_lock[[i]], TRUE), fpa_close_num_td(d$rev_file[[i]], TRUE),
              fpa_close_num_td(d$oi_lock[[i]], TRUE), fpa_close_num_td(d$oi_file[[i]], TRUE),
              fpa_close_num_td(d$oi_gap[[i]])
            )),
            shiny::tags$tr(
              class = "is-total",
              shiny::tags$th(scope = "row", fpa_screen("close_total")),
              shiny::tags$td(sum(d$n_lines)),
              fpa_close_num_td(sum(d$rev_lock), TRUE), fpa_close_num_td(sum(d$rev_file), TRUE),
              fpa_close_num_td(sum(d$oi_lock), TRUE), fpa_close_num_td(sum(d$oi_file), TRUE),
              fpa_close_num_td(sum(d$oi_gap))
            )
          )
        )
      ),
      shiny::tags$div(
        class = "fpa-close-acts",
        shiny::actionButton("close_drift_btn", fpa_screen("close_btn_drift"), class = "fpa-path-btn"),
        shiny::tags$span(class = "fpa-var-note", fpa_screen("close_drift_keep"))
      )
    )
  } else if (length(st$lock_months)) {
    shiny::tags$p(class = "fpa-close-ok", fpa_shiny_check_svg(14), fpa_screen("close_drift_ok", length(intersect(st$lock_months, st$months))))
  } else NULL
  shiny::tagList(
    drift_block,
    if (length(st$unlocked)) shiny::tags$div(
      class = "fpa-close-acts",
      shiny::actionButton(
        "close_lock_btn2",
        if (length(st$unlocked) == 1L) fpa_screen("close_s_lock_one", fpa_close_mlong(st$unlocked)) else fpa_screen("close_btn_lock_n", fpa_close_between(st$unlocked)),
        class = "fpa-path-btn"
      ),
      shiny::tags$span(class = "fpa-var-note", fpa_screen("close_lock_what"))
    ) else NULL,
    if (nrow(st$lock)) {
      in_calc <- st$lock[as.character(st$lock$periode) %in% st$months, , drop = FALSE]
      shiny::tagList(
        shiny::tags$h4(class = "fpa-close-h4", if (nrow(in_calc)) fpa_screen("close_lock_grid_calc") else fpa_screen("close_lock_grid")),
        fpa_shiny_lock_grid(if (nrow(in_calc)) in_calc else st$lock, nature = nature, show_op_fin = show_op_fin)
      )
    } else NULL,
    if (length(outside)) shiny::tags$p(class = "fpa-var-note", fpa_screen("close_lock_outside", length(outside), fpa_close_between(outside))) else NULL
  )
}

fpa_close_budget_oi <- function(tab, col) {
  sl <- tab[tab$line_id %in% fpa_close_op_lines(), , drop = FALSE]
  if (!nrow(sl)) return(NA_real_)
  sum(vapply(seq_len(nrow(sl)), function(i) fpa_pnl_ni_sign(sl$line_id[[i]]) * sl[[col]][[i]], numeric(1)), na.rm = TRUE)
}

fpa_close_budget_fact <- function(b) {
  if (is.null(b) || !isTRUE(b$frozen)) return(fpa_screen("close_bud_none"))
  rev <- b$table$frozen[b$table$line_id == "REV"]
  oi <- fpa_close_budget_oi(b$table, "frozen")
  if (isTRUE(b$intact)) {
    return(fpa_screen("close_bud_fact_ok", fpa_shiny_when(b$frozen_at), fpa_var_eur(if (length(rev)) rev[[1]] else NA), fpa_var_eur(oi)))
  }
  fpa_screen("close_bud_fact_moved", fpa_shiny_when(b$frozen_at), fpa_var_eur_s(fpa_close_budget_oi(b$table, "current") - oi))
}

fpa_close_budget_ui <- function(b) {
  if (is.null(b)) return(NULL)
  if (!isTRUE(b$frozen)) {
    return(shiny::tags$div(
      class = "fpa-close-acts",
      shiny::actionButton("close_freeze_btn2", fpa_screen("close_btn_freeze"), class = "fpa-path-btn"),
      shiny::tags$span(class = "fpa-var-note", fpa_screen("close_bud_what"))
    ))
  }
  tab <- b$table
  show_gap <- !isTRUE(b$intact) && any(is.finite(tab$delta) & abs(tab$delta) >= 0.5)
  oi_f <- fpa_close_budget_oi(tab, "frozen")
  oi_c <- fpa_close_budget_oi(tab, "current")
  bud_row <- function(i) shiny::tags$tr(
    shiny::tags$th(scope = "row", fpa_shiny_line_name(tab$line_id[[i]])),
    fpa_close_num_td(tab$frozen[[i]], TRUE), fpa_close_num_td(tab$current[[i]], TRUE),
    if (show_gap) fpa_close_num_td(tab$delta[[i]]) else NULL
  )
  shiny::tagList(
    shiny::tags$div(
      class = "fpa-close-tbl-wrap",
      shiny::tags$table(
        class = "fpa-close-tbl fpa-close-bud",
        shiny::tags$thead(shiny::tags$tr(
          shiny::tags$th(fpa_screen("close_col_line")),
          shiny::tags$th(fpa_screen("close_bud_frozen")),
          shiny::tags$th(fpa_screen("close_bud_current")),
          if (show_gap) shiny::tags$th(fpa_screen("close_bud_gap")) else NULL
        )),
        shiny::tags$tbody(
          lapply(which(tab$line_id %in% fpa_close_op_lines()), bud_row),
          shiny::tags$tr(
            class = "is-total",
            shiny::tags$th(scope = "row", fpa_shiny_line_name("OI")),
            fpa_close_num_td(oi_f, TRUE), fpa_close_num_td(oi_c, TRUE),
            if (show_gap) fpa_close_num_td(oi_c - oi_f) else NULL
          ),
          lapply(which(!tab$line_id %in% fpa_close_op_lines()), bud_row)
        )
      )
    ),
    shiny::tags$p(class = "fpa-var-note", if (show_gap) fpa_screen("close_bud_cap_moved") else fpa_screen("close_bud_cap_ok")),
    shiny::tags$div(
      class = "fpa-close-acts",
      shiny::actionButton("close_freeze_btn2", fpa_screen("close_btn_refreeze"), class = "fpa-path-btn is-quiet"),
      shiny::tags$span(class = "fpa-var-note", fpa_screen("close_bud_refreeze_what"))
    )
  )
}

fpa_shiny_plain_table <- function(df) {
  if (is.null(df) || !is.data.frame(df) || !nrow(df)) {
    return(shiny::tags$p(fpa_screen("loc_nothing_in_config")))
  }
  shiny::tags$div(
    style = "overflow-x:auto;margin-bottom:1.2rem;",
    shiny::tags$table(
      class = "table table-sm table-striped",
      style = "font-size:0.9rem;",
      shiny::tags$thead(
        shiny::tags$tr(lapply(names(df), function(n) shiny::tags$th(n)))
      ),
      shiny::tags$tbody(lapply(seq_len(nrow(df)), function(i) {
        shiny::tags$tr(lapply(as.character(df[i, ]), function(cell) shiny::tags$td(cell)))
      }))
    )
  )
}

fpa_shiny_source_path <- function(config, source) {
  sid <- as.character(source$source_id %||% "")
  extras <- config$extra_files %||% list()
  if (length(extras)) {
    for (ex in extras) {
      if (!identical(as.character(ex$source_id %||% ""), sid)) next
      p <- as.character(ex$path %||% "")
      if (nzchar(p)) return(p)
    }
  }
  role <- as.character(source$file_role %||% "")
  paths <- config$paths %||% list()
  as.character(paths[[role]] %||% "")
}

fpa_shiny_map_identity <- function(config) {
  co <- config$company %||% list()
  data.frame(
    Champ = c(fpa_screen("loc_company"), "Secteur", "Devise", fpa_screen("loc_close_month_label"), "Horizon", "Version"),
    Valeur = c(
      as.character(co$name %||% ""),
      as.character(co$industry_tag %||% ""),
      as.character(co$currency %||% ""),
      as.character(co$fiscal_year_end_month %||% ""),
      as.character(config$horizon_months %||% ""),
      as.character(config$config_version %||% "")
    ),
    stringsAsFactors = FALSE
  )
}

fpa_shiny_map_files <- function(config) {
  srcs <- config$sources %||% list()
  if (!length(srcs)) return(data.frame())
  rows <- lapply(srcs, function(s) {
    path <- fpa_shiny_source_path(config, s)
    data.frame(
      Source = as.character(s$source_name %||% s$source_id %||% ""),
      Role = as.character(s$file_role %||% ""),
      Fichier = if (nzchar(path)) basename(path) else "",
      Present = if (nzchar(path) && file.exists(path)) "oui" else "non",
      Grain = as.character(s$grain %||% ""),
      Disposition = as.character(s$file_layout %||% ""),
      Nature = as.character(s$incoming_kind %||% ""),
      Etat = as.character(s$state %||% ""),
      stringsAsFactors = FALSE
    )
  })
  do.call(rbind, rows)
}

fpa_shiny_map_columns <- function(config) {
  srcs <- config$sources %||% list()
  rows <- list()
  for (s in srcs) {
    cm <- s$column_map %||% list()
    if (!length(cm)) next
    cp <- s$column_period %||% list()
    headers <- names(cm)
    for (h in headers) {
      rows[[length(rows) + 1L]] <- data.frame(
        Source = as.character(s$source_name %||% ""),
        Colonne_fichier = h,
        Role_moteur = as.character(cm[[h]] %||% ""),
        Periode = as.character(cp[[h]] %||% ""),
        stringsAsFactors = FALSE
      )
    }
  }
  if (!length(rows)) return(data.frame())
  do.call(rbind, rows)
}

fpa_shiny_map_unmapped <- function(config) {
  srcs <- config$sources %||% list()
  bits <- character(0)
  for (s in srcs) {
    declared <- as.character(unlist(s$headers_declared %||% list()))
    mapped <- names(s$column_map %||% list())
    missing <- setdiff(declared, mapped)
    if (!length(missing)) next
    bits <- c(bits, paste0(
      as.character(s$source_name %||% ""), ": ",
      paste(missing, collapse = ", ")
    ))
  }
  bits
}

fpa_shiny_named_map <- function(mp, statement) {
  if (is.null(mp) || !length(mp)) return(data.frame())
  data.frame(
    Etat = statement,
    Libelle_fichier = names(mp),
    Ligne_moteur = as.character(unlist(mp, use.names = FALSE)),
    stringsAsFactors = FALSE
  )
}

fpa_shiny_map_lines <- function(config) {
  parts <- list(
    fpa_shiny_named_map(config$line_map, "Compte de résultat"),
    fpa_shiny_named_map(config$line_map_bs, "Bilan"),
    fpa_shiny_named_map(config$line_map_budget, "Budget")
  )
  parts <- parts[vapply(parts, nrow, integer(1)) > 0]
  if (!length(parts)) return(data.frame())
  do.call(rbind, parts)
}

fpa_shiny_map_drivers <- function(config) {
  binds <- config$driver_bindings %||% list()
  if (!length(binds)) return(data.frame())
  rows <- lapply(binds, function(b) {
    data.frame(
      Serie = as.character(b$series_id %||% ""),
      Ligne = as.character(b$target_line %||% ""),
      Bas = as.character(b$low_factor %||% ""),
      Haut = as.character(b$high_factor %||% ""),
      Motif = as.character(b$reason %||% ""),
      stringsAsFactors = FALSE
    )
  })
  do.call(rbind, rows)
}

fpa_shiny_branch <- function(title, ..., open = FALSE) {
  shiny::tags$details(
    style = "margin:0.35rem 0 0.35rem 0.15rem;padding-left:0.75rem;border-left:3px solid #1f4e5f;",
    open = if (isTRUE(open)) NA else NULL,
    shiny::tags$summary(
      style = "cursor:pointer;font-weight:600;margin-bottom:0.35rem;",
      title
    ),
    ...
  )
}

fpa_shiny_catchup_where <- function(path) {
  if (!nzchar(path %||% "")) return(NULL)
  shown <- tryCatch(normalizePath(path, winslash = "\\", mustWork = FALSE), error = function(e) path)
  shiny::tagList(
    shiny::tags$p(class = "fpa-cu-where", fpa_screen("catchup_path")),
    shiny::tags$p(class = "fpa-cu-path", shown)
  )
}

fpa_shiny_catchup_modal <- function(sheet) {
  title <- if (nzchar(sheet$title %||% "")) sheet$title else fpa_screen("catchup_series")
  if (!isTRUE(sheet$ok)) {
    reason <- if (identical(sheet$reason, "excel")) fpa_screen("catchup_excel") else fpa_screen("catchup_unavailable")
    return(shiny::modalDialog(
      title = title,
      shiny::tags$p(reason),
      easyClose = TRUE,
      footer = shiny::modalButton(fpa_screen("catchup_close"))
    ))
  }
  hist <- as.character(sheet$hist)
  head_row <- shiny::tags$tr(
    shiny::tags$th(fpa_screen("catchup_series")),
    lapply(hist, function(h) shiny::tags$th(class = "num", h)),
    shiny::tags$th(class = "num", paste(sheet$needed, fpa_screen("catchup_enter")))
  )
  body <- lapply(seq_len(nrow(sheet$rows)), function(i) {
    row <- sheet$rows[i, , drop = FALSE]
    shiny::tags$tr(
      shiny::tags$td(row$label),
      if (length(hist) >= 1L) shiny::tags$td(class = "num", row$h1),
      if (length(hist) >= 2L) shiny::tags$td(class = "num", row$h2),
      shiny::tags$td(class = "entry", shiny::textInput(paste0("cu_", row$id), NULL, value = "", width = "120px"))
    )
  })
  shiny::modalDialog(
    title = title,
    easyClose = TRUE,
    size = "l",
    shiny::tags$style(HTML("
      .fpa-cu { width:auto; border-collapse:collapse; font-size:13px; }
      .fpa-cu th { text-align:left; background:#1f4e5f; color:#fff; padding:8px 10px; font-weight:600; white-space:nowrap; }
      .fpa-cu td { padding:6px 10px; border-bottom:1px solid #e6edef; vertical-align:middle; }
      .fpa-cu th.num, .fpa-cu td.num { text-align:right; font-variant-numeric:tabular-nums; padding-left:28px; }
      .fpa-cu td.entry { text-align:right; }
      .fpa-cu td.entry .form-group, .fpa-cu td.entry .shiny-input-container { width:120px; margin:0 0 0 auto; }
      .fpa-cu td.entry input { text-align:right; font-variant-numeric:tabular-nums; }
      .fpa-cu .form-group, .fpa-cu .shiny-input-container { margin:0; }
      .fpa-cu-where { margin:0 0 0.2rem; font-size:13.5px; color:#1a2b32; }
      .fpa-cu-path { margin:0 0 0.7rem; font-size:13px; line-height:1.4; color:#0f2f3a; font-weight:700; overflow-wrap:anywhere; }
      .modal-footer .btn-primary { background:#1f4e5f; border-color:#1f4e5f; border-radius:8px; }
      .modal-footer .btn-primary:hover { background:#163844; }
    ")),
    shiny::tags$p(fpa_screen("catchup_lead")),
    fpa_shiny_catchup_where(sheet$path),
    if (length(hist) < 2L) shiny::tags$p(fpa_screen("catchup_one")),
    if (identical(sheet$layout, "yearcol")) shiny::tags$p(fpa_screen("catchup_year")),
    shiny::tags$div(
      style = "max-height:60vh; overflow:auto;",
      shiny::tags$table(
        class = "fpa-cu",
        shiny::tags$thead(head_row),
        shiny::tags$tbody(body)
      )
    ),
    footer = shiny::tagList(
      shiny::actionButton("catchup_save", fpa_screen("catchup_save"), class = "btn-primary"),
      shiny::modalButton(fpa_screen("catchup_close"))
    )
  )
}

fpa_shiny_listed_path <- function(p, rel) {
  rel <- gsub("\\\\", "/", trimws(as.character(rel %||% "")))
  if (!nzchar(rel) || !isTRUE(p$ok)) return("")
  if (grepl("^[A-Za-z]:[/\\\\]", rel) || startsWith(rel, "/")) {
    return(if (file.exists(rel)) rel else "")
  }
  if (identical(tolower(basename(rel)), "cash-outlook.json")) return(fpa_outlook_path(p$config))
  if (startsWith(tolower(rel), "input/") && nzchar(p$paths$input %||% "")) {
    return(file.path(p$paths$input, substring(rel, 7L)))
  }
  if (startsWith(tolower(rel), "work/") && nzchar(p$paths$work %||% "")) {
    return(file.path(p$paths$work, substring(rel, 6L)))
  }
  file.path(p$paths$working %||% dirname(p$config_path %||% ""), rel)
}

fpa_shiny_under_input <- function(p, path) {
  root <- as.character(p$paths$input %||% "")
  if (!nzchar(root) || !nzchar(path)) return(FALSE)
  root_n <- paste0(gsub("/+$", "", gsub("\\\\", "/", root)), "/")
  full <- paste0(gsub("\\\\", "/", path), "/")
  startsWith(tolower(full), tolower(root_n))
}

fpa_shiny_preview_table <- function(df, cap = 200L) {
  if (is.null(df) || !ncol(df) || !nrow(df)) return(shiny::tags$p(fpa_screen("kpi_file_empty")))
  shown <- if (nrow(df) > cap) df[seq_len(cap), , drop = FALSE] else df
  shiny::tags$div(
    style = "max-height:60vh; overflow:auto;",
    shiny::tags$table(
      class = "fpa-file-edit",
      shiny::tags$thead(shiny::tags$tr(lapply(names(shown), shiny::tags$th))),
      shiny::tags$tbody(lapply(seq_len(nrow(shown)), function(i) {
        shiny::tags$tr(lapply(names(shown), function(nm) {
          v <- shown[[nm]][[i]]
          label <- if (length(v) != 1L || is.na(v)) "" else as.character(v)
          shiny::tags$td(class = if (is.numeric(shown[[nm]])) "num" else NULL, label)
        }))
      }))
    )
  )
}

fpa_shiny_kpi_back <- function(kpi_back) {
  if (!nzchar(kpi_back %||% "")) return(NULL)
  shiny::tags$button(
    type = "button",
    class = "fpa-go-btn",
    onclick = sprintf(
      "Shiny.setInputValue('kpi_reopen',{id:%s},{priority:'event'})",
      jsonlite::toJSON(kpi_back, auto_unbox = TRUE)
    ),
    fpa_screen("kpi_file_back")
  )
}

fpa_shiny_file_edit_modal <- function(sheet, periode = "", saved = "", kind = "pnl", line = "", kpi_back = "") {
  kind <- if (as.character(kind %||% "") %in% c("pnl", "cash", "bs")) as.character(kind) else "pnl"
  line <- gsub("[^A-Za-z0-9_]", "", as.character(line %||% ""))
  back <- if (nzchar(kpi_back)) {
    fpa_shiny_kpi_back(kpi_back)
  } else if (grepl("^[0-9]{4}-[0-9]{2}$", as.character(periode))) {
    shiny::tags$button(
      type = "button",
      style = "background:#fff;color:#1f4e5f;border:1px solid #1f4e5f;border-radius:8px;font-weight:600;padding:6px 14px;",
      onclick = sprintf(
        "Shiny.setInputValue('stmt_read',{stmt:'%s',periode:'%s',line:'%s'},{priority:'event'})",
        kind, periode, line
      ),
      fpa_screen("oi_file_back")
    )
  }
  close_btn <- shiny::tags$button(
    type = "button",
    style = "background:#1f4e5f;color:#fff;border:1px solid #1f4e5f;border-radius:8px;font-weight:600;padding:6px 14px;",
    `data-dismiss` = "modal",
    `data-bs-dismiss` = "modal",
    fpa_screen("kpi_close")
  )
  if (!isTRUE(sheet$csv)) {
    preview <- shiny::tags$p(class = "fpa-file-lead", fpa_screen("oi_file_csv"))
    got <- if (nzchar(sheet$path %||% "") && file.exists(sheet$path)) {
      tryCatch(fpa_read_raw_file(sheet$path), error = function(e) NULL)
    } else {
      NULL
    }
    if (!is.null(got) && is.null(got$error) && !is.null(got$data) && nrow(got$data)) {
      df <- got$data
      cap <- 200L
      shown <- if (nrow(df) > cap) df[seq_len(cap), , drop = FALSE] else df
      preview <- shiny::tagList(
        preview,
        shiny::tags$div(
          style = "max-height:60vh; overflow:auto;",
          shiny::tags$table(
            class = "fpa-file-edit",
            shiny::tags$thead(shiny::tags$tr(lapply(names(shown), shiny::tags$th))),
            shiny::tags$tbody(lapply(seq_len(nrow(shown)), function(i) {
              shiny::tags$tr(lapply(names(shown), function(nm) {
                v <- shown[[nm]][[i]]
                label <- if (length(v) != 1L || is.na(v)) "" else as.character(v)
                shiny::tags$td(class = if (is.numeric(shown[[nm]])) "num" else NULL, label)
              }))
            }))
          )
        )
      )
    }
    return(shiny::modalDialog(
      title = sheet$name %||% "",
      easyClose = TRUE,
      size = "l",
      preview,
      footer = shiny::tagList(back, close_btn)
    ))
  }
  df <- sheet$df
  find_edit <- function(i, j) {
    for (e in sheet$edits) {
      if (identical(e$row, i) && identical(e$col, j)) return(e)
    }
    NULL
  }
  header <- shiny::tags$tr(lapply(names(df), function(nm) shiny::tags$th(nm)))
  body <- lapply(seq_len(nrow(df)), function(i) {
    shiny::tags$tr(
      class = if (isTRUE(sheet$open_row[[i]])) "is-open" else NULL,
      lapply(seq_along(df), function(j) {
        e <- find_edit(i, j)
        val <- df[[j]][[i]]
        label <- if (length(val) != 1L || is.na(val)) "" else as.character(val)
        if (!is.null(e)) {
          return(shiny::tags$td(
            class = "num",
            shiny::textInput(e$id, NULL, value = e$value)
          ))
        }
        shiny::tags$td(class = if (isTRUE(sheet$num_col[[j]])) "num" else NULL, label)
      })
    )
  })
  shiny::modalDialog(
    title = sheet$name,
    easyClose = TRUE,
    size = "xl",
    footer = shiny::tagList(
      back,
      if (length(sheet$edits)) shiny::actionButton(
        "fe_save", fpa_screen("oi_file_save"),
        style = "background:#1f4e5f;color:#fff;border:1px solid #1f4e5f;border-radius:8px;font-weight:600;"
      ),
      close_btn
    ),
    if (nzchar(saved)) shiny::tags$p(class = "fpa-file-lead", saved),
    shiny::tags$p(
      class = "fpa-file-lead",
      if (length(sheet$edits)) fpa_screen("oi_file_lead") else fpa_screen("oi_file_none")
    ),
    shiny::tags$div(
      style = "max-height:60vh; overflow:auto;",
      shiny::tags$table(class = "fpa-file-edit", shiny::tags$thead(header), shiny::tags$tbody(body))
    )
  )
}

fpa_shiny_file_view_modal <- function(title, lead, body, kpi_back = "") {
  close_btn <- shiny::tags$button(
    type = "button",
    class = "fpa-go-btn",
    `data-dismiss` = "modal",
    `data-bs-dismiss` = "modal",
    fpa_screen("kpi_close")
  )
  shiny::modalDialog(
    title = title,
    easyClose = TRUE,
    size = "l",
    footer = shiny::tagList(fpa_shiny_kpi_back(kpi_back), close_btn),
    shiny::tags$p(class = "fpa-file-lead", lead),
    body
  )
}

fpa_shiny_trace_modal <- function(spec) {
  rows <- spec$rows
  if (is.null(rows) || !nrow(rows)) {
    rows <- data.frame(
      item = spec$k %||% "", amount = spec$v %||% "", file = "",
      ligne = "", mois = "", sens = spec$s %||% "",
      stringsAsFactors = FALSE
    )
  }
  file_cell <- function(file) {
    file <- as.character(file %||% "")
    if (!length(file) || is.na(file[[1]]) || !nzchar(file[[1]])) return(NULL)
    file <- file[[1]]
    shiny::tags$button(
      type = "button",
      class = "fpa-kpi-file",
      title = fpa_screen("kpi_file_tip"),
      onclick = sprintf(
        "Shiny.setInputValue('kpi_file',{file:%s,back:%s},{priority:'event'})",
        jsonlite::toJSON(file, auto_unbox = TRUE),
        jsonlite::toJSON(spec$id %||% "", auto_unbox = TRUE)
      ),
      file
    )
  }
  is_ym <- function(x) grepl("^[0-9]{4}-[0-9]{2}$", as.character(x %||% ""))
  items <- as.character(rows$item %||% "")
  mois <- as.character(rows$mois %||% "")
  files <- as.character(rows$file %||% "")
  lignes <- as.character(rows$ligne %||% "")
  sens <- as.character(rows$sens %||% "")
  # Month detail rows: label is a YYYY-MM (often duplicated in mois).
  detail_i <- which(is_ym(items) | (is_ym(mois) & items == mois))
  summary_i <- setdiff(seq_len(nrow(rows)), detail_i)
  # Collapse only when a run of detail rows share file + line + meaning.
  collapse <- FALSE
  src_file <- ""
  src_line <- ""
  src_sens <- ""
  if (length(detail_i) >= 3L) {
    src_file <- unique(files[detail_i][nzchar(files[detail_i])])
    src_line <- unique(lignes[detail_i][nzchar(lignes[detail_i])])
    src_sens <- unique(sens[detail_i][nzchar(sens[detail_i])])
    collapse <- length(src_file) <= 1L && length(src_line) <= 1L && length(src_sens) <= 1L
    if (collapse) {
      src_file <- if (length(src_file)) src_file[[1]] else ""
      src_line <- if (length(src_line)) src_line[[1]] else ""
      src_sens <- if (length(src_sens)) src_sens[[1]] else ""
    }
  }
  go_tab <- as.character(spec$go_tab %||% "Impact")
  go_line <- as.character(spec$go_line %||% "")
  go_open <- as.character(spec$go_open %||% "")
  summary_i <- summary_i[vapply(summary_i, function(i) {
    amt <- as.character(rows$amount[[i]] %||% "")
    # Keep rows that carry an amount or a distinct watch note with empty amount.
    nzchar(amt) || grepl("signal", items[[i]], ignore.case = TRUE)
  }, logical(1))]
  # Drop watch-only rows with no amount: they add noise next to the tone line.
  summary_i <- summary_i[vapply(summary_i, function(i) {
    nzchar(as.character(rows$amount[[i]] %||% ""))
  }, logical(1))]
  summary_table <- if (length(summary_i)) {
    shiny::tags$table(
      class = "fpa-kpi-trace fpa-kpi-trace-sum",
      shiny::tags$thead(shiny::tags$tr(
        shiny::tags$th(fpa_screen("kpi_th_item")),
        shiny::tags$th(fpa_screen("kpi_th_amt")),
        shiny::tags$th(fpa_screen("kpi_th_rows"))
      )),
      shiny::tags$tbody(lapply(summary_i, function(i) {
        shiny::tags$tr(
          shiny::tags$td(items[[i]]),
          shiny::tags$td(class = "num", rows$amount[[i]]),
          shiny::tags$td(mois[[i]])
        )
      }))
    )
  } else {
    NULL
  }
  has_month_bits <- length(spec$formulas) > 0L && any(vapply(spec$formulas, function(f) {
    length(f$bits %||% list()) >= 4L
  }, logical(1)))
  detail_block <- if (!length(detail_i)) {
    NULL
  } else if (isTRUE(collapse)) {
    month_table <- shiny::tags$table(
      class = "fpa-kpi-trace fpa-kpi-trace-months",
      shiny::tags$thead(shiny::tags$tr(
        shiny::tags$th(fpa_screen("kpi_th_rows")),
        shiny::tags$th(fpa_screen("kpi_th_amt"))
      )),
      shiny::tags$tbody(lapply(detail_i, function(i) {
        lab <- if (is_ym(items[[i]])) items[[i]] else mois[[i]]
        shiny::tags$tr(
          shiny::tags$td(fpa_ym_fr(lab)),
          shiny::tags$td(class = "num", rows$amount[[i]])
        )
      }))
    )
    shiny::tags$div(
      class = "fpa-kpi-trace-block",
      shiny::tags$div(
        class = "fpa-kpi-prov",
        if (nzchar(src_file) || nzchar(src_line)) {
          shiny::tags$p(
            class = "fpa-kpi-prov-k",
            fpa_screen("kpi_trace_src", if (nzchar(src_line)) src_line else "—"),
            if (nzchar(src_file)) file_cell(src_file)
          )
        },
        if (nzchar(src_sens)) shiny::tags$p(class = "fpa-kpi-prov-s", src_sens),
        shiny::tags$p(class = "fpa-kpi-prov-note", fpa_screen("kpi_trace_same"))
      ),
      if (isTRUE(has_month_bits)) {
        shiny::tags$details(
          class = "fpa-kpi-months-fold",
          shiny::tags$summary(fpa_screen("kpi_trace_months")),
          month_table
        )
      } else {
        shiny::tagList(shiny::tags$h4(fpa_screen("kpi_trace_months")), month_table)
      }
    )
  } else {
    # Heterogeneous detail: keep a readable 4-column table, drop the duplicated mois when item is the month.
    shiny::tags$table(
      class = "fpa-kpi-trace",
      shiny::tags$thead(shiny::tags$tr(lapply(
        c(fpa_screen("kpi_th_item"), fpa_screen("kpi_th_amt"), fpa_screen("kpi_th_file"), fpa_screen("kpi_th_mean")),
        function(h) shiny::tags$th(h)
      ))),
      shiny::tags$tbody(lapply(detail_i, function(i) {
        shiny::tags$tr(
          shiny::tags$td(items[[i]]),
          shiny::tags$td(class = "num", rows$amount[[i]]),
          shiny::tags$td(file_cell(files[[i]])),
          shiny::tags$td(sens[[i]])
        )
      }))
    )
  }
  shiny::modalDialog(
    title = spec$k,
    easyClose = TRUE,
    size = "l",
    footer = shiny::tagList(
      shiny::tags$button(
        type = "button", class = "fpa-go-btn",
        onclick = sprintf(
          "Shiny.setInputValue('journal_capture',{kind:'kpi',id:'%s',k:%s,v:%s,s:%s},{priority:'event'})",
          spec$id,
          jsonlite::toJSON(spec$k %||% "", auto_unbox = TRUE),
          jsonlite::toJSON(spec$v %||% "", auto_unbox = TRUE),
          jsonlite::toJSON(spec$s %||% "", auto_unbox = TRUE)
        ),
        fpa_screen("journal_to_journal")
      ),
      shiny::tags$button(
        type = "button", class = "fpa-go-btn",
        onclick = sprintf(
          "Shiny.setInputValue('fpa_go',{tab:%s,line:%s,open:%s},{priority:'event'}); $('#shiny-modal').modal('hide');",
          jsonlite::toJSON(go_tab, auto_unbox = TRUE),
          jsonlite::toJSON(go_line, auto_unbox = TRUE),
          jsonlite::toJSON(go_open, auto_unbox = TRUE)
        ),
        fpa_screen("home_test_response")
      ),
      shiny::modalButton(fpa_screen("kpi_close"))
    ),
    shiny::tags$style(HTML("
      .modal-dialog:has(.fpa-kpi-trace-wrap) { max-width:760px; width:92vw; }
      .fpa-kpi-trace-wrap .fpa-kpi-formulas { margin:0 0 12px; }
      .fpa-kpi-trace-wrap .fpa-kpi-align {
        display:flex; flex-wrap:wrap; align-items:flex-start; gap:2px 8px; margin:0 0 10px;
      }
      .fpa-kpi-trace-wrap .pair { display:flex; flex-direction:column; align-items:center; text-align:center; max-width:7.5em; }
      .fpa-kpi-trace-wrap .num {
        font-family:Consolas,'Courier New',monospace; font-weight:700; font-size:14px;
        color:#0f2f3a; white-space:nowrap; font-variant-numeric:tabular-nums;
      }
      .fpa-kpi-trace-wrap .lab { font-size:12px; color:#3d4c54; line-height:1.25; margin-top:3px; }
      .fpa-kpi-trace-wrap .op { font-weight:700; font-size:14px; color:#0f2f3a; line-height:1.3; padding:0 1px; }
      .fpa-kpi-trace-wrap .eq { margin:0 0 2px; font-family:Consolas,'Courier New',monospace; font-size:13px; font-weight:650; color:#0f2f3a; }
      .fpa-kpi-trace-wrap .eq-note { margin:0 0 10px; color:#3d4c54; font-size:13px; line-height:1.35; }
      .fpa-kpi-trace-wrap table.fpa-kpi-trace {
        width:100%; border-collapse:collapse; font-size:13px; margin:0 0 12px;
      }
      .fpa-kpi-trace-wrap table.fpa-kpi-trace th {
        background:#1f4e5f; color:#fff; text-align:left; padding:7px 10px; font-weight:600;
      }
      .fpa-kpi-trace-wrap table.fpa-kpi-trace td {
        padding:7px 10px; border-bottom:1px solid #e6edef; vertical-align:top; line-height:1.35;
      }
      .fpa-kpi-trace-wrap table.fpa-kpi-trace tr:nth-child(even) td { background:#f6f9fa; }
      .fpa-kpi-trace-wrap table.fpa-kpi-trace td.num {
        text-align:right; font-variant-numeric:tabular-nums; white-space:nowrap;
        font-family:Consolas,'Courier New',monospace; font-weight:650; color:#0f2f3a;
      }
      .fpa-kpi-trace-wrap table.fpa-kpi-trace-months { max-width:420px; }
      .fpa-kpi-trace-wrap .fpa-kpi-prov {
        margin:0 0 10px; padding:10px 12px; border:1px solid #d6e1e5; border-radius:10px; background:#f4f8f9;
      }
      .fpa-kpi-trace-wrap .fpa-kpi-prov-k { margin:0 0 4px; font-weight:650; color:#0f2f3a; }
      .fpa-kpi-trace-wrap .fpa-kpi-prov-s { margin:0 0 4px; color:#1a2b32; font-size:13px; line-height:1.4; }
      .fpa-kpi-trace-wrap .fpa-kpi-prov-note { margin:0; color:#5c6b73; font-size:12.5px; }
      .fpa-kpi-trace-wrap h4 { margin:0 0 8px; font-size:14px; color:#0f2f3a; }
      .fpa-kpi-trace-wrap details.fpa-kpi-months-fold { margin:0 0 12px; }
      .fpa-kpi-trace-wrap details.fpa-kpi-months-fold > summary {
        cursor:pointer; font-weight:650; color:#1f4e5f; margin:0 0 8px; list-style:none;
      }
      .fpa-kpi-trace-wrap details.fpa-kpi-months-fold > summary::-webkit-details-marker { display:none; }
      button.fpa-kpi-file {
        display:inline; margin:0 0 0 6px; padding:2px 8px; border:1px solid #b7c9d0; border-radius:8px;
        background:#fff; color:#1f4e5f; font:inherit; font-weight:650; cursor:pointer;
      }
      button.fpa-kpi-file:hover, button.fpa-kpi-file:focus { outline:2px solid #1f4e5f; outline-offset:1px; }
    ")),
    shiny::tags$div(
      class = "fpa-kpi-trace-wrap",
      shiny::tags$p(style = "margin:0 0 6px;line-height:1.45;font-weight:600;color:#1f4e5f;", spec$tone_txt %||% ""),
      shiny::tags$p(style = "margin:0 0 12px;font-size:22px;font-weight:700;color:#1f4e5f;font-variant-numeric:tabular-nums;", spec$v),
      if (length(spec$formulas)) shiny::tags$div(
        class = "fpa-kpi-formulas",
        lapply(spec$formulas, function(f) {
          if (!is.null(f$bits) && length(f$bits)) {
            return(shiny::tags$div(
              class = "fpa-kpi-align",
              lapply(f$bits, function(bit) {
                if (is.character(bit)) return(shiny::tags$span(class = "op", bit))
                shiny::tags$span(
                  class = "pair",
                  shiny::tags$span(class = "num", bit$num),
                  shiny::tags$span(class = "lab", bit$lab)
                )
              })
            ))
          }
          shiny::tagList(
            shiny::tags$p(class = "eq", f$eq),
            if (nzchar(f$note %||% "")) shiny::tags$p(class = "eq-note", f$note)
          )
        })
      ),
      shiny::tags$div(
        style = "overflow:auto;max-height:55vh;",
        summary_table,
        detail_block
      )
    )
  )
}

fpa_manual_popup <- function(config, applied, ye, with_close, without_close, bar_eur = 500) {
  cur <- tryCatch(fpa_manual_read(config), error = function(e) NULL)
  df <- if (is.null(cur)) fpa_manual_empty() else fpa_manual_active(cur$data)
  retired_n <- if (is.null(cur) || !nrow(cur$data)) 0L else sum(as.character(cur$data$statut) == "retire")
  ligne_lab <- function(code) {
    key <- switch(
      as.character(code %||% ""),
      OTHER_OP_INC = "man_ligne_other_inc",
      OPEX_OTHER = "man_ligne_opex",
      REV = "man_ligne_rev",
      COGS = "man_ligne_cogs",
      PAYROLL = "man_ligne_pay",
      FIN = "man_ligne_fin",
      EXCEP = "man_ligne_excep",
      "man_ligne"
    )
    fpa_screen(key)
  }
  on <- isTRUE(applied)
  close_now <- if (on) with_close else without_close
  close_other <- if (on) without_close else with_close
  lead <- if (is.null(df) || !nrow(df)) {
    if (retired_n > 0L) fpa_screen("man_pop_empty_n", as.character(retired_n)) else fpa_screen("man_pop_empty")
  } else {
    fpa_screen(
      if (on) "man_list_on" else "man_list_off",
      fpa_shiny_close_when(ye), fpa_shiny_eur(close_now), fpa_shiny_eur(close_other)
    )
  }
  has_pnl <- !is.null(df) && nrow(df) && any(as.character(df$nature) == "nouveau")
  table <- if (is.null(df) || !nrow(df)) {
    NULL
  } else {
    shiny::tags$table(
      class = "fpa-man-pop",
      shiny::tags$thead(shiny::tags$tr(
        shiny::tags$th(fpa_screen("out_label")),
        shiny::tags$th(fpa_screen("out_kind")),
        shiny::tags$th(class = "num", fpa_screen("out_amount")),
        shiny::tags$th(fpa_screen("out_when")),
        shiny::tags$th(fpa_screen("man_nature")),
        shiny::tags$th(fpa_screen("man_ligne"))
      )),
      shiny::tags$tbody(lapply(seq_len(nrow(df)), function(i) {
        sens <- if (identical(as.character(df$sens[[i]]), "in")) fpa_screen("out_in") else fpa_screen("out_out")
        nat <- if (identical(as.character(df$nature[[i]]), "decalage")) fpa_screen("man_decalage") else fpa_screen("man_nouveau")
        shiny::tags$tr(
          shiny::tags$td(as.character(df$libelle[[i]])),
          shiny::tags$td(sens),
          shiny::tags$td(class = "num", fpa_shiny_eur(df$montant[[i]])),
          shiny::tags$td(as.character(df$date_effet[[i]])),
          shiny::tags$td(nat),
          shiny::tags$td(ligne_lab(df$ligne[[i]]))
        )
      }))
    )
  }
  btn <- "background:#1f4e5f;color:#fff;border:1px solid #1f4e5f;border-radius:8px;font-weight:600;"
  ghost <- "background:#fff;color:#1f4e5f;border:1px solid #1f4e5f;border-radius:8px;font-weight:600;"
  shiny::modalDialog(
    title = fpa_screen("man_pop_title"),
    size = "l",
    easyClose = TRUE,
    shiny::tags$p(class = "fpa-out-rule", fpa_screen("man_bar", fpa_shiny_eur(bar_eur))),
    shiny::tags$p(class = "fpa-out-rule", fpa_screen("man_line_hint")),
    shiny::tags$p(class = "fpa-man-pop-lead", lead),
    table,
    footer = shiny::tags$div(
      style = "display:flex; gap:8px; justify-content:flex-end; flex-wrap:wrap;",
      shiny::actionButton("manual_hist", fpa_screen("man_pop_hist"), style = ghost),
      if (isTRUE(has_pnl)) shiny::actionButton("manual_pnl", fpa_screen("man_pop_pnl"), style = ghost),
      shiny::actionButton("manual_cash", fpa_screen("man_pop_cash"), style = btn)
    )
  )
}

fpa_shiny_manual_choices <- function(kind) {
  if (identical(kind, "sens")) {
    return(stats::setNames(c("in", "out"), c(fpa_screen("out_in"), fpa_screen("out_out"))))
  }
  if (identical(kind, "nature")) {
    return(stats::setNames(c("nouveau", "decalage"), c(fpa_screen("man_nouveau"), fpa_screen("man_decalage"))))
  }
  if (identical(kind, "statut")) {
    return(stats::setNames(c("actif", "retire"), c(fpa_screen("man_statut_on"), fpa_screen("man_statut_off"))))
  }
  stats::setNames(
    c("REV", "OTHER_OP_INC", "COGS", "PAYROLL", "OPEX_OTHER", "FIN", "EXCEP"),
    c(
      fpa_screen("man_ligne_rev"), fpa_screen("man_ligne_other_inc"),
      fpa_screen("man_ligne_cogs"), fpa_screen("man_ligne_pay"),
      fpa_screen("man_ligne_opex"), fpa_screen("man_ligne_fin"), fpa_screen("man_ligne_excep")
    )
  )
}

fpa_shiny_manual_pick <- function(choices, value) {
  value <- as.character(value %||% "")
  hit <- names(choices)[match(value, unname(choices))]
  if (length(hit) == 1L && !is.na(hit)) hit else value
}

#' Manual ledger as a form that fits the window. Codes stay in the file.
fpa_shiny_manual_file <- function(df, edit = FALSE, note = "", guide = "") {
  sens_ch <- fpa_shiny_manual_choices("sens")
  nat_ch <- fpa_shiny_manual_choices("nature")
  stat_ch <- fpa_shiny_manual_choices("statut")
  ligne_ch <- fpa_shiny_manual_choices("ligne")
  cards <- if (is.null(df) || !nrow(df)) {
    list(shiny::tags$p(fpa_screen("man_file_empty")))
  } else {
    lapply(seq_len(nrow(df)), function(i) {
      sens <- as.character(df$sens[[i]] %||% "")
      nature <- as.character(df$nature[[i]] %||% "")
      ligne <- as.character(df$ligne[[i]] %||% "")
      statut <- as.character(df$statut[[i]] %||% "")
      lib <- as.character(df$libelle[[i]] %||% "")
      amt <- suppressWarnings(as.numeric(df$montant[[i]]))
      d_eff <- fpa_manual_parse_date(df$date_effet[[i]])
      d_prev <- fpa_manual_parse_date(df$date_prevue[[i]])
      if (!isTRUE(edit)) {
        when <- if (is.finite(d_eff)) fpa_shiny_date_fr(d_eff) else ""
        bits <- c(
          fpa_shiny_manual_pick(sens_ch, sens),
          if (is.finite(amt)) paste0(fpa_shiny_eur(amt), " EUR") else "",
          when
        )
        bits <- bits[nzchar(bits)]
        meta <- c(
          fpa_shiny_manual_pick(nat_ch, nature),
          if (nzchar(ligne)) fpa_shiny_manual_pick(ligne_ch, ligne) else "",
          fpa_shiny_manual_pick(stat_ch, statut)
        )
        meta <- meta[nzchar(meta)]
        return(shiny::tags$div(
          class = "fpa-man-edit-card",
          shiny::tags$p(class = "fpa-man-edit-name", if (nzchar(lib)) lib else fpa_screen("man_file")),
          shiny::tags$p(paste(bits, collapse = " · ")),
          shiny::tags$p(paste(meta, collapse = " · "))
        ))
      }
      if (!sens %in% unname(sens_ch)) sens <- "out"
      if (!nature %in% unname(nat_ch)) nature <- "nouveau"
      if (!ligne %in% unname(ligne_ch)) ligne <- fpa_manual_default_ligne(sens)
      if (!statut %in% unname(stat_ch)) statut <- "actif"
      shiny::tags$div(
        class = "fpa-man-edit-card",
        shiny::div(style = "display:none;", shiny::textInput(paste0("maned_id_", i), NULL, value = as.character(df$id[[i]]))),
        shiny::textInput(paste0("maned_lib_", i), fpa_screen("out_label"), value = lib, width = "100%"),
        shiny::div(
          class = "fpa-man-edit-grid",
          shiny::selectInput(
            paste0("maned_sens_", i), fpa_screen("out_kind"),
            choices = sens_ch, selected = sens, width = "100%", selectize = FALSE
          ),
          shiny::numericInput(paste0("maned_amt_", i), fpa_screen("out_amount"), value = amt, min = 0, step = 100, width = "100%"),
          shiny::dateInput(
            paste0("maned_date_", i), fpa_screen("out_when"),
            value = if (is.finite(d_eff)) d_eff else Sys.Date(),
            format = "dd/mm/yyyy", language = "fr", width = "100%"
          ),
          shiny::selectInput(
            paste0("maned_nat_", i), fpa_screen("man_nature"),
            choices = nat_ch, selected = nature, width = "100%", selectize = FALSE
          ),
          shiny::conditionalPanel(
            condition = sprintf("input.maned_nat_%d == 'decalage'", i),
            shiny::dateInput(
              paste0("maned_prev_", i), fpa_screen("man_prevue"),
              value = if (is.finite(d_prev)) d_prev else Sys.Date(),
              format = "dd/mm/yyyy", language = "fr", width = "100%"
            )
          ),
          shiny::conditionalPanel(
            condition = sprintf("input.maned_nat_%d == 'nouveau'", i),
            shiny::selectInput(
              paste0("maned_ligne_", i), fpa_screen("man_ligne"),
              choices = ligne_ch, selected = ligne, width = "100%", selectize = FALSE
            )
          ),
          shiny::selectInput(
            paste0("maned_stat_", i), fpa_screen("man_statut"),
            choices = stat_ch, selected = statut, width = "100%", selectize = FALSE
          )
        )
      )
    })
  }
  shiny::tags$div(
    class = "fpa-man-edit",
    shiny::tags$style(shiny::HTML(
      ".fpa-man-edit{max-width:100%;overflow-x:hidden;}",
      ".modal-body:has(.fpa-man-edit),.modal-content:has(.fpa-man-edit){overflow-x:hidden;}",
      ".fpa-man-edit .fpa-out-rule{margin:0 0 10px;font-size:13.5px;font-weight:700;line-height:1.45;color:#0f2f3a;}",
      ".fpa-man-edit-card{max-width:100%;overflow:hidden;box-sizing:border-box;border:1px solid #d6e1e5;border-radius:8px;padding:10px 12px;margin:0 0 10px;background:#fff;}",
      ".fpa-man-edit-name{margin:0 0 4px;font-weight:700;color:#0f2f3a;overflow-wrap:anywhere;}",
      ".fpa-man-edit-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(11rem,1fr));gap:8px 12px;max-width:100%;}",
      ".fpa-man-edit .shiny-input-container,.fpa-man-edit .form-group{width:100%!important;max-width:100%;min-width:0;margin:0;}",
      ".fpa-man-edit .form-control,.fpa-man-edit select{width:100%!important;max-width:100%;min-width:0;box-sizing:border-box;border:1px solid #1f4e5f;border-radius:8px;}",
      ".fpa-man-edit .control-label{font-size:12px;font-weight:600;color:#1f4e5f;}"
    )),
    if (nzchar(note)) shiny::tags$p(class = "fpa-file-lead", note),
    if (nzchar(guide)) shiny::tags$p(class = "fpa-out-rule", guide),
    shiny::tags$p(class = "fpa-out-rule", fpa_screen("man_file_lead")),
    shiny::tags$p(class = "fpa-out-rule", fpa_screen("man_line_hint")),
    cards
  )
}

fpa_shiny_raw_modal <- function(config, node_id, edit = FALSE, note = "", cash = NULL) {
  manual <- identical(as.character(node_id %||% ""), "manual:ledger")
  sid <- sub("^src:", "", as.character(node_id %||% ""))
  src <- NULL
  if (!manual) {
    for (s in config$sources %||% list()) {
      if (identical(as.character(s$source_id %||% ""), sid)) src <- s
    }
  }
  title <- if (manual) fpa_screen("man_file") else if (is.null(src)) sid else as.character(src$source_name %||% sid)
  path <- if (manual) fpa_manual_path(config) else if (is.null(src)) "" else fpa_chain_source_path(config, src)
  sheet_note <- NULL
  if (nzchar(path) && file.exists(path) && identical(fpa_sniff_kind(path), "excel") &&
      requireNamespace("readxl", quietly = TRUE)) {
    sheets <- tryCatch(readxl::excel_sheets(path), error = function(e) character())
    if (length(sheets) > 1L) {
      sheet_note <- shiny::tags$p(fpa_screen("raw_sheet", sheets[[1]], paste(sheets[-1], collapse = ", ")))
    }
  }
  is_csv <- nzchar(path) && identical(tolower(tools::file_ext(path)), "csv")
  cell_txt <- function(v, plain = FALSE, as_num = FALSE) {
    if (length(v) != 1L || is.na(v)) return("")
    if (inherits(v, "POSIXt") || inherits(v, "Date")) return(format(as.Date(v)))
    if (isTRUE(as_num) && !is.numeric(v)) {
      s <- gsub("[\u00a0 ]", "", as.character(v))
      s <- gsub(",", ".", s, fixed = TRUE)
      v <- suppressWarnings(as.numeric(s))
      if (!is.finite(v)) return("")
    }
    if (is.numeric(v)) {
      mark <- if (plain) "" else "\u00a0"
      return(format(v, scientific = FALSE, trim = TRUE, big.mark = mark))
    }
    as.character(v)
  }
  body <- if (!nzchar(path) || !file.exists(path)) {
    shiny::tags$p(fpa_screen("raw_missing"))
  } else {
    got <- fpa_raw_preview_frame(path)
    if (!is.null(got$error) || is.null(got$data)) {
      shiny::tags$p(fpa_screen("raw_fail", got$message %||% got$error %||% ""))
    } else {
      df <- got$data
      n <- nrow(df)
      cap <- 800L
      cut <- n > cap
      shown <- if (cut) df[seq_len(cap), , drop = FALSE] else df
      cols <- names(shown)
      editing <- isTRUE(edit) && is_csv
      is_num_col <- function(col) {
        if (is.numeric(col)) return(TRUE)
        x <- trimws(as.character(col))
        x <- x[!is.na(col) & nzchar(x)]
        if (!length(x)) return(FALSE)
        mean(grepl("^[+-]?[0-9][0-9 \u00a0]*([.,][0-9]+)?$", x)) >= 0.6
      }
      num_cols <- vapply(shown, is_num_col, logical(1))
      section_row <- function(i) {
        idx <- which(num_cols)
        if (!length(idx)) return(FALSE)
        all(vapply(idx, function(j) {
          v <- shown[[j]][[i]]
          if (is.numeric(v)) return(!is.finite(v))
          !nzchar(trimws(as.character(v %||% ""))) || is.na(v)
        }, logical(1)))
      }
      shiny::tagList(
        shiny::tags$style(shiny::HTML("
          .fpa-raw-wrap { max-height:68vh; max-width:100%; overflow:auto; border:1px solid #d6e1e5; border-radius:8px; }
          .fpa-raw-wrap table { border-collapse:separate; border-spacing:0; width:max-content; min-width:100%; }
          .fpa-raw-wrap th, .fpa-raw-wrap td {
            white-space:nowrap; padding:6px 10px; font-size:13px; line-height:1.35;
            border-bottom:1px solid #e6edef; border-right:1px solid #eef3f4; vertical-align:middle;
          }
          .fpa-raw-wrap th { position:sticky; top:0; background:#1f4e5f; color:#fff; z-index:2; font-weight:600; }
          .fpa-raw-wrap td.num { text-align:right; font-variant-numeric:tabular-nums; }
          .fpa-raw-wrap th.lab, .fpa-raw-wrap td.lab {
            position:sticky; left:0; text-align:left; min-width:14rem; max-width:18rem;
            white-space:normal; z-index:1;
          }
          .fpa-raw-wrap th.lab { z-index:3; background:#1f4e5f; }
          .fpa-raw-wrap td.lab { background:#fff; }
          .fpa-raw-wrap td.note { white-space:normal; max-width:16rem; color:#3d4c54; font-size:12px; }
          .fpa-raw-wrap tr:nth-child(even) td { background:#f4f7f8; }
          .fpa-raw-wrap tr:nth-child(even) td.lab { background:#f4f7f8; }
          .fpa-raw-wrap tr.is-section td { font-weight:700; background:#e7eef0; color:#0f2f3a; }
          .fpa-raw-wrap tr.is-section td.lab { background:#e7eef0; }
        ")),
        if (nzchar(note)) shiny::tags$p(class = "fpa-file-lead", note),
        if (editing) shiny::tags$p(class = "fpa-file-lead", fpa_screen("raw_edit_lead")),
        shiny::tags$p(if (cut) fpa_screen("raw_cut", cap, n, length(cols)) else fpa_screen("raw_all", n, length(cols))),
        sheet_note,
        shiny::tags$div(
          class = "fpa-raw-wrap",
          shiny::tags$table(
            shiny::tags$thead(shiny::tags$tr(lapply(seq_along(cols), function(j) {
              shiny::tags$th(class = if (j == 1L) "lab" else if (isTRUE(num_cols[[j]])) "num" else NULL, cols[[j]])
            }))),
            shiny::tags$tbody(lapply(seq_len(nrow(shown)), function(i) {
              sec <- isTRUE(section_row(i))
              shiny::tags$tr(
                class = if (sec) "is-section" else NULL,
                lapply(seq_along(shown), function(j) {
                  v <- shown[[j]][[i]]
                  num <- isTRUE(num_cols[[j]])
                  cls <- if (j == 1L) "lab" else if (num) "num" else "note"
                  if (editing) {
                    return(shiny::tags$td(
                      class = cls,
                      shiny::textInput(
                        sprintf("rawc_%d_%d", i, j), NULL,
                        value = cell_txt(v, plain = TRUE, as_num = num),
                        width = "100%"
                      )
                    ))
                  }
                  shiny::tags$td(class = cls, cell_txt(v, as_num = num))
                })
              )
            }))
          )
        )
      )
    }
  }
  if (manual) {
    gotm <- fpa_manual_read(config)
    body <- if (!isTRUE(gotm$ok)) {
      shiny::tags$p(fpa_screen("raw_fail", gotm$message %||% gotm$error %||% ""))
    } else {
      fpa_shiny_manual_file(
        gotm$data, edit = isTRUE(edit), note = note,
        guide = fpa_screen("man_bar", fpa_shiny_eur(fpa_shiny_manual_floor(cash)))
      )
    }
    is_csv <- TRUE
  }
  btn <- "background:#1f4e5f;color:#fff;border:1px solid #1f4e5f;border-radius:8px;font-weight:600;"
  ghost <- "background:#fff;color:#1f4e5f;border:1px solid #1f4e5f;border-radius:8px;font-weight:600;"
  shiny::modalDialog(
    title = title,
    size = if (manual) "l" else "xl",
    easyClose = !isTRUE(edit),
    if (!manual) shiny::tags$p(style = "font-size:13px;color:#3d4c54;overflow-wrap:anywhere;", path),
    body,
    footer = shiny::tagList(
      if (is_csv && !isTRUE(edit)) shiny::actionButton("raw_unlock", if (manual) fpa_screen("man_file_edit") else fpa_screen("raw_unlock"), style = ghost),
      if (is_csv && isTRUE(edit)) shiny::actionButton("raw_save", if (manual) fpa_screen("man_apply") else fpa_screen("raw_save"), style = btn),
      shiny::actionButton("raw_close", fpa_screen("catchup_close"), class = "btn-primary")
    )
  )
}

#' Lines the map question offers, in order: revenue first, then income, cash, the rest.
#' Names are labels, values are chain node ids.
fpa_shiny_map_asks <- function(nodes) {
  if (is.null(nodes) || !nrow(nodes)) return(character())
  ids <- as.character(nodes$id)
  rev_ids <- paste0("rule:", vapply(Filter(function(m) identical(m$line_id, "REV"), fpa_chain_catalog()), function(m) m$id, ""))
  rev_hit <- ids[ids %in% rev_ids]
  if (length(rev_hit)) {
    st <- as.character(nodes$status[match(rev_hit, ids)])
    live <- rev_hit[st %in% c("utilisé", "relié", "partagé")]
    rev_hit <- if (length(live)) live[[1]] else rev_hit[[1]]
  }
  out <- c(
    stats::setNames(rev_hit, rep(fpa_shiny_line_name("REV"), length(rev_hit))),
    stats::setNames("out:pnl", fpa_shiny_line_name("OI")),
    stats::setNames("out:cash", fpa_screen("health_lab_cash")),
    stats::setNames("out:bs", fpa_screen("nav_tab_bs")),
    stats::setNames("out:var", fpa_screen("loc_gap_to_budget"))
  )
  out[out %in% ids]
}

fpa_shiny_chain_page <- function(config, evidence = NULL, selected = "", series = NULL, paths = NULL) {
  chain <- tryCatch(fpa_chain_build(config, evidence), error = function(e) NULL)
  if (is.null(chain) || is.null(chain$nodes) || !nrow(chain$nodes)) {
    return(shiny::tags$p(fpa_screen("loc_config_no_files")))
  }
  asks <- fpa_shiny_map_asks(chain$nodes)
  selected <- as.character(selected %||% "")
  if (identical(selected, "none")) {
    selected <- ""
  } else if (!nzchar(selected) && length(asks)) {
    selected <- unname(asks[[1]])
  }
  touch <- fpa_chain_touch(chain, selected)
  on <- function(id) nzchar(selected) && id %in% touch
  status_bg <- c(
    présent = "#e6f1f4", utilisé = "#1f4e5f", relié = "#e6f1f4", déclaré = "#f4f7f8",
    "non relu" = "#f4f7f8", "non vérifié" = "#f4f7f8", écrit = "#1f4e5f",
    incomplet = "#fdf6ea", absent = "#f8eeee",
    "sans suite" = "#fdf6ea", partagé = "#fdf6ea"
  )
  status_fg <- c(
    présent = "#1f4e5f", utilisé = "#ffffff", relié = "#1f4e5f", déclaré = "#3d4c54",
    "non relu" = "#5c6b73", "non vérifié" = "#5c6b73", écrit = "#ffffff",
    incomplet = "#8a5a00", absent = "#8c3a3a",
    "sans suite" = "#8a5a00", partagé = "#8a5a00"
  )
  series_of <- function(node_id) {
    empty <- if (is.null(series) || !is.data.frame(series)) {
      data.frame(series_id = character(), series_name = character(), source_id = character(), stringsAsFactors = FALSE)
    } else {
      series[0, , drop = FALSE]
    }
    if (!nrow(empty) && (is.null(series) || !nrow(series) || !"source_id" %in% names(series))) return(empty)
    sid <- sub("^src:", "", as.character(node_id))
    hit <- series[as.character(series$source_id) == sid, , drop = FALSE]
    if (nrow(hit)) hit <- hit[order(as.character(hit$series_name)), , drop = FALSE]
    hit
  }
  var_panel <- function(node_id) {
    hit <- series_of(node_id)
    shiny::tags$div(
      class = "fpa-chain-vars",
      shiny::tags$div(class = "fpa-chain-vars-label", fpa_screen("loc_series_of_file")),
      if (!nrow(hit)) {
        shiny::tags$p(class = "fpa-var-empty", fpa_screen("loc_no_series_file"))
      } else {
        lapply(seq_len(nrow(hit)), function(i) {
          sid <- gsub("[^A-Za-z0-9_-]", "", as.character(hit$series_id[[i]]))
          shiny::tags$button(
            type = "button",
            class = "fpa-var",
            onclick = sprintf(
              "Shiny.setInputValue('map_jump', {id:'%s', tab:'Fiche', nav:'Drivers'}, {priority:'event'})",
              sid
            ),
            shiny::tags$span(class = "fpa-var-name", hit$series_name[[i]]),
            shiny::tags$span(class = "fpa-var-note", fpa_screen("loc_open_card"))
          )
        })
      }
    )
  }
  synced_at <- if (is.null(paths)) as.POSIXct(NA) else fpa_shiny_sync_stamp_read(paths)
  if (is.na(synced_at) && !is.null(paths)) {
    pnl_stamp <- file.path(paths$work %||% "", "pnl-monthly.csv")
    if (nzchar(pnl_stamp) && file.exists(pnl_stamp)) synced_at <- file.info(pnl_stamp)$mtime
  }
  synced_line <- if (is.na(synced_at)) fpa_screen("file_synced_none") else fpa_screen("file_synced", fpa_shiny_fr_stamp(synced_at))
  file_dates <- function(path) {
    path <- as.character(path %||% "")
    mt <- if (nzchar(path) && file.exists(path)) file.info(path)$mtime else as.POSIXct(NA)
    saved <- if (is.na(mt)) {
      shiny::tags$p(fpa_screen("file_saved_none"))
    } else {
      hours <- as.numeric(difftime(Sys.time(), mt, units = "hours"))
      fresh <- is.finite(hours) && hours >= 0 && hours <= 24
      shiny::tags$p(
        fpa_screen("file_saved"),
        " ",
        shiny::tags$span(
          class = if (fresh) "fpa-file-fresh" else NULL,
          paste0(fpa_shiny_fr_stamp(mt), ".")
        )
      )
    }
    shiny::tags$div(class = "fpa-file-stamps", saved, shiny::tags$p(synced_line))
  }
  card <- function(n) {
    kind <- if (identical(as.character(n$col), "source")) {
      as.character(n$frame)
    } else if (identical(as.character(n$col), "output")) {
      "out"
    } else if (startsWith(as.character(n$id), "rule:read:")) {
      "read"
    } else {
      "calc"
    }
    cat_lab <- c(
      history = "Historique", rolling = "Suivi", plan = "Plan",
      read = "Lecture", calc = "Calcul", out = "Sortie"
    )[[kind]]
    mark <- status_bg[[as.character(n$status)]] %||% "#f4f7f8"
    ink <- status_fg[[as.character(n$status)]] %||% "#3d4c54"
    open_vars <- identical(as.character(n$col), "source") && nzchar(selected) && identical(as.character(n$id), selected)
    safe_id <- gsub("[^A-Za-z0-9_:.-]", "", n$id)
    body <- shiny::tagList(
      shiny::tags$span(class = paste("fpa-cat", paste0("fpa-cat-", kind)), cat_lab %||% ""),
      shiny::tags$span(class = "fpa-chain-title", n$title),
      shiny::tags$span(class = "fpa-chain-sub", n$sub),
      if (identical(as.character(n$col), "source")) file_dates(if ("path" %in% names(n)) n$path else ""),
      if (identical(as.character(n$col), "source")) {
        shiny::tags$div(
          class = "fpa-chain-foot",
          shiny::tags$span(class = "fpa-chain-status", style = paste0("background:", mark, ";color:", ink, ";"), n$status),
          shiny::tags$button(
            type = "button",
            class = "fpa-raw-btn",
            onclick = sprintf(
              "event.stopPropagation(); Shiny.setInputValue('raw_file','%s',{priority:'event'})",
              safe_id
            ),
            fpa_screen("raw_view")
          )
        )
      } else {
        shiny::tags$span(class = "fpa-chain-status", style = paste0("background:", mark, ";color:", ink, ";"), n$status)
      }
    )
    card_class <- paste("fpa-chain-card", paste0("fpa-card-", kind), if (on(as.character(n$id))) "is-on" else "")
    face <- if (identical(as.character(n$col), "source")) {
      shiny::tags$div(
        class = card_class,
        onclick = sprintf("Shiny.setInputValue('chain_focus','%s',{priority:'event'})", safe_id),
        body
      )
    } else {
      shiny::tags$button(
        type = "button",
        class = card_class,
        onclick = sprintf("Shiny.setInputValue('chain_focus','%s',{priority:'event'})", safe_id),
        body
      )
    }
    shiny::tags$div(
      class = if (open_vars) "fpa-chain-item is-open" else "fpa-chain-item",
      face,
      if (open_vars) var_panel(as.character(n$id))
    )
  }
  stack <- function(rows) {
    if (!nrow(rows)) return(NULL)
    lapply(seq_len(nrow(rows)), function(i) card(rows[i, , drop = FALSE]))
  }
  file_stack <- function(src) {
    frames <- c(history = "Historique", rolling = "Suivi", plan = "Plan")
    lapply(names(frames), function(fr) {
      sub <- src[as.character(src$frame) == fr, , drop = FALSE]
      fold(paste0("fpa-file-", fr), frames[[fr]], sub, stack(sub))
    })
  }
  fold <- function(class, title, rows, body) {
    if (is.null(rows) || !nrow(rows)) return(NULL)
    show <- nzchar(selected) && any(as.character(rows$id) %in% touch)
    shiny::tags$details(
      class = paste("fpa-fold", class),
      open = if (show || any(as.character(rows$status) == "absent")) NA else NULL,
      shiny::tags$summary(
        shiny::tags$span(class = "fpa-fold-title", title),
        shiny::tags$span(class = "fpa-fold-count", paste0(nrow(rows), " · ", fpa_chain_status_bits(rows)))
      ),
      body
    )
  }
  fold_tools <- function() {
    shiny::div(
      class = "fpa-fold-tools",
      shiny::tags$button(
        type = "button", class = "fpa-map-btn fpa-map-btn-primary",
        onclick = "this.closest('.fpa-chain-col').querySelectorAll('details.fpa-fold').forEach(function(d){ d.open = true })",
        shiny::HTML('<svg viewBox="0 0 16 16" width="15" height="15" aria-hidden="true"><path d="M3.2 6.2 8 10.2l4.8-4" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/><path d="M3.2 9.4 8 13.4l4.8-4" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>'),
        shiny::tags$span("Tout ouvrir")
      ),
      shiny::tags$button(
        type = "button", class = "fpa-map-btn",
        onclick = "this.closest('.fpa-chain-col').querySelectorAll('details.fpa-fold').forEach(function(d){ d.open = false })",
        shiny::HTML('<svg viewBox="0 0 16 16" width="15" height="15" aria-hidden="true"><path d="M3.2 9.8 8 5.8l4.8 4" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/><path d="M3.2 6.6 8 2.6l4.8 4" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>'),
        shiny::tags$span("Tout fermer")
      )
    )
  }
  nodes <- chain$nodes
  src <- nodes[nodes$col == "source", , drop = FALSE]
  if (nrow(src)) {
    ord <- order(match(src$frame, c("history", "rolling", "plan")), src$title)
    src <- src[ord, , drop = FALSE]
  }
  rules <- nodes[nodes$col == "rule", , drop = FALSE]
  outs <- nodes[nodes$col == "output", , drop = FALSE]
  reads <- if (nrow(rules)) rules[startsWith(as.character(rules$id), "rule:read:"), , drop = FALSE] else rules
  calcs <- if (nrow(rules)) rules[!startsWith(as.character(rules$id), "rule:read:"), , drop = FALSE] else rules
  cov <- fpa_chain_coverage(config)
  fy_end <- suppressWarnings(as.integer((config$company %||% list())$fiscal_year_end_month %||% 12L))
  if (is.na(fy_end) || fy_end < 1L || fy_end > 12L) fy_end <- 12L
  rulers <- fpa_chain_rulers(cov, fy_end)
  ruler_row <- function(kind, title, meta) {
    segs <- rulers[rulers$kind == kind, , drop = FALSE]
    if (!nrow(segs)) return(NULL)
    shiny::tags$div(
      class = "fpa-span-row is-ruler",
      shiny::tags$span(class = "fpa-span-name", title),
      shiny::tags$span(
        class = "fpa-span-track is-ruler",
        lapply(seq_len(nrow(segs)), function(i) {
          shiny::tags$span(
            class = paste("fpa-year-seg", if (identical(kind, "fiscal")) "is-fy" else "is-civil"),
            style = sprintf("left:%.2f%%;width:%.2f%%;", segs$left_pct[[i]], segs$width_pct[[i]]),
            title = segs$full[[i]],
            segs$label[[i]]
          )
        }),
        if (nrow(cov) && is.finite(cov$today_pct[[1]])) shiny::tags$span(
          class = "fpa-span-today",
          style = sprintf("left:%.2f%%;", cov$today_pct[[1]])
        )
      ),
      shiny::tags$span(class = "fpa-span-meta", meta)
    )
  }
  fy_meta <- if (fy_end == 12L) fpa_screen("span_fy_same") else fpa_screen("span_fy_end", fpa_chain_month_fr(fy_end))
  picked <- if (nzchar(selected)) nodes[nodes$id == selected, , drop = FALSE] else nodes[0, , drop = FALSE]
  path_bits <- character()
  if (nrow(picked) && nrow(chain$edges)) {
    e <- chain$edges
    names <- stats::setNames(nodes$title, nodes$id)
    left <- e$from[e$to == selected]
    right <- e$to[e$from == selected]
    path_bits <- c(
      if (length(left)) paste(names[left], collapse = ", "),
      picked$title[[1]],
      if (length(right)) paste(names[right], collapse = ", ")
    )
    path_bits <- path_bits[nzchar(path_bits)]
  }
  one_path <- local({
    src_nodes <- nodes[nodes$col == "source", , drop = FALSE]
    prefer <- if (nrow(src_nodes)) {
      grep("volume|ops|activ|nuitee", paste(src_nodes$id, src_nodes$title), ignore.case = TRUE)
    } else {
      integer()
    }
    srow <- if (!nrow(src_nodes)) NULL else if (length(prefer)) src_nodes[prefer[[1]], , drop = FALSE] else src_nodes[1, , drop = FALSE]
    sid <- if (is.null(srow)) "" else as.character(srow$id[[1]])
    rule_ids <- if (nzchar(sid) && nrow(chain$edges)) as.character(chain$edges$to[chain$edges$from == sid]) else character()
    rrow <- nodes[nodes$col == "rule" & nodes$id %in% rule_ids, , drop = FALSE]
    if (!nrow(rrow) && any(nodes$col == "rule")) rrow <- nodes[nodes$col == "rule", , drop = FALSE][1, , drop = FALSE]
    rid <- if (nrow(rrow)) as.character(rrow$id[[1]]) else ""
    out_ids <- if (nzchar(rid) && nrow(chain$edges)) as.character(chain$edges$to[chain$edges$from == rid]) else character()
    orow <- nodes[nodes$col == "output" & nodes$id %in% out_ids, , drop = FALSE]
    if (!nrow(orow) && any(nodes$col == "output")) orow <- nodes[nodes$col == "output", , drop = FALSE]
    hit_pnl <- if (nrow(orow)) grep("resultat|pnl|compte", paste(orow$id, orow$title), ignore.case = TRUE) else integer()
    if (length(hit_pnl)) orow <- orow[hit_pnl[[1]], , drop = FALSE] else if (nrow(orow)) orow <- orow[1, , drop = FALSE]
    if (is.null(srow) || !nrow(rrow) || !nrow(orow)) {
      NULL
    } else {
      shiny::tags$div(
        class = "fpa-one-path",
        shiny::tags$p(class = "fpa-path-kicker", fpa_screen("map_path_kicker")),
        shiny::tags$p(
          class = "fpa-one-path-line",
          shiny::tags$span(srow$title[[1]]),
          shiny::tags$span(class = "fpa-one-path-arrow", "→"),
          shiny::tags$span(rrow$title[[1]]),
          shiny::tags$span(class = "fpa-one-path-arrow", "→"),
          shiny::tags$span(orow$title[[1]])
        ),
        shiny::tags$p(fpa_screen("map_path_note"))
      )
    }
  })
  rows <- if (!nrow(chain$edges)) NULL else lapply(seq_len(nrow(chain$edges)), function(i) {
    e <- chain$edges[i, , drop = FALSE]
    from <- nodes[nodes$id == e$from, , drop = FALSE]
    to <- nodes[nodes$id == e$to, , drop = FALSE]
    if (!nrow(from) || !nrow(to)) return(NULL)
    shiny::tags$tr(
      shiny::tags$td(from$title),
      shiny::tags$td(fpa_chain_frame_label(from$frame)),
      shiny::tags$td(if (identical(from$col, "rule")) from$title else to$title),
      shiny::tags$td(if (identical(to$col, "output")) to$title else ""),
      shiny::tags$td(from$status)
    )
  })
  shiny::tagList(
    shiny::tags$style(HTML("
      .tab-pane:has(.fpa-chain) { height:auto !important; overflow:visible !important; }
      .fpa-chain { padding:0.4rem 0.2rem 2rem; }
      .fpa-map-ask { display:flex; flex-wrap:wrap; align-items:center; gap:8px 12px; margin:0 0 10px; }
      .fpa-map-ask label { font-weight:700; color:#0f2f3a; font-size:15px; margin:0; }
      .fpa-map-ask select {
        height:34px; padding:0 10px; border:1px solid #1f4e5f; border-radius:8px;
        background:#fff; color:#1f4e5f; font:inherit; font-weight:600;
      }
      .fpa-map-howto { margin:0 0 12px; padding:0 20px 18px; }
      .fpa-fold.fpa-map-howto > summary { margin:0 -20px; padding:14px 20px 12px 14px; }
      .fpa-map-howto > p { margin:12px 0; color:#3d4c54; font-size:13px; line-height:1.45; }
      .fpa-map-howto .fpa-frames { margin:4px 0 16px; gap:12px; }
      .fpa-map-howto .fpa-one-path { margin:16px 0 0; }
      .fpa-map-howto .fpa-one-path p { margin:8px 0; }
      .fpa-map-howto .fpa-one-path p:last-child { margin-bottom:0; }
      .fpa-chain h3 { margin:0 0 0.15rem; font-size:15px; }
      .fpa-col-source { background:#f4f8f9; border-radius:12px; padding:12px; }
      .fpa-col-source h3 { color:#1f4e5f; }
      .fpa-col-rule { background:#fff; border:1px solid #d6e1e5; border-radius:12px; padding:12px; }
      .fpa-col-rule h3 { color:#1f4e5f; }
      .fpa-col-out { background:#0f2f3a; border-radius:12px; padding:12px; }
      .fpa-col-out h3, .fpa-col-out > p { color:#fff; }
      .fpa-file-label, .fpa-rule-label {
        font-size:11px; font-weight:700; letter-spacing:0.04em; text-transform:uppercase;
        margin:8px 0 6px;
      }
      .fpa-file-history .fpa-file-label { color:#1f4e5f; }
      .fpa-file-rolling .fpa-file-label { color:#8a5a00; }
      .fpa-file-plan .fpa-file-label { color:#0f2f3a; }
      .fpa-frames { display:grid; grid-template-columns:repeat(3, minmax(0, 1fr)); gap:8px; margin:0 0 0.8rem; }
      @media (max-width: 720px) { .fpa-frames { grid-template-columns:1fr; } }
      .fpa-frame { border-radius:8px; padding:12px 14px; font-size:13px; line-height:1.4; text-align:left; }
