      .fpa-chain-grid { display:grid; grid-template-columns:repeat(3, minmax(0, 1fr)); gap:14px; align-items:start; width:100%; }
      @media (max-width: 980px) { .fpa-chain-grid { grid-template-columns:1fr; } }
