      .fpa-file-stamps { margin:2px 0 6px; }
      .fpa-file-stamps p { margin:0; font-size:12px; line-height:1.45; color:#3d4c54; }
      .fpa-file-fresh { display:inline; background:#e7f2fb; border-radius:4px; padding:1px 5px; white-space:nowrap; }
      .fpa-path-warn {
        margin:0 0 10px; padding:8px 10px; border-radius:8px;
        background:#f8eeee; border:1px solid #e4c8c8;
