      .fpa-raw-wrap th, .fpa-raw-wrap td {
        white-space:nowrap; padding:5px 12px; font-size:12.5px; border-bottom:1px solid #e6edef;
      }
      .fpa-raw-wrap th { position:sticky; top:0; background:#1f4e5f; color:#fff; z-index:2; font-weight:600; }
      .fpa-raw-wrap td.num { text-align:right; font-variant-numeric:tabular-nums; }
      .fpa-raw-wrap .form-group { margin:0; }
      .fpa-raw-wrap .form-control {
        min-width:7.5rem; border:1px solid #1f4e5f; border-radius:8px;
        font-variant-numeric:tabular-nums; padding:4px 8px; height:auto;
      }
      .fpa-raw-wrap tr:nth-child(even) td { background:#f6f9fa; }
      .modal-dialog.modal-xl { max-width:min(1180px, 96vw); }
      .modal-footer .btn-primary { background:#1f4e5f; border-color:#1f4e5f; border-radius:8px; }
      .modal-footer .btn-primary:hover { background:#163844; }
      .fpa-card-history { background:#f3f8f9; border-left-color:#1f4e5f; }
      .fpa-card-rolling { background:#fffaf3; border-left-color:#c47b2b; }
      .fpa-card-plan { background:#eef3f5; border-left-color:#3d5c66; }
      .fpa-card-read { background:#fff; border-left-color:#7d9299; border-left-style:dashed; }
      .fpa-card-calc { background:#e7f2f4; border-left-color:#1f4e5f; }
      .fpa-card-out { background:#fff; border-left-color:#0f2f3a; }
      .fpa-cat {
        display:inline-block; font-size:10px; font-weight:700; letter-spacing:0.05em;
        text-transform:uppercase; padding:2px 6px; border-radius:4px; margin-bottom:4px;
      }
      .fpa-cat-history { background:#1f4e5f; color:#fff; }
      .fpa-cat-rolling { background:#c47b2b; color:#fff; }
      .fpa-cat-plan { background:#3d5c66; color:#fff; }
      .fpa-cat-read { background:#fff; color:#3d4c54; border:1px solid #7d9299; }
      .fpa-cat-calc { background:#1f4e5f; color:#fff; }
      .fpa-cat-out { background:#0f2f3a; color:#fff; }
      .fpa-fold-tools { display:flex; flex-wrap:wrap; gap:8px; margin:0 0 10px; }
      .fpa-chain-col .fpa-fold { margin:0 0 6px; border:0; background:transparent; border-radius:0; }
      .fpa-chain-col .fpa-fold > summary {
        display:grid; grid-template-columns:12px minmax(0, 1fr) auto;
        column-gap:8px; align-items:baseline;
        list-style:none; padding:4px 0 6px; font-weight:700; text-align:left;
      }
      .fpa-chain-col .fpa-fold > summary::before {
        content:''; margin:0; width:0; height:0; justify-self:center;
        border-style:solid; border-width:4px 0 4px 6px;
        border-color:transparent transparent transparent #5c6b73;
      }
      .fpa-chain-col .fpa-fold[open] > summary::before {
        border-width:6px 4px 0 4px;
        border-color:#5c6b73 transparent transparent transparent;
      }
      .fpa-fold-title { text-align:left; }
      .fpa-fold-count { font-size:12px; font-weight:600; color:#5c6b73; white-space:nowrap; text-align:right; }
      .fpa-col-out .fpa-fold-title, .fpa-col-out .fpa-fold-count, .fpa-col-out .fpa-fold > summary::before { color:#d6e7ec; }
      .fpa-span { margin:0 0 14px; }
      .fpa-span-legend { display:flex; flex-wrap:wrap; gap:8px 18px; margin:2px 0 10px; font-size:12.5px; color:#3d4c54; }
      .fpa-span-legend span { display:inline-flex; align-items:center; gap:7px; }
      .fpa-span-legend i { display:inline-block; width:22px; height:8px; border-radius:4px; }
      .fpa-span-legend i.is-history { background:#1f4e5f; }
      .fpa-span-legend i.is-rolling { background:#c47b2b; }
      .fpa-span-legend i.is-plan { background:#6b3fa0; }
      .fpa-span-legend i.is-manual { background:#3b6fb6; border-radius:50%; width:10px; height:10px; }
      .fpa-span-row, .fpa-span-head {
        display:grid; grid-template-columns:minmax(140px, 220px) 1fr minmax(200px, 320px);
        gap:8px; align-items:center; margin:3px 0;
      }
      .fpa-span-name { font-size:13px; font-weight:600; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
      .fpa-span-track { position:relative; display:block; height:16px; background:#eef3f4; border-radius:8px; }
      .fpa-span-track.is-ruler { height:18px; background:#f4f7f8; }
      .fpa-span-row.is-ruler .fpa-span-name { color:#5c6b73; font-weight:600; font-size:12px; }
      .fpa-year-seg {
        position:absolute; top:2px; height:14px; border-radius:3px; box-sizing:border-box;
        font-size:10px; font-weight:700; line-height:14px; text-align:center;
        overflow:hidden; color:#0f2f3a; white-space:nowrap;
      }
      .fpa-year-seg.is-civil { background:#d9e6ea; }
      .fpa-year-seg.is-fy { background:#fff; border:1px solid #1f4e5f; line-height:12px; }
      .fpa-span-bar { position:absolute; top:3px; height:10px; border-radius:5px; background:#1f4e5f; }
      .fpa-span-dot {
        position:absolute; top:2px; width:12px; height:12px; margin-left:-6px;
        border-radius:50%; background:#1f4e5f;
      }
      .fpa-span-dot.is-rolling { background:#c47b2b; }
      .fpa-span-dot.is-plan { background:#6b3fa0; }
      .fpa-span-dot.is-late { background:#8c3a3a; }
      .fpa-span-dot.is-manual { background:#3b6fb6; z-index:3; cursor:pointer; }
      .fpa-span-row.is-off .fpa-span-dot.is-manual { opacity:0.35; }
      .fpa-span-row.is-off .fpa-span-name { opacity:0.72; }
      .fpa-span-rolling { background:#c47b2b; }
      .fpa-span-plan { background:#6b3fa0; }
      .fpa-span-bar.is-late { background:#8c3a3a; }
      .fpa-span-bar.has-ahead { border-top-right-radius:0; border-bottom-right-radius:0; }
      .fpa-span-ahead { position:absolute; top:3px; height:10px; border-radius:0 5px 5px 0; background:#1f4e5f; opacity:0.35; }
      .fpa-span-today { position:absolute; top:-2px; width:2px; height:20px; background:#0f2f3a; z-index:2; }
      .fpa-span-meta { justify-self:start; max-width:100%; font-size:12px; color:#3d4c54; padding:3px 8px; border-radius:6px; }
      .fpa-span-meta.is-late { color:#8c3a3a; font-weight:700; background:#f4d6d6; }
      .fpa-span-row.is-source { cursor:pointer; }
      .fpa-span-row.is-source:hover .fpa-span-track { outline:1px solid #1f4e5f; }
      .fpa-span-row.is-late:hover .fpa-span-meta.is-late { outline:1px solid #8c3a3a; }
      .fpa-chain-title, .fpa-chain-sub { overflow-wrap:anywhere; }
      .fpa-chain-title { display:block; font-weight:700; font-size:14.5px; }
      .fpa-chain-sub { display:block; color:#5c6b73; font-size:12.5px; line-height:1.35; margin-top:3px; }
      .fpa-chain-status {
        display:inline-block; margin-top:6px; border-radius:999px; padding:2px 8px;
        font-size:11.5px; font-weight:700;
      }
      .fpa-chain-side {
        margin-top:12px; border:1px solid #d6e1e5; border-radius:10px; padding:12px 14px; background:#fff;
      }
      .fpa-gaps { border:1px solid #e0cba8; background:#fdf6ea; border-radius:10px; padding:10px 12px; margin:0 0 12px; }
      .fpa-budget-year {
        grid-column:1 / -1; margin:2px 0 12px; padding:10px 12px; border-radius:8px;
        background:#f8eeee; border:1px solid #e4c8c8;
      }
      .fpa-budget-year p { margin:0 0 8px; color:#0f2f3a; font-size:13px; line-height:1.45; }
      .fpa-budget-year label { display:block; margin:0 0 6px; font-weight:700; color:#0f2f3a; }
      .fpa-budget-year select {
        height:34px; padding:0 10px; border:1px solid #1f4e5f; border-radius:8px;
        background:#fff; color:#1f4e5f; font:inherit; font-weight:600;
      }
      .fpa-budget-year .hint { margin:8px 0 0; color:#3d4c54; font-size:12.5px; }
      .fpa-span-stale {
        margin:0 0 12px; padding:10px 12px; border-radius:8px;
        background:#fdf6ea; border:1px solid #e0cba8;
      }
      .fpa-span-stale p { margin:0 0 8px; color:#5a4420; font-size:13px; line-height:1.4; }
    ")),
    shiny::div(
      class = "fpa-chain",
      if (length(asks)) shiny::tags$div(
        class = "fpa-map-ask",
        shiny::tags$label(`for` = "fpa-map-ask-sel", fpa_screen("map_ask")),
        shiny::tags$select(
          id = "fpa-map-ask-sel",
          onchange = "Shiny.setInputValue('chain_focus', this.value, {priority:'event'})",
          lapply(seq_along(asks), function(i) {
            shiny::tags$option(value = unname(asks[[i]]), selected = if (identical(unname(asks[[i]]), selected)) NA else NULL, names(asks)[[i]])
          }),
          shiny::tags$option(value = "none", selected = if (!nzchar(selected)) NA else NULL, fpa_screen("map_ask_none"))
        )
      ),
      shiny::tags$details(
        class = "fpa-fold fpa-map-howto",
        shiny::tags$summary(shiny::tags$span(class = "fpa-fold-title", fpa_screen("map_howto"))),
        shiny::tags$p(
          fpa_screen("loc_chain_lead"),
          fpa_screen("loc_file_not_rule")
        ),
        shiny::div(
          class = "fpa-frames",
          shiny::div(class = "fpa-frame", style = "background:#e6f1f4;color:#0f2f3a;", shiny::tags$b(fpa_screen("man_pop_hist")), fpa_screen("loc_hist_blurb")),
          shiny::div(class = "fpa-frame", style = "background:#fdf6ea;color:#5a4420;", shiny::tags$b(fpa_screen("loc_frame_track")), fpa_screen("loc_track_blurb")),
          shiny::div(class = "fpa-frame", style = "background:#e8eef0;color:#0f2f3a;", shiny::tags$b(fpa_screen("loc_frame_plan")), fpa_screen("loc_plan_blurb"))
        ),
        shiny::tags$p(fpa_screen("loc_chain_legend")),
        if (nrow(cov)) shiny::tagList(
          shiny::tags$p(fpa_screen("loc_chain_today")),
          shiny::tags$p(fpa_screen("span_plan_note")),
          shiny::tags$p(fpa_screen("span_ruler_note")),
          shiny::tags$p(fpa_screen("catchup_click"))
        ),
        one_path
      ),
      if (length(chain$gaps)) shiny::div(
        class = "fpa-gaps",
        shiny::tags$strong(fpa_screen("loc_to_treat")),
        paste(chain$gaps, collapse = " ")
      ),
      if (!chain$read) shiny::tags$p(fpa_screen("loc_calc_not_reread")),
      local({
        stale <- if (is.null(paths)) character(0) else fpa_shiny_newer_sources(config, paths)
        if (!length(stale)) return(NULL)
        shiny::tags$div(
          class = "fpa-span-stale",
          shiny::tags$p(fpa_screen("map_sync_stale", paste(stale, collapse = ", "))),
          shiny::tags$button(
            type = "button",
            class = "fpa-map-btn fpa-map-btn-primary",
            onclick = "var b=document.getElementById('sync'); if(b) b.click();",
            fpa_screen("nav_sync")
          )
        )
      }),
      if (nrow(cov)) shiny::tags$div(
        class = "fpa-span",
        shiny::tags$h3(fpa_screen("loc_how_far_file")),
        shiny::tags$div(
          class = "fpa-span-legend",
          shiny::tags$span(shiny::tags$i(class = "is-history"), fpa_screen("span_key_history")),
          shiny::tags$span(shiny::tags$i(class = "is-rolling"), fpa_screen("span_key_rolling")),
          shiny::tags$span(shiny::tags$i(class = "is-plan"), fpa_screen("span_key_plan")),
          shiny::tags$span(shiny::tags$i(class = "is-manual"), fpa_screen("man_file"))
        ),
        shiny::tags$div(
          class = "fpa-span-head",
          shiny::tags$span(""),
          shiny::tags$span(class = "fpa-span-track", shiny::tags$span(class = "fpa-span-today", style = sprintf("left:%.2f%%;", cov$today_pct[[1]]))),
          shiny::tags$span("aujourd'hui")
        ),
        ruler_row("civil", fpa_screen("span_year"), fpa_screen("span_year_meta")),
        ruler_row("fiscal", fpa_screen("span_fy"), fy_meta),
        lapply(seq_len(nrow(cov)), function(i) {
          g <- cov[i, , drop = FALSE]
          sid <- sub("^src:", "", as.character(g$id))
          src_row <- NULL
          for (s in config$sources %||% list()) {
            if (identical(as.character(s$source_id %||% ""), sid)) src_row <- s
          }
          year_need <- fpa_budget_needs_year(src_row, fy_end)
          dot <- identical(as.character(g$mark), "dot")
          meta <- if (identical(g$state, "non daté")) {
            "pas de date"
          } else if (identical(as.character(g$state), "en vigueur")) {
            fpa_screen("span_in_force", fpa_ym_fr(format(g$start, "%Y-%m")))
          } else if (dot) {
            paste0(
              if (identical(as.character(g$state), "instantané")) {
                fpa_screen("span_situation", format(g$start, "%Y-%m"))
              } else {
                fpa_screen("span_one_date", format(g$start, "%Y-%m"))
              },
              if (!identical(g$state, "instantané")) paste0(" · ", g$state) else ""
            )
          } else if (!is.null(year_need)) {
            paste0(fpa_screen("span_age", g$months_back), " · ", format(g$start, "%Y-%m"), " → ", format(g$end, "%Y-%m"))
          } else {
            paste0(fpa_screen("span_age", g$months_back), " · ", format(g$start, "%Y-%m"), " → ", format(g$end, "%Y-%m"), " · ", g$state)
          }
          bar <- if (dot && is.finite(g$left_pct)) {
            shiny::tags$span(
              class = paste(
                "fpa-span-dot",
                paste0("is-", g$frame),
                if (identical(g$state, "en retard")) "is-late" else ""
              ),
              style = sprintf("left:%.2f%%;", g$left_pct)
            )
          } else if (is.finite(g$left_pct)) shiny::tags$span(
            class = paste(
              "fpa-span-bar",
              paste0("fpa-span-", g$frame),
              if (is.finite(g$ahead_pct) && g$ahead_pct > 0.2) "has-ahead" else "",
              if (identical(g$state, "en retard")) "is-late" else ""
            ),
            style = sprintf("left:%.2f%%;width:%.2f%%;", g$left_pct, max(g$width_pct, 0.8))
          )
          ahead <- if (is.finite(g$ahead_pct) && g$ahead_pct > 0.2) shiny::tags$span(
            class = "fpa-span-ahead",
            style = sprintf("left:%.2f%%;width:%.2f%%;", g$today_pct, g$ahead_pct)
          )
          late <- identical(as.character(g$state), "en retard")
          safe_id <- gsub("[^A-Za-z0-9_:.-]", "", as.character(g$id))
          row <- shiny::tags$div(
            class = paste("fpa-span-row is-source", if (late) "is-late"),
            title = fpa_screen("raw_view"),
            onclick = sprintf(
              "Shiny.setInputValue('raw_file','%s',{priority:'event'})",
              safe_id
            ),
            shiny::tags$span(class = "fpa-span-name", g$title),
            shiny::tags$span(
              class = "fpa-span-track",
              bar, ahead,
              shiny::tags$span(class = "fpa-span-today", style = sprintf("left:%.2f%%;", g$today_pct))
            ),
            shiny::tags$span(class = paste("fpa-span-meta", if (identical(g$state, "en retard")) "is-late" else ""), meta)
          )
          shiny::tagList(row, fpa_shiny_budget_year_ask(year_need, sid))
        }),
        local({
          win <- fpa_chain_window(cov)
          cur <- tryCatch(fpa_manual_read(config), error = function(e) NULL)
          df <- if (is.null(cur)) NULL else fpa_manual_active(cur$data)
          n <- if (is.null(df)) 0L else nrow(df)
          dots <- if (!is.null(win) && n > 0L) {
            lapply(seq_len(n), function(i) {
              d <- fpa_manual_parse_date(df$date_effet[[i]])
              if (!is.finite(d)) return(NULL)
              pct <- as.numeric(d - win$lo) / win$span * 100
              if (!is.finite(pct)) return(NULL)
              tip <- paste(
                as.character(df$libelle[[i]]),
                as.character(df$sens[[i]]),
                format(round(df$montant[[i]]), big.mark = " ", scientific = FALSE),
                "EUR",
                as.character(d)
              )
              shiny::tags$span(
                class = "fpa-span-dot is-manual",
                style = sprintf("left:%.2f%%;", pct),
                title = tip,
                onclick = "event.stopPropagation(); Shiny.setInputValue('raw_file','manual:ledger',{priority:'event'})"
              )
            })
          } else {
            NULL
          }
          shiny::tags$div(
            class = if (isTRUE(fpa_manual_applied(config))) "fpa-span-row is-source" else "fpa-span-row is-source is-off",
            title = fpa_screen("man_file"),
            onclick = "Shiny.setInputValue('raw_file','manual:ledger',{priority:'event'})",
            shiny::tags$span(class = "fpa-span-name", fpa_screen("man_file")),
            shiny::tags$span(
              class = "fpa-span-track",
              dots,
              if (!is.null(win)) shiny::tags$span(
                class = "fpa-span-today",
                style = sprintf("left:%.2f%%;", as.numeric(win$today - win$lo) / win$span * 100)
              )
            ),
            shiny::tags$span(
              class = "fpa-span-meta",
              fpa_screen(
                if (isTRUE(fpa_manual_applied(config))) "man_span_meta" else "man_span_off",
                as.character(n)
              )
            )
          )
        })
      ),
      shiny::div(
        class = "fpa-chain-grid",
        shiny::tags$div(
          class = "fpa-chain-col fpa-col-source",
          shiny::tags$div(
            class = "fpa-file-head",
            shiny::tags$h3("Fichiers"),
            shiny::tags$button(
              type = "button",
              class = "fpa-map-btn fpa-map-btn-primary",
              title = fpa_screen("nav_sync_title"),
              onclick = "var b=document.getElementById('sync'); if(b) b.click();",
              fpa_screen("nav_sync_group")
            )
          ),
          {
            gone <- src[as.character(src$status) == "absent", , drop = FALSE]
            if (!nrow(gone)) {
              NULL
            } else {
              shiny::tags$div(
                class = "fpa-path-warn",
                lapply(seq_len(nrow(gone)), function(i) {
                  title <- as.character(gone$title[[i]])
                  path <- if ("path" %in% names(gone)) as.character(gone$path[[i]] %||% "") else ""
                  shiny::tags$p(
                    if (nzchar(path)) fpa_screen("map_path_missing", title, path) else fpa_screen("map_path_empty", title)
                  )
                })
              )
            }
          },
          fold_tools(),
          file_stack(src)
        ),
        shiny::tags$div(
          class = "fpa-chain-col fpa-col-rule",
          shiny::tags$h3(fpa_screen("loc_rules")),
          fold_tools(),
          fold("fpa-fold-read", "Lecture", reads, stack(reads)),
          fold("fpa-fold-calc", "Calcul", calcs, stack(calcs))
        ),
        shiny::tags$div(
          class = "fpa-chain-col fpa-col-out",
          shiny::tags$h3("Sorties"),
          fold_tools(),
          fold("fpa-fold-out", "Sorties", outs, stack(outs))
        )
      ),
      shiny::div(
        class = "fpa-chain-side",
        if (!nrow(picked)) {
          shiny::tags$p(fpa_screen("loc_pick_card"))
        } else {
          shiny::tagList(
            shiny::tags$strong(picked$title[[1]]),
            shiny::tags$p(picked$detail[[1]]),
            if (length(path_bits) > 1L) shiny::tags$p(paste(path_bits, collapse = " → "))
          )
        }
      ),
      if (length(rows)) shiny::tags$div(
        style = "margin-top:12px;border:1px solid #d6e1e5;border-radius:8px;overflow:auto;",
        shiny::tags$table(
          style = "width:100%;border-collapse:collapse;font-size:13px;",
          shiny::tags$thead(shiny::tags$tr(
            lapply(c("Depuis", "Cadre", fpa_screen("loc_rule"), "Sortie", "État"), function(h) {
              shiny::tags$th(style = "text-align:left;background:#1f4e5f;color:#fff;padding:8px 10px;", h)
            })
          )),
          shiny::tags$tbody(rows)
        )
      )
    )
  )
}

fpa_shiny_map_tree <- function(config) {
  co <- config$company %||% list()
  files <- fpa_shiny_map_files(config)
  columns <- fpa_shiny_map_columns(config)
  srcs <- config$sources %||% list()
  file_nodes <- if (!nrow(files)) {
    list(shiny::tags$p(fpa_screen("loc_no_file")))
  } else {
    lapply(seq_len(nrow(files)), function(i) {
    src_name <- files$Source[[i]]
    cols <- if (nrow(columns)) columns[columns$Source == src_name, , drop = FALSE] else columns
    declared <- character(0)
    mapped <- character(0)
    if (i <= length(srcs)) {
      declared <- as.character(unlist(srcs[[i]]$headers_declared %||% list()))
      mapped <- names(srcs[[i]]$column_map %||% list())
    }
    missing <- setdiff(declared, mapped)
    gap <- if (length(missing)) {
      shiny::tags$p(
        style = "color:#8c3a3a;margin:0.2rem 0 0.4rem;",
        paste(fpa_screen("loc_without_role"), paste(missing, collapse = ", "))
      )
    } else {
      NULL
    }
    summary <- paste(
      src_name,
      files$Fichier[[i]],
      if (files$Present[[i]] == "oui") "présent" else "absent",
      files$Grain[[i]],
      files$Disposition[[i]],
      sep = " · "
    )
    fpa_shiny_branch(
      summary,
      if (!is.null(cols) && nrow(cols)) {
        fpa_shiny_plain_table(cols[, c("Colonne_fichier", "Role_moteur", "Periode"), drop = FALSE])
      } else {
        shiny::tags$p(fpa_screen("loc_no_column_mapped"))
      },
      gap
    )
    })
  }
  line_sets <- list(
    list("Compte de résultat", config$line_map),
    list("Bilan", config$line_map_bs),
    list("Budget", config$line_map_budget)
  )
  line_nodes <- lapply(line_sets, function(pair) {
    df <- fpa_shiny_named_map(pair[[2]], pair[[1]])
    fpa_shiny_branch(
      if (nrow(df)) paste0(pair[[1]], " · ", nrow(df), fpa_screen("loc_labels_sp")) else pair[[1]],
      if (nrow(df)) fpa_shiny_plain_table(df[, c("Libelle_fichier", "Ligne_moteur"), drop = FALSE]) else shiny::tags$p("Aucune ligne.")
    )
  })
  drivers <- fpa_shiny_map_drivers(config)
  shiny::tags$div(
    class = "fpa-map",
    style = "height:auto;overflow:visible;padding:0.6rem 0.2rem 2rem;",
    shiny::tags$div(
      class = "fpa-map-actions",
      shiny::tags$button(
        type = "button",
        class = "fpa-map-btn fpa-map-btn-primary",
        onclick = "document.querySelectorAll('.fpa-map details').forEach(function(d){ d.open = true })",
        shiny::HTML('<svg viewBox="0 0 16 16" width="15" height="15" aria-hidden="true"><path d="M3.2 6.2 8 10.2l4.8-4" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/><path d="M3.2 9.4 8 13.4l4.8-4" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>'),
        shiny::tags$span("Tout ouvrir")
      ),
      shiny::tags$button(
        type = "button",
        class = "fpa-map-btn",
        onclick = "document.querySelectorAll('.fpa-map details').forEach(function(d){ d.open = false })",
        shiny::HTML('<svg viewBox="0 0 16 16" width="15" height="15" aria-hidden="true"><path d="M3.2 9.8 8 5.8l4.8 4" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/><path d="M3.2 6.6 8 2.6l4.8 4" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>'),
        shiny::tags$span("Tout fermer")
      )
    ),
    shiny::tags$p(
      style = "margin-bottom:0.8rem;",
      shiny::tags$strong(as.character(co$name %||% "")),
      " · ", as.character(co$industry_tag %||% ""),
      " · ", as.character(co$currency %||% ""),
      fpa_screen("loc_close_month_chip"), as.character(co$fiscal_year_end_month %||% ""),
      " · horizon ", as.character(config$horizon_months %||% "")
    ),
    fpa_shiny_branch("Fichiers", file_nodes, open = TRUE),
    fpa_shiny_branch("Lignes", line_nodes, open = TRUE),
    fpa_shiny_branch(
      if (nrow(drivers)) paste0("Leviers · ", nrow(drivers)) else "Leviers",
      if (nrow(drivers)) fpa_shiny_plain_table(drivers) else shiny::tags$p(fpa_screen("loc_no_lever"))
    )
  )
}

