        }
        .fpa-menu-btn:hover, .fpa-menu-btn:focus { background:rgba(255,255,255,0.16); outline:none; }
        .fpa-menu-btn[aria-expanded=true] { background:#fff; color:#0f2f3a; border-color:#fff; }
        body.fpa-params-mode .fpa-menu-btn { display:none; }
      }
      .fpa-menu-btn svg { flex:0 0 auto; }
      .fpa-menu-txt { display:flex; flex-direction:column; min-width:0; line-height:1.1; }
