        white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
      }
      .fpa-menu-cur { font-size:14px; font-weight:700; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
      .fpa-menu-cur .fpa-nav-check { display:none; }
      .fpa-menu {
        position:fixed; left:8px; width:min(320px, 92vw); z-index:3500; overflow-y:auto;
        padding:6px; background:#fff; border:1px solid #d6e1e5; border-radius:10px;
        box-shadow:0 12px 32px rgba(15,47,58,0.28);
      }
      .fpa-menu-block {
        margin:8px 2px 0; padding:2px 4px 4px;
        background:#f4f8f9; border:1px solid #e6edef; border-left:4px solid #1f4e5f; border-radius:8px;
      }
      .fpa-menu-k {
        display:flex; align-items:center; gap:6px; margin:4px 8px 2px; padding:2px 0 5px;
        border-bottom:1px solid #d6e1e5;
        font-size:11px; font-weight:700; letter-spacing:0.09em; text-transform:uppercase; color:#1f4e5f;
      }
      .fpa-menu-item {
        display:flex; align-items:center; gap:6px; width:100%; min-height:36px;
        padding:6px 10px 6px 14px; border:0; border-radius:8px; background:transparent;
        color:#0f2f3a; font-size:14px; font-weight:500; text-align:left; cursor:pointer;
      }
      .fpa-menu-item.is-home { min-height:40px; margin:2px 0; padding-left:12px; font-weight:700; }
      .fpa-menu-item:hover, .fpa-menu-item:focus { background:#fff; outline:none; }
      .fpa-menu-item.is-on { background:#fff; box-shadow:inset 4px 0 0 #c9a227; font-weight:700; }
      .fpa-menu .fpa-nav-check { color:#1f4e5f; margin-left:auto; }
      /* Card folds: CSS triangle in col 1; title never under the chevron */
      .fpa-fold {
        border:1px solid #d6e1e5; border-radius:10px; background:#fff; margin:0 0 10px;
      }
      .fpa-fold.is-act { border-color:#e0c4c4; background:#fdf8f8; }
      .fpa-fold.is-watch { border-color:#e0cba8; background:#fdf6ea; }
      .fpa-fold.is-hold { border-color:#d6e1e5; background:#f4f8f8; }
      .fpa-fold.is-act .fpa-fold-k { color:#8c3a3a; }
      .fpa-fold.is-watch .fpa-fold-k { color:#5a4420; }
      .fpa-fold.is-hold .fpa-fold-k { color:#1f4e5f; }
      .fpa-fold.is-act > summary::before { border-color:transparent transparent transparent #8c3a3a; }
      .fpa-fold.is-act[open] > summary::before { border-color:#8c3a3a transparent transparent transparent; }
      .fpa-fold.is-watch > summary::before { border-color:transparent transparent transparent #5a4420; }
      .fpa-fold.is-watch[open] > summary::before { border-color:#5a4420 transparent transparent transparent; }
      .fpa-fold > summary {
        display:grid; grid-template-columns:12px minmax(0, 1fr); column-gap:10px; row-gap:2px;
        align-items:start; cursor:pointer; list-style:none; padding:12px 14px 12px 12px; line-height:1.35;
      }
      .fpa-fold > summary::-webkit-details-marker { display:none; }
      .fpa-fold > summary::marker { content:''; font-size:0; }
      .fpa-fold > summary::before {
        content:''; grid-column:1; grid-row:1 / span 2; justify-self:center; align-self:start;
        box-sizing:border-box; width:0; height:0; margin:6px 0 0; padding:0;
        border-style:solid; border-width:5px 0 5px 7px;
        border-color:transparent transparent transparent #1f4e5f;
      }
      .fpa-fold[open] > summary::before {
        margin-top:8px;
        border-width:7px 5px 0 5px;
        border-color:#1f4e5f transparent transparent transparent;
      }
      .fpa-fold-sum { grid-column:2; min-width:0; }
      .fpa-fold-k {
        grid-column:2; display:block; font-size:11px; font-weight:700; letter-spacing:0.04em;
        text-transform:uppercase; color:#1f4e5f; margin:0 0 2px; padding:0;
      }
      .fpa-fold-fact { grid-column:2; display:block; font-size:13.5px; font-weight:600; color:#1a2b32; margin:0; }
      .fpa-fold-body { padding:0 14px 12px 34px; }
      .fpa-fold > summary .fpa-scn-flat { grid-column:2; width:auto; max-width:none; }
      .fpa-wws.is-hit { background:#e6f1f4; border-radius:8px; box-shadow:inset 3px 0 0 #1f4e5f; padding:6px 8px; }
      .fpa-chip {
        display:block; margin:2px; padding:4px 8px; border-radius:4px;
        text-align:right; font-variant-numeric:tabular-nums; font-weight:600; line-height:1.35;
      }
      .fpa-opfin {
        display:inline-flex; align-items:center; justify-content:center;
        min-width:28px; margin:0 6px 0 0; padding:1px 6px; border-radius:4px;
        border:1px solid; font-size:10px; font-weight:700; letter-spacing:0.02em; line-height:1.3;
        vertical-align:middle;
      }
      .fpa-opfin.is-op { background:#E8F5E9; border-color:#3FA34D; color:#1B5E20; }
      .fpa-opfin.is-fin { background:#FFEBEE; border-color:#E76F51; color:#B71C1C; }
      .fpa-opfin.is-other { background:#F3F4F6; border-color:#9CA3AF; color:#374151; }
      .fpa-opfin-lab { white-space:normal; }
      .fpa-pnl .fpa-opfin-lab { display:flex; align-items:center; gap:6px; }
      .fpa-opfin-name { vertical-align:middle; min-width:0; }
      .fpa-line-go {
        display:inline; background:none; border:none; padding:0; margin:0;
        color:inherit; font:inherit; font-weight:inherit; text-align:left;
        cursor:pointer; line-height:1.35;
      }
      .fpa-line-go:hover, .fpa-line-go:focus {
        color:#1f4e5f; text-decoration:underline; outline:none;
      }
      .fpa-oi-hit {
        display:block; width:100%; background:transparent; border:0; padding:0; margin:0;
        cursor:pointer; font:inherit; line-height:inherit;
      }
      .fpa-oi-hit .fpa-chip { outline:1px solid #1f4e5f; outline-offset:1px; }
      .fpa-oi-hit:hover .fpa-chip, .fpa-oi-hit:focus-visible .fpa-chip {
        outline:2px solid #0f2f3a; outline-offset:1px;
      }
