      (function () {
        if (window.fpaTipReady) return;
        window.fpaTipReady = true;
        var tip = null;
        function box() {
          if (!tip) { tip = document.createElement('div'); tip.id = 'fpa-tip'; tip.setAttribute('role', 'tooltip'); document.body.appendChild(tip); }
          return tip;
        }
        function place(x, y) {
          var t = box(), w = t.offsetWidth, h = t.offsetHeight;
          var left = Math.min(x + 14, window.innerWidth - w - 8);
          var top = y + 18;
          if (top + h > window.innerHeight - 8) top = y - h - 12;
          t.style.left = Math.max(8, left) + 'px';
          t.style.top = Math.max(8, top) + 'px';
        }
        function show(el, x, y) {
          var txt = el.getAttribute('data-tip');
          if (!txt) return;
          var t = box();
          t.style.minWidth = '';
          t.style.maxWidth = '';
          if (el.getAttribute('data-tip-html') === '1') {
            t.innerHTML = txt;
            t.style.whiteSpace = 'normal';
            t.style.fontVariantNumeric = '';
            t.style.textAlign = 'left';
            t.style.minWidth = '240px';
            t.style.maxWidth = '420px';
          } else if (el.classList.contains('fpa-vh-c') && txt.indexOf('|') !== -1) {
            t.textContent = txt.split('|').join('\\n');
            t.style.whiteSpace = 'pre';
            t.style.fontVariantNumeric = 'tabular-nums';
            t.style.textAlign = 'right';
          } else {
            t.textContent = txt;
            t.style.whiteSpace = '';
            t.style.fontVariantNumeric = '';
            t.style.textAlign = '';
          }
          t.style.display = 'block';
          place(x, y);
        }
        function hide() { if (tip) tip.style.display = 'none'; }
        document.addEventListener('mouseover', function (e) {
          var el = e.target.closest ? e.target.closest('[data-tip]') : null;
          if (el) show(el, e.clientX, e.clientY); else hide();
        });
        document.addEventListener('mousemove', function (e) {
          if (tip && tip.style.display === 'block') place(e.clientX, e.clientY);
        });
        document.addEventListener('focusin', function (e) {
          var el = e.target.closest ? e.target.closest('[data-tip]') : null;
          if (!el) return;
          var r = el.getBoundingClientRect(); show(el, r.left, r.bottom - 8);
        });
        document.addEventListener('focusout', hide);
        document.addEventListener('scroll', hide, true);
      })();
    ")),
