    shiny::tags$script(HTML("
      if (!window.fpaScnDockBound) {
        window.fpaScnDockBound = true;
        function fpaScnClosePops() {
          document.querySelectorAll('.fpa-scn-pop').forEach(function (p) { p.setAttribute('hidden', ''); });
          document.querySelectorAll('.fpa-scn-btn').forEach(function (b) { b.setAttribute('aria-expanded', 'false'); });
          window.fpaScnDockOpen = '';
        }
        document.addEventListener('click', function (ev) {
          if (ev.target.closest('.fpa-scn-gear')) {
            ev.preventDefault();
            if (window.fpaScnSheetOn) window.fpaScnSheetClose();
            else window.fpaScnSheetOpen();
            return;
          }
          if (ev.target.closest('.fpa-scn-sheet')) {
            if (ev.target.closest('.fpa-scn-sheet-x') || ev.target.id === 'fpa-scn-sheet') window.fpaScnSheetClose();
            return;
          }
          var pick = ev.target.closest('.fpa-scn-pick');
          if (pick && window.Shiny) {
            ev.preventDefault();
            Shiny.setInputValue('scn_dock', {
              scope: pick.getAttribute('data-scope'),
              case: pick.getAttribute('data-case'),
              n: Date.now()
            }, {priority: 'event'});
            return;
          }
          var btn = ev.target.closest('.fpa-scn-btn');
          if (btn) {
            ev.preventDefault();
            var dock = btn.closest('.fpa-scn-dock');
            var pop = dock && dock.querySelector('.fpa-scn-pop');
            if (!pop) return;
            var willOpen = pop.hasAttribute('hidden');
            fpaScnClosePops();
            if (willOpen) {
              pop.removeAttribute('hidden');
              btn.setAttribute('aria-expanded', 'true');
              window.fpaScnDockOpen = dock.getAttribute('data-dock') || '';
            }
            return;
          }
          if (!ev.target.closest('.fpa-scn-pop')) {
            fpaScnClosePops();
            if (window.fpaScnSheetOn) window.fpaScnSheetClose();
          }
        });
        document.addEventListener('keydown', function (ev) {
          if (ev.key === 'Escape' && window.fpaScnSheetOn) window.fpaScnSheetClose();
        });
      }
      window.fpaScnSheetOpen = function () {
        var sheet = document.getElementById('fpa-scn-sheet');
        var body = document.getElementById('fpa-scn-sheet-body');
        var wait = document.getElementById('fpa-scn-sheet-wait');
        var title = document.getElementById('fpa-scn-sheet-title');
        var src = document.getElementById('pnl_ranges');
        var sum = document.querySelector('#pnl-fold-pct summary');
        if (!sheet || !body) return;
        if (sheet.parentNode !== document.body) document.body.appendChild(sheet);
        if (title && sum && sum.textContent.replace(/\\s+/g, ' ').trim()) {
          title.textContent = sum.textContent.replace(/\\s+/g, ' ').trim();
        }
        if (src && src.childNodes.length) {
          if (!window.fpaScnRangeHome) window.fpaScnRangeHome = src.parentNode;
          body.appendChild(src);
          if (wait) wait.setAttribute('hidden', '');
        } else if (wait) {
          wait.removeAttribute('hidden');
        }
        sheet.removeAttribute('hidden');
        window.fpaScnSheetOn = true;
      };
      window.fpaScnSheetClose = function () {
        var src = document.getElementById('pnl_ranges');
        var sheet = document.getElementById('fpa-scn-sheet');
        if (src && window.fpaScnRangeHome) window.fpaScnRangeHome.appendChild(src);
        if (sheet) sheet.setAttribute('hidden', '');
        window.fpaScnSheetOn = false;
      };
      window.fpaVarTile = function (btn) {
        var id = btn.getAttribute('aria-controls');
        var panel = document.getElementById(id);
        var root = btn.closest('.fpa-var-hero');
        if (!panel || !root) return;
        var open = btn.getAttribute('aria-expanded') === 'true';
        var tiles = root.querySelectorAll('.fpa-var-tile');
        var panels = root.querySelectorAll('.fpa-var-math');
        var i;
        for (i = 0; i < tiles.length; i++) {
          tiles[i].setAttribute('aria-expanded', 'false');
          tiles[i].classList.remove('is-on');
        }
        for (i = 0; i < panels.length; i++) panels[i].hidden = true;
        if (!open) {
          btn.setAttribute('aria-expanded', 'true');
          btn.classList.add('is-on');
          panel.hidden = false;
        }
      };
      window.fpaVarFolds = function (open) {
        var nodes = document.querySelectorAll('.fpa-var-page details.fpa-var-fold');
        var i;
        for (i = 0; i < nodes.length; i++) nodes[i].open = !!open;
      };
      document.addEventListener('toggle', function (ev) {
        var d = ev.target;
        if (!d || !d.classList || !d.classList.contains('fpa-var-fold') || !d.open) return;
        window.setTimeout(function () { window.dispatchEvent(new Event('resize')); }, 60);
      }, true);
    ")),
