    shiny::tags$script(HTML("
    Shiny.addCustomMessageHandler('fpa-rep-busy', function (msg) {
      document.body.classList.toggle('fpa-rep-busy', !!msg.busy);
      document.body.classList.toggle('fpa-ai-batching', !!msg.busy);
      var stop = document.getElementById('rep_stop');
      if (stop) stop.style.display = msg.busy ? '' : 'none';
    });
    Shiny.addCustomMessageHandler('fpa-rep-file', function (msg) {
      var row = document.getElementById('rep_file_row');
      if (!row) return;
      row.classList.toggle('is-empty', !msg.file);
      var name = row.querySelector('.fpa-rep-file-name');
      if (name) name.textContent = msg.file || msg.nofile || '';
      var url = row.querySelector('.fpa-rep-file-url');
      if (url) {
        url.textContent = msg.url || '';
        if (msg.url) url.setAttribute('href', msg.url); else url.removeAttribute('href');
      }
      var seal = document.getElementById('rep_seal');
      if (seal) {
        seal.style.display = (msg.can_seal || msg.sealed) ? '' : 'none';
        seal.disabled = !!msg.sealed || !msg.can_seal;
      }
      var note = document.getElementById('rep_seal_note');
      if (note) note.textContent = msg.seal_note || '';
    });
    Shiny.addCustomMessageHandler('fpa-rep-open-analyst', function () {
      var d = document.querySelector('.fpa-rep-grp[data-group=\"analyst\"]');
      if (d) d.open = true;
    });
    window.fpaRepExpand = function (open) {
      document.querySelectorAll('.fpa-rep-grp').forEach(function (d) { d.open = !!open; });
    };
    window.fpaRepTick = function (on) {
      document.querySelectorAll('.fpa-rep-el input[type=checkbox]').forEach(function (c) {
        if (c.checked === !!on) return;
        c.checked = !!on;
        c.dispatchEvent(new Event('change', { bubbles: true }));
        if (window.Shiny) Shiny.setInputValue(c.id, !!on, { priority: 'event' });
      });
    };
    ")),
