      .fpa-ai-batch-live[hidden] { display:none !important; }
      .fpa-ai-batch-live .fpa-ai-batch-note { margin:0 0 8px; font-size:13px; font-weight:650; color:#0f2f3a; }
      .fpa-ai-fav-lead { margin: 0 0 12px; font-size: 12.5px; line-height: 1.45; color: #5c6b73; max-width: 62ch; }
      .fpa-ai-tools { display:flex; flex-wrap:wrap; gap:8px; margin:8px 0 0; }
      .fpa-ai-answer-head { display:none; align-items:center; justify-content:space-between; gap:12px; margin:0 0 8px; padding-bottom:8px; border-bottom:1px solid #e6edef; }
      body.fpa-ai-has-answer .fpa-ai-answer-head { display:flex; }
