      .fpa-ai-step[data-state='done'] .btn.fpa-pm-btn:not(#ai_report_add) { background:#fff; color:#1f4e5f; }
      .fpa-ai-step[data-state='ready'] .btn.fpa-pm-btn { background:#fff; color:#1f4e5f; }
      .fpa-ai-step[data-state='later'] { border-style:dashed; background:#fbfdfd; }
