      .fpa-ai-step[data-state='later'] .btn.fpa-pm-btn:hover { background:#e6f1f4; border-color:#1f4e5f; }
      .fpa-ai-step[data-state='current']::after { background:repeating-linear-gradient(90deg, #1f4e5f 0 4px, transparent 4px 7px); }
      .fpa-ai-step[data-state='locked'] { opacity:0.55; background:#f7f8f8; }
      .fpa-ai-step[data-state='locked'] .btn.fpa-pm-btn,
      #ai_report_add:disabled { background:#e6edef; border-color:#c5d0d4; color:#5c6b73; opacity:1; }
      .fpa-ai-report-head h3 { flex-wrap:wrap; line-height:1.35; }
      .fpa-ai-user-row { display:flex; gap:6px; align-items:stretch; margin:0 0 6px; }
      .fpa-ai-user-row .fpa-ai-prompt { margin:0; flex:1 1 auto; }
      .fpa-ai-user-drop { flex:0 0 auto; border:1px solid #c5d0d4; background:#fff; color:#5c6b73; border-radius:8px; padding:6px 8px; cursor:pointer; font-size:12px; }
      .fpa-ai-user-drop:hover { border-color:#8c3a3a; color:#8c3a3a; }
      .fpa-ai-user-empty { margin:6px 0 0; font-size:12.5px; color:#5c6b73; }
      .fpa-ai-prompt-row { display:flex; gap:6px; align-items:stretch; margin:0 0 6px; }
      .fpa-ai-prompt-row .fpa-ai-prompt { margin:0; flex:1 1 auto; }
      .fpa-ai-fav {
        flex:0 0 auto; width:auto; min-width:78px; height:auto; min-height:34px; border:1px solid #c5d0d4; border-radius:8px;
        background:#fff; color:#1f4e5f; cursor:pointer; display:inline-flex; align-items:center; justify-content:center;
        gap:6px; padding:0 8px; font-size:11px; font-weight:700; line-height:1; letter-spacing:0.01em;
      }
      .fpa-ai-fav:hover { border-color:#1f4e5f; background:#e6f1f4; }
      .fpa-ai-fav.is-on { background:#1f4e5f; border-color:#1f4e5f; color:#fff; }
      .fpa-ai-fav .fpa-ai-fav-box {
        width:14px; height:14px; border:1.5px solid currentColor; border-radius:3px; display:inline-block; position:relative;
      }
      .fpa-ai-fav.is-on .fpa-ai-fav-box::after {
        content:''; position:absolute; left:3px; top:0; width:5px; height:9px;
        border:solid #fff; border-width:0 2px 2px 0; transform:rotate(45deg);
      }
      .fpa-ai-sets { margin:14px 0 0; padding:12px; border-radius:8px; background:#f4f8f9; border:1px solid #d6e1e5; }
      .fpa-ai-sets h3 { margin:0 0 6px; font-size:15px; font-weight:700; color:#0f2f3a; }
      .fpa-ai-sets-lead { margin:0 0 10px; font-size:12.5px; line-height:1.45; color:#5c6b73; }
      .fpa-ai-sets-tools { display:flex; flex-wrap:wrap; gap:8px; align-items:flex-end; margin:0 0 10px; }
      .fpa-ai-sets-tools .shiny-input-container { margin-bottom:0 !important; min-width:160px; flex:1 1 160px; }
      .fpa-ai-set-row {
        display:grid; grid-template-columns:28px minmax(0,1fr) auto; gap:6px; align-items:center;
        padding:7px 8px; border:1px solid #d6e1e5; border-radius:8px; background:#fff; margin:0 0 6px;
        cursor:grab;
      }
      .fpa-ai-set-row.is-over { border-color:#1f4e5f; background:#e6f1f4; }
      .fpa-ai-set-row:nth-child(even) { background:#fbfdfd; }
      .fpa-ai-set-num { font-variant-numeric:tabular-nums; font-weight:700; color:#5c6b73; font-size:12px; text-align:center; }
      .fpa-ai-set-name { font-size:13px; color:#0f2f3a; overflow-wrap:anywhere; }
      .fpa-ai-set-name .fpa-ai-set-flag { display:block; font-size:11px; color:#8c3a3a; margin-top:2px; }
      .fpa-ai-set-ops { display:flex; gap:4px; }
      .fpa-ai-set-ops button {
        border:1px solid #c5d0d4; background:#fff; color:#1f4e5f; border-radius:8px; padding:4px 6px; cursor:pointer; line-height:1;
      }
      .fpa-ai-set-ops button:hover { background:#e6f1f4; border-color:#1f4e5f; }
      .fpa-ai-set-ops button.is-danger:hover { border-color:#8c3a3a; color:#8c3a3a; background:#fff; }
      .fpa-ai-sets-add { display:flex; flex-wrap:wrap; gap:8px; align-items:flex-end; margin:8px 0 10px; }
      .fpa-ai-sets-add .shiny-input-container { margin-bottom:0 !important; flex:1 1 160px; }
      .fpa-ai-batch-note { margin:6px 0 0; font-size:12px; color:#5c6b73; font-variant-numeric:tabular-nums; }
      .fpa-ai-batch-bar { height:6px; border-radius:999px; background:#e6edef; margin:8px 0 0; overflow:hidden; }
      .fpa-ai-batch-bar > span { display:block; height:100%; background:#1f4e5f; border-radius:999px; width:0; transition:width .2s; }
      body.fpa-ai-batching #ai_ask,
      body.fpa-ai-batching .fpa-ai-prompt,
      body.fpa-ai-batching #ai_report_start,
      body.fpa-ai-batching #ai_report_add,
      body.fpa-ai-batching #ai_report_final,
      body.fpa-ai-batching #ai_report_into,
      body.fpa-ai-batching #ai_batch_run { opacity:0.55; pointer-events:none; }
      .fpa-ai-file {
        display:flex; align-items:center; gap:10px; flex-wrap:wrap; margin-top:12px; padding:10px 12px;
        border-radius:8px; background:#fff; border:1px dashed #c5d0d4;
      }
      .fpa-ai-file-label { display:flex; align-items:center; gap:6px; font-size:12px; font-weight:700; color:#5c6b73; text-transform:uppercase; letter-spacing:0.04em; }
      .fpa-ai-file-name { flex:1 1 220px; font-size:13px; color:#0f2f3a; font-variant-numeric:tabular-nums; overflow-wrap:anywhere; }
      .fpa-ai-file .btn.fpa-pm-btn { font-size:13px; padding:7px 12px; }
      .btn.fpa-pm-btn.is-danger { background:#fff; color:#8c3a3a; border-color:#8c3a3a; }
      .btn.fpa-pm-btn.is-danger:hover, .btn.fpa-pm-btn.is-danger:focus { background:#8c3a3a; border-color:#8c3a3a; color:#fff; }
      .fpa-ai-file.is-empty .btn.fpa-pm-btn { opacity:0.55; pointer-events:none; }
      .fpa-ai-file.is-empty .fpa-ai-file-name { color:#9aa8ae; }
      @media (max-width: 1200px) { .fpa-ai-steps { grid-template-columns:1fr 1fr; } .fpa-ai-step::after { display:none; } }
      @media (max-width: 900px) { .fpa-ai-page { grid-template-columns:1fr; } }
    ")),
    shiny::tags$script(HTML("
    Shiny.addCustomMessageHandler('fpa-ai-batch', function (msg) {
      document.body.classList.toggle('fpa-ai-batching', !!msg.busy);
      document.querySelectorAll('.fpa-ai-batch-note').forEach(function (note) {
        note.textContent = msg.note || '';
      });
      document.querySelectorAll('.fpa-ai-batch-bar > span').forEach(function (bar) {
        bar.style.width = (msg.pct || 0) + '%';
      });
      document.querySelectorAll('.fpa-ai-batch-live').forEach(function (el) {
        el.hidden = !msg.busy;
      });
      var stop = document.getElementById('ai_batch_stop');
      if (stop) stop.style.display = msg.busy ? '' : 'none';
      var resume = document.getElementById('ai_batch_resume');
      if (resume) resume.style.display = msg.can_resume ? '' : 'none';
    });
    window.fpaAiFold = function (open) {
      var root = document.getElementById('ai_prompts');
      if (!root) return;
      var names = [];
      root.querySelectorAll('details').forEach(function (d) {
        d.open = !!open;
        if (open) {
          var s = d.querySelector('summary');
          if (s) names.push((s.textContent || '').trim());
        }
      });
      window.fpaAiOpenGroups = names;
    };
    Shiny.addCustomMessageHandler('fpa-ai-steps', function (msg) {
      document.body.classList.toggle('fpa-ai-has-answer', !!msg.has_answer);
      (msg.steps || []).forEach(function (s, i) {
        var el = document.querySelector('.fpa-ai-step[data-step=\"' + (i + 1) + '\"]');
        if (!el) return;
        el.setAttribute('data-state', s.state);
        var note = el.querySelector('.fpa-ai-step-note');
        if (note) note.textContent = s.note || '';
        el.querySelectorAll('button.btn').forEach(function (b) {
          var off = s.state === 'locked' || (b.id === 'ai_report_add' && !msg.can_add);
          if (b.id === 'ai_report_into') off = !msg.can_into;
          b.disabled = off;
        });
      });
      var file = document.querySelector('.fpa-ai-file');
      if (file) {
        file.classList.toggle('is-empty', !msg.file);
        var name = file.querySelector('.fpa-ai-file-name');
        if (name) name.textContent = msg.file || msg.nofile || '';
      }
      var old = document.getElementById('ai_sealed_old');
      if (old) old.textContent = msg.sealed_old || '';
    });
    document.addEventListener('click', function (e) {
      var btn = e.target.closest && e.target.closest('.fpa-ai-fav');
      if (!btn) return;
      var root = document.getElementById('ai_prompts');
      if (!root) return;
      var names = [];
      root.querySelectorAll('details').forEach(function (d) {
        if (!d.open) return;
        var s = d.querySelector('summary');
        if (s) names.push((s.textContent || '').trim());
      });
      window.fpaAiOpenGroups = names;
    }, true);
    $(document).on('shiny:value', function (ev) {
      if (!ev || ev.name !== 'ai_prompts') return;
      var names = window.fpaAiOpenGroups || [];
      if (!names.length) return;
      setTimeout(function () {
        var root = document.getElementById('ai_prompts');
        if (!root) return;
        root.querySelectorAll('details').forEach(function (d) {
          var s = d.querySelector('summary');
          var label = s ? (s.textContent || '').trim() : '';
          if (names.indexOf(label) >= 0) d.open = true;
        });
      }, 40);
    });
    var fpaSetDrag = null;
    document.addEventListener('dragstart', function (e) {
      var row = e.target.closest && e.target.closest('.fpa-ai-set-row');
      if (!row || (e.target.closest && e.target.closest('.fpa-ai-set-ops'))) {
        if (e.target.closest && e.target.closest('.fpa-ai-set-ops')) e.preventDefault();
        return;
      }
      fpaSetDrag = parseInt(row.getAttribute('data-i'), 10);
      if (e.dataTransfer) {
        e.dataTransfer.effectAllowed = 'move';
        try { e.dataTransfer.setData('text/plain', String(fpaSetDrag)); } catch (err) {}
      }
    });
    document.addEventListener('dragover', function (e) {
      var row = e.target.closest && e.target.closest('.fpa-ai-set-row');
      if (!row) return;
      e.preventDefault();
      row.classList.add('is-over');
    });
    document.addEventListener('dragleave', function (e) {
      var row = e.target.closest && e.target.closest('.fpa-ai-set-row');
      if (row) row.classList.remove('is-over');
    });
    document.addEventListener('drop', function (e) {
      var row = e.target.closest && e.target.closest('.fpa-ai-set-row');
      if (!row) return;
      e.preventDefault();
      row.classList.remove('is-over');
      var to = parseInt(row.getAttribute('data-i'), 10);
      if (!fpaSetDrag || !to || fpaSetDrag === to || !window.Shiny) return;
      Shiny.setInputValue('ai_set_move', {i: fpaSetDrag, dir: 'to', j: to}, {priority: 'event'});
      fpaSetDrag = null;
    });
    window.fpaAiCopy = function (btn) {
      var t = document.querySelector('.fpa-ai-answer');
      if (!t) return;
      var done = function () {
        btn.classList.add('is-copied');
        setTimeout(function () { btn.classList.remove('is-copied'); }, 1600);
      };
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(t.innerText).then(done).catch(function () {});
      }
    };
    ")),
    shiny::tags$div(
      class = "fpa-ai-page",
      shiny::tags$div(
        class = "fpa-ai-card",
        shiny::tags$div(
          class = "fpa-ai-compose",
          shiny::tags$h2(fpa_screen("ai_title")),
          shiny::tags$p(class = "fpa-ai-fav-lead", fpa_screen("ai_workshop_lead")),
          shiny::textAreaInput("ai_question", fpa_screen("ai_question"), rows = 4, width = "100%"),
          shiny::tags$div(
            class = "fpa-ai-tools",
            shiny::actionButton("ai_ask", fpa_screen("ai_ask"), class = "fpa-pm-btn"),
            shiny::actionButton("ai_prompt_save", fpa_screen("ai_prompt_save"), class = "fpa-pm-btn is-ghost"),
            shiny::actionButton("ai_clear", fpa_screen("ai_clear"), class = "fpa-pm-btn is-ghost")
          )
        ),
        shiny::uiOutput("ai_prompts"),
        shiny::tags$section(
          class = "fpa-ai-sets",
          shiny::tags$h3(fpa_screen("ai_sets_head")),
          shiny::tags$p(class = "fpa-ai-sets-lead", fpa_screen("ai_sets_lead")),
          shiny::tags$div(
            class = "fpa-ai-sets-tools",
            shiny::selectInput("ai_set_pick", fpa_screen("ai_sets_pick"), choices = c(` ` = ""), selected = "", selectize = FALSE, width = "100%"),
            shiny::actionButton("ai_set_new", fpa_screen("ai_sets_new"), class = "fpa-pm-btn"),
            shiny::actionButton("ai_set_rename", fpa_screen("ai_sets_rename"), class = "fpa-pm-btn is-ghost"),
            shiny::actionButton("ai_set_drop", fpa_screen("ai_sets_drop"), class = "fpa-pm-btn is-ghost")
          ),
          shiny::uiOutput("ai_set_list"),
          shiny::tags$div(
            class = "fpa-ai-sets-add",
            shiny::actionButton("ai_set_add_all", fpa_screen("ai_sets_add_all"), class = "fpa-pm-btn")
          ),
          shiny::tags$div(
            class = "fpa-ai-tools",
            shiny::actionButton(
              "ai_batch_run",
              shiny::tagList(shiny::HTML(fpa_pm_icon("play")), shiny::tags$span(fpa_screen("ai_batch_run"))),
              class = "fpa-pm-btn"
            ),
            shiny::actionButton("ai_batch_stop", fpa_screen("ai_batch_stop"), class = "fpa-pm-btn is-ghost", style = "display:none;"),
            shiny::actionButton("ai_batch_resume", fpa_screen("ai_batch_resume"), class = "fpa-pm-btn is-ghost", style = "display:none;")
          ),
          shiny::tags$p(class = "fpa-ai-batch-note"),
          shiny::tags$div(class = "fpa-ai-batch-bar", shiny::tags$span(style = "width:0%;"))
        )
      ),
      shiny::tags$div(
        class = "fpa-ai-card",
        shiny::uiOutput("ai_status"),
        shiny::tags$div(
          class = "fpa-ai-answer-head",
          shiny::tags$h3(shiny::HTML(fpa_pm_icon("ai")), fpa_screen("ai_answer_head")),
          shiny::tags$button(
            type = "button", class = "fpa-ai-copy", onclick = "fpaAiCopy(this)",
            title = fpa_screen("ai_copy"), `aria-label` = fpa_screen("ai_copy"),
            shiny::tags$span(class = "fpa-ai-copy-idle", shiny::HTML(fpa_pm_icon("copy")), fpa_screen("ai_copy")),
            shiny::tags$span(class = "fpa-ai-copy-done", shiny::HTML(fpa_pm_icon("tick")), fpa_screen("ai_copied"))
          )
        ),
        shiny::uiOutput("ai_answer"),
        shiny::tags$div(
          class = "fpa-ai-batch-live",
          hidden = NA,
          shiny::tags$p(class = "fpa-ai-batch-note"),
          shiny::tags$div(class = "fpa-ai-batch-bar", shiny::tags$span(style = "width:0%;"))
        ),
        local({
          ico <- function(name) shiny::HTML(fpa_pm_icon(name))
          step <- function(i, title_key, lead_key, state, ...) {
            shiny::tags$div(
              class = "fpa-ai-step", `data-step` = i, `data-state` = state,
              shiny::tags$div(
                class = "fpa-ai-step-head",
                shiny::tags$span(class = "fpa-ai-step-num", shiny::tags$span(i), ico("tick")),
                shiny::tags$h4(fpa_screen(title_key))
              ),
              shiny::tags$p(class = "fpa-ai-step-lead", fpa_screen(lead_key)),
              shiny::tags$div(class = "fpa-ai-step-body", ...),
              shiny::tags$p(class = "fpa-ai-step-note")
            )
          }
          btn <- function(id, key, icon) {
            shiny::actionButton(id, shiny::tagList(ico(icon), shiny::tags$span(fpa_screen(key))), class = "fpa-pm-btn")
          }
          shiny::tags$section(
            class = "fpa-ai-report",
            shiny::tags$div(
              class = "fpa-ai-report-head",
              shiny::tags$h3(ico("file"), fpa_screen("ai_report_head")),
              shiny::tags$p(fpa_screen("ai_report_lead"))
            ),
            shiny::tags$div(
              class = "fpa-ai-steps",
              step(1, "ai_step1", "ai_step1_lead", "current",
                shiny::textInput("ai_report_title", NULL, placeholder = fpa_screen("ai_report_title_ph"), width = "100%"),
                btn("ai_report_start", "ai_report_start", "file")
              ),
              step(2, "ai_step2", "ai_step2_lead", "locked", btn("ai_report_add", "ai_report_add", "plus")),
              step(3, "ai_step3", "ai_step3_lead", "locked", btn("ai_report_final", "ai_report_final", "pen")),
              step(4, "ai_step4", "ai_step4_lead", "locked", btn("ai_report_into", "ai_to_report", "file"))
            ),
            shiny::tags$div(
              class = "fpa-ai-file is-empty",
              shiny::tags$span(class = "fpa-ai-file-label", ico("folder"), fpa_screen("ai_report_file")),
              shiny::tags$span(class = "fpa-ai-file-name", fpa_screen("ai_report_nofile")),
              shiny::downloadButton("ai_report_file", fpa_screen("ai_report_download"), class = "fpa-pm-btn"),
              shiny::actionButton("ai_report_folder", shiny::tagList(ico("folder"), shiny::tags$span(fpa_screen("ai_report_folder"))), class = "fpa-pm-btn is-ghost"),
              shiny::actionButton("ai_report_erase", shiny::tagList(ico("trash"), shiny::tags$span(fpa_screen("ai_report_erase"))), class = "fpa-pm-btn is-danger")
            ),
            shiny::tags$p(id = "ai_sealed_old", class = "fpa-ai-batch-note")
          )
        }),
        shiny::tags$details(
          shiny::tags$summary(fpa_screen("ai_sent")),
          shiny::uiOutput("ai_sent")
        )
      )
    )
  ),
  bslib::nav_panel(
    title = fpa_screen("nav_params"),
    value = "Paramètres",
    shiny::tags$div(
      class = "fpa-params-page",
      shiny::actionButton(
        "params_back",
        label = shiny::HTML(paste0(
          '<svg viewBox="0 0 16 16" width="18" height="18" aria-hidden="true">',
          '<path d="M10.5 2.5 5 8l5.5 5.5" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>',
          '<path d="M5.2 8H14" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/>',
          '</svg><span>', fpa_screen("nav_params_back"), '</span>'
        )),
        class = "fpa-params-back",
        title = fpa_screen("nav_params_back_title"),
        `aria-label` = fpa_screen("nav_params_back_title")
      ),
      shiny::tags$div(
        class = "fpa-params-body",
        shiny::uiOutput("params_home")
      )
    )
  ),
  bslib::nav_item(
    shiny::div(class = "fpa-year-slot", shiny::uiOutput("header_year"))
  ),
  bslib::nav_spacer(),
  bslib::nav_item(
    shiny::div(
      class = "fpa-nav-tools",
      shiny::uiOutput("header_todo"),
      shiny::uiOutput("header_actions")
    )
  )
)

server <- function(input, output, session) {
  init_cfg <- fpa_shiny_find_config()
  cfg_path <- shiny::reactiveVal(init_cfg)
  boot_lang <- fpa_lang_read_config(init_cfg)
  options(fpa.lang = boot_lang)
  ui_lang <- shiny::reactiveVal(boot_lang)
  session$userData$fpa_lang <- function() ui_lang()
  ai_rev <- shiny::reactiveVal(0L)
  ai_job <- shiny::reactiveVal(NULL)
  ai_answer <- shiny::reactiveVal("")
  ai_sent_txt <- shiny::reactiveVal("")
  ai_status_txt <- shiny::reactiveVal("")
  ai_title_txt <- shiny::reactiveVal("")
  ai_last_report <- shiny::reactiveVal("")
  ai_erase_path <- shiny::reactiveVal("")
  ai_user_rev <- shiny::reactiveVal(0L)
  ai_fav_rev <- shiny::reactiveVal(0L)
  ai_batch <- shiny::reactiveVal(NULL)
  ai_batch_resume_at <- shiny::reactiveVal(NULL)
  ai_from_batch <- shiny::reactiveVal(FALSE)
  ai_pending <- shiny::reactiveVal(NULL)
  ai_preview_pass <- shiny::reactiveVal(FALSE)
  rep_last_html <- shiny::reactiveVal("")
  rep_last_pdf <- shiny::reactiveVal("")
  rep_seal_nudge <- shiny::reactiveVal(0L)
  rep_status_txt <- shiny::reactiveVal("")
  rep_job <- shiny::reactiveVal(NULL)
  rep_ai_cache_mem <- shiny::reactiveVal(list())
  fpa_ai_show_tab <- function(show) {
    session$sendCustomMessage("fpa-ai-tab", list(show = isTRUE(show)))
    if (!isTRUE(show) && identical(shiny::isolate(input$main_nav), "Analyste")) {
      bslib::nav_select("main_nav", "Synthèse", session = session)
    }
  }
  fpa_ai_settings_now <- function() fpa_ai_settings_read(shiny::isolate(cfg_path()))
  fpa_ai_save_settings <- function(patch) {
    cur <- fpa_ai_settings_now()
    for (nm in names(patch)) cur[[nm]] <- patch[[nm]]
    fpa_ai_settings_write(shiny::isolate(cfg_path()), cur)
    ai_rev(shiny::isolate(ai_rev()) + 1L)
    fpa_ai_show_tab(cur$enabled)
    invisible(cur)
  }
  fpa_ai_fail_text <- function(hit) {
    kind <- hit$kind %||% ""
    if (identical(kind, "auth")) return(fpa_screen("ai_err_auth"))
    if (identical(kind, "rate")) return(fpa_screen("ai_err_rate"))
    if (identical(kind, "timeout")) return(fpa_screen("ai_err_timeout"))
    if (identical(kind, "empty")) return(fpa_screen("ai_err_empty"))
    if (identical(kind, "http")) return(fpa_screen("ai_err_http", hit$status %||% ""))
    fpa_screen("ai_err_offline")
  }
  fpa_ai_launch <- function(recipe, slice, title, purpose = "ask", report = "", skip_preview = FALSE) {
    set <- fpa_ai_settings_now()
    model_now <- shiny::isolate(input$ai_model)
    base_now <- shiny::isolate(input$ai_base_url)
    patch <- list()
    if (!is.null(model_now) && nzchar(model_now) && !identical(set$model, model_now)) patch$model <- model_now
    if (!is.null(base_now) && !identical(set$base_url, base_now %||% "")) patch$base_url <- base_now
    if (length(patch)) set <- fpa_ai_save_settings(patch)
    if (!isTRUE(set$enabled)) {
      ai_status_txt(fpa_screen("ai_need_on"))
      return(invisible(NULL))
    }
    key <- fpa_ai_key_read()
    prov <- fpa_ai_provider(set$provider)
    if (!nzchar(key) && !identical(prov$id, "other")) {
      ai_status_txt(fpa_screen("ai_need_key"))
      return(invisible(NULL))
    }
    home <- dirname(shiny::isolate(cfg_path()))
    cfg <- tryCatch(pack()$config, error = function(e) NULL)
    labels <- fpa_ai_labels_build(
      tryCatch(fpa_line_map(cfg, "pnl"), error = function(e) NULL),
      tryCatch(fpa_line_map(cfg, "bs"), error = function(e) NULL)
    )
    currency <- as.character((cfg$company %||% list())$currency %||% "EUR")
    books <- fpa_ai_books_enrich(fpa_ai_books_from_home(home), labels)
    snap <- fpa_rep_snapshot(home, scenario = fpa_screen("rep_scenario_base"), currency = currency)
    if (length(snap$months)) {
      if (!is.null(books$pnl) && nrow(books$pnl)) books$pnl <- books$pnl[as.character(books$pnl$periode) %in% snap$months, , drop = FALSE]
      if (!is.null(books$cash) && nrow(books$cash)) books$cash <- books$cash[as.character(books$cash$periode) %in% snap$months, , drop = FALSE]
      if (!is.null(books$bs) && nrow(books$bs)) books$bs <- books$bs[as.character(books$bs$periode) %in% snap$months, , drop = FALSE]
    }
    raw <- fpa_ai_context(
      books, closed = if (nzchar(snap$cutoff)) snap$cutoff else fpa_ai_closed_through(home),
      labels = labels, currency = currency, months = snap$months, cutoff = snap$cutoff
    )
    blocks <- fpa_ai_render_blocks(raw, set$mode)
    lang <- fpa_lang_current()
    messages <- list(
      list(role = "system", content = fpa_ai_system_prompt(set$mode, lang, attr(raw, "mark") %||% "€", reconciled = FALSE)),
      list(role = "user", content = fpa_ai_user_message(recipe, blocks, slice))
    )
    preview_on <- isTRUE(set$preview %||% TRUE)
    gated <- preview_on && !isTRUE(skip_preview) && !isTRUE(shiny::isolate(ai_preview_pass()))
    gated <- gated && purpose %in% c("ask", "batch", "report_section", "report_summary", "finalize", "batch_finalize")
    if (gated) {
      calls <- 1L
      if (identical(purpose, "batch")) {
        b <- shiny::isolate(ai_batch())
        if (!is.null(b)) calls <- max(1L, length(b$queue) - as.integer(b$index %||% 1L) + 1L)
      }
      if (identical(purpose, "report_section")) {
        rj <- shiny::isolate(rep_job())
        if (!is.null(rj)) calls <- max(1L, length(rj$queue) - as.integer(rj$index %||% 1L) + 2L)
      }
      ai_pending(list(recipe = recipe, slice = slice, title = title, purpose = purpose, report = report, calls = calls))
      host <- sub("^https?://", "", fpa_ai_endpoint(set))
      host <- sub("/.*$", "", host)
      shiny::showModal(shiny::modalDialog(
        title = fpa_screen("ai_preview_title"),
        easyClose = TRUE,
        footer = shiny::tagList(
          shiny::actionButton("ai_preview_cancel", fpa_screen("ai_prompt_cancel"), class = "fpa-pm-btn is-ghost"),
          shiny::actionButton("ai_preview_go", fpa_screen("ai_preview_go"), class = "fpa-pm-btn")
        ),
        shiny::tags$p(fpa_screen("ai_preview_host", host)),
        shiny::tags$p(fpa_screen("ai_preview_calls", calls)),
        shiny::tags$pre(class = "fpa-ai-sent", messages[[2]]$content)
      ))
      return(invisible(NULL))
    }
    job <- fpa_ai_request_start(fpa_ai_endpoint(set), messages, set$model %||% prov$model, prov$style, key)
    job$sent <- messages[[2]]$content
    job$title <- title
    job$mode <- set$mode
    job$purpose <- purpose
    job$report <- report
    ai_job(job)
    ai_status_txt(fpa_screen("ai_busy"))
    invisible(job)
  }
  shiny::observe({
    shiny::req(input$main_nav)
    fpa_ai_show_tab(isTRUE(fpa_ai_settings_now()$enabled))
  })
  p_boot <- fpa_shiny_load(init_cfg)
  pack <- shiny::reactiveVal(p_boot)
  manual_show <- shiny::reactiveVal(
    if (isTRUE(p_boot$ok)) isTRUE(fpa_manual_applied(p_boot$config)) else TRUE
  )
  manual_pair <- shiny::reactiveVal(NULL)
  manual_busy <- shiny::reactiveVal(FALSE)
  ye_close <- function(cash) {
    if (is.null(cash) || !nrow(cash)) return(NA_real_)
    suppressWarnings(as.numeric(cash$cash_close[[nrow(cash)]]))
  }
  manual_cash_now <- function() {
    p <- pack()
    if (isTRUE(p$ok)) p$finance$cash else NULL
  }
  manual_books <- shiny::reactiveVal(NULL)
  manual_want <- shiny::reactiveVal(NULL)
  shiny::observe({
    p <- pack()
    if (!isTRUE(p$ok) || !is.null(shiny::isolate(manual_books()))) return()
    if (isTRUE(shiny::isolate(manual_busy()))) return()
    manual_busy(TRUE)
    on.exit(manual_busy(FALSE), add = TRUE)
    applied <- fpa_manual_applied(p$config)
    path <- shiny::isolate(cfg_path())
    if (!nzchar(path %||% "")) path <- as.character(p$config_path %||% "")
    alt_fin <- NULL
    if (nzchar(path)) {
      fpa_manual_set_applied(p$config, !applied)
      res <- tryCatch(fpa_run(path, write = FALSE, stop_on_error = FALSE), error = function(e) NULL)
      fpa_manual_set_applied(p$config, applied)
      if (!is.null(res) && !inherits(res, "error")) {
        alt_fin <- fpa_shiny_finance_from_run(res, p$finance)
      }
    }
    books <- if (applied) {
      list(on = p$finance, off = alt_fin)
    } else {
      list(on = alt_fin, off = p$finance)
    }
    manual_books(books)
    on_cash <- if (is.null(books$on)) NULL else books$on$cash
    off_cash <- if (is.null(books$off)) NULL else books$off$cash
    manual_pair(list(with = ye_close(on_cash), without = ye_close(off_cash)))
    pending <- shiny::isolate(manual_want())
    if (!is.null(pending)) {
      manual_want(NULL)
      fin <- if (isTRUE(pending)) books$on else books$off
      if (!is.null(fin)) {
        p$finance <- fin
        pack(p)
        fpa_manual_set_applied(p$config, isTRUE(pending))
        manual_show(isTRUE(pending))
        tryCatch(fpa_write_outputs(list(
          pnl = fin$pnl, pnl_long = fin$pnl_long, bs = fin$bs, cash = fin$cash,
          budget_monthly = fin$budget, variance = fin$variance,
          scenarios = fin$scenarios, scenario_ranks = fin$scenario_ranks,
          line_drivers = fin$line_drivers, period_status = fin$period_status
        ), p$paths), error = function(e) NULL)
      }
    }
  })
  shiny::observeEvent(input$manual_switch, {
    p <- pack()
    if (!isTRUE(p$ok)) return()
    want <- !isTRUE(fpa_manual_applied(p$config))
    books <- manual_books()
    if (is.null(books) || isTRUE(manual_busy())) {
      manual_want(want)
      return()
    }
    fin <- if (isTRUE(want)) books$on else books$off
    if (is.null(fin) || is.null(fin$cash) || !nrow(fin$cash)) return()
    p$finance <- fin
    pack(p)
    fpa_manual_set_applied(p$config, want)
    manual_show(want)
    manual_pair(list(with = ye_close(books$on$cash), without = ye_close(books$off$cash)))
    tryCatch(fpa_write_outputs(list(
      pnl = fin$pnl, pnl_long = fin$pnl_long, bs = fin$bs, cash = fin$cash,
      budget_monthly = fin$budget, variance = fin$variance,
      scenarios = fin$scenarios, scenario_ranks = fin$scenario_ranks,
      line_drivers = fin$line_drivers, period_status = fin$period_status
    ), p$paths), error = function(e) NULL)
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$manual_go, {
    p <- pack()
    if (!isTRUE(p$ok)) return()
    pair <- manual_pair()
    fin <- p$finance$cash
    ye <- if (!is.null(fin) && nrow(fin)) as.character(fin$periode[[nrow(fin)]]) else ""
    shiny::showModal(fpa_manual_popup(
      p$config,
      isTRUE(manual_show()),
      ye,
      if (is.null(pair)) NA_real_ else pair$with,
      if (is.null(pair)) NA_real_ else pair$without,
      fpa_shiny_manual_floor(fin)
    ))
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$manual_hist, {
    shiny::removeModal()
    cfg <- pack()$config
    if (is.null(cfg)) return()
    raw_node("manual:ledger")
    shiny::showModal(fpa_shiny_raw_modal(cfg, "manual:ledger", edit = FALSE, cash = manual_cash_now()))
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$manual_cash, {
    shiny::removeModal()
    bslib::nav_select("main_nav", "Trésorerie", session = session)
    session$sendCustomMessage("fpa-open-details", list(sel = "#bridge_caption"))
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$manual_pnl, {
    shiny::removeModal()
    bslib::nav_select("main_nav", "Compte de résultat", session = session)
    session$sendCustomMessage("fpa-open-details", list(sel = "#pnl_cone"))
  }, ignoreInit = TRUE)
  focus_series <- shiny::reactiveVal("")
  changed_list <- shiny::reactiveVal({
    p0 <- fpa_shiny_load(init_cfg)
    if (!isTRUE(p0$ok)) {
      NULL
    } else {
      prev <- fpa_snapshot_read_prev(p0$paths)
      cur <- fpa_snapshot_read(p0$paths)
      if (is.null(prev) || is.null(cur)) NULL else fpa_snapshot_diff(prev, cur)
    }
  })
  fpa_go_periode <- shiny::reactiveVal("")
  journal_rev <- shiny::reactiveVal(0L)
  journal_draft <- shiny::reactiveVal(NULL)
  journal_focus <- shiny::reactiveVal("")
  last_main_nav <- shiny::reactiveVal(fpa_screen("loc_summary"))
  journal_entries <- shiny::reactive({
    journal_rev()
    p <- pack()
    if (!isTRUE(p$ok)) return(list())
    fpa_journal_read(p$paths)
  })
  todo_open <- shiny::reactiveVal(FALSE)
  todo_clear_rev <- shiny::reactiveVal(0L)
  shiny::observeEvent(input$header_todo_toggle, {
    todo_open(!isTRUE(todo_open()))
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$header_todo_pick, {
    id <- as.character(input$header_todo_pick %||% "")
    if (!nzchar(id)) return()
    todo_open(FALSE)
    if (startsWith(id, "synth:")) {
      last_main_nav("Trésorerie")
      bslib::nav_select("main_nav", selected = "Trésorerie", session = session)
      session$sendCustomMessage("fpa-open-details", list(sel = "#fpa-out-fold"))
      return()
    }
    if (startsWith(id, "close:")) {
      last_main_nav(fpa_screen("loc_closing"))
      bslib::nav_select("main_nav", selected = fpa_screen("loc_closing"), session = session)
      return()
    }
    if (startsWith(id, "path:") || startsWith(id, "map:")) {
      last_main_nav("Cartographie")
      bslib::nav_select("main_nav", selected = "Cartographie", session = session)
      return()
    }
    if (startsWith(id, "anom:")) {
      sel <- paste0("#", sub("^anom:", "", id))
      last_main_nav("Anomalies")
      bslib::nav_select("main_nav", selected = "Anomalies", session = session)
      if (grepl("^#anom-row-", sel)) session$sendCustomMessage("fpa-open-details", list(sel = sel))
      return()
    }
    journal_focus(id)
    last_main_nav("Journal")
    bslib::nav_select("main_nav", selected = "Journal", session = session)
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$header_todo_clear, {
    id <- as.character(input$header_todo_clear %||% "")
    p <- pack()
    if (!nzchar(id) || !isTRUE(p$ok)) return()
    tg <- fpa_todo_queue(p, journal_entries())
    it <- fpa_todo_find(tg, id)
    fpa_todo_cleared_add(
      p$paths, id,
      if (is.null(it)) "" else it$title %||% "",
      if (is.null(it)) "" else it$sentence %||% "",
      "check",
      if (is.null(it)) "" else it$stamp %||% ""
    )
    todo_clear_rev(shiny::isolate(todo_clear_rev()) + 1L)
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$todo_restore, {
    id <- as.character(input$todo_restore %||% "")
    p <- pack()
    if (!nzchar(id) || !isTRUE(p$ok)) return()
    fpa_todo_cleared_remove(p$paths, id)
    todo_clear_rev(shiny::isolate(todo_clear_rev()) + 1L)
  }, ignoreInit = TRUE)
  todo_static <- shiny::reactive({
    p <- pack()
    map_rev()
    if (!isTRUE(p$ok)) return(list(absent = NULL, scan = NULL, nodes = NULL, gaps = character()))
    fpa_todo_parts(p$config, p$paths, p$finance)
  })
  todo_queue_live <- shiny::reactive({
    p <- pack()
    if (!isTRUE(p$ok)) return(NULL)
    todo_clear_rev()
    tg <- fpa_todo_queue(p, journal_entries())
    fpa_todo_hide_cleared(tg, fpa_todo_cleared_read(p$paths))
  })
  output$header_todo <- shiny::renderUI({
    input$main_nav
    tg <- todo_queue_live()
    if (is.null(tg)) {
      tg <- list(groups = list(decisions = list(), files = list(), anomalies = list(), map = list()), n = 0L)
    }
    g <- tg$groups
    n <- tg$n
    open <- isTRUE(todo_open())
    one <- function(it) {
      shiny::tags$div(
        class = "fpa-todo-row",
        shiny::tags$button(
          type = "button",
          class = paste("fpa-todo-item", if (isTRUE(it$neg)) "is-neg" else ""),
          `data-todo` = "pick",
          `data-id` = it$id,
          shiny::tags$strong(it$title),
          shiny::tags$span(it$sentence)
        ),
        shiny::tags$button(
          type = "button",
          class = "fpa-todo-check",
          `data-todo` = "clear",
          `data-id` = it$id,
          title = fpa_screen("todo_clear_title"),
          `aria-label` = fpa_screen("todo_clear_title"),
          shiny::HTML('<svg viewBox="0 0 16 16" width="14" height="14" aria-hidden="true"><path d="M3.2 8.2 6.4 11.4 12.8 4.6" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>')
        )
      )
    }
    shiny::tags$div(
      class = "fpa-todo",
      shiny::tags$button(
        type = "button",
        class = paste("fpa-todo-btn", if (n > 0L) "has-due" else "", if (open) "is-open" else ""),
        `data-todo` = "toggle",
        `aria-expanded` = if (open) "true" else "false",
        shiny::tags$span(fpa_screen("header_todo")),
        shiny::tags$span(class = "fpa-todo-n", as.character(n))
      ),
      if (open) shiny::tags$div(
        class = "fpa-todo-panel",
        shiny::tags$div(
          class = "fpa-todo-kicker",
          shiny::tags$strong(fpa_screen("header_todo")),
          shiny::tags$p(fpa_screen("header_todo_lead"))
        ),
        if (!n) {
          shiny::tagList(
            shiny::tags$h3(fpa_screen("journal_due_title")),
            shiny::tags$p(class = "fpa-todo-empty", fpa_screen("header_todo_none"))
          )
        } else {
          sec <- function(key, rows) {
            if (!length(rows)) return(NULL)
            shiny::tagList(shiny::tags$h3(paste0(fpa_screen(key), " · ", length(rows))), lapply(rows, one))
          }
          shiny::tagList(
            shiny::tags$p(
              class = "fpa-todo-sum",
              fpa_screen(
                "header_todo_sum", n, length(g$decisions), length(g$files),
                length(g$anomalies), length(g$map)
              )
            ),
            sec("journal_due_title", g$decisions),
            sec("header_todo_files", g$files),
            sec("header_todo_anom", g$anomalies),
            sec("header_todo_map", g$map)
          )
        }
      )
    )
  })

