    session$sendCustomMessage("fpa-params-mode", list(on = identical(cur, "Paramètres")))
  }, ignoreNULL = FALSE)

  shiny::observeEvent(input$params, {
    cur <- as.character(input$main_nav %||% "")
    if (nzchar(cur) && !identical(cur, "Paramètres")) last_main_nav(cur)
