  params_tick <- shiny::reactiveVal(0L)
  sync_mode <- shiny::reactiveVal(fpa_sync_mode(init_cfg))

  output$header_year <- shiny::renderUI({
    p <- pack()
    cfg <- if (isTRUE(p$ok)) p$config else list()
    clock <- fpa_header_clock(cfg, Sys.Date())
    left_txt <- if (clock$left <= 0L) {
      fpa_screen("hdr_month_last")
    } else if (identical(clock$left, 1L)) {
      fpa_screen("hdr_month_left_one")
    } else {
      fpa_screen("hdr_month_left", clock$left)
    }
    done_txt <- fpa_screen("hdr_year_done", clock$pct)
    tip <- paste(
      c(fpa_screen("hdr_today"), fpa_header_fr_date(clock$today), left_txt, done_txt,
        fpa_header_fr_date(clock$start), fpa_header_fr_date(clock$end)),
      collapse = " · "
    )
    shiny::tags$div(
      class = "fpa-year",
      title = tip,
      shiny::tags$span(class = "fpa-year-date", fpa_header_fr_date(clock$today)),
      shiny::tags$span(class = "fpa-year-left", left_txt),
      shiny::tags$span(
        class = "fpa-year-track",
        shiny::tags$span(class = "fpa-year-fill", style = paste0("width:", clock$pct, "%;"))
      ),
      shiny::tags$strong(class = "fpa-year-pct", done_txt)
    )
  })

  output$header_actions <- shiny::renderUI({
    p <- pack()
    bar_tip <- fpa_screen("man_bar_tip", fpa_shiny_eur(fpa_shiny_manual_floor(if (isTRUE(p$ok)) p$finance$cash else NULL)))
    local <- identical(sync_mode(), "local")
    site_tip <- if (local) fpa_screen("nav_sync_site_off") else fpa_screen("nav_sync_site_title")
    ico <- function(inner) paste0('<span class="fpa-ico">', inner, '</span>')
    svg_files <- ico('<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M1.8 4.3h3.8l1.3 1.5H14.2V11.7H1.8V4.3z" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/></svg>')
    svg_site <- ico('<svg viewBox="0 0 16 16" aria-hidden="true"><rect x="2" y="2.1" width="12" height="4" rx="1" fill="none" stroke="currentColor" stroke-width="1.6"/><rect x="2" y="9.9" width="12" height="4" rx="1" fill="none" stroke="currentColor" stroke-width="1.6"/><circle cx="4.3" cy="4.1" r="0.8" fill="currentColor"/><circle cx="4.3" cy="11.9" r="0.8" fill="currentColor"/></svg>')
    svg_gear <- ico('<svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="2.1" fill="none" stroke="currentColor" stroke-width="1.6"/><path d="M8 1.5v2.2M8 12.3v2.2M1.5 8h2.2M12.3 8h2.2M3.3 3.3l1.6 1.6M11.1 11.1l1.6 1.6M12.7 3.3 11.1 4.9M4.9 11.1 3.3 12.7" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>')
    one <- function(id, label, svg, class, tip, off = FALSE) {
      args <- list(
        id,
        label = shiny::HTML(paste0(svg, "<span>", label, "</span>")),
        class = class, title = tip, `aria-label` = tip
      )
      if (off) args$disabled <- "disabled"
      btn <- do.call(shiny::actionButton, args)
      if (off) shiny::tags$span(class = "is-off", title = tip, btn) else btn
    }
    on <- isTRUE(manual_show())
    n_man <- 0L
    if (isTRUE(p$ok)) {
      cur <- tryCatch(fpa_manual_read(p$config), error = function(e) NULL)
      if (!is.null(cur) && !is.null(cur$data) && nrow(cur$data)) {
        n_man <- sum(as.character(cur$data$statut) == "actif")
      }
    }
    shiny::tags$div(
      class = "fpa-nav-tool-stack",
      shiny::tags$div(
        class = "fpa-sync-group",
        role = "group",
        `aria-label` = fpa_screen("nav_sync_group"),
        shiny::tags$span(class = "fpa-sync-k", fpa_screen("nav_sync_group")),
        one("sync", fpa_screen("nav_sync"), svg_files, "fpa-nav-sync", fpa_screen("nav_sync_title")),
        one("sync_site", fpa_screen("nav_sync_site"), svg_site, "fpa-nav-sync", site_tip, off = local)
      ),
      one("params", fpa_screen("nav_params"), svg_gear, "fpa-nav-params", fpa_screen("nav_params_title")),
      shiny::tags$div(
        class = "fpa-manual-row",
        shiny::tags$div(
          class = "fpa-manual-pair",
          shiny::tags$button(
            id = "manual_switch",
            type = "button",
            class = if (on) "fpa-switch is-on" else "fpa-switch",
            title = if (on) fpa_screen("man_toggle_on") else fpa_screen("man_toggle_off"),
            `aria-pressed` = if (on) "true" else "false",
            onclick = "Shiny.setInputValue('manual_switch', Date.now(), {priority:'event'})",
            shiny::tags$span(class = "fpa-switch-knob")
          ),
          shiny::tags$button(
            id = "manual_go",
            type = "button",
            class = "fpa-manual-go",
            title = bar_tip,
            onclick = "Shiny.setInputValue('manual_go', Date.now(), {priority:'event'})",
            shiny::tags$span(
              class = "fpa-manual-line",
              shiny::tags$span(fpa_screen("man_toggle")),
              shiny::tags$span(class = "fpa-todo-n", as.character(n_man))
            ),
            shiny::tags$span(class = "fpa-manual-state", fpa_screen("man_kind"))
          )
        )
      )
    )
  })
  pm_path <- function() {
    path <- shiny::isolate(cfg_path())
    if (!nzchar(path)) path <- fpa_shiny_find_config()
    path
  }
  server_scripts <- shiny::reactiveVal({
    cached <- fpa_sync_contact(init_cfg)$scripts
    if (is.list(cached) && nzchar(as.character(cached$engine %||% ""))) cached else NULL
  })
  fpa_check_server_scripts <- function() {
    path <- pm_path()
    if (identical(fpa_sync_mode(path), "local")) return(NULL)
    p <- shiny::isolate(pack())
    site <- if (isTRUE(p$ok)) as.character(p$config$project$site %||% "") else ""
    got <- tryCatch(fpa_sync_server_scripts(site), error = function(e) NULL)
    tryCatch(fpa_sync_report_scripts(dirname(path), path), error = function(e) NULL)
    if (is.null(got)) {
      fpa_sync_note_contact(path, "scripts", list(status = "offline"))
    } else {
      fpa_sync_note_contact(path, "scripts", c(got, list(status = "ok")))
      server_scripts(got)
    }
    params_tick(shiny::isolate(params_tick()) + 1L)
    got
  }
  shiny::observeEvent(input$main_nav, {
    if (!identical(as.character(input$main_nav %||% ""), "Paramètres")) return()
    path <- pm_path()
    if (identical(fpa_sync_mode(path), "local")) return()
    last <- as.character(fpa_sync_contact(path)$scripts$at %||% "")
    t <- suppressWarnings(as.POSIXct(last, format = "%Y-%m-%d %H:%M", tz = Sys.timezone()))
    if (!nzchar(last) || is.na(t) || as.numeric(difftime(Sys.time(), t, units = "hours")) > 24) {
      fpa_check_server_scripts()
    }
  }, ignoreInit = TRUE)

  fpa_lang_push <- function(lang) {
    lang <- fpa_lang_norm(lang)
    tabs <- lapply(fpa_lang_tabs(), function(p) list(value = p$value, title = fpa_screen(p$key)))
    groups <- lapply(fpa_lang_groups(), function(p) list(group = p$group, title = fpa_screen(p$key)))
    session$sendCustomMessage("fpa-lang", list(
      lang = lang,
      map = fpa_lang_pairs(lang),
      tabs = tabs,
      groups = groups
    ))
  }
  shiny::observeEvent(ui_lang(), {
    lang <- ui_lang()
    session$onFlushed(function() fpa_lang_push(lang), once = TRUE)
  })
  shiny::observeEvent(input$params_lang, {
    lang <- fpa_lang_norm(input$params_lang)
    if (identical(lang, shiny::isolate(ui_lang()))) return()
    path <- shiny::isolate(cfg_path())
    if (!nzchar(path %||% "")) {
      shiny::showNotification(fpa_screen("pm_lang_save_fail"), type = "error", duration = 6)
      return()
    }
    if (!isTRUE(fpa_lang_write_config(path, lang))) {
      shiny::showNotification(fpa_screen("pm_lang_save_fail"), type = "error", duration = 6)
      return()
    }
    p <- shiny::isolate(pack())
    if (is.list(p$config)) p$config$language <- lang
    pack(p)
    options(fpa.lang = lang)
    ui_lang(lang)
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$params_mode, {
    want <- if (identical(as.character(input$params_mode), "local")) "local" else "connected"
    path <- pm_path()
    if (!nzchar(path) || identical(want, fpa_sync_mode(path))) return()
    fpa_sync_set_mode(path, want)
    sync_mode(want)
    shiny::showNotification(
      fpa_screen(if (identical(want, "local")) "pm_mode_set_local" else "pm_mode_set_connected"),
      type = "message", duration = 6
    )
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$ai_enabled, {
    want <- isTRUE(input$ai_enabled)
    cur <- fpa_ai_settings_now()
    if (identical(isTRUE(cur$enabled), want)) return()
    cur$enabled <- want
    fpa_ai_settings_write(shiny::isolate(cfg_path()), cur)
    fpa_ai_show_tab(want)
    bslib::update_switch(
      "ai_enabled",
      label = fpa_screen(if (want) "ai_on" else "ai_off"),
      value = want,
      session = session
    )
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$ai_provider, {
    prov <- fpa_ai_provider(input$ai_provider)
    cur <- fpa_ai_settings_now()
    if (identical(cur$provider, prov$id)) return()
    fpa_ai_save_settings(list(provider = prov$id, model = prov$model))
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$ai_mode, {
    fpa_ai_save_settings(list(mode = fpa_ai_mode_norm(input$ai_mode)))
