  shiny::observeEvent(input$ai_user_go, {
    id <- as.character(input$ai_user_go)
    items <- fpa_ai_user_prompts_read(shiny::isolate(cfg_path()))
    hit <- Filter(function(x) identical(x$id, id), items)
