  fpa_ai_prompt_label <- function(id, lang = "fr") {
    item <- fpa_ai_catalog_item(id)
    if (!is.null(item)) return(fpa_ai_pick(item, "label", lang))
    saved <- fpa_ai_user_prompts_read(shiny::isolate(cfg_path()))
    hit <- Filter(function(x) identical(x$id, id), saved)
    if (length(hit)) return(hit[[1]]$name)
    id
  }
  fpa_ai_batch_ui <- function() {
    b <- shiny::isolate(ai_batch())
    resume <- shiny::isolate(ai_batch_resume_at())
    busy <- !is.null(b)
    note <- ""
    pct <- 0
    if (busy) {
      n <- length(b$queue)
      i <- as.integer(b$index %||% 1L)
      done <- max(0L, i - 1L)
      if (identical(b$phase, "format")) {
        note <- fpa_screen("ai_batch_format", n, n)
        pct <- 100
      } else if (n > 0L) {
        title <- b$queue[[min(i, n)]]$title %||% ""
        note <- fpa_screen("ai_batch_progress", done, n, title)
        pct <- round(100 * done / n)
      }
    } else {
      set_id <- as.character(shiny::isolate(input$ai_set_pick) %||% "")
      set <- if (nzchar(set_id)) fpa_ai_set_get(shiny::isolate(cfg_path()), set_id) else NULL
      n <- if (is.null(set)) 0L else length(unlist(set$items))
      if (n > 0L) note <- fpa_screen("ai_batch_plan", n, n + 1L, n)
    }
    session$sendCustomMessage("fpa-ai-batch", list(
      busy = busy,
      can_resume = !busy && !is.null(resume),
      note = note,
      pct = pct
    ))
  }
  fpa_ai_finalize_start <- function(path, purpose = "finalize") {
    if (!nzchar(path) || !file.exists(path)) return(invisible(NULL))
    msgs <- fpa_ai_report_finalize_messages(path, shiny::isolate(ui_lang()))
    set <- fpa_ai_settings_now()
    prov <- fpa_ai_provider(set$provider)
    job <- fpa_ai_request_start(fpa_ai_endpoint(set), msgs, set$model %||% prov$model, prov$style, fpa_ai_key_read(), max_tokens = 2000L)
    job$purpose <- purpose
    job$report <- path
    job$sent <- "finalize"
    job$mode <- set$mode
    job$title <- "Note"
    ai_job(job)
    ai_status_txt(fpa_screen("ai_busy"))
    invisible(job)
  }
  fpa_ai_batch_launch_i <- function(b) {
    i <- as.integer(b$index %||% 1L)
    if (i > length(b$queue)) {
      b$phase <- "format"
      ai_batch(b)
      fpa_ai_batch_ui()
      fpa_ai_finalize_start(b$report, purpose = "batch_finalize")
      return(invisible(NULL))
    }
    item <- b$queue[[i]]
    fpa_ai_launch(item$recipe, item$slice, item$title, purpose = "batch", report = b$report)
    fpa_ai_batch_ui()
    invisible(NULL)
  }
  fpa_ai_batch_start <- function(set_id, from = 1L, report = "") {
    if (!is.null(shiny::isolate(ai_batch()))) {
      ai_status_txt(fpa_screen("ai_batch_busy"))
      return(invisible(NULL))
    }
    set <- fpa_ai_set_get(shiny::isolate(cfg_path()), set_id)
    if (is.null(set)) {
      ai_status_txt(fpa_screen("ai_batch_need_set"))
      return(invisible(NULL))
    }
    lang <- shiny::isolate(ui_lang())
    queue <- fpa_ai_batch_queue(set, fpa_ai_catalog(), fpa_ai_user_prompts_read(shiny::isolate(cfg_path())), lang)
    if (!length(queue)) {
      ai_status_txt(fpa_screen("ai_batch_need_set"))
      return(invisible(NULL))
    }
    from <- max(1L, min(as.integer(from), length(queue)))
    cfg <- shiny::isolate(cfg_path())
    settings <- fpa_ai_settings_now()
    home <- dirname(cfg)
    path <- as.character(report %||% "")
    if (!nzchar(path) || !file.exists(path)) {
      path <- fpa_ai_report_start(cfg, set$name, fpa_ai_closed_through(home), settings$mode, settings$provider, settings$model)
    } else {
      cur <- settings
      cur$open_report <- path
      fpa_ai_settings_write(cfg, cur)
    }
    if (!nzchar(path %||% "") || !file.exists(path)) {
      ai_status_txt(fpa_screen("ai_batch_need_set"))
      return(invisible(NULL))
    }
    ai_batch_resume_at(NULL)
    ai_from_batch(FALSE)
    ai_batch(list(
      set_id = set$id, name = set$name, queue = queue, index = from,
      report = path, stop = FALSE, phase = "ask"
    ))
    ai_rev(shiny::isolate(ai_rev()) + 1L)
    fpa_ai_batch_ui()
    fpa_ai_batch_launch_i(shiny::isolate(ai_batch()))
    invisible(NULL)
  }
