  fpa_rep_wf_fig <- function() {
    book <- tryCatch(pnl_wf_book(), error = function(e) NULL)
    if (is.null(book) || !nrow(book)) return(plotly::plotly_empty())
    years <- fpa_pnl_wf_years(book)
    prefer <- format(Sys.Date(), "%Y")
    ordered <- unique(c(prefer, rev(years)))
    for (y in ordered) {
      span <- fpa_pnl_wf_span(book, y, c(1L, 12L))
      if (is.null(span) || !length(span$found)) next
      row <- tryCatch(fpa_pnl_waterfall_sum(book, span$found), error = function(e) NULL)
      if (is.null(row)) next
      fig <- tryCatch(fpa_shiny_pnl_waterfall_plot(row, compact = TRUE), error = function(e) NULL)
      if (!fpa_rep_fig_blank(fig)) return(fig)
    }
    plotly::plotly_empty()
  }

  fpa_rep_collect_blocks <- function(sel, ai_map = list(), summary_ai = "") {
    old_print <- getOption("fpa.print")
    options(fpa.print = TRUE)
    on.exit(options(fpa.print = old_print), add = TRUE)
    ids <- fpa_rep_selected_ids(sel)
    cat <- fpa_rep_catalog()
    labs <- setNames(vapply(cat, function(x) fpa_screen(x$label_key), ""), vapply(cat, function(x) x$id, ""))
    kinds <- setNames(vapply(cat, function(x) x$kind, ""), vapply(cat, function(x) x$id, ""))
    p <- shiny::isolate(pack())
    fin <- if (is.list(p)) p$finance else NULL
    home <- dirname(shiny::isolate(cfg_path()))
    co <- if (is.list(p) && is.list(p$config)) p$config$company else NULL
    snap <- fpa_rep_snapshot(home, scenario = fpa_screen("rep_scenario_base"), currency = as.character(co$currency %||% "EUR"))
    blocks <- list()
    for (id in ids) {
      want_txt <- isTRUE(sel$texts[[id]])
      block <- list(id = id, kind = kinds[[id]] %||% "text", title = fpa_rep_one(labs[[id]], id), text = "", ai = fpa_rep_one(ai_map[[id]], ""))
      block <- tryCatch({
      if (identical(id, "syn_cards")) {
        pnl <- shiny::isolate({
          v <- pnl_view()
          if (isTRUE(v$ready) && !is.null(v$pnl)) v$pnl else fin$pnl
        })
        cash <- shiny::isolate(cash_now())
        months <- snap$months
        rev_n <- oi_n <- booked_n <- cash_n <- NA_real_
        if (!is.null(pnl) && nrow(pnl) && length(months)) {
          sub <- pnl[as.character(pnl$periode) %in% months, , drop = FALSE]
          rev_n <- sum(suppressWarnings(as.numeric(sub$REV)), na.rm = TRUE)
          oi_n <- if ("OI" %in% names(sub)) sum(suppressWarnings(as.numeric(sub$OI)), na.rm = TRUE) else NA_real_
          actuals <- names(snap$status)[snap$status == "actual"]
          booked <- sub[as.character(sub$periode) %in% actuals, , drop = FALSE]
          booked_n <- sum(suppressWarnings(as.numeric(booked$REV)), na.rm = TRUE)
        }
        year_end <- paste0(snap$year, "-12")
        if (!is.null(cash) && nrow(cash) && "cash_close" %in% names(cash)) {
          hit <- cash[as.character(cash$periode) == year_end, , drop = FALSE]
          if (!nrow(hit) && length(months)) hit <- cash[as.character(cash$periode) == months[[length(months)]], , drop = FALSE]
          if (nrow(hit)) cash_n <- suppressWarnings(as.numeric(hit$cash_close[[1]]))
        }
        pct <- if (is.finite(rev_n) && rev_n > 0 && is.finite(booked_n)) paste0(round(100 * booked_n / rev_n), " %") else "—"
        cards <- list(
          list(lab = fpa_screen("rep_card_rev"), val = fpa_rep_one(fpa_shiny_eur(rev_n), "—")),
          list(lab = fpa_screen("rep_card_oi"), val = fpa_rep_one(fpa_shiny_eur(oi_n), "—")),
          list(lab = fpa_screen("rep_card_cash"), val = fpa_rep_one(fpa_shiny_eur(cash_n), "—")),
          list(lab = fpa_screen("rep_card_booked"), val = pct)
        )
        block$html <- fpa_rep_cards_html(cards)
      } else if (identical(id, "syn_cash")) {
        fig <- tryCatch(shiny::isolate(fig_cash_line()), error = function(e) NULL)
        block$fig_json <- tryCatch(fpa_rep_fig_json(fig), error = function(e) NULL)
        if (want_txt) block$text <- fpa_rep_one(shiny::isolate(rep_txt_cash()))
      } else if (identical(id, "pnl_cone")) {
        fig <- tryCatch(shiny::isolate(fig_pnl_cone()), error = function(e) NULL)
        block$fig_json <- tryCatch(fpa_rep_fig_json(fig), error = function(e) NULL)
        if (want_txt) block$text <- fpa_rep_one(shiny::isolate(rep_txt_cone()))
      } else if (identical(id, "pnl_wf")) {
        fig <- tryCatch(shiny::isolate(fig_pnl_waterfall()), error = function(e) NULL)
        if (fpa_rep_fig_blank(fig)) fig <- tryCatch(fpa_rep_wf_fig(), error = function(e) NULL)
        if (fpa_rep_fig_blank(fig)) {
          block$kind <- "text"
          block$text <- fpa_screen("rep_chart_empty")
        } else {
          block$fig_json <- tryCatch(fpa_rep_fig_json(fig), error = function(e) NULL)
          if (want_txt) block$text <- fpa_rep_one(shiny::isolate(rep_txt_wf()))
        }
      } else if (identical(id, "pnl_table")) {
        pnl <- shiny::isolate({
          v <- pnl_view()
          if (isTRUE(v$ready) && !is.null(v$pnl)) v$pnl else fin$pnl
        })
        df <- fpa_rep_pnl_frame(pnl, line_name_fn = fpa_shiny_line_name, months = snap$months, status = snap$status)
        got <- fpa_rep_table_html(df, total_rows = c("GP", "EBITDA", "OI", "NI", fpa_shiny_line_name("GP"), fpa_shiny_line_name("OI"), fpa_shiny_line_name("NI")))
        block$html <- got$html
        if (length(got$dropped)) block$text <- fpa_screen("rep_drop_cols", paste(got$dropped, collapse = ", "))
      } else if (identical(id, "cash_bridge")) {
        fig <- tryCatch(bridge_fig_make("chain"), error = function(e) NULL)
        block$fig_json <- tryCatch(fpa_rep_fig_json(fig), error = function(e) NULL)
        if (want_txt) block$text <- fpa_rep_one(shiny::isolate(rep_txt_bridge()))
      } else if (identical(id, "cash_table")) {
        cash <- shiny::isolate(cash_now())
        df <- fpa_rep_cash_frame(cash, months = snap$months, status = snap$status)
        got <- fpa_rep_table_html(df)
        block$html <- got$html
        if (want_txt && length(got$dropped)) block$text <- fpa_screen("rep_drop_cols", paste(got$dropped, collapse = ", "))
      } else if (identical(id, "bs_table")) {
        bs <- fin$bs
        df <- fpa_rep_bs_frame(bs, months = snap$bs_months, status = snap$status, line_name_fn = fpa_shiny_line_name)
        got <- fpa_rep_table_html(df)
        block$html <- got$html
        if (want_txt && length(got$dropped)) block$text <- fpa_screen("rep_drop_cols", paste(got$dropped, collapse = ", "))
      } else if (identical(id, "var_main")) {
        sl <- shiny::isolate(cur_sl())
        fig <- if (is.null(sl)) NULL else fpa_var_main_fig(sl, as.character(shiny::isolate(input$var_mode) %||% "gap"), shiny::isolate(var_month()))
        block$fig_json <- tryCatch(fpa_rep_fig_json(fig), error = function(e) NULL)
        if (want_txt) block$text <- fpa_rep_one(shiny::isolate(rep_txt_var_main()))
      } else if (identical(id, "var_bridge")) {
        sl <- shiny::isolate(cur_sl())
        fig <- if (is.null(sl)) NULL else tryCatch(fpa_var_bridge_fig(fpa_var_bridge_frame(sl)), error = function(e) NULL)
        block$fig_json <- tryCatch(fpa_rep_fig_json(fig), error = function(e) NULL)
        if (want_txt) block$text <- fpa_rep_one(shiny::isolate(rep_txt_var_bridge()))
      } else if (identical(id, "var_pv")) {
        sl <- shiny::isolate(cur_sl())
        fig <- if (is.null(sl)) NULL else tryCatch(fpa_var_pv_fig(sl, shiny::isolate(var_month())), error = function(e) NULL)
        block$fig_json <- tryCatch(fpa_rep_fig_json(fig), error = function(e) NULL)
        if (want_txt) block$text <- fpa_rep_one(shiny::isolate(rep_txt_var_pv()))
      } else if (identical(id, "var_table")) {
        sl <- shiny::isolate(cur_sl())
        df <- fpa_rep_var_frame(sl)
        got <- fpa_rep_table_html(df)
        block$html <- got$html
      } else if (identical(id, "health_table")) {
        closed <- tryCatch(fpa_ai_closed_through(home), error = function(e) "")
        if (!nzchar(closed) && is.data.frame(fin$bs) && nrow(fin$bs) && "periode" %in% names(fin$bs)) {
          closed <- max(as.character(fin$bs$periode))
        }
        fy_start <- tryCatch(
          fpa_fy_start_month(if (is.list(p) && is.list(p$config)) p$config else NULL),
          error = function(e) 1L
        )
        h <- tryCatch(fpa_health_month(fin$bs, fin$pnl, closed, fy_start), error = function(e) NULL)
        df <- fpa_rep_health_frame(h, label_fn = function(id) {
          keys <- fpa_health_copy_keys(id)
          if (length(keys)) fpa_screen(keys[[1]]) else id
        })
        if (!is.null(df) && nrow(df) && is.data.frame(h) && "id" %in% names(h) && nrow(h) == nrow(df)) {
          df$Valeur <- vapply(seq_len(nrow(df)), function(i) fpa_health_fmt(h$id[[i]], df$Valeur[[i]]), "")
        }
        got <- fpa_rep_table_html(df)
        block$html <- got$html
        if (want_txt && nzchar(closed)) block$text <- fpa_screen("rep_health_month", closed)
      } else if (identical(id, "ai_note")) {
        path <- shiny::isolate(fpa_ai_settings_now()$open_report %||% "")
        md <- if (nzchar(path) && file.exists(path)) fpa_rep_note_body(fpa_ai_read_utf8(path), isTRUE(sel$audit)) else ""
        block$md <- md
        if (!nzchar(md)) block$text <- fpa_screen("ai_step_none")
      }
      block
      }, error = function(e) {
        list(
          id = id, kind = "text", title = fpa_rep_one(labs[[id]], id),
          text = fpa_rep_one(conditionMessage(e), "Erreur"),
          ai = ""
        )
      })
      blocks[[length(blocks) + 1L]] <- block
    }
    attr(blocks, "summary_ai") <- summary_ai
    blocks
  }

  fpa_rep_meta_now <- function(title, summary_ai = "") {
    p <- shiny::isolate(pack())
    co <- if (is.list(p) && is.list(p$config)) p$config$company else NULL
    home <- dirname(shiny::isolate(cfg_path()))
    cur <- if (is.list(co)) as.character(co$currency %||% "EUR") else "EUR"
    snap <- fpa_rep_snapshot(home, scenario = fpa_screen("rep_scenario_base"), currency = cur)
    list(
      title = title,
      company = if (is.list(co)) as.character(co$name %||% co$legal_name %||% "") else "",
      currency = cur,
      period = fpa_screen(
        "rep_scope_line", snap$year,
        if (nzchar(snap$cutoff)) snap$cutoff else "—",
        length(snap$horizon), snap$scenario, snap$currency
      ),
      when = format(Sys.time(), "%Y-%m-%d %H:%M"),
      lang = fpa_lang_current(),
      ai_label = fpa_screen("rep_ai_label"),
      summary_ai = summary_ai
    )
  }

  fpa_rep_finish <- function(rj) {
    on.exit({
      ai_preview_pass(FALSE)
      rep_job(NULL)
      session$sendCustomMessage("fpa-rep-busy", list(busy = FALSE))
    }, add = TRUE)
    ok <- tryCatch({
      sel <- rj$sel
      cache <- shiny::isolate(rep_ai_cache_mem())
      ai_map <- fpa_rep_ai_map_for(rj$want_ai, cache, fpa_rep_selected_ids(sel), rj$fps)
      summary_ai <- if (isTRUE(rj$want_ai)) {
        rj$summary_ai %||% fpa_rep_ai_cache_get(cache, "summary", rj$fps[["summary"]] %||% "")
      } else {
        ""
      }
      blocks <- fpa_rep_collect_blocks(sel, ai_map = ai_map, summary_ai = summary_ai)
      title <- if (nzchar(sel$title)) sel$title else fpa_screen("rep_title_default")
      meta <- fpa_rep_meta_now(title, summary_ai = summary_ai)
      html <- fpa_rep_html(blocks, meta)
      paths <- fpa_rep_start_paths(shiny::isolate(cfg_path()), title)
      fpa_rep_write_utf8(paths$html, html)
      rep_last_html(paths$html)
      pdf_ok <- FALSE
      pdf_reason <- "skipped"
      if (isTRUE(rj$want_pdf)) {
        got <- fpa_rep_pdf(paths$html, paths$pdf)
        pdf_ok <- isTRUE(got$ok)
        pdf_reason <- got$reason %||% "edge_fail"
        if (pdf_ok) rep_last_pdf(paths$pdf) else rep_last_pdf("")
      } else {
        rep_last_pdf("")
      }
      sel$last_html <- paths$html
      sel$last_pdf <- if (pdf_ok) paths$pdf else ""
      fpa_rep_sel_write(shiny::isolate(cfg_path()), sel)
      if (pdf_ok) {
        rep_status_txt(fpa_screen("rep_done"))
      } else if (isTRUE(rj$want_pdf)) {
        rep_status_txt(fpa_screen("rep_done_html", pdf_reason))
      } else {
        rep_status_txt(fpa_screen("rep_done"))
      }
      TRUE
    }, error = function(e) {
      rep_status_txt(conditionMessage(e))
      FALSE
    })
    invisible(ok)
  }

  fpa_rep_ai_launch_next <- function() {
    rj <- shiny::isolate(rep_job())
    if (is.null(rj)) return(invisible(NULL))
    if (isTRUE(rj$stop)) {
      rep_status_txt(fpa_screen("ai_batch_stopped"))
      rep_job(NULL)
      session$sendCustomMessage("fpa-rep-busy", list(busy = FALSE))
      return(invisible(NULL))
    }
    q <- rj$queue
    i <- as.integer(rj$index %||% 1L)
    if (i > length(q)) {
      # summary
      names_lab <- paste(vapply(rj$sel_ids, function(id) {
        el <- Filter(function(x) identical(x$id, id), fpa_rep_catalog())
        if (length(el)) fpa_screen(el[[1]]$label_key) else id
      }, ""), collapse = ", ")
      recipe <- fpa_screen("rep_ai_prompt_summary", names_lab)
      fp <- rj$fps[["summary"]] %||% fpa_rep_fingerprint(rj$sel_ids, "summary")
      cached <- fpa_rep_ai_cache_get(shiny::isolate(rep_ai_cache_mem()), "summary", fp)
      if (nzchar(cached)) {
        rj$summary_ai <- cached
        rep_job(rj)
        fpa_rep_finish(rj)
        return(invisible(NULL))
      }
      fpa_ai_launch(recipe, NULL, fpa_screen("rep_ai_box"), purpose = "report_summary")
      job <- shiny::isolate(ai_job())
      if (!is.null(job)) {
        job$rep_fp <- fp
        ai_job(job)
      }
      rep_status_txt(fpa_screen("rep_busy"))
      return(invisible(NULL))
    }
    item <- q[[i]]
    cached <- fpa_rep_ai_cache_get(shiny::isolate(rep_ai_cache_mem()), item$id, item$fp)
    if (nzchar(cached)) {
      rj$index <- i + 1L
      rep_job(rj)
      fpa_rep_ai_launch_next()
      return(invisible(NULL))
    }
    recipe <- fpa_screen("rep_ai_prompt_section", item$title)
    fpa_ai_launch(recipe, item$slice, item$title, purpose = "report_section")
    job <- shiny::isolate(ai_job())
    if (!is.null(job)) {
      job$rep_id <- item$id
      job$rep_fp <- item$fp
      ai_job(job)
    }
    rep_status_txt(fpa_screen("ai_batch_progress", i, length(q), item$title))
    invisible(NULL)
  }

  fpa_rep_start_build <- function(want_pdf = TRUE) {
    if (!is.null(shiny::isolate(rep_job())) || !is.null(shiny::isolate(ai_batch())) || !is.null(shiny::isolate(ai_job()))) {
      rep_status_txt(fpa_screen("ai_batch_busy"))
      return(invisible(NULL))
    }
    sel <- fpa_rep_sel_now()
    ids <- fpa_rep_selected_ids(sel)
    if (!length(ids)) {
      rep_status_txt(fpa_screen("rep_fail_empty"))
      return(invisible(NULL))
    }
    want_ai <- isTRUE(sel$ai_comment) && isTRUE(fpa_ai_settings_now()$enabled) && nzchar(fpa_ai_key_read())
    home <- dirname(shiny::isolate(cfg_path()))
    p <- shiny::isolate(pack())
    fin <- if (is.list(p)) p$finance else NULL
    co <- if (is.list(p) && is.list(p$config)) p$config$company else NULL
    snap <- fpa_rep_snapshot(home, scenario = fpa_screen("rep_scenario_base"), currency = as.character(co$currency %||% "EUR"))
    pnl <- shiny::isolate({
      v <- tryCatch(pnl_view(), error = function(e) NULL)
      if (is.list(v) && isTRUE(v$ready) && !is.null(v$pnl)) v$pnl else fin$pnl
    })
    sig <- fpa_rep_content_sig(pnl, snap$months)
    set <- fpa_ai_settings_now()
    lang <- fpa_lang_current()
    fps <- list()
    for (id in ids) {
      fps[[id]] <- fpa_rep_fp_hash(id, isTRUE(sel$texts[[id]]), snap$cutoff, sig, set$mode %||% "", set$model %||% "", set$provider %||% "", lang)
    }
    fps[["summary"]] <- fpa_rep_fp_hash(ids, "summary", snap$cutoff, sig, set$mode %||% "", set$model %||% "", set$provider %||% "", lang)
    rj <- list(
      sel = sel, sel_ids = ids, want_pdf = want_pdf, want_ai = want_ai,
      queue = list(), index = 1L, stop = FALSE, fps = fps, summary_ai = ""
    )
    if (want_ai) {
      cat <- fpa_rep_catalog()
      labs <- setNames(vapply(cat, function(x) fpa_screen(x$label_key), ""), vapply(cat, function(x) x$id, ""))
      rj$queue <- lapply(ids, function(id) {
        list(id = id, title = labs[[id]] %||% id, fp = fps[[id]], slice = fpa_rep_section_slice(id))
      })
      rep_job(rj)
      session$sendCustomMessage("fpa-rep-busy", list(busy = TRUE))
      rep_status_txt(fpa_screen("rep_busy"))
      fpa_rep_ai_launch_next()
    } else {
      rep_job(rj)
      session$sendCustomMessage("fpa-rep-busy", list(busy = TRUE))
      fpa_rep_finish(rj)
    }
    invisible(NULL)
  }
  shiny::observeEvent(input$rep_build_pdf, {
    fpa_rep_start_build(TRUE)
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$rep_build_html, {
    fpa_rep_start_build(FALSE)
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$rep_stop, {
    rj <- shiny::isolate(rep_job())
    if (is.null(rj)) return()
    rj$stop <- TRUE
    rep_job(rj)
    rep_status_txt(fpa_screen("ai_batch_stopped"))
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$rep_ai_regen, {
    cfg <- shiny::isolate(cfg_path())
    fpa_rep_ai_cache_write(cfg, list())
    rep_ai_cache_mem(list())
    rep_status_txt("")
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$rep_seal, {
    pdf <- shiny::isolate(rep_last_pdf())
    if (!nzchar(pdf) || !file.exists(pdf)) return()
    tryCatch({
      fpa_rep_seal_pdf(pdf)
      rep_seal_nudge(shiny::isolate(rep_seal_nudge()) + 1L)
    }, error = function(e) rep_status_txt(conditionMessage(e)))
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$rep_folder, {
    dir <- fpa_rep_dir(shiny::isolate(cfg_path()))
    if (!nzchar(dir)) return()
    dir.create(dir, recursive = TRUE, showWarnings = FALSE)
    shell.exec(normalizePath(dir, winslash = "\\", mustWork = FALSE))
  }, ignoreInit = TRUE)
  output$rep_download <- shiny::downloadHandler(
    filename = function() {
      pdf <- shiny::isolate(rep_last_pdf())
      html <- shiny::isolate(rep_last_html())
      if (nzchar(pdf) && file.exists(pdf)) return(basename(pdf))
      if (nzchar(html) && file.exists(html)) return(basename(html))
      "rapport.html"
    },
    content = function(file) {
      pdf <- shiny::isolate(rep_last_pdf())
      html <- shiny::isolate(rep_last_html())
      src <- if (nzchar(pdf) && file.exists(pdf)) pdf else html
      if (!nzchar(src) || !file.exists(src)) {
        writeLines("", file)
      } else {
        file.copy(src, file, overwrite = TRUE)
      }
    }
  )

  shiny::observe({
    job <- ai_job()
    if (is.null(job)) return()
    shiny::invalidateLater(500, session)
    hit <- fpa_ai_request_poll(job)
    if (is.null(hit)) return()
    ai_job(NULL)
    purpose <- job$purpose %||% "ask"
    if (!isTRUE(hit$ok)) {
      ai_status_txt(fpa_ai_fail_text(hit))
      if (purpose %in% c("batch", "batch_finalize")) {
        b <- shiny::isolate(ai_batch())
        if (!is.null(b)) {
          fail_title <- if (identical(purpose, "batch_finalize")) {
            fpa_screen("ai_step3")
          } else {
            b$queue[[min(as.integer(b$index), length(b$queue))]]$title %||% ""
          }
          ai_status_txt(fpa_screen("ai_batch_fail", fail_title))
          ai_batch_resume_at(list(set_id = b$set_id, index = as.integer(b$index), report = b$report))
          ai_batch(NULL)
          ai_preview_pass(FALSE)
          fpa_ai_batch_ui()
        }
      }
      if (purpose %in% c("report_section", "report_summary")) {
        rep_status_txt(fpa_ai_fail_text(hit))
        rep_job(NULL)
        session$sendCustomMessage("fpa-rep-busy", list(busy = FALSE))
      }
      return()
    }
    if (identical(purpose, "report_section")) {
      rj <- shiny::isolate(rep_job())
      if (!is.null(rj)) {
        id <- as.character(job$rep_id %||% "")
        fp <- as.character(job$rep_fp %||% "")
        cache <- shiny::isolate(rep_ai_cache_mem())
        cache <- fpa_rep_ai_cache_put(cache, id, fp, hit$text)
        rep_ai_cache_mem(cache)
        fpa_rep_ai_cache_write(shiny::isolate(cfg_path()), cache)
        if (isTRUE(rj$stop)) {
          rep_status_txt(fpa_screen("ai_batch_stopped"))
          rep_job(NULL)
          session$sendCustomMessage("fpa-rep-busy", list(busy = FALSE))
          return()
        }
        rj$index <- as.integer(rj$index) + 1L
        rep_job(rj)
        fpa_rep_ai_launch_next()
        return()
      }
    }
    if (identical(purpose, "report_summary")) {
      rj <- shiny::isolate(rep_job())
      if (!is.null(rj)) {
        cache <- shiny::isolate(rep_ai_cache_mem())
        cache <- fpa_rep_ai_cache_put(cache, "summary", job$rep_fp %||% "", hit$text)
        rep_ai_cache_mem(cache)
        fpa_rep_ai_cache_write(shiny::isolate(cfg_path()), cache)
        rj$summary_ai <- hit$text
        rep_job(rj)
        fpa_rep_finish(rj)
        return()
      }
    }
    if (purpose %in% c("finalize", "batch_finalize") && nzchar(job$report %||% "")) {
      tryCatch(fpa_ai_report_append(job$report, "Note", hit$text, job$sent, job$mode), error = function(e) NULL)
    }
    if (identical(purpose, "batch")) {
      b <- shiny::isolate(ai_batch())
      if (!is.null(b) && nzchar(b$report %||% "")) {
        head <- substr(gsub("[\r\n]+", " ", job$title %||% ""), 1L, 120L)
        if (!nzchar(head)) head <- fpa_screen("ai_answer_head")
        tryCatch(fpa_ai_report_append(b$report, head, hit$text, job$sent, job$mode), error = function(e) NULL)
        ai_answer(hit$text)
        ai_title_txt(job$title %||% "")
        ai_sent_txt(job$sent %||% "")
        ai_status_txt("")
        ai_rev(shiny::isolate(ai_rev()) + 1L)
        if (isTRUE(b$stop)) {
          ai_status_txt(fpa_screen("ai_batch_stopped"))
          next_i <- as.integer(b$index) + 1L
          if (next_i <= length(b$queue)) {
            ai_batch_resume_at(list(set_id = b$set_id, index = next_i, report = b$report))
          } else {
            ai_batch_resume_at(NULL)
          }
          ai_batch(NULL)
          ai_preview_pass(FALSE)
          fpa_ai_batch_ui()
          return()
        }
        b$index <- as.integer(b$index) + 1L
        ai_batch(b)
        fpa_ai_batch_launch_i(b)
        return()
      }
    }
    if (identical(purpose, "batch_finalize")) {
      ai_answer(hit$text)
      ai_title_txt(job$title %||% "")
      ai_sent_txt(job$sent %||% "")
      ai_status_txt(fpa_screen("ai_batch_done"))
      ai_from_batch(TRUE)
      ai_batch(NULL)
      ai_preview_pass(FALSE)
      ai_batch_resume_at(NULL)
      ai_rev(shiny::isolate(ai_rev()) + 1L)
      fpa_ai_batch_ui()
      return()
    }
    if (identical(purpose, "ask")) ai_from_batch(FALSE)
    ai_answer(hit$text)
    ai_title_txt(job$title %||% "")
    ai_sent_txt(job$sent %||% "")
    ai_status_txt("")
    ai_rev(shiny::isolate(ai_rev()) + 1L)
  })
  output$ai_prompts <- shiny::renderUI({
    ui_lang()
    lang <- ui_lang()
    en <- identical(lang, "en")
    cluster_lab <- c(
      direction = if (en) "Direction" else "Direction",
      variance = if (en) "Gaps to budget" else "Écarts",
      landing = if (en) "Landing" else "Atterrissage",
      cash = if (en) "Cash" else "Trésorerie",
      close = if (en) "Close" else "Clôture",
      drivers = "Drivers",
      health = if (en) "Health" else "Santé",
      decisions = if (en) "Decisions" else "Décisions"
    )
    ai_user_rev()
    ai_fav_rev()
    favs <- fpa_ai_fav_read(shiny::isolate(cfg_path()))$favorites
    fav_btn <- function(id) {
      on <- id %in% favs
      shiny::tags$button(
        type = "button",
        class = paste("fpa-ai-fav", if (on) "is-on" else ""),
        title = fpa_screen("ai_fav_title"),
        `aria-label` = fpa_screen("ai_fav_title"),
        `aria-pressed` = if (on) "true" else "false",
        onclick = sprintf(
          "event.preventDefault();event.stopPropagation();Shiny.setInputValue('ai_fav_toggle','%s',{priority:'event'})",
          id
        ),
        shiny::tags$span(class = "fpa-ai-fav-box"),
