      )
    }
    clusters <- unique(vapply(fpa_ai_catalog(), function(x) x$cluster, ""))
    saved <- fpa_ai_user_prompts_read(shiny::isolate(cfg_path()))
    catalog_ui <- lapply(clusters, function(cl) {
      items <- Filter(function(x) identical(x$cluster, cl), fpa_ai_catalog())
      shiny::tags$details(
        open = if (identical(cl, "direction")) NA else NULL,
        shiny::tags$summary(unname(cluster_lab[[cl]] %||% cl)),
        lapply(items, function(item) {
          shiny::tags$div(
            class = "fpa-ai-prompt-row",
            fav_btn(item$id),
            shiny::tags$button(
              type = "button", class = "fpa-ai-prompt",
              onclick = sprintf("Shiny.setInputValue('ai_prompt_id','%s',{priority:'event'})", item$id),
              fpa_ai_pick(item, "label", lang)
            )
          )
        })
      )
    })
    mine <- shiny::tags$details(
      shiny::tags$summary(fpa_screen("ai_prompt_cluster")),
      if (!length(saved)) {
        shiny::tags$p(class = "fpa-ai-user-empty", fpa_screen("ai_prompt_empty"))
      } else {
        lapply(saved, function(item) {
          shiny::tags$div(
            class = "fpa-ai-user-row",
            fav_btn(item$id),
            shiny::tags$button(
              type = "button", class = "fpa-ai-prompt",
              title = item$text,
              onclick = sprintf("Shiny.setInputValue('ai_user_go','%s',{priority:'event'})", item$id),
              item$name
            ),
            shiny::tags$button(
              type = "button", class = "fpa-ai-user-drop",
              title = fpa_screen("ai_prompt_drop"),
              onclick = sprintf("Shiny.setInputValue('ai_user_drop','%s',{priority:'event'})", item$id),
              fpa_screen("ai_prompt_drop")
            )
          )
        })
      }
    )
    shiny::tagList(
      shiny::tags$div(
        class = "fpa-ai-catalog-bar",
        shiny::tags$h3(class = "fpa-ai-catalog-head", fpa_screen("ai_prompts_head")),
        shiny::tags$div(
          class = "fpa-ai-catalog-fold",
          shiny::tags$button(
            type = "button",
            onclick = "fpaAiFold(true)",
            fpa_screen("ai_prompts_expand")
          ),
          shiny::tags$button(
            type = "button",
            onclick = "fpaAiFold(false)",
            fpa_screen("ai_prompts_collapse")
          )
        )
      ),
      shiny::tags$p(class = "fpa-ai-fav-lead", fpa_screen("ai_fav_lead")),
      catalog_ui,
      mine
    )
  })
  shiny::observe({
    ai_fav_rev()
    ui_lang()
    data <- fpa_ai_fav_read(shiny::isolate(cfg_path()))
