      names_v <- vapply(data$sets, function(s) s$name, "")
      ids_v <- vapply(data$sets, function(s) s$id, "")
      choices <- c(choices, stats::setNames(ids_v, names_v))
    }
    cur <- shiny::isolate(input$ai_set_pick) %||% ""
    if (!cur %in% unname(choices)) cur <- ""
    shiny::updateSelectInput(session, "ai_set_pick", choices = choices, selected = cur)
    fpa_ai_batch_ui()
  })
  output$ai_set_list <- shiny::renderUI({
    ai_fav_rev()
    ui_lang()
    lang <- ui_lang()
    set_id <- as.character(input$ai_set_pick %||% "")
    if (!nzchar(set_id)) return(shiny::tags$p(class = "fpa-ai-user-empty", fpa_screen("ai_sets_none")))
    set <- fpa_ai_set_get(shiny::isolate(cfg_path()), set_id)
    if (is.null(set)) return(shiny::tags$p(class = "fpa-ai-user-empty", fpa_screen("ai_sets_none")))
    ids <- as.character(unlist(set$items))
    if (!length(ids)) return(shiny::tags$p(class = "fpa-ai-user-empty", fpa_screen("ai_sets_empty")))
    favs <- fpa_ai_fav_read(shiny::isolate(cfg_path()))$favorites
    saved <- fpa_ai_user_prompts_read(shiny::isolate(cfg_path()))
    saved_ids <- vapply(saved, function(x) x$id, character(1))
    cat_ids <- vapply(fpa_ai_catalog(), function(x) x$id, character(1))
    lapply(seq_along(ids), function(i) {
      id <- ids[[i]]
      missing <- !(id %in% cat_ids || id %in% saved_ids)
      off <- !missing && !(id %in% favs)
      flag <- if (missing) fpa_screen("ai_sets_missing") else if (off) fpa_screen("ai_sets_off_fav") else ""
      shiny::tags$div(
        class = "fpa-ai-set-row",
        draggable = "true",
        `data-i` = i,
        title = fpa_screen("ai_sets_drag"),
        shiny::tags$span(class = "fpa-ai-set-num", i),
        shiny::tags$div(
          class = "fpa-ai-set-name",
          fpa_ai_prompt_label(id, lang),
          if (nzchar(flag)) shiny::tags$span(class = "fpa-ai-set-flag", flag)
        ),
        shiny::tags$div(
          class = "fpa-ai-set-ops",
          shiny::tags$button(
            type = "button", title = fpa_screen("ai_sets_top"),
            onclick = sprintf("Shiny.setInputValue('ai_set_move',{i:%d,dir:'top'},{priority:'event'})", i),
            shiny::HTML(fpa_pm_icon("top"))
          ),
          shiny::tags$button(
            type = "button", title = fpa_screen("ai_sets_up"),
            onclick = sprintf("Shiny.setInputValue('ai_set_move',{i:%d,dir:'up'},{priority:'event'})", i),
            shiny::HTML(fpa_pm_icon("up"))
          ),
          shiny::tags$button(
            type = "button", title = fpa_screen("ai_sets_down"),
            onclick = sprintf("Shiny.setInputValue('ai_set_move',{i:%d,dir:'down'},{priority:'event'})", i),
            shiny::HTML(fpa_pm_icon("down"))
          ),
          shiny::tags$button(
            type = "button", title = fpa_screen("ai_sets_bottom"),
            onclick = sprintf("Shiny.setInputValue('ai_set_move',{i:%d,dir:'bottom'},{priority:'event'})", i),
            shiny::HTML(fpa_pm_icon("bottom"))
          ),
          shiny::tags$button(
            type = "button", class = "is-danger", title = fpa_screen("ai_sets_remove"),
            onclick = sprintf("Shiny.setInputValue('ai_set_remove',%d,{priority:'event'})", i),
            shiny::HTML(fpa_pm_icon("trash"))
          )
        )
      )
    })
  })
  output$ai_status <- shiny::renderUI({
    txt <- ai_status_txt()
    if (!nzchar(txt)) return(NULL)
    shiny::tags$p(class = "fpa-pm-lead", txt)
  })
  output$ai_answer <- shiny::renderUI({
    txt <- ai_answer()
    if (!nzchar(txt)) return(NULL)
    shiny::tags$div(class = "fpa-ai-answer", shiny::markdown(txt))
  })
  output$ai_sent <- shiny::renderUI({
    txt <- ai_sent_txt()
    if (!nzchar(txt)) return(NULL)
    shiny::tags$pre(class = "fpa-ai-sent", txt)
  })
  shiny::observe({
    ai_rev()
    ui_lang()
    has_answer <- nzchar(ai_answer())
    path <- fpa_ai_settings_now()$open_report
    open <- nzchar(path) && file.exists(path)
    text <- if (open) fpa_ai_read_utf8(path) else ""
    sealed_open <- open && fpa_ai_report_sealed(text)
    heads <- if (open) regmatches(text, gregexpr("(?m)^## .*$", text, perl = TRUE))[[1]] else character(0)
    heads <- sub("^## ", "", heads)
    formatted <- any(heads == "Note")
    n_ans <- sum(!heads %in% c("Note", "Annexe"))
    already <- has_answer && open && !sealed_open && fpa_ai_report_contains(path, ai_answer())
    from_batch <- isTRUE(ai_from_batch())
    running <- ai_batch()
    title_now <- if (open) fpa_ai_report_title(text) else ""
    last <- shiny::isolate(ai_last_report())
    last_text <- if (!open && nzchar(last) && file.exists(last)) fpa_ai_read_utf8(last) else ""
    sealed_old <- if (sealed_open) TRUE else fpa_ai_report_sealed(last_text)
    st <- function(state, note = "") list(state = state, note = note)
    after <- function(i) fpa_screen("ai_step_after", i)
    step2 <- if (!open || sealed_open) {
      st(if (sealed_open) "done" else "locked", if (sealed_open) fpa_screen("ai_sealed_old") else after(1))
    } else if (n_ans > 0L && !formatted) {
      note <- if (already) {
        fpa_screen("ai_step_more_in", n_ans)
      } else if (!has_answer) {
        fpa_screen("ai_step_more", n_ans)
      } else {
        fpa_screen("ai_step_ready")
      }
      st("current", note)
    } else if (!has_answer) {
      st(if (n_ans) "done" else "current", if (n_ans) fpa_screen("ai_step_count", n_ans) else fpa_screen("ai_step_ask"))
    } else if (already || (formatted && from_batch)) {
      st("done", if (from_batch) fpa_screen("ai_step_batch_done", n_ans) else paste(fpa_screen("ai_step_count", n_ans), fpa_screen("ai_step_added"), sep = " · "))
    } else {
      st("current", fpa_screen("ai_step_ready"))
    }
    if (!is.null(running) && open) {
      nq <- length(running$queue)
      iq <- as.integer(running$index %||% 1L)
      done_n <- max(0L, iq - 1L)
      if (identical(running$phase, "format")) {
        step2 <- st("done", fpa_screen("ai_batch_format", nq, nq))
      } else if (nq > 0L) {
        cur <- running$queue[[min(iq, nq)]]$title %||% ""
        step2 <- st("current", fpa_screen("ai_batch_progress", done_n, nq, cur))
      }
    }
    hand <- if (!open || sealed_open || n_ans == 0L || !is.null(running)) {
      st("locked", after(3))
    } else if (formatted) {
      st("current", fpa_screen("ai_step_ready"))
    } else {
      st("later", fpa_screen("ai_step4_lead"))
    }
    steps <- if (!open) {
      list(
        st("current", if (nzchar(last)) fpa_screen("ai_step_new", basename(last)) else fpa_screen("ai_step_none")),
        step2, st("locked", after(2)), hand
      )
    } else if (sealed_open || n_ans == 0L) {
      list(
        st("done", fpa_screen("ai_step_open", title_now)),
        step2, st("locked", after(2)), hand
      )
    } else {
      list(
        st("done", fpa_screen("ai_step_open", title_now)),
        step2,
        if (formatted) st("done", fpa_screen("ai_step_done")) else st("later", fpa_screen("ai_step_later")),
        hand
      )
    }
    file <- if (open) path else last
    session$sendCustomMessage("fpa-ai-steps", list(
      steps = steps,
      has_answer = has_answer,
      can_add = has_answer && open && !sealed_open && !already && is.null(running) && !(formatted && from_batch),
      can_into = open && !sealed_open && n_ans > 0L && is.null(running) && formatted,
      file = if (nzchar(file)) basename(file) else "",
      nofile = fpa_screen("ai_report_nofile"),
      sealed_old = if (isTRUE(sealed_old)) fpa_screen("ai_sealed_old") else ""
    ))
  })
  shiny::observeEvent(input$ai_report_start, {
    title <- trimws(shiny::isolate(input$ai_report_title) %||% "")
    if (!nzchar(title)) title <- fpa_screen("ai_report_default")
    set <- fpa_ai_settings_now()
    home <- dirname(shiny::isolate(cfg_path()))
    path <- fpa_ai_report_start(
      shiny::isolate(cfg_path()), title, fpa_ai_closed_through(home),
      set$mode, set$provider, set$model
    )
    ai_from_batch(FALSE)
    ai_rev(shiny::isolate(ai_rev()) + 1L)
    ai_status_txt("")
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$ai_report_add, {
    path <- fpa_ai_settings_now()$open_report
    ans <- shiny::isolate(ai_answer())
    if (!nzchar(path) || !nzchar(ans)) return()
    if (fpa_ai_report_contains(path, ans)) {
      ai_status_txt(fpa_screen("ai_step_added"))
      ai_rev(shiny::isolate(ai_rev()) + 1L)
      return()
    }
    head <- trimws(shiny::isolate(ai_title_txt()))
    if (!nzchar(head) || identical(head, "Note")) head <- fpa_screen("ai_answer_head")
    head <- substr(gsub("[\r\n]+", " ", head), 1L, 120L)
    added <- tryCatch(
      fpa_ai_report_append(path, head, ans, shiny::isolate(ai_sent_txt()), fpa_ai_settings_now()$mode),
      error = function(e) {
        ai_status_txt(conditionMessage(e))
        NA_character_
      }
    )
    if (is.na(added)) ai_status_txt(fpa_screen("ai_step_added"))
    ai_rev(shiny::isolate(ai_rev()) + 1L)
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$ai_report_final, {
    path <- fpa_ai_settings_now()$open_report
    fpa_ai_finalize_start(path, purpose = "finalize")
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$ai_report_into, {
    path <- fpa_ai_settings_now()$open_report
    if (!nzchar(path) || !file.exists(path)) return()
    if (fpa_ai_report_sealed(fpa_ai_read_utf8(path))) return()
    shiny::updateCheckboxInput(session, "rep_el_ai_note", value = TRUE)
    bslib::nav_select("main_nav", "Composer", session = session)
    session$sendCustomMessage("fpa-rep-open-analyst", list(open = TRUE))
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$rep_open_workshop, {
    bslib::nav_select("main_nav", "Analyste", session = session)
  }, ignoreInit = TRUE)
  fpa_ai_report_shown <- function() {
    path <- fpa_ai_settings_now()$open_report
    if (!nzchar(path)) path <- shiny::isolate(ai_last_report())
    if (!nzchar(path) || !file.exists(path)) return("")
    path
  }
  shiny::observeEvent(input$ai_report_erase, {
    path <- fpa_ai_report_shown()
    if (!nzchar(path)) return()
    ai_erase_path(path)
    shiny::showModal(shiny::modalDialog(
      title = fpa_screen("ai_report_erase_title"),
      easyClose = TRUE,
      footer = shiny::tagList(
        shiny::actionButton("ai_report_erase_cancel", fpa_screen("ai_prompt_cancel"), class = "fpa-pm-btn is-ghost"),
        shiny::actionButton("ai_report_erase_ok", fpa_screen("ai_report_erase_ok"), class = "fpa-pm-btn is-danger")
      ),
      shiny::tags$p(fpa_screen("ai_report_erase_body", basename(path)))
    ))
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$ai_report_erase_cancel, {
    ai_erase_path("")
    shiny::removeModal()
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$ai_report_erase_ok, {
    path <- shiny::isolate(ai_erase_path())
    dir <- fpa_ai_report_dir(shiny::isolate(cfg_path()))
    inside <- nzchar(path) && nzchar(dir) && startsWith(normalizePath(path, winslash = "/", mustWork = FALSE), normalizePath(dir, winslash = "/", mustWork = FALSE))
    if (inside && file.exists(path)) unlink(path)
    cur <- fpa_ai_settings_now()
    if (identical(cur$open_report, path)) {
      cur$open_report <- ""
      fpa_ai_settings_write(shiny::isolate(cfg_path()), cur)
    }
    if (identical(shiny::isolate(ai_last_report()), path)) ai_last_report("")
    ai_erase_path("")
    shiny::removeModal()
    ai_rev(shiny::isolate(ai_rev()) + 1L)
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$ai_report_folder, {
    dir <- fpa_ai_report_dir(shiny::isolate(cfg_path()))
    if (nzchar(dir)) {
      dir.create(dir, recursive = TRUE, showWarnings = FALSE)
      utils::browseURL(dir)
    }
  }, ignoreInit = TRUE)
  output$ai_report_file <- shiny::downloadHandler(
    filename = function() {
      path <- fpa_ai_settings_now()$open_report
      if (!nzchar(path)) path <- shiny::isolate(ai_last_report())
      if (nzchar(path)) basename(path) else "rapport.md"
    },
    content = function(file) {
      path <- fpa_ai_settings_now()$open_report
      if (!nzchar(path)) path <- shiny::isolate(ai_last_report())
      if (nzchar(path) && file.exists(path)) file.copy(path, file, overwrite = TRUE)
    }
  )
  output$params_home <- shiny::renderUI({
    params_tick()
    ai_rev()
    local <- identical(sync_mode(), "local")
    p <- pack()
    if (!isTRUE(p$ok)) {
      return(shiny::tags$p(class = "fpa-params-hint", fpa_screen("params_no_key")))
    }
    cfg <- p$config
    path <- as.character(p$config_path %||% "")
    home <- dirname(path)
    proj <- cfg$project %||% list()
    titled <- fpa_shiny_project_title(cfg)
    name <- titled$name
    company_name <- titled$company
    pnl <- file.path(p$paths$work %||% "", "pnl-monthly.csv")
    calc <- if (nzchar(pnl) && file.exists(pnl)) format(file.info(pnl)$mtime, "%Y-%m-%d %H:%M") else ""
    grades <- file.path(p$paths$work %||% "", "drivers", "driver-grades.csv")
    ndrv <- if (file.exists(grades)) tryCatch(nrow(utils::read.csv(grades)), error = function(e) 0L) else 0L
    contact <- fpa_sync_contact(path)
    delta <- fpa_sync_read_delta(path)
    has_link <- nzchar(fpa_shiny_project_link(cfg))
    net_off <- local || !has_link

    icon <- function(name) shiny::HTML(fpa_pm_icon(name))
    btn <- function(id, label, ico, ghost = FALSE, off = FALSE, tip = label) {
      args <- list(
        id, label = shiny::tagList(icon(ico), shiny::tags$span(label)),
        class = paste("fpa-pm-btn", if (ghost) "is-ghost"),
        title = tip, `aria-label` = tip
      )
      if (off) args$disabled <- TRUE
      do.call(shiny::actionButton, args)
    }
    mode_btn <- function(value, label, sub, ico, on) {
      shiny::tags$button(
        type = "button", role = "radio", `aria-checked` = if (on) "true" else "false",
        class = paste("fpa-pm-mode-btn", if (on) "is-on"),
        onclick = sprintf("Shiny.setInputValue('params_mode','%s',{priority:'event'})", value),
        icon(ico),
        shiny::tags$span(shiny::tags$strong(label), shiny::tags$small(sub))
      )
    }
    lang_btn <- function(value, label, on) {
      shiny::tags$button(
        type = "button", role = "radio", `aria-checked` = if (on) "true" else "false",
        class = paste("fpa-pm-mode-btn", if (on) "is-on"),
        onclick = sprintf("Shiny.setInputValue('params_lang','%s',{priority:'event'})", value),
        shiny::tags$span(shiny::tags$strong(label))
      )
    }
    card <- function(title, ico, ..., net = FALSE, wide = FALSE, badge = NULL) {
      shiny::tags$section(
        class = paste("fpa-pm-card", if (net) "is-net", if (wide) "is-wide"),
        shiny::tags$div(
          class = "fpa-pm-card-head",
          shiny::tags$h3(icon(ico), title),
          if (!is.null(badge)) shiny::tags$span(class = "fpa-pm-badge", badge)
        ),
        ...
      )
    }
    tile <- function(label, value) {
      shiny::tags$div(
        class = "fpa-pm-tile",
        shiny::tags$span(class = "fpa-pm-tile-label", label),
        shiny::tags$span(class = "fpa-pm-tile-value", if (nzchar(value)) value else fpa_screen("pm_none"))
      )
    }
    rows <- function(...) {
      pairs <- list(...)
      pairs <- pairs[!vapply(pairs, is.null, logical(1))]
      shiny::tags$dl(class = "fpa-pm-rows", lapply(pairs, function(x) {
        shiny::tagList(shiny::tags$dt(x[[1]]), shiny::tags$dd(x[[2]]))
      }))
    }
    path_row <- function(value) {
      shown <- normalizePath(value, winslash = "\\", mustWork = FALSE)
      shiny::tags$span(
        class = "fpa-pm-path",
        shiny::tags$code(shown),
        shiny::tags$button(
          type = "button", class = "fpa-pm-copy", `data-path` = shown, `data-done` = fpa_screen("pm_copied"),
          onclick = "var b=this;navigator.clipboard.writeText(b.dataset.path).then(function(){b.lastChild.textContent=b.dataset.done;});",
          icon("copy"), shiny::tags$span(fpa_screen("pm_copy"))
        )
      )
    }

    status_txt <- function(x) {
      st <- as.character(x$status %||% "")
      switch(st,
        unchanged = fpa_screen("pm_status_unchanged"),
        pulled = fpa_screen("pm_status_pulled", as.character(x$revision %||% "")),
        offline = fpa_screen("pm_status_offline"),
        refused = fpa_screen("pm_status_refused"),
        missing = fpa_screen("pm_status_missing"),
        ""
      )
    }
    cfg_check <- contact$config %||% list()
    checked <- if (nzchar(as.character(cfg_check$at %||% ""))) {
      paste(c(fpa_shiny_ago(cfg_check$at), status_txt(cfg_check))[nzchar(c(fpa_shiny_ago(cfg_check$at), status_txt(cfg_check)))], collapse = " \u00b7 ")
    } else fpa_screen("pm_never")
    received <- if (!is.null(delta) && !is.null(delta$revision)) {
      paste0(fpa_screen("params_card_rev", delta$revision), " \u00b7 ", fpa_shiny_ago(delta$at), " \u00b7 ", fpa_shiny_delta_body(delta))
    } else fpa_screen("pm_never")

    st <- fpa_shiny_script_rows(home, server_scripts())
    role <- c("fpa-engine.R" = fpa_screen("pm_script_role_engine"), "app.R" = fpa_screen("pm_script_role_screen"))
    script_row <- function(r) {
      state <- r$state
      ico <- switch(state, ok = "check", old = "warn", missing = "warn", "dash")
      pill <- switch(state,
        ok = fpa_screen("pm_script_ok"),
        old = fpa_screen("pm_script_old", r$want),
        missing = fpa_screen("pm_script_missing", r$want),
        ahead = fpa_screen("pm_script_ahead", r$want),
        fpa_screen("pm_script_unchecked")
      )
      shiny::tags$div(
        class = paste0("fpa-pm-script is-", state),
        shiny::tags$span(class = "fpa-pm-script-ico", icon(ico)),
        shiny::tags$span(
          class = "fpa-pm-script-name",
          shiny::tags$strong(r$local_file),
          shiny::tags$small(unname(role[[r$file]] %||% ""))
        ),
        shiny::tags$span(class = "fpa-pm-script-ver", if (nzchar(r$have)) r$have else "\u2014"),
        shiny::tags$span(class = paste0("fpa-pm-state is-", state), pill)
      )
    }
    sc <- contact$scripts %||% list()
    scripts_meta <- if (nzchar(as.character(sc$at %||% ""))) {
      paste0(
        fpa_screen("pm_scripts_checked", fpa_shiny_ago(sc$at)),
        if (identical(as.character(sc$status %||% ""), "offline")) fpa_screen("pm_scripts_failed") else ""
      )
