        )
      ),
      shiny::tags$p(style = "font-weight:600;color:#1f4e5f;margin:0 0 8px;", draft$title %||% ""),
      if (is.finite(suppressWarnings(as.numeric(draft$amount)))) shiny::tags$p(
        style = "margin:0 0 8px;",
        fpa_screen("journal_amount"), ": ",
        if (nzchar(draft$amount_label %||% "")) paste0(draft$amount_label, " · ") else "",
        fpa_shiny_eur(draft$amount), " EUR"
      ) else NULL,
      if (!simple) shiny::radioButtons(
        "journal_type", fpa_screen("journal_type_label"),
        choices = stats::setNames(
          FPA_JOURNAL_TYPES,
          c(fpa_screen("journal_type_observation"), fpa_screen("journal_type_scenario"), fpa_screen("journal_type_decision"))
        ),
        selected = draft$type %||% "observation"
      ),
      shiny::textAreaInput(
        "journal_note", if (simple) fpa_screen("out_journal_simple_note") else fpa_screen("journal_note_label"),
        value = draft$note %||% "", rows = if (simple) 2 else 3, width = "100%",
        placeholder = fpa_screen("journal_note_ph")
      ),
      if (!simple) shiny::tagList(
        shiny::textInput("journal_review", fpa_screen("journal_review"), value = draft$review_date %||% "", width = "100%"),
        shiny::textInput("journal_owner", fpa_screen("journal_owner"), value = draft$owner %||% "", width = "100%"),
        shiny::textInput("journal_due", fpa_screen("journal_due"), value = draft$due %||% "", width = "100%"),
        shiny::selectInput(
          "journal_state", fpa_screen("journal_state"),
          choices = stats::setNames(
            c("open", "watching", "done"),
            c(fpa_screen("journal_state_open"), fpa_screen("journal_state_watching"), fpa_screen("journal_state_done"))
          ),
          selected = if (nzchar(draft$state %||% "")) draft$state else "open",
          width = "100%", selectize = FALSE
        )
      )
    ))
  }

  shiny::observeEvent(input$sync, {
    path <- cfg_path()
    if (!nzchar(path)) path <- fpa_shiny_find_config()
    if (!nzchar(path)) {
      fpa_sync_show(fpa_screen("sync_bad"), "", waiting = FALSE)
      return()
    }
    cfg_path(path)
    fpa_sync_show(fpa_screen("nav_sync_busy"), fpa_screen("sync_wait_files"), waiting = TRUE)
    fpa_sync_later({
      before_p <- shiny::isolate(pack())
      before_entries <- shiny::isolate(journal_entries())
      before_tg <- fpa_todo_queue(before_p, before_entries)
      got <- tryCatch(
        fpa_shiny_sync(path, pull = list(status = "files", changed = FALSE, message = ""), force = TRUE),
        error = function(e) list(pack = pack(), status = "run_fail", newer = character(0), detail = conditionMessage(e), changed = list())
      )
      if (isTRUE(got$pack$ok) && got$status %in% c("fresh", "rebuilt", "drv_fail")) {
        fpa_shiny_sync_stamp_write(got$pack$paths)
      }
      if (!is.null(got$pack)) pack(got$pack)
      if (isTRUE(got$pack$ok) && got$status %in% c("fresh", "rebuilt")) {
        after_tg <- fpa_todo_queue(got$pack, before_entries)
        if (fpa_todo_retire_resolved(got$pack$paths, before_tg, after_tg) > 0L) {
          todo_clear_rev(shiny::isolate(todo_clear_rev()) + 1L)
        }
      }
      if (isTRUE(got$first)) {
        changed_list(list(list(id = "first", label = fpa_screen("home_changed_first"), when = "", tab = fpa_screen("loc_summary"), line = "", periode = "", abs_delta = 0)))
      } else {
        changed_list(got$changed %||% list())
      }
      note <- if (identical(got$status, "fresh")) {
        fpa_screen("sync_fresh")
      } else if (identical(got$status, "rebuilt") && !length(got$newer)) {
        fpa_screen("sync_reread")
      } else if (identical(got$status, "rebuilt")) {
        fpa_screen("sync_rebuilt", paste(got$newer, collapse = ", "))
      } else if (identical(got$status, "drv_fail")) {
        fpa_screen("sync_drv_fail", got$detail %||% "")
      } else if (identical(got$status, "run_fail")) {
        fpa_screen("sync_run_fail", got$detail %||% "")
      } else {
        fpa_screen("sync_bad")
      }
      extra <- if (!is.null(got$pull) && nzchar(as.character(got$pull$message %||% ""))) as.character(got$pull$message) else ""
      fpa_sync_show(note, extra, waiting = FALSE)
    })
  }, ignoreInit = TRUE)

