      ),
      shiny::div(
        class = "fpa-fold-body",
        if (!length(rows)) shiny::tags$p(class = "fpa-journal-meta", fpa_screen("todo_cleared_empty")) else lapply(rev(seq_along(rows)), function(i) {
        e <- rows[[i]]
