              " · ", fpa_screen("journal_from"), " ", e$source_tab,
              if (nzchar(e$source_metric %||% "")) paste0(" · ", e$source_metric) else "",
              if (nzchar(e$periode %||% "")) paste0(" · ", e$periode) else ""
            ),
            shiny::tags$p(class = "fpa-journal-title", e$title),
