  output$journal_due <- shiny::renderUI({
    p <- pack()
    if (!isTRUE(p$ok)) return(NULL)
    entries <- journal_entries()
    bits <- list()
    for (e in entries) {
      fu <- fpa_journal_followup(e, p$finance$cash, p$finance$pnl, p$finance$period_status)
      if (!isTRUE(fu$show) || !isTRUE(fu$due)) next
      sentence <- fpa_journal_followup_text(fu)
      if (!nzchar(sentence)) next
      neg <- is.finite(fu$gap) && fu$gap < 0
      bits[[length(bits) + 1L]] <- shiny::tags$li(
        style = if (neg) "color:#8c3a3a;" else NULL,
        shiny::tags$span(style = "font-weight:600;", e$title %||% ""),
        " ",
        sentence
      )
    }
    if (!length(bits)) return(NULL)
    shiny::tags$section(
      class = "fpa-changed",
      shiny::tags$h3(fpa_screen("journal_due_title")),
      shiny::tags$ul(bits)
    )
  })

  journal_detail_ui <- function(focus) {
    if (is.null(focus)) return(NULL)
    snap_bits <- character()
    sn <- focus$snapshot %||% list()
    if (!is.null(sn$moves)) snap_bits <- c(snap_bits, paste("Mouvements:", sn$moves))
    if (!is.null(sn$cash_close)) snap_bits <- c(snap_bits, paste(fpa_screen("loc_cash_colon"), fpa_shiny_eur(sn$cash_close), "EUR"))
    if (!is.null(sn$cash_delta)) snap_bits <- c(snap_bits, paste(fpa_screen("loc_cash_gap_colon"), fpa_shiny_eur(sn$cash_delta), "EUR"))
    if (!is.null(sn$oi_fy)) {
      inf <- list(measured = as.character(sn$ye_month %||% ""))
      snap_bits <- c(snap_bits, paste0(fpa_shiny_obj_metric_lab("oi_fy", inf), " : ", fpa_shiny_eur(sn$oi_fy), " EUR"))
      if (!is.null(sn$oi_last)) {
        snap_bits <- c(snap_bits, paste0(fpa_shiny_obj_metric_lab("oi_ye", inf), " : ", fpa_shiny_eur(sn$oi_last), " EUR"))
      }
    } else if (!is.null(sn$oi)) {
      snap_bits <- c(snap_bits, paste("RE:", fpa_shiny_eur(sn$oi), "EUR"))
    }
    if (!is.null(sn$sentence)) snap_bits <- c(snap_bits, sn$sentence)
    if (!is.null(sn$text)) snap_bits <- c(snap_bits, sn$text)
    if (!is.null(sn$v)) snap_bits <- c(snap_bits, paste(sn$k %||% "", sn$v, sn$s %||% ""))
    if (identical(as.character(focus$source_metric %||% ""), "outlook_4w") || !is.null(sn$as_of)) {
      snap_bits <- c(snap_bits, fpa_outlook_journal_bits(sn))
    }
    if (!length(snap_bits) && length(sn)) {
      snap_bits <- vapply(names(sn), function(nm) {
        paste0(nm, ": ", paste(as.character(sn[[nm]]), collapse = ", "))
      }, character(1))
    }
    p <- pack()
    fu_ui <- NULL
    if (isTRUE(p$ok) && identical(as.character(focus$type %||% ""), "decision")) {
      fu <- fpa_journal_followup(focus, p$finance$cash, p$finance$pnl, p$finance$period_status)
      sentence <- fpa_journal_followup_text(fu)
      if (nzchar(sentence)) {
        tone <- if (is.finite(fu$gap) && fu$gap < 0) "color:#8c3a3a;" else NULL
        fu_ui <- shiny::tags$p(class = "fpa-journal-meta", style = tone, shiny::tags$strong(fpa_screen("journal_fu_kicker")), " · ", sentence)
      }
    }
    withdrawn <- identical(as.character(focus$state %||% ""), "withdrawn")
    is_bank <- identical(as.character(focus$source_metric %||% ""), "outlook_4w")
    shiny::tags$div(
      class = "fpa-journal-detail",
      shiny::tags$h3(focus$title),
      if (withdrawn) shiny::tags$span(class = "fpa-journal-withdrawn", fpa_screen("journal_withdrawn_badge")),
      shiny::tags$p(
        class = "fpa-journal-meta",
        fpa_screen("journal_context"), ": ",
        focus$company, " · ", focus$source_tab, " · ", focus$created_at
      ),
      if (withdrawn) shiny::tags$p(class = "fpa-journal-meta", fpa_screen("journal_withdrawn_note")),
      fu_ui,
      if (nzchar(focus$note %||% "")) shiny::tags$p(shiny::tags$strong(fpa_screen("journal_note_label")), ": ", focus$note),
      if (is.finite(suppressWarnings(as.numeric(focus$amount)))) shiny::tags$p(
        fpa_screen("journal_amount"), ": ",
        if (nzchar(focus$amount_label %||% "")) paste0(focus$amount_label, " · ") else "",
        fpa_shiny_eur(focus$amount), " EUR"
      ),
      shiny::tags$div(
        class = "fpa-journal-snap",
        shiny::tags$strong(fpa_screen("journal_snapshot")),
        shiny::tags$ul(style = "margin:6px 0 0;padding-left:1.1rem;", lapply(snap_bits, shiny::tags$li))
      ),
      shiny::tags$div(
        class = "fpa-journal-actions",
        if (nzchar(focus$link$tab %||% "")) shiny::tags$button(
          type = "button", class = "fpa-go-btn",
          onclick = sprintf(
            "Shiny.setInputValue('fpa_go',{tab:'%s',line:'%s',periode:'%s'},{priority:'event'})",
            focus$link$tab %||% "", focus$link$line %||% "", focus$link$periode %||% ""
          ),
          fpa_screen("journal_open")
        ) else NULL,
        if (is_bank && !withdrawn) shiny::tags$button(
          type = "button", class = "fpa-go-btn is-quiet",
          onclick = sprintf(
            "Shiny.setInputValue('journal_withdraw','%s',{priority:'event'})",
            focus$id
          ),
          fpa_screen("journal_withdraw")
        ) else NULL,
        if (is_bank && withdrawn) shiny::tags$button(
          type = "button", class = "fpa-go-btn is-quiet",
          onclick = sprintf(
            "Shiny.setInputValue('journal_restore_keep','%s',{priority:'event'})",
            focus$id
          ),
          fpa_screen("journal_restore_keep")
        ) else NULL
      )
    )
  }

  shiny::observeEvent(input$journal_open, {
    id <- as.character(input$journal_open %||% "")
    if (identical(id, shiny::isolate(journal_focus()))) journal_focus("") else journal_focus(id)
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$journal_star, {
    p <- pack()
    if (!isTRUE(p$ok)) return()
    id <- as.character(input$journal_star %||% "")
    cur <- fpa_journal_get(fpa_journal_read(p$paths), id)
    if (is.null(cur)) return()
    fpa_journal_set_favorite(p$paths, id, !isTRUE(cur$favorite))
    journal_rev(journal_rev() + 1L)
