  #' After a bank diamond is withdrawn or restored, refresh the cash form to the live reading.
  #' Pass `entries` from the write result so we do not read a stale reactive.
  fpa_out_hydrate_from_journal <- function(entries = NULL) {
    p <- pack()
    if (!isTRUE(p$ok) || !isTRUE(out_loaded())) return()
    saved <- tryCatch(fpa_outlook_read(p$config), error = function(e) NULL)
    opening <- suppressWarnings(as.numeric(saved$opening %||% NA_real_))
    as_of <- fpa_outlook_date(saved$as_of %||% Sys.Date())
    if (!is.finite(opening)) {
      ents <- entries %||% tryCatch(journal_entries(), error = function(e) list())
      declared <- tryCatch(fpa_synth_latest_declared(ents), error = function(e) NULL)
      if (!is.null(declared) && is.finite(declared$opening)) {
        opening <- declared$opening
        as_of <- fpa_outlook_date(declared$as_of)
      } else {
        opening <- NA_real_
      }
    }
    if (is.finite(as_of)) shiny::updateDateInput(session, "out_asof", value = as_of)
    if (is.finite(opening)) {
      shiny::updateNumericInput(session, "out_open", value = opening)
    } else {
      shiny::updateNumericInput(session, "out_open", value = NA_real_)
    }
    invisible(NULL)
  }

  shiny::observeEvent(input$journal_withdraw, {
    p <- pack()
    if (!isTRUE(p$ok)) return()
    id <- as.character(input$journal_withdraw %||% "")
    got <- fpa_journal_withdraw(p$paths, id)
    if (!isTRUE(got$ok)) return()
    # If the live outlook still holds this diamond's amount, clear it so the form
    # follows the next active journal entry (or modeled cash). Local file only.
    ent <- got$entry
    if (!is.null(ent) && identical(as.character(ent$source_metric %||% ""), "outlook_4w")) {
      sn <- ent$snapshot %||% list()
      wd_open <- suppressWarnings(as.numeric(if (!is.null(sn$opening)) sn$opening else ent$amount))
      wd_asof <- as.character(sn$as_of %||% ent$periode %||% "")
      saved <- tryCatch(fpa_outlook_read(p$config), error = function(e) NULL)
      if (!is.null(saved) && is.finite(wd_open) && is.finite(saved$opening) &&
            abs(saved$opening - wd_open) < 0.5 &&
            identical(as.character(saved$as_of %||% ""), wd_asof)) {
        tryCatch(
          fpa_outlook_write(p$config, list(
            as_of = saved$as_of,
            opening = NA_real_,
            items = saved$items %||% list()
          )),
          error = function(e) NULL
        )
      }
    }
    journal_rev(journal_rev() + 1L)
    todo_clear_rev(shiny::isolate(todo_clear_rev()) + 1L)
    fpa_out_hydrate_from_journal(got$entries)
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$journal_restore_keep, {
    p <- pack()
    if (!isTRUE(p$ok)) return()
    id <- as.character(input$journal_restore_keep %||% "")
    got <- fpa_journal_restore_keep(p$paths, id)
    if (!isTRUE(got$ok)) return()
    journal_rev(journal_rev() + 1L)
    todo_clear_rev(shiny::isolate(todo_clear_rev()) + 1L)
    fpa_out_hydrate_from_journal(got$entries)
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$journal_confirm, {
    p <- pack()
    draft <- journal_draft()
    if (!isTRUE(p$ok) || is.null(draft)) return()
    simple <- isTRUE(draft$snapshot$simple)
    draft$type <- if (simple) "observation" else as.character(input$journal_type %||% draft$type)
    draft$note <- as.character(input$journal_note %||% "")
    draft$review_date <- if (simple) "" else as.character(input$journal_review %||% "")
    draft$owner <- if (simple) "" else as.character(input$journal_owner %||% "")
    draft$due <- if (simple) "" else as.character(input$journal_due %||% "")
    draft$state <- if (simple) "open" else as.character(input$journal_state %||% "open")
    got <- fpa_journal_add(p$paths, draft)
    shiny::removeModal()
    journal_draft(NULL)
    if (isTRUE(got$ok)) {
      sn <- draft$snapshot %||% list()
      fam <- as.character(sn$family %||% "")
      lid <- as.character(sn$line_id %||% "")
      if (fam %in% c("books", "ratio") && nzchar(lid)) {
        fpa_todo_cleared_add(
          p$paths,
          paste0("anom:", fpa_anom_row_dom_id(fam, sn$periode %||% "", lid)),
          draft$title %||% "",
          as.character(sn$sentence %||% draft$title %||% ""),
          "journal",
          ""
        )
        todo_clear_rev(shiny::isolate(todo_clear_rev()) + 1L)
      }
      journal_rev(journal_rev() + 1L)
      journal_focus(got$id)
      shiny::showNotification(fpa_screen("journal_saved"), type = "message", duration = 4)
      if (identical(as.character(draft$source_metric %||% ""), "outlook_4w")) {
        shiny::updateRadioButtons(session, "synth_hero_mode", selected = "cash")
        bslib::nav_select("main_nav", fpa_screen("loc_summary"), session = session)
        session$sendCustomMessage("fpa-open-details", list(sel = "#plot_cash_line"))
      }
    }
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$journal_capture, {
    p <- pack()
    if (!isTRUE(p$ok)) return()
    cap <- input$journal_capture
    if (!is.list(cap)) return()
    kind <- as.character(cap$kind %||% "")
    draft <- NULL
    if (identical(kind, "anomaly")) {
      draft <- fpa_journal_from_anomaly(
        p, cap$family %||% "", cap$line %||% "", cap$periode %||% "",
        cap$gap %||% NA, cap$sentence %||% ""
      )
    } else if (identical(kind, "kpi")) {
      draft <- fpa_journal_from_kpi(p, cap$id %||% "", cap$k %||% "", cap$v %||% "", cap$s %||% "")
    } else if (identical(kind, "fifo")) {
      draft <- fpa_journal_from_fifo(p, cap$text %||% "")
    } else if (identical(kind, "scenario")) {
      log <- scn_log()
      ix <- suppressWarnings(as.integer(cap$ix %||% length(log)))
      if (!length(log) || is.na(ix) || ix < 1L || ix > length(log)) return()
      draft <- fpa_journal_from_scenario(p, log[[ix]], type = as.character(cap$type %||% "explored_scenario"))
    }
    if (!is.null(draft)) fpa_journal_show_modal(draft)
  }, ignoreInit = TRUE)

