  fe_kpi <- shiny::reactiveVal("")
  fe_kind <- shiny::reactiveVal("pnl")
  fe_line <- shiny::reactiveVal("")

  shiny::observeEvent(input$oi_file, {
    file <- basename(as.character(input$oi_file$file %||% ""))
    periode <- as.character(input$oi_file$periode %||% "")
    kind <- as.character(input$oi_file$kind %||% "pnl")
    line <- gsub("[^A-Za-z0-9_]", "", as.character(input$oi_file$line %||% ""))
    if (!kind %in% c("pnl", "cash", "bs")) kind <- "pnl"
    p <- pack()
