      fresh, fe_back(),
      if (isTRUE(res$ok)) fpa_screen("oi_file_saved", res$n) else "",
      fe_kind(), fe_line(), fe_kpi()
    ))
  })

  fpa_shiny_open_stmt <- function(stmt, periode, line) {
    p <- pack()
    periode <- as.character(periode %||% "")
    line <- gsub("[^A-Za-z0-9_]", "", as.character(line %||% ""))
    stmt <- as.character(stmt %||% "pnl")
    if (!isTRUE(p$ok) || !nzchar(periode)) return()
    if (identical(stmt, "cash")) {
      read <- fpa_cash_cell_read(p$config, periode, p$paths, line)
      if (isTRUE(read$ok)) shiny::showModal(fpa_shiny_flow_modal(read))
      return()
    }
    if (identical(stmt, "bs")) {
      read <- fpa_bs_cell_read(p$config, periode, p$paths, line)
      if (isTRUE(read$ok)) shiny::showModal(fpa_shiny_flow_modal(read))
      return()
    }
    read <- fpa_oi_cell_read(p$config, periode, p$paths)
    if (isTRUE(read$ok)) shiny::showModal(fpa_shiny_oi_modal(read, if (nzchar(line)) line else "OI"))
  }

