  shiny::observeEvent(input$raw_unlock, {
    cfg <- pack()$config
    if (is.null(cfg) || !nzchar(raw_node())) return()
    shiny::showModal(fpa_shiny_raw_modal(cfg, raw_node(), edit = TRUE, cash = manual_cash_now()))
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$raw_save, {
    p <- pack()
    cfg <- p$config
    if (is.null(cfg) || !nzchar(raw_node())) return()
    if (identical(raw_node(), "manual:ledger")) {
      got <- fpa_manual_read(cfg)
      df <- got$data
      note <- fpa_screen("man_file_same")
      if (!is.null(df) && nrow(df) && !is.null(input[["maned_lib_1"]])) {
        rows <- lapply(seq_len(nrow(df)), function(i) {
          row <- as.list(df[i, , drop = FALSE])
          lib <- input[[paste0("maned_lib_", i)]]
          if (is.null(lib)) return(row)
          row$libelle <- trimws(as.character(lib))
          sens <- as.character(input[[paste0("maned_sens_", i)]] %||% row$sens)
          if (sens %in% c("in", "out")) row$sens <- sens
          nature <- as.character(input[[paste0("maned_nat_", i)]] %||% row$nature)
          if (nature %in% c("nouveau", "decalage")) row$nature <- nature
          amt <- suppressWarnings(as.numeric(input[[paste0("maned_amt_", i)]]))
          if (is.finite(amt) && amt > 0) row$montant <- amt
          when <- fpa_manual_parse_date(input[[paste0("maned_date_", i)]])
          if (is.finite(when)) row$date_effet <- when
          if (identical(as.character(row$nature), "decalage")) {
            prev <- fpa_manual_parse_date(input[[paste0("maned_prev_", i)]])
            if (is.finite(prev)) row$date_prevue <- prev
          }
          if (identical(as.character(row$nature), "nouveau")) {
            ligne <- as.character(input[[paste0("maned_ligne_", i)]] %||% "")
            if (ligne %in% FPA_MANUAL_LIGNES) row$ligne <- ligne
          }
          statut <- as.character(input[[paste0("maned_stat_", i)]] %||% row$statut)
          if (statut %in% c("actif", "retire")) row$statut <- statut
          row
        })
        new_df <- fpa_manual_as_df(rows)
        old_df <- fpa_manual_as_df(lapply(seq_len(nrow(df)), function(i) as.list(df[i, , drop = FALSE])))
        keys <- c("nature", "sens", "montant", "date_effet", "date_prevue", "ligne", "libelle", "statut")
        same <- identical(
          lapply(keys, function(k) as.character(new_df[[k]])),
          lapply(keys, function(k) as.character(old_df[[k]]))
        )
        if (!same) {
          fpa_manual_write(cfg, new_df)
          cfg_p <- p$config_path %||% cfg_path()
          ran <- tryCatch(fpa_run(cfg_p, write = TRUE, stop_on_error = FALSE), error = function(e) e)
          if (!inherits(ran, "error")) {
            pack(fpa_shiny_load(cfg_p))
            manual_books(NULL)
          }
          note <- fpa_screen("man_file_saved")
        }
      }
      shiny::showModal(fpa_shiny_raw_modal(cfg, raw_node(), edit = TRUE, note = note, cash = manual_cash_now()))
      return()
    }
    sid <- sub("^src:", "", raw_node())
    src <- NULL
    for (s in cfg$sources %||% list()) {
      if (identical(as.character(s$source_id %||% ""), sid)) src <- s
    }
    path <- if (is.null(src)) "" else fpa_chain_source_path(cfg, src)
    got <- if (nzchar(path)) fpa_raw_preview_frame(path) else NULL
    df <- if (!is.null(got)) got$data else NULL
    note <- fpa_screen("raw_saved_none")
    if (!is.null(df) && nrow(df) && ncol(df)) {
      cap <- min(800L, nrow(df))
      values <- list()
      for (i in seq_len(cap)) {
        for (j in seq_len(ncol(df))) {
          id <- sprintf("rawc_%d_%d", i, j)
          val <- input[[id]]
          if (!is.null(val)) values[[sprintf("%d_%d", i, j)]] <- val
        }
      }
      res <- fpa_raw_edit_apply(path, values)
      note <- if (isTRUE(res$ok) && res$n > 0L) fpa_screen("raw_saved", res$n) else fpa_screen("raw_saved_none")
    }
    shiny::showModal(fpa_shiny_raw_modal(cfg, raw_node(), note = note, cash = manual_cash_now()))
  }, ignoreInit = TRUE)

