  budget_year_lock <- shiny::reactiveVal(FALSE)
  shiny::observeEvent(input$budget_year, {
    if (isTRUE(budget_year_lock())) return()
    raw <- as.character(input$budget_year %||% "")
    bits <- strsplit(raw, "\t", fixed = TRUE)[[1]]
    if (length(bits) < 2L) return()
    sid <- bits[[1]]
    year <- suppressWarnings(as.integer(bits[[2]]))
    if (is.na(year) || year < 2000L || year > 2100L) return()
    path <- cfg_path()
    if (!nzchar(path)) path <- fpa_shiny_find_config()
    if (!nzchar(path)) return()
    current <- pack()
    src <- NULL
    if (!is.null(current$config)) {
      for (s in current$config$sources %||% list()) {
        if (identical(as.character(s$source_id %||% ""), sid)) src <- s
      }
    }
    declared <- if (is.null(src)) NA_integer_ else fpa_budget_declared_year(src)
    if (!is.na(declared) && declared == year) return()
    budget_year_lock(TRUE)
    on.exit(budget_year_lock(FALSE), add = TRUE)
    wrote <- tryCatch(
      fpa_budget_write_year(path, year, sid),
      error = function(e) list(ok = FALSE, reason = "write")
    )
    if (!isTRUE(wrote$ok)) {
      msg <- if (identical(wrote$reason, "empty")) {
        fpa_screen("budget_year_empty_local")
      } else if (identical(wrote$reason, "missing")) {
        fpa_screen("budget_year_missing")
      } else {
        fpa_screen("budget_year_write_fail")
      }
      shiny::showNotification(msg, type = "warning", duration = 8)
      return()
    }
    if (isTRUE(wrote$unchanged)) return()
    shiny::showNotification(fpa_screen("budget_year_busy"), id = "fpa-budget-year", duration = NULL, type = "message")
    posted <- tryCatch(
      fpa_sync_post_budget_year(dirname(path), path, year, wrote$source_id %||% sid),
      error = function(e) list(ok = FALSE, status = "fail", revision = NA_integer_)
    )
    got <- tryCatch(
      fpa_shiny_sync(path, pull = list(status = "files", changed = TRUE, message = "")),
      error = function(e) list(pack = pack(), status = "run_fail", detail = conditionMessage(e))
    )
    if (identical(posted$status, "ok")) fpa_budget_stamp_revision(path, posted$revision)
    loaded <- tryCatch(fpa_shiny_load(path), error = function(e) NULL)
    if (!is.null(loaded) && isTRUE(loaded$ok)) pack(loaded) else if (!is.null(got$pack)) pack(got$pack)
    shiny::removeNotification("fpa-budget-year")
    note <- if (posted$status %in% c("local", "nolink")) {
      fpa_screen("budget_year_local")
    } else if (identical(posted$status, "ok")) {
      fpa_screen("budget_year_site_ok")
    } else if (identical(posted$status, "empty")) {
      fpa_screen("budget_year_kept_pc")
    } else {
      fpa_screen("budget_year_site_old")
    }
    shiny::showNotification(note, type = if (identical(posted$status, "ok") || posted$status %in% c("local", "nolink")) "message" else "warning", duration = 8)
    if (identical(got$status, "run_fail")) {
      shiny::showNotification(fpa_screen("sync_run_fail", got$detail %||% ""), type = "error", duration = 10)
    }
  }, ignoreInit = TRUE)

