      catchup_rev(catchup_rev() + 1L)
      note <- if (identical(sheet$layout, "yearcol")) "catchup_cells" else "catchup_done"
      shiny::showNotification(fpa_screen(note, saved$n), type = "message", duration = 8)
    } else if (isTRUE(saved$ok)) {
      shiny::showNotification(fpa_screen("catchup_none"), type = "warning", duration = 5)
    }
  }, ignoreInit = TRUE)

