  output$bridge_caption <- shiny::renderUI({
    cash <- cash_now()
    built <- fpa_shiny_bridge_build(
      cash, input$bridge_view, input$bridge_period, input$bridge_span, input$bridge_start, input$bridge_link, input$bridge_grain
    )
    note <- local({
      p <- pack()
      if (!isTRUE(p$ok)) return(NULL)
      cur <- tryCatch(fpa_manual_read(p$config), error = function(e) NULL)
      df <- if (is.null(cur)) NULL else fpa_manual_active(cur$data)
      if (is.null(df) || !nrow(df)) return(NULL)
      fin <- p$finance$cash
      last_p <- if (!is.null(fin) && nrow(fin)) as.character(fin$periode[[nrow(fin)]]) else ""
      last_c <- if (!is.null(fin) && nrow(fin)) suppressWarnings(as.numeric(fin$cash_close[[nrow(fin)]])) else NA_real_
      bits <- vapply(seq_len(nrow(df)), function(i) {
        sens <- if (identical(as.character(df$sens[[i]]), "in")) fpa_screen("out_in") else fpa_screen("out_out")
        pair <- manual_pair()
        other <- if (is.null(pair)) NA_real_ else if (isTRUE(manual_show())) pair$without else pair$with
        key <- if (isTRUE(manual_show())) "man_bridge_on" else "man_bridge_off"
        fpa_screen(
          key,
          as.character(df$libelle[[i]]),
          sens,
          fpa_shiny_eur(df$montant[[i]]),
          as.character(df$date_effet[[i]]),
          last_p,
          fpa_shiny_eur(last_c),
          fpa_shiny_eur(other)
        )
      }, character(1))
      shiny::tags$p(
        class = "fpa-man-note",
        style = "margin:0.15rem 0 0.45rem;color:#1f4e5f;font-size:13px;line-height:1.45;",
        paste(bits, collapse = " ")
      )
    })
    if (is.null(built)) return(shiny::tagList(shiny::tags$p(fpa_screen("loc_no_cash")), note))
    if (length(built$periods) == 1) {
      row <- fpa_shiny_bridge_row(cash, built$periods[[1]])
      return(shiny::tagList(
        shiny::tags$p(
          style = "margin:0.7rem 0 0.2rem;",
          shiny::tags$strong(row$periode),
          " · ouverture ", fpa_shiny_eur(row$cash_open),
          " · variation ", fpa_shiny_eur(row$delta_cash),
          fpa_screen("loc_close_chip"), fpa_shiny_eur(row$cash_close),
          fpa_screen("loc_bars_from_zero")
        ),
        note
      ))
    }
    tiers <- fpa_shiny_bridge_tiers(built)
    shape <- if (isTRUE(built$chain)) {
      fpa_screen("loc_bridge_open_close")
    } else {
      fpa_screen("loc_each_month_zero")
    }
    grain <- if (isTRUE(built$monthly)) fpa_screen("loc_bar_per_month_sp") else fpa_screen("loc_bar_per_line_sp")
    detail <- if (isTRUE(tiers$zoom)) fpa_screen("loc_hover_or_zoom") else ""
    shiny::tagList(
      shiny::tags$p(
        style = "margin:0.7rem 0 0.2rem;",
        shiny::tags$strong(paste(built$periods[[1]], "→", built$periods[[length(built$periods)]])),
        " · ", length(built$periods), " mois",
        " · ouverture ", fpa_shiny_eur(built$opening),
        fpa_screen("loc_close_chip"), fpa_shiny_eur(built$closing),
        ". ", shape, grain, detail
      ),
      note
    )
  })

  #' Step the window instead of dragging a scrollbar.
  bridge_shift <- function(dir) {
    cash <- pack()$finance$cash
    if (is.null(cash) || !nrow(cash)) return(invisible(NULL))
    pers <- as.character(cash$periode)
    n <- suppressWarnings(as.integer(input$bridge_view))
    if (!is.finite(n) || n < 1L) n <- if (identical(as.character(input$bridge_view), "all")) 12L else 6L
    i0 <- match(as.character(input$bridge_start %||% ""), pers)
    if (is.na(i0)) i0 <- max(1L, length(pers) - n + 1L)
    i1 <- min(max(1L, i0 + dir * n), max(1L, length(pers) - n + 1L))
    shiny::updateSelectInput(session, "bridge_start", selected = pers[[i1]])
  }
  shiny::observeEvent(input$bridge_prev, bridge_shift(-1L), ignoreInit = TRUE)
  shiny::observeEvent(input$bridge_next, bridge_shift(1L), ignoreInit = TRUE)

  #' A preset is the latest window of that length. The start date still moves it.
  shiny::observeEvent(input$bridge_view, {
    cash <- pack()$finance$cash
    if (is.null(cash) || !nrow(cash)) return()
    pers <- as.character(cash$periode)
    key <- as.character(input$bridge_view %||% "6")
    n <- suppressWarnings(as.integer(key))
    pick <- if (identical(key, "all") || !is.finite(n) || n < 1L) {
      pers[[1]]
    } else {
      pers[[max(1L, length(pers) - n + 1L)]]
    }
    shiny::updateSelectInput(session, "bridge_start", selected = pick)
  }, ignoreInit = TRUE)

