  })
  shiny::outputOptions(output, "series_ui", suspendWhenHidden = FALSE)

  synthese_brief <- function() {
    p <- pack()
    v <- pnl_view()
    pnl <- if (isTRUE(v$ready)) v$pnl else p$finance$pnl
    cash <- if (isTRUE(v$ready) && !is.null(v$cash)) v$cash else p$finance$cash
    fpa_synthese_brief(pnl, cash, p$finance$period_status, variance_view())
  }

  fpa_shiny_kpi_build <- function(p, v, variance) {
    pnl <- if (isTRUE(v$ready)) v$pnl else p$finance$pnl
    cash <- if (isTRUE(v$ready) && !is.null(v$cash)) v$cash else p$finance$cash
    status <- p$finance$period_status
    b <- fpa_synthese_brief(pnl, cash, status, variance)
    empty_card <- function(id, k) list(id = id, k = k, v = "", s = "", tone = "ok", rows = data.frame(), formulas = list())
    if (is.null(pnl) || !nrow(pnl) || !nrow(b$frame)) {
      return(list(cards = list(
        rev = empty_card("rev", fpa_screen("loc_rev_actual")),
        margin = empty_card("margin", "Marge d'exploitation"),
        peak = empty_card("peak", fpa_screen("loc_strongest_month")),
        cash = empty_card("cash", "Trésorerie")
      )))
    }
    frame <- b$frame
    actual <- frame$etat != "prévision"
    root <- p$config$paths$working_root_hint %||% dirname(p$config_path %||% "")
    rel <- function(path) {
      path <- gsub("\\\\", "/", as.character(path %||% ""))
      if (!nzchar(path) || identical(path, "NA")) return("")
      root_n <- sub("/+$", "", gsub("\\\\", "/", as.character(root)))
      prefix <- paste0(root_n, "/")
      if (nzchar(root_n) && startsWith(tolower(path), tolower(prefix))) {
        return(substring(path, nchar(prefix) + 1L))
      }
      hit <- regexpr("fpa-local-test/", path, ignore.case = TRUE)
      if (hit[[1]] > 0L) return(substring(path, hit[[1]] + nchar("fpa-local-test/")))
      basename(path)
    }
    work_pnl <- rel(file.path(root, "work", "pnl-monthly.csv"))
    work_cash <- rel(file.path(root, "work", "cash-bridge-monthly.csv"))
    src_pnl <- rel(p$config$paths$pnl_monthly %||% "")
    src_bs <- rel(p$config$paths$opening_bs %||% "")
    src_budget <- rel(p$config$paths$budget %||% "")
    long <- p$finance$pnl_long
    evidence <- function(per, line) {
      if (is.null(long) || !nrow(long) || !all(c("periode", "line_id", "evidence_label") %in% names(long))) return("")
      hit <- long[as.character(long$periode) == per & as.character(long$line_id) == line, , drop = FALSE]
      if (!nrow(hit)) return("")
      as.character(hit$evidence_label[[1]])
    }
    eur <- function(x) paste(fpa_shiny_eur(x), "EUR")
    term <- function(x) {
      x <- suppressWarnings(as.numeric(x))
      if (!length(x) || !is.finite(x[[1]])) return("n/a")
      if (x[[1]] < 0) paste0("− ", fpa_shiny_eur(abs(x[[1]]))) else fpa_shiny_eur(x[[1]])
    }
    join_sum <- function(xs) {
      xs <- suppressWarnings(as.numeric(xs))
      xs <- xs[is.finite(xs)]
      if (!length(xs)) return("n/a")
      out <- term(xs[[1]])
      if (length(xs) == 1L) return(out)
      for (x in xs[-1]) {
        out <- if (is.finite(x) && x < 0) paste(out, term(x)) else paste(out, "+", term(x))
      }
      out
    }
    formula <- function(eq, note, bits = NULL) list(eq = eq, note = note, bits = bits)
    add_bit <- function(x, lab, lead = FALSE) {
      num <- term(x)
      if (isTRUE(lead) && is.finite(suppressWarnings(as.numeric(x))) && as.numeric(x) >= 0) num <- paste0("+ ", num)
      list(num = num, lab = lab)
    }
    row <- function(item, amount, file, ligne, mois, sens) {
      data.frame(item = item, amount = amount, file = file, ligne = ligne, mois = mois, sens = sens, stringsAsFactors = FALSE)
    }
    line_rev <- fpa_line_fr("REV")
    line_oi <- fpa_line_fr("OI")
    hist <- tryCatch(fpa_line_history(p$config, p$paths), error = function(e) NULL)
    vol <- fpa_shiny_volumes(p$config, p$paths)
    map <- tryCatch(fpa_line_map(p$config, "pnl"), error = function(e) NULL)
    closed <- tryCatch(fpa_health_closed_month(status), error = function(e) "")
    focus <- unique(c(closed, if (nzchar(closed)) paste0(substr(closed, 1, 4), "-12") else character()))
    scan <- tryCatch(
      fpa_anomaly_scan(p$finance$bs, p$finance$pnl, p$finance$cash, vol, hist, map, focus),
      error = function(e) NULL
    )
    books_bad <- !is.null(scan) && any(scan$family == "books" & scan$level != "clear")
    rev_watch <- !is.null(scan) && any(scan$line_id == "REV" & scan$level != "clear")
    ratio_watch <- !is.null(scan) && any(scan$family == "ratio" & scan$level != "clear")
    sens_for <- function(per, line) {
      ev <- evidence(per, line)
      if (identical(ev, "imported_actual")) return(fpa_screen("kpi_sens_import"))
      if (identical(ev, "mechanical_rule")) return(fpa_screen("kpi_sens_rule"))
      fpa_screen("kpi_sens_book")
    }
    file_for <- function(per, line) {
      ev <- evidence(per, line)
      if (identical(ev, "imported_actual") && nzchar(src_pnl)) return(src_pnl)
      if (identical(line, "CASH")) return(work_cash)
      work_pnl
    }
    rev_detail <- if (any(actual)) {
      do.call(rbind, lapply(which(actual), function(i) {
        per <- as.character(frame$periode[[i]])
        row(per, eur(frame$REV[[i]]), file_for(per, "REV"), line_rev, per, sens_for(per, "REV"))
      }))
    } else {
      NULL
    }
    span_a <- if (any(actual)) paste(frame$periode[which(actual)[1]], frame$periode[max(which(actual))], sep = fpa_screen("loc_to_glue")) else ""
    fc_ix <- which(!actual)
    span_f <- if (length(fc_ix)) paste(frame$periode[fc_ix[1]], frame$periode[fc_ix[length(fc_ix)]], sep = fpa_screen("loc_to_glue")) else ""
    rev_rows <- rbind(
      row(fpa_screen("loc_total_actual"), eur(b$rev_actual), work_pnl, line_rev, span_a, fpa_screen("kpi_rev_total")),
      if (rev_watch) row(fpa_screen("loc_gap_already"), "", "", line_rev, span_a, fpa_screen("kpi_rev_watch")) else NULL,
      rev_detail,
      row(fpa_screen("loc_forecast_aside"), eur(b$rev_forecast), work_pnl, line_rev, span_f, fpa_screen("kpi_sens_rule"))
    )
    rev_tone <- if (books_bad || !is.finite(b$rev_actual)) "alert" else if (rev_watch) "watch" else "ok"
    last_i <- if (any(actual)) max(which(actual)) else NA_integer_
    last_m <- if (!is.na(last_i) && is.finite(frame$REV[[last_i]]) && abs(frame$REV[[last_i]]) > 0.5) {
      frame$OI[[last_i]] / frame$REV[[last_i]]
    } else NA_real_
    has_budget <- FALSE
    if (!is.null(variance) && nrow(variance) && nzchar(b$last_actual) && all(c("line_id", "periode", "budget") %in% names(variance))) {
      rev_b <- variance[as.character(variance$line_id) == "REV" & as.character(variance$periode) == b$last_actual, , drop = FALSE]
      oi_b <- variance[as.character(variance$line_id) == "OI" & as.character(variance$periode) == b$last_actual, , drop = FALSE]
      has_budget <- nrow(rev_b) && is.finite(suppressWarnings(as.numeric(rev_b$budget[[1]]))) &&
        abs(as.numeric(rev_b$budget[[1]])) > 0.5 && nrow(oi_b) && is.finite(suppressWarnings(as.numeric(oi_b$budget[[1]])))
    }
    margin_rows <- rbind(
      row("Cumul clos", if (is.finite(b$margin)) paste0(format(round(100 * b$margin, 1), nsmall = 1), " %") else "n/a", work_pnl, paste(line_oi, "/", line_rev), span_a, fpa_screen("kpi_margin_ytd")),
      row("Résultat d'exploitation", eur(b$oi_actual), work_pnl, line_oi, span_a, fpa_screen("kpi_sens_book")),
      row(fpa_screen("loc_last_closed"), if (is.finite(last_m)) paste0(format(round(100 * last_m, 1), nsmall = 1), " %") else "n/a", work_pnl, paste(line_oi, "/", line_rev), b$last_actual, fpa_screen("kpi_margin_last"))
    )
    if (!has_budget) {
      margin_rows <- rbind(margin_rows, row("Budget", "n/a", src_budget, line_oi, b$last_actual, fpa_screen("kpi_margin_nobud")))
    }
    margin_tone <- if (is.finite(b$oi_actual) && b$oi_actual < 0) "alert" else if (!has_budget) "watch" else "ok"
    peak_rows <- row(b$peak_month, eur(b$peak_rev), work_pnl, line_rev, b$peak_month, fpa_screen("kpi_peak"))
    peak_fc <- nzchar(b$peak_month) && b$peak_month %in% as.character(frame$periode[!actual])
    peak_tone <- if (!nzchar(b$peak_month) || !is.finite(b$peak_rev)) "alert" else if (peak_fc) "watch" else "ok"
    cash_picks <- fpa_cash_period_picks(cash, status)
    last_cash <- cash_picks$closed_month
    last_fc <- nzchar(last_cash) && last_cash %in% as.character(frame$periode[!actual])
    open_cash <- if (!is.null(cash) && nrow(cash) && "cash_open" %in% names(cash)) cash$cash_open[[1]] else NA_real_
    cash_rows <- rbind(
      row(fpa_screen("loc_balance_shown"), eur(b$cash_close), work_cash, "Trésorerie", last_cash, fpa_screen("kpi_cash_end")),
      row("Plus bas", eur(b$cash_low), work_cash, "Trésorerie", b$cash_low_month, fpa_screen("kpi_cash_low")),
      row("Ouverture", eur(open_cash), if (nzchar(src_bs)) src_bs else work_cash, "Trésorerie", if (nrow(cash)) as.character(cash$periode[[1]]) else "", fpa_screen("kpi_cash_open"))
    )
    if (b$cash_under > 0L) cash_rows <- rbind(cash_rows, row(fpa_screen("loc_months_under_zero"), as.character(b$cash_under), work_cash, "Trésorerie", "", fpa_screen("kpi_cash_neg")))
    if (ratio_watch) cash_rows <- rbind(cash_rows, row(fpa_screen("loc_liquidity"), "", work_cash, fpa_screen("loc_cash_over_st"), closed, fpa_screen("kpi_cash_ratio")))
    cash_tone <- if (b$cash_under > 0L || books_bad) "alert" else if (last_fc || ratio_watch) "watch" else "ok"
    tone_txt <- function(tone) fpa_screen(switch(tone, alert = "kpi_alert", watch = "kpi_watch", "kpi_ok"))
    pct <- function(x) if (is.finite(x)) paste0(format(round(100 * x, 1), nsmall = 1), " %") else "n/a"
    rev_bits <- function(total, idx, total_lab) {
      bits <- list(list(num = paste(term(total), "EUR"), lab = total_lab), "=")
      vals <- suppressWarnings(as.numeric(frame$REV[idx]))
      pers <- as.character(frame$periode[idx])
      for (i in seq_along(vals)) {
        bits[[length(bits) + 1L]] <- add_bit(vals[[i]], fpa_shiny_month_short(pers[[i]]), i > 1L)
      }
      bits
    }
    rev_formulas <- list(formula(
      paste0(term(b$rev_actual), " EUR = ", join_sum(frame$REV[actual])),
      fpa_screen("kpi_f_rev", line_rev, span_a),
      if (any(actual)) rev_bits(b$rev_actual, which(actual), "réalisé") else NULL
    ))
    if (length(fc_ix) && is.finite(b$rev_forecast)) {
      rev_formulas <- c(rev_formulas, list(formula(
        paste0(term(b$rev_forecast), " EUR = ", join_sum(frame$REV[fc_ix])),
        fpa_screen("kpi_f_fc", span_f),
        rev_bits(b$rev_forecast, fc_ix, "prévision")
      )))
    }
    margin_formulas <- list(formula(
      paste0(pct(b$margin), " = ", term(b$oi_actual), " / ", term(b$rev_actual)),
      fpa_screen("kpi_f_margin"),
      list(
        list(num = pct(b$margin), lab = "marge"),
        "=",
        list(num = term(b$oi_actual), lab = fpa_screen("loc_oi_lower")),
        "/",
        list(num = term(b$rev_actual), lab = "chiffre d'affaires")
      )
    ))
    if (!is.na(last_i)) {
      margin_formulas <- c(margin_formulas, list(formula(
        paste0(pct(last_m), " = ", term(frame$OI[[last_i]]), " / ", term(frame$REV[[last_i]])),
        fpa_screen("kpi_f_margin_last", b$last_actual)
      )))
    }
    if (!has_budget) {
      margin_formulas <- c(margin_formulas, list(formula(
        "n/a",
        fpa_screen("kpi_f_nobud", b$last_actual)
      )))
    }
    peak_formulas <- list(formula(
      paste0(b$peak_month, " = ", term(b$peak_rev), " EUR"),
      fpa_screen("kpi_f_peak")
    ))
    cash_formulas <- list()
    if (!is.null(cash) && nrow(cash) && all(c("cash_open", "cash_close", "NI", "D_A", "wc_impact") %in% names(cash))) {
      last <- cash[nrow(cash), , drop = FALSE]
      capex <- if ("capex" %in% names(last)) last$capex[[1]] else 0
      debt <- if ("debt_net" %in% names(last)) last$debt_net[[1]] else 0
      cash_formulas <- list(formula(
        paste0(
          term(last$cash_close), " = ",
          join_sum(c(last$cash_open, last$NI, last$D_A, last$wc_impact, capex, debt))
        ),
        fpa_screen("kpi_f_cash"),
        list(
          list(num = term(last$cash_close), lab = fpa_screen("loc_closing")),
          "=",
          list(num = term(last$cash_open), lab = "ouverture du mois"),
          add_bit(last$NI, "résultat net", TRUE),
          add_bit(last$D_A, "dotations", TRUE),
          add_bit(last$wc_impact, "effet de BFR", TRUE),
          add_bit(capex, "investissements", TRUE),
          add_bit(debt, "dette nette", TRUE)
        )
      ))
    }
    cash_formulas <- c(cash_formulas, list(
      formula(paste0(term(b$cash_low), " EUR (Plus bas)"), fpa_screen("kpi_f_min")),
      formula(paste0(term(open_cash), " EUR (Ouverture)"), fpa_screen("kpi_f_read"))
    ))
    margin_txt <- if (is.finite(b$margin)) paste0(format(round(100 * b$margin, 1), nsmall = 1), " %") else "n/a"
    margin_note <- fpa_synthese_margin_note(pnl, status, variance)
    list(cards = list(
      rev = list(
        id = "rev", k = fpa_screen("loc_rev_actual"), v = paste(fpa_shiny_eur(b$rev_actual), "EUR"),
        s = if (nzchar(b$last_actual)) paste0(fpa_screen("loc_until_sp"), b$last_actual, fpa_screen("loc_forecast_adds"), fpa_shiny_eur(b$rev_forecast), " EUR.") else "",
        chip = fpa_period_chip_label("actual", b$last_actual), tone = rev_tone, tone_txt = tone_txt(rev_tone), rows = rev_rows, formulas = rev_formulas
      ),
      margin = list(
        id = "margin", k = "Marge d'exploitation", v = margin_txt,
        s = if (nzchar(margin_note)) margin_note else paste0(fpa_screen("loc_oi_actual_sp"), fpa_shiny_eur(b$oi_actual), fpa_screen("loc_eur_closed_only")),
        chip = fpa_period_chip_label("actual", b$last_actual), tone = margin_tone, tone_txt = tone_txt(margin_tone), rows = margin_rows, formulas = margin_formulas
      ),
      peak = list(
        id = "peak", k = fpa_screen("loc_strongest_month"), v = b$peak_month,
        s = paste0(fpa_shiny_eur(b$peak_rev), fpa_screen("loc_eur_rev_actual")),
        chip = fpa_period_chip_label("actual", b$peak_month), tone = peak_tone, tone_txt = tone_txt(peak_tone), rows = peak_rows, formulas = peak_formulas
      ),
      cash = list(
        id = "cash", k = "Trésorerie", v = paste(fpa_shiny_eur(cash_picks$closed), "EUR"),
        s = paste0(
          "Plus bas ", cash_picks$low_month, fpa_screen("loc_to_glue"), fpa_shiny_eur(cash_picks$low), " EUR. ",
          if (!identical(cash_picks$year_end_month, cash_picks$closed_month)) {
            paste0(fpa_screen("loc_forecast_sp"), fpa_shiny_eur(cash_picks$year_end), " EUR.")
          } else if (cash_picks$under > 0L) {
            paste0(cash_picks$under, fpa_screen("loc_months_below_sp"))
          } else fpa_screen("loc_no_month_below")
        ),
        chip = fpa_period_chip_label("actual", cash_picks$closed_month), tone = cash_tone, tone_txt = tone_txt(cash_tone), rows = cash_rows, formulas = cash_formulas
      )
    ))
  }

  kpi_state <- shiny::reactive({
    fpa_shiny_kpi_build(pack(), pnl_view(), variance_view())
  })

  synthese_model <- shiny::reactive({
    p <- pack()
    if (!isTRUE(p$ok)) return(NULL)
    out_updated()
    v <- pnl_view()
    fin <- p$finance
    if (isTRUE(v$ready)) {
      fin$pnl <- v$pnl
      if (!is.null(v$cash)) fin$cash <- v$cash
    }
    saved <- tryCatch(fpa_outlook_read(p$config), error = function(e) NULL)
    floor <- tryCatch(fpa_cash_floor_read(p$config), error = function(e) 0)
    vol <- tryCatch(fpa_shiny_volumes(p$config, p$paths), error = function(e) NULL)
    fpa_synthese_model(
      p$config, fin, saved, floor, Sys.Date(),
      journal_entries = journal_entries(),
      volumes = vol
    )
  })

  output$kpi_row <- shiny::renderUI({
    p <- pack()
    m <- synthese_model()
    if (is.null(m) || !isTRUE(m$ok)) {
      return(shiny::tags$p(fpa_screen("loc_no_monthly_pnl")))
    }
    L <- m$land
    eur <- function(x) fpa_shiny_eur(x)
    pct1 <- function(x) if (is.finite(x)) paste0(format(round(100 * x, 1), nsmall = 1), " %") else "n/a"
    signed <- function(x) {
      if (!is.finite(x)) return("—")
      paste0(if (x > 0.5) "+" else if (x < -0.5) "−" else "", eur(abs(x)))
    }
    tone_of <- function(sev, trust_code) {
      if (identical(trust_code, "limited") || identical(trust_code, "blocked")) return("watch")
      if (identical(sev, "alert")) return("alert")
      if (identical(sev, "watch")) return("watch")
      "hold"
    }
    find <- m$finding
    out <- m$outlook
    go_periode <- as.character(
      find$action_periode %||% L$cash_year_end_month %||% m$context$closed_through %||% ""
    )
    go_find <- sprintf(
      "Shiny.setInputValue('fpa_go',{tab:%s,line:%s,open:%s,periode:%s},{priority:'event'})",
      jsonlite::toJSON(find$action_tab %||% "Trésorerie", auto_unbox = TRUE),
      jsonlite::toJSON(find$action_line %||% "", auto_unbox = TRUE),
      jsonlite::toJSON(find$action_open %||% "", auto_unbox = TRUE),
      jsonlite::toJSON(go_periode, auto_unbox = TRUE)
    )
    bud_line <- if (isTRUE(L$bud_covers) && is.finite(L$bud_rev)) {
      fpa_screen("synth_card_bud_vs", eur(L$bud_rev), signed(L$rev_y - L$bud_rev))
    } else if (isTRUE(L$bud_partial)) {
      fpa_screen("synth_card_bud_partial")
    } else {
      fpa_screen("synth_card_bud_miss")
    }
    w <- if (is.finite(L$booked_pct) && L$rev_y > 0) max(0, min(100, L$booked_pct)) else NA_real_
    meter <- if (!is.finite(w)) NULL else shiny::tags$div(
      class = "fpa-kpi-meter",
      shiny::tags$span(class = "booked", style = sprintf("width:%.1f%%;", w)),
      shiny::tags$span(class = "open", style = sprintf("width:%.1f%%;", 100 - w))
    )
    face <- function(id, tone, kicker, value, body, tab, line = "", periode = "") {
      go <- sprintf(
        "Shiny.setInputValue('fpa_go',{tab:%s,line:%s,open:'',periode:%s},{priority:'event'});",
        jsonlite::toJSON(tab %||% "", auto_unbox = TRUE),
        jsonlite::toJSON(line %||% "", auto_unbox = TRUE),
        jsonlite::toJSON(periode %||% "", auto_unbox = TRUE)
      )
      shiny::tags$button(
        type = "button",
        class = paste("fpa-kpi-card", paste0("is-", tone)),
        onclick = paste0(
          go,
          sprintf("Shiny.setInputValue('kpi_open','%s',{priority:'event'});", id)
        ),
        shiny::div(class = "k", kicker),
        shiny::div(class = "v", value),
        body
      )
    }
    rev_tone <- tone_of(if (isTRUE(L$bud_partial)) "watch" else "ok", m$trust$rev)
    oi_tone <- tone_of(if (is.finite(L$oi_f) && L$oi_f < 0 && abs(L$oi_f) > 1000) "watch" else "ok", m$trust$oi)
    cash_tone <- tone_of(
      if (is.finite(L$cash_year_end) && L$cash_year_end < (m$cash_floor %||% 0)) "alert" else "ok",
      m$trust$cash
    )
    out_tone <- switch(
      out$state %||% "need_balance",
      need_balance = "watch", balance_only = "watch", stale_horizon = "watch",
      partial = if (is.finite(out$low) && out$low < 0) "alert" else "hold",
      "hold"
    )
    out_date <- if (nzchar(out$as_of %||% "")) format(fpa_outlook_date(out$as_of), "%d/%m/%Y") else ""
    out_tag <- if (isTRUE(out$planned)) {
      fpa_screen("synth_out_planned")
    } else if (identical(out$state, "partial")) {
      fpa_screen("synth_out_partial_tag")
    } else {
      ""
    }
    out_v <- if (identical(out$state, "need_balance")) {
      fpa_screen("synth_out_need")
    } else if (nzchar(out_tag)) {
      paste0(eur(out$opening), " EUR · ", out_tag)
    } else {
      paste(eur(out$opening), "EUR")
    }
    out_s <- switch(
      out$state %||% "need_balance",
      need_balance = fpa_screen("synth_out_need_s"),
      balance_only = if (isTRUE(out$planned)) {
        fpa_screen("out_asof_planned", out_date)
      } else {
        fpa_screen("synth_find_bal_only_b", eur(out$opening), out_date)
      },
      stale_horizon = fpa_screen("synth_out_stale", out_date),
      partial = fpa_screen(
        "synth_out_complete", eur(out$low),
        format(fpa_outlook_date(out$low_date), "%d/%m/%Y")
      ),
      fpa_screen("kpi_out_click")
    )
    shiny::tagList(
      shiny::tags$style(HTML("
        .fpa-synth-ctx { margin:0 0 10px; color:#3d4c54; font-size:15px; line-height:1.45; }
        .fpa-synth-ctx strong { color:#0f2f3a; font-size:15.5px; }
        .fpa-synth-find {
          margin:0 0 12px; padding:12px 14px; border:1px solid #d6e1e5; border-left:6px solid #1f4e5f;
          border-radius:10px; background:#f4f8f9;
        }
        .fpa-synth-find.is-watch { border-left-color:#c47b2b; background:#fdf6ea; }
        .fpa-synth-find.is-alert { border-left-color:#8c3a3a; background:#f8ecec; }
        .fpa-synth-find h3 { margin:0 0 4px; font-size:15px; color:#0f2f3a; }
        .fpa-synth-find p { margin:0 0 8px; color:#1a2b32; font-size:13.5px; line-height:1.45; }
        .fpa-synth-find .fpa-synth-floor, .fpa-synth-find .fpa-synth-wc {
          margin:0 0 8px; color:#5c6b73; font-size:12.5px; line-height:1.4;
        }
        .fpa-synth-horizon { margin:6px 0 10px; }
        .fpa-synth-horizon .shiny-options-group { display:flex; flex-wrap:wrap; gap:8px 18px; }
        .fpa-synth-horizon .shiny-options-group label { margin:0 !important; font-weight:600; color:#1f4e5f; }
        .fpa-synth-kpi { display:flex; flex-wrap:wrap; gap:10px; margin:0.2rem 0 0.8rem; }
        .fpa-synth-kpi button.fpa-kpi-card {
          flex:1 1 220px; border-radius:10px; padding:10px 12px; text-align:left;
          font:inherit; cursor:pointer; border:1px solid #d6e1e5; background:#f4f8f8;
        }
        .fpa-synth-kpi button.fpa-kpi-card.is-hold { border-color:#d6e1e5; background:#f4f8f8; }
        .fpa-synth-kpi button.fpa-kpi-card.is-watch { border-color:#e0cba8; background:#fdf6ea; }
        .fpa-synth-kpi button.fpa-kpi-card.is-alert { border-color:#e0c4c4; background:#f8ecec; }
        .fpa-synth-kpi button.fpa-kpi-card:hover, .fpa-synth-kpi button.fpa-kpi-card:focus {
          outline:2px solid #1f4e5f; outline-offset:2px;
        }
        .fpa-synth-kpi .k { font-size:11px; letter-spacing:0.02em; text-transform:uppercase; color:#5c6b73; }
        .fpa-synth-kpi .v { font-size:22px; font-weight:700; color:#1f4e5f; font-variant-numeric:tabular-nums; }
        .fpa-synth-kpi .is-alert .v { color:#8c3a3a; }
        .fpa-synth-kpi .against { font-size:13px; font-weight:650; color:#0f2f3a; line-height:1.35; margin-top:6px; }
        .fpa-synth-kpi .s { font-size:12.5px; color:#3d4c54; line-height:1.35; margin-top:4px; }
        .fpa-kpi-meter { display:flex; height:10px; border-radius:5px; overflow:hidden; border:1px solid #1f4e5f; margin:8px 0 4px; }
        .fpa-kpi-meter .booked { background:#1f4e5f; height:100%; }
        .fpa-kpi-meter .open { height:100%; background:repeating-linear-gradient(-45deg,#d5e2e6,#d5e2e6 2px,#fff 2px,#fff 5px); }
        .fpa-trust-chip {
          display:inline-block; margin-left:8px; padding:2px 8px; border-radius:8px;
          border:1px solid #e0cba8; background:#fdf6ea; color:#5a4420; font-size:11px; font-weight:700;
        }
        .fpa-synth-sec { margin:14px 0 8px; }
        .fpa-synth-sec h3 { margin:0 0 8px; font-size:15px; color:#0f2f3a; }
        .fpa-synth-bridge { width:100%; border-collapse:collapse; font-size:13px; }
        .fpa-synth-bridge th { background:#1f4e5f; color:#fff; text-align:left; padding:6px 8px; }
        .fpa-synth-bridge td { padding:6px 8px; border-bottom:1px solid #e6edef; }
        .fpa-synth-bridge td.num { text-align:right; font-variant-numeric:tabular-nums; }
        .fpa-synth-bridge tr:nth-child(even) td { background:#f6f9fa; }
      ")),
      shiny::tags$p(
        class = "fpa-synth-ctx",
        shiny::tags$strong(m$context$company %||% ""),
        " · ", m$context$currency %||% "EUR",
        " · ", fpa_screen("kpi_land_lead"),
        if (nzchar(m$context$closed_through %||% "")) paste0(fpa_screen("loc_actual_until"), fpa_ym_fr(m$context$closed_through)),
        if (any(m$trust$cash == "limited", m$trust$oi == "limited", m$trust$rev == "limited")) {
          shiny::tags$span(class = "fpa-trust-chip", fpa_screen("synth_trust_limited"))
        }
      ),
      shiny::tags$div(
        class = paste("fpa-synth-find", paste0("is-", find$severity %||% "ok")),
        shiny::tags$h3(find$title),
        shiny::tags$p(find$body),
        shiny::tags$p(class = "fpa-synth-floor", fpa_screen("synth_floor_note", eur(m$cash_floor %||% 0))),
        if (!is.null(m$wc_open) && nzchar(m$wc_open$sentence %||% "")) {
          shiny::tags$p(class = "fpa-synth-wc", m$wc_open$sentence)
        },
        shiny::tags$button(
          type = "button", class = "fpa-map-btn fpa-map-btn-primary",
          onclick = go_find,
          find$action_label
        )
      ),
      shiny::div(
        class = "fpa-synth-kpi",
        face("rev", rev_tone, fpa_screen("synth_card_rev"), paste(eur(L$rev_y), "EUR"), shiny::tagList(
          meter,
          shiny::div(class = "s", fpa_screen("kpi_land_split", eur(L$rev_a), eur(L$rev_f))),
          if (is.finite(L$booked_pct)) shiny::div(class = "against", fpa_screen("synth_card_booked", format(round(L$booked_pct)), eur(L$rev_f))),
          shiny::div(class = "s", bud_line),
          if (is.finite(m$hotel$revpar %||% NA_real_)) {
            shiny::div(class = "s", fpa_screen("synth_hotel_revpar", eur(m$hotel$revpar)))
          },
          shiny::div(class = "s", paste(fpa_synth_origin("actual"), "·", fpa_synth_origin("forecast")))
        ), "Compte de résultat", "REV", m$context$closed_through %||% ""),
        face("margin", oi_tone, fpa_screen("synth_card_oi"), paste(eur(L$oi_y), "EUR"), shiny::tagList(
          shiny::div(class = "against", fpa_screen(
            "synth_card_oi_open",
            if (is.finite(L$oi_f) && L$oi_f < 0) paste0("−", eur(abs(L$oi_f))) else eur(L$oi_f),
            pct1(L$margin_y)
          )),
          shiny::div(class = "s", fpa_screen("kpi_land_margin", pct1(L$margin_a), pct1(L$margin_y))),
          if (is.finite(m$hotel$payroll_pct %||% NA_real_)) {
            shiny::div(class = "s", fpa_screen("synth_hotel_payroll", pct1(m$hotel$payroll_pct)))
          },
          if (isTRUE(L$bud_oi_covers) && is.finite(L$bud_oi)) {
            shiny::div(class = "s", fpa_screen("synth_card_bud_vs", eur(L$bud_oi), signed(L$oi_y - L$bud_oi)))
          }
        ), "Scénarios", "OI", m$context$closed_through %||% ""),
        face("cash", cash_tone, fpa_screen("synth_card_cash"), paste(eur(L$cash_year_end), "EUR"), shiny::tagList(
          if (nzchar(L$cash_year_end_month %||% "")) {
            shiny::tags$div(class = "fpa-period-chip", paste(fpa_synth_origin("rebuilt"), "→", fpa_synth_origin("forecast"), "·", fpa_ym_fr(L$cash_year_end_month)))
          },
          shiny::div(class = "against", fpa_screen("synth_card_cash_closed", eur(L$cash_close))),
          shiny::div(class = "s", fpa_screen(
            "synth_card_cash_basis",
            fpa_ym_fr(L$cash_year_end_month),
            eur(m$cash_floor %||% 0)
          ))
        ), "Trésorerie", "", L$cash_year_end_month %||% ""),
        shiny::tags$button(
          type = "button",
          class = paste("fpa-kpi-card", paste0("is-", out_tone)),
          onclick = "Shiny.setInputValue('kpi_open','out',{priority:'event'})",
          shiny::div(class = "k", fpa_screen("synth_out_panel_k")),
          shiny::div(class = "v", out_v),
          shiny::div(class = "against", out_s),
          shiny::div(class = "s", fpa_screen("kpi_out_click"))
        )
      )
    )
  })

