  shiny::observeEvent(input$synth_cash_yscale_btn, {
    nxt <- if (identical(synth_cash_yscale(), "fit")) "zero" else "fit"
    synth_cash_yscale(nxt)
    shiny::updateActionButton(
      session, "synth_cash_yscale_btn",
