  output$synth_horizon_ui <- shiny::renderUI({
    p <- pack()
    if (!isTRUE(p$ok)) return(NULL)
    n <- tryCatch(fpa_horizon_months_read(p$config), error = function(e) 18L)
    cash <- p$finance$cash
    fy_end <- suppressWarnings(as.integer((p$config$company %||% list())$fiscal_year_end_month %||% 12L))
    fy_marks <- if (!is.null(cash) && nrow(cash)) fpa_fy_mark_dates(cash$periode, fy_end) else NULL
    win_id <- as.character(input$synth_cash_window %||% "fy")
    prior_empty <- FALSE
    if (identical(win_id, "prior") && !is.null(cash) && nrow(cash)) {
      model <- synthese_model()
      fy_m <- if (is.null(model)) character() else as.character(model$context$fy_months %||% character())
      prior <- fpa_fy_window(fy_m, "prior")
      prior_empty <- length(prior$months) > 0L && !any(as.character(cash$periode) %in% prior$months)
    }
    first_year <- if (!is.null(cash) && nrow(cash)) substr(as.character(cash$periode[[1]]), 1, 4) else ""
    shiny::tags$div(
      class = "fpa-synth-horizon",
      shiny::radioButtons(
        "synth_horizon_months",
        fpa_screen("synth_horizon_label"),
        choices = stats::setNames(c("12", "18", "24"), c("12 mois", "18 mois", "24 mois")),
        selected = as.character(n),
        inline = TRUE
      ),
      shiny::tags$p(class = "fpa-bs-cmp-note", fpa_screen("synth_horizon_caption")),
      if (!is.null(fy_marks) && nrow(fy_marks)) shiny::tags$p(class = "fpa-bs-cmp-note", fpa_screen("synth_fy_mark")),
      if (isTRUE(prior_empty) && nzchar(first_year)) shiny::tags$p(class = "fpa-bs-cmp-note", fpa_screen("synth_cash_window_empty", first_year))
    )
  })

  shiny::observeEvent(input$synth_horizon_months, {
    p <- pack()
    if (!isTRUE(p$ok)) return()
    want <- suppressWarnings(as.integer(input$synth_horizon_months %||% 18L))
    if (!is.finite(want) || !(want %in% c(12L, 18L, 24L))) return()
    have <- tryCatch(fpa_horizon_months_read(p$config), error = function(e) 18L)
    if (identical(as.integer(have), as.integer(want))) return()
    fpa_horizon_months_write(p$config, want)
    path <- p$config_path %||% ""
    if (!nzchar(path)) return()
    res <- tryCatch(
      fpa_run(path, write = TRUE, stop_on_error = FALSE, horizon_months = want),
      error = function(e) e
    )
    if (inherits(res, "error")) return()
    pack(fpa_shiny_load(path))
    manual_books(NULL)
  }, ignoreInit = TRUE)

