  fpa_shiny_extra_spec <- function(p, id) {
    eur <- function(x) if (is.finite(x)) paste(fpa_shiny_eur(x), "EUR") else "—"
    row <- function(item, amount, file, ligne, mois, sens) {
      data.frame(item = item, amount = amount, file = file, ligne = ligne, mois = mois, sens = sens, stringsAsFactors = FALSE)
    }
    info <- fpa_shiny_obj_info(p)
    if (identical(id, "obj")) {
      cash <- tryCatch(fpa_objectif_read(p$finance, "cash_ye", info$close), error = function(e) NA_real_)
      oi <- tryCatch(fpa_objectif_read(p$finance, "oi_fy", info$close), error = function(e) NA_real_)
      return(list(
        id = "obj", k = fpa_screen("synth_obj_k"),
        v = paste0(eur(cash), " · ", eur(oi)),
        s = fpa_screen("synth_obj_s", fpa_ym_fr(info$measured)),
        tone_txt = fpa_screen("synth_obj_s", fpa_ym_fr(info$measured)),
        formulas = list(),
        go_tab = "Impact", go_line = "", go_open = "obj",
        rows = rbind(
          row(fpa_screen("obj_metric_cash"), eur(cash), "work/cash-bridge-monthly.csv", fpa_screen("health_lab_cash"), info$close %||% "", fpa_screen("kpi_obj_cash")),
          row(fpa_screen("obj_metric_oi_fy"), eur(oi), "work/pnl-monthly.csv", fpa_line_fr("OI"), info$close %||% "", fpa_screen("kpi_obj_oi"))
        )
      ))
    }
    saved <- tryCatch(fpa_outlook_read(p$config), error = function(e) NULL)
    roll <- if (is.null(saved)) NULL else fpa_outlook_roll(saved$opening, saved$items, saved$as_of, FALSE)
    need <- is.null(roll) || identical(roll$reason, "need_balance")
    moves <- if (is.null(saved)) list() else saved$items
    move_rows <- if (!length(moves)) {
      NULL
    } else {
      do.call(rbind, lapply(moves, function(it) {
        signed <- if (identical(it$kind, "out")) -it$amount else it$amount
        row(it$label, eur(signed), "cash-outlook.json", if (identical(it$kind, "out")) fpa_screen("out_out") else fpa_screen("out_in"), it$date, fpa_screen("kpi_out_move"))
      }))
    }
    low <- if (need || is.null(roll)) NA_real_ else roll$low
    low_when <- if (need || is.null(roll) || !is.finite(roll$low_date)) "" else format(fpa_outlook_date(roll$low_date), "%Y-%m-%d")
    list(
      id = "out", k = fpa_screen("synth_out_k"),
      v = if (need) fpa_screen("synth_out_need") else eur(low),
      s = if (need) fpa_screen("synth_out_need_s") else fpa_screen("synth_out_low", format(fpa_outlook_date(roll$low_date), "%d/%m/%Y")),
      tone_txt = if (need) fpa_screen("synth_out_need_s") else fpa_screen("synth_out_low", format(fpa_outlook_date(roll$low_date), "%d/%m/%Y")),
      formulas = list(),
      go_tab = "Trésorerie", go_line = "", go_open = "out",
      rows = rbind(
        row(fpa_screen("out_balance_k"), if (is.null(saved)) "—" else eur(saved$opening), "cash-outlook.json", fpa_screen("out_balance_k"), if (is.null(saved)) "" else saved$as_of, fpa_screen("kpi_out_open")),
        row(fpa_screen("synth_out_k"), if (need) "—" else eur(low), "cash-outlook.json", fpa_screen("synth_out_k"), low_when, fpa_screen("kpi_out_low")),
        move_rows
      )
    )
  }

  shiny::observeEvent(input$kpi_open, {
    id <- as.character(input$kpi_open %||% "")
    if (identical(id, "out")) {
      bslib::nav_select("main_nav", selected = "Trésorerie", session = session)
      session$sendCustomMessage("fpa-open-details", list(sel = "#fpa-out-fold"))
      return()
    }
    p <- pack()
    spec <- if (id %in% c("obj", "out") && isTRUE(p$ok)) {
      fpa_shiny_extra_spec(p, id)
    } else {
      kpi_state()$cards[[id]]
    }
    if (is.null(spec)) return()
    if (is.null(spec$go_tab)) {
      spec$go_tab <- "Impact"
      spec$go_line <- switch(spec$id, rev = "REV", margin = "OI", peak = "REV", "")
      spec$go_open <- ""
    }
    shiny::showModal(fpa_shiny_trace_modal(spec))
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$kpi_reopen, {
    id <- as.character(input$kpi_reopen$id %||% "")
    if (!nzchar(id)) return()
    p <- pack()
    spec <- if (id %in% c("obj", "out") && isTRUE(p$ok)) fpa_shiny_extra_spec(p, id) else kpi_state()$cards[[id]]
    if (is.null(spec)) return()
    if (is.null(spec$go_tab)) {
      spec$go_tab <- "Impact"
      spec$go_line <- switch(id, rev = "REV", margin = "OI", peak = "REV", "")
      spec$go_open <- ""
    }
    shiny::showModal(fpa_shiny_trace_modal(spec))
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$kpi_file, {
    rel <- as.character(input$kpi_file$file %||% "")
    back <- as.character(input$kpi_file$back %||% "")
    p <- pack()
    if (!isTRUE(p$ok) || !nzchar(rel)) return()
    path <- fpa_shiny_listed_path(p, rel)
    title <- basename(rel)
    if (!nzchar(path) || !file.exists(path)) {
      shiny::showModal(fpa_shiny_file_view_modal(title, fpa_screen("kpi_file_missing"), NULL, back))
      return()
    }
    ext <- tolower(tools::file_ext(path))
    if (identical(ext, "csv") && fpa_shiny_under_input(p, path)) {
      sheet <- fpa_file_edit_sheet(p$config, basename(path), p$paths)
      if (isTRUE(sheet$ok) && isTRUE(sheet$csv)) {
        fe_sheet(sheet)
        fe_kpi(back)
        fe_back("")
        shiny::showModal(fpa_shiny_file_edit_modal(sheet, "", "", "pnl", "", back))
        return()
      }
    }
    if (identical(ext, "json")) {
      saved <- tryCatch(fpa_outlook_read(p$config), error = function(e) NULL)
      df <- data.frame(Libelle = character(), Date = character(), Montant = character(), stringsAsFactors = FALSE)
      if (!is.null(saved)) {
        df <- rbind(df, data.frame(Libelle = fpa_screen("out_balance_k"), Date = saved$as_of, Montant = if (is.finite(saved$opening)) fpa_shiny_eur(saved$opening) else "", stringsAsFactors = FALSE))
        for (it in saved$items) {
          signed <- if (identical(it$kind, "out")) -it$amount else it$amount
          df <- rbind(df, data.frame(Libelle = it$label, Date = it$date, Montant = fpa_shiny_eur(signed), stringsAsFactors = FALSE))
        }
      }
      shiny::showModal(fpa_shiny_file_view_modal(title, fpa_screen("kpi_file_json"), fpa_shiny_preview_table(df), back))
      return()
    }
