    chart_month_pills <- function(id, periods, labels, forecast, selected, kind = c("check", "radio")) {
      kind <- match.arg(kind)
      periods <- as.character(periods)
      labels <- as.character(labels)
      forecast <- if (is.null(forecast) || length(forecast) != length(periods)) rep(FALSE, length(periods)) else as.logical(forecast)
      selected <- as.character(selected)
      pill <- function(per, lab, on) {
        box <- if (identical(kind, "check")) {
          shiny::tags$input(type = "checkbox", name = id, value = per, checked = if (isTRUE(on)) "checked" else NULL)
        } else {
          shiny::tags$input(type = "radio", name = id, value = per, checked = if (isTRUE(on)) "checked" else NULL)
        }
        shiny::tags$label(class = if (identical(kind, "check")) "checkbox-inline" else "radio-inline", box, shiny::tags$span(lab))
      }
      cluster <- function(idx, caption) {
        if (!length(idx)) return(NULL)
        pills <- lapply(idx, function(i) pill(periods[[i]], labels[[i]], periods[[i]] %in% selected))
        if (!is.null(caption)) pills <- c(list(shiny::tags$span(class = "fpa-chartx-split-h", caption)), pills)
        shiny::tags$div(class = "fpa-chartx-cluster", pills)
      }
      split <- any(forecast)
      kids <- list(cluster(which(!forecast), if (split) fpa_screen("chart_st_hist") else NULL))
      if (split) kids[[length(kids) + 1L]] <- cluster(which(forecast), fpa_screen("chart_st_fc"))
      shiny::tags$div(
        id = id,
        class = paste(
          "form-group shiny-input-container",
          if (identical(kind, "check")) "shiny-input-checkboxgroup" else "shiny-input-radiogroup",
          if (split) "fpa-chartx-has-split" else ""
        ),
        role = if (identical(kind, "radio")) "radiogroup" else NULL,
        shiny::tags$div(class = paste("shiny-options-group", if (split) "fpa-chartx-months-split" else ""), kids)
      )
    }
    output$chart_math_nav <- shiny::renderUI({
