    output$chart_math_eq <- shiny::renderUI({
      fpa_lang_current()
      math <- chart_math_bundle(input$chart_math_period)
      if (is.null(math) || !length(math$eqs)) return(NULL)
      para <- function(i, eqs, pieces, gloss) {
        line <- if (is.null(pieces)) {
          shiny::tags$p(eqs[[i]])
        } else {
          bits <- lapply(pieces[[i]], function(piece) {
            if (isTRUE(piece$hot)) shiny::tags$span(class = "fpa-chartx-hot", style = piece$style, piece$text) else piece$text
          })
          shiny::tags$p(bits)
        }
        note <- if (length(gloss) >= i && nzchar(gloss[[i]])) shiny::tags$p(class = "fpa-chartx-gloss", gloss[[i]]) else NULL
        shiny::tags$div(class = "fpa-chartx-eq-line", line, note)
      }
      eq_nodes <- function(eqs, pieces = NULL, gloss = character()) {
        n <- length(eqs)
        groups <- if (identical(math$which, "cloud") && n >= 2L && n %% 2L == 0L) {
          lapply(seq_len(n / 2L), function(i) c(i * 2L - 1L, i * 2L))
        } else {
          list(seq_len(n))
        }
        if (length(groups) <= 1L) {
          lapply(groups[[1]], function(i) para(i, eqs, pieces, gloss))
        } else {
          lapply(groups, function(g) {
            shiny::tags$div(class = "fpa-chartx-eq-pair", lapply(g, function(i) para(i, eqs, pieces, gloss)))
          })
        }
      }
      block <- function(eqs, when, pieces = NULL, gloss = character()) {
        kids <- eq_nodes(eqs, pieces, gloss)
        if (!is.null(when)) kids <- c(list(shiny::tags$p(class = "fpa-chartx-eq-when", when)), kids)
        shiny::tags$div(class = "fpa-chartx-eq", kids)
      }
      src_foot <- function() {
        refs <- fpa_chart_source_refs(pack()$config, math$which)
        if (!length(refs)) return(NULL)
        bits <- list(shiny::tags$span(fpa_screen("chart_src_h")))
        for (s in refs) {
          safe <- gsub("[^A-Za-z0-9_-]", "", s$id)
          if (!nzchar(safe)) next
          bits[[length(bits) + 1L]] <- shiny::tags$button(
            type = "button",
            class = "fpa-file-link",
            onclick = sprintf("Shiny.setInputValue('raw_file','src:%s',{priority:'event'})", safe),
            s$name
          )
        }
        shiny::tags$p(class = "fpa-chartx-src", bits)
      }
      label_of <- function(picked, periods, labels) {
        i <- match(fpa_chart_math_pick(periods, picked), periods)
        if (is.na(i)) "" else labels[[i]]
      }
      if (!isTRUE(input$chart_math_compare)) {
        return(shiny::tags$div(block(math$eqs, NULL, NULL, math$gloss), src_foot()))
      }
      per_b <- input$chart_math_period_b
      if (is.null(per_b) || !nzchar(as.character(per_b))) per_b <- math$periods[[length(math$periods)]]
      other <- chart_math_bundle(per_b)
      if (is.null(other) || !length(other$eqs)) {
        return(shiny::tags$div(block(math$eqs, NULL, NULL, math$gloss), src_foot()))
      }
      marked <- fpa_chart_eq_marks(math$eqs, other$eqs)
      shiny::tags$div(
        shiny::tags$div(
          class = "fpa-chartx-eqs",
          block(math$eqs, label_of(input$chart_math_period, math$periods, math$labels), marked$left, math$gloss),
          block(other$eqs, label_of(per_b, other$periods, other$labels), marked$right, other$gloss)
        ),
        src_foot()
      )
    })
    be_show <- shiny::reactiveVal(NULL)
    be_periods <- shiny::reactive({
