    output$plot_trend <- plotly::renderPlotly({
      p <- pack()
      v <- pnl_view()
      m <- synthese_model()
      pnl_show <- if (isTRUE(v$ready)) v$pnl else p$finance$pnl
      frame <- if (!is.null(m) && !is.null(m$frame) && nrow(m$frame)) m$frame else fpa_synthese_frame(pnl_show, p$finance$period_status, variance_view())
      if (!nrow(frame)) return(plotly::plotly_empty())
      fy <- m$context$fy_months %||% character()
      if (length(fy)) frame <- frame[frame$periode %in% fy, , drop = FALSE]
      if (!nrow(frame)) return(plotly::plotly_empty())
      hover <- paste0(
        frame$periode, " · ", frame$etat, "<br>",
        fpa_screen("loc_oi_sp"), fpa_synthese_eur(frame$OI), " EUR"
      )
      act <- frame$etat == "réalisé"
      fc <- frame$etat == "prévision"
      chart <- plotly::plot_ly()
      ribbon <- if (isTRUE(v$ready)) {
        fpa_shiny_oi_ribbon(v$low, v$high, frame)
      } else {
        NULL
      }
      if (!is.null(ribbon) && nrow(ribbon) > 1L) {
        chart <- plotly::add_ribbons(
          chart, data = ribbon, x = ~periode, ymin = ~ymin, ymax = ~ymax,
          name = fpa_screen("synth_band_shocks"),
          line = list(width = 0),
          fillcolor = "rgba(196,123,43,0.22)",
          hoverinfo = "skip"
        )
      }
      cols <- ifelse(frame$OI >= 0, "#1f4e5f", "#8c3a3a")
      if (any(act)) {
        chart <- plotly::add_trace(
          chart, data = frame[act, , drop = FALSE], x = ~periode, y = ~OI,
          type = "bar", name = fpa_synth_origin("actual"),
          marker = list(color = cols[act]),
          hovertext = hover[act], hoverinfo = "text"
        )
      }
      if (any(fc)) {
        chart <- plotly::add_trace(
          chart, data = frame[fc, , drop = FALSE], x = ~periode, y = ~OI,
          type = "bar", name = fpa_synth_origin("forecast"),
          marker = list(color = cols[fc], pattern = list(shape = "/")),
          hovertext = hover[fc], hoverinfo = "text"
        )
        bridge_i <- if (any(act)) c(max(which(act)), which(fc)) else which(fc)
        chart <- plotly::add_trace(
          chart,
          x = frame$periode[bridge_i], y = frame$OI[bridge_i],
          type = "scatter", mode = "lines",
          name = fpa_synth_origin("forecast"),
          showlegend = FALSE,
          line = list(color = "#0f2f3a", width = 2.2, dash = "dot"),
          hoverinfo = "skip"
        )
      }
      shapes <- list(list(
        type = "line", x0 = -0.5, x1 = nrow(frame) - 0.5, y0 = 0, y1 = 0,
        line = list(color = "#0f2f3a", width = 1)
      ))
      if (any(fc) && any(act)) {
        xcut <- frame$periode[which(fc)[1]]
        shapes <- c(shapes, list(list(
          type = "line", x0 = xcut, x1 = xcut, y0 = 0, y1 = 1, yref = "paper",
          line = list(color = "#8a5a00", width = 1, dash = "dot")
        )))
      }
      chart <- plotly::layout(
        chart,
        barmode = "relative",
        hovermode = "x",
        shapes = shapes,
        yaxis = list(title = "EUR / mois", gridcolor = "#e6edef", tickformat = ",d", zeroline = TRUE),
        xaxis = list(title = "", tickangle = -45, type = "category", automargin = TRUE),
        legend = list(
          orientation = "h", x = 0, y = 1.14, xanchor = "left", yanchor = "bottom",
          bgcolor = "rgba(255,255,255,0.92)", borderwidth = 0, font = list(size = 13, color = "#0f2f3a")
        ),
        margin = list(t = 60, b = 72, l = 56, r = 16)
      )
      chart <- plotly::config(chart, displaylogo = FALSE, displayModeBar = TRUE)
      htmlwidgets::onRender(chart, "
        function(el) {
          function fit() {
            var w = el.parentElement ? el.parentElement.clientWidth : 0;
            if (w > 80 && window.Plotly) Plotly.relayout(el, {width: w});
          }
          fit();
          window.addEventListener('resize', fit);
        }
      ")
    })
    fig_cash_line <- shiny::reactive({
      p <- pack()
      v <- pnl_view()
      m <- synthese_model()
      cash <- if (isTRUE(v$ready) && !is.null(v$cash)) v$cash else p$finance$cash
      if (is.null(cash) || !nrow(cash)) return(plotly::plotly_empty())
      # Full cash path, including months past fiscal year-end. Landing cards stay on the FY.
      if (!nrow(cash)) return(plotly::plotly_empty())
      cash$xday <- fpa_shiny_month_end(cash$periode)
      hover <- fpa_synthese_hover_cash(cash, p$finance$period_status)
      status <- p$finance$period_status
      etat <- rep("inconnu", nrow(cash))
      if (!is.null(status) && nrow(status)) {
        mst <- match(as.character(cash$periode), as.character(status$periode))
        hit <- !is.na(mst)
        flag <- as.character(status$status)[mst[hit]]
        etat[hit] <- ifelse(flag == "forecast", "prévision",
          ifelse(flag %in% c("actual", "réalisé", "closed"), "réalisé", "inconnu"))
      }
      act <- etat == "réalisé"
      fc <- etat == "prévision"
      floor_v <- suppressWarnings(as.numeric(m$cash_floor %||% 0))[1]
      if (!is.finite(floor_v)) floor_v <- 0
      chart <- plotly::plot_ly()
      cash_ribbon <- NULL
      today <- Sys.Date()
      if (isTRUE(v$ready) && !is.null(v$cash_low) && !is.null(v$cash_high) && length(v$open)) {
        pers <- as.character(v$cash_low$periode)
        central <- suppressWarnings(as.numeric(cash$cash_close[match(pers, as.character(cash$periode))]))
        band <- fpa_shiny_band_remaining(pers, central, v$cash_low$cash_close, v$cash_high$cash_close, today)
        idx <- which(pers %in% v$open)
        if (length(idx) && idx[[1]] > 1L) idx <- c(idx[[1]] - 1L, idx)
        if (length(idx) > 1L) {
          cash_ribbon <- data.frame(
            periode = pers[idx],
            xday = fpa_shiny_month_end(pers[idx]),
            low = band$low[idx],
            high = band$high[idx],
            ymin = pmin(band$low[idx], band$high[idx]),
            ymax = pmax(band$low[idx], band$high[idx]),
            stringsAsFactors = FALSE
          )
        }
      }
      if (is.null(cash_ribbon)) {
        cash_ribbon <- fpa_shiny_case_ribbon(p$finance$scenarios, p$finance$period_status, "cash_close")
        if (!is.null(cash_ribbon) && nrow(cash_ribbon)) {
          mid <- (cash_ribbon$ymin + cash_ribbon$ymax) / 2
          band <- fpa_shiny_band_remaining(cash_ribbon$periode, mid, cash_ribbon$ymin, cash_ribbon$ymax, today)
          cash_ribbon$low <- band$low
          cash_ribbon$high <- band$high
          cash_ribbon$ymin <- pmin(band$low, band$high)
          cash_ribbon$ymax <- pmax(band$low, band$high)
        }
      }
      month_end_today <- as.Date(fpa_shiny_month_end(format(today, "%Y-%m")))
      today_txt <- format(today, "%Y-%m-%d")
      eom_txt <- format(month_end_today, "%Y-%m-%d")
      cash_at_day <- function(xday, y, at) {
        xday <- as.Date(xday)
        y <- suppressWarnings(as.numeric(y))
        ok <- !is.na(xday) & is.finite(y)
        xday <- xday[ok]
        y <- y[ok]
        if (!length(xday)) return(NA_real_)
        ord <- order(xday)
        xday <- xday[ord]
        y <- y[ord]
        if (at <= xday[[1]]) return(y[[1]])
        if (at >= xday[[length(xday)]]) return(y[[length(y)]])
        i <- max(which(xday <= at))
        span <- as.numeric(xday[[i + 1L]] - xday[[i]])
        if (!is.finite(span) || span <= 0) return(y[[i]])
        y[[i]] + as.numeric(at - xday[[i]]) / span * (y[[i + 1L]] - y[[i]])
      }
      y_today <- cash_at_day(cash$xday, cash$cash_close, today)
      if (!is.null(cash_ribbon) && nrow(cash_ribbon) > 1L && is.finite(y_today)) {
        if (!"xday" %in% names(cash_ribbon)) cash_ribbon$xday <- fpa_shiny_month_end(cash_ribbon$periode)
        later <- cash_ribbon[as.Date(cash_ribbon$xday) > today, , drop = FALSE]
        if (nrow(later)) {
          mouth <- later[1, , drop = FALSE]
          anchor <- mouth
          anchor$periode <- today_txt
          anchor$xday <- today_txt
          anchor$ymin <- y_today
          anchor$ymax <- y_today
          anchor$low <- y_today
          anchor$high <- y_today
          cash_ribbon <- rbind(anchor, later)
        }
      }
      if (!is.null(cash_ribbon) && nrow(cash_ribbon) && all(c("low", "high") %in% names(cash_ribbon))) {
        for (i in seq_along(hover)) {
          j <- match(as.character(cash$periode[[i]]), as.character(cash_ribbon$periode))
          if (is.na(j)) next
          lo <- cash_ribbon$low[[j]]
          hi <- cash_ribbon$high[[j]]
          if (!is.finite(lo) || !is.finite(hi) || abs(lo - hi) < 0.5) next
          hover[[i]] <- paste0(
            hover[[i]], "<br>",
            fpa_screen("synth_hover_edge", fpa_synthese_eur(lo), fpa_synthese_eur(hi))
          )
        }
      }
      if (!is.null(cash_ribbon) && nrow(cash_ribbon) > 1L) {
        if (!"xday" %in% names(cash_ribbon)) cash_ribbon$xday <- fpa_shiny_month_end(cash_ribbon$periode)
        edge_tip <- vapply(seq_len(nrow(cash_ribbon)), function(i) {
          lo <- cash_ribbon$low[[i]]
          hi <- cash_ribbon$high[[i]]
          if (!is.finite(lo) || !is.finite(hi)) return("")
          when <- as.Date(cash_ribbon$xday[[i]])
          if (!is.na(when) && abs(lo - hi) < 0.5 && i < nrow(cash_ribbon)) {
            nxt <- cash_ribbon[i + 1L, , drop = FALSE]
            day <- paste(as.integer(format(as.Date(nxt$xday), "%d")), fpa_shiny_month_short(format(as.Date(nxt$xday), "%Y-%m")))
            return(fpa_screen("synth_hover_edge_on", day, fpa_synthese_eur(nxt$low), fpa_synthese_eur(nxt$high)))
          }
          if (abs(lo - hi) < 0.5) return("")
          fpa_screen("synth_hover_edge", fpa_synthese_eur(lo), fpa_synthese_eur(hi))
        }, "")
        chart <- plotly::add_ribbons(
          chart, data = cash_ribbon, x = ~xday, ymin = ~ymin, ymax = ~ymax,
          name = fpa_screen("cone_legend_band"),
          line = list(width = 0),
          fillcolor = "rgba(31,78,95,0.16)",
          hoverinfo = "skip"
        )
        chart <- plotly::add_trace(
          chart, data = cash_ribbon, x = ~xday, y = ~ymin,
          type = "scatter", mode = "lines", name = "band-low",
          line = list(color = "rgba(31,78,95,0.01)", width = 10),
          hovertext = edge_tip, hoverinfo = "text", showlegend = FALSE
        )
        chart <- plotly::add_trace(
          chart, data = cash_ribbon, x = ~xday, y = ~ymax,
          type = "scatter", mode = "lines", name = "band-high",
          line = list(color = "rgba(31,78,95,0.01)", width = 10),
          hovertext = edge_tip, hoverinfo = "text", showlegend = FALSE
        )
      }
      act_plot <- if (any(act)) cash[act, , drop = FALSE] else NULL
      hover_act <- if (any(act)) hover[act] else character()
      fc_plot <- if (any(fc)) cash[fc, , drop = FALSE] else NULL
      hover_fc <- if (any(fc)) hover[fc] else character()
      split_today <- is.finite(y_today) && any(act) && today > as.Date(cash$xday[[max(which(act))]]) && today <= month_end_today
      if (split_today) {
        tip <- act_plot[nrow(act_plot), , drop = FALSE]
        tip$xday <- today_txt
        tip$periode <- today_txt
        tip$cash_close <- y_today
        today_tip <- fpa_screen("pnl_cone_today", paste(as.integer(format(today, "%d")), fpa_shiny_month_short(format(today, "%Y-%m"))))
        act_plot <- rbind(act_plot, tip)
        hover_act <- c(hover_act, today_tip)
        if (!is.null(fc_plot)) {
          fc_plot <- rbind(tip, fc_plot)
          hover_fc <- c(today_tip, hover_fc)
        }
      }
      if (!is.null(act_plot)) {
        chart <- plotly::add_trace(
          chart, data = act_plot, x = ~xday, y = ~cash_close,
          type = "scatter", mode = "lines", name = fpa_synth_origin("rebuilt"),
          line = list(color = "#1f4e5f", width = 2.4),
          hovertext = hover_act, hoverinfo = "text"
        )
      }
      if (!is.null(fc_plot)) {
        if (!split_today && any(act)) {
          fc_plot <- rbind(cash[max(which(act)), , drop = FALSE], fc_plot)
          hover_fc <- c(hover[max(which(act))], hover_fc)
        }
        chart <- plotly::add_trace(
          chart, data = fc_plot, x = ~xday, y = ~cash_close,
          type = "scatter", mode = "lines", name = fpa_synth_origin("forecast"),
          line = list(color = "#1f4e5f", width = 2.4, dash = "dot"),
          hovertext = hover_fc, hoverinfo = "text"
        )
      }
      shapes <- list(list(
        type = "line", xref = "paper", x0 = 0, x1 = 1, y0 = floor_v, y1 = floor_v,
        line = list(color = "#8c3a3a", width = 1.2, dash = "dash")
      ))
      annotations <- list(list(
        xref = "paper", x = 1, y = floor_v, xanchor = "right",
        # Keep the floor label above the axis ticks when the floor sits at zero.
        yanchor = if (is.finite(floor_v) && abs(floor_v) < 1) "bottom" else "bottom",
        yshift = if (is.finite(floor_v) && abs(floor_v) < 1) 14 else 0,
        text = paste0("Plancher ", fpa_shiny_eur(floor_v)), showarrow = FALSE,
        font = list(size = 11, color = "#8c3a3a")
      ))
      marks <- fpa_synth_declared_marks(journal_entries())
      if (!is.null(marks) && nrow(marks)) {
        hover_mark <- vapply(seq_len(nrow(marks)), function(i) {
          line <- paste0(
            fpa_screen("loc_declared_sp"), fpa_shiny_eur(marks$amount[[i]]), " EUR au ",
            fpa_shiny_date_fr(marks$as_of[[i]])
          )
          note <- marks$note[[i]]
          if (nzchar(note)) line <- paste0(line, "<br>", note)
          line
        }, character(1))
        chart <- plotly::add_trace(
          chart,
          x = marks$as_of, y = marks$amount,
          type = "scatter", mode = "markers", name = fpa_synth_origin("declared"),
          marker = list(color = "#c47b2b", size = 11, symbol = "diamond"),
          hoverinfo = "text",
          hovertext = hover_mark
        )
      }
      moves <- NULL
      cur_m <- tryCatch(fpa_manual_read(p$config), error = function(e) NULL)
      active_n <- if (is.null(cur_m)) 0L else nrow(fpa_manual_active(cur_m$data))
      if (isTRUE(fpa_manual_applied(p$config))) {
        moves <- fpa_synth_ledger_marks(p$config, cash)
      }
      if ((is.null(moves) || !nrow(moves)) && active_n == 0L) {
        moves <- fpa_synth_movement_marks(journal_entries(), NULL)
      }
      if (!is.null(moves) && nrow(moves)) {
        chart <- plotly::add_trace(
          chart,
          x = moves$as_of, y = moves$amount,
          type = "scatter", mode = "markers", name = fpa_synth_origin("move"),
          marker = list(
            color = "#3b6fb6", size = 12,
            symbol = ifelse(moves$kind == "in", "triangle-up", "triangle-down")
          ),
          hoverinfo = "text",
          hovertext = paste0(
            moves$note, fpa_screen("loc_est_balance"), vapply(moves$amount, fpa_shiny_eur, character(1)),
            " EUR"
          )
        )
      }
      if (is.finite(m$breaches$low_fut %||% NA_real_) && nzchar(m$breaches$low_fut_m %||% "")) {
        annotations <- c(annotations, list(list(
          x = fpa_shiny_month_end(m$breaches$low_fut_m), y = m$breaches$low_fut,
          text = paste0("Min. futur ", fpa_shiny_eur(m$breaches$low_fut)),
          showarrow = TRUE, arrowhead = 0, ax = 0, ay = -28,
          font = list(size = 11, color = "#8c3a3a")
        )))
      }
      win_id <- as.character(input$synth_cash_window %||% "fy")
      if (!win_id %in% c("fy", "prior")) win_id <- "fy"
      fy_end <- suppressWarnings(as.integer((p$config$company %||% list())$fiscal_year_end_month %||% 12L))
      win <- fpa_fy_window(m$context$fy_months %||% character(), win_id)
      in_win <- function(d) {
        d <- as.Date(d)
        ok <- !is.na(d) & is.finite(win$start) & is.finite(win$end) & d >= win$start & d <= win$end
        ok[is.na(ok)] <- FALSE
        ok
      }
      y_vals <- suppressWarnings(as.numeric(cash$cash_close[in_win(cash$xday)]))
      if (!length(y_vals)) y_vals <- suppressWarnings(as.numeric(cash$cash_close))
      if (!is.null(cash_ribbon) && nrow(cash_ribbon)) {
        rk <- in_win(cash_ribbon$xday)
        if (any(rk)) y_vals <- c(y_vals, cash_ribbon$ymin[rk], cash_ribbon$ymax[rk])
      }
      if (!is.null(marks) && nrow(marks)) {
        mk <- in_win(marks$as_of)
        if (any(mk)) y_vals <- c(y_vals, marks$amount[mk])
      }
      if (!is.null(moves) && nrow(moves)) {
        vk <- in_win(moves$as_of)
        if (any(vk)) y_vals <- c(y_vals, moves$amount[vk])
      }
      y_mode <- as.character(synth_cash_yscale() %||% "fit")
      if (!y_mode %in% c("fit", "zero")) y_mode <- "fit"
      y_ax <- fpa_shiny_y_axis(
        y_vals, mode = y_mode, title = "Solde, EUR",
        anchors = c(floor_v, m$breaches$low_fut %||% NA_real_)
      )
      y_ax$uirevision <- paste0("cash-win-", win_id)
      # In fit mode the plancher at 0 is often off-screen; keep the shape only when visible.
      if (identical(y_mode, "fit") && is.finite(floor_v) &&
          (floor_v < y_ax$range[[1]] || floor_v > y_ax$range[[2]])) {
        shapes <- Filter(function(s) !(is.list(s) && identical(s$y0, floor_v)), shapes)
        annotations <- Filter(function(a) {
          !(is.list(a) && grepl("^Plancher", as.character(a$text %||% "")))
        }, annotations)
      }
      fy_marks <- fpa_fy_mark_dates(cash$periode, fy_end)
      if (nrow(fy_marks)) {
        shapes <- c(shapes, lapply(fy_marks$x, function(x) list(
          type = "line", xref = "x", yref = "paper", layer = "below",
          x0 = x, x1 = x, y0 = 0, y1 = 1,
          line = list(color = "#1a2b32", width = 1.6, dash = "dot")
        )))
        annotations <- c(annotations, lapply(seq_len(nrow(fy_marks)), function(i) {
          near_end <- is.finite(win$end) && as.Date(fy_marks$x[[i]]) >= win$end - 8
          list(
            x = fy_marks$x[[i]], y = 0.97, xref = "x", yref = "paper",
            xanchor = if (near_end) "right" else "left", yanchor = "top",
            text = paste0("<b>", fy_marks$label[[i]], "</b>"),
            showarrow = FALSE,
            font = list(size = 11, color = "#1a2b32")
          )
        }))
      }
      if (is.finite(month_end_today) && today < month_end_today) {
        short_d <- function(d) paste(as.integer(format(d, "%d")), fpa_shiny_month_short(format(d, "%Y-%m")))
        shapes <- c(shapes, list(
          list(
            type = "rect", xref = "x", yref = "paper", layer = "below",
            x0 = today_txt, x1 = eom_txt, y0 = 0, y1 = 1,
            fillcolor = "rgba(127,140,141,0.18)", line = list(width = 0)
          ),
          list(
            type = "line", xref = "x", yref = "paper",
            x0 = today_txt, x1 = today_txt, y0 = 0, y1 = 1,
            line = list(color = "#7f8c8d", width = 1.5, dash = "dot")
          ),
          list(
            type = "line", xref = "x", yref = "paper",
            x0 = eom_txt, x1 = eom_txt, y0 = 0, y1 = 1,
            line = list(color = "#1a2b32", width = 1.6, dash = "dot")
          )
        ))
        annotations <- c(annotations, list(
          list(
            x = today_txt, y = 0.90, xref = "x", yref = "paper",
            xanchor = "right", yanchor = "top",
            text = fpa_screen("pnl_cone_today", short_d(today)),
            showarrow = FALSE, font = list(size = 11, color = "#7f8c8d")
          ),
          list(
            x = eom_txt, y = 0.97, xref = "x", yref = "paper",
            xanchor = "left", yanchor = "top",
            text = paste0("<b>", fpa_screen("pnl_cone_eom", short_d(month_end_today)), "</b>"),
            showarrow = FALSE, font = list(size = 11, color = "#1a2b32")
          )
        ))
      }
      chart <- plotly::layout(
        chart,
        hovermode = "closest",
        shapes = shapes,
        annotations = annotations,
        yaxis = y_ax,
        xaxis = list(
          title = "", tickangle = -45, type = "date", automargin = TRUE,
          tickmode = "array", tickvals = cash$xday, ticktext = as.character(cash$periode),
          range = if (is.finite(win$start) && is.finite(win$end)) c(as.character(win$start), as.character(win$end)) else NULL,
          autorange = !(is.finite(win$start) && is.finite(win$end)),
          uirevision = paste0("cash-win-", win_id),
          rangeslider = list(
            visible = TRUE, thickness = 0.08,
            bgcolor = "#f4f8f8", bordercolor = "#d6e1e5", borderwidth = 1
          )
        ),
        legend = list(
          orientation = "h", x = 0, y = 1.14, xanchor = "left", yanchor = "bottom",
          bgcolor = "rgba(255,255,255,0.92)", borderwidth = 0, font = list(size = 13, color = "#0f2f3a")
        ),
        margin = list(t = 60, b = 28, l = 64, r = 16)
      )
      chart <- plotly::config(chart, displaylogo = FALSE, displayModeBar = TRUE)
      htmlwidgets::onRender(chart, "
        function(el) {
          function fit() {
            var w = el.parentElement ? el.parentElement.clientWidth : 0;
            if (w > 80 && window.Plotly) Plotly.relayout(el, {width: w, height: 480});
          }
          function inWindow(t, x0, x1) {
            if (!isFinite(x0) || !isFinite(x1)) return true;
            return t >= x0 && t <= x1;
          }
          function collect(tr, x0, x1) {
            if (!tr || tr.visible === false || tr.visible === 'legendonly') return [];
            var raw = tr.x || [];
            var xs = [];
            for (var i = 0; i < raw.length; i++) {
              var t = new Date(raw[i]).getTime();
              xs.push(isFinite(t) ? t : NaN);
            }
            var bags = [];
            if (tr.y) bags.push(tr.y);
            if (tr.ymin) bags.push(tr.ymin);
            if (tr.ymax) bags.push(tr.ymax);
            var ys = [];
            bags.forEach(function(bag) {
              if (!bag) return;
              if (xs.length && bag.length === xs.length) {
                for (var i = 0; i < xs.length; i++) {
                  if (!inWindow(xs[i], x0, x1)) continue;
                  var v = +bag[i];
                  if (isFinite(v)) ys.push(v);
                }
              }
            });
            return ys;
          }
          function fitY() {
            if (el._fpaFitting || !window.Plotly || !el.layout) return;
            var xr = (el.layout.xaxis && el.layout.xaxis.range) || [];
            var x0 = xr.length === 2 ? new Date(xr[0]).getTime() : NaN;
            var x1 = xr.length === 2 ? new Date(xr[1]).getTime() : NaN;
            var ys = [];
            (el.data || []).forEach(function(tr) { ys = ys.concat(collect(tr, x0, x1)); });
            if (!ys.length) return;
            var lo = Math.min.apply(null, ys);
            var hi = Math.max.apply(null, ys);
            var span = hi - lo;
            var pad = span > 0 ? span * 0.08 : Math.max(Math.abs(hi) * 0.04, 1);
            var bottom = lo - pad;
            var top = hi + pad;
            if (lo >= 0 && bottom < 0) bottom = 0;
            // Same rule as fpa_shiny_y_step: round the step up so labels cannot stack.
            function yStep(width) {
              var rough = width / 6;
              if (!(rough > 0)) return 1;
              var mag = Math.pow(10, Math.floor(Math.log10(rough)));
              var cand = [1, 2, 2.5, 5, 10];
              var step = 10 * mag;
              for (var i = 0; i < cand.length; i++) {
                if (cand[i] * mag >= rough - 1e-6) { step = cand[i] * mag; break; }
              }
              return step;
            }
            var step = yStep(Math.max(top - bottom, 1));
            bottom = Math.floor(bottom / step) * step;
            top = Math.ceil(top / step) * step;
            if (lo >= 0 && bottom < 0) bottom = 0;
            if ((top - bottom) / step > 6) {
              step = yStep(Math.max(top - bottom, 1));
              if ((top - bottom) / step > 6) step = step * 2;
              bottom = Math.floor(bottom / step) * step;
              top = Math.ceil(top / step) * step;
              if (lo >= 0 && bottom < 0) bottom = 0;
            }
            el._fpaFitting = true;
            Plotly.relayout(el, {
              'yaxis.range': [bottom, top],
              'yaxis.dtick': step,
              'yaxis.tick0': bottom,
              'yaxis.minor.dtick': step / 2,
              'yaxis.autorange': false,
              'yaxis.automargin': true
            }).then(function() { el._fpaFitting = false; }, function() { el._fpaFitting = false; });
          }
          if (el._fpaCashZoom) {
            try { el.removeListener('plotly_relayout', el._fpaCashZoom); } catch (e) {}
          }
          el._fpaCashZoom = function(ev) {
            if (!ev || el._fpaFitting) return;
            var keys = Object.keys(ev);
            if (keys.some(function(k) { return k.indexOf('xaxis.range') === 0 || k === 'xaxis.autorange'; })) fitY();
          };
          el.on('plotly_relayout', el._fpaCashZoom);
          if (!el._fpaCashResize) {
            el._fpaCashResize = true;
            window.addEventListener('resize', fit);
          }
          fit();
          fitY();
        }
      ")
    })
    output$plot_cash_line <- plotly::renderPlotly({
      fig <- fig_cash_line()
      if (is.null(fig)) return(plotly::plotly_empty())
      fig
    })
    bridge_fig_make <- function(force_link = NULL) {
      link <- if (!is.null(force_link) && nzchar(as.character(force_link))) as.character(force_link) else input$bridge_link
      built <- fpa_shiny_bridge_build(
        cash_now(), input$bridge_view, input$bridge_period, input$bridge_span, input$bridge_start, link, input$bridge_grain
      )
      if (is.null(built)) return(plotly::plotly_empty())
      br <- built$bars
      tiers <- fpa_shiny_bridge_tiers(built)
      amounts <- vapply(br$value, fpa_shiny_eur, character(1))
      signs <- ifelse(br$value >= 0, "+", "")
      cols <- ifelse(br$kind == "total", "#0f2f3a", ifelse(br$value >= 0, "#1f4e5f", "#8c3a3a"))

      bands <- list()
      if (tiers$bands && !is.null(built$months) && nrow(built$months) > 1) {
        even <- seq(2, nrow(built$months), by = 2)
        bands <- lapply(even, function(i) {
          list(
            type = "rect", xref = "x", yref = "paper", layer = "below",
            x0 = built$months$x0[i] - 0.62, x1 = built$months$x1[i] + 0.62,
            y0 = 0, y1 = 1, fillcolor = "#f1f6f7", line = list(width = 0)
          )
        })
      }
      links <- if (!is.null(built$connectors)) {
        lapply(seq_len(nrow(built$connectors)), function(i) {
          list(
            type = "line", xref = "x", yref = "y",
            x0 = built$connectors$x0[i], x1 = built$connectors$x1[i],
            y0 = built$connectors$y[i], y1 = built$connectors$y[i],
            line = list(color = "#7d9299", width = 1.1)
          )
        })
      } else {
        list()
      }

      months <- built$months
      annotations <- list()
      if (tiers$steps_on_axis && !isTRUE(built$monthly) && !is.null(months) && length(built$periods) > 1L) {
        keep <- seq(1, nrow(months), by = tiers$month_every)
        annotations <- lapply(keep, function(i) {
          list(
            x = months$x[i], y = 1.03, xref = "x", yref = "paper",
            text = months$month[i], showarrow = FALSE, textangle = if (tiers$month_every > 1) -90 else 0,
            yanchor = "bottom", font = list(size = 12, color = "#1f4e5f")
          )
        })
      }

      if (tiers$steps_on_axis) {
        idx <- seq_len(nrow(br))
        if (isTRUE(built$monthly) && tiers$month_every > 1L) {
          steps_i <- which(br$kind == "step")
          idx <- sort(unique(c(
            which(br$kind == "total"),
            steps_i[seq(1, length(steps_i), by = tiers$month_every)]
          )))
        }
        tickvals <- br$x[idx]
        ticktext <- br$label[idx]
      } else if (!is.null(months)) {
        keep <- seq(1, nrow(months), by = tiers$month_every)
        tickvals <- months$x[keep]
        ticktext <- months$month[keep]
      } else {
        tickvals <- br$x
        ticktext <- br$label
      }
      tickangle <- if (tiers$upright) 0 else -90

      y_mode <- as.character(bridge_yscale() %||% "fit")
      if (!y_mode %in% c("fit", "zero")) y_mode <- "fit"
      # Total bars are drawn from zero. The scale follows the running balance.
      levels <- br$end
      if (any(br$kind != "total")) levels <- c(levels, br$base[br$kind != "total"])
      lim <- fpa_shiny_round_axis(levels, y_mode)
      y_ax <- fpa_shiny_y_axis(lim, mode = "fit", title = "EUR", pad = 0)
      y_ax$range <- lim
      y_ax$autorange <- FALSE
      y_ax$tick0 <- lim[[1]]
      y_ax$zerolinecolor <- "#1f4e5f"
      y_ax$zerolinewidth <- 2

      fc_months <- fpa_shiny_forecast_periods(pack()$finance$period_status)
      xcut <- fpa_shiny_bridge_future_x(built, fc_months)
      future <- list()
      if (is.finite(xcut)) {
        future <- list(
          list(
            type = "rect", xref = "x", yref = "paper", layer = "below",
            x0 = xcut, x1 = max(br$x) + 0.7, y0 = 0, y1 = 1,
            fillcolor = "rgba(138,90,0,0.08)", line = list(width = 0)
          ),
          list(
            type = "line", xref = "x", yref = "paper",
            x0 = xcut, x1 = xcut, y0 = 0, y1 = 1,
            line = list(color = "#8a5a00", width = 1.6, dash = "dot")
          )
        )
        lab_x <- xcut
        if (!is.null(months) && nrow(months) && months$month[[1]] %in% fc_months) lab_x <- months$x[[1]]
        annotations <- c(annotations, list(list(
          x = lab_x, y = 1.02, xref = "x", yref = "paper",
          xanchor = "left", yanchor = "bottom",
          text = paste0("\u00a0", fpa_screen("var_plot_fc"), " \u2192"),
          showarrow = FALSE,
          font = list(size = 11, color = "#8a5a00")
        )))
      }

      p <- plotly::plot_ly(
        type = "bar",
        x = br$x,
        y = br$value,
        base = br$base,
        width = built$width,
        marker = list(color = cols, line = list(width = 0)),
        text = if (tiers$values) paste0(signs, amounts) else "",
        textposition = if (tiers$values) "outside" else "none",
        textangle = if (tiers$upright) 0 else -90,
        cliponaxis = FALSE,
        constraintext = "none",
        textfont = list(size = 11, color = "#1a2b32"),
        hovertext = paste0(
          "<b>", br$month, "</b> · ", br$label, "<br>",
          ifelse(br$kind == "total", "Solde ", ""), signs, amounts, " EUR",
          ifelse(br$kind == "total", "", paste0("<br>Cumul ", vapply(br$end, fpa_shiny_eur, character(1)), " EUR"))
        ),
        hoverinfo = "text",
        showlegend = FALSE
      )
      if (isTRUE(manual_show())) {
        cur <- tryCatch(fpa_manual_read(pack()$config), error = function(e) NULL)
        dfm <- if (is.null(cur)) NULL else fpa_manual_active(cur$data)
        if (!is.null(dfm) && nrow(dfm) && !is.null(months) && nrow(months)) {
          xs <- numeric()
          ys <- numeric()
          tips <- character()
          keys <- character()
          syms <- character()
          for (i in seq_len(nrow(dfm))) {
            per <- format(fpa_manual_parse_date(dfm$date_effet[[i]]), "%Y-%m")
            ix <- match(per, as.character(months$month))
            if (is.na(ix)) next
            steps <- br[br$kind == "step" & as.character(br$month) == per, , drop = FALSE]
            if (!nrow(steps)) next
            xs <- c(xs, months$x[[ix]])
            ys <- c(ys, steps$end[[nrow(steps)]])
            sens <- if (identical(as.character(dfm$sens[[i]]), "in")) fpa_screen("out_in") else fpa_screen("out_out")
            nat <- if (identical(as.character(dfm$nature[[i]]), "decalage")) fpa_screen("man_decalage") else fpa_screen("man_nouveau")
            tips <- c(tips, fpa_screen(
              "man_mark_hover", nat, as.character(dfm$libelle[[i]]),
              fpa_shiny_eur(dfm$montant[[i]]), as.character(dfm$date_effet[[i]]),
              paste(sens, fpa_screen("man_mark_cash"))
            ))
            keys <- c(keys, "manual:ledger")
            syms <- c(syms, if (identical(as.character(dfm$sens[[i]]), "in")) "triangle-up" else "triangle-down")
          }
          if (length(xs)) {
            p <- plotly::add_markers(
              p, x = xs, y = ys, name = fpa_screen("man_legend"),
              inherit = FALSE,
              marker = list(symbol = syms, size = 14, color = "#3b6fb6", line = list(color = "#fff", width = 1)),
              hovertext = tips, hoverinfo = "text", customdata = keys
            )
          }
        }
      }
      p <- plotly::layout(
        p,
        autosize = TRUE,
        separators = ",\u202f",
        bargap = 0,
        hovermode = "closest",
        plot_bgcolor = "#ffffff",
        paper_bgcolor = "#ffffff",
        yaxis = y_ax,
        xaxis = list(
          title = "",
          tickmode = "array",
          tickvals = tickvals,
          ticktext = ticktext,
          tickangle = tickangle,
          tickfont = list(size = 11, color = "#33474f"),
          showgrid = FALSE,
          range = c(min(br$x) - 0.55, max(br$x) + 0.55)
        ),
        shapes = c(bands, links, future),
        annotations = annotations,
        margin = list(t = 28, b = if (tiers$upright) 48 else 78, l = 64, r = 12)
      )
      p <- plotly::config(
        p,
        responsive = TRUE,
        displayModeBar = TRUE,
        displaylogo = FALSE,
        scrollZoom = TRUE,
        doubleClick = "reset"
      )
      htmlwidgets::onRender(p, "
        function(el) {
          function fit() {
            var host = el.closest('.fpa-cash') || el.parentElement;
            var w = host ? host.clientWidth : 0;
            if (w > 80 && window.Plotly) Plotly.relayout(el, {width: w});
          }
          fit();
          if (window.ResizeObserver) {
            new ResizeObserver(fit).observe(el.closest('.fpa-cash') || el.parentElement);
          }
          window.addEventListener('resize', fit);
        }
      ")
    }
    fig_cash_bridge <- shiny::reactive(bridge_fig_make(NULL))
    output$plot_bridge <- plotly::renderPlotly({
      fig <- fig_cash_bridge()
      if (is.null(fig)) return(plotly::plotly_empty())
      fig
    })
  } else {
    output$plot_trend <- shiny::renderPlot({
      v <- pnl_view()
      pnl <- if (isTRUE(v$ready)) v$pnl else pack()$finance$pnl
      if (is.null(pnl) || !nrow(pnl)) return(invisible(NULL))
      x <- seq_len(nrow(pnl))
      rev <- fpa_shiny_cum_year(pnl$periode, pnl$REV)
      oi <- fpa_shiny_cum_year(pnl$periode, pnl$OI)
      span <- fpa_shiny_span(rev, oi)
      if (is.null(span)) return(invisible(NULL))
      plot(x, rev, type = "l", col = "#1f4e5f", lwd = 2, xlab = "Mois", ylab = "EUR cumulés",
           ylim = span, xaxt = "n")
      lines(x, oi, col = "#c47b2b", lwd = 2)
      axis(1, at = x, labels = pnl$periode, las = 2, cex.axis = 0.6)
      legend("topleft", c("Chiffre d'affaires", fpa_screen("loc_oi_ascii")),
             col = c("#1f4e5f", "#c47b2b"), lty = 1, bty = "n")
      title("Trajectoire mensuelle")
    })
    output$plot_cash_line <- shiny::renderPlot({
      cash <- cash_now()
      if (is.null(cash) || !nrow(cash)) return(invisible(NULL))
      x <- seq_len(nrow(cash))
      plot(x, cash$cash_close, type = "l", col = "#1f4e5f", lwd = 2,
           xlab = "Mois", ylab = "EUR", xaxt = "n")
      axis(1, at = x, labels = cash$periode, las = 2, cex.axis = 0.6)
      title(fpa_screen("loc_cash_close_ascii"))
    })
    output$plot_bridge <- shiny::renderPlot({
      built <- fpa_shiny_bridge_build(
        cash_now(), input$bridge_view, input$bridge_period, input$bridge_span, input$bridge_start, input$bridge_link, input$bridge_grain
      )
      if (is.null(built)) return(invisible(NULL))
      br <- built$bars
      y_mode <- as.character(bridge_yscale() %||% "fit")
      if (!y_mode %in% c("fit", "zero")) y_mode <- "fit"
      levels <- br$end
      if (any(br$kind != "total")) levels <- c(levels, br$base[br$kind != "total"])
      lim <- fpa_shiny_round_axis(levels, y_mode)
      span <- lim
      xcut <- fpa_shiny_bridge_future_x(built, fpa_shiny_forecast_periods(pack()$finance$period_status))
      plot(NA, xlim = c(min(br$x) - 0.7, max(br$x) + 0.7), ylim = span,
           xlab = "", ylab = "EUR", xaxt = "n",
           main = if (length(built$periods) == 1) paste("Pont de tresorerie", built$periods[[1]]) else "Pont de tresorerie")
      cols <- ifelse(br$kind == "total", "#0f2f3a", ifelse(br$value >= 0, "#1f4e5f", "#8c3a3a"))
      half <- built$width / 2
      rect(br$x - half, br$base, br$x + half, br$end, col = cols, border = NA)
      if (!is.null(built$connectors)) {
        segments(built$connectors$x0, built$connectors$y, built$connectors$x1, built$connectors$y, col = "#5c6b73")
      }
      abline(h = 0, col = "#1f4e5f", lwd = 2)
      if (is.finite(xcut)) abline(v = xcut, col = "#8a5a00", lwd = 1.6, lty = 2)
      axis(1, at = br$x, labels = br$label, las = 2, cex.axis = 0.75)
      text(built$months$x, span[2], built$months$month, col = "#1f4e5f", cex = 0.85)
    })
  }

