  }, ignoreInit = TRUE)

  output$pnl_partner_flat <- shiny::renderUI({
    fpa_shiny_flat_ui(pnl_view(), pack()$config)
  })

  output$pnl_partner <- shiny::renderUI({
    p <- pack()
    fin <- p$finance
    open_all <- fpa_shiny_open_months(fin$pnl, fin$period_status)
    fy <- character()
    tryCatch({
      pers <- if (!is.null(fin$pnl) && nrow(fin$pnl)) as.character(fin$pnl$periode) else character()
      ye <- fpa_year_end_info(p$config %||% list(), fin$period_status, pers)
      fy <- as.character(ye$months %||% character())
    }, error = function(e) NULL)
    open <- if (length(fy)) intersect(open_all, fy) else open_all
    if (!length(open)) {
      return(shiny::tags$div(
        class = "fpa-partner",
        shiny::uiOutput("pnl_partner_flat"),
        shiny::tags$p(class = "fpa-partner-kicker", fpa_screen("pnl_partner_kicker")),
        shiny::tags$p(class = "fpa-partner-lead", fpa_screen("pnl_partner_lead_none"))
      ))
    }
    held <- shiny::isolate(scn_choice())
    pick <- function(id, per = NULL) {
      mem <- if (!is.null(per)) held[[per]] else held[["__all"]]
      cur <- shiny::isolate(input[[id]] %||% "")
      sel <- if (!is.null(mem) && mem %in% c("low", "base", "high")) mem else as.character(cur)
      if (!sel %in% c("low", "base", "high")) "base" else sel
    }
    month_lab <- function(per) {
      nm <- fpa_shiny_month_name(per)
      y <- substr(as.character(per), 1, 4)
      if (nzchar(y)) paste(nm, y) else nm
    }
    shiny::tags$div(
      class = "fpa-partner",
      shiny::uiOutput("pnl_partner_flat"),
      shiny::tags$p(class = "fpa-partner-kicker", fpa_screen("pnl_partner_kicker")),
      shiny::tags$p(
        class = "fpa-partner-lead",
        fpa_screen("pnl_partner_lead", length(open), paste(vapply(open, month_lab, character(1)), collapse = ", "))
      ),
      shiny::tags$div(
        class = "fpa-partner-row",
        fpa_shiny_case_input("case_all", fpa_screen("pnl_partner_all"), pick("case_all")),
        lapply(open, function(per) {
          id <- paste0("case_", gsub("-", "_", per))
          fpa_shiny_case_input(id, month_lab(per), pick(id, per))
        })
      )
    )
  })

  output$pnl_partner_read <- shiny::renderUI({
    v <- pnl_view()
    if (!isTRUE(v$ready) || !length(v$open)) return(NULL)
    p <- pack()
    show <- as.character(v$open)
    fy <- tryCatch({
      pers <- if (!is.null(p$finance$pnl) && nrow(p$finance$pnl)) as.character(p$finance$pnl$periode) else character()
      as.character(fpa_year_end_info(p$config %||% list(), p$finance$period_status, pers)$months)
    }, error = function(e) character())
    if (length(fy)) show <- intersect(show, fy)
    num <- function(x, d) formatC(round(x, d), format = "f", digits = d, decimal.mark = ",", big.mark = " ")
    lines <- lapply(show, function(per) {
      e <- v$edits[[per]]
      if (is.null(e)) return(NULL)
      r <- if (!is.null(v$widths)) v$widths[[per]] else v$ranges
      id <- if (!is.null(v$cases[[per]])) v$cases[[per]] else "base"
      who <- switch(id, low = fpa_screen("scen_bas"), high = fpa_screen("scen_haut"), fpa_screen("scen_central"))
      occ <- fpa_shiny_shock_number(e$occ, "taux_utilisation", r, id)
      rate <- fpa_shiny_shock_number(e$rate, "tarif", r, id)
      head_n <- fpa_shiny_shock_number(e$head, "effectif", r, id)
      cost <- fpa_shiny_shock_number(e$cost, "cout_moyen", r, id)
      if (!any(is.finite(c(occ, rate, head_n, cost)))) return(NULL)
      shiny::tags$div(fpa_screen(
        "pnl_partner_mean",
        fpa_shiny_month_name(per), who,
        num(occ, 2), num(rate, 2), num(head_n, 2), num(cost, 0)
      ))
    })
    lines <- Filter(Negate(is.null), lines)
    if (!length(lines)) return(NULL)
    shiny::tagList(
      shiny::tags$div(class = "fpa-partner-read", lines)
    )
  })

  output$scenario_rank <- shiny::renderUI({
    fpa_shiny_rank_table(pack()$finance$scenario_ranks)
  })

  output$pnl_drivers <- shiny::renderUI({
    p <- pack()
    fin <- p$finance
    open <- fpa_shiny_open_months(fin$pnl, fin$period_status)
    vol <- fpa_shiny_volumes(p$config, p$paths)
    if (!length(open) || is.null(vol)) return(NULL)
    has_occ <- "taux_utilisation" %in% names(vol) && any(is.finite(suppressWarnings(as.numeric(vol$taux_utilisation))))
    has_hire <- "effectif" %in% names(vol) && any(is.finite(suppressWarnings(as.numeric(vol$effectif))))
    hist <- tryCatch(fpa_history_pnl(p$config, p$paths), error = function(e) NULL)
    span <- fpa_history_span(hist)
    lines <- fpa_shiny_driven_lines(fin$line_drivers)
    last_act <- setdiff(as.character(fin$pnl$periode), open)
    var0 <- 2.6
    if (length(last_act) && all(c("COGS", "REV") %in% names(fin$pnl))) {
      i <- match(last_act[[length(last_act)]], fin$pnl$periode)
      rev <- suppressWarnings(as.numeric(fin$pnl$REV[[i]]))
      cogs <- suppressWarnings(as.numeric(fin$pnl$COGS[[i]]))
      if (is.finite(rev) && abs(rev) > 1 && is.finite(cogs)) var0 <- round(100 * cogs / rev, 1)
    }
    num <- function(id, value, step) {
      shiny::numericInput(id, NULL, value = value, step = step, width = "76px")
    }
    cells <- lapply(open, function(per) {
      hit <- which(as.character(vol$periode) == per)
      row <- if (length(hit)) vol[hit[[1]], , drop = FALSE] else NULL
      id <- gsub("-", "_", per)
      rooms <- if (!is.null(row)) suppressWarnings(as.numeric(row$capacite[[1]])) else NA_real_
      list(
        title = shiny::tags$div(
          class = "mh",
          fpa_shiny_month_short(per),
          shiny::tags$span(class = "ms", if (is.finite(rooms)) fpa_screen("pnl_drv_rooms", format(round(rooms), trim = TRUE)) else "")
        ),
        occ = num(paste0("drv_occ_", id), if (!is.null(row)) round(100 * as.numeric(row$taux_utilisation[[1]]), 2) else NA, 0.1),
        rate = num(paste0("drv_rate_", id), if (!is.null(row)) round(as.numeric(row$tarif[[1]]), 2) else NA, 1),
        staff = num(paste0("drv_head_", id), if (!is.null(row)) round(as.numeric(row$effectif[[1]]), 2) else NA, 0.1),
        cost = num(paste0("drv_cost_", id), if (!is.null(row)) round(as.numeric(row$cout_moyen[[1]]), 1) else NA, 10)
      )
    })
    shiny::tags$div(
      class = "fpa-drv",
      style = sprintf("--drv-n:%d;", length(open)),
      shiny::tags$p(class = "fpa-drv-lead", fpa_screen("scn_lead")),
      shiny::tags$div(
        class = "fpa-path-actions",
        if (has_occ) shiny::actionButton(
          "scn_occ", fpa_screen("scn_occ"),
          style = "background:#fff;color:#1f4e5f;border:1px solid #1f4e5f;border-radius:8px;font-weight:600;"
        ),
        if (has_hire) shiny::actionButton(
          "scn_hire", fpa_screen("scn_hire"),
          style = "background:#fff;color:#1f4e5f;border:1px solid #1f4e5f;border-radius:8px;font-weight:600;"
        )
      ),
      shiny::tags$p(class = "fpa-drv-lead", fpa_screen("scn_capex")),
      if (span$n > 0L) shiny::tags$p(
        class = "fpa-drv-lead",
        fpa_screen("pnl_drv_lead", span$n, span$from, span$to)
      ),
      shiny::tags$div(
        class = "fpa-drv-grid",
        shiny::tags$div(),
        lapply(cells, function(cell) cell$title),
        shiny::tags$div(class = "rl", fpa_screen("pnl_drv_occ")),
        lapply(cells, function(cell) cell$occ),
        shiny::tags$div(class = "rl", fpa_screen("pnl_drv_rate")),
        lapply(cells, function(cell) cell$rate),
        shiny::tags$div(class = "rl", fpa_screen("pnl_drv_head")),
        lapply(cells, function(cell) cell$staff),
        shiny::tags$div(class = "rl", fpa_screen("pnl_drv_cost")),
        lapply(cells, function(cell) cell$cost),
        if (is.null(lines)) shiny::tags$div(class = "rl", fpa_screen("pnl_drv_var")),
        if (is.null(lines)) num("drv_var_pct", var0, 0.1),
        if (is.null(lines)) rep(list(shiny::tags$div()), max(0L, length(open) - 1L))
      ),
      if (!is.null(lines)) fpa_shiny_driven_list(lines)
    )
  })

  output$scenario_cash_pick <- shiny::renderUI({
    v <- pnl_view()
