  shiny::observeEvent(input$scn_flat_map, {
    bslib::nav_select("main_nav", "Drivers")
    shiny::updateTabsetPanel(session, "driver_tabs", selected = "Carte")
    session$sendCustomMessage("fpa-open-details", list(sel = "#drv-more"))
  }, ignoreInit = TRUE)

  # The dock writes here first. The month radios follow. A redraw of those radios
  # must not put the chart back on the central case.
  scn_choice <- shiny::reactiveVal(list())

  shiny::observeEvent(input$scn_dock, {
    msg <- input$scn_dock
    if (is.null(msg)) return()
    sel <- as.character(msg$case %||% "")
    scope <- as.character(msg$scope %||% "")
    if (!sel %in% c("low", "base", "high")) return()
    open <- fpa_shiny_open_months(pack()$finance$pnl, pack()$finance$period_status)
    cur <- scn_choice()
    if (identical(scope, "all")) {
      for (per in open) cur[[per]] <- sel
      cur[["__all"]] <- sel
      scn_choice(cur)
      shiny::updateRadioButtons(session, "case_all", selected = sel)
      return()
    }
    if (!scope %in% open) return()
    cur[[scope]] <- sel
    scn_choice(cur)
    shiny::updateRadioButtons(session, paste0("case_", gsub("-", "_", scope)), selected = sel)
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$case_all, {
    open <- fpa_shiny_open_months(pack()$finance$pnl, pack()$finance$period_status)
    sel <- as.character(input$case_all %||% "")
    if (!sel %in% c("low", "base", "high") || !length(open)) return()
    cur <- scn_choice()
    cur[["__all"]] <- sel
    for (per in open) {
      cur[[per]] <- sel
      shiny::updateRadioButtons(session, paste0("case_", gsub("-", "_", per)), selected = sel)
    }
    scn_choice(cur)
  }, ignoreInit = TRUE)

  #' A month radio the user moves is kept. This does not read scn_choice, so a
  #' dock click is not overwritten by the radio's previous value.
  shiny::observe({
    open <- fpa_shiny_open_months(pack()$finance$pnl, pack()$finance$period_status)
    if (!length(open)) return()
    cur <- shiny::isolate(scn_choice())
    changed <- FALSE
    for (per in open) {
      val <- input[[paste0("case_", gsub("-", "_", per))]]
      if (is.null(val) || !val %in% c("low", "base", "high")) next
      val <- as.character(val)
      if (!identical(cur[[per]], val)) {
        cur[[per]] <- val
        changed <- TRUE
      }
    }
    if (changed) scn_choice(cur)
  })

  output$pnl_headline <- shiny::renderUI({
    fin <- pack()$finance
    if (is.null(fin$pnl) || !nrow(fin$pnl)) return(NULL)
    txt <- fpa_synthese_pnl_headline(if (isTRUE(pnl_view()$ready)) pnl_view()$pnl else fin$pnl, variance_view(), input$pnl_span, input$pnl_start)
    if (!nzchar(txt)) return(NULL)
    closed <- tryCatch(fpa_health_closed_month(fin$period_status), error = function(e) "")
    note <- fpa_nav_restore_note()
    shiny::tagList(
      if (nzchar(closed)) shiny::tags$div(class = "fpa-period-chip", fpa_period_chip_label("actual", closed)),
      shiny::tags$p(style = "margin:0.2rem 0 0.5rem;line-height:1.45;font-weight:600;color:#1f4e5f;", txt),
      if (nzchar(note)) shiny::tags$p(
        class = "fpa-bs-cmp-note",
        note, " ",
        shiny::tags$button(
          type = "button", class = "fpa-path-btn is-quiet",
          onclick = "Shiny.setInputValue('nav_fy_return', Date.now(), {priority:'event'})",
          fpa_screen("synth_cash_window_fy")
        )
      )
    )
  })

