  budget_view <- shiny::reactive({
    p <- pack()
    bud <- p$finance$budget
    if (is.null(bud) || !nrow(bud) || !fpa_budget_season_on(p$config)) return(bud)
    mapped <- fpa_season_mapped(p$config, p$paths)
    byear <- max(substr(as.character(bud$periode), 1, 4))
    catalogue <- fpa_season_year_rows(mapped, byear, fpa_budget_season_lookback(p$config))
    years <- as.character(catalogue$year)
    picked <- lapply(years, function(y) input[[paste0("season_keep_", y)]])
    keep <- if (!length(years) || all(vapply(picked, is.null, logical(1)))) {
      saved <- fpa_season_keep_read(p$paths)
      if (is.null(saved)) catalogue$year[catalogue$complete] else saved
    } else {
      years[vapply(picked, isTRUE, logical(1))]
    }
    fpa_budget_reshape(bud, mapped, p$config, keep)
  })

  shiny::observe({
    p <- pack()
    if (!isTRUE(p$ok) || !fpa_budget_season_on(p$config)) return()
    bud <- p$finance$budget
    if (is.null(bud) || !nrow(bud)) return()
    mapped <- fpa_season_mapped(p$config, p$paths)
    catalogue <- fpa_season_year_rows(mapped, max(substr(as.character(bud$periode), 1, 4)), fpa_budget_season_lookback(p$config))
    if (!nrow(catalogue)) return()
    picked <- lapply(catalogue$year, function(y) input[[paste0("season_keep_", y)]])
    if (any(vapply(picked, is.null, logical(1)))) return()
    fpa_season_keep_write(p$paths, catalogue$year, catalogue$year[vapply(picked, isTRUE, logical(1))])
  })

  fpa_shiny_season_note <- function(budget) {
    info <- attr(budget, "season")
    if (is.null(info) || !isTRUE(info$on)) {
      return(shiny::tags$p(class = "fpa-var-note", fpa_screen("sea_flat_echo")))
    }
    if ("none" %in% info$fallback || "need_two" %in% info$fallback || !length(info$years)) {
      return(shiny::tags$p(class = "fpa-var-note", fpa_screen("sea_need")))
    }
    dropped <- as.character(info$dropped %||% character(0))
    dropped <- dropped[nzchar(dropped)]
    bits <- c(
      fpa_screen("sea_echo", paste(info$years, collapse = ", ")),
      if (length(info$years) == 1L) {
        fpa_screen("sea_one")
      } else if (length(dropped)) {
        fpa_screen("sea_dropped", paste(vapply(dropped, fpa_shiny_scn_month_lab, character(1)), collapse = ", "))
      } else {
        fpa_screen("sea_dropped_none")
      }
    )
    shiny::tags$p(class = "fpa-var-note", paste(bits, collapse = " "))
  }

  pnl_view <- shiny::reactive({
    p <- pack()
    fin <- p$finance
    open <- fpa_shiny_open_months(fin$pnl, fin$period_status)
    ranges <- fpa_shiny_ranges(p$config)
    months <- as.character(fin$pnl$periode)
    locked <- vapply(months, function(per) fpa_shiny_month_is_locked(per, open, input), logical(1))
    names(locked) <- months
    active <- months[!locked]
    widths <- list()
    for (per in months) widths[[per]] <- fpa_shiny_widths_for(ranges, per, input)
    edits <- list()
    ready <- length(active) > 0L
    for (per in open) {
      id <- gsub("-", "_", per)
      occ <- input[[paste0("drv_occ_", id)]]
      rate <- input[[paste0("drv_rate_", id)]]
      head_n <- input[[paste0("drv_head_", id)]]
      cost <- input[[paste0("drv_cost_", id)]]
      if (is.null(occ) || is.null(rate) || is.null(head_n) || is.null(cost)) next
      edits[[per]] <- list(
        occ = suppressWarnings(as.numeric(occ)),
        rate = suppressWarnings(as.numeric(rate)),
        head = suppressWarnings(as.numeric(head_n)),
        cost = suppressWarnings(as.numeric(cost))
      )
    }
    lines <- fpa_shiny_driven_lines(fin$line_drivers)
    var_pct <- if (is.null(lines) && length(input$drv_var_pct)) {
      suppressWarnings(as.numeric(input$drv_var_pct))
    } else {
      NA_real_
    }
    vol <- fpa_shiny_volumes(p$config, p$paths)
    build <- function(case_name) {
      if (!ready) return(fin$pnl)
      fpa_shiny_case_pnl(
        fin$pnl, vol, open, edits, var_pct, ranges, case_name, lines,
        active = active, widths = widths
      )
    }
    low <- if (ready) build("low") else fin$pnl
    base <- if (ready) build("base") else fin$pnl
    high <- if (ready) build("high") else fin$pnl
    cases <- setNames(rep("base", length(active)), active)
    held <- scn_choice()
    for (per in active) {
      mem <- held[[per]]
      cases[[per]] <- if (!is.null(mem) && mem %in% c("low", "base", "high")) {
        mem
      } else {
        fpa_shiny_month_case(per, input)
      }
    }
    path <- if (ready) fpa_shiny_stitch_pnl(base, low, high, cases) else fin$pnl
    shown <- if (length(open)) open[[1]] else if (length(active)) active[[1]] else NULL
    list(
      pnl = path,
      low = low,
      base = base,
      high = high,
      open = open,
      active = active,
      cases = cases,
      case_id = if (length(unique(cases)) == 1L && length(cases)) unname(cases[[1]]) else "base",
      ranges = if (!is.null(shown)) widths[[shown]] else ranges,
      widths = widths,
      ready = ready,
      edits = edits,
      lines = lines,
      budget = budget_view(),
      cash = fpa_shiny_cash_path(fin$cash, base, path),
      cash_low = fpa_shiny_cash_path(fin$cash, base, low),
      cash_high = fpa_shiny_cash_path(fin$cash, base, high),
      status = fin$period_status,
      long = fin$pnl_long
    )
  })

  cash_now <- function() {
    v <- pnl_view()
    if (isTRUE(v$ready) && !is.null(v$cash) && nrow(v$cash)) return(v$cash)
    pack()$finance$cash
  }

