  shiny::observeEvent(input$scn_occ, {
    p <- pack()
    open <- fpa_shiny_open_months(p$finance$pnl, p$finance$period_status)
    vol <- fpa_shiny_volumes(p$config, p$paths)
    for (per in open) {
      id <- gsub("-", "_", per)
      hit <- if (!is.null(vol)) which(as.character(vol$periode) == per) else integer()
      base <- if (length(hit)) 100 * suppressWarnings(as.numeric(vol$taux_utilisation[[hit[[1]]]])) else NA_real_
      if (!is.finite(base)) next
      shiny::updateNumericInput(session, paste0("drv_occ_", id), value = max(0, round(base - 5, 1)))
    }
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$scn_hire, {
    p <- pack()
    open <- fpa_shiny_open_months(p$finance$pnl, p$finance$period_status)
    vol <- fpa_shiny_volumes(p$config, p$paths)
    for (per in open) {
      id <- gsub("-", "_", per)
      hit <- if (!is.null(vol)) which(as.character(vol$periode) == per) else integer()
      base <- if (length(hit)) suppressWarnings(as.numeric(vol$effectif[[hit[[1]]]])) else NA_real_
      if (!is.finite(base)) next
      shiny::updateNumericInput(session, paste0("drv_head_", id), value = round(base + 1, 1))
    }
  }, ignoreInit = TRUE)

  output$mgmt_report <- shiny::downloadHandler(
    filename = function() paste0("rapport-", format(Sys.Date(), "%Y-%m"), ".txt"),
    content = function(file) {
      p <- pack()
      cfg <- p$config
      company <- as.character((cfg$company %||% list())$name %||% "Societe")
      status <- p$finance$period_status
      closed <- ""
      if (!is.null(status) && nrow(status) && "status" %in% names(status)) {
        act <- status[as.character(status$status) == "actual", , drop = FALSE]
        if (nrow(act)) closed <- as.character(act$periode[[nrow(act)]])
      }
      brief <- tryCatch(synthese_brief(), error = function(e) NULL)
      rev <- ""
      margin <- ""
      if (!is.null(brief) && !is.null(brief$frame) && nrow(brief$frame)) {
        fr <- brief$frame
        actual <- if ("etat" %in% names(fr)) fr$etat != "prévision" else rep(TRUE, nrow(fr))
        if ("REV" %in% names(fr)) rev <- format(round(sum(fr$REV[actual], na.rm = TRUE)), big.mark = " ", scientific = FALSE, trim = TRUE)
        if (all(c("OI", "REV") %in% names(fr)) && sum(fr$REV[actual], na.rm = TRUE) != 0) {
          margin <- formatC(100 * sum(fr$OI[actual], na.rm = TRUE) / sum(fr$REV[actual], na.rm = TRUE), format = "f", digits = 1, decimal.mark = ",")
        }
      }
      eur <- function(x) format(round(x), big.mark = " ", scientific = FALSE, trim = TRUE)
      cash <- p$finance$cash
      cash_txt <- if (!is.null(cash) && nrow(cash) && "cash_close" %in% names(cash)) {
        eur(cash$cash_close[[nrow(cash)]])
      } else {
        ""
      }
      band <- tryCatch(fpa_live_oi_band_sentence(pnl_view(), status, budget_view()), error = function(e) "")
      cash_band <- ""
      view <- tryCatch(pnl_view(), error = function(e) NULL)
      if (!is.null(view) && isTRUE(view$ready) && length(view$open)) {
        oi_of <- function(df) {
          if (is.null(df) || !nrow(df) || !"OI" %in% names(df)) return(NA_real_)
          sum(df$OI[as.character(df$periode) %in% view$open], na.rm = TRUE)
        }
        oi_base <- oi_of(view$base)
        oi_low <- oi_of(view$low)
        oi_high <- oi_of(view$high)
        if (all(is.finite(c(oi_base, oi_low, oi_high)))) {
          band <- fpa_screen("scen_band_nobudget", eur(oi_base), eur(oi_low), eur(oi_high))
        }
        last_cash <- function(df) {
          if (is.null(df) || !nrow(df) || !"cash_close" %in% names(df)) return(NA_real_)
          suppressWarnings(as.numeric(df$cash_close[[nrow(df)]]))
        }
        lo <- last_cash(view$cash_low)
        mid <- last_cash(view$cash)
        hi <- last_cash(view$cash_high)
        if (all(is.finite(c(lo, mid, hi)))) {
          cash_band <- fpa_screen("scen_cash_trio", eur(lo), eur(mid), eur(hi))
        }
      }
      var_rev <- tryCatch(fpa_variance_headline(p$finance$variance, "REV"), error = function(e) "")
      var_oi <- tryCatch(fpa_variance_headline(p$finance$variance, "OI"), error = function(e) "")
      vol <- tryCatch(fpa_shiny_volumes(cfg, p$paths), error = function(e) NULL)
      open <- tryCatch(fpa_shiny_open_months(p$finance$pnl, status), error = function(e) character())
      assum <- character()
      if (!is.null(vol) && length(open)) {
        for (per in open) {
          hit <- which(as.character(vol$periode) == per)
          if (!length(hit)) next
          row <- vol[hit[[1]], , drop = FALSE]
          occ <- suppressWarnings(as.numeric(row$taux_utilisation[[1]]))
          rate <- suppressWarnings(as.numeric(row$tarif[[1]]))
          head_n <- suppressWarnings(as.numeric(row$effectif[[1]]))
          assum <- c(assum, paste(
            per,
            if (is.finite(occ)) paste0("occupation ", formatC(100 * occ, format = "f", digits = 1, decimal.mark = ","), " %") else "",
            if (is.finite(rate)) paste0("tarif ", eur(rate), " EUR") else "",
            if (is.finite(head_n)) paste0("effectif ", formatC(head_n, format = "f", digits = 1, decimal.mark = ",")) else ""
          ))
        }
      }
      sc <- p$finance$scenarios
      if (!nzchar(cash_band) && !is.null(sc) && nrow(sc) && all(c("case", "cash_close") %in% names(sc))) {
        last_of <- function(case_id) {
          sub <- sc[as.character(sc$case) == case_id, , drop = FALSE]
          if (!nrow(sub)) return(NA_real_)
          suppressWarnings(as.numeric(sub$cash_close[[nrow(sub)]]))
        }
        lo <- last_of("low")
        mid <- last_of("base")
        hi <- last_of("high")
        if (all(is.finite(c(lo, mid, hi)))) {
          cash_band <- fpa_screen("scen_cash_trio", eur(lo), eur(mid), eur(hi))
        }
      }
      n_series <- if (!is.null(p$grades)) nrow(p$grades) else 0L
      saved <- length(fpa_shiny_saved_ids(fpa_shiny_confirm_read(p$config_path %||% "")))
      n_fix <- 0L
      counts <- list(act = 0L, watch = 0L)
      scan <- tryCatch({
        hist <- fpa_line_history(cfg, p$paths)
        map <- fpa_line_map(cfg, "pnl")
        fpa_anomaly_scan(p$finance$bs, p$finance$pnl, p$finance$cash, vol, hist, map, fpa_anomaly_focus_periods(status))
      }, error = function(e) NULL)
      if (!is.null(scan) && nrow(scan)) counts <- fpa_anomaly_counts(scan)
      n_fix <- as.integer(counts$act %||% 0L) + as.integer(counts$watch %||% 0L)
      lines <- c(
        "Rapport de gestion",
        company,
        if (nzchar(closed)) paste("Mois clos", closed) else fpa_screen("loc_closed_not_set"),
        paste(fpa_screen("loc_prepared_on"), format(Sys.time(), "%Y-%m-%d %H:%M")),
        "",
        "Réalisé",
        if (nzchar(rev)) paste("Chiffre d'affaires", rev, "EUR") else fpa_screen("loc_rev_not_calc"),
        if (nzchar(margin)) paste("Marge d'exploitation", paste0(margin, " %")) else fpa_screen("loc_margin_not_calc"),
        if (nzchar(cash_txt)) paste(fpa_screen("loc_cash_last_bridge"), cash_txt, "EUR") else fpa_screen("loc_cash_not_calc"),
        "",
        "Prévision",
        if (nzchar(band)) band else fpa_screen("scen_band_missing"),
        if (nzchar(cash_band)) cash_band else NULL,
        "",
        fpa_screen("loc_gap_to_budget"),
        if (nzchar(var_rev)) var_rev else fpa_screen("loc_rev_no_gap"),
        if (nzchar(var_oi)) var_oi else fpa_screen("loc_oi_no_gap"),
        "",
        fpa_screen("loc_open_assumptions"),
        if (length(assum)) assum else fpa_screen("loc_no_open_assumption"),
        "",
        fpa_screen("loc_decisions"),
        fpa_journal_report_lines(
          tryCatch(fpa_journal_read(p$paths), error = function(e) list()),
          p$finance$cash, p$finance$pnl, status
        ),
        "",
        fpa_screen("header_todo"),
        if (n_series > 0L && saved < n_series) paste("Enregistrer", n_series - saved, fpa_screen("loc_series_in_drivers")) else fpa_screen("loc_drivers_saved"),
        if (n_fix > 0L) paste(n_fix, fpa_screen("loc_points_anomalies")) else fpa_screen("home_clear"),
        "",
        fpa_screen("loc_doc_not_books"),
        fpa_screen("loc_amounts_stay")
      )
      lines <- lines[!vapply(lines, is.null, logical(1))]
      con <- file(file, open = "wb")
      writeBin(charToRaw(enc2utf8(paste(lines, collapse = "\n"))), con)
      close(con)
    }
  )

