  output$pnl_width_sum <- shiny::renderUI({
    p <- pack()
    ranges <- fpa_shiny_ranges(p$config)
    pnl <- p$finance$pnl
    if (!nrow(ranges) || is.null(pnl) || !nrow(pnl)) {
      return(shiny::tags$span(class = "fpa-fold-k", fpa_screen("pnl_width_title")))
    }
    months <- as.character(pnl$periode)
    open <- fpa_shiny_open_months(pnl, p$finance$period_status)
    lows <- numeric()
    highs <- numeric()
    locked_n <- 0L
    for (per in months) {
      if (fpa_shiny_month_is_locked(per, open, input)) locked_n <- locked_n + 1L
      w <- fpa_shiny_widths_for(ranges, per, input)
      lows <- c(lows, w$low_pct)
      highs <- c(highs, w$high_pct)
    }
    pct <- function(x) {
      x <- suppressWarnings(as.numeric(x))
      x <- x[is.finite(x)]
      if (!length(x)) return("–")
      if (length(unique(round(x, 1))) > 1L) return(NA_character_)
      v <- x[[1]]
      if (abs(v - round(v)) < 0.05) return(format(round(v), trim = TRUE, scientific = FALSE))
      formatC(v, format = "f", digits = 1, decimal.mark = ",")
    }
    lo <- pct(lows)
    hi <- pct(highs)
    fact <- if (is.na(lo) || is.na(hi)) {
      fpa_screen("pnl_width_sum_mix", locked_n)
    } else {
      fpa_screen("pnl_width_sum", lo, hi, locked_n)
    }
    shiny::tagList(
      shiny::tags$span(class = "fpa-fold-k", fpa_screen("pnl_width_title")),
      shiny::tags$span(class = "fpa-fold-fact", fact)
    )
  })

  output$pnl_grid_sum <- shiny::renderUI({
    p <- pack()
    pnl <- p$finance$pnl
    if (is.null(pnl) || !nrow(pnl)) {
      return(shiny::tags$span(class = "fpa-fold-k", fpa_screen("pnl_fold_grid_title")))
    }
    pers <- as.character(pnl$periode)
    span <- as.character(input$pnl_span %||% "12")
    start <- as.character(input$pnl_start %||% pers[max(1L, length(pers) - 11L)])
    span_lab <- if (identical(span, "all")) "tout l'historique" else paste(span, "mois")
    v <- pnl_view()
    banked <- ""
    if (isTRUE(v$ready) && length(v$open) && nrow(v$pnl)) {
      year <- substr(v$open[[1]], 1, 4)
      bk <- as.character(v$pnl$periode[startsWith(v$pnl$periode, year) & !v$pnl$periode %in% v$open])
      if (length(bk)) {
        eur <- function(x) format(round(x), big.mark = " ", scientific = FALSE, trim = TRUE)
        sum_line <- function(line) sum(suppressWarnings(as.numeric(v$pnl[[line]][v$pnl$periode %in% bk])), na.rm = TRUE)
        banked <- fpa_screen("pnl_banked", bk[[1]], bk[[length(bk)]], eur(sum_line("REV")), eur(sum_line("OI")))
      }
    }
    fact <- fpa_screen("pnl_fold_grid", span_lab, start)
    if (nzchar(banked)) fact <- paste(fact, banked)
    shiny::tagList(
      shiny::tags$span(class = "fpa-fold-k", fpa_screen("pnl_fold_grid_title")),
      shiny::tags$span(class = "fpa-fold-fact", fact)
    )
  })

  output$pnl_ranges <- shiny::renderUI({
    p <- pack()
    ranges <- fpa_shiny_ranges(p$config)
    pnl <- p$finance$pnl
    if (!nrow(ranges) || is.null(pnl) || !nrow(pnl)) return(NULL)
    months <- as.character(pnl$periode)
    open <- fpa_shiny_open_months(pnl, p$finance$period_status)
    num <- function(id, value) {
      shiny::numericInput(id, NULL, value = value, min = 0, max = 90, step = 1, width = "36px")
    }
    head_style <- "background:#1f4e5f;color:#fff;font-size:11px;font-weight:600;padding:4px 2px;text-align:center;"
    closed <- setdiff(months, open)
    cell <- function(sign_class, sign, id, value) {
      shiny::tags$div(
        class = sign_class,
        shiny::tags$span(class = "rng-tag", if (identical(sign_class, "rng-lo")) fpa_screen("scen_bas") else fpa_screen("scen_haut")),
        shiny::tags$span(
          class = "rng-line",
          shiny::tags$span(class = "rng-sign", sign),
          num(id, value),
          shiny::tags$span(class = "rng-unit", "%")
        )
      )
    }
    month_lab <- function(per) paste(fpa_shiny_month_short(per), substr(per, 1L, 4L))
    month_choices <- stats::setNames(months, vapply(months, month_lab, character(1)))
    from_def <- if (length(open)) open[[1]] else months[[1]]
    to_def <- months[[length(months)]]
    jump <- function(target, key, open_it = FALSE) {
      js <- paste0(
        "var el = document.getElementById('", target, "'); if (el) {",
        if (open_it) " el.open = true;" else "",
        " el.scrollIntoView({behavior:'smooth', block:'start'}); }"
      )
      shiny::tags$button(type = "button", class = "fpa-rng-jump", onclick = js, fpa_screen(key))
    }
