        .fpa-rng-batch select, .fpa-rng-batch input[type=number] {
          height:32px; border:1px solid #1f4e5f; border-radius:8px; padding:2px 8px; color:#0f2f3a; font-size:13px;
        }
        .fpa-rng-batch input[type=number] { width:80px; font-variant-numeric:tabular-nums; }
        .fpa-rng-batch .control-label { font-size:12px; font-weight:700; color:#1f4e5f; margin:0 0 4px; }
        .fpa-rng-rows { grid-column:1 / -1; }
        .fpa-rng-rows .shiny-options-group { display:flex; flex-wrap:wrap; gap:6px; }
        .fpa-rng-rows .checkbox-inline { margin:0 !important; padding:0; }
        .fpa-rng-rows .checkbox-inline label, .fpa-rng-rows label.checkbox-inline {
          display:inline-flex; align-items:center; gap:6px; border:1px solid #1f4e5f; border-radius:8px;
          padding:3px 10px; font-size:13px; font-weight:600; color:#1f4e5f; background:#fff; cursor:pointer;
        }
        .fpa-rng-rows label.checkbox-inline:has(input:checked) { background:#1f4e5f; color:#fff; }
        .fpa-rng-rows input { accent-color:#1f4e5f; margin:0; position:static; }
        .fpa-rng-tools { grid-column:1 / -1; display:flex; flex-wrap:wrap; gap:8px; align-items:center; }
        .fpa-rng-side .shiny-options-group {
          display:inline-flex; border:1px solid #1f4e5f; border-radius:8px; overflow:hidden; background:#fff;
        }
        .fpa-rng-side label.radio-inline {
