        }
        .fpa-rng-side input { position:absolute; opacity:0; inset:0; width:100%; height:100%; margin:0; cursor:pointer; }
        .fpa-rng-side label.radio-inline:has(input:checked) { background:#1f4e5f; color:#fff; }
        .fpa-rng-go { background:#1f4e5f !important; color:#fff !important; border:0 !important; border-radius:8px !important; font-weight:700; }
      ")),
      shiny::tags$div(
        class = "fpa-rng-nav",
        jump("rng-sec-batch", "rng_nav_batch"),
        jump("rng-sec-table", "rng_nav_table"),
        if (length(closed)) jump("rng-sec-closed", "rng_nav_closed", open_it = TRUE),
        shiny::tags$button(
          type = "button",
