        )
      ),
      shiny::tags$p(class = "fpa-width-lead", fpa_screen("pnl_width_lead")),
      shiny::tags$div(
        id = "rng-sec-batch", class = "fpa-rng-sec",
        shiny::tags$h5(fpa_screen("rng_nav_batch")),
        shiny::tags$p(class = "fpa-width-lead", fpa_screen("rng_batch_lead")),
        shiny::tags$div(
          class = "fpa-rng-batch",
          shiny::selectInput("rng_batch_from", fpa_screen("rng_batch_from"), choices = month_choices, selected = from_def, selectize = FALSE),
          shiny::selectInput("rng_batch_to", fpa_screen("rng_batch_to"), choices = month_choices, selected = to_def, selectize = FALSE),
          shiny::div(
