          .fpa-rng col.rng-c-name { width:132px; }
          .fpa-rng col.rng-c-num { width:80px; }
          .fpa-rng td, .fpa-rng th { border-bottom:1px solid #e6edef; vertical-align:middle; padding:4px 3px; text-align:center; }
          .fpa-rng .rng-name {
            position:sticky; left:0; z-index:1; text-align:left; padding:4px 8px;
            font-weight:600; color:#1f4e5f; background:#fff; line-height:1.2;
          }
          .fpa-rng tbody tr:nth-child(even) .rng-name { background:#f6f9fa; }
          .fpa-rng tbody tr:nth-child(even) td { background:#f6f9fa; }
          .fpa-rng .rng-month { white-space:nowrap; }
          .fpa-rng .rng-stack { display:flex; flex-direction:column; gap:3px; align-items:center; }
          .fpa-rng .rng-hi, .fpa-rng .rng-lo {
            display:flex; flex-direction:column; align-items:center; gap:1px;
            font-size:11px; font-weight:700; font-variant-numeric:tabular-nums;
          }
          .fpa-rng .rng-hi { color:#1f4e5f; }
          .fpa-rng .rng-lo { color:#8c3a3a; }
          .fpa-rng .rng-tag { font-size:10px; line-height:1.1; }
          .fpa-rng .rng-line { display:flex; align-items:center; gap:1px; white-space:nowrap; }
          .fpa-rng .rng-sign, .fpa-rng .rng-unit { width:10px; text-align:center; }
          .fpa-rng .form-group, .fpa-rng .shiny-input-container { margin:0; width:36px !important; min-width:0; }
          .fpa-rng input[type=number] {
            width:36px !important; box-sizing:border-box; text-align:center;
            font-variant-numeric:tabular-nums; padding:2px 0; height:22px; font-size:12px;
            -moz-appearance:textfield;
          }
          .fpa-rng input[type=number]::-webkit-outer-spin-button,
          .fpa-rng input[type=number]::-webkit-inner-spin-button {
            -webkit-appearance:none; margin:0;
          }
          .fpa-rng .rng-lock { display:flex; justify-content:center; }
          .fpa-rng .rng-lock .shiny-input-container { width:auto !important; }
          .fpa-rng .rng-lock .checkbox { margin:0; min-height:0; }
          .fpa-rng .rng-lock label { margin:0; padding:0; font-size:0; display:flex; justify-content:center; }
          .fpa-rng .rng-lock span { display:none; }
          .fpa-rng .rng-lock input { width:14px; height:14px; margin:0; }
          .fpa-rng .is-locked { opacity:0.4; }
        ")),
        shiny::tags$table(
          shiny::tags$colgroup(
            shiny::tags$col(class = "rng-c-name"),
            lapply(months, function(per) shiny::tags$col(class = "rng-c-num"))
          ),
          shiny::tags$thead(
            shiny::tags$tr(
              shiny::tags$th(style = paste0(head_style, "text-align:left;position:sticky;left:0;z-index:2;"), "Entrée"),
              lapply(months, function(per) {
                key <- gsub("-", "_", per)
                shiny::tags$th(
                  style = head_style,
                  `data-rng-col` = key,
                  shiny::tags$div(class = "rng-month", fpa_shiny_month_short(per)),
                  shiny::tags$div(
                    class = "rng-lock",
                    title = fpa_screen("pnl_range_lock"),
                    shiny::checkboxInput(
                      paste0("rng_lock_", key),
                      fpa_screen("pnl_range_lock"),
                      value = !(per %in% open)
                    )
                  )
                )
              })
            )
          ),
          shiny::tags$tbody(lapply(seq_len(nrow(ranges)), function(i) {
            shiny::tags$tr(
              shiny::tags$td(class = "rng-name", ranges$label[[i]]),
              lapply(months, function(per) {
                key <- gsub("-", "_", per)
                base <- paste0("rng_", fpa_shiny_range_id(ranges$id[[i]]), "_", key)
                shiny::tags$td(
                  class = "rng-cell",
                  `data-rng-col` = key,
                  shiny::tags$div(
                    class = "rng-stack",
                    cell("rng-hi", "+", paste0(base, "_high"), fpa_shiny_cell_pct(ranges, i, per, "high")),
                    cell("rng-lo", "\u2212", paste0(base, "_low"), fpa_shiny_cell_pct(ranges, i, per, "low"))
                  )
                )
              })
            )
          }))
        ),
        shiny::tags$script(HTML("
          function fpaRngPaint() {
            document.querySelectorAll('.fpa-rng .rng-lock input').forEach(function(box) {
              var th = box.closest('th');
              var col = th ? th.getAttribute('data-rng-col') : '';
              document.querySelectorAll('[data-rng-col=\"' + col + '\"]').forEach(function(n) {
                n.classList.toggle('is-locked', box.checked);
              });
            });
          }
          document.addEventListener('change', function(ev) {
            if (ev.target && ev.target.closest && ev.target.closest('.fpa-rng .rng-lock')) fpaRngPaint();
          });
          setTimeout(fpaRngPaint, 0);
        "))
      )
      ),
      if (length(closed)) shiny::tags$details(
        id = "rng-sec-closed", class = "fpa-rng-sec",
        shiny::tags$summary(
          fpa_screen("rng_nav_closed"),
          shiny::tags$span(class = "fpa-rng-fact", fpa_screen("rng_closed_fact", month_lab(closed[[1]]), month_lab(closed[[length(closed)]])))
        ),
        shiny::tags$div(
          class = "fpa-partner-row",
          lapply(closed, function(per) {
            fpa_shiny_case_input(paste0("case_", gsub("-", "_", per)), fpa_shiny_month_short(per))
          })
        )
      )
    )
  })

  shiny::observeEvent(input$rng_batch_all, {
    ranges <- fpa_shiny_ranges(pack()$config)
    shiny::updateCheckboxGroupInput(session, "rng_batch_rows", selected = as.character(ranges$id))
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$rng_batch_none, {
    shiny::updateCheckboxGroupInput(session, "rng_batch_rows", selected = character(0))
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$rng_batch_go, {
    p <- pack()
    ranges <- fpa_shiny_ranges(p$config)
    pnl <- p$finance$pnl
    if (!nrow(ranges) || is.null(pnl) || !nrow(pnl)) return()
    months <- as.character(pnl$periode)
    open <- fpa_shiny_open_months(pnl, p$finance$period_status)
    a <- as.character(input$rng_batch_from %||% "")
    b <- as.character(input$rng_batch_to %||% "")
    if (!a %in% months) a <- months[[1]]
    if (!b %in% months) b <- months[[length(months)]]
    if (a > b) { tmp <- a; a <- b; b <- tmp }
    span <- months[months >= a & months <= b]
    rows <- intersect(as.character(input$rng_batch_rows %||% character(0)), as.character(ranges$id))
    side <- as.character(input$rng_batch_side %||% "both")
    sides <- switch(side, low = "low", high = "high", c("low", "high"))
    pct <- suppressWarnings(as.numeric(input$rng_batch_pct))
    if (!length(pct) || !is.finite(pct)) pct <- 10
    pct <- min(90, max(0, pct))
    live <- span[!vapply(span, function(per) fpa_shiny_month_is_locked(per, open, input), logical(1))]
    skipped <- length(span) - length(live)
    n <- 0L
    for (per in live) {
      stem <- gsub("-", "_", per)
      for (id in rows) {
        base <- paste0("rng_", fpa_shiny_range_id(id), "_", stem)
        for (s in sides) {
          shiny::updateNumericInput(session, paste0(base, "_", s), value = pct)
          n <- n + 1L
        }
      }
    }
    lab <- function(per) paste(fpa_shiny_month_short(per), substr(per, 1L, 4L))
    pct_txt <- if (abs(pct - round(pct)) < 1e-9) format(round(pct), trim = TRUE) else formatC(pct, format = "f", digits = 1)
    msg <- if (n > 0L) fpa_screen("rng_batch_done", n, pct_txt, lab(a), lab(b)) else fpa_screen("rng_batch_none")
    if (skipped > 0L) msg <- paste(msg, fpa_screen("rng_batch_skip", skipped))
    shiny::showNotification(msg, type = if (n > 0L) "message" else "warning", duration = 6)
  }, ignoreInit = TRUE)

  output$pnl_band <- shiny::renderUI({
    v <- pnl_view()
    if (!nrow(v$pnl) || !length(v$open)) return(NULL)
    year <- substr(v$open[[1]], 1, 4)
    banked <- as.character(v$pnl$periode[startsWith(v$pnl$periode, year) & !v$pnl$periode %in% v$open])
    sum_line <- function(df, months, line) {
      if (!nrow(df) || !(line %in% names(df)) || !length(months)) return(NA_real_)
      sum(suppressWarnings(as.numeric(df[[line]][df$periode %in% months])), na.rm = TRUE)
    }
    bud <- fpa_scenario_budget_oi(v$budget)
    open_hit <- !is.null(bud) && any(as.character(bud$periode) %in% v$open)
    bud_oi <- if (open_hit) sum(bud$OI[as.character(bud$periode) %in% v$open], na.rm = TRUE) else NA_real_
    eur <- function(x) format(round(x), big.mark = " ", scientific = FALSE, trim = TRUE)
    phrase <- sub("\\.$", "", fpa_shiny_case_phrase(v$open, v$cases))
    band <- if (open_hit) {
      fpa_screen(
        "pnl_open_band", phrase,
        eur(sum_line(v$pnl, v$open, "REV")),
        eur(sum_line(v$pnl, v$open, "OI")),
        eur(sum_line(v$low, v$open, "OI")),
        eur(sum_line(v$high, v$open, "OI")),
        eur(bud_oi)
      )
    } else {
      fpa_screen(
        "pnl_open_band_gap", phrase,
        eur(sum_line(v$pnl, v$open, "REV")),
        eur(sum_line(v$pnl, v$open, "OI")),
        eur(sum_line(v$low, v$open, "OI")),
        eur(sum_line(v$high, v$open, "OI"))
      )
    }
    shiny::tagList(
      if (length(banked)) shiny::tags$p(
        style = "margin:0 0 4px;line-height:1.4;",
        fpa_screen("pnl_banked", banked[[1]], banked[[length(banked)]], eur(sum_line(v$pnl, banked, "REV")), eur(sum_line(v$pnl, banked, "OI")))
      ),
      shiny::tags$p(
        style = "margin:0 0 8px;line-height:1.45;font-weight:600;color:#1f4e5f;",
        band
      ),
      fpa_shiny_flat_ui(v, pack()$config)
    )
  })

  output$pnl_year_picks <- shiny::renderUI({
    p <- pack()
    fin <- p$finance
    open <- fpa_shiny_open_months(fin$pnl, fin$period_status)
    if (!length(open) || is.null(fin$pnl) || !nrow(fin$pnl)) return(NULL)
    year <- substr(open[[1]], 1, 4)
    hist <- fpa_shiny_hist_rev(p$config, p$paths)
    years <- sort(unique(c(names(hist), year)))
    shiny::div(
      class = "fpa-years",
      lapply(years, function(y) {
        shiny::checkboxInput(paste0("pnl_year_", y), y, value = identical(y, year))
      }),
      shiny::checkboxInput("pnl_show_budget", fpa_screen("pnl_budget_toggle"), value = TRUE)
    )
  })

  output$pnl_season <- shiny::renderUI({
    p <- pack()
    bud <- p$finance$budget
    if (is.null(bud) || !nrow(bud)) return(NULL)
    if (!fpa_budget_season_on(p$config)) {
      return(shiny::tags$div(
        class = "fpa-season",
        shiny::tags$p(class = "fpa-season-title", fpa_screen("sea_title")),
        shiny::tags$p(fpa_screen("sea_off"))
      ))
    }
    mapped <- fpa_season_mapped(p$config, p$paths)
    byear <- max(substr(as.character(bud$periode), 1, 4))
    catalogue <- fpa_season_year_rows(mapped, byear, fpa_budget_season_lookback(p$config))
    saved <- fpa_season_keep_read(p$paths)
    shown <- catalogue[catalogue$complete, , drop = FALSE]
    totals <- if (nrow(shown)) {
      paste(vapply(seq_len(nrow(shown)), function(i) {
        fpa_screen("sea_total_one", shown$year[[i]], fpa_shiny_eur(shown$total[[i]]))
      }, character(1)), collapse = ". ")
    } else {
      ""
    }
    shiny::tags$div(
      class = "fpa-season",
      shiny::tags$p(class = "fpa-season-title", fpa_screen("sea_title")),
      shiny::tags$p(fpa_screen("sea_lead")),
      if (any(catalogue$complete)) shiny::tags$div(
        class = "fpa-years",
        lapply(which(catalogue$complete), function(i) {
          y <- catalogue$year[[i]]
          on <- if (is.null(saved)) TRUE else y %in% saved
          lab <- if (isTRUE(catalogue$apart[[i]])) fpa_screen("sea_apart", y) else y
          shiny::checkboxInput(paste0("season_keep_", y), lab, value = on)
        })
      ),
      if (any(!catalogue$complete)) shiny::tags$p(paste(vapply(which(!catalogue$complete), function(i) {
        fpa_screen("sea_short", catalogue$year[[i]], fpa_shiny_eur(catalogue$total[[i]]))
      }, character(1)), collapse = " ")),
      if (nzchar(totals)) shiny::tags$p(totals)
    )
  })

  output$pnl_season_note <- shiny::renderUI({
    b <- budget_view()
    info <- attr(b, "season")
    if (is.null(info) || !isTRUE(info$on)) return(NULL)
    fpa_shiny_season_note(b)
  })

  output$pnl_cone_note <- shiny::renderUI({
    today <- Sys.Date()
    month_end <- function(p) {
      d <- as.Date(paste0(p, "-01"))
      seq(d, by = "month", length.out = 2L)[[2]] - 1
    }
    end <- month_end(format(today, "%Y-%m"))
    v <- pnl_view()
    gap_ui <- NULL
    if (length(v$open)) {
      year <- substr(v$open[[1]], 1, 4)
      gap <- fpa_shiny_budget_gap(v$budget, year)
      if (isTRUE(gap$has_rows) && !isTRUE(gap$covers)) {
        src <- fpa_shiny_role_source(pack()$config, "budget")
        title <- if (!is.null(src)) as.character(src$source_name %||% "Budget") else "Budget"
        if (length(title) != 1L || !nzchar(title)) title <- "Budget"
        sid <- if (!is.null(src)) gsub("[^A-Za-z0-9_:.-]", "", as.character(src$source_id %||% "")) else ""
        gap_ui <- shiny::tags$div(
          style = "margin:0 0 10px;",
          shiny::tags$p(
            style = "margin:0 0 8px;line-height:1.45;color:#1a2b32;font-size:13px;",
            fpa_screen("pnl_cone_budget_gap", title, fpa_ym_fr(gap$last), year)
          ),
          if (nzchar(sid)) shiny::tags$button(
            type = "button",
            class = "fpa-map-btn fpa-map-btn-primary",
            onclick = sprintf("Shiny.setInputValue('raw_file','src:%s',{priority:'event'})", sid),
            fpa_screen("pnl_cone_open", title)
          )
        )
      }
    }
    shiny::tagList(
      shiny::tags$p(
        style = "margin:4px 0 10px;line-height:1.4;color:#3d4c54;font-size:13px;",
        fpa_screen("pnl_cone_dates", fpa_shiny_date_fr(today), fpa_shiny_date_fr(end))
      ),
      local({
        p <- pack()
        if (!isTRUE(p$ok)) return(NULL)
        cur <- tryCatch(fpa_manual_read(p$config), error = function(e) NULL)
        df <- if (is.null(cur)) NULL else fpa_manual_active(cur$data)
        if (is.null(df) || !nrow(df)) return(NULL)
        skip <- df[as.character(df$ligne) != "REV", , drop = FALSE]
        if (!nrow(skip)) return(NULL)
        fin <- p$finance$cash
        last_p <- if (!is.null(fin) && nrow(fin)) as.character(fin$periode[[nrow(fin)]]) else ""
        last_c <- if (!is.null(fin) && nrow(fin)) suppressWarnings(as.numeric(fin$cash_close[[nrow(fin)]])) else NA_real_
        bits <- vapply(seq_len(nrow(skip)), function(i) {
          sens <- if (identical(as.character(skip$sens[[i]]), "in")) fpa_screen("out_in") else fpa_screen("out_out")
          pair <- manual_pair()
          other <- if (is.null(pair)) NA_real_ else if (isTRUE(manual_show())) pair$without else pair$with
          key <- if (isTRUE(manual_show())) "man_cone_on" else "man_cone_off"
          fpa_screen(
            key,
            as.character(skip$libelle[[i]]),
            sens,
            fpa_shiny_eur(skip$montant[[i]]),
            last_p,
            fpa_shiny_eur(last_c),
            fpa_shiny_eur(other)
          )
        }, character(1))
        shiny::tags$p(
          style = "margin:0 0 10px;line-height:1.45;color:#1f4e5f;font-size:13px;",
          paste(bits, collapse = " ")
        )
      }),
      gap_ui
    )
  })

  if (FPA_HAS_PLOTLY) {
    fig_pnl_cone <- shiny::reactive({
      v <- pnl_view()
      if (is.null(v$base) || !nrow(v$base) || !length(v$open)) return(plotly::plotly_empty())
      today <- Sys.Date()
      year <- substr(v$open[[1]], 1, 4)
      months <- as.character(v$base$periode[startsWith(as.character(v$base$periode), year)])
      if (!length(months)) return(plotly::plotly_empty())
      month_end <- function(p) {
        d <- as.Date(paste0(p, "-01"))
        seq(d, by = "month", length.out = 2L)[[2]] - 1
      }
      ends <- as.Date(vapply(months, function(p) as.character(month_end(p)), character(1)))
      year_start <- as.Date(paste0(year, "-01-01"))
      year_end <- seq(year_start, by = "year", length.out = 2L)[[2]]
      grid_starts <- seq(year_start, by = "month", length.out = 12L)
      grid_next <- c(grid_starts[-1], year_end)
      grid_mids <- grid_starts + as.numeric(grid_next - grid_starts) / 2
      grid_bounds <- c(grid_starts, year_end)
      rev_of <- function(df) suppressWarnings(as.numeric(df$REV[match(months, df$periode)]))
      base_m <- rev_of(v$base)
      path_m <- rev_of(v$pnl)
      low_m <- rev_of(v$low)
      high_m <- rev_of(v$high)
      bud_m <- rep(NA_real_, length(months))
      if (!is.null(v$budget) && nrow(v$budget) && "functional_label" %in% names(v$budget)) {
        sl <- v$budget[as.character(v$budget$functional_label) == "REV", , drop = FALSE]
        bud_m <- suppressWarnings(as.numeric(sl$montant[match(months, as.character(sl$periode))]))
      }
      # Last month fully before today is banked. The current month splits at today.
      closed <- ends < today
      cur_i <- which(ends >= today)[1]
      ratio_lo <- 1
      ratio_hi <- 1
      open_i <- match(v$open, months)
      open_i <- open_i[!is.na(open_i)]
      if (length(open_i) && is.finite(base_m[open_i[1]]) && abs(base_m[open_i[1]]) > 1) {
        ratio_lo <- low_m[open_i[1]] / base_m[open_i[1]]
        ratio_hi <- high_m[open_i[1]] / base_m[open_i[1]]
      }
      cum_b <- 0
      cum_lo <- 0
      cum_hi <- 0
      cum_bud <- 0
      bank_x <- as.Date(character())
      bank_y <- numeric()
      fan_x <- as.Date(character())
      fan_c <- numeric()
      fan_lo <- numeric()
      fan_hi <- numeric()
      bud_x <- as.Date(character())
      bud_y <- numeric()
      for (i in seq_along(months)) {
        end_i <- ends[[i]]
        b <- if (is.finite(path_m[[i]])) path_m[[i]] else 0
        lo <- if (is.finite(low_m[[i]])) low_m[[i]] else b
        hi <- if (is.finite(high_m[[i]])) high_m[[i]] else b
        if (end_i < today) {
          cum_b <- cum_b + b
          cum_lo <- cum_b
          cum_hi <- cum_b
          bank_x <- c(bank_x, end_i)
          bank_y <- c(bank_y, cum_b)
        } else if (!is.na(cur_i) && i == cur_i && today < end_i) {
          start_i <- as.Date(paste0(months[[i]], "-01"))
          span <- as.numeric(end_i - start_i) + 1
          done <- max(0, as.numeric(today - start_i))
          u <- if (span > 0) (span - done) / span else 0
          banked_bit <- b * (1 - u)
          cum_b <- cum_b + banked_bit
          cum_lo <- cum_b
          cum_hi <- cum_b
          bank_x <- c(bank_x, today)
          bank_y <- c(bank_y, cum_b)
          fan_x <- c(fan_x, today)
          fan_c <- c(fan_c, cum_b)
          fan_lo <- c(fan_lo, cum_b)
          fan_hi <- c(fan_hi, cum_b)
          open_bit <- b * u
          cum_b <- cum_b + open_bit
          cum_lo <- cum_lo + open_bit * ratio_lo
          cum_hi <- cum_hi + open_bit * ratio_hi
          fan_x <- c(fan_x, end_i)
          fan_c <- c(fan_c, cum_b)
          fan_lo <- c(fan_lo, cum_lo)
          fan_hi <- c(fan_hi, cum_hi)
        } else {
          cum_b <- cum_b + b
          cum_lo <- cum_lo + lo
          cum_hi <- cum_hi + hi
          fan_x <- c(fan_x, end_i)
          fan_c <- c(fan_c, cum_b)
          fan_lo <- c(fan_lo, cum_lo)
          fan_hi <- c(fan_hi, cum_hi)
        }
        if (is.finite(bud_m[[i]])) {
          cum_bud <- cum_bud + bud_m[[i]]
          bud_x <- c(bud_x, end_i)
          bud_y <- c(bud_y, cum_bud)
        }
      }
      if (length(bank_x) && bank_x[[1]] > year_start && identical(format(bank_x[[1]], "%m"), "01")) {
        bank_x <- c(year_start, bank_x)
        bank_y <- c(0, bank_y)
      }
      if (length(bud_x) && bud_x[[1]] > year_start && identical(format(bud_x[[1]], "%m"), "01")) {
        bud_x <- c(year_start, bud_x)
        bud_y <- c(0, bud_y)
      }
      if (!length(fan_x)) {
        fan_x <- bank_x
        fan_c <- bank_y
        fan_lo <- bank_y
        fan_hi <- bank_y
      }
      mid_lo <- fan_c - 0.5 * (fan_c - fan_lo)
      mid_hi <- fan_c + 0.5 * (fan_hi - fan_c)
      eur <- function(x) format(round(x), big.mark = " ", scientific = FALSE, trim = TRUE)
      hover <- paste0(
        "<b>", format(fan_x, "%d %b %Y"), "</b><br>",
        vapply(seq_along(fan_c), function(i) {
          paste(
            fpa_screen("cone_hover_line", eur(fan_c[[i]])),
            fpa_screen("cone_hover_band", eur(fan_lo[[i]]), eur(fan_hi[[i]])),
            sep = "<br>"
          )
        }, character(1))
      )
      chart <- plotly::plot_ly()
      show_year <- fpa_shiny_year_on(year, year, input)
      if (show_year) {
        chart <- plotly::add_ribbons(
          chart, x = fan_x, ymin = fan_lo, ymax = fan_hi,
          name = fpa_screen("cone_legend_band"), line = list(width = 0),
          fillcolor = "rgba(31,78,95,0.12)", hoverinfo = "skip"
        )
        chart <- plotly::add_ribbons(
          chart, x = fan_x, ymin = mid_lo, ymax = mid_hi,
          name = fpa_screen("cone_legend_mid"), line = list(width = 0),
          fillcolor = "rgba(31,78,95,0.28)", hoverinfo = "skip"
        )
        chart <- plotly::add_trace(
          chart, x = fan_x, y = fan_c, type = "scatter", mode = "lines",
          name = fpa_screen("cone_legend_line", year), line = list(color = "#1f4e5f", width = 2, dash = "dot"),
          text = hover, hoverinfo = "text"
        )
        if (length(bank_x)) {
          chart <- plotly::add_trace(
            chart, x = bank_x, y = bank_y, type = "scatter", mode = "lines",
            name = paste("Réalisé", year), line = list(color = "#16302b", width = 3),
            hoverinfo = "x+y"
          )
        }
      }
      show_budget <- input[["pnl_show_budget"]]
      if (is.null(show_budget)) show_budget <- TRUE
      if (isTRUE(show_budget) && length(bud_x) && any(is.finite(bud_y))) {
        chart <- plotly::add_trace(
          chart, x = bud_x, y = bud_y, type = "scatter", mode = "lines",
          name = "Budget voté", line = list(color = "#e67e22", width = 2, dash = "dash")
        )
      }
      hist_years <- fpa_shiny_hist_rev(pack()$config, pack()$paths)
      prior <- sort(setdiff(names(hist_years), year))
      for (k in seq_along(prior)) {
        y <- prior[[k]]
        if (!fpa_shiny_year_on(y, year, input)) next
        monthly <- hist_years[[y]]
        x <- as.Date(character())
        yv <- numeric()
        cum <- 0
        started <- FALSE
        first_m <- ""
        for (i in seq_along(months)) {
          key <- sprintf("%s-%s", y, substr(months[[i]], 6, 7))
          val <- unname(monthly[key])
          if (!length(val) || is.na(val) || !is.finite(val)) next
          if (!started) first_m <- substr(key, 6, 7)
          started <- TRUE
          cum <- cum + val
          x <- c(x, ends[[i]])
          yv <- c(yv, cum)
        }
        if (identical(first_m, "01") && length(x) && x[[1]] > year_start) {
          x <- c(year_start, x)
          yv <- c(0, yv)
        }
        if (length(x) < 2L) next
        label <- y
        if (!identical(first_m, "01")) label <- paste0(y, " (dès ", fpa_chain_month_fr(as.integer(first_m)), ")")
        chart <- plotly::add_trace(
          chart, x = x, y = yv, type = "scatter", mode = "lines",
          name = label,
          line = list(color = fpa_shiny_year_color(y), width = 2.4),
          hoverinfo = "x+y"
        )
      }
      if (isTRUE(manual_show())) {
        cur <- tryCatch(fpa_manual_read(pack()$config), error = function(e) NULL)
        dfm <- if (is.null(cur)) NULL else fpa_manual_active(cur$data)
        if (!is.null(dfm) && nrow(dfm)) {
          xs <- as.Date(character())
          ys <- numeric()
          tips <- character()
          syms <- character()
          for (i in seq_len(nrow(dfm))) {
            d <- fpa_manual_parse_date(dfm$date_effet[[i]])
            if (!is.finite(d) || format(d, "%Y") != year) next
            per <- format(d, "%Y-%m")
            me <- month_end(per)
            j <- if (length(fan_x)) match(as.character(me), as.character(fan_x)) else NA_integer_
            yv <- if (!is.na(j)) fan_c[[j]] else NA_real_
            if (!is.finite(yv)) next
            ligne <- as.character(dfm$ligne[[i]] %||% "")
            effect <- if (identical(as.character(dfm$nature[[i]]), "nouveau") && identical(ligne, "REV")) {
              fpa_screen("man_mark_rev")
            } else {
              fpa_screen("man_mark_not_rev", if (nzchar(ligne)) ligne else as.character(dfm$nature[[i]]))
            }
            sens <- if (identical(as.character(dfm$sens[[i]]), "in")) fpa_screen("out_in") else fpa_screen("out_out")
            nat <- if (identical(as.character(dfm$nature[[i]]), "decalage")) fpa_screen("man_decalage") else fpa_screen("man_nouveau")
            xs <- c(xs, d)
            ys <- c(ys, yv)
            tips <- c(tips, fpa_screen(
              "man_mark_hover", nat, as.character(dfm$libelle[[i]]),
              fpa_shiny_eur(dfm$montant[[i]]), as.character(d), paste(sens, effect)
            ))
            syms <- c(syms, if (identical(as.character(dfm$sens[[i]]), "in")) "triangle-up" else "triangle-down")
          }
          if (length(xs)) {
            chart <- plotly::add_markers(
              chart, x = xs, y = ys, name = fpa_screen("man_legend"),
              inherit = FALSE,
              marker = list(symbol = syms, size = 13, color = "#3b6fb6", line = list(color = "#fff", width = 1)),
              hovertext = tips, hoverinfo = "text",
              customdata = rep("manual:ledger", length(xs))
            )
          }
        }
      }
      month_end_today <- month_end(format(today, "%Y-%m"))
      shapes <- lapply(grid_bounds, function(b) {
        list(
          type = "line", x0 = b, x1 = b, y0 = 0, y1 = 1, yref = "paper",
          line = list(color = "#e6edef", width = 1), layer = "below"
        )
      })
      shapes <- c(shapes, list(
        list(
          type = "rect", x0 = today, x1 = month_end_today, y0 = 0, y1 = 1, yref = "paper",
          fillcolor = "rgba(31,78,95,0.11)", line = list(width = 0), layer = "below"
        ),
        list(
          type = "line", x0 = today, x1 = today, y0 = 0, y1 = 1, yref = "paper",
          line = list(color = "#7f8c8d", width = 1.5, dash = "dot")
        ),
        list(
          type = "line", x0 = month_end_today, x1 = month_end_today, y0 = 0, y1 = 1, yref = "paper",
          line = list(color = "#1a2b32", width = 1.6, dash = "dot")
        )
      ))
      short_d <- function(d) paste(as.integer(format(d, "%d")), fpa_shiny_month_short(format(d, "%Y-%m")))
      ann <- list(
        list(
          x = today, y = 0.90, yref = "paper",
          xanchor = "right", yanchor = "top",
          text = fpa_screen("pnl_cone_today", short_d(today)),
          showarrow = FALSE, font = list(size = 11, color = "#7f8c8d")
        ),
        list(
          x = month_end_today, y = 0.97, yref = "paper",
          xanchor = "left", yanchor = "top",
          text = paste0("<b>", fpa_screen("pnl_cone_eom", short_d(month_end_today)), "</b>"),
          showarrow = FALSE, font = list(size = 11, color = "#1a2b32")
        )
      )
      ticks <- vapply(format(grid_starts, "%Y-%m"), fpa_shiny_month_short, character(1))
      chart <- plotly::layout(
        chart,
        uirevision = "pnl-cone",
        shapes = shapes,
        annotations = ann,
        hovermode = "x",
        yaxis = list(
          title = fpa_screen("loc_rev_cum_fy"), gridcolor = "#e6edef", tickformat = ",d",
          uirevision = "pnl-cone"
        ),
        xaxis = list(
          title = "", type = "date",
          range = c(as.character(year_start), as.character(year_end)),
          autorange = FALSE,
          uirevision = "pnl-cone",
          tickmode = "array",
          tickvals = as.character(grid_mids),
          ticktext = ticks,
          showgrid = FALSE,
          rangeslider = list(
            visible = TRUE, thickness = 0.08,
            bgcolor = "#f4f8f8", bordercolor = "#d6e1e5", borderwidth = 1
          )
        ),
        legend = list(orientation = "h", y = -0.32, yanchor = "top", x = 0),
        margin = list(t = 30, b = 36, r = 20)
      )
      chart <- plotly::config(chart, displaylogo = FALSE, displayModeBar = TRUE)
      htmlwidgets::onRender(chart, "
        function(el) {
          function fit() {
            var w = el.parentElement ? el.parentElement.clientWidth : 0;
            if (w > 80 && window.Plotly) Plotly.relayout(el, {width: w, height: 480});
          }
          function inWindow(t, x0, x1) {
            if (!isFinite(x0) || !isFinite(x1)) return true;
            return t >= x0 && t <= x1;
          }
          function collect(tr, x0, x1) {
            if (!tr || tr.visible === false || tr.visible === 'legendonly') return [];
            var raw = tr.x || [];
            var xs = [];
            for (var i = 0; i < raw.length; i++) {
              var t = new Date(raw[i]).getTime();
              xs.push(isFinite(t) ? t : NaN);
            }
            var bags = [];
            if (tr.y) bags.push(tr.y);
            if (tr.ymin) bags.push(tr.ymin);
            if (tr.ymax) bags.push(tr.ymax);
            var ys = [];
            bags.forEach(function(bag) {
              if (!bag) return;
              if (xs.length && bag.length === xs.length) {
                for (var i = 0; i < xs.length; i++) {
                  if (!inWindow(xs[i], x0, x1)) continue;
                  var v = +bag[i];
                  if (isFinite(v)) ys.push(v);
                }
              } else {
                for (var j = 0; j < bag.length; j++) {
                  var w = +bag[j];
                  if (isFinite(w)) ys.push(w);
                }
              }
            });
            return ys;
          }
          var fitting = false;
          function fitY(all) {
            if (el._fpaFitting || !window.Plotly || !el.layout) return;
            var xr = (el.layout.xaxis && el.layout.xaxis.range) || [];
            var x0 = !all && xr.length === 2 ? new Date(xr[0]).getTime() : NaN;
            var x1 = !all && xr.length === 2 ? new Date(xr[1]).getTime() : NaN;
            var ys = [];
            (el.data || []).forEach(function(tr) { ys = ys.concat(collect(tr, x0, x1)); });
            if (!ys.length) return;
            var lo = Math.min.apply(null, ys);
            var hi = Math.max.apply(null, ys);
            var span = hi - lo;
            var pad = span > 0 ? span * 0.08 : Math.max(Math.abs(hi) * 0.04, 1);
            var bottom = lo - pad;
            var top = hi + pad;
            if (lo >= 0 && bottom < 0) bottom = 0;
            el._fpaFitting = true;
            Plotly.relayout(el, {
              'yaxis.range': [bottom, top],
              'yaxis.autorange': false,
              'yaxis.rangemode': 'normal'
            }).then(function() { el._fpaFitting = false; }, function() { el._fpaFitting = false; });
          }
          if (el._fpaConeZoom) {
            try { el.removeListener('plotly_relayout', el._fpaConeZoom); } catch (e) {}
          }
          el._fpaConeZoom = function(ev) {
            if (!ev || el._fpaRestoring) return;
            if (ev['xaxis.autorange']) {
              window.fpaConeX = null;
              if (!el._fpaFitting) fitY(true);
              return;
            }
            var pair = ev['xaxis.range'];
            var a = ev['xaxis.range[0]'];
            var b = ev['xaxis.range[1]'];
            if (pair && pair.length === 2) { a = pair[0]; b = pair[1]; }
            if (a != null && b != null) window.fpaConeX = [a, b];
            if (el._fpaFitting) return;
            var keys = Object.keys(ev);
            var xchange = keys.some(function(k) { return k.indexOf('xaxis.range') === 0; });
            if (xchange) fitY(false);
          };
          el.on('plotly_relayout', el._fpaConeZoom);
          if (!el._fpaConeResize) {
            el._fpaConeResize = true;
            window.addEventListener('resize', fit);
          }
          fit();
          var saved = window.fpaConeX;
          if (saved && window.Plotly) {
            el._fpaRestoring = true;
            Plotly.relayout(el, {'xaxis.range': saved, 'xaxis.autorange': false}).then(function() {
              el._fpaRestoring = false;
              fitY(false);
            }, function() { el._fpaRestoring = false; });
          } else {
            fitY(false);
          }
        }
      ")
    })
    output$pnl_cone <- plotly::renderPlotly({
      fig <- fig_pnl_cone()
      if (is.null(fig)) return(plotly::plotly_empty())
      fig
    })
  }

  output$pnl_opfin_ctrls <- shiny::renderUI({
    cfg <- pack()$config
    if (!fpa_line_nature_has(cfg, "pnl")) return(NULL)
    fpa_shiny_opfin_controls("pnl")
  })

  output$pnl_grid <- shiny::renderUI({
    v <- pnl_view()
    cfg <- pack()$config
    nature <- fpa_line_nature(cfg, "pnl")
    show <- length(nature) > 0L && isTRUE(input$pnl_show_op_fin)
    scope <- if (length(nature) > 0L) as.character(input$pnl_op_fin_scope %||% "all") else "all"
    fpa_shiny_pnl_grid(
      v$pnl, v$long, v$status, input$pnl_span, input$pnl_start, input$pnl_mode,
      nature = nature, show_op_fin = show, scope = scope
    )
  })

  output$pnl_wf_one <- shiny::renderUI({
    pnl <- pack()$finance$pnl
    if (is.null(pnl) || !nrow(pnl)) return(NULL)
    pers <- as.character(pnl$periode)
    shiny::selectInput(
      "pnl_wf_period", fpa_screen("stmt_period"),
      choices = pers, selected = pers[[length(pers)]], selectize = FALSE
    )
  })

  pnl_wf_hist <- shiny::reactive({
    p <- pack()
    tryCatch(fpa_history_pnl(p$config, p$paths), error = function(e) NULL)
  })
  pnl_wf_book <- shiny::reactive({
    fpa_pnl_wf_book(pnl_view()$pnl, pnl_wf_hist())
  })
  pnl_wf_year_choices <- shiny::reactive({
    fpa_pnl_wf_years(fpa_pnl_wf_book(pack()$finance$pnl, pnl_wf_hist()))
  })

  fpa_shiny_wf_year_ui <- function(input_id) {
    years <- pnl_wf_year_choices()
    if (!length(years)) return(NULL)
    shiny::selectInput(
      input_id, fpa_screen("stmt_wf_year"),
      choices = years, selected = years[[length(years)]],
      selectize = FALSE, width = "168px"
    )
  }
  fpa_shiny_wf_span <- function(book, year_input, rg, fallback) {
    year <- fpa_pnl_wf_year_pick(year_input, fpa_pnl_wf_years(book))
    span <- fpa_pnl_wf_span(book, year, rg)
    if (is.null(span)) span <- fpa_pnl_wf_span(book, year, fallback)
    span
  }
  fpa_shiny_wf_period_lab <- function(span) {
    if (is.null(span)) return(NULL)
    if (!length(span$found)) {
      return(shiny::tags$p(
        class = "fpa-stmt-wf-period-lab",
        fpa_screen("stmt_wf_year_none", span$year)
      ))
    }
    shiny::tags$p(
      class = "fpa-stmt-wf-period-lab",
      paste(
        fpa_screen("stmt_wf_from"), span$found[[1]],
        fpa_screen("stmt_wf_to"), span$found[[length(span$found)]]
      ),
      if (length(span$missing)) {
        shiny::tags$span(class = "fpa-stmt-wf-miss", fpa_screen("stmt_wf_year_miss", length(span$missing)))
      }
    )
  }

  output$pnl_wf_year_a_ui <- shiny::renderUI({
    fpa_shiny_wf_year_ui("pnl_wf_year_a")
  })
  output$pnl_wf_year_b_ui <- shiny::renderUI({
    fpa_shiny_wf_year_ui("pnl_wf_year_b")
