  pnl_wf_fifo <- shiny::reactiveVal(list())
  pnl_wf_live_sentence <- shiny::reactiveVal("")

  fpa_shiny_pnl_wf_sentence <- function(book, span_a, span_b) {
    if (is.null(book) || !nrow(book) || is.null(span_a) || is.null(span_b)) return("")
    if (!length(span_a$found) || !length(span_b$found)) return("")
    row_a <- fpa_pnl_waterfall_sum(book, span_a$found)
    row_b <- fpa_pnl_waterfall_sum(book, span_b$found)
    hits <- fpa_pnl_waterfall_compare(row_a, row_b, top_n = 3L)
    if (is.null(hits) || !nrow(hits)) return("")
    bits <- vapply(seq_len(nrow(hits)), function(i) {
      pct <- hits$pct[[i]]
      paste0(
        fpa_shiny_line_name(hits$id[[i]]),
        " (", if (pct >= 0) "+" else "",
        formatC(pct, format = "f", digits = 1, big.mark = "\u202f", decimal.mark = ","),
        " ", fpa_screen("stmt_wf_fifo_pt"), ")"
      )
    }, character(1))
    lab <- function(span) fpa_pnl_range_label(span$found, 1L, length(span$found))
    fpa_screen(
      "stmt_wf_fifo_line",
      lab(span_a), lab(span_b),
      paste(bits, collapse = ", ")
    )
  }

