  pnl_shift <- function(dir) {
    pnl <- pack()$finance$pnl
    if (is.null(pnl) || !nrow(pnl)) return(invisible(NULL))
    pers <- as.character(pnl$periode)
    n <- suppressWarnings(as.integer(input$pnl_span))
    if (!is.finite(n) || n < 1L) n <- 12L
    i0 <- match(as.character(input$pnl_start %||% ""), pers)
    if (is.na(i0)) i0 <- max(1L, length(pers) - n + 1L)
    i1 <- min(max(1L, i0 + dir * n), max(1L, length(pers) - n + 1L))
    shiny::updateSelectInput(session, "pnl_start", selected = pers[[i1]])
  }
  shiny::observeEvent(input$pnl_prev, pnl_shift(-1L), ignoreInit = TRUE)
  shiny::observeEvent(input$pnl_next, pnl_shift(1L), ignoreInit = TRUE)

  out_items <- shiny::reactiveVal(list())
  out_loaded <- shiny::reactiveVal(FALSE)
  out_updated <- shiny::reactiveVal("")
  out_msg <- shiny::reactiveVal("")
  out_ack_txt <- shiny::reactiveVal("")

  out_refresh_items <- function(cfg, as_of = NULL) {
    if (is.null(cfg)) return(list())
    when <- as_of %||% Sys.Date()
    fpa_manual_outlook_items(cfg, when, 4L)
  }

  out_save_balance <- function() {
    p <- pack()
    if (!isTRUE(p$ok) || !isTRUE(out_loaded())) return(invisible(NULL))
    saved <- tryCatch(
      fpa_outlook_write(p$config, list(
        as_of = input$out_asof,
        opening = input$out_open,
        items = list()
      )),
      error = function(e) NULL
    )
    if (!is.null(saved)) {
      out_updated(saved$updated %||% "")
      out_items(out_refresh_items(p$config, input$out_asof))
    }
    invisible(saved)
  }

  #' Rerun the engine after a ledger write. Returns acknowledgement text.
  out_rerun <- function(before_fin) {
    manual_books(NULL)
    path <- cfg_path()
    if (!nzchar(path %||% "")) path <- pack()$config_path %||% ""
    if (!nzchar(path)) return("")
    shiny::showNotification(fpa_screen("man_rerun"), id = "fpa-man-run", duration = NULL, type = "message")
    res <- tryCatch(fpa_run(path, write = TRUE, stop_on_error = FALSE), error = function(e) e)
    if (!inherits(res, "error")) {
      if (exists("fpa_sync_report_run", mode = "function")) {
        tryCatch(fpa_sync_report_run(dirname(path), path, res), error = function(e) NULL)
      }
      tryCatch(fpa_driver_pass(path, res = res, write = TRUE), error = function(e) NULL)
      pack(fpa_shiny_load(path))
    }
    shiny::removeNotification("fpa-man-run")
    if (inherits(res, "error")) return(conditionMessage(res))
    after <- list(cash = res$cash, pnl = res$pnl)
    before <- list(cash = before_fin$cash, pnl = before_fin$pnl)
    ye <- if (!is.null(after$cash) && nrow(after$cash)) {
      as.character(after$cash$periode[[nrow(after$cash)]])
    } else {
      ""
    }
    ack <- fpa_manual_ack(before, after, ye)
    eur <- function(x) if (!is.finite(x)) "—" else fpa_shiny_eur(x)
    cash_line <- fpa_screen(
      "man_ack_cash", ye, eur(ack$cash_before), eur(ack$cash_after)
    )
    ni_line <- if (isTRUE(ack$ni_unchanged)) {
      fpa_screen("man_ack_ni_flat")
    } else {
      fpa_screen("man_ack_ni", eur(ack$ni_before), eur(ack$ni_after))
    }
    paste(cash_line, ni_line)
  }

  #' Typed balance when there is one. Otherwise the modeled cash on that date.
  out_roll <- function() {
    opening <- suppressWarnings(as.numeric(input$out_open))
    source <- "declared"
    if (length(opening) != 1L || !is.finite(opening)) {
      cash <- cash_now()
      if (is.null(cash) || !nrow(cash)) cash <- pack()$finance$cash
      opening <- fpa_synth_cash_on_date(cash, input$out_asof)
      source <- "modeled"
    }
    items <- out_items()
    roll <- fpa_outlook_roll(opening, items, input$out_asof, FALSE)
    roll$opening_source <- if (identical(roll$reason, "need_balance")) "missing" else source
    roll$lines <- items
    roll
  }

  shiny::observe({
    p <- pack()
    if (!isTRUE(p$ok) || isTRUE(out_loaded())) return()
    tryCatch(fpa_manual_migrate_outlook(p$config), error = function(e) 0L)
    saved <- fpa_outlook_read(p$config)
    opening <- suppressWarnings(as.numeric(saved$opening))
    as_of <- fpa_outlook_date(saved$as_of)
    # Same row as Synthèse: when the outlook file has no opening, hydrate amount and date from the journal.
    if (!is.finite(opening)) {
      declared <- tryCatch(fpa_synth_latest_declared(journal_entries()), error = function(e) NULL)
      if (!is.null(declared) && is.finite(declared$opening)) {
        opening <- declared$opening
        as_of <- fpa_outlook_date(declared$as_of)
      }
    }
    out_updated(saved$updated %||% "")
    if (is.finite(as_of)) shiny::updateDateInput(session, "out_asof", value = as_of)
    if (is.finite(opening)) shiny::updateNumericInput(session, "out_open", value = opening)
    out_items(out_refresh_items(p$config, if (is.finite(as_of)) as_of else saved$as_of))
    out_loaded(TRUE)
  })

  shiny::observeEvent(input$out_open, out_save_balance(), ignoreInit = TRUE)
  shiny::observeEvent(input$out_asof, {
    out_save_balance()
    p <- pack()
    if (isTRUE(p$ok)) out_items(out_refresh_items(p$config, input$out_asof))
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$out_add, {
    p <- pack()
    if (!isTRUE(p$ok)) return()
    kind <- as.character(input$out_kind %||% "out")
    if (!kind %in% c("in", "out")) kind <- "out"
    nature <- as.character(input$out_nature %||% "nouveau")
    if (!nature %in% c("nouveau", "decalage")) nature <- "nouveau"
    amt <- suppressWarnings(as.numeric(input$out_amount))
    lab <- trimws(as.character(input$out_label %||% ""))
    when <- fpa_outlook_date(input$out_when)
    if (!nzchar(lab) || !is.finite(amt) || amt <= 0 || !is.finite(when)) {
      out_msg(fpa_screen("out_bad_line"))
      return()
    }
    ligne <- as.character(input$out_ligne %||% fpa_manual_default_ligne(kind))
    if (identical(nature, "nouveau") && identical(kind, "in") && identical(ligne, "OPEX_OTHER")) {
      ligne <- "OTHER_OP_INC"
    }
    if (identical(nature, "nouveau") && identical(kind, "out") && identical(ligne, "OTHER_OP_INC")) {
      ligne <- "OPEX_OTHER"
    }
    prevue <- if (identical(nature, "decalage")) fpa_outlook_date(input$out_prevue) else as.Date(NA)
    if (identical(nature, "decalage") && !is.finite(prevue)) {
      out_msg(fpa_screen("man_need_prevue"))
      return()
    }
    entry <- list(
      id = fpa_manual_id(),
      saisi_le = format(Sys.time(), "%Y-%m-%d %H:%M:%S"),
      nature = nature,
      sens = kind,
      montant = amt,
      date_effet = as.character(when),
      date_prevue = if (is.finite(prevue)) as.character(prevue) else "",
      ligne = if (identical(nature, "nouveau")) ligne else "",
      quantite = NA_real_,
      unite = "",
      libelle = lab,
      statut = "actif",
      journal_id = ""
    )
    # Dry-run ledger gate on closed months before writing.
    probe <- fpa_manual_as_df(list(entry))
    actual <- character(0)
    st <- p$finance$period_status
    if (!is.null(st) && nrow(st) && "status" %in% names(st)) {
      actual <- as.character(st$periode[as.character(st$status) == "actual"])
    }
    periods <- if (!is.null(p$finance$pnl)) as.character(p$finance$pnl$periode) else character(0)
    led <- fpa_manual_ledger(probe, periods, actual)
    if (nrow(led) && identical(as.character(led$state[[1]]), "excluded")) {
      out_msg(fpa_screen("man_closed_refuse", as.character(led$reason[[1]])))
      return()
    }
    before_fin <- p$finance
    tryCatch(fpa_manual_upsert(p$config, entry), error = function(e) NULL)
    out_msg("")
    out_ack_txt(out_rerun(before_fin))
    shiny::updateTextInput(session, "out_label", value = "")
    shiny::updateNumericInput(session, "out_amount", value = NA_real_)
    out_items(out_refresh_items(pack()$config, input$out_asof))
    shiny::updateRadioButtons(session, "synth_hero_mode", selected = "cash")
    bslib::nav_select("main_nav", fpa_screen("loc_summary"), session = session)
    session$sendCustomMessage("fpa-open-details", list(sel = "#plot_cash_line"))
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$out_remove, {
    p <- pack()
    if (!isTRUE(p$ok)) return()
    id <- as.character(input$out_remove %||% "")
    if (!nzchar(id)) return()
    before_fin <- p$finance
    tryCatch(fpa_manual_retire(p$config, id), error = function(e) NULL)
    out_ack_txt(out_rerun(before_fin))
    out_items(out_refresh_items(pack()$config, input$out_asof))
  }, ignoreInit = TRUE)

