  output$out_gap <- shiny::renderUI({
    opening <- suppressWarnings(as.numeric(input$out_open))
    if (length(opening) != 1L || !is.finite(opening)) return(NULL)
    cash <- cash_now()
    if (is.null(cash) || !nrow(cash)) cash <- pack()$finance$cash
    modeled <- fpa_synth_cash_on_date(cash, input$out_asof)
    if (!is.finite(modeled)) return(NULL)
    gap <- opening - modeled
    if (abs(gap) < 0.5) {
      return(shiny::tags$p(style = "color:#1f4e5f;", fpa_screen("man_gap_ok", fpa_shiny_eur(opening))))
    }
    shiny::tags$p(
      style = "color:#8c3a3a;",
      fpa_screen("man_gap", fpa_shiny_eur(opening), fpa_shiny_eur(modeled), fpa_shiny_eur(gap))
    )
  })

