  output$manual_list_note <- shiny::renderUI({
    p <- pack()
    manual_show()
    pair <- manual_pair()
    if (!isTRUE(p$ok)) return(NULL)
    cur <- tryCatch(fpa_manual_read(p$config), error = function(e) NULL)
    df <- if (is.null(cur)) NULL else fpa_manual_active(cur$data)
    if (is.null(df) || !nrow(df)) return(shiny::tags$p(class = "fpa-man-note", fpa_screen("man_list_empty")))
    fin <- p$finance$cash
    last_p <- if (!is.null(fin) && nrow(fin)) as.character(fin$periode[[nrow(fin)]]) else ""
    last_c <- if (!is.null(fin) && nrow(fin)) suppressWarnings(as.numeric(fin$cash_close[[nrow(fin)]])) else NA_real_
    other <- if (is.null(pair)) NA_real_ else if (isTRUE(manual_show())) pair$without else pair$with
    lines <- vapply(seq_len(nrow(df)), function(i) {
      sens <- if (identical(as.character(df$sens[[i]]), "in")) fpa_screen("out_in") else fpa_screen("out_out")
      fpa_screen(
        "man_list_line",
        as.character(df$libelle[[i]]),
        sens,
        fpa_shiny_eur(df$montant[[i]]),
        as.character(df$date_effet[[i]])
      )
    }, character(1))
    shiny::tags$div(
      shiny::tags$p(class = "fpa-man-note", paste(lines, collapse = " ")),
      shiny::tags$p(
        class = "fpa-man-note",
        fpa_screen(
          if (isTRUE(manual_show())) "man_list_on" else "man_list_off",
          fpa_shiny_close_when(last_p), fpa_shiny_eur(last_c), fpa_shiny_eur(other)
        )
      )
    )
  })

  output$out_items <- shiny::renderUI({
