    if (!length(items)) return(shiny::tags$p(fpa_screen("out_none")))
    rows <- lapply(items, function(it) {
      when <- format(fpa_outlook_date(it$date), "%d/%m/%Y")
      kind <- if (identical(it$kind, "in")) fpa_screen("out_in") else fpa_screen("out_out")
      nat <- if (identical(as.character(it$nature %||% ""), "decalage")) {
        fpa_screen("man_decalage")
      } else {
        fpa_screen("man_nouveau")
      }
      shiny::div(
        class = "fpa-out-line",
