        )),
        shiny::tags$button(
          type = "button",
          style = "background:#fff;color:#1f4e5f;border:1px solid #1f4e5f;border-radius:8px;font-weight:600;font-size:12px;",
          onclick = sprintf("Shiny.setInputValue('out_remove','%s',{priority:'event'})", it$id),
