  output$out_board <- shiny::renderUI({
    roll <- out_roll()
    eur <- function(x) if (!is.finite(x)) "—" else fpa_shiny_eur(x)
    fmt <- function(d) if (!is.finite(fpa_outlook_date(d))) "—" else format(fpa_outlook_date(d), "%d/%m/%Y")
    if (identical(roll$reason, "need_balance")) {
      return(shiny::tags$p(fpa_screen("out_need")))
    }
    notes <- list()
    as_of_d <- fpa_outlook_date(roll$as_of)
    if (is.finite(as_of_d) && as_of_d > Sys.Date()) {
      notes[[length(notes) + 1L]] <- shiny::tags$p(fpa_screen("out_asof_planned", fmt(roll$as_of)))
    }
    if (identical(roll$opening_source, "modeled")) {
      notes[[length(notes) + 1L]] <- shiny::tags$p(
        fpa_screen("out_open_modeled", eur(roll$opening), fpa_shiny_date_fr(roll$as_of))
      )
    }
    if (identical(roll$reason, "balance_only") && !identical(roll$opening_source, "modeled")) {
      notes[[length(notes) + 1L]] <- shiny::tags$p(fpa_screen("out_balance_saved", eur(roll$opening), fmt(roll$as_of)))
    } else if (!identical(roll$reason, "balance_only")) {
      notes[[length(notes) + 1L]] <- shiny::tags$p(fpa_screen("out_partial", if (nzchar(out_updated())) out_updated() else "—"))
      if (isTRUE(roll$delay)) notes[[length(notes) + 1L]] <- shiny::tags$p(fpa_screen("out_delay_on"))
      if ((roll$beyond %||% 0L) > 0L) notes[[length(notes) + 1L]] <- shiny::tags$p(fpa_screen("out_beyond", as.character(roll$beyond)))
      if ((roll$before %||% 0L) > 0L) notes[[length(notes) + 1L]] <- shiny::tags$p(fpa_screen("out_before", as.character(roll$before)))
      low_p <- if (!length(roll$low_items) && identical(as.character(roll$low_date), as.character(roll$as_of))) {
        shiny::tags$p(class = "fpa-out-lowline", fpa_screen("out_low_open", eur(roll$low), fmt(roll$low_date)))
      } else {
        shiny::tags$p(class = "fpa-out-lowline", fpa_screen("out_low", eur(roll$low), fmt(roll$low_date)))
      }
      if (length(roll$low_items)) {
        low_p <- shiny::tagList(
          low_p,
          shiny::tags$p(fpa_screen("out_low_items", paste(roll$low_items, collapse = ", ")))
        )
      }
      notes[[length(notes) + 1L]] <- low_p
    }
    head <- shiny::tags$tr(
      shiny::tags$th(fpa_screen("out_col_week")),
      shiny::tags$th(fpa_screen("out_col_end")),
      shiny::tags$th(fpa_screen("out_col_in")),
      shiny::tags$th(fpa_screen("out_col_out")),
      shiny::tags$th(fpa_screen("out_col_bal"))
    )
    body <- lapply(roll$weeks, function(w) {
      cls <- if (is.finite(w$close) && w$close < 0) "neg" else NULL
      shiny::tags$tr(
        class = if (identical(w$i, roll$low_week)) "fpa-out-low" else NULL,
        shiny::tags$td(fpa_screen("out_week", as.character(w$i))),
        shiny::tags$td(fmt(w$end)),
        shiny::tags$td(eur(w$inflow)),
        shiny::tags$td(eur(w$outflow)),
        shiny::tags$td(class = cls, eur(w$close))
      )
    })
    shiny::tagList(
      notes,
      if (!identical(roll$reason, "balance_only")) shiny::tags$table(
        class = "fpa-out-table",
        shiny::tags$thead(head),
        shiny::tags$tbody(body)
      )
    )
  })

