  output$bs_check <- shiny::renderUI({
    bs <- bs_view()
    if (is.null(bs) || !nrow(bs)) return(shiny::tags$p("Pas de bilan."))
    last <- bs[nrow(bs), , drop = FALSE]
    assets <- sum(last$CASH, last$AR, last$INV, last$PPE, last$OTHER_CA, na.rm = TRUE)
    claims <- sum(last$AP, last$ST_DEBT, last$LT_DEBT, last$OTHER_CL, last$EQUITY, na.rm = TRUE)
    gap <- assets - claims
    ok <- is.finite(gap) && abs(gap) < 1
    head <- fpa_shiny_bs_headline(bs)
    shiny::tagList(
      if (nzchar(head)) shiny::tags$p(
        style = "margin:0.2rem 0 0.35rem;line-height:1.45;font-weight:600;color:#1f4e5f;",
        head
      ) else NULL,
      shiny::tags$p(
        style = "margin:0 0 0.5rem;line-height:1.4;color:#5c6b73;font-size:13px;",
        shiny::tags$span(if (ok) fpa_screen("bs_ok") else fpa_screen("bs_bad"), " "),
        fpa_screen("bs_line", last$periode, fpa_shiny_eur(assets), fpa_shiny_eur(claims), fpa_shiny_eur(gap))
      )
    )
  })

