  output$bs_tm_period <- shiny::renderUI({
    bs <- bs_view()
    if (is.null(bs) || !nrow(bs)) return(NULL)
    pers <- unique(as.character(bs$periode))
    pers <- pers[nzchar(pers)]
    if (!length(pers)) return(NULL)
    labels <- vapply(pers, fpa_ym_fr, character(1))
    choices <- stats::setNames(pers, labels)
    last <- pers[[length(pers)]]
    y <- suppressWarnings(as.integer(substr(last, 1, 4)))
    m <- substr(last, 6, 7)
    prior <- if (!is.na(y) && nzchar(m)) sprintf("%04d-%s", y - 1L, m) else ""
    def_a <- if (prior %in% pers) prior else pers[[1]]
    def_b <- last
    cur_a <- shiny::isolate(input$bs_cmp_a %||% "")
    cur_b <- shiny::isolate(input$bs_cmp_b %||% "")
    if (nzchar(cur_a) && cur_a %in% pers) def_a <- cur_a
    if (nzchar(cur_b) && cur_b %in% pers) def_b <- cur_b
    shiny::tags$div(
      class = "fpa-bs-picks",
      shiny::selectInput("bs_cmp_a", fpa_screen("bs_cmp_a"), choices = choices, selected = def_a, selectize = FALSE),
      shiny::selectInput("bs_cmp_b", fpa_screen("bs_cmp_b"), choices = choices, selected = def_b, selectize = FALSE)
    )
  })

  output$bs_maps <- shiny::renderUI({
