        fpa_shiny_bs_map_column(bs, b, sides$asset, "is-asset", fpa_screen("bs_cmp_asset"), paste0(fpa_screen("bs_cmp_b"), " · ", fpa_ym_fr(b))),
        fpa_shiny_bs_map_column(bs, a, sides$claim, "is-claim", fpa_screen("bs_cmp_claim"), paste0(fpa_screen("bs_cmp_a"), " · ", fpa_ym_fr(a))),
        fpa_shiny_bs_map_column(bs, b, sides$claim, "is-claim", fpa_screen("bs_cmp_claim"), paste0(fpa_screen("bs_cmp_b"), " · ", fpa_ym_fr(b)))
      )
