  fpa_shiny_health_gauge <- function(id, value) {
    g <- fpa_health_gauge_zone(id, value)
    if (is.null(g)) {
      if (identical(id, "asset_turnover")) {
        return(shiny::tags$p(class = "fpa-gauge-word", style = "margin:0 0 6px;", fpa_screen("health_band_none")))
      }
      return(NULL)
    }
    s <- g$spec
    w1 <- 100 * s$lo / s$scale
    w2 <- 100 * (s$hi - s$lo) / s$scale
    w3 <- 100 - w1 - w2
    cols <- if (identical(s$dir, "down")) {
      c("#c5ddd4", "#e7e0c8", "#f0c8c8")
    } else if (identical(s$dir, "up")) {
      c("#f0c8c8", "#e7e0c8", "#c5ddd4")
    } else {
      c("#f0c8c8", "#c5ddd4", "#e7e0c8")
    }
    fmt_band <- function(x) {
      if (id %in% c("gross_margin", "ebitda_margin", "oi_margin", "roa", "roce")) {
        return(paste0(formatC(100 * x, format = "f", digits = 0), " %"))
      }
      if (id %in% c("dso_days", "dio_days")) return(paste0(format(round(x), trim = TRUE), " j"))
      formatC(x, format = "f", digits = 1, decimal.mark = ",")
    }
    note <- if (isTRUE(g$beyond)) {
      fpa_screen("health_band_beyond", fmt_band(s$lo), fmt_band(s$hi))
    } else {
      fpa_screen("health_band_note", fmt_band(s$lo), fmt_band(s$hi))
    }
    shiny::tags$div(
      class = "fpa-gauge",
      shiny::tags$div(
        class = "fpa-gauge-track",
        shiny::tags$span(style = paste0("width:", round(w1, 1), "%;background:", cols[[1]], ";")),
        shiny::tags$span(style = paste0("width:", round(w2, 1), "%;background:", cols[[2]], ";")),
        shiny::tags$span(style = paste0("width:", round(w3, 1), "%;background:", cols[[3]], ";")),
        shiny::tags$i(style = paste0("left:", round(100 * g$pos, 1), "%;"))
      ),
      shiny::tags$div(class = "fpa-gauge-word", paste0(fpa_screen(g$key), ". ", note))
    )
  }

  fpa_shiny_health_fold_gauge <- function(ids, values, skip = character(), cl = NA_real_) {
    mix <- fpa_health_fold_mix(ids, values, skip)
    if (length(mix$skipped) && (!is.finite(mix$pos) || mix$n_used < 1L)) {
      return(shiny::tags$span(
        class = "fpa-gauge fpa-fold-gauge",
        shiny::tags$span(class = "fpa-gauge-word", style = "display:block;", fpa_screen("health_fold_thin_none"))
      ))
    }
    if (!is.finite(mix$pos) || mix$n_used < 1L) return(NULL)
    count <- if (isTRUE(mix$n_used == mix$n_all)) {
      if (isTRUE(mix$n_used == 1)) fpa_screen("health_fold_one") else fpa_screen("health_fold_all", mix$n_used)
    } else if (isTRUE(mix$n_used == 1)) {
      fpa_screen("health_fold_one_some", mix$n_all)
    } else {
      fpa_screen("health_fold_some", mix$n_used, mix$n_all)
    }
    zone <- switch(
      fpa_health_fold_zone(mix$pos),
      attn = "health_fold_attn",
      mid = "health_fold_mid",
      "health_fold_good"
    )
    note <- paste(count, fpa_screen(zone))
    if (length(mix$skipped)) note <- paste(note, fpa_screen("health_fold_thin_some", length(mix$skipped)))
    trust_cash <- tryCatch({
      m <- synthese_model()
      as.character(m$trust$cash %||% "")
    }, error = function(e) "")
    if (identical(trust_cash, "limited") && identical(zone, "health_fold_good")) {
      note <- paste(fpa_screen("health_fold_limited"), note)
    } else if (identical(trust_cash, "limited")) {
      note <- paste(note, fpa_screen("health_fold_limited"))
    }
    shiny::tags$span(
      class = "fpa-gauge fpa-fold-gauge",
      shiny::tags$span(
        class = "fpa-gauge-track",
        shiny::tags$span(style = "width:33.3%;background:#f0c8c8;"),
        shiny::tags$span(style = "width:33.4%;background:#e7e0c8;"),
        shiny::tags$span(style = "width:33.3%;background:#c5ddd4;"),
        shiny::tags$i(style = paste0("left:", formatC(100 * mix$pos, format = "f", digits = 1), "%;"))
      ),
      shiny::tags$span(class = "fpa-gauge-word", style = "display:block;", note)
    )
  }

  output$health_page <- shiny::renderUI({
    p0 <- pack()
    fin <- p0$finance
    fy_start <- fpa_fy_start_month(p0$config)
    fy_name <- fpa_shiny_month_name(sprintf("2000-%02d", fy_start))
    closed <- fpa_health_closed_month(fin$period_status)
    if (!nzchar(closed) || is.null(fin$bs) || !nrow(fin$bs) || is.null(fin$pnl) || !nrow(fin$pnl)) {
      return(shiny::tags$p(fpa_screen("health_empty")))
    }
    v <- pnl_view()
    bs_p <- if (isTRUE(v$ready)) bs_view() else fin$bs
    pnl_p <- if (isTRUE(v$ready)) v$pnl else fin$pnl
    path <- fpa_year_end_info(p0$config, fin$period_status, as.character(fin$pnl$periode))$measured
    left <- fpa_health_month(fin$bs, fin$pnl, closed, fy_start)
    right <- fpa_health_month(bs_p, pnl_p, path, fy_start)
    if (!nrow(left)) return(shiny::tags$p(fpa_screen("health_empty")))
    pick <- function(df, id, col) {
      if (is.null(df) || !nrow(df) || !id %in% df$id) return(NA_real_)
      suppressWarnings(as.numeric(df[[col]][df$id == id][[1]]))
    }
    fmt <- function(id, value) {
      if (!is.finite(value)) return(fpa_screen("health_na"))
      if (id %in% c("gross_margin", "ebitda_margin", "oi_margin", "roa", "roce")) {
        return(paste0(formatC(100 * value, format = "f", digits = 1, decimal.mark = ","), " %"))
      }
      if (id %in% c("dso_days", "dio_days")) {
        return(paste0(formatC(value, format = "f", digits = 1, decimal.mark = ","), " j"))
      }
      if (identical(id, "book_ev")) return(paste0(fpa_shiny_eur(value), " EUR"))
      if (abs(value) >= 100) {
        return(paste0(format(round(value), big.mark = " ", scientific = FALSE, trim = TRUE), " x"))
      }
      paste0(formatC(value, format = "f", digits = 2, decimal.mark = ","), " x")
    }
    cell <- function(id, value) {
      style <- "text-align:right;font-variant-numeric:tabular-nums;"
      if (is.finite(value) && value < 0) style <- paste0(style, "color:#8c3a3a;")
      shiny::tags$td(style = style, fmt(id, value))
    }
    read_of <- function(id) {
      a <- pick(left, id, "a")
      b <- pick(left, id, "b")
      c <- pick(left, id, "c")
      eur <- function(x) fpa_shiny_eur(x)
      if (identical(id, "book_ev")) return(fpa_screen("health_ev_read", eur(a), eur(b), eur(c)))
      if (identical(id, "dso_days")) return(fpa_screen("health_dso_read", eur(a), eur(b)))
      if (identical(id, "dio_days")) return(fpa_screen("health_dio_read", eur(a), eur(b)))
      if (id %in% c("interest_coverage", "asset_turnover", "gross_margin", "ebitda_margin", "oi_margin", "roa", "roce")) {
        return(fpa_screen("health_ytd", fy_name, eur(a), eur(b)))
      }
      fpa_screen("health_pair", eur(a), eur(b))
    }
    label_of <- function(id) {
      key <- switch(
        id,
        current_ratio = "health_current", quick_ratio = "health_quick", cash_ratio = "health_cash",
        debt_to_equity = "health_de", debt_to_assets = "health_da", interest_coverage = "health_cover",
        dso_days = "health_dso", dio_days = "health_dio", asset_turnover = "health_turn",
        gross_margin = "health_gm", ebitda_margin = "health_ebitda", oi_margin = "health_om",
        roa = "health_roa", book_ev = "health_ev", roce = "health_roce", ""
      )
      if (!nzchar(key)) id else fpa_screen(key)
    }
    groups <- list(
      list(title = "health_liq", q = "health_liq_q", lead = "cash_ratio", ids = c("current_ratio", "quick_ratio", "cash_ratio")),
      list(title = "health_lev", q = "health_lev_q", lead = "debt_to_equity", ids = c("debt_to_equity", "debt_to_assets", "interest_coverage")),
      list(title = "health_eff", q = "health_eff_q", lead = "dso_days", ids = c("dso_days", "dio_days", "asset_turnover")),
      list(title = "health_pro", q = "health_pro_q", lead = "oi_margin", ids = c("gross_margin", "ebitda_margin", "oi_margin", "roa")),
      list(title = "health_scr", q = "health_scr_q", lead = "book_ev", ids = c("book_ev", "roce"))
    )
    when <- paste(fpa_shiny_month_name(closed), substr(closed, 1, 4))
    thin_ids <- fpa_health_thin_ids(left)
    thin_cl <- pick(left, "cash_ratio", "b")
    shiny::div(
      class = "fpa-health",
      shiny::tags$div(class = "fpa-period-chip", fpa_period_chip_label("actual", closed)),
      shiny::tags$p(
        style = "margin:0.2rem 0 0.35rem;line-height:1.45;font-weight:600;color:#1f4e5f;",
        fpa_screen(
          "health_head", when,
          fpa_shiny_eur(pick(left, "cash_ratio", "a")),
          fpa_shiny_eur(pick(left, "cash_ratio", "b")),
          fpa_shiny_eur(pick(left, "debt_to_equity", "a")),
          fy_name,
          fpa_shiny_eur(pick(left, "oi_margin", "a"))
        )
      ),
      shiny::tags$p(style = "margin:0 0 4px;line-height:1.4;color:#3d4c54;", fpa_screen("health_path")),
      shiny::tags$p(style = "margin:0 0 10px;line-height:1.4;color:#3d4c54;", fpa_screen("health_skip")),
      shiny::div(
        id = "health-folds",
        shiny::div(
          class = "fpa-pnl-tools",
          shiny::tags$button(
            type = "button", class = "fpa-fold-icon",
            title = fpa_screen("pnl_fold_open"),
            `aria-label` = fpa_screen("pnl_fold_open"),
            onclick = "this.closest('#health-folds').querySelectorAll('details.fpa-fold').forEach(function(d){ d.open = true })",
            shiny::HTML('<svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true"><path d="M3.2 6.2 8 10.2l4.8-4" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/><path d="M3.2 9.4 8 13.4l4.8-4" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>')
          ),
          shiny::tags$button(
            type = "button", class = "fpa-fold-icon",
            title = fpa_screen("pnl_fold_close"),
            `aria-label` = fpa_screen("pnl_fold_close"),
            onclick = "this.closest('#health-folds').querySelectorAll('details.fpa-fold').forEach(function(d){ d.open = false })",
            shiny::HTML('<svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true"><path d="M3.2 9.8 8 5.8l4.8 4" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/><path d="M3.2 6.6 8 2.6l4.8 4" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>')
          )
        ),
        lapply(groups, function(g) {
          lead_v <- pick(left, g$lead, "value")
          band <- fpa_health_fold_band(g$lead, lead_v)
          skip <- intersect(thin_ids, g$ids)
          lead_thin <- g$lead %in% skip
          if (lead_thin) band <- "watch"
          fact <- if (lead_thin) {
            paste0(fpa_screen(g$q), " ", fpa_screen("health_thin_read", fpa_shiny_eur(thin_cl)))
          } else {
            paste0(fpa_screen(g$q), " ", label_of(g$lead), " ", fmt(g$lead, lead_v), ".")
          }
          shiny::tags$details(
            class = paste("fpa-fold", paste0("is-", band)),
            shiny::tags$summary(
              shiny::tags$span(
                class = "fpa-fold-sum",
                shiny::tags$span(class = "fpa-fold-k", fpa_screen(g$title)),
                shiny::tags$span(class = "fpa-fold-fact", fact)
              ),
              fpa_shiny_health_fold_gauge(g$ids, vapply(g$ids, function(id) pick(left, id, "value"), numeric(1)), skip, thin_cl)
            ),
            shiny::div(
              class = "fpa-fold-body",
              shiny::tags$table(
                shiny::tags$thead(
                  shiny::tags$tr(
                    shiny::tags$th("Indicateur"),
                    shiny::tags$th(fpa_screen("health_col_closed")),
                    shiny::tags$th(fpa_screen("health_col_path")),
                    shiny::tags$th(fpa_screen("health_col_read"))
                  )
                ),
                shiny::tags$tbody(lapply(g$ids, function(id) {
                  shiny::tags$tr(
                    shiny::tags$td(
                      shiny::tags$button(
                        type = "button",
                        class = "fpa-line-go",
                        onclick = sprintf("Shiny.setInputValue('health_read','%s',{priority:'event'})", id),
                        label_of(id)
                      )
                    ),
                    cell(id, pick(left, id, "value")),
                    cell(id, pick(right, id, "value")),
                    shiny::tags$td(
                      class = "fpa-health-read",
                      if (id %in% thin_ids) {
                        shiny::tags$p(class = "fpa-gauge-word", style = "margin:0 0 6px;", fpa_screen("health_thin_read", fpa_shiny_eur(thin_cl)))
                      } else {
                        fpa_shiny_health_gauge(id, pick(left, id, "value"))
                      },
                      read_of(id)
                    )
                  )
                }))
              )
            )
          )
        })
      )
    )
  })

  shiny::observeEvent(input$health_read, {
    id <- gsub("[^A-Za-z0-9_]", "", as.character(input$health_read %||% ""))
    if (!id %in% fpa_health_ids()) return()
    p <- pack()
    fin <- p$finance
    fy_start <- fpa_fy_start_month(p$config)
    fy_name <- fpa_shiny_month_name(sprintf("2000-%02d", fy_start))
    closed <- fpa_health_closed_month(fin$period_status)
    left <- fpa_health_month(fin$bs, fin$pnl, closed, fy_start)
    if (!nrow(left) || !id %in% left$id) return()
    row <- left[left$id == id, , drop = FALSE]
    value <- suppressWarnings(as.numeric(row$value[[1]]))
    shown <- if (!is.finite(value)) {
      fpa_screen("health_na")
    } else if (id %in% c("gross_margin", "ebitda_margin", "oi_margin", "roa", "roce")) {
      paste0(formatC(100 * value, format = "f", digits = 1, decimal.mark = ","), " %")
    } else if (id %in% c("dso_days", "dio_days")) {
      paste0(formatC(value, format = "f", digits = 1, decimal.mark = ","), " j")
    } else if (identical(id, "book_ev")) {
      paste0(fpa_shiny_eur(value), " EUR")
    } else if (abs(value) >= 100) {
      paste0(format(round(value), big.mark = " ", scientific = FALSE, trim = TRUE), " x")
    } else {
      paste0(formatC(value, format = "f", digits = 2, decimal.mark = ","), " x")
    }
    src_of <- function(role) {
      for (s in p$config$sources %||% list()) {
        if (!identical(as.character(s$file_role %||% ""), role)) next
        return(list(
          id = as.character(s$source_id %||% ""),
          name = basename(fpa_chain_source_path(p$config, s))
        ))
      }
      list(id = "", name = "")
    }
    dlg <- fpa_shiny_health_modal(
      id, row, closed,
      src_of("opening_bs"),
      src_of("pnl_monthly"),
      shown,
      fy_name
    )
    if (!is.null(dlg)) shiny::showModal(dlg)
  }, ignoreInit = TRUE)

  output$anomaly_page <- shiny::renderUI({
    p <- pack()
    fin <- p$finance
    if (is.null(fin$pnl) || !nrow(fin$pnl)) return(shiny::tags$p(fpa_screen("anom_empty")))
    hist <- tryCatch(fpa_line_history(p$config, p$paths), error = function(e) NULL)
    vol <- fpa_shiny_volumes(p$config, p$paths)
    map <- tryCatch(fpa_line_map(p$config, "pnl"), error = function(e) NULL)
    closed <- fpa_health_closed_month(fin$period_status)
    focus <- fpa_anomaly_focus_periods(fin$period_status)
    scan <- fpa_anomaly_scan(fin$bs, fin$pnl, fin$cash, vol, hist, map, focus)
    eur <- function(x) fpa_shiny_eur(x)
    when <- function(per) {
      per <- as.character(per)
      if (!nzchar(per)) return("")
      paste(fpa_shiny_month_name(per), substr(per, 1, 4))
    }
    signed <- function(x) {
      if (!is.finite(x)) return(fpa_screen("health_na"))
      paste0(format(round(x), big.mark = " ", scientific = FALSE, trim = TRUE), " EUR")
    }
    line_name <- function(id) {
      if (identical(id, "BS")) return("Bilan")
      if (identical(id, "CASH")) return("Trésorerie")
      if (identical(id, "cash_ratio")) return(fpa_screen("health_cash"))
      lab <- tryCatch(fpa_line_fr(id), error = function(e) id)
      if (!nzchar(lab)) id else lab
    }
    sentence <- function(row) {
      i <- 1
      fam <- row$family[[i]]
      if (identical(fam, "books") && identical(row$level[[i]], "clear")) return(fpa_screen("anom_books_clear"))
      if (identical(row$line_id[[i]], "BS")) {
        return(fpa_screen("anom_books_bs", when(row$periode[[i]]), eur(row$value[[i]]), eur(row$reference[[i]]), signed(row$gap[[i]])))
      }
      if (identical(row$line_id[[i]], "CASH")) {
        return(fpa_screen("anom_books_cash", when(row$periode[[i]]), eur(row$value[[i]]), eur(row$reference[[i]]), signed(row$gap[[i]])))
      }
      if (identical(fam, "driver")) {
        return(fpa_screen("anom_driver_row", when(row$periode[[i]]), line_name(row$line_id[[i]]), eur(row$value[[i]]), eur(row$reference[[i]]), signed(row$gap[[i]])))
      }
      if (identical(fam, "season") && is.finite(row$n[[i]]) && row$n[[i]] >= 4L) {
        return(fpa_screen(
          "anom_season_many", line_name(row$line_id[[i]]), row$n[[i]], when(row$periode[[i]]),
          eur(row$value[[i]]), eur(row$reference[[i]]), signed(row$gap[[i]])
        ))
      }
      if (identical(fam, "season")) {
        return(fpa_screen("anom_season_row", when(row$periode[[i]]), line_name(row$line_id[[i]]), eur(row$value[[i]]), eur(row$reference[[i]]), signed(row$gap[[i]])))
      }
      ratio_txt <- if (abs(row$value[[i]]) >= 100) {
        format(round(row$value[[i]]), big.mark = " ", scientific = FALSE, trim = TRUE)
      } else {
        formatC(row$value[[i]], format = "f", digits = 1, decimal.mark = ",")
      }
      fpa_screen("anom_ratio_row", when(row$periode[[i]]), ratio_txt, eur(row$gap[[i]]), eur(row$reference[[i]]))
    }
    story <- function(row) {
      fam <- row$family[[1]]
      line <- row$line_id[[1]]
      why <- if (identical(fam, "books")) {
        fpa_screen("anom_books_why")
      } else if (identical(fam, "driver") && identical(line, "REV")) {
        fpa_screen("anom_drv_rev_why")
      } else if (identical(fam, "driver")) {
        fpa_screen("anom_drv_pay_why")
      } else if (identical(fam, "season") && identical(line, "REV")) {
        fpa_screen("anom_sea_rev_why")
      } else if (identical(fam, "season")) {
        fpa_screen("anom_sea_pay_why")
      } else {
        fpa_screen("anom_ratio_why")
      }
      so <- if (identical(fam, "books")) {
        fpa_screen("anom_books_so")
      } else if (identical(fam, "driver") && identical(line, "REV")) {
        fpa_screen("anom_drv_rev_so")
      } else if (identical(fam, "driver")) {
        fpa_screen("anom_drv_pay_so")
      } else if (identical(fam, "season") && identical(line, "REV")) {
        fpa_screen("anom_sea_rev_so")
      } else if (identical(fam, "season")) {
        fpa_screen("anom_sea_pay_so")
      } else {
        fpa_screen("anom_ratio_so")
      }
      bit <- function(k, txt) {
        shiny::tags$p(style = "margin:0 0 4px;line-height:1.4;", shiny::tags$strong(fpa_screen(k)), " ", txt)
      }
      where <- if (identical(fam, "driver")) {
        source_path <- as.character(
          if (identical(line, "REV")) p$config$paths$volumes %||% p$config$paths$ops %||% ""
          else p$config$paths$ops %||% p$config$paths$volumes %||% ""
        )
        shiny::tagList(
          shiny::tags$div(
            style = "margin:8px 0 0;padding:8px 10px;border-left:3px solid #1f4e5f;background:#f4f8f9;",
            shiny::tags$strong(fpa_screen("anom_where_title")),
            shiny::tags$p(style = "margin:4px 0 0;", fpa_screen("anom_where_file", basename(source_path))),
            shiny::tags$p(style = "margin:4px 0 0;", fpa_screen("anom_where_checks")),
            shiny::tags$button(
              type = "button", class = "fpa-go-btn",
              onclick = sprintf("Shiny.setInputValue('fpa_go',{tab:'Impact',line:'%s',periode:'%s'},{priority:'event'})", line, row$periode[[1]]),
              fpa_screen("home_test_response")
            ),
            shiny::tags$button(
              type = "button", class = "fpa-go-btn", style = "margin-left:6px;",
              onclick = sprintf(
                "Shiny.setInputValue('journal_capture',{kind:'anomaly',family:'%s',line:'%s',periode:'%s',gap:%s,sentence:%s},{priority:'event'})",
                fam, line, row$periode[[1]],
                jsonlite::toJSON(suppressWarnings(as.numeric(row$gap[[1]])), auto_unbox = TRUE),
                jsonlite::toJSON(sentence(row), auto_unbox = TRUE)
              ),
              fpa_screen("journal_to_journal")
            )
          )
        )
      } else {
        shiny::tags$button(
          type = "button", class = "fpa-go-btn", style = "margin-top:6px;",
          onclick = sprintf(
            "Shiny.setInputValue('journal_capture',{kind:'anomaly',family:'%s',line:'%s',periode:'%s',gap:%s,sentence:%s},{priority:'event'})",
            fam, line, row$periode[[1]],
            jsonlite::toJSON(suppressWarnings(as.numeric(row$gap[[1]])), auto_unbox = TRUE),
            jsonlite::toJSON(sentence(row), auto_unbox = TRUE)
          ),
          fpa_screen("journal_to_journal")
        )
      }
      shiny::tagList(bit("anom_wws_what", sentence(row)), bit("anom_wws_why", why), bit("anom_wws_so", so), where)
    }
    families <- list(
      list(id = "books", title = "anom_books", q = "anom_books_q", clear = "anom_books_clear"),
      list(id = "driver", title = "anom_driver", q = "anom_driver_q", clear = "anom_driver_clear"),
      list(id = "season", title = "anom_season", q = "anom_season_q", clear = "anom_season_clear"),
      list(id = "ratio", title = "anom_ratio", q = "anom_ratio_q", clear = "anom_ratio_clear")
    )
    hits <- scan[scan$level != "clear", , drop = FALSE]
    floor_txt <- format(FPA_ANOMALY_FLOOR, big.mark = " ", scientific = FALSE, trim = TRUE)
    card <- function(g) {
      sl <- scan[scan$family == g$id & scan$level != "clear", , drop = FALSE]
      fact <- if (!nrow(sl)) {
        if (g$id %in% c("driver", "season")) fpa_screen(g$clear, floor_txt) else fpa_screen(g$clear)
      } else if (identical(g$id, "ratio")) {
        bits <- vapply(seq_len(nrow(sl)), function(i) sentence(sl[i, , drop = FALSE]), character(1))
        if (nrow(sl) > 1L) fpa_screen("anom_ratio_same_card", nrow(sl), paste(bits, collapse = " ")) else bits[[1]]
      } else {
        top <- sl[which.max(abs(sl$gap)), , drop = FALSE]
        paste0(nrow(sl), fpa_screen("loc_gaps_sp"), sentence(top))
      }
      shiny::tags$details(
        class = "fpa-fold",
        shiny::tags$summary(
          shiny::tags$span(
            class = "fpa-fold-sum",
            shiny::tags$span(class = "fpa-fold-k", fpa_screen(g$title)),
            shiny::tags$span(class = "fpa-fold-fact", paste0(fpa_screen(g$q), " ", fact))
          )
        ),
        shiny::div(
          class = "fpa-fold-body",
          if (!nrow(sl) && identical(g$id, "books")) {
            shiny::tagList(
              shiny::tags$p(style = "margin:0 0 4px;line-height:1.4;", shiny::tags$strong(fpa_screen("anom_wws_what")), " ", fpa_screen("anom_books_clear")),
              shiny::tags$p(style = "margin:0 0 4px;line-height:1.4;", shiny::tags$strong(fpa_screen("anom_wws_why")), " ", fpa_screen("anom_books_why")),
              shiny::tags$p(style = "margin:0;line-height:1.4;", shiny::tags$strong(fpa_screen("anom_wws_so")), " ", fpa_screen("anom_books_so"))
            )
          } else if (!nrow(sl)) {
            shiny::tags$p(style = "margin:0;line-height:1.45;color:#3d4c54;", fact)
          } else {
            shiny::tags$ul(
              style = "margin:0;padding-left:1.1rem;line-height:1.45;",
              lapply(seq_len(nrow(sl)), function(i) {
                gap <- sl$gap[[i]]
                col <- if (is.finite(gap) && gap < 0 && g$id != "ratio") "#8c3a3a" else "#1a2b32"
                shiny::tags$li(
                  id = fpa_anom_row_dom_id(g$id, sl$periode[[i]], sl$line_id[[i]]),
                  class = "fpa-wws",
                  style = paste0("color:", col, ";margin:0 0 10px;"),
                  story(sl[i, , drop = FALSE])
                )
              })
            )
          }
        )
      )
    }
    band <- function(id, title_key, line, groups) {
      n_hit <- sum(vapply(groups, function(g) {
        sum(scan$family == g$id & scan$level != "clear")
      }, integer(1)))
      n_show <- if (identical(id, "hold")) length(groups) else n_hit
      shiny::tags$section(
        class = paste("fpa-anom-cat", paste0("is-", id)),
        shiny::tags$h3(paste0(fpa_screen(title_key), " · ", n_show)),
        shiny::tags$p(class = "fpa-anom-line", line),
        if (!length(groups)) shiny::tags$p(class = "fpa-anom-none", fpa_screen("anom_cat_none")) else lapply(groups, card)
      )
    }
    placed <- lapply(families, function(g) {
      sl_n <- sum(scan$family == g$id & scan$level != "clear")
      g$band <- if (sl_n == 0L) "hold" else if (g$id %in% c("books", "ratio")) "act" else "watch"
      g
    })
    shiny::div(
      class = "fpa-health",
      shiny::tags$p(style = "margin:0.2rem 0 10px;line-height:1.45;color:#3d4c54;", fpa_screen("anom_central")),
      shiny::div(
        id = "anomaly-folds",
        shiny::div(
          class = "fpa-pnl-tools",
          shiny::tags$button(
            type = "button", class = "fpa-fold-icon",
            title = fpa_screen("pnl_fold_open"),
            `aria-label` = fpa_screen("pnl_fold_open"),
            onclick = "this.closest('#anomaly-folds').querySelectorAll('details.fpa-fold').forEach(function(d){ d.open = true })",
            shiny::HTML('<svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true"><path d="M3.2 6.2 8 10.2l4.8-4" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/><path d="M3.2 9.4 8 13.4l4.8-4" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>')
          ),
          shiny::tags$button(
            type = "button", class = "fpa-fold-icon",
            title = fpa_screen("pnl_fold_close"),
            `aria-label` = fpa_screen("pnl_fold_close"),
            onclick = "this.closest('#anomaly-folds').querySelectorAll('details.fpa-fold').forEach(function(d){ d.open = false })",
            shiny::HTML('<svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true"><path d="M3.2 9.8 8 5.8l4.8 4" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/><path d="M3.2 6.6 8 2.6l4.8 4" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>')
          )
        ),
        band("act", "anom_cat_act", fpa_screen("anom_cat_act_line"), Filter(function(g) identical(g$band, "act"), placed)),
        band("watch", "anom_cat_watch", fpa_screen("anom_cat_watch_line", floor_txt), Filter(function(g) identical(g$band, "watch"), placed)),
        band("hold", "anom_cat_hold", fpa_screen("anom_cat_hold_line"), Filter(function(g) identical(g$band, "hold"), placed))
      )
    )
  })

  var_line <- shiny::reactiveVal(NULL)
  var_month <- shiny::reactiveVal("")

  shiny::observeEvent(input$var_pick, {
    pk <- input$var_pick
    ln <- gsub("[^A-Za-z0-9_]", "", as.character(pk$line %||% ""))
    mo <- gsub("[^0-9-]", "", as.character(pk$month %||% ""))
    same_line <- identical(ln, var_line())
    if (nzchar(ln)) var_line(ln)
    if (!nzchar(mo)) {
      var_month("")
    } else if (same_line && identical(mo, var_month())) {
      var_month("")
    } else {
      var_month(mo)
    }
  }, ignoreInit = TRUE)

  cur_line <- shiny::reactive({
    v <- variance_view()
    if (is.null(v) || !nrow(v)) return(NULL)
    present <- unique(as.character(v$line_id))
    sel <- var_line()
    if (!is.null(sel) && sel %in% present) return(sel)
    if ("REV" %in% present) "REV" else c(intersect(fpa_var_line_order, present), present)[[1]]
  })

  cur_sl <- shiny::reactive({
    v <- variance_view()
    ln <- cur_line()
    if (is.null(v) || !nrow(v) || is.null(ln)) return(NULL)
    sl <- v[as.character(v$line_id) == ln, , drop = FALSE]
    if (!nrow(sl)) return(NULL)
    sl <- sl[order(as.character(sl$periode)), , drop = FALSE]
    p <- pack()
    vol <- if (identical(ln, "REV")) tryCatch(fpa_shiny_volumes(p$config, p$paths), error = function(e) NULL) else NULL
    fpa_var_split(sl, vol)
  })

  output$var_hero <- shiny::renderUI(shiny::tagList(
    fpa_var_hero_ui(variance_view()),
    fpa_shiny_season_note(budget_view())
  ))

  output$var_heat <- shiny::renderUI({
    v <- variance_view()
    if (is.null(v) || !nrow(v)) return(NULL)
    p <- pack()
    vol <- tryCatch(fpa_shiny_volumes(p$config, p$paths), error = function(e) NULL)
    fpa_var_heat_ui(v, cur_line(), var_month(), vol)
  })

  output$var_detail_head <- shiny::renderUI({
    sl <- cur_sl()
    if (is.null(sl)) return(NULL)
    ln <- cur_line()
    story <- fpa_var_story(sl)
    note <- variance_save_note()
    shiny::tags$div(
      class = "fpa-var-dhead",
      shiny::tags$div(
        class = "fpa-var-dhead-top",
        shiny::tags$div(
          shiny::tags$h3(fpa_shiny_line_name(ln))
        ),
        shiny::actionButton("save_ecart_arret", fpa_screen("var_rest_save"), class = "fpa-path-btn")
      ),
      shiny::tags$div(class = "fpa-drv-lead", lapply(story, function(s) shiny::tags$p(s))),
      if (nzchar(note)) shiny::tags$p(class = "fpa-var-saved", note)
    )
  })

  output$var_main_cap <- shiny::renderUI({
    sl <- cur_sl()
    if (is.null(sl)) return(NULL)
    mode <- as.character(input$var_mode %||% "gap")
    txt <- if (identical(mode, "level")) {
      paste(c(fpa_screen("var_plot_level_cap"), if (fpa_var_has_split(sl)) fpa_screen("var_plot_level_vol")), collapse = " ")
    } else {
      fpa_screen("var_plot_gap_cap", fpa_shiny_scn_month_lab(sl$periode[[1]]))
    }
    shiny::tags$p(class = "fpa-var-cap", txt)
  })

  output$var_bridge_head <- shiny::renderUI({
    if (is.null(cur_sl())) return(NULL)
    shiny::tags$p(class = "fpa-var-lead", fpa_screen("var_bridge_lead"))
  })

  output$var_bridge_cap <- shiny::renderUI({
    sl <- cur_sl()
    if (is.null(sl)) return(NULL)
    s <- fpa_var_line_sum(sl)
    shiny::tags$p(class = "fpa-var-cap", fpa_screen("var_bridge_tie", fpa_var_eur(s$budget), fpa_var_eur(s$actual), fpa_var_eur_s(s$year)))
