  card_facts <- shiny::reactive(fpa_var_card_facts(variance_view(), cur_sl()))
  fact_out <- function(key) shiny::renderUI(card_facts()[[key]])
  output$var_fact_hero <- fact_out("hero")
  output$var_fact_heat <- fact_out("heat")
  output$var_fact_line <- fact_out("line")
  output$var_fact_pv <- fact_out("pv")
  output$var_fact_bridge <- fact_out("bridge")
  output$var_fact_parts <- fact_out("parts")
  output$var_fact_months <- fact_out("months")
  # The open card hides its sentence with CSS. Shiny would otherwise skip it, so folding would flash empty.
  for (id in c("var_fact_hero", "var_fact_heat", "var_fact_line", "var_fact_pv", "var_fact_bridge", "var_fact_parts", "var_fact_months")) {
    shiny::outputOptions(output, id, suspendWhenHidden = FALSE)
  }

  shiny::observeEvent(input$var_card, {
    v <- variance_view()
    line <- as.character(cur_line() %||% "")
    which <- as.character(input$var_card %||% "")
    if (is.null(v) || !nrow(v) || !nzchar(line)) return()
    sl <- v[v$line_id == line, , drop = FALSE]
    if (!nrow(sl)) return()
    signed_sum <- function(col) {
      if (!col %in% names(sl)) return(0)
      sum(vapply(seq_len(nrow(sl)), function(i) {
        fpa_variance_signed(line, sl[[col]][[i]])
      }, numeric(1)), na.rm = TRUE)
    }
    tot_var <- signed_sum("variance")
    tot_act <- sum(suppressWarnings(as.numeric(sl$actual)), na.rm = TRUE)
    tot_bud <- sum(suppressWarnings(as.numeric(sl$budget)), na.rm = TRUE)
    parts <- list(
      list(id = "price", lab = fpa_screen("var_col_price"), v = signed_sum("price"), note = "var_eq_price"),
      list(id = "volume", lab = fpa_screen("var_col_volume"), v = signed_sum("volume"), note = "var_eq_volume"),
      list(id = "mix", lab = fpa_screen("var_col_mix"), v = signed_sum("mix"), note = "var_eq_mix"),
      list(id = "rate", lab = fpa_screen("var_col_rate"), v = signed_sum("rate"), note = "var_eq_rate"),
      list(id = "head", lab = fpa_screen("var_col_head"), v = signed_sum("headcount"), note = "var_eq_head"),
      list(id = "unexp", lab = fpa_screen("var_col_unexplained"), v = signed_sum("unexplained"), note = "var_eq_unexp")
    )
    shown <- Filter(function(p) is.finite(p$v) && abs(p$v) > 0.5, parts)
    hit <- if (identical(which, "total")) NULL else {
      keep <- Filter(function(p) identical(p$id, which), parts)
      if (length(keep)) keep[[1]] else NULL
    }
    is_fc <- if ("status" %in% names(sl)) as.character(sl$status) == "forecast" else rep(FALSE, nrow(sl))
    signed_part <- function(keep) {
      if (!any(keep)) return(0)
      sum(vapply(which(keep), function(i) fpa_variance_signed(line, sl$variance[[i]]), numeric(1)), na.rm = TRUE)
    }
    year_lab <- if (any(is_fc)) fpa_screen("var_card_year") else fpa_screen("var_card_total")
    title <- if (is.null(hit)) year_lab else hit$lab
    note <- if (is.null(hit)) fpa_screen("var_eq_total") else fpa_screen(hit$note)
    act_lab <- if (any(is_fc)) fpa_screen("var_col_landing") else fpa_screen("var_col_actual")
    eur <- function(x) {
      s <- fpa_shiny_eur(abs(x))
      if (is.finite(x) && x < -0.5) s <- paste0("\u2212", s)
      paste(s, "EUR")
    }
    bits <- list(fpa_shiny_scn_pair(eur(tot_var), year_lab), "=")
    for (i in seq_along(shown)) {
      if (i > 1L) bits[[length(bits) + 1L]] <- "+"
      bits[[length(bits) + 1L]] <- fpa_shiny_scn_pair(eur(shown[[i]]$v), shown[[i]]$lab)
    }
    sign <- fpa_pnl_ni_sign(line)
    gap_bits <- if (is.finite(sign) && sign < 0) {
      list(
        fpa_shiny_scn_pair(eur(tot_bud), fpa_screen("var_col_budget")),
        "\u2212",
        fpa_shiny_scn_pair(eur(tot_act), act_lab),
        "=",
        fpa_shiny_scn_pair(eur(tot_var), fpa_screen("var_col_variance"))
      )
    } else {
      list(
        fpa_shiny_scn_pair(eur(tot_act), act_lab),
        "\u2212",
        fpa_shiny_scn_pair(eur(tot_bud), fpa_screen("var_col_budget")),
        "=",
        fpa_shiny_scn_pair(eur(tot_var), fpa_screen("var_col_variance"))
      )
    }
    keys <- c("pnl_actuals", "pnl_monthly", "budget")
    if (line %in% c("REV", "PAYROLL")) keys <- c(keys, "ops_other")
    files <- fpa_shiny_scn_files_for(pack()$config, keys)
    file_rows <- lapply(files, function(f) {
      name <- basename(f$path)
      safe <- gsub("[^A-Za-z0-9._-]", "", name)
      shiny::tags$tr(
        shiny::tags$td(
          shiny::tags$button(
            type = "button",
            class = "fpa-file-link",
            onclick = sprintf(
              "Shiny.setInputValue('oi_file',{periode:'',file:'%s',kind:'pnl',line:'%s'},{priority:'event'})",
              safe, gsub("[^A-Za-z0-9_]", "", line)
            ),
            name
          )
        ),
        shiny::tags$td(f$role)
      )
    })
    shiny::showModal(shiny::modalDialog(
      title = title,
      easyClose = TRUE,
      size = "l",
      footer = shiny::modalButton(fpa_screen("scn_close")),
      fpa_shiny_scn_trace_style(),
      shiny::div(
        class = "fpa-scn-trace",
        shiny::tags$p(style = "margin:0 0 12px;line-height:1.45;color:#3d4c54;", note),
        if (length(shown)) fpa_shiny_scn_align_ui(bits),
        fpa_shiny_scn_align_ui(gap_bits),
        if (any(is_fc) && any(!is_fc)) fpa_shiny_scn_align_ui(list(
          fpa_shiny_scn_pair(eur(tot_var), year_lab),
          "=",
          fpa_shiny_scn_pair(eur(signed_part(!is_fc)), fpa_screen("var_part_actual", fpa_shiny_scn_span(sl$periode[!is_fc]))),
          "+",
          fpa_shiny_scn_pair(eur(signed_part(is_fc)), fpa_screen("var_part_fc", fpa_shiny_scn_span(sl$periode[is_fc])))
        )),
        if (length(file_rows)) shiny::tagList(
          shiny::tags$h4(style = "margin:4px 0 8px;font-size:14px;color:#1f4e5f;", fpa_screen("scn_trace_files")),
          shiny::tags$table(
            shiny::tags$thead(shiny::tags$tr(
              shiny::tags$th(fpa_screen("scn_th_file")),
              shiny::tags$th(fpa_screen("scn_th_role"))
            )),
            shiny::tags$tbody(file_rows)
          )
        )
      )
    ))
  }, ignoreInit = TRUE)

