  if (FPA_HAS_PLOTLY) {
    output$plot_var_main <- plotly::renderPlotly({
      sl <- cur_sl()
      if (is.null(sl)) return(plotly::plotly_empty())
      fpa_var_main_fig(sl, as.character(input$var_mode %||% "gap"), var_month())
    })
    output$plot_var_bridge <- plotly::renderPlotly({
      sl <- cur_sl()
      if (is.null(sl)) return(plotly::plotly_empty())
      fpa_var_bridge_fig(fpa_var_bridge_frame(sl))
    })
    output$plot_var_pv <- plotly::renderPlotly({
      sl <- cur_sl()
      fig <- if (is.null(sl)) NULL else fpa_var_pv_fig(sl, var_month())
      if (is.null(fig)) return(plotly::plotly_empty())
      fig
    })
    output$plot_impact_span <- plotly::renderPlotly({
      d <- pack()$finance$driver_impact
      s <- pack()$finance$sensitivity
      names_v <- character(0)
      eur_v <- numeric(0)
      if (!is.null(d) && nrow(d) && ("eur" %in% names(d))) {
        names_v <- c(names_v, as.character(d$series_id %||% d$target_line))
        eur_v <- c(eur_v, as.numeric(d$eur))
      }
      if (!is.null(s) && nrow(s) && ("oi_span" %in% names(s))) {
        names_v <- c(names_v, as.character(s$assumption_id))
        eur_v <- c(eur_v, as.numeric(s$oi_span))
      }
      ok <- is.finite(eur_v)
      if (!length(names_v) || !any(ok)) return(plotly::plotly_empty())
      names_v <- names_v[ok]
      eur_v <- eur_v[ok]
      ord <- order(abs(eur_v), decreasing = TRUE)
      cols <- ifelse(eur_v[ord] >= 0, "#1f4e5f", "#8c3a3a")
      p <- plotly::plot_ly(x = names_v[ord], y = eur_v[ord], type = "bar",
                           marker = list(color = cols))
      plotly::layout(p, title = fpa_screen("imp_span_title"),
                     yaxis = list(title = "EUR"), xaxis = list(title = ""))
    })
    output$plot_sensitivity <- plotly::renderPlotly({
      s <- pack()$finance$sensitivity
      if (is.null(s) || !nrow(s) || !"oi_span" %in% names(s)) return(plotly::plotly_empty())
      ord <- order(abs(s$oi_span), decreasing = TRUE)
      s <- s[ord, , drop = FALSE]
      cols <- ifelse(s$oi_span >= 0, "#1f4e5f", "#8c3a3a")
      p <- plotly::plot_ly(x = s$assumption_id, y = s$oi_span, type = "bar",
                           marker = list(color = cols))
      plotly::layout(p, title = fpa_screen("loc_oi_sensitivity"),
                     yaxis = list(title = "EUR"), xaxis = list(title = ""))
    })
  } else {
    output$plot_var_main <- shiny::renderPlot({
      sl <- cur_sl()
      if (is.null(sl)) return(invisible(NULL))
      line <- as.character(sl$line_id[[1]])
      y <- fpa_var_sg(line, sl$variance)
      y[!is.finite(y)] <- 0
      fc <- fpa_var_is_fc(sl)
      cols <- ifelse(y >= 0, "#1f4e5f", "#8c3a3a")
      cols[fc] <- ifelse(y[fc] >= 0, "#9fb9c2", "#d3b0b0")
      graphics::barplot(y, names.arg = fpa_var_month_abbr(sl$periode), col = cols, border = NA, las = 2, ylab = "EUR")
      graphics::abline(h = 0, col = "#5c6b73")
    })
    output$plot_var_bridge <- shiny::renderPlot({
      sl <- cur_sl()
      if (is.null(sl)) return(invisible(NULL))
      bf <- fpa_var_bridge_frame(sl)
      if (is.null(bf)) return(invisible(NULL))
      cols <- ifelse(bf$kind == "total", "#0f2f3a", ifelse(bf$signed >= 0, "#1f4e5f", "#8c3a3a"))
      lo <- pmin(bf$start, bf$end)
      hi <- pmax(bf$start, bf$end)
      n <- nrow(bf)
      graphics::plot(NA, xlim = c(0.5, n + 0.5), ylim = range(c(0, lo, hi)), xaxt = "n", xlab = "", ylab = "EUR")
      graphics::rect(seq_len(n) - 0.35, lo, seq_len(n) + 0.35, hi, col = cols, border = NA)
      graphics::axis(1, at = seq_len(n), labels = bf$label, las = 2, cex.axis = 0.7)
    })
    output$plot_var_pv <- shiny::renderPlot({
      sl <- cur_sl()
      f <- if (is.null(sl)) NULL else fpa_var_pv_frame(sl)
      if (is.null(f)) return(invisible(NULL))
      r <- f$rows
      m <- rbind(r$volume, r$price, r$mix)
      graphics::barplot(
        m, beside = TRUE, border = NA, las = 2, ylab = "EUR",
        col = c("#1f4e5f", "#c47b2b", "#3b6fb6"),
        names.arg = fpa_var_month_abbr(r$periode),
        legend.text = c(fpa_screen("var_col_volume"), fpa_screen("var_col_price"), fpa_screen("var_col_mix"))
      )
      graphics::abline(h = 0, col = "#5c6b73")
    })
    output$plot_impact_span <- shiny::renderPlot({
      d <- pack()$finance$driver_impact
      s <- pack()$finance$sensitivity
      names_v <- character(0)
      eur_v <- numeric(0)
      if (!is.null(d) && nrow(d) && ("eur" %in% names(d))) {
        names_v <- c(names_v, as.character(d$series_id %||% d$target_line))
        eur_v <- c(eur_v, as.numeric(d$eur))
      }
      if (!is.null(s) && nrow(s) && ("oi_span" %in% names(s))) {
        names_v <- c(names_v, as.character(s$assumption_id))
        eur_v <- c(eur_v, as.numeric(s$oi_span))
      }
      ok <- is.finite(eur_v)
      if (!length(names_v) || !any(ok)) {
        plot.new()
        title(fpa_screen("imp_span_empty"))
        return(invisible(NULL))
      }
      names_v <- names_v[ok]
      eur_v <- eur_v[ok]
      ord <- order(abs(eur_v), decreasing = TRUE)
      cols <- ifelse(eur_v[ord] >= 0, "#1f4e5f", "#8c3a3a")
      barplot(eur_v[ord], names.arg = names_v[ord], col = cols, las = 2, ylab = "EUR",
              main = fpa_screen("imp_span_title"))
      abline(h = 0)
    })
    output$plot_sensitivity <- shiny::renderPlot({
      s <- pack()$finance$sensitivity
      if (is.null(s) || !nrow(s) || !"oi_span" %in% names(s)) return(invisible(NULL))
      ord <- order(abs(s$oi_span), decreasing = TRUE)
      s <- s[ord, , drop = FALSE]
      cols <- ifelse(s$oi_span >= 0, "#1f4e5f", "#8c3a3a")
      barplot(s$oi_span, names.arg = s$assumption_id, las = 2, col = cols,
              ylab = "EUR", main = fpa_screen("loc_oi_sensitivity_ascii"))
      abline(h = 0)
    })
  }


  #' Levers offered: enabled assumption_keys, plus scenario_lines from the same JSON.
  scenario_levers <- shiny::reactive({
    p <- pack()
    keys <- tryCatch(fpa_enabled_assumptions(p$config), error = function(e) list())
    ids <- if (length(keys)) vapply(keys, function(k) as.character(k$id), character(1)) else character(0)
    assum <- tryCatch(fpa_read_assumptions(p$config, p$paths), error = function(e) NULL)
    wide <- if (!is.null(assum) && isTRUE(assum$ok)) assum$wide else NULL
    base <- tryCatch(fpa_scenario_base_values(wide, ids), error = function(e) list())
    keys <- keys[ids %in% names(base)]
    ids <- ids[ids %in% names(base)]
    lines <- tryCatch(
      fpa_scenario_lines(p$config, names(p$finance$pnl %||% list())),
      error = function(e) list(ids = character(0), spec = list())
    )
    list(ids = ids, keys = keys, base = base, lines = lines$ids, line_spec = lines$spec)
  })

  output$impact_ui <- shiny::renderUI({
    lv <- scenario_levers()
    if (!length(lv$ids) && !length(lv$lines)) {
      return(shiny::tags$p(fpa_screen("loc_no_lever_pnl")))
    }
    day_ids <- lv$ids[vapply(lv$ids, function(i) {
      identical(fpa_scenario_lever_spec(i, fpa_scenario_find(lv$keys, i))$kind, "days")
    }, logical(1))]
    other_ids <- setdiff(lv$ids, day_ids)
    slider <- function(id, label, spec) {
      shiny::sliderInput(
        paste0("lev_", id), label,
        min = spec$min, max = spec$max, value = 0, step = spec$step,
        post = spec$unit, ticks = TRUE, width = "230px"
      )
    }
    shiny::tagList(
      shiny::tags$style(HTML("
        .tab-pane:has(.fpa-scn) { height:auto !important; overflow:visible !important; }
        .fpa-scn { padding-bottom:2rem; }
        .fpa-scn .irs--shiny .irs-bar, .fpa-scn .irs--shiny .irs-handle > i:first-child { background:#1f4e5f; }
        .fpa-scn .irs--shiny .irs-single, .fpa-scn .irs--shiny .irs-from, .fpa-scn .irs--shiny .irs-to { background:#1f4e5f; }
        .fpa-scn .shiny-input-container { margin-bottom:0.2rem; }
        .fpa-kpi { display:flex; flex-wrap:wrap; gap:10px; margin:0.2rem 0 0.4rem; }
        .fpa-kpi button.fpa-kpi-card {
          flex:1 1 150px; border:1px solid #d6e1e5; border-radius:10px; padding:10px 12px;
          background:#fff; text-align:left; font:inherit; cursor:pointer;
        }
        .fpa-kpi button.fpa-kpi-card:hover, .fpa-kpi button.fpa-kpi-card:focus {
          outline:2px solid #1f4e5f; outline-offset:2px;
        }
        .fpa-kpi-card .k { font-size:11px; letter-spacing:0.02em; text-transform:uppercase; color:#5c6b73; }
        .fpa-kpi-card .v { font-size:19px; font-weight:700; color:#1f4e5f; font-variant-numeric:tabular-nums; }
        .fpa-kpi-card .s { font-size:11.5px; color:#5c6b73; }
        .fpa-kpi-card.warn { border-color:#e0cba8; background:#fdf6ea; }
        .fpa-kpi-card.warn .v { color:#8c3a3a; }
        #impact_extras, #impact_extras .html-fill-item, #impact_extras .html-fill-container {
          height:auto !important; overflow:visible !important; flex:0 0 auto !important;
        }
        #impact_extras .js-plotly-plot, #impact_extras .plot-container, #impact_extras .svg-container {
          width:100% !important; max-width:none !important;
        }
        .fpa-scn-chart { display:flex; align-items:flex-end; gap:14px; min-height:168px; margin:0.2rem 0 0; }
        .fpa-scn-col { flex:1 1 0; min-width:72px; max-width:140px; display:flex; flex-direction:column; align-items:center; }
        .fpa-scn-col.is-click { cursor:pointer; border-radius:8px; padding:4px 2px; }
        .fpa-scn-col.is-click:hover, .fpa-scn-col.is-click:focus {
          outline:2px solid #1f4e5f; outline-offset:2px;
        }
        .fpa-scn-val { font-size:12px; font-weight:700; font-variant-numeric:tabular-nums; color:#1f4e5f; margin-bottom:4px; }
        .fpa-scn-val.neg { color:#8c3a3a; }
        .fpa-scn-track { position:relative; width:36px; height:120px; }
        .fpa-scn-zero { position:absolute; left:0; right:0; top:50%; height:1px; background:#c5d0d4; }
        .fpa-scn-fill { position:absolute; left:4px; right:4px; border-radius:3px; }
        .fpa-scn-fill.up { bottom:50%; background:#1f4e5f; }
        .fpa-scn-fill.down { top:50%; background:#8c3a3a; }
        .fpa-scn-tm { margin-top:4px; font-size:11px; color:#5c6b73; font-variant-numeric:tabular-nums; }
        .fpa-scn-time { display:flex; align-items:center; gap:0; }
        .fpa-scn-mark {
          display:inline-flex; align-items:center; justify-content:center;
          width:16px; flex:0 0 16px; height:1em;
        }
        .fpa-scn-now {
          display:inline-block; width:8px; height:8px; border-radius:50%;
          background:#2e7d4f; vertical-align:middle;
        }
        .fpa-scn-at { font-variant-numeric:tabular-nums; }
        .fpa-scn-webs-wrap { container-type: inline-size; width: 100%; }
        .fpa-scn-webs {
          display: grid; grid-template-columns: repeat(2, minmax(0, 1fr));
          gap: 8px 12px; width: 100%;
        }
        @container (min-width: 960px) {
          .fpa-scn-webs { grid-template-columns: repeat(5, minmax(0, 1fr)); }
        }
        @media (max-width: 899px) {
          .fpa-scn-webs { grid-template-columns: repeat(2, minmax(0, 1fr)); }
        }
        @media (min-width: 1100px) {
          .fpa-scn-webs { grid-template-columns: repeat(5, minmax(0, 1fr)); }
        }
        .fpa-scn-web { display:flex; flex-direction:column; align-items:center; min-width:0; }
        .fpa-scn-web.is-click { cursor:pointer; border-radius:10px; padding:4px; }
        .fpa-scn-web.is-click:hover, .fpa-scn-web.is-click:focus {
          outline:2px solid #1f4e5f; outline-offset:2px;
        }
        .fpa-scn-web-svg { width:100%; height:auto; max-width:240px; display:block; }
        .fpa-scn-web-time { font-size:11px; color:#5c6b73; font-variant-numeric:tabular-nums; }
        .fpa-scn-web-gap {
