        .fpa-scn-board {
          border:1px solid #d6e1e5; border-radius:12px; background:#f4f8f9;
          padding:0; margin:0 0 12px;
        }
        .fpa-scn-board > summary {
          display:grid; grid-template-columns:12px minmax(0,1fr); column-gap:10px;
