        .fpa-scn-board:not([open]) > summary { padding-bottom:14px; }
        .fpa-scn-board > summary::-webkit-details-marker { display:none; }
        .fpa-scn-board > summary::marker { content:''; font-size:0; }
        .fpa-scn-board > summary::before {
          content:''; width:0; height:0; justify-self:center;
          border-style:solid; border-width:5px 0 5px 7px;
          border-color:transparent transparent transparent #1f4e5f;
        }
        .fpa-scn-board[open] > summary::before {
