        .fpa-scn-board-do { margin:0 16px 12px 34px; color:#3d4c54; font-size:13px; line-height:1.4; }
        .fpa-scn-dials { display:flex; flex-wrap:wrap; gap:22px; align-items:flex-start; padding:0 16px 0 34px; }
        .fpa-scn-dial-col { flex:1 1 210px; min-width:200px; }
