        .fpa-scn-floor-ex { margin:4px 0 10px; color:#1a2b32; font-size:13.5px; line-height:1.45; }
        .fpa-scn-floor .shiny-input-container { width:160px !important; margin:4px 0 0; }
        .fpa-scn-floor .control-label { font-weight:700; color:#1f4e5f; font-size:13px; }
        .fpa-scn-sens {
          margin:0 0 12px; border:1px solid #e6edef; border-radius:10px;
          background:#fff; padding:8px 12px;
        }
        .fpa-scn-sens > summary {
