        .fpa-obj-mix .mix-moves { flex:1 1 180px; font-size:13px; color:#0f2f3a; line-height:1.35; }
        .fpa-obj-mix .mix-val { font-size:12px; color:#5c6b73; white-space:nowrap; }
        .fpa-obj { padding:11px 14px; }
        .fpa-obj > p, .fpa-obj .fpa-obj-help { margin:11px 0; line-height:1.55; }
        .fpa-obj-controls {
          display:flex; flex-wrap:wrap; gap:16px 0; align-items:flex-start; margin:12px 0 14px;
        }
        .fpa-obj-controls > .form-group { margin-right:28px; }
        .fpa-obj-ask {
          flex:1 1 auto; align-self:center;
          display:flex; align-items:center; justify-content:center; gap:14px;
          min-height:34px;
        }
        .fpa-obj-ask .shiny-input-container { display:contents; }
        .fpa-obj-controls .fpa-obj-ask .control-label {
          margin:0; white-space:nowrap; line-height:1;
          height:34px; display:inline-flex; align-items:center;
        }
        .fpa-obj-ask input.form-control {
          width:9rem; height:34px; margin:0; padding-top:0; padding-bottom:0;
        }
        .fpa-obj-ask .fpa-obj-run { display:flex; align-items:center; margin:0; }
        .fpa-obj-ask .btn {
          height:34px; display:inline-flex; align-items:center;
          padding:0 16px; margin:0;
        }
        .fpa-obj-controls .form-group,
        .fpa-obj-controls .shiny-input-container { margin-bottom:0; }
        .fpa-obj-controls .control-label {
          font-weight:700; color:#1f4e5f; font-size:14px; margin:0 0 6px; line-height:1.2;
        }
        .fpa-obj-controls .radio-inline { margin-top:0; padding-top:2px; }
        .fpa-obj-metric-head {
          display:flex; justify-content:space-between; align-items:baseline;
          gap:16px; padding:0 12px; margin:0 0 6px;
        }
        .fpa-obj-metric-head span:first-child {
          font-weight:700; color:#1f4e5f; font-size:14px; margin:0; line-height:1.2;
        }
        .fpa-obj-metric-head .fpa-obj-now-cap {
          font-weight:600; font-size:13px; color:#5c6b73; margin:0;
        }
        .fpa-obj-row {
          display:flex; align-items:center; gap:14px;
          border:1px solid #b7c9cf; border-radius:8px; background:#f7fbfc;
          padding:6px 12px; margin:0 0 8px; cursor:pointer; font-weight:400;
        }
        .fpa-obj-row.is-on,
        .fpa-obj-row:has(input:checked) { border-color:#1f4e5f; background:#f4f8f9; }
        .fpa-obj-row input { margin:0 2px 0 0; flex:0 0 auto; }
        .fpa-obj-row-lab { flex:1 1 auto; color:#0f2f3a; }
        .fpa-obj-fy { margin:6px 0 0 !important; font-size:12.5px; color:#5c6b73; line-height:1.45; }
        .fpa-obj-sens-note {
          margin:6px 0 10px; padding:6px 10px; font-size:12.5px; line-height:1.45;
          color:#3d4c54; background:#f4f8f9; border-left:3px solid #1f4e5f; border-radius:0 8px 8px 0;
        }
        .fpa-obj-row-val {
          font-weight:700; color:#0f2f3a; font-variant-numeric:tabular-nums; white-space:nowrap;
        }
        .fpa-obj-row-val.neg { color:#8c3a3a; }
        .fpa-obj-run { align-self:center; }
        .fpa-obj .fpa-obj-levers { margin:8px 0 12px; }
        .fpa-obj .fpa-obj-levers .checkbox,
        .fpa-obj .fpa-obj-levers .checkbox-inline,
        .fpa-obj .fpa-obj-levers .form-check { margin:4px 16px 4px 0; }
        .fpa-obj-anchor { margin:8px 0 10px; max-width:42rem; }
        .fpa-obj-anchor p {
          margin:0 0 4px; font-size:13px; line-height:1.5; color:#3d4c54;
          font-variant-numeric:tabular-nums;
        }
        .fpa-obj-anchor p.pos { color:#1f4e5f; }
        .fpa-obj-anchor p.neg { color:#8c3a3a; }
      ")),
      shiny::div(
        class = "fpa-scn",
        shiny::tags$p(
          style = "margin:0 0 0.7rem;line-height:1.45;",
          fpa_screen("scn_apply_lead")
        ),
        shiny::uiOutput("scenario_kpi"),
        shiny::tags$details(
          class = "fpa-fold fpa-scn-floor",
          shiny::tags$summary(
            shiny::tags$span(class = "fpa-fold-k", fpa_screen("scn_floor_title")),
            shiny::tags$span(class = "fpa-fold-fact", fpa_screen("scn_floor_fact"))
          ),
          shiny::div(
            class = "fpa-fold-body fpa-scn-floor-body",
            shiny::tags$p(class = "fpa-scn-floor-h", fpa_screen("scn_floor_moves")),
            shiny::tags$ul(
              shiny::tags$li(fpa_screen("scn_floor_m1")),
              shiny::tags$li(fpa_screen("scn_floor_m2")),
              shiny::tags$li(fpa_screen("scn_floor_m3")),
              shiny::tags$li(fpa_screen("scn_floor_m4"))
            ),
            shiny::tags$p(class = "fpa-scn-floor-h", fpa_screen("scn_floor_stays")),
            shiny::tags$ul(
              shiny::tags$li(fpa_screen("scn_floor_s1")),
              shiny::tags$li(fpa_screen("scn_floor_s2")),
              shiny::tags$li(fpa_screen("scn_floor_s3"))
            ),
            shiny::tags$p(class = "fpa-scn-floor-ex", fpa_screen("scn_floor_ex")),
            shiny::numericInput(
              "cash_floor", fpa_screen("scn_floor_label"),
              value = fpa_cash_floor_read(pack()$config), step = 1000, width = "160px"
            )
          )
        ),
        shiny::tags$details(
          class = "fpa-scn-board",
          open = "open",
          shiny::tags$summary(fpa_screen("scn_board_title")),
          shiny::tags$p(class = "fpa-scn-board-do", fpa_screen("scn_board_do")),
          shiny::div(
            class = "fpa-scn-dials",
            if (length(day_ids)) shiny::div(
              class = "fpa-scn-dial-col",
              shiny::tags$strong(fpa_screen("loc_delays")),
              lapply(day_ids, function(id) {
                row <- fpa_scenario_find(lv$keys, id)
                slider(id, fpa_scenario_label(id, row), fpa_scenario_lever_spec(id, row))
              })
            ),
            if (length(other_ids)) shiny::div(
              class = "fpa-scn-dial-col",
              shiny::tags$strong(fpa_screen("loc_assumptions")),
              lapply(other_ids, function(id) {
                row <- fpa_scenario_find(lv$keys, id)
                slider(id, fpa_scenario_label(id, row), fpa_scenario_lever_spec(id, row))
              })
            ),
            if (length(lv$lines)) shiny::div(
              class = "fpa-scn-dial-col",
              shiny::tags$strong(fpa_screen("loc_lines_forecast_months")),
              lapply(lv$lines, function(nm) {
                range <- lv$line_spec[[nm]] %||% list(min = -20, max = 20, step = 5)
                line_step <- fpa_objectif_line_step(range$step)
                shiny::sliderInput(
                  paste0("line_", nm), fpa_shiny_line_name(nm),
                  min = range$min, max = range$max, value = 0, step = line_step,
                  post = " %", ticks = line_step >= 5, width = "230px"
                )
              })
            )
          ),
          shiny::div(
            class = "fpa-scn-actions",
            shiny::actionButton(
              "scn_apply", fpa_screen("scn_apply"),
              style = "background:#1f4e5f;color:#fff;border:1px solid #1f4e5f;"
            ),
            shiny::actionButton(
              "scenario_reset", fpa_screen("scn_reset"),
              style = "background:#fff;color:#1f4e5f;border:1px solid #1f4e5f;"
            ),
            shiny::actionButton(
              "journal_save_last_scn", fpa_screen("journal_save_scenario"),
              style = "background:#fff;color:#1f4e5f;border:1px solid #1f4e5f;"
            )
          )
        ),
          shiny::tags$details(
            class = "fpa-scn-sens fpa-obj", open = "open",
            shiny::tags$summary(fpa_screen("obj_sum")),
            shiny::uiOutput("obj_help_ui"),
            shiny::div(
              class = "fpa-obj-controls",
              shiny::radioButtons(
                "obj_mode", fpa_screen("obj_mode"),
                choices = stats::setNames(
                  c("manual", "auto"),
                  c(fpa_screen("obj_mode_manual"), fpa_screen("obj_mode_auto"))
                ),
                selected = "manual", inline = TRUE
              ),
              shiny::uiOutput("obj_metric_ui"),
              shiny::div(
                class = "fpa-obj-ask",
                shiny::numericInput(
                  "obj_target", fpa_screen("obj_target"),
                  value = NA_real_, step = 1000, width = "100%"
                ),
                shiny::uiOutput("obj_run_btn")
              )
            ),
            shiny::uiOutput("obj_anchor"),
            shiny::conditionalPanel(
              condition = "input.obj_mode == 'manual'",
              shiny::div(
                class = "fpa-obj-levers",
                style = "margin:4px 0 8px;",
                shiny::div(
                  class = "fpa-obj-lever-bar",
                  shiny::tags$span(class = "fpa-obj-lever-title", fpa_screen("obj_levers")),
                  shiny::actionButton("obj_levers_all", fpa_screen("obj_levers_all")),
                  shiny::actionButton("obj_levers_none", fpa_screen("obj_levers_none"))
                ),
                shiny::checkboxGroupInput(
                  "obj_levers", NULL,
                  choices = {
                    labs <- character(0)
                    vals <- character(0)
                    for (id in lv$ids) {
                      row <- fpa_scenario_find(lv$keys, id)
                      labs <- c(labs, fpa_scenario_label(id, row))
                      vals <- c(vals, paste0("assum:", id))
                    }
                    for (nm in lv$lines) {
                      labs <- c(labs, fpa_shiny_line_name(nm))
                      vals <- c(vals, paste0("line:", nm))
                    }
                    if (!length(vals)) character(0) else stats::setNames(vals, labs)
                  },
                  selected = if ("REV" %in% (lv$lines %||% character(0))) "line:REV" else character(0),
                  inline = TRUE
                )
              )
            ),
            shiny::uiOutput("obj_result"),
            shiny::uiOutput("obj_mixes_ui")
          ),
          shiny::tags$details(
          class = "fpa-scn-sens",
          shiny::tags$summary(fpa_screen("scn_sens_sum")),
          shiny::tags$p(fpa_screen("scn_sens_help")),
          shiny::actionButton(
            "run_sensitivity", fpa_screen("scn_sens_btn"),
            style = "background:#1f4e5f;color:#fff;border:1px solid #1f4e5f;border-radius:8px;font-weight:600;"
          )
        ),
        shiny::uiOutput("scenario_moves"),
        shiny::verbatimTextOutput("scenario_result"),
        shiny::uiOutput("scn_log_ui")
      )
    )
  })

  #' Sliders are read on the click only. A drag does not run the engine.
  scn_log <- shiny::reactiveVal(list())
  obj_note <- shiny::reactiveVal(NULL)
  obj_mixes <- shiny::reactiveVal(list())

  obj_lever_ids <- function() {
    lv <- scenario_levers()
    vals <- character(0)
    for (id in lv$ids %||% character(0)) vals <- c(vals, paste0("assum:", id))
    for (nm in lv$lines %||% character(0)) vals <- c(vals, paste0("line:", nm))
    vals
  }

  shiny::observeEvent(input$obj_levers_all, {
    vals <- obj_lever_ids()
    if (!length(vals)) return()
    shiny::updateCheckboxGroupInput(session, "obj_levers", selected = vals)
  })

  shiny::observeEvent(input$obj_levers_none, {
    shiny::updateCheckboxGroupInput(session, "obj_levers", selected = character(0))
  })

  output$obj_help_ui <- shiny::renderUI({
    mode <- as.character(input$obj_mode %||% "manual")
    shiny::tags$p(class = "fpa-obj-help", if (identical(mode, "auto")) fpa_screen("obj_help_auto") else fpa_screen("obj_help_manual"))
  })

  output$obj_metric_ui <- shiny::renderUI({
    p <- pack()
    selected <- shiny::isolate(as.character(input$obj_metric %||% "cash_ye"))
    if (!selected %in% FPA_OBJ_METRICS) selected <- "cash_ye"
    ye <- NULL
    books <- NULL
    info <- NULL
    if (isTRUE(p$ok)) {
      info <- fpa_shiny_obj_info(p)
      ye <- info$close
      books <- list(cash = p$finance$cash, pnl = p$finance$pnl)
    }
    row <- function(metric, label) {
      v <- if (is.null(books)) NA_real_ else fpa_objectif_read(books, metric, ye)
      neg <- is.finite(v) && v < -0.5
      shown <- if (!is.finite(v)) "\u2013" else paste0(fpa_shiny_eur(v), " EUR")
      on <- identical(selected, metric)
      shiny::tags$label(
        class = "fpa-obj-row",
        shiny::tags$input(
          type = "radio", name = "obj_metric", value = metric,
          checked = if (on) "checked" else NULL
        ),
        shiny::tags$span(class = "fpa-obj-row-lab", label),
        shiny::tags$span(class = if (neg) "fpa-obj-row-val neg" else "fpa-obj-row-val", shown)
      )
    }
    shiny::div(
      id = "obj_metric",
      class = "shiny-input-radiogroup",
      shiny::div(
        class = "fpa-obj-metric-head",
        shiny::tags$span(fpa_screen("obj_metric")),
        shiny::tags$span(class = "fpa-obj-now-cap", fpa_screen("obj_now_cap"))
      ),
      row("cash_ye", fpa_shiny_obj_metric_lab("cash_ye", info)),
      row("oi_fy", fpa_shiny_obj_metric_lab("oi_fy", info)),
      row("oi_ye", fpa_shiny_obj_metric_lab("oi_ye", info)),
      if (!is.null(info)) shiny::tags$p(class = "fpa-obj-fy", fpa_shiny_obj_fy_note(info))
    )
  })

  output$obj_anchor <- shiny::renderUI({
    p <- pack()
    if (!isTRUE(p$ok)) return(NULL)
    metric <- as.character(input$obj_metric %||% "cash_ye")
    if (!metric %in% FPA_OBJ_METRICS) metric <- "cash_ye"
    ye <- fpa_shiny_obj_info(p)$close
    base_v <- fpa_objectif_read(
      list(cash = p$finance$cash, pnl = p$finance$pnl),
      metric, ye
    )
    if (!is.finite(base_v)) return(NULL)
    target <- suppressWarnings(as.numeric(input$obj_target))
    if (!is.finite(target)) return(NULL)
    eur_txt <- function(v) {
      s <- fpa_shiny_eur(abs(v))
      if (is.finite(v) && v < -0.5) s <- paste0("\u2212", s)
      s
    }
    gap <- target - base_v
    both_pos <- base_v > 0.5 && target > 0.5
    pct_line <- if (both_pos) {
      NULL
    } else if (abs(base_v) < 0.5) {
      shiny::tags$p(fpa_screen("obj_anchor_pct_undef"))
    } else if (abs(gap) < 0.5) {
      shiny::tags$p(fpa_screen("obj_anchor_level"))
    } else if (gap > 0) {
      shiny::tags$p(class = "pos", fpa_screen("obj_anchor_span_up", eur_txt(base_v), eur_txt(target), eur_txt(gap)))
    } else {
      shiny::tags$p(class = "neg", fpa_screen("obj_anchor_span_down", eur_txt(base_v), eur_txt(target), eur_txt(abs(gap))))
    }
    if (both_pos) {
      pct <- fpa_objectif_pct(target, base_v)
      sign <- if (pct > 0.05) "+" else if (pct < -0.05) "\u2212" else ""
      num <- formatC(abs(pct), format = "f", digits = 1, decimal.mark = ",")
      cls <- if (pct < -0.05) "neg" else if (pct > 0.05) "pos" else NULL
      pct_line <- shiny::tags$p(class = cls, fpa_screen("obj_anchor_pct", paste0(sign, num)))
    }
    shiny::div(class = "fpa-obj-anchor", pct_line)
  })

  output$obj_run_btn <- shiny::renderUI({
    mode <- as.character(input$obj_mode %||% "manual")
    lab <- if (identical(mode, "auto")) fpa_screen("obj_run_auto") else fpa_screen("obj_run")
    shiny::div(
      class = "fpa-obj-run",
      shiny::actionButton(
        "obj_run", lab,
        style = "background:#1f4e5f;color:#fff;border:1px solid #1f4e5f;border-radius:8px;font-weight:600;"
      )
    )
  })

  output$obj_result <- shiny::renderUI({
    note <- obj_note()
    if (is.null(note) || !nzchar(note$text %||% "")) return(NULL)
    col <- if (isTRUE(note$ok)) "#1f4e5f" else "#8c3a3a"
    shiny::tagList(
      shiny::tags$p(style = paste0("margin:8px 0 0;line-height:1.45;color:", col, ";"), note$text),
      if (isTRUE(note$line_move)) shiny::tags$p(class = "fpa-obj-sens-note", fpa_screen("obj_line_sens"))
