  output$obj_mixes_ui <- shiny::renderUI({
    if (!identical(as.character(input$obj_mode %||% "manual"), "auto")) return(NULL)
    mixes <- obj_mixes()
    if (!length(mixes)) return(NULL)
    lv <- scenario_levers()
    if (is.null(lv)) return(NULL)
    eur <- function(x) if (!is.finite(x)) "—" else fpa_shiny_eur(x)
    rows <- lapply(seq_along(mixes), function(i) {
      m <- mixes[[i]]
      gap <- m$gap
      gap_s <- if (!is.finite(gap)) "—" else paste0(if (gap > 0) "+" else "", eur(gap))
      shiny::div(
        class = "fpa-obj-mix",
        shiny::span(class = "mix-lab", fpa_screen("obj_mix_title", as.character(i))),
        shiny::span(class = "mix-moves", fpa_shiny_obj_move_lab(m$deltas, lv$keys)),
        shiny::span(class = "mix-val", paste0(eur(m$value), " · ", gap_s)),
        shiny::tags$button(
          type = "button",
          class = "btn btn-sm",
          style = "background:#1f4e5f;color:#fff;border:1px solid #1f4e5f;border-radius:8px;font-weight:600;",
          onclick = sprintf("Shiny.setInputValue('obj_apply_mix', %d, {priority:'event'})", i),
          fpa_screen("obj_apply_mix")
        )
      )
    })
    shiny::tagList(rows)
  })

  #' Push solved deltas onto the dials, run the scenario, and append the journal.
  #' Screen names for lever rows (kind + id), lines and assumptions alike.
  obj_lever_labs <- function(lv, rows) {
    labs <- vapply(rows, function(L) {
      if (identical(L$kind, "line")) {
        fpa_shiny_line_name(L$id)
      } else {
        fpa_scenario_label(L$id, fpa_scenario_find(lv$keys, L$id))
      }
    }, character(1))
    labs[nzchar(labs)]
  }
  #' After an unreachable or partial result: the ticked levers that do not move the figure,
  #' then, for an income target, the P&L lines left unticked that would.
  obj_lever_hints <- function(lv, levers, inert, metric) {
    bits <- character(0)
    inert_labs <- obj_lever_labs(lv, inert %||% list())
    if (length(inert_labs)) bits <- c(bits, fpa_screen("obj_inert", paste(inert_labs, collapse = ", ")))
    if (metric %in% c("oi_fy", "oi_ye")) {
      ticked <- vapply(levers, function(L) if (identical(L$kind, "line")) as.character(L$id) else "", character(1))
      left <- setdiff(lv$lines %||% character(0), ticked)
      if (length(left)) {
        rows <- lapply(left, function(nm) list(kind = "line", id = nm))
        labs <- obj_lever_labs(lv, rows)
        if (length(labs)) bits <- c(bits, fpa_screen("obj_try_lines", paste(labs, collapse = ", ")))
      }
    }
    bits
  }
  obj_commit <- function(p, lv, deltas, metric, target, ye, value, gap, note_key, reset_others, inert = list()) {
    now <- fpa_shiny_scn_read(lv, input)
    if (isTRUE(reset_others)) {
      now$assum <- lapply(now$assum, function(x) 0)
      now$lines <- lapply(now$lines, function(x) 0)
      for (id in lv$ids) shiny::updateSliderInput(session, paste0("lev_", id), value = 0)
      for (nm in lv$lines) shiny::updateSliderInput(session, paste0("line_", nm), value = 0)
    }
    for (id in names(deltas$assum %||% list())) {
      d <- suppressWarnings(as.numeric(deltas$assum[[id]]))
      if (!is.finite(d)) next
      now$assum[[id]] <- d
      shiny::updateSliderInput(session, paste0("lev_", id), value = d)
    }
    for (nm in names(deltas$lines %||% list())) {
      d <- suppressWarnings(as.numeric(deltas$lines[[nm]]))
      if (!is.finite(d)) next
      now$lines[[nm]] <- d
      spec <- lv$line_spec[[nm]] %||% list(min = -20, max = 20, step = 5)
      step <- fpa_objectif_line_step(spec$step %||% 1)
      mn <- suppressWarnings(as.numeric(spec$min %||% -20))
      mx <- suppressWarnings(as.numeric(spec$max %||% 20))
      if (!is.finite(mn)) mn <- -20
      if (!is.finite(mx)) mx <- 20
      if (d < mn) mn <- floor(d)
      if (d > mx) mx <- ceiling(d)
      shiny::updateSliderInput(
        session, paste0("line_", nm), min = mn, max = mx, value = d, step = step
      )
    }
    floor <- suppressWarnings(as.numeric(input$cash_floor %||% 0))
    if (!is.finite(floor)) floor <- 0
    scen <- tryCatch(
      fpa_scenario_run(p$config_path, lv$base, now$assum, now$lines, lv$keys),
      error = function(e) e
    )
    if (inherits(scen, "error") || is.null(scen)) {
      obj_note(list(ok = FALSE, text = fpa_screen("obj_fail")))
      return(invisible(FALSE))
    }
    info <- fpa_shiny_obj_info(p)
    base_kpi <- fpa_scenario_cash_kpi(list(cash = p$finance$cash, pnl = p$finance$pnl), floor, info$close)
    scen_kpi <- fpa_scenario_cash_kpi(scen, floor, info$close)
    moves <- fpa_shiny_scn_moves(now$assum, now$lines, lv$keys)
    under_months <- character(0)
    if (!is.null(scen$cash) && nrow(scen$cash) && "cash_close" %in% names(scen$cash)) {
      closes <- suppressWarnings(as.numeric(scen$cash$cash_close))
      hit <- which(is.finite(closes) & closes < floor)
      under_months <- as.character(scen$cash$periode[hit])
    }
    entry <- c(
      list(
        at = format(Sys.time(), "%Y-%m-%d %H:%M:%S"),
        moves = if (length(moves)) paste(moves, collapse = " · ") else fpa_screen("scn_none_moved"),
        span = fpa_shiny_scn_span(fpa_shiny_forecast_periods(p$finance$period_status))
      ),
      fpa_shiny_scn_kpi_fields(scen_kpi, base_kpi, info),
      list(
      bridge = fpa_shiny_scn_bridge(scen$cash),
      bridge_ref = fpa_shiny_scn_bridge(p$finance$cash),
      files = fpa_shiny_scn_files_for(p$config, c("work_cash", "work_pnl", "opening_bs", "decisions", "manual")),
      low = scen_kpi$low,
      low_month = scen_kpi$low_month,
      under = scen_kpi$under,
      under_months = under_months,
      floor = floor,
      deltas = now,
      dials = fpa_shiny_scn_dial_rows(lv, now, p$finance$pnl, scen$pnl),
      objectif = list(metric = metric, target = target, ye_month = ye, value = value)
      )
    )
    log <- c(scn_log(), list(entry))
    if (length(log) > 10L) log <- log[(length(log) - 9L):length(log)]
    scn_log(log)
    metric_lab <- fpa_shiny_obj_metric_lab(metric, info)
    ye <- info$measured
    move_lab <- fpa_shiny_obj_move_lab(deltas, lv$keys)
    eur <- function(x) if (!is.finite(x)) "—" else fpa_shiny_eur(x)
    gap_s <- if (!is.finite(gap)) "—" else paste0(if (gap > 0) "+" else "", eur(gap))
    hit <- identical(note_key, "obj_hit") || identical(note_key, "obj_applied")
    text <- fpa_screen(note_key, metric_lab, ye, move_lab, eur(value), gap_s, eur(target))
    inert_labs <- obj_lever_labs(lv, inert %||% list())
    if (length(inert_labs)) text <- paste(text, fpa_screen("obj_inert", paste(inert_labs, collapse = ", ")))
    obj_note(list(
      ok = isTRUE(hit),
      text = text,
      line_move = fpa_shiny_scn_has_line_move(deltas)
    ))
    invisible(TRUE)
  }

  shiny::observeEvent(input$obj_metric, {
    obj_note(NULL)
    obj_mixes(list())
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$obj_run, {
    p <- pack()
    lv <- scenario_levers()
    if (!isTRUE(p$ok) || is.null(lv)) return()
    target <- suppressWarnings(as.numeric(input$obj_target))
    if (!is.finite(target)) {
      obj_note(list(ok = FALSE, text = fpa_screen("obj_bad_target")))
      return()
    }
    metric <- as.character(input$obj_metric %||% "cash_ye")
    if (!metric %in% FPA_OBJ_METRICS) metric <- "cash_ye"
    mode <- as.character(input$obj_mode %||% "manual")
    if (!mode %in% c("manual", "auto")) mode <- "manual"
    info <- fpa_shiny_obj_info(p)
    ye <- info$close
    ye_shown <- info$measured
    metric_lab <- fpa_shiny_obj_metric_lab(metric, info)
    eur <- function(x) if (!is.finite(x)) "—" else fpa_shiny_eur(x)
    tol <- max(50, abs(target) * 0.002)
    now <- fpa_shiny_scn_read(lv, input)
    shiny::showNotification(
      if (identical(mode, "auto")) fpa_screen("obj_busy_auto") else fpa_screen("obj_busy"),
      id = "fpa-obj", duration = NULL, type = "message"
    )
    if (identical(mode, "auto")) {
      pool_tokens <- c(paste0("assum:", lv$ids), paste0("line:", lv$lines))
      pool <- fpa_objectif_parse_levers(pool_tokens, lv)
      got <- tryCatch(
        fpa_objectif_auto(
          p$config_path, lv$base, lv$keys, pool,
          target = target, metric = metric, ye_month = ye,
          other_assum = lapply(now$assum, function(x) 0),
          other_lines = lapply(now$lines, function(x) 0),
          tol = tol, n_mixes = 5L, max_evals_each = 8L
        ),
        error = function(e) e
      )
      shiny::removeNotification("fpa-obj")
      if (inherits(got, "error") || is.null(got)) {
        obj_mixes(list())
        obj_note(list(ok = FALSE, text = fpa_screen("obj_fail")))
        return()
      }
      if (identical(got$reason, "already")) {
        obj_mixes(list())
        obj_note(list(ok = TRUE, text = fpa_screen("obj_already", eur(got$base), ye_shown)))
        return()
      }
      mixes <- got$mixes %||% list()
      obj_mixes(mixes)
      if (!length(mixes)) {
        obj_note(list(
          ok = FALSE,
          text = if (is.finite(got$reachable_lo %||% NA_real_) && is.finite(got$reachable_hi %||% NA_real_)) {
            fpa_screen("obj_infeasible_multi", metric_lab, ye_shown, eur(got$reachable_lo), eur(got$reachable_hi), eur(target))
          } else {
            fpa_screen("obj_mix_none")
          }
        ))
        return()
      }
      best <- mixes[[1]]
      gap <- best$gap
      gap_s <- if (!is.finite(gap)) "—" else paste0(if (gap > 0) "+" else "", eur(gap))
      obj_note(list(
        ok = identical(got$reason, "hit") || (is.finite(gap) && abs(gap) <= tol),
        text = fpa_screen("obj_mixes_ready", as.character(length(mixes)), metric_lab, ye_shown, eur(best$value), gap_s)
      ))
      return()
    }
    levers <- fpa_objectif_parse_levers(input$obj_levers, lv)
    if (!length(levers)) {
      shiny::removeNotification("fpa-obj")
      obj_mixes(list())
      obj_note(list(ok = FALSE, text = fpa_screen("obj_no_lever")))
      return()
    }
    # Each click is one mix, comparable with the others. Start from the
    # projection on screen, not from dials a previous mix left behind.
    got <- tryCatch(
      fpa_objectif_solve(
        p$config_path, lv$base, lv$keys, levers,
        target = target, metric = metric, ye_month = ye,
        status = p$finance$period_status,
        other_assum = lapply(now$assum, function(x) 0),
        other_lines = lapply(now$lines, function(x) 0),
        tol = tol, max_evals = 48L
      ),
      error = function(e) e
    )
    shiny::removeNotification("fpa-obj")
    obj_mixes(list())
    if (inherits(got, "error") || is.null(got)) {
      obj_note(list(ok = FALSE, text = fpa_screen("obj_fail")))
      return()
    }
    if (identical(got$reason, "already")) {
      obj_note(list(ok = TRUE, text = fpa_screen("obj_already", eur(got$base), ye_shown)))
      return()
    }
    if (identical(got$reason, "range_fail") && is.finite(got$base %||% NA_real_)) {
      got$reason <- "infeasible"
      got$reachable_lo <- got$base
      got$reachable_hi <- got$base
    }
    if (identical(got$reason, "infeasible") || identical(got$reason, "no_lever")) {
      key <- if (length(levers) > 1L) "obj_infeasible_multi" else "obj_infeasible"
      text <- if (identical(got$reason, "no_lever")) fpa_screen("obj_no_lever") else fpa_screen(
        key, metric_lab, ye_shown, eur(got$reachable_lo), eur(got$reachable_hi), eur(target)
      )
      hints <- obj_lever_hints(lv, levers, got$inert %||% list(), metric)
      if (length(hints)) text <- paste(c(text, hints), collapse = " ")
      obj_note(list(ok = FALSE, text = text))
      return()
    }
    if (!isTRUE(got$ok) || !length(got$deltas)) {
      obj_note(list(ok = FALSE, text = fpa_screen("obj_fail")))
      return()
    }
    note_key <- if (identical(got$reason, "hit") || (is.finite(got$gap) && abs(got$gap) <= tol)) {
      "obj_hit"
    } else {
      "obj_closest"
    }
    obj_commit(
      p, lv, got$deltas, metric, target, ye, got$value, got$gap, note_key,
      reset_others = TRUE, inert = got$inert %||% list()
    )
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$obj_apply_mix, {
    p <- pack()
    lv <- scenario_levers()
    mixes <- obj_mixes()
    i <- suppressWarnings(as.integer(input$obj_apply_mix))
    if (!isTRUE(p$ok) || is.null(lv) || !length(mixes) || !is.finite(i) || i < 1L || i > length(mixes)) return()
    m <- mixes[[i]]
    target <- suppressWarnings(as.numeric(input$obj_target))
    metric <- as.character(input$obj_metric %||% "cash_ye")
    if (!metric %in% FPA_OBJ_METRICS) metric <- "cash_ye"
    ye <- m$ye_month %||% fpa_shiny_obj_info(p)$close
    # Mixes are solved from a zero board, so applying one clears the other dials.
    obj_commit(p, lv, m$deltas, metric, target, ye, m$value, m$gap, "obj_applied", reset_others = TRUE)
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$cash_floor, {
    p <- pack()
    if (isTRUE(p$ok)) fpa_cash_floor_write(p$config, input$cash_floor)
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$scenario_reset, {
    lv <- scenario_levers()
    for (id in lv$ids) shiny::updateSliderInput(session, paste0("lev_", id), value = 0)
    for (nm in lv$lines) shiny::updateSliderInput(session, paste0("line_", nm), value = 0)
  }, ignoreInit = TRUE)

  output$scenario_kpi <- shiny::renderUI({
    p <- pack()
    log <- scn_log()
    last <- if (length(log)) log[[length(log)]] else NULL
    floor <- if (is.null(last)) {
      v <- suppressWarnings(as.numeric(input$cash_floor %||% 0))
      if (!is.finite(v)) 0 else v
    } else {
      last$floor
    }
    info <- fpa_shiny_obj_info(p)
    base_kpi <- fpa_scenario_cash_kpi(list(cash = p$finance$cash, pnl = p$finance$pnl), floor, info$close)
    close_v <- if (is.null(last)) base_kpi$close else last$cash_close
    oi_v <- if (is.null(last)) base_kpi$oi_fy else last$oi_fy %||% last$oi
    oi_last_v <- if (is.null(last)) base_kpi$oi_last else last$oi_last %||% NA_real_
    low_v <- if (is.null(last)) base_kpi$low else last$low
    low_m <- if (is.null(last)) base_kpi$low_month else last$low_month
    under_v <- if (is.null(last)) base_kpi$under else last$under
    delta <- if (is.null(last)) 0 else last$cash_delta
    card <- function(id, k, v, s, warn = FALSE) {
      shiny::tags$button(
        type = "button",
        class = paste("fpa-kpi-card", if (warn) "warn" else ""),
        onclick = sprintf("Shiny.setInputValue('scn_kpi_open','%s',{priority:'event'})", id),
        shiny::div(class = "k", k),
        shiny::div(class = "v", v),
        shiny::div(class = "s", s)
      )
    }
    shiny::tagList(
      shiny::div(
        class = "fpa-kpi",
        card("open", fpa_screen("scn_kpi_open"), paste(fpa_shiny_eur(base_kpi$open), "EUR"), fpa_screen("scn_kpi_open_s")),
        card("ref", fpa_screen("scn_kpi_ref"), paste(fpa_shiny_eur(base_kpi$close), "EUR"), fpa_screen("scn_kpi_ref_s")),
        card(
          "scen", fpa_screen("scn_kpi_scen"), paste(fpa_shiny_eur(close_v), "EUR"),
          if (is.null(last)) fpa_screen("scn_kpi_waiting") else fpa_screen("scn_kpi_applied")
        ),
        card(
          "gap", fpa_screen("scn_kpi_gap"), paste0(fpa_shiny_eur_signed(delta), " EUR"),
          fpa_screen("scn_kpi_gap_s"),
          warn = is.finite(delta) && delta < -0.5
        ),
        card("low", fpa_screen("scn_kpi_low"), paste(fpa_shiny_eur(low_v), "EUR"), low_m),
        card(
          "under", fpa_screen("scn_kpi_under"),
          paste0(under_v, " / ", length(p$finance$cash$periode %||% character(0))),
          paste0(fpa_screen("scn_kpi_floor"), " ", fpa_shiny_eur(floor), " EUR"),
          warn = is.finite(under_v) && under_v > 0
        ),
        card(
          "oi", fpa_shiny_obj_metric_lab("oi_fy", info), paste(fpa_shiny_eur(oi_v), "EUR"),
          paste0(fpa_screen("scn_kpi_oi_ref"), " ", fpa_shiny_eur(base_kpi$oi_fy), " EUR"),
          warn = is.finite(oi_v) && oi_v < -0.5
        ),
        card(
          "oi_last", fpa_shiny_obj_metric_lab("oi_ye", info), paste(fpa_shiny_eur(oi_last_v), "EUR"),
          paste0(fpa_screen("scn_kpi_oi_ref"), " ", fpa_shiny_eur(base_kpi$oi_last), " EUR"),
          warn = is.finite(oi_last_v) && oi_last_v < -0.5
        )
      ),
      shiny::tags$p(style = "color:#5c6b73;font-size:12.5px;margin:0 0 0.8rem;", fpa_screen("scn_kpi_hint"))
    )
  })

  shiny::observeEvent(input$scn_kpi_open, {
    id <- as.character(input$scn_kpi_open %||% "")
    p <- pack()
    if (!isTRUE(p$ok) || !nzchar(id)) return()
    log <- scn_log()
    last <- if (length(log)) log[[length(log)]] else NULL
    floor <- if (is.null(last)) {
      v <- suppressWarnings(as.numeric(input$cash_floor %||% 0))
      if (!is.finite(v)) 0 else v
    } else {
      last$floor
    }
    info <- fpa_shiny_obj_info(p)
    base_kpi <- fpa_scenario_cash_kpi(list(cash = p$finance$cash, pnl = p$finance$pnl), floor, info$close)
    bridge_ref <- fpa_shiny_scn_bridge(p$finance$cash)
    bridge_scen <- if (!is.null(last$bridge)) last$bridge else bridge_ref
    files <- switch(
      id,
      open = fpa_shiny_scn_files_for(p$config, "opening_bs"),
      ref = fpa_shiny_scn_files_for(p$config, "work_cash"),
      scen = fpa_shiny_scn_files_for(p$config, "work_cash"),
      gap = fpa_shiny_scn_files_for(p$config, "work_cash"),
      low = fpa_shiny_scn_files_for(p$config, "work_cash"),
      under = fpa_shiny_scn_files_for(p$config, "work_cash"),
      oi = ,
      oi_last = fpa_shiny_scn_files_for(p$config, "work_pnl"),
      list()
    )
    title <- switch(
      id,
      open = fpa_screen("scn_kpi_open"),
      ref = fpa_screen("scn_kpi_ref"),
      scen = fpa_screen("scn_kpi_scen"),
      gap = fpa_screen("scn_kpi_gap"),
      low = fpa_screen("scn_kpi_low"),
      under = fpa_screen("scn_kpi_under"),
      oi = fpa_shiny_obj_metric_lab("oi_fy", info),
      oi_last = fpa_shiny_obj_metric_lab("oi_ye", info),
      fpa_screen("scn_kpi_ref")
    )
    body <- switch(
      id,
      open = {
        open_m <- if (!is.null(p$finance$cash) && nrow(p$finance$cash)) as.character(p$finance$cash$periode[[1]]) else ""
        fpa_shiny_scn_align_ui(list(
          fpa_shiny_scn_pair(paste(fpa_shiny_eur(base_kpi$open), "EUR"), fpa_screen("scn_lab_open")),
          if (nzchar(open_m)) fpa_shiny_scn_pair(open_m, fpa_screen("scn_kpi_first_month"))
        ))
      },
      ref = if (!is.null(bridge_ref)) {
        fpa_shiny_scn_align_ui(fpa_shiny_scn_bridge_bits(bridge_ref, fpa_screen("scn_lab_ref_close")))
      } else {
        shiny::tags$p(style = "color:#5c6b73;", fpa_screen("scn_kpi_no_calc"))
      },
      scen = if (!is.null(bridge_scen)) {
        shiny::tagList(
          if (is.null(last)) shiny::tags$p(style = "margin:0 0 10px;color:#5c6b73;", fpa_screen("scn_kpi_waiting")),
          fpa_shiny_scn_align_ui(fpa_shiny_scn_bridge_bits(
            bridge_scen,
            if (is.null(last)) fpa_screen("scn_lab_ref_close") else fpa_screen("scn_lab_close")
          ))
        )
      } else {
        shiny::tags$p(style = "color:#5c6b73;", fpa_screen("scn_kpi_no_calc"))
      },
      gap = {
        close_v <- if (is.null(last)) base_kpi$close else last$cash_close
        delta <- if (is.null(last)) 0 else last$cash_delta
        fpa_shiny_scn_align_ui(list(
          fpa_shiny_scn_pair(fpa_shiny_eur_signed(delta), fpa_screen("scn_lab_gap")),
          "=",
          fpa_shiny_scn_pair(paste(fpa_shiny_eur(close_v), "EUR"), fpa_screen("scn_lab_pass_cash")),
          "−",
          fpa_shiny_scn_pair(paste(fpa_shiny_eur(base_kpi$close), "EUR"), fpa_screen("scn_lab_ref_cash"))
        ))
      },
      low = {
        low_v <- if (is.null(last)) base_kpi$low else last$low
        low_m <- if (is.null(last)) base_kpi$low_month else last$low_month
        fpa_shiny_scn_align_ui(list(
          fpa_shiny_scn_pair(paste(fpa_shiny_eur(low_v), "EUR"), fpa_screen("scn_kpi_low")),
          if (nzchar(low_m %||% "")) fpa_shiny_scn_pair(low_m, fpa_screen("scn_kpi_low_month"))
        ))
      },
      under = {
        under_v <- if (is.null(last)) base_kpi$under else last$under
        n_m <- length(p$finance$cash$periode %||% character(0))
        months <- if (!is.null(last$under_months)) {
          last$under_months
        } else {
          character(0)
        }
        if (!length(months) && is.null(last)) {
          cash <- p$finance$cash
          if (!is.null(cash) && nrow(cash) && "cash_close" %in% names(cash)) {
            closes <- suppressWarnings(as.numeric(cash$cash_close))
            hit <- which(is.finite(closes) & closes < floor)
            months <- as.character(cash$periode[hit])
          }
        }
        shiny::tagList(
          fpa_shiny_scn_align_ui(list(
            fpa_shiny_scn_pair(as.character(under_v), fpa_screen("scn_kpi_under")),
            "/",
            fpa_shiny_scn_pair(as.character(n_m), fpa_screen("scn_kpi_months"))
          )),
          fpa_shiny_scn_align_ui(list(
            fpa_shiny_scn_pair(paste(fpa_shiny_eur(floor), "EUR"), fpa_screen("scn_kpi_floor"))
          )),
          if (length(months)) shiny::tags$p(
            style = "margin:0 0 12px;color:#3d4c54;font-size:13px;",
            paste(months, collapse = " · ")
          )
        )
      },
      oi = ,
      oi_last = {
        e0 <- if (is.null(last)) {
          fpa_shiny_scn_kpi_fields(base_kpi, base_kpi, info)
        } else {
          last
        }
        fpa_shiny_scn_oi_identities(e0, NULL, info)
      },
      shiny::tags$p(style = "color:#5c6b73;", fpa_screen("scn_kpi_no_calc"))
    )
    shiny::showModal(shiny::modalDialog(
      title = title,
      easyClose = TRUE,
      size = "l",
      footer = shiny::modalButton(fpa_screen("scn_close")),
      fpa_shiny_scn_trace_style(),
      shiny::div(class = "fpa-scn-trace", body, fpa_shiny_scn_files_table(files))
    ))
  }, ignoreInit = TRUE)

  output$scenario_moves <- shiny::renderUI({
    lv <- scenario_levers()
    now <- fpa_shiny_scn_read(lv, input)
    log <- scn_log()
    zero <- all(vapply(now$assum, function(v) isTRUE(all.equal(as.numeric(v), 0)), logical(1))) &&
      all(vapply(now$lines, function(v) isTRUE(all.equal(as.numeric(v), 0)), logical(1)))
    msg <- if (!length(log) && zero) {
      fpa_screen("scn_pending_wait")
    } else if (!length(log)) {
      fpa_screen("scn_pending_armed")
    } else if (fpa_shiny_scn_same(now, log[[length(log)]]$deltas)) {
      fpa_screen("scn_pending_match")
    } else {
      fpa_screen("scn_pending_dirty")
    }
    shiny::tags$p(style = "color:#1f4e5f;font-weight:600;margin:0.7rem 0 0.2rem;", msg)
  })

  output$scn_log_ui <- shiny::renderUI({
    lv <- scenario_levers()
    fpa_shiny_scn_log_ui(scn_log(), lv, fpa_shiny_scn_read(lv, input))
  })

  shiny::observeEvent(input$scn_apply, {
    p <- pack()
    lv <- scenario_levers()
    if (!isTRUE(p$ok) || is.null(lv)) return()
    now <- fpa_shiny_scn_read(lv, input)
    floor <- suppressWarnings(as.numeric(input$cash_floor %||% 0))
    if (!is.finite(floor)) floor <- 0
    scen <- tryCatch(
      fpa_scenario_run(p$config_path, lv$base, now$assum, now$lines, lv$keys),
      error = function(e) e
    )
    if (inherits(scen, "error") || is.null(scen)) {
      scenario_note(if (inherits(scen, "error")) conditionMessage(scen) else fpa_screen("loc_scenario_failed"))
      return()
    }
    info <- fpa_shiny_obj_info(p)
    base_kpi <- fpa_scenario_cash_kpi(list(cash = p$finance$cash, pnl = p$finance$pnl), floor, info$close)
    scen_kpi <- fpa_scenario_cash_kpi(scen, floor, info$close)
    moves <- fpa_shiny_scn_moves(now$assum, now$lines, lv$keys)
    under_months <- character(0)
    if (!is.null(scen$cash) && nrow(scen$cash) && "cash_close" %in% names(scen$cash)) {
      closes <- suppressWarnings(as.numeric(scen$cash$cash_close))
      hit <- which(is.finite(closes) & closes < floor)
      under_months <- as.character(scen$cash$periode[hit])
    }
    entry <- c(
      list(
        at = format(Sys.time(), "%Y-%m-%d %H:%M:%S"),
        moves = if (length(moves)) paste(moves, collapse = " · ") else fpa_screen("scn_none_moved"),
        span = fpa_shiny_scn_span(fpa_shiny_forecast_periods(p$finance$period_status))
      ),
      fpa_shiny_scn_kpi_fields(scen_kpi, base_kpi, info),
      list(
        bridge = fpa_shiny_scn_bridge(scen$cash),
        bridge_ref = fpa_shiny_scn_bridge(p$finance$cash),
        files = fpa_shiny_scn_files_for(p$config, c("work_cash", "work_pnl", "opening_bs", "decisions", "manual")),
        low = scen_kpi$low,
        low_month = scen_kpi$low_month,
        under = scen_kpi$under,
        under_months = under_months,
        floor = floor,
        deltas = now,
        dials = fpa_shiny_scn_dial_rows(lv, now, p$finance$pnl, scen$pnl)
      )
    )
    log <- c(scn_log(), list(entry))
    if (length(log) > 10L) log <- log[(length(log) - 9L):length(log)]
    scn_log(log)
    scenario_note("")
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$scn_open, {
    i <- suppressWarnings(as.integer(input$scn_open))
    log <- scn_log()
    if (is.na(i) || i < 1L || i > length(log)) return()
    e <- log[[i]]
    base_cash <- if (!is.null(e$base_cash)) e$base_cash else e$cash_close - e$cash_delta
    base_oi <- if (!is.null(e$base_oi)) e$base_oi else e$oi - e$oi_delta
    b <- e$bridge
    br <- e$bridge_ref
    if (is.null(br)) {
      p_now <- pack()
      if (isTRUE(p_now$ok)) br <- fpa_shiny_scn_bridge(p_now$finance$cash)
    }
    dials <- e$dials
    if (is.null(dials) && !is.null(e$deltas)) {
      lv_now <- scenario_levers()
      p_now <- pack()
      dials <- fpa_shiny_scn_dial_rows(
        lv_now, e$deltas,
        if (isTRUE(p_now$ok)) p_now$finance$pnl else NULL,
        NULL
      )
    }
    shiny::showModal(shiny::modalDialog(
      title = e$at,
      easyClose = TRUE,
      size = "l",
      footer = shiny::modalButton(fpa_screen("scn_close")),
      fpa_shiny_scn_trace_style(),
      shiny::div(
        class = "fpa-scn-trace",
        shiny::tags$p(
          style = "margin:0 0 12px;font-weight:600;color:#1f4e5f;",
          {
            span <- as.character(e$span %||% "")
            if (!nzchar(span)) {
              p_span <- pack()
              if (isTRUE(p_span$ok)) {
                span <- fpa_shiny_scn_span(fpa_shiny_forecast_periods(p_span$finance$period_status))
              }
            }
            if (nzchar(span) && nzchar(e$moves %||% "")) paste(e$moves, span, sep = " · ") else e$moves
          }
        ),
        fpa_shiny_scn_dial_trace_ui(dials),
        if (fpa_shiny_scn_has_line_move(e$deltas)) shiny::tags$p(class = "fpa-obj-sens-note", fpa_screen("obj_line_sens")),
        fpa_shiny_scn_align_ui(list(
          fpa_shiny_scn_pair(fpa_shiny_eur_signed(e$cash_delta), fpa_screen("scn_lab_gap")),
          "=",
          fpa_shiny_scn_pair(paste(fpa_shiny_eur(e$cash_close), "EUR"), fpa_screen("scn_lab_pass_cash")),
          "−",
          fpa_shiny_scn_pair(paste(fpa_shiny_eur(base_cash), "EUR"), fpa_screen("scn_lab_ref_cash"))
        )),
        fpa_shiny_scn_oi_identities(e, base_oi),
        if (!is.null(b)) fpa_shiny_scn_align_ui(fpa_shiny_scn_bridge_bits(b, fpa_screen("scn_lab_close"))),
        if (!is.null(br)) fpa_shiny_scn_align_ui(fpa_shiny_scn_bridge_bits(br, fpa_screen("scn_lab_ref_close"))),
        fpa_shiny_scn_files_table(e$files)
      )
    ))
  }, ignoreInit = TRUE)

  scenario_note <- shiny::reactiveVal("")

  shiny::observeEvent(input$run_sensitivity, {
    p <- pack()
    if (!isTRUE(p$ok)) return()
    sens <- tryCatch(
      fpa_sensitivity_run(p$config_path, write = TRUE),
      error = function(e) e
    )
    if (inherits(sens, "error")) {
      scenario_note(conditionMessage(sens))
      return()
    }
    cur <- pack()
    cur$finance$sensitivity <- sens$rows
    pack(cur)
    scenario_note(paste0(
      fpa_screen("loc_sens_written"),
      "Residu d'interaction ", fpa_shiny_eur(sens$interaction_residual),
      fpa_screen("loc_eur_together")
    ))
  })

  output$scenario_result <- shiny::renderText(scenario_note())

  output$driver_impact_table <- shiny::renderTable({
    d <- pack()$finance$driver_impact
    if (is.null(d) || !nrow(d)) return(NULL)
    d
  }, digits = 0)

  close_tick <- shiny::reactiveVal(0L)
  close_bump <- function() close_tick(shiny::isolate(close_tick()) + 1L)
  variance_save_note <- shiny::reactiveVal("")

  shiny::observeEvent(input$save_ecart_arret, {
    p <- pack()
    if (!isTRUE(p$ok)) return()
    line <- as.character(cur_line() %||% "")
    label <- if (nzchar(line)) {
      tryCatch(paste("écart", fpa_line_fr(line)), error = function(e) paste("écart", line))
    } else {
      "écart"
    }
    saved <- tryCatch(fpa_save_vintage(p$paths, label), error = function(e) e)
    if (inherits(saved, "error")) {
      variance_save_note(conditionMessage(saved))
      return()
    }
    close_bump()
    variance_save_note(fpa_screen("var_rest_saved", saved$id))
  })

  close_st <- shiny::reactive({
    close_tick()
    fpa_close_state(pack())
  })

  close_drift <- shiny::reactive({
    close_tick()
    p <- pack()
    if (!isTRUE(p$ok) || is.null(p$paths)) return(NULL)
    lock <- fpa_shiny_csv(file.path(p$paths$work, "standing-lock.csv"))
    if (!nrow(lock)) return(fpa_close_drift(lock, NULL))
    tryCatch(fpa_close_drift(lock, fpa_close_source_pnl(p$config, p$paths)), error = function(e) NULL)
  })

  close_steps <- shiny::reactive(fpa_close_steps(close_st(), close_drift()))

  output$close_fact_steps <- shiny::renderUI(fpa_close_steps_fact(close_st(), close_steps()))
  output$close_steps <- shiny::renderUI(fpa_close_steps_ui(close_st(), close_steps()))

  close_pair <- shiny::reactive({
    st <- close_st()
    if (is.null(st)) return(c(a = "", b = ""))
    ch <- unname(fpa_close_pick_choices(st))
    a <- as.character(input$close_a %||% "")
    b <- as.character(input$close_b %||% "")
    if (!nzchar(a) || !a %in% ch || !nzchar(b) || !b %in% ch) {
      d <- fpa_close_default_pair(st$versions, st$cur_md5)
      if (!nzchar(a) || !a %in% ch) a <- d[["a"]]
      if (!nzchar(b) || !b %in% ch) b <- d[["b"]]
    }
    c(a = a, b = b)
  })

  output$close_picks <- shiny::renderUI({
    st <- close_st()
    if (is.null(st)) return(NULL)
    d <- fpa_close_default_pair(st$versions, st$cur_md5)
    a <- shiny::isolate(as.character(input$close_a %||% ""))
    b <- shiny::isolate(as.character(input$close_b %||% ""))
    fpa_close_picks_ui(st, if (nzchar(a)) a else d[["a"]], if (nzchar(b)) b else d[["b"]])
  })

  shiny::observeEvent(input$close_pick, {
    st <- close_st()
    a <- as.character(input$close_pick$a %||% "")
    if (is.null(st) || !nzchar(a)) return()
    ch <- fpa_close_pick_choices(st)
    b <- if ("current" %in% ch) "current" else fpa_close_default_pair(st$versions, st$cur_md5)[["b"]]
    shiny::updateSelectInput(session, "close_a", selected = a)
    shiny::updateSelectInput(session, "close_b", selected = b)
    session$sendCustomMessage("fpa-open-details", list(sel = "#fpa-var-fold-close-cmp"))
  }, ignoreInit = TRUE)

  close_cmp <- shiny::reactive({
    st <- close_st()
    pr <- close_pair()
    p <- pack()
    if (is.null(st) || !nzchar(pr[["a"]]) || !nzchar(pr[["b"]]) || identical(pr[["a"]], pr[["b"]])) return(NULL)
    fpa_close_compare(fpa_close_read_pnl(p$paths, pr[["a"]]), fpa_close_read_pnl(p$paths, pr[["b"]]), st$months)
  })

  close_refs <- shiny::reactive({
    st <- close_st()
    pr <- close_pair()
    if (is.null(st)) return(list(a = "", b = "", la = "", lb = ""))
    list(
      a = fpa_close_ver_ref(st$versions, pr[["a"]]), b = fpa_close_ver_ref(st$versions, pr[["b"]]),
      la = fpa_close_ver_label(st$versions, pr[["a"]]), lb = fpa_close_ver_label(st$versions, pr[["b"]])
    )
  })

  output$close_cmp_on <- shiny::reactive({
    cmp <- close_cmp()
    !is.null(cmp) && length(cmp$moved) > 0L
  })
  shiny::outputOptions(output, "close_cmp_on", suspendWhenHidden = FALSE)

  output$close_fact_cmp <- shiny::renderUI({
    st <- close_st()
    pr <- close_pair()
    if (is.null(st)) return(fpa_screen("close_fact_wait"))
    if (identical(pr[["a"]], pr[["b"]])) return(fpa_screen("close_cmp_pick_two"))
    r <- close_refs()
    fpa_close_cmp_fact(close_cmp(), r$a, r$b, st$year, length(st$months))
  })
  output$close_cmp_lead <- shiny::renderUI({
    st <- close_st()
    if (is.null(st)) return(NULL)
    pr <- close_pair()
    txt <- if (identical(pr[["a"]], pr[["b"]])) {
      fpa_screen("close_cmp_pick_two")
    } else {
      r <- close_refs()
      fpa_close_cmp_fact(close_cmp(), r$a, r$b, st$year, length(st$months))
    }
    shiny::tags$p(class = "fpa-close-lead", txt)
  })

  output$close_cmp_body <- shiny::renderUI({
    st <- close_st()
    cmp <- close_cmp()
    if (is.null(st) || is.null(cmp) || !length(cmp$moved)) return(NULL)
    sp <- fpa_close_cmp_span(cmp, st$year, length(st$months))
    shiny::tagList(
      shiny::tags$p(class = "fpa-var-cap", fpa_screen("close_br_cap", sp$of, fpa_var_eur(cmp$oi_a), fpa_var_eur(cmp$oi_b))),
      fpa_close_cmp_table(cmp, st$act, st$year, length(st$months)),
      shiny::tags$div(
        class = "fpa-close-acts",
        shiny::actionButton("close_export_btn", fpa_screen("close_btn_export"), class = "fpa-path-btn is-quiet", icon = shiny::icon("file-csv")),
        shiny::tags$span(class = "fpa-var-note", fpa_screen("close_export_what"))
      )
    )
  })

  if (FPA_HAS_PLOTLY) {
    output$plot_close_bridge <- plotly::renderPlotly({
      cmp <- close_cmp()
      r <- close_refs()
      bf <- fpa_close_bridge_frame(cmp, r$la, r$lb)
      if (is.null(bf)) return(plotly::plotly_empty())
      plotly::config(fpa_var_bridge_fig(bf), displaylogo = FALSE, displayModeBar = FALSE)
    })
  } else {
    output$plot_close_bridge <- shiny::renderPlot({
      bf <- fpa_close_bridge_frame(close_cmp())
      if (is.null(bf)) return(invisible(NULL))
      cols <- ifelse(bf$kind == "total", "#0f2f3a", ifelse(bf$signed >= 0, "#1f4e5f", "#8c3a3a"))
      lo <- pmin(bf$start, bf$end)
      hi <- pmax(bf$start, bf$end)
      n <- nrow(bf)
      graphics::plot(NA, xlim = c(0.5, n + 0.5), ylim = range(c(0, lo, hi)), xaxt = "n", xlab = "", ylab = "EUR")
      graphics::rect(seq_len(n) - 0.35, lo, seq_len(n) + 0.35, hi, col = cols, border = NA)
      graphics::axis(1, at = seq_len(n), labels = bf$label, las = 2, cex.axis = 0.7)
    })
  }

  output$close_fact_reg <- shiny::renderUI({
    st <- close_st()
    if (is.null(st)) return(fpa_screen("close_fact_wait"))
    fpa_close_reg_fact(st)
  })
  output$close_reg <- shiny::renderUI({
    st <- close_st()
    if (is.null(st)) return(NULL)
    fpa_close_register_ui(st)
  })

  output$close_fact_lock <- shiny::renderUI(fpa_close_lock_fact(close_st(), close_drift()))
  output$close_lock <- shiny::renderUI({
    st <- close_st()
    p <- pack()
    cfg <- if (isTRUE(p$ok)) p$config else NULL
    has_nat <- !is.null(cfg) && fpa_line_nature_has(cfg, "pnl")
    fpa_close_lock_ui(
      st, close_drift(),
      nature = if (has_nat) fpa_line_nature(cfg, "pnl") else character(0),
      show_op_fin = has_nat
    )
  })

  output$close_fact_bud <- shiny::renderUI({
    st <- close_st()
    if (is.null(st)) return(fpa_screen("close_fact_wait"))
    fpa_close_budget_fact(st$budget)
  })
  output$close_bud <- shiny::renderUI({
    st <- close_st()
    if (is.null(st)) return(NULL)
    fpa_close_budget_ui(st$budget)
  })

  for (nm in c("close_fact_steps", "close_fact_cmp", "close_fact_reg", "close_fact_lock", "close_fact_bud")) {
    shiny::outputOptions(output, nm, suspendWhenHidden = FALSE)
  }

  close_done <- function(msg, type = "message") {
    shiny::showNotification(msg, type = type, duration = 8)
  }

  close_do_lock <- function() {
    p <- pack()
    if (!isTRUE(p$ok)) return()
    locked <- tryCatch(fpa_shiny_write_lock(p$paths), error = function(e) e)
    if (inherits(locked, "error")) return(close_done(conditionMessage(locked), "error"))
    close_bump()
    added <- locked$added
    close_done(if (length(added)) {
      fpa_screen("close_ok_lock", fpa_close_between(added), length(unique(locked$lock$periode)))
    } else {
      fpa_screen("close_ok_lock_none")
    })
  }
  shiny::observeEvent(input$close_lock_btn, close_do_lock(), ignoreInit = TRUE)
  shiny::observeEvent(input$close_lock_btn2, close_do_lock(), ignoreInit = TRUE)

  shiny::observeEvent(input$close_save_btn, {
    p <- pack()
    if (!isTRUE(p$ok)) return()
    lab <- trimws(as.character(input$close_label %||% ""))
    if (!nzchar(lab)) lab <- fpa_screen("close_label_def", fpa_close_mlong(close_st()$closed))
    saved <- tryCatch(fpa_save_vintage(p$paths, lab), error = function(e) e)
    if (inherits(saved, "error")) return(close_done(conditionMessage(saved), "error"))
    close_bump()
    close_done(fpa_screen("close_ok_save", fpa_shiny_when(saved$saved_at), lab))
  }, ignoreInit = TRUE)

  close_freeze_ask <- function() {
    b <- close_st()$budget
    shiny::showModal(shiny::modalDialog(
      title = if (isTRUE(b$frozen)) fpa_screen("close_btn_refreeze") else fpa_screen("close_btn_freeze"),
      easyClose = TRUE,
      shiny::tags$p(if (isTRUE(b$frozen)) fpa_screen("close_freeze_warn", fpa_shiny_when(b$frozen_at)) else fpa_screen("close_bud_what")),
      footer = shiny::tagList(
        shiny::modalButton(fpa_screen("journal_cancel")),
        shiny::actionButton("close_freeze_ok", fpa_screen("close_btn_freeze"), class = "fpa-path-btn")
      )
    ))
  }
  shiny::observeEvent(input$close_freeze_btn, close_freeze_ask(), ignoreInit = TRUE)
  shiny::observeEvent(input$close_freeze_btn2, close_freeze_ask(), ignoreInit = TRUE)
  shiny::observeEvent(input$close_freeze_ok, {
    shiny::removeModal()
    p <- pack()
    if (!isTRUE(p$ok)) return()
    man <- tryCatch(fpa_freeze_budget(p$paths), error = function(e) e)
    if (inherits(man, "error")) return(close_done(conditionMessage(man), "error"))
    close_bump()
    close_done(fpa_screen("close_ok_freeze", fpa_shiny_when(man$frozen_at)))
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$close_drift_btn, {
    st <- close_st()
    d <- fpa_close_drift_months(st, close_drift())
    if (!nrow(d)) return()
    shiny::showModal(shiny::modalDialog(
      title = fpa_screen("close_btn_drift"),
      easyClose = TRUE,
      shiny::tags$p(fpa_screen("close_drift_warn", nrow(d), fpa_close_between(d$periode), fpa_var_eur_s(sum(d$oi_gap)))),
      footer = shiny::tagList(
        shiny::modalButton(fpa_screen("journal_cancel")),
        shiny::actionButton("close_drift_ok", fpa_screen("close_btn_drift_ok"), class = "fpa-path-btn")
      )
    ))
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$close_drift_ok, {
    shiny::removeModal()
    p <- pack()
    st <- close_st()
    if (!isTRUE(p$ok) || is.null(st)) return()
    d <- fpa_close_drift_in(st, close_drift())
    n <- tryCatch(fpa_close_accept_drift(p$paths, d), error = function(e) e)
    if (inherits(n, "error")) return(close_done(conditionMessage(n), "error"))
    path <- cfg_path()
    shiny::showNotification(fpa_screen("close_rerun"), id = "fpa-close-run", duration = NULL, type = "message")
    res <- tryCatch(fpa_run(path, write = TRUE, stop_on_error = FALSE), error = function(e) e)
    if (!inherits(res, "error")) {
      if (exists("fpa_sync_report_run", mode = "function")) {
        tryCatch(fpa_sync_report_run(dirname(path), path, res), error = function(e) NULL)
      }
      tryCatch(fpa_driver_pass(path, res = res, write = TRUE), error = function(e) NULL)
    }
    shiny::removeNotification("fpa-close-run")
    if (inherits(res, "error")) return(close_done(conditionMessage(res), "error"))
    pack(fpa_shiny_load(path))
    close_bump()
    close_done(fpa_screen("close_ok_drift", n, length(unique(d$periode))))
  }, ignoreInit = TRUE)

