    out <- fpa_close_cmp_csv(cmp)
    nm <- paste0("ecart-versions-", pr[["a"]], "-vers-", pr[["b"]], ".csv")
    dest <- file.path(p$paths$reports, nm)
    ok <- tryCatch({
      dir.create(p$paths$reports, recursive = TRUE, showWarnings = FALSE)
      utils::write.csv(out, dest, row.names = FALSE, fileEncoding = "UTF-8")
      TRUE
    }, error = function(e) e)
    if (inherits(ok, "error")) return(close_done(conditionMessage(ok), "error"))
    close_done(fpa_screen("close_ok_export", file.path(basename(p$paths$reports), nm)))
  }, ignoreInit = TRUE)

