  fpa_nav_restore_note <- shiny::reactiveVal("")
  shiny::observeEvent(input$fpa_go, {
    go <- input$fpa_go
    if (is.null(go) || !is.list(go)) return()
    tab <- as.character(go$tab %||% "")
    line <- as.character(go$line %||% "")
    periode <- as.character(go$periode %||% "")
    if (nzchar(periode)) fpa_go_periode(periode)
    if (nzchar(tab)) bslib::nav_select("main_nav", selected = tab, session = session)
    open <- as.character(go$open %||% "")
    sel <- switch(open, obj = "details.fpa-obj", out = "#fpa-out-fold", "")
    if (nzchar(sel)) session$sendCustomMessage("fpa-open-details", list(sel = sel))
    if (nzchar(periode) && grepl("^[0-9]{4}-[0-9]{2}$", periode)) {
      if (identical(tab, "Écarts") || identical(tab, "Ecarts")) {
        if (nzchar(line)) var_line(line)
        var_month(periode)
      }
      if (identical(tab, "Compte de résultat")) {
        shiny::updateSelectInput(session, "pnl_start", selected = periode)
        fy <- character()
        tryCatch({
          p <- pack()
          pers <- as.character(p$finance$pnl$periode %||% character())
          ye <- fpa_year_end_info(p$config %||% list(), p$finance$period_status, pers)
          fy <- as.character(ye$months %||% character())
        }, error = function(e) NULL)
        if (length(fy) && !periode %in% fy) {
          fpa_nav_restore_note(fpa_screen("nav_period_restored"))
        } else {
          fpa_nav_restore_note("")
        }
      }
      if (identical(tab, "Trésorerie")) {
        shiny::updateRadioButtons(session, "synth_cash_window", selected = "fy")
      }
      if (identical(tab, "Bilan")) {
        shiny::updateSelectInput(session, "bs_cmp_b", selected = periode)
      }
    }
    lv <- scenario_levers()
    if (identical(tab, "Impact") && nzchar(line) && line %in% lv$lines) {
      shiny::updateSliderInput(session, paste0("line_", line), value = input[[paste0("line_", line)]] %||% 0)
    }
  }, ignoreInit = TRUE)
