  fpa_shiny_nav_marks <- function() {
    p <- pack()
    map_done <- FALSE
    drv_done <- FALSE
    if (isTRUE(p$ok)) {
      prog <- fpa_shiny_progress_read(p$config_path %||% "")
      map_done <- isTRUE(prog$map_read) && !nrow(fpa_chain_absent_sources(p$config))
      if (isTRUE(p$drivers_ok) && nrow(p$grades)) {
        saved <- fpa_shiny_saved_ids(confirmations())
        ids <- as.character(p$grades$series_id)
        drv_done <- length(ids) > 0L && all(ids %in% saved)
      }
    }
    session$sendCustomMessage("fpa-nav-mark", list(map = map_done, drivers = drv_done, structure = isTRUE(drv_done)))
  }

