  })

  shiny::observeEvent(input$drv_keep, {
    id <- as.character(input$drv_keep %||% "")
    p <- pack()
    if (!nzchar(id) || !isTRUE(p$drivers_ok)) return()
    hit <- p$grades[gsub("[^A-Za-z0-9_-]", "", as.character(p$grades$series_id)) == id, , drop = FALSE]
    if (!nrow(hit)) return()
    g <- hit[1, , drop = FALSE]
    dest <- file.path(dirname(p$config_path), "config", "driver-confirmations.json")
    dir.create(dirname(dest), recursive = TRUE, showWarnings = FALSE)
    existing <- list()
    if (file.exists(dest)) {
      existing <- tryCatch(jsonlite::fromJSON(dest, simplifyVector = FALSE), error = function(e) list())
    }
    if (!is.list(existing) || !is.null(existing$series_id)) existing <- list(existing)
    lag <- if (is.finite(fpa_shiny_num(g$causal_lag))) as.integer(g$causal_lag) else NULL
    in_formula <- fpa_shiny_in_formula(g)
    proved <- fpa_shiny_state_flag(g, "state_proved")
    inconclusive <- (proved && !fpa_shiny_state_flag(g, "state_stat")) ||
      (in_formula && !is.finite(fpa_shiny_num(g$bottom_r)))
    keep_v <- as.character(g$verdict)
    if (proved && identical(keep_v, "Reject")) keep_v <- "Optional"
    row <- list(
      series_id = as.character(g$series_id),
      target_line = as.character(g$target_line),
      verdict = keep_v,
      engine_verdict = as.character(g$verdict),
      note = if (inconclusive) fpa_screen("drv_read_note") else "",
      confirmed_at = format(Sys.time(), "%Y-%m-%dT%H:%M:%S")
    )
    if (!is.null(lag)) row$engine_lag <- lag
    if (!inconclusive && !is.null(lag)) row$lag <- lag
    existing <- Filter(function(item) !identical(as.character(item$series_id), row$series_id), existing)
    existing[[length(existing) + 1]] <- row
    jsonlite::write_json(existing, dest, auto_unbox = TRUE, pretty = TRUE)
    confirm_rev(confirm_rev() + 1L)
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$drv_pick, {
    id <- as.character(input$drv_pick %||% "")
    if (!nzchar(id)) return()
    focus_series(id)
    shiny::updateSelectInput(session, "series_id", selected = id)
    shiny::updateTabsetPanel(session, "driver_tabs", selected = "Fiche")
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$drv_next, {
    p <- pack()
    if (!isTRUE(p$drivers_ok) || !nrow(p$grades)) return()
    ids <- as.character(p$grades$series_id)
    saved <- fpa_shiny_saved_ids(confirmations())
    todo <- ids[!ids %in% saved]
    if (!length(todo)) return()
    cur <- as.character(input$series_id %||% "")
    pos <- match(cur, ids)
    nxt <- todo[[1]]
    if (!is.na(pos)) {
      after <- ids[seq(from = pos + 1L, to = length(ids))]
      hit <- after[after %in% todo]
      if (length(hit)) nxt <- hit[[1]]
    }
    focus_series(nxt)
    shiny::updateSelectInput(session, "series_id", selected = nxt)
    shiny::updateTabsetPanel(session, "driver_tabs", selected = "Fiche")
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$map_read, {
    p <- pack()
    if (!isTRUE(p$ok) || !nzchar(p$config_path %||% "")) return()
    dest <- fpa_shiny_progress_path(p$config_path)
    dir.create(dirname(dest), recursive = TRUE, showWarnings = FALSE)
    jsonlite::write_json(
      list(map_read = TRUE, map_read_at = format(Sys.time(), "%Y-%m-%d %H:%M")),
      dest, auto_unbox = TRUE, pretty = TRUE
    )
    map_rev(map_rev() + 1L)
  }, ignoreInit = TRUE)

