    if (is.null(g)) return(shiny::tags$p(p$message))
    name <- fpa_shiny_bottom_label(g$series_name)
    line <- tolower(fpa_shiny_line_name(g$target_line))
    fr_r <- function(x) fpa_shiny_fr_num(x, 2)
    fr_pct <- function(x) fpa_shiny_fr_num(fpa_shiny_num(x) * 100, 1)
    mech <- "relation" %in% names(g) && as.character(g$relation[[1]]) %in% c("part_whole", "derived")
    soutien <- fpa_shiny_axis_mark(g, "evidence")
    soutien_body <- if (!is.finite(fpa_shiny_num(g$evidence_r))) {
      fpa_screen("drv_line_flat")
    } else if (mech) {
      fpa_screen("drv_card_soutien_mech", line, fr_r(g$evidence_r))
    } else {
      paste(
        fpa_screen(
          "drv_card_soutien", soutien, line, fr_r(g$evidence_r), fr_r(g$evidence_r_crit),
          fr_pct(g$permutation_rank)
        ),
        if (identical(as.character(g$lag_status[[1]] %||% ""), "refused_reverse_causality")) fpa_screen("drv_card_soutien_reverse") else ""
      )
    }
    result <- fpa_shiny_axis_mark(g, "result")
    result_body <- if ("bottom_r" %in% names(g) && is.finite(fpa_shiny_num(g$bottom_r))) {
      fpa_screen("drv_card_result", result, fr_r(g$bottom_r), fr_pct(g$bottom_rank))
    } else if ("bottom_line" %in% names(g) && identical(as.character(g$bottom_line[[1]]), "OI")) {
      fpa_screen("drv_line_flat")
    } else {
      result
    }
    lab <- function(txt) shiny::tags$strong(paste0(txt, ". "))
    indep <- fpa_shiny_axis_mark(g, "independence")
    indep_body <- if (!identical(as.character(g$independence_status), "measured")) {
      if (fpa_shiny_is_volume(g$series_name)) {
        paste(indep, fpa_screen("drv_nights"), sep = ". ")
      } else {
        fpa_screen("drv_card_indep_na", indep)
      }
    } else {
      ctl <- if ("bottom_control" %in% names(g)) as.character(g$bottom_control[[1]] %||% "") else ""
      phrase <- if (nzchar(ctl)) fpa_shiny_control_de(ctl) else ""
      if (nzchar(phrase)) {
        fpa_screen("drv_card_indep", indep, phrase, fr_r(g$independence_r))
      } else {
        fpa_screen("drv_card_indep_plain", indep, fr_r(g$independence_r))
      }
    }
    saved <- NULL
    for (item in confirmations()) {
      if (identical(as.character(item$series_id %||% ""), as.character(g$series_id))) saved <- item
    }
    confirmed_body <- if (is.null(saved)) fpa_screen("drv_card_confirmed_open") else ""
    why <- switch(
      as.character(g$verdict),
      Keep = fpa_screen("drv_why_keep"),
      Optional = fpa_screen("drv_why_optional"),
      Reject = fpa_screen("drv_why_reject"),
      "Needs more history" = fpa_screen("drv_why_short"),
      ""
    )
    mark_class <- function(mark) {
      if (identical(as.character(mark), fpa_screen("drv_pass"))) "is-pass"
      else if (identical(as.character(mark), fpa_screen("drv_fail"))) "is-fail"
      else "is-na"
    }
    test_tile <- function(term, mark, body) {
      shiny::tags$div(
        class = paste("fpa-fiche-tile", mark_class(mark)),
        shiny::tags$div(class = "fpa-fiche-tile-head", fpa_drv_term(term), shiny::tags$span(class = "fpa-fiche-mark", mark)),
        shiny::tags$p(body)
      )
    }
    strip_lead <- function(txt, mark) {
      pre <- paste0(mark, ". ")
      if (identical(txt, mark)) return("")
      if (startsWith(txt, pre)) substr(txt, nchar(pre) + 1L, nchar(txt)) else txt
    }
    shiny::tags$div(
      class = "fpa-fiche",
      shiny::tags$p(
        class = "fpa-fiche-verdict",
        lab(fpa_screen("path_h_verdict")),
        if (nzchar(fpa_shiny_state_label(g))) paste0(fpa_shiny_state_label(g), ".") else paste0(fpa_shiny_verdict_fr(g$verdict), ". ", why)
      ),
      shiny::tags$h4(fpa_screen("drv_fiche_tests")),
      shiny::tags$div(
        class = "fpa-fiche-tiles",
        test_tile("soutien", soutien, strip_lead(soutien_body, soutien)),
        test_tile("indep", indep, strip_lead(indep_body, indep)),
        test_tile("resultat", result, strip_lead(result_body, result))
      ),
      shiny::tags$p(class = "fpa-fiche-status", lab(fpa_screen("drv_fiche_status")), if (nzchar(confirmed_body)) confirmed_body else fpa_screen("drv_saved", fpa_shiny_when(saved$confirmed_at), fpa_shiny_verdict_fr(saved$verdict %||% ""))),
      shiny::tags$details(
        class = "fpa-drv-fold-lite",
        shiny::tags$summary(fpa_screen("drv_fiche_detail")),
        shiny::tags$p(style = "margin-top:0.4rem;", lab(fpa_screen("drv_line_title")), fpa_shiny_line_sentence(g)),
        shiny::tags$p(lab(fpa_screen("drv_bottom_title")), fpa_shiny_bottom_sentence(g))
      )
    )
  })

  output$confirm_ui <- shiny::renderUI({
    g <- grade_row()
    if (is.null(g)) return(NULL)
    prof <- fpa_shiny_profile(pack(), g$series_id)
    offers <- fpa_shiny_shift_offers(g, prof)
    verdicts <- c("Keep", "Optional", "Needs more history", "Reject")
    engine_pick <- as.character(g$verdict)
    if (fpa_shiny_state_flag(g, "state_proved") && identical(engine_pick, "Reject")) engine_pick <- "Optional"
    picked <- engine_pick
    for (item in confirmations()) {
      if (identical(as.character(item$series_id %||% ""), as.character(g$series_id)) &&
          as.character(item$verdict %||% "") %in% verdicts) {
        picked <- as.character(item$verdict)
      }
    }
    v_lab <- vapply(verdicts, function(v) {
      lab <- fpa_shiny_verdict_fr(v)
      if (identical(v, engine_pick)) paste0(lab, " · ", fpa_screen("drv_engine_pick")) else lab
    }, character(1))
    shiny::tagList(
      shiny::tags$h2(class = "fpa-series-now", fpa_shiny_bottom_label(g$series_name)),
      shiny::tags$p(
        shiny::tags$strong(paste0(fpa_screen("drv_rec_head"), " ")),
        fpa_shiny_recommend_sentence(g, prof, offers)
      ),
      shiny::radioButtons(
        "confirm_verdict", fpa_screen("drv_confirm_verdict"),
        choices = stats::setNames(verdicts, v_lab),
        selected = picked, width = "100%"
      ),
      shiny::radioButtons(
        "confirm_lag", fpa_screen("drv_confirm_lag"),
        choices = offers$choices,
        selected = offers$selected, width = "100%"
      ),
      {
        saved <- NULL
        for (item in confirmations()) {
          if (identical(as.character(item$series_id %||% ""), as.character(g$series_id))) saved <- item
        }
        if (!is.null(saved)) shiny::tags$p(
          style = "margin:0 0 8px;color:#1f4e5f;font-weight:700;",
          shiny::HTML('<svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true" style="vertical-align:-2px;margin-right:6px;"><path d="M3.2 8.2 6.4 11.4 12.8 4.6" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>'),
          fpa_screen("drv_saved", fpa_shiny_when(saved$confirmed_at), fpa_shiny_verdict_fr(saved$verdict %||% ""))
        )
      },
      shiny::textInput("confirm_note", fpa_screen("drv_note")),
      shiny::tags$div(
        style = "display:flex;flex-wrap:wrap;gap:8px;align-items:center;",
        shiny::actionButton(
          "confirm", fpa_screen("drv_confirm_save"),
          style = "background:#1f4e5f;color:#fff;border:1px solid #1f4e5f;border-radius:8px;font-weight:600;"
        ),
        shiny::actionButton(
          "drv_next", fpa_screen("path_next"),
          style = "background:#fff;color:#1f4e5f;border:1px solid #1f4e5f;border-radius:8px;font-weight:600;"
        )
      )
    )
  })

  shiny::observeEvent(input$confirm_lag, {
    h <- suppressWarnings(as.integer(input$confirm_lag))
    if (!is.na(h)) shiny::updateSliderInput(session, "lag_slider", value = h)
  }, ignoreInit = TRUE)

  shiny::observeEvent(input$confirm, {
    p <- pack()
    g <- grade_row()
    if (!isTRUE(p$ok) || is.null(g)) return()
    dest <- file.path(dirname(p$config_path), "config", "driver-confirmations.json")
    dir.create(dirname(dest), recursive = TRUE, showWarnings = FALSE)
    existing <- list()
    if (file.exists(dest)) {
      existing <- tryCatch(jsonlite::fromJSON(dest, simplifyVector = FALSE), error = function(e) list())
    }
    if (!is.list(existing) || !is.null(existing$series_id)) existing <- list(existing)
    chosen_lag <- suppressWarnings(as.integer(input$confirm_lag))
    row <- list(
      series_id = g$series_id,
      target_line = g$target_line,
      lag = if (!is.na(chosen_lag)) chosen_lag else NULL,
      engine_lag = if (is.finite(g$causal_lag)) as.integer(g$causal_lag) else NULL,
      verdict = input$confirm_verdict,
      engine_verdict = as.character(g$verdict),
      note = input$confirm_note,
      confirmed_at = format(Sys.time(), "%Y-%m-%dT%H:%M:%S")
    )
    existing <- Filter(function(item) !identical(item$series_id, g$series_id), existing)
    existing[[length(existing) + 1]] <- row
    jsonlite::write_json(existing, dest, auto_unbox = TRUE, pretty = TRUE)
    confirm_rev(confirm_rev() + 1L)
    shiny::updateRadioButtons(session, "confirm_verdict", selected = as.character(row$verdict))
    shiny::showNotification(paste("Confirmation ecrite :", dest), type = "message")
  })
}

# Rscript is not an interactive session, so Shiny would only print the address.
options(shiny.launch.browser = TRUE)
shiny::shinyApp(ui, server)
